/* Overload category for symbol conflict detection.
 *
 * Derived from FengDeclKind + sub-form (is_tuple / spec form). Finer than
 * FengDeclKind: plain type vs tuple and the three spec forms are separate
 * overload faces — same name across sub-forms is a conflict.
 *
 * See docs/engineering/feng-type-arity-overload-dev.md §0.3 for the full design. */
typedef enum {
    FENG_OVERLOAD_CATEGORY_FUNCTION = 0,
    FENG_OVERLOAD_CATEGORY_TYPE,              /* plain type + @value type */
    FENG_OVERLOAD_CATEGORY_TUPLE,             /* tuple type */
    FENG_OVERLOAD_CATEGORY_SPEC_OBJECT,
    FENG_OVERLOAD_CATEGORY_SPEC_CALLABLE,
    FENG_OVERLOAD_CATEGORY_SPEC_UNION,
    FENG_OVERLOAD_CATEGORY_SPEC_INTERSECTION,
    FENG_OVERLOAD_CATEGORY_NO_OVERLOADING     /* enum / global_binding (no generic params) */
} FengOverloadCategory;

/* Extract type_param_count from a decl. Returns 0 for non-generic decls. */
static size_t decl_type_param_count(const FengDecl *decl) {
    if (decl->kind == FENG_DECL_TYPE) {
        return decl->as.type_decl.type_param_count;
    }
    if (decl->kind == FENG_DECL_SPEC) {
        return decl->as.spec_decl.type_param_count;
    }
    return 0U;
}

/* Derive overload category from a decl. is_value does not participate in
 * category derivation — plain type and @value type share TYPE (semantically
 * isomorphic). enum / global_binding / fit etc. all map to NO_OVERLOADING. */
static FengOverloadCategory decl_overload_category(const FengDecl *decl) {
    switch (decl->kind) {
        case FENG_DECL_FUNCTION:
            return FENG_OVERLOAD_CATEGORY_FUNCTION;
        case FENG_DECL_TYPE:
            return decl->as.type_decl.is_tuple
                ? FENG_OVERLOAD_CATEGORY_TUPLE
                : FENG_OVERLOAD_CATEGORY_TYPE;
        case FENG_DECL_SPEC:
            switch (decl->as.spec_decl.form) {
                case FENG_SPEC_FORM_OBJECT:   return FENG_OVERLOAD_CATEGORY_SPEC_OBJECT;
                case FENG_SPEC_FORM_CALLABLE: return FENG_OVERLOAD_CATEGORY_SPEC_CALLABLE;
                case FENG_SPEC_FORM_UNION:    return FENG_OVERLOAD_CATEGORY_SPEC_UNION;
                case FENG_SPEC_FORM_INTERSECTION: return FENG_OVERLOAD_CATEGORY_SPEC_INTERSECTION;
            }
            return FENG_OVERLOAD_CATEGORY_NO_OVERLOADING;
        default:
            return FENG_OVERLOAD_CATEGORY_NO_OVERLOADING;
    }
}

typedef struct AliasEntry {
    FengSlice alias;
    const FengSemanticModule *target_module;
    const FengUseDecl *use_decl;
} AliasEntry;

/* Per-program record of every module referenced by a `use` declaration in
 * the current file (whether short-name or aliased). Cross-module visibility
 * checks against external modules require an entry here in addition to the
 * target being declared `open mod`. */
typedef struct ImportedModuleEntry {
    const FengSemanticModule *target_module;
} ImportedModuleEntry;

/* InferredExprType represents the type of an expression during semantic
 * analysis. It exists as a separate structure from FengTypeRef for historical
 * implementation reasons: it carries direct pointers to FengDecl/FengExpr
 * (avoiding name resolution) and uses string slices for builtin types
 * (avoiding FengTypeRef synthesis).
 *
 * Future refactoring direction: unify with FengTypeRef. A type is a type,
 * regardless of how it was determined (annotated, declared, or inferred).
 * "Inferred" should describe the provenance, not be a separate type structure.
 * When unified, infer_expr_type will return const FengTypeRef *, expr->type
 * will be the single source of truth, and the BUILTIN/DECL/LAMBDA kinds will
 * be representable as FENG_TYPE_REF_NAMED (with an intern table for builtins
 * and function type declarations for lambdas). */
typedef enum InferredExprTypeKind {
    FENG_INFERRED_EXPR_TYPE_UNKNOWN = 0,
    FENG_INFERRED_EXPR_TYPE_BUILTIN,
    FENG_INFERRED_EXPR_TYPE_TYPE_REF,
    FENG_INFERRED_EXPR_TYPE_DECL,
    FENG_INFERRED_EXPR_TYPE_LAMBDA
} InferredExprTypeKind;

typedef struct InferredExprType {
    InferredExprTypeKind kind;
    FengSlice builtin_name;
    const FengTypeRef *type_ref;
    const FengDecl *type_decl;
    const FengExpr *lambda_expr;
} InferredExprType;

typedef struct UnionNarrowingSet UnionNarrowingSet;

typedef struct LocalNameEntry {
    FengSlice name;
    InferredExprType type;
    FengMutability mutability;
    const FengExpr *source_expr;
    const UnionNarrowingSet *union_narrowing;
} LocalNameEntry;

/* Expression-level union narrowing entry. Used to narrow non-identifier match
 * targets (e.g. self.member) within match branch bodies. */
typedef struct ExprNarrowingEntry {
    const FengExpr *target_expr;
    InferredExprType narrowed_type;
} ExprNarrowingEntry;

/* Compile-time constant evaluation result. Used by evaluate_constant_expr to model the
 * limited set of values producible by Feng's constant-folder. INT carries one complete
 * 64-bit pattern plus its resolved signedness; FLOAT carries IEEE 754 double; BOOL
 * carries a flag. */
typedef enum FengConstKind {
    FENG_CONST_NONE = 0,
    FENG_CONST_INT,
    FENG_CONST_FLOAT,
    FENG_CONST_BOOL
} FengConstKind;

typedef struct FengConstValue {
    FengConstKind kind;
    int64_t i;
    bool integer_is_unsigned;
    double f;
    bool b;
} FengConstValue;

/* Linked-list guard threaded through evaluate_constant_expr_inner to detect identifier
 * cycles such as `let a = b; let b = a;` without resorting to global state. */
typedef struct ConstEvalGuard {
    const FengExpr *expr;
    struct ConstEvalGuard *prev;
} ConstEvalGuard;

typedef struct ScopeFrame {
    LocalNameEntry *locals;
    size_t local_count;
    size_t local_capacity;
} ScopeFrame;

