/* Stable semantic identity used by one normalized @friend type. Named types
 * retain declaration identity, while owner parameters remain symbolic until
 * the annotated member is viewed through a concrete owner instance. */
typedef enum FriendTypeIdentityKind {
    FRIEND_TYPE_IDENTITY_NAMED = 0,
    FRIEND_TYPE_IDENTITY_BUILTIN,
    FRIEND_TYPE_IDENTITY_OWNER_PARAM,
    FRIEND_TYPE_IDENTITY_ACTIVE_PARAM,
    FRIEND_TYPE_IDENTITY_POINTER,
    FRIEND_TYPE_IDENTITY_ARRAY
} FriendTypeIdentityKind;

/* Recursive semantic type identity for @friend normalization and matching. */
typedef struct FriendTypeIdentity {
    FriendTypeIdentityKind kind;
    bool array_element_writable;
    const FengTypeRef *source_ref;
    union {
        struct {
            const FengDecl *decl;
            struct FriendTypeIdentity **type_args;
            size_t type_arg_count;
        } named;
        const char *builtin_name;
        size_t owner_param_index;
        const FengTypeParam *active_param;
        struct FriendTypeIdentity *inner;
    } as;
} FriendTypeIdentity;

/* One same-package fit method that consumed a friend type's authorization. */
typedef struct FriendFitAccess {
    const FengSemanticModule *module;
    const FengProgram *program;
    const FengTypeMember *callable_member;
} FriendFitAccess;

/* One member's single normalized friend set. The member/owner/module/program
 * pointers borrow analysis/source objects; each friend identity tree is owned
 * by this record and released with FengSemanticAnalysis. */
struct FengFriendMemberInfo {
    const FengTypeMember *member;
    const FengDecl *owner_decl;
    const FengSemanticModule *owner_module;
    const FengProgram *owner_program;
    size_t owner_type_param_count;
    FriendTypeIdentity **friend_types;
    size_t friend_type_count;
    size_t friend_type_capacity;
    bool signature_checked;
    const FengDecl *owner_private_signature_decl;
    const FengTypeRef *owner_private_signature_ref;
    FriendFitAccess *fit_accesses;
    size_t fit_access_count;
    size_t fit_access_capacity;
};

/* G4: One entry per active type parameter in the current declaration scope. */
typedef struct TypeParamEntry {
    FengSlice name;
    const FengTypeParam *type_param;
} TypeParamEntry;

struct UnionNarrowingSet {
    const FengDecl *union_decl;
    bool *active_members;
    size_t member_count;
};

/* Nearest value-expression result branch. It blocks loop control targeting a
 * loop outside the branch. Inner loops remain valid break/continue targets,
 * while nested lambdas reset the boundary because they establish an
 * independent callable. */
typedef enum ExpressionBranchBoundary {
    EXPRESSION_BRANCH_BOUNDARY_NONE = 0,
    EXPRESSION_BRANCH_BOUNDARY_IF,
    EXPRESSION_BRANCH_BOUNDARY_MATCH,
    EXPRESSION_BRANCH_BOUNDARY_CATCH
} ExpressionBranchBoundary;

typedef struct ResolveContext {
    const FengSemanticAnalysis *analysis;
    const FengSemanticModule *module;
    const FengProgram *program;
    const VisibleTypeEntry *visible_types;
    size_t visible_type_count;
    const VisibleValueEntry *visible_values;
    size_t visible_value_count;
    const FunctionOverloadSetEntry *function_sets;
    size_t function_set_count;
    const AliasEntry *aliases;
    size_t alias_count;
    /* Modules the current file imported via `use` (short-name or aliased).
     * Used to enforce that cross-module symbol/contract visibility requires
     * an explicit `use`, not just the target being `open mod`. */
    const ImportedModuleEntry *imported_modules;
    size_t imported_module_count;
    ScopeFrame *scopes;
    size_t scope_count;
    size_t scope_capacity;
    const FengDecl *current_type_decl;
    /* Lexical concrete type whose executable implementation is currently
     * being resolved. This covers field initializers, ordinary methods,
     * constructors, and finalizers. Friend access uses this explicit owner
     * instead of inferring authority from one FengTypeMemberKind. */
    const FengDecl *current_type_implementation_owner;
    /* When non-NULL, the resolver is currently inside the body of a fit-block
     * function. `current_type_decl` is set to the fit's resolved target type so
     * that `self`/instance lookups still work, and `current_fit_decl` is used
     * to enforce that fit-body code cannot reach the target type's private
     * members regardless of whether the target lives in the same package. */
    const FengDecl *current_fit_decl;
    const FengTypeRef *current_fit_target_type_ref;
    /* Lexical member implementation context. Nested lambdas intentionally
     * preserve this identity for friend/spec-seal/mixable authorization. */
    const FengTypeMember *current_callable_member;
    /* Member whose own callable body is currently being resolved. Nested
     * lambdas clear this field so their return and constructor-binding rules
     * cannot inherit restrictions from the lexical member. */
    const FengTypeMember *current_callable_body_member;
    const FengCallableSignature *current_callable_signature;
    InferredExprType current_callable_inferred_return_type;
    bool current_callable_saw_return;
    FengSlice *current_constructor_bound_names;
    size_t current_constructor_bound_count;
    size_t current_constructor_bound_capacity;
    FengTypeRef **synthetic_type_refs;
    size_t synthetic_type_ref_count;
    size_t synthetic_type_ref_capacity;
    UnionNarrowingSet **union_narrowings;
    size_t union_narrowing_count;
    size_t union_narrowing_capacity;
    CallableReturnCache *callable_return_cache;
    CallableExceptionEscapeCache *callable_exception_escape_cache;
    FengSemanticError **errors;
    size_t *error_count;
    size_t *error_capacity;
    bool current_callable_has_escaping_exception;
    size_t exception_capture_depth;
    size_t unknown_type_depth;
    /* Exact identifier expression permitted as the operand of an original
     * `throw error` rethrow. An `unknown` catch binding nested anywhere inside
     * a larger expression remains an ordinary, and therefore invalid, use. */
    const FengExpr *allowed_unknown_rethrow_expr;
    /* Number of nested `while`/`for` loop bodies currently being resolved
     * inside the active callable scope. Used to enforce that `break` and
     * `continue` can only appear inside a loop body. Reset to 0 across
     * callable / lambda boundaries so that a lambda nested in a loop cannot
     * jump out of the surrounding loop. */
    size_t loop_depth;
    /* Nearest if/match/try result branch. It prevents break/continue from
     * targeting a loop outside the value expression. Reset across callable
     * boundaries; loops declared inside the branch use loop_depth normally. */
    ExpressionBranchBoundary expression_branch_boundary;
    /* When non-NULL, the resolver is currently resolving an expression that
     * has an explicit target type (binding annotation, function argument,
     * return value, member assignment). Used by the shared if/match/try
     * result fitter so every value-producing branch sees the same target. */
    const FengTypeRef *current_expr_expected_type_ref;
    /* Number of call-argument resolution frames whose parameter target is not
     * known until overload selection completes. Target-sensitive expressions
     * resolve their contents immediately but defer diagnostics that would
     * otherwise assume an untyped context; overload probing then checks every
     * candidate through the side-effect-free expected-type matcher. */
    size_t deferred_call_argument_target_depth;
    /* When true, expr_matches_expected_type_ref must NOT set expr->type as a
     * side effect.  Set during overload-resolution candidate probing so that
     * rejected or non-winning candidates cannot corrupt the literal node's
     * type field — the correct type is committed after resolution picks the
     * unique winner (see commit_literal_arg_adaptations_for_resolved_call). */
    bool suppress_literal_type_commit;
    /* Number of nested `defer { ... }` blocks currently being resolved.
     * Used to enforce the §4 semantic restrictions on control flow inside
     * defer bodies: `return`/`throw`/nested `defer` are forbidden at any
     * depth (strong), and `break`/`continue` are forbidden only when the
     * defer block is their direct lexical location (i.e. when loop_depth is
     * still 0 inside the defer body — a nested `for`/`while` resets loop_depth
     * at entry, so break/continue inside that nested loop remains legal).
     * Reset to 0 across callable / lambda boundaries because a defer block
     * never escapes its enclosing function scope. */
    size_t defer_depth;
    /* When true, a lambda body resolved in this context may capture `self`
     * from the enclosing type. Set inside type method/constructor bodies and
     * inside callable-spec field initializers. */
    bool self_capturable;
    /* Stack of lambda capture frames, pushed by resolve_lambda_expr while a
     * lambda body is being resolved. Used to record captured outer locals and
     * self references onto FengExpr.lambda.captures. */
    struct LambdaCaptureFrame *lambda_frames;
    size_t lambda_frame_count;
    size_t lambda_frame_capacity;
    /* G4: Active generic type parameter scope.  Pushed when entering a generic
     * declaration (type, spec, fn) and popped on exit.  An inner push
     * concatenates with the outer scope so that both type-level and
     * method-level type params are simultaneously visible. */
    const TypeParamEntry *type_params;
    size_t type_param_count;
    ExprNarrowingEntry *expr_narrowings;
    size_t expr_narrowing_count;
    size_t expr_narrowing_capacity;
    /* Host pointer size in bytes (sizeof(void *)).  Used by
     * canonical_builtin_type_name() to resolve platform-dependent aliases
     * (e.g. `int` → `i32` on 32-bit, `i64` on 64-bit).  Propagated from
     * FengSemanticAnalyzeOptions.pointer_size through the analysis entry. */
    size_t pointer_size;
} ResolveContext;

/* Saved resolver state while entering one value-expression result branch. */
typedef struct ExpressionBranchBoundaryState {
    size_t loop_depth;
    ExpressionBranchBoundary boundary;
} ExpressionBranchBoundaryState;

/* Enter a result branch without inheriting loop targets from outside the
 * value expression. A loop declared inside the branch increments loop_depth
 * from zero and remains a legal target. */
static void enter_expression_branch_boundary(
    ResolveContext *context,
    ExpressionBranchBoundary boundary,
    ExpressionBranchBoundaryState *saved) {
    saved->loop_depth = context->loop_depth;
    saved->boundary = context->expression_branch_boundary;
    context->loop_depth = 0U;
    context->expression_branch_boundary = boundary;
}

/* Restore the resolver state that surrounded a value-expression branch. */
static void leave_expression_branch_boundary(
    ResolveContext *context,
    const ExpressionBranchBoundaryState *saved) {
    context->loop_depth = saved->loop_depth;
    context->expression_branch_boundary = saved->boundary;
}

static bool resolver_append_error(ResolveContext *context, FengToken token, const char *code, char *message);

typedef struct ResolvedTypeTarget {
    const FengDecl *type_decl;
    const FengSemanticModule *provider_module;
    const FengTypeRef *type_ref;
    bool is_builtin_type_name;
    FengSlice builtin_name;
    /* When the identifier resolves to a generic function type parameter
     * (e.g., `T` in `func f<T: Factory<T>>() { T.make(); }`), the
     * following fields record which type parameter is being referenced
     * and the constraint spec used to find its static members. */
    bool is_generic_type_param;
    const FengDecl *constraint_spec_decl;
    /* Complete declared constraint instance (for example Surface<int> or
     * Surface<U>). Member signatures must be closed through this type ref;
     * generic parameter names are not spec-owner type arguments. */
    const FengTypeRef *constraint_spec_type_ref;
} ResolvedTypeTarget;

typedef struct AbiTrace {
    const FengDecl *decl;
    const struct AbiTrace *parent;
} AbiTrace;

static FengSlice slice_from_cstr(const char *text) {
    FengSlice slice;

    slice.data = text;
    slice.length = strlen(text);
    return slice;
}

static bool slice_equals(FengSlice left, FengSlice right) {
    return left.length == right.length && memcmp(left.data, right.data, left.length) == 0;
}


static bool slice_equals_cstr(FengSlice slice, const char *text) {
    size_t length = strlen(text);

    return slice.length == length && memcmp(slice.data, text, length) == 0;
}

static bool path_equals(const FengSlice *left,
                        size_t left_count,
                        const FengSlice *right,
                        size_t right_count) {
    size_t index;

    if (left_count != right_count) {
        return false;
    }

    for (index = 0U; index < left_count; ++index) {
        if (!slice_equals(left[index], right[index])) {
            return false;
        }
    }

    return true;
}

