static const FengTypeRef *substitute_type_ref_for_fit_instance(
    ResolveContext *context,
    const FengDecl *fit_decl,
    InferredExprType owner_type,
    const FengTypeRef *member_type_ref) {
    FengTypeParam fit_local_type_param;
    FengTypeRef *type_args[1];
    FengTypeRef *substituted;

    if (context == NULL || fit_decl == NULL || fit_decl->kind != FENG_DECL_FIT ||
        member_type_ref == NULL || owner_type.kind != FENG_INFERRED_EXPR_TYPE_TYPE_REF ||
        owner_type.type_ref == NULL || owner_type.type_ref->kind != FENG_TYPE_REF_ARRAY ||
        owner_type.type_ref->as.inner == NULL ||
        !fit_target_collect_array_local_type_param(context,
                                                   fit_decl->as.fit_decl.target,
                                                   &fit_local_type_param)) {
        return member_type_ref;
    }
    if (fit_decl->as.fit_decl.target == NULL ||
        fit_decl->as.fit_decl.target->kind != FENG_TYPE_REF_ARRAY ||
        fit_decl->as.fit_decl.target->array_element_writable !=
            owner_type.type_ref->array_element_writable) {
        return member_type_ref;
    }

    type_args[0] = (FengTypeRef *)owner_type.type_ref->as.inner;
    substituted = clone_type_ref_substituting_type_params(context->program, member_type_ref,
                                                          &fit_local_type_param,
                                                          1U,
                                                          type_args);
    if (substituted == NULL) {
        return member_type_ref;
    }
    if (!resolver_track_synthetic_type_ref(context, substituted)) {
        free_synthetic_type_ref(substituted);
        return member_type_ref;
    }
    return substituted;
}

/* Instantiate one callable-local constraint in the same order used for its
 * parameter and return surfaces: owner, fit target, then callable arguments.
 * The returned reference is borrowed unless `out_owned` is non-NULL; callers
 * either free that owned result after a probe or transfer it to a semantic
 * lifetime tracker before recording a witness. */
static const FengTypeRef *instantiate_callable_constraint_for_owner_instance(
    ResolveContext *context,
    const FengCallableSignature *callable,
    size_t type_param_index,
    FengTypeRef *const *type_args,
    const FengDecl *owner_type_decl,
    const FengDecl *fit_decl,
    InferredExprType owner_type,
    FengTypeRef **out_owned) {
    const FengTypeRef *constraint;
    FengTypeRef *substituted;

    if (out_owned != NULL) {
        *out_owned = NULL;
    }
    if (context == NULL || callable == NULL ||
        type_param_index >= callable->type_param_count) {
        return NULL;
    }
    constraint = callable->type_params[type_param_index].constraint;
    if (constraint == NULL) {
        return NULL;
    }
    constraint = substitute_type_ref_for_owner_instance(context,
                                                        owner_type_decl,
                                                        owner_type,
                                                        constraint);
    constraint = substitute_type_ref_for_fit_instance(context,
                                                      fit_decl,
                                                      owner_type,
                                                      constraint);
    if (type_args == NULL || callable->type_param_count == 0U) {
        return constraint;
    }
    substituted = clone_type_ref_substituting_type_params(
        context->program,
        constraint,
        callable->type_params,
        callable->type_param_count,
        type_args);
    if (substituted == NULL) {
        return constraint;
    }
    if (out_owned != NULL) {
        *out_owned = substituted;
        return substituted;
    }
    free_synthetic_type_ref(substituted);
    return constraint;
}

/* Return the callable signature identified by one resolved call record. */
static const FengCallableSignature *resolved_callable_signature(
    const FengResolvedCallable *resolved) {
    if (resolved == NULL) {
        return NULL;
    }
    if (resolved->kind == FENG_RESOLVED_CALLABLE_FUNCTION &&
        resolved->function_decl != NULL &&
        resolved->function_decl->kind == FENG_DECL_FUNCTION) {
        return &resolved->function_decl->as.function_decl;
    }
    if ((resolved->kind == FENG_RESOLVED_CALLABLE_TYPE_METHOD ||
         resolved->kind == FENG_RESOLVED_CALLABLE_FIT_METHOD ||
         resolved->kind == FENG_RESOLVED_CALLABLE_TYPE_STATIC_METHOD ||
         resolved->kind == FENG_RESOLVED_CALLABLE_FIT_STATIC_METHOD ||
         resolved->kind == FENG_RESOLVED_CALLABLE_SPEC_METHOD ||
         resolved->kind == FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD) &&
        resolved->member != NULL) {
        return &resolved->member->as.callable;
    }
    return NULL;
}

static const FengTypeRef *substitute_callable_return_type_for_call(
    ResolveContext *context,
    const FengDecl *owner_type_decl,
    const FengDecl *fit_decl,
    InferredExprType owner_type,
    const FengExpr *call_expr,
    const FengCallableSignature *callable,
    bool allow_wrapped_inference) {
    const FengTypeRef *return_type_ref;
    FengTypeRef **type_args = NULL;
    bool *owned_type_args = NULL;
    FengTypeRef *substituted = NULL;

    if (callable == NULL || callable->return_type == NULL) {
        return NULL;
    }

    return_type_ref = substitute_type_ref_for_owner_instance(context,
                                                            owner_type_decl,
                                                            owner_type,
                                                            callable->return_type);
    return_type_ref = substitute_type_ref_for_fit_instance(context,
                                                          fit_decl,
                                                          owner_type,
                                                          return_type_ref);
    if (callable->type_param_count == 0U || call_expr == NULL ||
        call_expr->kind != FENG_EXPR_CALL) {
        return return_type_ref;
    }

    /* A resolved call already owns the authoritative caller-view generic
     * arguments. Reuse them during later type checks instead of attempting to
     * infer again after the surrounding target context has been restored. */
    if (resolved_callable_signature(&call_expr->as.call.resolved_callable) == callable &&
        call_expr->as.call.resolved_callable.callable_type_arg_count ==
            callable->type_param_count) {
        substituted = clone_type_ref_substituting_type_params(
            context->program,
            return_type_ref,
            callable->type_params,
            callable->type_param_count,
            (FengTypeRef *const *)
                call_expr->as.call.resolved_callable.callable_type_args);
        if (substituted != NULL &&
            resolver_track_synthetic_type_ref(context, substituted)) {
            return substituted;
        }
        free_synthetic_type_ref(substituted);
        substituted = NULL;
    }

    type_args = calloc(callable->type_param_count, sizeof *type_args);
    owned_type_args = calloc(callable->type_param_count, sizeof *owned_type_args);
    if (type_args == NULL || owned_type_args == NULL) {
        free(type_args);
        free(owned_type_args);
        return return_type_ref;
    }

    /* Only generic extern call sites pass `allow_wrapped_inference = true`.
     * Other call kinds keep return-type substitution aligned with the narrower
     * direct-`T` inference behavior they already had. */
    if (!callable_collect_call_type_args(context,
                                         call_expr,
                                         callable,
                                         return_type_ref,
                                         allow_wrapped_inference,
                                         false,
                                         type_args,
                                         owned_type_args)) {
        goto cleanup;
    }

    for (size_t type_param_index = 0U;
         type_param_index < callable->type_param_count;
         ++type_param_index) {
        if (type_args[type_param_index] == NULL) {
            goto cleanup;
        }
    }

    substituted = clone_type_ref_substituting_type_params(context->program, return_type_ref,
                                                          callable->type_params,
                                                          callable->type_param_count,
                                                          type_args);
    if (substituted != NULL && resolver_track_synthetic_type_ref(context, substituted)) {
        return_type_ref = substituted;
        substituted = NULL;
    }

cleanup:
    if (substituted != NULL) {
        free_synthetic_type_ref(substituted);
    }
    for (size_t type_param_index = 0U;
         type_param_index < callable->type_param_count;
         ++type_param_index) {
        if (owned_type_args[type_param_index]) {
            free_synthetic_type_ref(type_args[type_param_index]);
        }
    }
    free(type_args);
    free(owned_type_args);
    return return_type_ref;
}

/* Validate an alias at its actual use, before type/member/signature lookup can
 * select a candidate. A declaration and an alias are distinct sources even
 * when both ultimately belong to the same module. */
static bool validate_alias_name_reference(ResolveContext *context,
                                         FengToken token,
                                         FengSlice name) {
    const AliasEntry *alias = find_alias(context->aliases, context->alias_count, name);
    SymbolCandidate inline_candidates[SYMBOL_CANDIDATE_INLINE_CAPACITY];
    SymbolCandidate *candidates = inline_candidates;
    size_t count;
    char *alias_module;
    char *message;

    if (alias == NULL) {
        return true;
    }
    count = collect_symbol_candidates(context, name, inline_candidates,
                                      SYMBOL_CANDIDATE_INLINE_CAPACITY);
    if (count == 0U) {
        return true;
    }
    if (count > SYMBOL_CANDIDATE_INLINE_CAPACITY) {
        candidates = calloc(count, sizeof(*candidates));
        if (candidates == NULL) {
            return false;
        }
        collect_symbol_candidates(context, name, candidates, count);
    }
    /* Several semantic passes may visit a type annotation. Deduplicate within
     * its source file, never suppress an equal line/column in a sibling file. */
    for (size_t index = 0U; index < *context->error_count; ++index) {
        const FengSemanticError *error = &(*context->errors)[index];
        if (error->token.line == token.line && error->token.column == token.column &&
            strcmp(error->path, context->program->path) == 0 &&
            strcmp(error->code, "AE0005") == 0) {
            if (candidates != inline_candidates) free(candidates);
            return false;
        }
    }
    alias_module = format_module_name(alias->target_module->segments,
                                      alias->target_module->segment_count);
    message = format_message("'%.*s' is ambiguous: import alias for module '%s' in '%s' conflicts with",
                             (int)name.length, name.data,
                             alias_module != NULL ? alias_module : "<unknown>",
                             context->program->path);
    free(alias_module);
    for (size_t index = 0U; message != NULL && index < count; ++index) {
        const SymbolCandidate *candidate = &candidates[index];
        bool duplicate = false;
        char *module_name;
        char *next;

        for (size_t prior = 0U; prior < index; ++prior) {
            if (candidates[prior].provider_program == candidate->provider_program) {
                duplicate = true;
                break;
            }
        }
        if (duplicate) continue;
        module_name = format_module_name(candidate->provider_module->segments,
                                         candidate->provider_module->segment_count);
        next = format_message("%s declaration from module '%s' in '%s';",
                              message, module_name != NULL ? module_name : "<unknown>",
                              candidate->provider_program->path);
        free(module_name);
        free(message);
        message = next;
    }
    if (candidates != inline_candidates) free(candidates);
    if (message == NULL) {
        return false;
    }
    resolver_append_error(context, token, "AE0005", message);
    return false;
}

/* Lexical locals retain ordinary member access; all other alias collisions
 * are rejected by validate_alias_name_reference before resolving their use. */
static const AliasEntry *find_unshadowed_alias(const ResolveContext *context, FengSlice alias_name) {
    if (resolver_has_local_name(context, alias_name) ||
        find_visible_value(context->visible_values, context->visible_value_count, alias_name) != NULL ||
        find_visible_type_any_arity(context->visible_types, context->visible_type_count, alias_name) != NULL) {
        return NULL;
    }

    return find_alias(context->aliases, context->alias_count, alias_name);
}

/* A module member can be qualified either by a file-local import alias or by
 * the module's complete path.  Keeping both spellings behind one resolver
 * guarantees that all top-level declaration categories share the same module
 * identity and visibility rules. */
typedef struct ResolvedModuleMemberTarget {
    const FengSemanticModule *module;
    FengSlice member_name;
    const AliasEntry *alias;
} ResolvedModuleMemberTarget;

/* Resolve `alias.member` or `module.path.member` without performing a lookup
 * for the member declaration itself. */
static bool resolve_module_member_target(
    const ResolveContext *context,
    const FengExpr *expr,
    ResolvedModuleMemberTarget *out_target) {
    const FengExpr *object;
    size_t segment_count = 0U;
    FengSlice *segments = NULL;

    if (out_target != NULL) {
        memset(out_target, 0, sizeof(*out_target));
    }
    if (context == NULL || expr == NULL || out_target == NULL ||
        expr->kind != FENG_EXPR_MEMBER || expr->as.member.object == NULL) {
        return false;
    }

    object = expr->as.member.object;
    if (object->kind == FENG_EXPR_IDENTIFIER) {
        const AliasEntry *alias =
            find_unshadowed_alias(context, object->as.identifier);

        if (alias != NULL) {
            out_target->module = alias->target_module;
            out_target->member_name = expr->as.member.member;
            out_target->alias = alias;
            return true;
        }
    }

    segments = expr_path_segments_alloc(expr, &segment_count);
    if (segments != NULL && segment_count > 1U) {
        size_t module_index;

        /* A lexical local keeps ordinary member-access meaning even when the
         * same segments also form a complete module path. */
        if (resolver_has_local_name(context, segments[0])) {
            free(segments);
            return false;
        }
        module_index = find_module_index_by_path(
            context->analysis, segments, segment_count - 1U);

        if (module_index < context->analysis->module_count &&
            module_is_full_path_visible_from(
                context, &context->analysis->modules[module_index])) {
            out_target->module = &context->analysis->modules[module_index];
            out_target->member_name = segments[segment_count - 1U];
        }
    }
    free(segments);
    return out_target->module != NULL;
}

/* Format the source-visible qualified name for diagnostics while preserving
 * an import alias when that was the spelling used by the program. */
static char *format_module_member_target_name(
    const ResolvedModuleMemberTarget *target) {
    char *qualifier;
    char *result;

    if (target == NULL || target->module == NULL) {
        return NULL;
    }
    qualifier = target->alias != NULL
                    ? format_message("%.*s",
                                     (int)target->alias->alias.length,
                                     target->alias->alias.data)
                    : format_module_name(target->module->segments,
                                         target->module->segment_count);
    if (qualifier == NULL) {
        return NULL;
    }
    result = format_message("%s.%.*s",
                            qualifier,
                            (int)target->member_name.length,
                            target->member_name.data);
    free(qualifier);
    return result;
}

static const FengDecl *find_named_type_decl(const ResolveContext *context,
                                            const FengSlice *segments,
                                            size_t segment_count,
                                            size_t type_param_count) {
    FengSlice name;

    if (segment_count == 0U) {
        return NULL;
    }

    name = segments[segment_count - 1U];
    if (segment_count == 1U) {
        if (is_builtin_type_name(name)) {
            return NULL;
        }

        return find_visible_type_decl(context->visible_types, context->visible_type_count,
                                      name, type_param_count);
    }

    if (segment_count == 2U) {
        const AliasEntry *alias = find_alias(context->aliases, context->alias_count, segments[0]);

        if (alias != NULL) {
            return find_module_public_type_decl(alias->target_module, segments[1],
                                                type_param_count);
        }
    }

    {
        size_t module_index = find_module_index_by_path(context->analysis, segments, segment_count - 1U);

        if (module_index < context->analysis->module_count &&
            module_is_full_path_visible_from(context, &context->analysis->modules[module_index])) {
            return find_module_public_type_decl(&context->analysis->modules[module_index],
                                                name, type_param_count);
        }
    }

    return NULL;
}

static const char *type_ref_builtin_canonical_name(const FengTypeRef *type_ref, size_t pointer_size) {
    if (type_ref == NULL || type_ref->kind != FENG_TYPE_REF_NAMED ||
        type_ref->as.named.segment_count != 1U) {
        return NULL;
    }

    return canonical_builtin_type_name(type_ref->as.named.segments[0], pointer_size);
}

typedef enum FitTargetKind {
    FIT_TARGET_KIND_INVALID = 0,
    FIT_TARGET_KIND_USER_TYPE,
    FIT_TARGET_KIND_BUILTIN,
    FIT_TARGET_KIND_ARRAY,
} FitTargetKind;

typedef struct FitTargetResolution {
    FitTargetKind kind;
    const FengTypeRef *target_ref;
    const FengDecl *type_decl;
    const char *builtin_canonical_name;
} FitTargetResolution;

static const FengDecl *resolve_type_ref_decl(const ResolveContext *context,
                                             const FengTypeRef *type_ref);
static bool type_refs_semantically_equal(const ResolveContext *context,
                                         const FengTypeRef *left,
                                         const FengTypeRef *right);

static FitTargetResolution resolve_fit_target(const ResolveContext *context,
                                              const FengTypeRef *target_ref) {
    FitTargetResolution result;

    memset(&result, 0, sizeof(result));
    result.kind = FIT_TARGET_KIND_INVALID;
    result.target_ref = target_ref;
    if (target_ref == NULL) {
        return result;
    }
    if (target_ref->kind == FENG_TYPE_REF_ARRAY) {
        result.kind = FIT_TARGET_KIND_ARRAY;
        return result;
    }
    result.builtin_canonical_name = type_ref_builtin_canonical_name(target_ref, context->pointer_size);
    if (result.builtin_canonical_name != NULL) {
        result.kind = FIT_TARGET_KIND_BUILTIN;
        return result;
    }

    result.type_decl = resolve_type_ref_decl(context, target_ref);
    if (decl_is_named_fit_target(result.type_decl)) {
        result.kind = FIT_TARGET_KIND_USER_TYPE;
        return result;
    }

    return result;
}

static bool fit_target_collect_array_local_type_param(const ResolveContext *context,
                                                      const FengTypeRef *target_ref,
                                                      FengTypeParam *out_type_param) {
    const FengTypeRef *element_ref;
    FengSlice element_name;

    if (out_type_param == NULL || target_ref == NULL ||
        target_ref->kind != FENG_TYPE_REF_ARRAY) {
        return false;
    }

    element_ref = target_ref->as.inner;
    if (element_ref == NULL || element_ref->kind != FENG_TYPE_REF_NAMED ||
        element_ref->as.named.segment_count != 1U ||
        element_ref->as.named.type_arg_count != 0U) {
        return false;
    }

    element_name = element_ref->as.named.segments[0];
    if (is_builtin_type_name(element_name) ||
        resolve_type_ref_decl(context, element_ref) != NULL ||
        find_type_param(context, element_name) != NULL) {
        return false;
    }

    memset(out_type_param, 0, sizeof(*out_type_param));
    out_type_param->token = element_ref->token;
    out_type_param->name = element_name;
    out_type_param->constraint = NULL;
    return true;
}

static bool maybe_downgrade_orphan_fit_export(ResolveContext *context,
                                              const FengDecl *fit_decl,
                                              FitTargetResolution fit_target,
                                              const FengDecl *const *closure,
                                              size_t closure_count) {
    bool is_local = false;
    size_t i;

    if (fit_decl == NULL || fit_decl->visibility != FENG_VISIBILITY_PUBLIC) {
        return true;
    }

    if (fit_decl->as.fit_decl.spec_count == 0U) {
        return true;
    }

    if (fit_target.kind == FIT_TARGET_KIND_USER_TYPE && fit_target.type_decl != NULL) {
        const FengSemanticModule *target_module =
            find_decl_provider_module(context->analysis, fit_target.type_decl);

        is_local = (target_module == context->module);
    }

    if (fit_target.kind == FIT_TARGET_KIND_BUILTIN) {
        is_local = true;
    }

    for (i = 0U; i < closure_count && !is_local; ++i) {
        const FengSemanticModule *spec_module =
            find_decl_provider_module(context->analysis, closure[i]);
        if (spec_module == context->module) {
            is_local = true;
        }
    }

    if (!is_local) {
        FengDecl *mutable_decl = (FengDecl *)fit_decl;
        char *target_name = format_type_ref_name(fit_decl->as.fit_decl.target);
        char *message = format_message(
            "orphan fit for '%s' cannot be exported; downgraded to module-local visibility",
            target_name != NULL ? target_name : "<unknown>");

        free(target_name);
        mutable_decl->visibility = FENG_VISIBILITY_PRIVATE;
        if (!analysis_append_info(context->analysis, context->program->path,
                                  fit_decl->token, message)) {
            return false;
        }
    }

    return true;
}

static InferredExprType inferred_expr_type_from_fit_target_type_ref(const FengTypeRef *type_ref) {
    InferredExprType type = inferred_expr_type_unknown();

    if (type_ref == NULL) {
        return type;
    }

    type.kind = FENG_INFERRED_EXPR_TYPE_TYPE_REF;
    type.type_ref = type_ref;
    return type;
}

static bool fit_decl_target_matches_owner_type(const ResolveContext *context,
                                               const FengDecl *fit_decl,
                                               const FengDecl *owner_type_decl,
                                               InferredExprType owner_type) {
    FitTargetResolution fit_target;
    FengTypeParam fit_local_type_param;

    if (context == NULL || fit_decl == NULL || fit_decl->kind != FENG_DECL_FIT) {
        return false;
    }

    fit_target = resolve_fit_target(context, fit_decl->as.fit_decl.target);
    if (fit_target.target_ref == NULL) {
        return false;
    }

    if (owner_type_decl != NULL) {
        return fit_target.kind == FIT_TARGET_KIND_USER_TYPE &&
               fit_target.type_decl == owner_type_decl;
    }

    if (owner_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
        owner_type.type_ref != NULL) {
        if (fit_target.kind == FIT_TARGET_KIND_ARRAY &&
            fit_target_collect_array_local_type_param(context,
                                                      fit_target.target_ref,
                                                      &fit_local_type_param)) {
            return owner_type.type_ref->kind == FENG_TYPE_REF_ARRAY &&
                   owner_type.type_ref->array_element_writable ==
                       fit_target.target_ref->array_element_writable;
        }
        return type_refs_semantically_equal(context, fit_target.target_ref, owner_type.type_ref);
    }

    if (owner_type.kind == FENG_INFERRED_EXPR_TYPE_BUILTIN) {
        const char *owner_builtin = canonical_builtin_type_name(owner_type.builtin_name, context->pointer_size);

        return fit_target.kind == FIT_TARGET_KIND_BUILTIN &&
               fit_target.builtin_canonical_name != NULL &&
               owner_builtin != NULL &&
               strcmp(fit_target.builtin_canonical_name, owner_builtin) == 0;
    }

    return false;
}

/* Resolve closed declaration types without importing their short names into
 * the consumer's lexical environment. Implemented with the shared file type
 * environment builders below. */
static const FengDecl *resolve_type_ref_decl_in_program(
    const ResolveContext *context,
    const FengTypeRef *type_ref);

static const FengDecl *resolve_type_ref_decl(const ResolveContext *context,
                                             const FengTypeRef *type_ref) {
    if (type_ref == NULL || type_ref->kind != FENG_TYPE_REF_NAMED) {
        return NULL;
    }
    if (type_ref->as.named.segment_count == 1U &&
        is_builtin_type_name(type_ref->as.named.segments[0])) {
        return NULL;
    }
    if (type_ref->resolution_program != NULL &&
        type_ref->resolution_program != context->program) {
        return resolve_type_ref_decl_in_program(context, type_ref);
    }

    return find_named_type_decl(
        context, type_ref->as.named.segments, type_ref->as.named.segment_count,
        type_ref->as.named.type_arg_count);
}

static bool type_refs_semantically_equal(const ResolveContext *context,
                                         const FengTypeRef *left,
                                         const FengTypeRef *right) {
    if (left == right) {
        return true;
    }
    if (left == NULL || right == NULL) {
        return false;
    }
    if (left->kind != right->kind) {
        return false;
    }

    switch (left->kind) {
        case FENG_TYPE_REF_NAMED: {
            const char *left_builtin = type_ref_builtin_canonical_name(left, context->pointer_size);
            const char *right_builtin = type_ref_builtin_canonical_name(right, context->pointer_size);
            bool base_matches = false;

            if (left_builtin != NULL || right_builtin != NULL) {
                return left_builtin != NULL && right_builtin != NULL &&
                       strcmp(left_builtin, right_builtin) == 0;
            }

            {
                const FengDecl *left_decl = resolve_type_ref_decl(context, left);
                const FengDecl *right_decl = resolve_type_ref_decl(context, right);

                if (left_decl != NULL || right_decl != NULL) {
                    base_matches = left_decl != NULL && left_decl == right_decl;
                } else {
                    base_matches = left->as.named.segment_count == right->as.named.segment_count;
                    for (size_t segment_index = 0U;
                         base_matches && segment_index < left->as.named.segment_count;
                         ++segment_index) {
                        base_matches = slice_equals(left->as.named.segments[segment_index],
                                                    right->as.named.segments[segment_index]);
                    }
                }
            }

            if (!base_matches ||
                left->as.named.type_arg_count != right->as.named.type_arg_count) {
                return false;
            }
            for (size_t arg_index = 0U;
                 arg_index < left->as.named.type_arg_count;
                 ++arg_index) {
                if (!type_refs_semantically_equal(context,
                                                  left->as.named.type_args[arg_index],
                                                  right->as.named.type_args[arg_index])) {
                    return false;
                }
            }
            return true;
        }

        case FENG_TYPE_REF_POINTER:
        case FENG_TYPE_REF_ARRAY:
            if (left->kind == FENG_TYPE_REF_ARRAY &&
                left->array_element_writable != right->array_element_writable) {
                return false;
            }
            return type_refs_semantically_equal(context, left->as.inner, right->as.inner);
    }

    return false;
}

/* Release one recursive @friend semantic type identity. */
static void friend_type_identity_free(FriendTypeIdentity *identity) {
    if (identity == NULL) {
        return;
    }
    if (identity->kind == FRIEND_TYPE_IDENTITY_NAMED) {
        for (size_t index = 0U;
             index < identity->as.named.type_arg_count;
             ++index) {
            friend_type_identity_free(identity->as.named.type_args[index]);
        }
        free(identity->as.named.type_args);
    } else if (identity->kind == FRIEND_TYPE_IDENTITY_POINTER ||
               identity->kind == FRIEND_TYPE_IDENTITY_ARRAY) {
        friend_type_identity_free(identity->as.inner);
    }
    free(identity);
}

/* Return the owner-parameter index denoted by one plain named reference. */
static bool friend_type_ref_owner_param_index(
    const FengTypeRef *type_ref,
    const FengTypeParam *owner_type_params,
    size_t owner_type_param_count,
    size_t *out_index) {
    if (type_ref == NULL || type_ref->kind != FENG_TYPE_REF_NAMED ||
        type_ref->as.named.segment_count != 1U ||
        type_ref->as.named.type_arg_count != 0U) {
        return false;
    }
    for (size_t index = 0U; index < owner_type_param_count; ++index) {
        if (slice_equals(type_ref->as.named.segments[0],
                         owner_type_params[index].name)) {
            if (out_index != NULL) {
                *out_index = index;
            }
            return true;
        }
    }
    return false;
}

/* Build a stable semantic identity for a source type reference. During
 * declaration normalization owner parameters become indexed placeholders;
 * during access matching other active parameters retain their declaration
 * pointers so exact generic identities can be compared. */
static FriendTypeIdentity *build_friend_type_identity(
    const ResolveContext *context,
    const FengTypeRef *type_ref,
    const FengTypeParam *owner_type_params,
    size_t owner_type_param_count,
    bool normalize_owner_params) {
    FriendTypeIdentity *identity;

    if (context == NULL || type_ref == NULL) {
        return NULL;
    }
    identity = (FriendTypeIdentity *)calloc(1U, sizeof(*identity));
    if (identity == NULL) {
        return NULL;
    }
    identity->source_ref = type_ref;
    if (type_ref->kind == FENG_TYPE_REF_POINTER ||
        type_ref->kind == FENG_TYPE_REF_ARRAY) {
        identity->kind = type_ref->kind == FENG_TYPE_REF_POINTER
                             ? FRIEND_TYPE_IDENTITY_POINTER
                             : FRIEND_TYPE_IDENTITY_ARRAY;
        identity->array_element_writable = type_ref->array_element_writable;
        identity->as.inner = build_friend_type_identity(context,
                                                        type_ref->as.inner,
                                                        owner_type_params,
                                                        owner_type_param_count,
                                                        normalize_owner_params);
        if (identity->as.inner == NULL) {
            friend_type_identity_free(identity);
            return NULL;
        }
        return identity;
    }
    if (type_ref->kind != FENG_TYPE_REF_NAMED) {
        friend_type_identity_free(identity);
        return NULL;
    }
    if (normalize_owner_params) {
        size_t owner_param_index = 0U;

        if (friend_type_ref_owner_param_index(type_ref,
                                              owner_type_params,
                                              owner_type_param_count,
                                              &owner_param_index)) {
            identity->kind = FRIEND_TYPE_IDENTITY_OWNER_PARAM;
            identity->as.owner_param_index = owner_param_index;
            return identity;
        }
    } else if (type_ref->as.named.segment_count == 1U &&
               type_ref->as.named.type_arg_count == 0U) {
        const TypeParamEntry *entry =
            find_type_param(context, type_ref->as.named.segments[0]);

        if (entry != NULL && entry->type_param != NULL) {
            identity->kind = FRIEND_TYPE_IDENTITY_ACTIVE_PARAM;
            identity->as.active_param = entry->type_param;
            return identity;
        }
    }
    if (type_ref->as.named.segment_count == 1U) {
        const char *builtin_name = canonical_builtin_type_name(
            type_ref->as.named.segments[0], context->pointer_size);

        if (builtin_name != NULL) {
            identity->kind = FRIEND_TYPE_IDENTITY_BUILTIN;
            identity->as.builtin_name = builtin_name;
            return identity;
        }
    }
    identity->kind = FRIEND_TYPE_IDENTITY_NAMED;
    identity->as.named.decl = resolve_type_ref_decl(context, type_ref);
    identity->as.named.type_arg_count = type_ref->as.named.type_arg_count;
    if (identity->as.named.decl == NULL) {
        friend_type_identity_free(identity);
        return NULL;
    }
    if (type_ref->as.named.type_arg_count > 0U) {
        identity->as.named.type_args = (FriendTypeIdentity **)calloc(
            type_ref->as.named.type_arg_count,
            sizeof(*identity->as.named.type_args));
        if (identity->as.named.type_args == NULL) {
            friend_type_identity_free(identity);
            return NULL;
        }
        for (size_t index = 0U;
             index < type_ref->as.named.type_arg_count;
             ++index) {
            identity->as.named.type_args[index] = build_friend_type_identity(
                context,
                type_ref->as.named.type_args[index],
                owner_type_params,
                owner_type_param_count,
                normalize_owner_params);
            if (identity->as.named.type_args[index] == NULL) {
                friend_type_identity_free(identity);
                return NULL;
            }
        }
    }
    return identity;
}

/* Compare two fully materialized semantic type identities. */
static bool friend_type_identities_equal(const FriendTypeIdentity *left,
                                         const FriendTypeIdentity *right) {
    if (left == right) {
        return true;
    }
    if (left == NULL || right == NULL || left->kind != right->kind) {
        return false;
    }
    switch (left->kind) {
        case FRIEND_TYPE_IDENTITY_NAMED:
            if (left->as.named.decl != right->as.named.decl ||
                left->as.named.type_arg_count != right->as.named.type_arg_count) {
                return false;
            }
            for (size_t index = 0U;
                 index < left->as.named.type_arg_count;
                 ++index) {
                if (!friend_type_identities_equal(left->as.named.type_args[index],
                                                  right->as.named.type_args[index])) {
                    return false;
                }
            }
            return true;
        case FRIEND_TYPE_IDENTITY_BUILTIN:
            return left->as.builtin_name != NULL &&
                   right->as.builtin_name != NULL &&
                   strcmp(left->as.builtin_name, right->as.builtin_name) == 0;
        case FRIEND_TYPE_IDENTITY_OWNER_PARAM:
            return left->as.owner_param_index == right->as.owner_param_index;
        case FRIEND_TYPE_IDENTITY_ACTIVE_PARAM:
            return left->as.active_param == right->as.active_param;
        case FRIEND_TYPE_IDENTITY_POINTER:
            return friend_type_identities_equal(left->as.inner, right->as.inner);
        case FRIEND_TYPE_IDENTITY_ARRAY:
            return left->array_element_writable == right->array_element_writable &&
                   friend_type_identities_equal(left->as.inner, right->as.inner);
    }
    return false;
}

/* Compare a normalized friend identity with a materialized subject, replacing
 * owner-parameter placeholders from the concrete member-owner instance. */
static bool normalized_friend_type_matches_subject(
    const FriendTypeIdentity *normalized,
    FriendTypeIdentity *const *owner_type_args,
    size_t owner_type_arg_count,
    const FriendTypeIdentity *subject) {
    if (normalized == NULL || subject == NULL) {
        return false;
    }
    if (normalized->kind == FRIEND_TYPE_IDENTITY_OWNER_PARAM) {
        size_t index = normalized->as.owner_param_index;

        return index < owner_type_arg_count &&
               friend_type_identities_equal(owner_type_args[index], subject);
    }
    if (normalized->kind != subject->kind) {
        return false;
    }
    switch (normalized->kind) {
        case FRIEND_TYPE_IDENTITY_NAMED:
            if (normalized->as.named.decl != subject->as.named.decl ||
                normalized->as.named.type_arg_count !=
                    subject->as.named.type_arg_count) {
                return false;
            }
            for (size_t index = 0U;
                 index < normalized->as.named.type_arg_count;
                 ++index) {
                if (!normalized_friend_type_matches_subject(
                        normalized->as.named.type_args[index],
                        owner_type_args,
                        owner_type_arg_count,
                        subject->as.named.type_args[index])) {
                    return false;
                }
            }
            return true;
        case FRIEND_TYPE_IDENTITY_BUILTIN:
            return normalized->as.builtin_name != NULL &&
                   subject->as.builtin_name != NULL &&
                   strcmp(normalized->as.builtin_name,
                          subject->as.builtin_name) == 0;
        case FRIEND_TYPE_IDENTITY_ACTIVE_PARAM:
            return normalized->as.active_param == subject->as.active_param;
        case FRIEND_TYPE_IDENTITY_POINTER:
            return normalized_friend_type_matches_subject(
                normalized->as.inner,
                owner_type_args,
                owner_type_arg_count,
                subject->as.inner);
        case FRIEND_TYPE_IDENTITY_ARRAY:
            return normalized->array_element_writable ==
                       subject->array_element_writable &&
                   normalized_friend_type_matches_subject(
                       normalized->as.inner,
                       owner_type_args,
                       owner_type_arg_count,
                       subject->as.inner);
        case FRIEND_TYPE_IDENTITY_OWNER_PARAM:
            break;
    }
    return false;
}

/* Find normalized friend metadata for one local source member. */
static const struct FengFriendMemberInfo *find_friend_member_info(
    const FengSemanticAnalysis *analysis,
    const FengTypeMember *member) {
    if (analysis == NULL || member == NULL) {
        return NULL;
    }
    for (size_t index = 0U;
         index < analysis->friend_member_info_count;
         ++index) {
        if (analysis->friend_member_infos[index].member == member) {
            return &analysis->friend_member_infos[index];
        }
    }
    return NULL;
}

/* Return or create the single normalized friend-set record for a member. */
static struct FengFriendMemberInfo *ensure_friend_member_info(
    ResolveContext *context,
    const FengDecl *owner_decl,
    const FengTypeMember *member,
    size_t owner_type_param_count) {
    FengSemanticAnalysis *analysis;
    struct FengFriendMemberInfo info;

    if (context == NULL || context->analysis == NULL || owner_decl == NULL ||
        member == NULL) {
        return NULL;
    }
    analysis = (FengSemanticAnalysis *)context->analysis;
    for (size_t index = 0U;
         index < analysis->friend_member_info_count;
         ++index) {
        if (analysis->friend_member_infos[index].member == member) {
            return &analysis->friend_member_infos[index];
        }
    }
    memset(&info, 0, sizeof(info));
    info.member = member;
    info.owner_decl = owner_decl;
    info.owner_module = context->module;
    info.owner_program = context->program;
    info.owner_type_param_count = owner_type_param_count;
    if (!append_raw((void **)&analysis->friend_member_infos,
                    &analysis->friend_member_info_count,
                    &analysis->friend_member_info_capacity,
                    sizeof(info),
                    &info)) {
        return NULL;
    }
    return &analysis->friend_member_infos[
        analysis->friend_member_info_count - 1U];
}

/* Resolve all @friend type-position arguments in the owner's lexical scope,
 * merge multiple annotations, and silently deduplicate semantic identities. */
static bool normalize_friend_member_annotations(
    ResolveContext *context,
    const FengDecl *owner_decl,
    const FengTypeMember *member,
    const FengTypeParam *owner_type_params,
    size_t owner_type_param_count) {
    struct FengFriendMemberInfo *info = NULL;

    if (context == NULL || owner_decl == NULL || member == NULL) {
        return true;
    }
    for (size_t annotation_index = 0U;
         annotation_index < member->annotation_count;
         ++annotation_index) {
        const FengAnnotation *annotation =
            &member->annotations[annotation_index];

        if (annotation->builtin_kind != FENG_ANNOTATION_FRIEND) {
            continue;
        }
        if (info == NULL) {
            info = ensure_friend_member_info(context,
                                             owner_decl,
                                             member,
                                             owner_type_param_count);
            if (info == NULL) {
                return false;
            }
        }
        for (size_t arg_index = 0U;
             arg_index < annotation->arg_count;
             ++arg_index) {
            const FengTypeRef *friend_ref = annotation->type_args[arg_index];
            const FengDecl *friend_decl;
            FriendTypeIdentity *identity;
            bool duplicate = false;

            if (!resolve_type_ref(context, friend_ref, false)) {
                return false;
            }
            friend_decl = resolve_type_ref_decl(context, friend_ref);
            if (friend_ref == NULL || friend_ref->kind != FENG_TYPE_REF_NAMED ||
                friend_decl == NULL || friend_decl->kind != FENG_DECL_TYPE) {
                char *friend_name = format_type_ref_name(friend_ref);
                bool reported = resolver_append_error(
                    context,
                    friend_ref != NULL ? friend_ref->token : annotation->token,
                    "AE1336",
                    format_message(
                        "@friend argument '%s' must resolve to a concrete type",
                        friend_name != NULL ? friend_name : "<unknown>"));

                free(friend_name);
                return reported && false;
            }
            identity = build_friend_type_identity(context,
                                                  friend_ref,
                                                  owner_type_params,
                                                  owner_type_param_count,
                                                  true);
            if (identity == NULL) {
                return false;
            }
            for (size_t existing_index = 0U;
                 existing_index < info->friend_type_count;
                 ++existing_index) {
                if (friend_type_identities_equal(
                        info->friend_types[existing_index], identity)) {
                    duplicate = true;
                    break;
                }
            }
            if (duplicate) {
                friend_type_identity_free(identity);
                continue;
            }
            if (!append_raw((void **)&info->friend_types,
                            &info->friend_type_count,
                            &info->friend_type_capacity,
                            sizeof(identity),
                            &identity)) {
                friend_type_identity_free(identity);
                return false;
            }
        }
    }
    return true;
}

static const FengDecl *resolve_union_spec_type_ref_decl(const ResolveContext *context,
                                                        const FengTypeRef *type_ref) {
    const FengDecl *decl = resolve_type_ref_decl(context, type_ref);

    if (decl != NULL && decl->kind == FENG_DECL_SPEC &&
        decl->as.spec_decl.form == FENG_SPEC_FORM_UNION) {
        return decl;
    }
    if (type_ref != NULL && type_ref->kind == FENG_TYPE_REF_NAMED &&
        type_ref->as.named.segment_count == 1U &&
        type_ref->as.named.type_arg_count == 0U) {
        const TypeParamEntry *type_param = find_type_param(context, type_ref->as.named.segments[0]);

        if (type_param != NULL && type_param->type_param != NULL) {
            const FengDecl *constraint_decl =
                resolve_type_ref_decl(context, type_param->type_param->constraint);

            if (constraint_decl != NULL && constraint_decl->kind == FENG_DECL_SPEC &&
                constraint_decl->as.spec_decl.form == FENG_SPEC_FORM_UNION) {
                return constraint_decl;
            }
        }
    }
    return NULL;
}

static void free_union_member_infos_local(FengUnionSpecMemberInfo *members,
                                          size_t member_count) {
    for (size_t index = 0U; index < member_count; ++index) {
        free_synthetic_type_ref((FengTypeRef *)members[index].type_ref);
    }
    free(members);
}

static bool append_normalized_union_member(ResolveContext *context,
                                           FengUnionSpecMemberInfo **members,
                                           size_t *member_count,
                                           size_t *member_capacity,
                                           const FengTypeRef *type_ref,
                                           bool is_nested_union) {
    FengUnionSpecMemberInfo entry;

    for (size_t index = 0U; index < *member_count; ++index) {
        if (type_refs_semantically_equal(context, (*members)[index].type_ref, type_ref)) {
            return true;
        }
    }

    memset(&entry, 0, sizeof(entry));
    entry.type_ref = clone_type_ref_for_inference(type_ref);
    if (entry.type_ref == NULL) {
        return false;
    }
    entry.resolved_decl = resolve_type_ref_decl(context, type_ref);
    entry.is_nested_union = is_nested_union;
    if (!append_raw((void **)members,
                    member_count,
                    member_capacity,
                    sizeof(entry),
                    &entry)) {
        free_synthetic_type_ref((FengTypeRef *)entry.type_ref);
        return false;
    }
    return true;
}

static bool collect_normalized_union_member(ResolveContext *context,
                                            const FengDecl *owner_union_decl,
                                            const FengTypeRef *member_ref,
                                            FengUnionSpecMemberInfo **members,
                                            size_t *member_count,
                                            size_t *member_capacity) {
    const FengDecl *resolved = resolve_type_ref_decl(context, member_ref);
    bool is_nested_union = (resolved != NULL && resolved->kind == FENG_DECL_SPEC &&
                             resolved->as.spec_decl.form == FENG_SPEC_FORM_UNION);

    (void)owner_union_decl;

    return append_normalized_union_member(context,
                                          members,
                                          member_count,
                                          member_capacity,
                                          member_ref,
                                          is_nested_union);
}

static bool detect_union_form_cycle(ResolveContext *context,
                                    const FengDecl *current,
                                    const FengDecl **stack,
                                    size_t stack_count) {
    for (size_t i = 0U; i < stack_count; ++i) {
        if (stack[i] == current) {
            return resolver_append_error(
                context,
                current->token,
                "AE0601", format_message("union-form spec '%.*s' forms a cycle through its member list",
                               (int)current->as.spec_decl.name.length,
                               current->as.spec_decl.name.data));
        }
    }

    if (current->kind != FENG_DECL_SPEC ||
        current->as.spec_decl.form != FENG_SPEC_FORM_UNION) {
        return true;
    }

    if (stack_count >= 256U) {
        return false;
    }
    stack[stack_count] = current;
    stack_count++;

    for (size_t i = 0U;
         i < current->as.spec_decl.as.union_form.member_count;
         ++i) {
        const FengTypeRef *member_ref = current->as.spec_decl.as.union_form.members[i];
        const FengDecl *member_decl = resolve_type_ref_decl(context, member_ref);

        if (member_decl != NULL &&
            member_decl->kind == FENG_DECL_SPEC &&
            member_decl->as.spec_decl.form == FENG_SPEC_FORM_UNION) {
            if (!detect_union_form_cycle(context, member_decl, stack, stack_count)) {
                return false;
            }
        }
    }

    return true;
}

static bool record_normalized_union_spec_info(ResolveContext *context, const FengDecl *decl) {
    FengUnionSpecMemberInfo *members = NULL;
    size_t member_count = 0U;
    size_t member_capacity = 0U;
    bool ok = true;

    if (context == NULL || context->analysis == NULL || decl == NULL ||
        decl->kind != FENG_DECL_SPEC || decl->as.spec_decl.form != FENG_SPEC_FORM_UNION) {
        return true;
    }

    const FengDecl *cycle_stack[256];
    if (!detect_union_form_cycle(context, decl, cycle_stack, 0U)) {
        return false;
    }

    for (size_t index = 0U;
         ok && index < decl->as.spec_decl.as.union_form.member_count;
         ++index) {
        const FengTypeRef *member_ref = decl->as.spec_decl.as.union_form.members[index];

        if (type_ref_is_void(member_ref)) {
            ok = resolver_append_error(
                context,
                member_ref != NULL ? member_ref->token : decl->token,
                "AE0602", format_message("union-form spec members cannot be 'void'"));
            break;
        }
        if (!resolve_type_ref(context, member_ref, false)) {
            ok = false;
            break;
        }
        {
            const FengDecl *resolved_member = resolve_type_ref_decl(context, member_ref);
            if (resolved_member != NULL && resolved_member->kind == FENG_DECL_SPEC &&
                resolved_member->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
                ok = resolver_append_error(
                    context, member_ref->token,
                    "AE0622", format_message(
                        "union-form spec '%.*s' cannot have intersection-form spec '%.*s' as a member",
                        (int)decl->as.spec_decl.name.length,
                        decl->as.spec_decl.name.data,
                        (int)resolved_member->as.spec_decl.name.length,
                        resolved_member->as.spec_decl.name.data));
                break;
            }
        }
        ok = collect_normalized_union_member(context,
                                             decl,
                                             member_ref,
                                             &members,
                                             &member_count,
                                             &member_capacity);
    }

    if (!ok) {
        free_union_member_infos_local(members, member_count);
        return false;
    }
    if (member_count == 0U) {
        free_union_member_infos_local(members, member_count);
        return resolver_append_error(
            context,
            decl->token,
            "AE0603", format_message("union-form spec '%.*s' must have at least one member",
                           (int)decl->as.spec_decl.name.length,
                           decl->as.spec_decl.name.data));
    }
    if (!feng_semantic_record_union_spec_info(context->analysis, decl, members, member_count)) {
        return false;
    }
    return true;
}

static bool function_type_refs_have_equal_signature(const ResolveContext *context,
                                                    const FengTypeRef *src_ref,
                                                    const FengTypeRef *dst_ref);

static const FengDecl *resolve_callable_spec_type_ref_decl(const ResolveContext *context,
                                                           const FengTypeRef *type_ref) {
    const FengDecl *decl;

    if (type_ref == NULL) {
        return NULL;
    }
    decl = resolve_type_ref_decl(context, type_ref);
    if (decl == NULL || decl->kind != FENG_DECL_SPEC ||
        decl->as.spec_decl.form != FENG_SPEC_FORM_CALLABLE) {
        return NULL;
    }
    return decl;
}

static bool inferred_expr_type_matches_type_ref(const ResolveContext *context,
                                                InferredExprType expr_type,
                                                const FengTypeRef *type_ref) {
    const char *expr_builtin;
    const char *target_builtin;
    const FengDecl *target_decl;

    switch (expr_type.kind) {
        case FENG_INFERRED_EXPR_TYPE_BUILTIN:
            expr_builtin = canonical_builtin_type_name(expr_type.builtin_name, context->pointer_size);
            target_builtin = type_ref_builtin_canonical_name(type_ref, context->pointer_size);
            if (expr_builtin != NULL && target_builtin != NULL &&
                strcmp(expr_builtin, target_builtin) == 0) {
                return true;
            }
            target_decl = resolve_type_ref_decl(context, type_ref);
            if (expr_builtin != NULL && target_decl != NULL &&
                target_decl->kind == FENG_DECL_SPEC) {
                FengSlice seg = slice_from_cstr(expr_builtin);
                FengTypeRef src_ref;

                memset(&src_ref, 0, sizeof(src_ref));
                src_ref.kind = FENG_TYPE_REF_NAMED;
                src_ref.as.named.segments = &seg;
                src_ref.as.named.segment_count = 1U;
                src_ref.as.named.type_args = NULL;
                src_ref.as.named.type_arg_count = 0U;
                return type_ref_satisfies_spec_type_ref(context,
                                                        &src_ref,
                                                        type_ref);
            }
            return false;

        case FENG_INFERRED_EXPR_TYPE_TYPE_REF:
            if (expr_type.type_ref != NULL &&
                type_refs_semantically_equal(context, expr_type.type_ref, type_ref)) {
                return true;
            }
            if (resolve_callable_spec_type_ref_decl(context, expr_type.type_ref) != NULL &&
                resolve_callable_spec_type_ref_decl(context, type_ref) != NULL) {
                return false;
            }
            if (function_type_refs_have_equal_signature(context,
                                                        expr_type.type_ref,
                                                        type_ref)) {
                return true;
            }
            {
                const FengDecl *dst_decl = resolve_type_ref_decl(context, type_ref);
                ObjectSpecUpcastPath upcast_path;

                if (dst_decl != NULL && dst_decl->kind == FENG_DECL_SPEC &&
                    dst_decl->as.spec_decl.form == FENG_SPEC_FORM_OBJECT &&
                    find_object_spec_upcast_path(context,
                                                 expr_type,
                                                 type_ref,
                                                 &upcast_path)) {
                    object_spec_upcast_path_free(&upcast_path);
                    return true;
                }

                /* Object-form spec satisfaction is nominal: the source type must explicitly
                 * declare the spec (in its declared spec list, transitively, or via a visible
                 * fit). Structural shape match alone is not sufficient — duck typing is not
                 * supported here. See type_decl_satisfies_spec_decl for the lookup. */
                if (dst_decl != NULL && dst_decl->kind == FENG_DECL_SPEC &&
                    type_ref_satisfies_spec_type_ref(context, expr_type.type_ref, type_ref)) {
                    return true;
                }
            }
            return false;

        case FENG_INFERRED_EXPR_TYPE_DECL:
            target_decl = resolve_type_ref_decl(context, type_ref);
            if (target_decl != NULL && target_decl == expr_type.type_decl) {
                return true;
            }
            if (target_decl != NULL && target_decl->kind == FENG_DECL_SPEC &&
                target_decl->as.spec_decl.form == FENG_SPEC_FORM_OBJECT) {
                ObjectSpecUpcastPath upcast_path;

                if (find_object_spec_upcast_path(context,
                                                 expr_type,
                                                 type_ref,
                                                 &upcast_path)) {
                    object_spec_upcast_path_free(&upcast_path);
                    return true;
                }
            }
            if (target_decl != NULL && target_decl->kind == FENG_DECL_SPEC &&
                decl_is_named_fit_target(expr_type.type_decl) &&
                type_decl_satisfies_spec_type_ref(context, expr_type.type_decl, type_ref)) {
                return true;
            }
            return false;

        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
            target_decl = resolve_type_ref_decl(context, type_ref);
            if (!decl_is_function_type(target_decl)) {
                return false;
            }
            return lambda_expr_matches_function_type((ResolveContext *)context,
                                                     expr_type.lambda_expr,
                                                     type_ref,
                                                     target_decl);

        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
            return false;
    }

    return false;
}

#define UNION_MAX_PATH_DEPTH 8U

typedef struct UnionMemberSelection {
    bool matched;
    bool ambiguous;
    size_t member_index;
    const FengTypeRef *member_type_ref;
    /* Final non-union member reached by path_indices. This can differ from
     * member_type_ref when the selected direct member is a nested union. */
    const FengTypeRef *leaf_type_ref;
    size_t path_indices[UNION_MAX_PATH_DEPTH];
    size_t path_length;
} UnionMemberSelection;

static bool inferred_expr_type_exactly_matches_type_ref(const ResolveContext *context,
                                                        InferredExprType expr_type,
                                                        const FengTypeRef *type_ref) {
    const char *expr_builtin;
    const char *target_builtin;
    const FengDecl *target_decl;

    switch (expr_type.kind) {
        case FENG_INFERRED_EXPR_TYPE_BUILTIN:
            expr_builtin = canonical_builtin_type_name(expr_type.builtin_name, context->pointer_size);
            target_builtin = type_ref_builtin_canonical_name(type_ref, context->pointer_size);
            return expr_builtin != NULL && target_builtin != NULL &&
                   strcmp(expr_builtin, target_builtin) == 0;

        case FENG_INFERRED_EXPR_TYPE_TYPE_REF:
            return type_refs_semantically_equal(context, expr_type.type_ref, type_ref);

        case FENG_INFERRED_EXPR_TYPE_DECL:
            target_decl = resolve_type_ref_decl(context, type_ref);
            return target_decl != NULL && target_decl == expr_type.type_decl;

        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
            return false;
    }
    return false;
}

static UnionMemberSelection select_union_member_for_expr_type(const ResolveContext *context,
                                                              InferredExprType expr_type,
                                                              const FengDecl *union_decl,
                                                              const FengTypeRef *union_spec_type_ref) {
    const FengUnionSpecInfo *info = feng_semantic_lookup_union_spec_info(context->analysis,
                                                                         union_decl);
    UnionMemberSelection result;
    size_t match_count = 0U;
    size_t compatible_count = 0U;

    memset(&result, 0, sizeof(result));
    if (info == NULL) {
        return result;
    }

    /* Pass 1: exact direct match. */
    for (size_t index = 0U; index < info->member_count; ++index) {
        const FengTypeRef *member_type_ref = substitute_spec_member_type_ref_for_instance(
            (ResolveContext *)context,
            union_decl,
            union_spec_type_ref,
            info->members[index].type_ref);

        if (inferred_expr_type_exactly_matches_type_ref(context,
                                                        expr_type,
                                                        member_type_ref)) {
            result.matched = true;
            result.member_index = index;
            result.member_type_ref = member_type_ref;
            result.leaf_type_ref = member_type_ref;
            result.path_indices[0] = index;
            result.path_length = 1U;
            return result;
        }
    }

    /* Pass 2: exact match through nested union members (multi-level). */
    for (size_t index = 0U; index < info->member_count; ++index) {
        if (!info->members[index].is_nested_union) {
            continue;
        }
        const FengDecl *nested_decl = info->members[index].resolved_decl;
        if (nested_decl == NULL) {
            continue;
        }
        const FengTypeRef *member_type_ref = substitute_spec_member_type_ref_for_instance(
            (ResolveContext *)context,
            union_decl,
            union_spec_type_ref,
            info->members[index].type_ref);

        UnionMemberSelection nested = select_union_member_for_expr_type(
            context, expr_type, nested_decl, member_type_ref);
        if (nested.matched && !nested.ambiguous) {
            if (match_count == 0U) {
                result.matched = true;
                result.member_index = index;
                result.member_type_ref = member_type_ref;
                result.leaf_type_ref = nested.leaf_type_ref;
                result.path_indices[0] = index;
                size_t copy_len = nested.path_length;
                if (copy_len + 1U > UNION_MAX_PATH_DEPTH) {
                    copy_len = UNION_MAX_PATH_DEPTH - 1U;
                }
                for (size_t j = 0U; j < copy_len; ++j) {
                    result.path_indices[j + 1U] = nested.path_indices[j];
                }
                result.path_length = copy_len + 1U;
            }
            ++match_count;
        }
    }
    if (match_count > 1U) {
        result.ambiguous = true;
        result.matched = false;
        result.member_type_ref = NULL;
        result.leaf_type_ref = NULL;
        return result;
    }
    if (match_count == 1U) {
        return result;
    }

    /* Pass 3: compatibility match (non-exact). */
    for (size_t index = 0U; index < info->member_count; ++index) {
        const FengTypeRef *member_type_ref = substitute_spec_member_type_ref_for_instance(
            (ResolveContext *)context,
            union_decl,
            union_spec_type_ref,
            info->members[index].type_ref);

        if (!inferred_expr_type_matches_type_ref(context,
                                                 expr_type,
                                                 member_type_ref)) {
            continue;
        }
        if (compatible_count == 0U) {
            result.matched = true;
            result.member_index = index;
            result.member_type_ref = member_type_ref;
            result.leaf_type_ref = member_type_ref;
            result.path_indices[0] = index;
            result.path_length = 1U;
        } else {
            result.ambiguous = true;
        }
        ++compatible_count;
    }
    if (result.ambiguous) {
        result.matched = false;
        result.member_type_ref = NULL;
        result.leaf_type_ref = NULL;
    }
    return result;
}

static bool inferred_expr_type_is_union_view(const ResolveContext *context,
                                             InferredExprType expr_type) {
    switch (expr_type.kind) {
        case FENG_INFERRED_EXPR_TYPE_TYPE_REF:
            return resolve_union_spec_type_ref_decl(context, expr_type.type_ref) != NULL;

        case FENG_INFERRED_EXPR_TYPE_DECL:
            return expr_type.type_decl != NULL && expr_type.type_decl->kind == FENG_DECL_SPEC &&
                   expr_type.type_decl->as.spec_decl.form == FENG_SPEC_FORM_UNION;

        case FENG_INFERRED_EXPR_TYPE_BUILTIN:
        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
            return false;
    }
    return false;
}

static bool inferred_expr_types_equal(const ResolveContext *context,
                                      InferredExprType left,
                                      InferredExprType right) {
    if (left.kind == FENG_INFERRED_EXPR_TYPE_UNKNOWN ||
        right.kind == FENG_INFERRED_EXPR_TYPE_UNKNOWN) {
        return false;
    }
    if (left.kind == FENG_INFERRED_EXPR_TYPE_BUILTIN &&
        right.kind == FENG_INFERRED_EXPR_TYPE_BUILTIN) {
        return strcmp(canonical_builtin_type_name(left.builtin_name, context->pointer_size),
                      canonical_builtin_type_name(right.builtin_name, context->pointer_size)) == 0;
    }
    if (left.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
        right.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        return type_refs_semantically_equal(context, left.type_ref, right.type_ref);
    }
    if (left.kind == FENG_INFERRED_EXPR_TYPE_DECL &&
        right.kind == FENG_INFERRED_EXPR_TYPE_DECL) {
        return left.type_decl != NULL && left.type_decl == right.type_decl;
    }
    if (left.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA &&
        right.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA) {
        return lambda_expr_signature_matches_lambda_expr(
            (ResolveContext *)context, left.lambda_expr, right.lambda_expr);
    }
    if (left.kind == FENG_INFERRED_EXPR_TYPE_BUILTIN &&
        right.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        return inferred_expr_type_matches_type_ref(context, left, right.type_ref);
    }
    if (left.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
        right.kind == FENG_INFERRED_EXPR_TYPE_BUILTIN) {
        return inferred_expr_type_matches_type_ref(context, right, left.type_ref);
    }
    if (left.kind == FENG_INFERRED_EXPR_TYPE_DECL &&
        right.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        return inferred_expr_type_matches_type_ref(context, left, right.type_ref);
    }
    if (left.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
        right.kind == FENG_INFERRED_EXPR_TYPE_DECL) {
        return inferred_expr_type_matches_type_ref(context, right, left.type_ref);
    }
    if (left.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA &&
        right.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        return inferred_expr_type_matches_type_ref(context, left, right.type_ref);
    }
    if (left.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
        right.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA) {
        return inferred_expr_type_matches_type_ref(context, right, left.type_ref);
    }
    if (left.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA &&
        right.kind == FENG_INFERRED_EXPR_TYPE_DECL &&
        right.type_decl != NULL &&
        decl_is_function_type(right.type_decl)) {
        return lambda_expr_matches_function_type((ResolveContext *)context,
                                                 left.lambda_expr,
                                                 NULL,
                                                 right.type_decl);
    }
    if (left.kind == FENG_INFERRED_EXPR_TYPE_DECL &&
        right.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA &&
        left.type_decl != NULL &&
        decl_is_function_type(left.type_decl)) {
        return lambda_expr_matches_function_type((ResolveContext *)context,
                                                 right.lambda_expr,
                                                 NULL,
                                                 left.type_decl);
    }

    return false;
}

/* Resolve a type reference only when it denotes a named tuple declaration. */
static const FengDecl *resolve_tuple_type_ref_decl(const ResolveContext *context,
                                                  const FengTypeRef *type_ref) {
    const FengDecl *decl = resolve_type_ref_decl(context, type_ref);

    return decl_is_tuple_type(decl) ? decl : NULL;
}

/* Fetch the positional tuple field at index, preserving parser member order. */
static const FengTypeMember *tuple_field_member_at(const FengDecl *tuple_decl,
                                                   size_t field_index) {
    size_t member_index;
    size_t seen_fields = 0U;

    if (!decl_is_tuple_type(tuple_decl)) {
        return NULL;
    }

    for (member_index = 0U;
         member_index < tuple_decl->as.type_decl.member_count;
         ++member_index) {
        const FengTypeMember *member = tuple_decl->as.type_decl.members[member_index];

        if (member == NULL || member->is_static ||
            member->kind != FENG_TYPE_MEMBER_FIELD) {
            continue;
        }
        if (seen_fields == field_index) {
            return member;
        }
        ++seen_fields;
    }

    return NULL;
}

/* Return a tuple field type after applying the instance's generic arguments. */
static const FengTypeRef *tuple_field_type_for_instance(ResolveContext *context,
                                                        const FengDecl *tuple_decl,
                                                        const FengTypeRef *tuple_type_ref,
                                                        size_t field_index) {
    const FengTypeMember *field = tuple_field_member_at(tuple_decl, field_index);

    if (field == NULL) {
        return NULL;
    }
    return substitute_type_ref_for_owner_instance(context,
                                                  tuple_decl,
                                                  inferred_expr_type_from_type_ref(tuple_type_ref),
                                                  field->as.field.type);
}

/* Compare two named tuple instances structurally for explicit casts. */
static bool tuple_type_refs_have_equal_shape(ResolveContext *context,
                                             const FengTypeRef *source_type_ref,
                                             const FengTypeRef *target_type_ref) {
    const FengDecl *source_decl = resolve_tuple_type_ref_decl(context, source_type_ref);
    const FengDecl *target_decl = resolve_tuple_type_ref_decl(context, target_type_ref);
    size_t field_index;

    if (source_decl == NULL || target_decl == NULL) {
        return false;
    }
    if (source_decl->as.type_decl.member_count != target_decl->as.type_decl.member_count) {
        return false;
    }

    for (field_index = 0U;
         field_index < source_decl->as.type_decl.member_count;
         ++field_index) {
        const FengTypeRef *source_field_type =
            tuple_field_type_for_instance(context, source_decl, source_type_ref, field_index);
        const FengTypeRef *target_field_type =
            tuple_field_type_for_instance(context, target_decl, target_type_ref, field_index);

        if (source_field_type == NULL || target_field_type == NULL ||
            !type_refs_semantically_equal(context, source_field_type, target_field_type)) {
            return false;
        }
    }

    return true;
}

/* Compare an inferred tuple value against a target tuple for explicit casts. */
static bool inferred_tuple_type_has_equal_shape(ResolveContext *context,
                                                InferredExprType source_type,
                                                const FengTypeRef *target_type_ref) {
    const FengDecl *target_decl = resolve_tuple_type_ref_decl(context, target_type_ref);

    if (target_decl == NULL) {
        return false;
    }
    if (source_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        return tuple_type_refs_have_equal_shape(context, source_type.type_ref, target_type_ref);
    }
    if (source_type.kind == FENG_INFERRED_EXPR_TYPE_DECL &&
        decl_is_tuple_type(source_type.type_decl)) {
        size_t field_index;

        if (source_type.type_decl->as.type_decl.member_count !=
            target_decl->as.type_decl.member_count) {
            return false;
        }
        for (field_index = 0U;
             field_index < source_type.type_decl->as.type_decl.member_count;
             ++field_index) {
            const FengTypeMember *source_field =
                tuple_field_member_at(source_type.type_decl, field_index);
            const FengTypeRef *target_field_type =
                tuple_field_type_for_instance(context, target_decl, target_type_ref, field_index);

            if (source_field == NULL || target_field_type == NULL ||
                !type_refs_semantically_equal(context,
                                              source_field->as.field.type,
                                              target_field_type)) {
                return false;
            }
        }
        return true;
    }

    return false;
}

/* Pure tuple literal matcher used by overload resolution and expected-type checks. */
static bool tuple_literal_matches_tuple_type_ref(ResolveContext *context,
                                                 const FengExpr *expr,
                                                 const FengTypeRef *expected_type_ref) {
    const FengDecl *tuple_decl = resolve_tuple_type_ref_decl(context, expected_type_ref);
    size_t item_index;

    if (expr == NULL || expr->kind != FENG_EXPR_TUPLE_LITERAL || tuple_decl == NULL) {
        return false;
    }
    if (expr->as.tuple_literal.count != tuple_decl->as.type_decl.member_count) {
        return false;
    }

    for (item_index = 0U; item_index < expr->as.tuple_literal.count; ++item_index) {
        const FengTypeRef *field_type =
            tuple_field_type_for_instance(context, tuple_decl, expected_type_ref, item_index);

        if (field_type == NULL ||
            !expr_matches_expected_type_ref(context,
                                            expr->as.tuple_literal.items[item_index],
                                            field_type)) {
            return false;
        }
    }

    return true;
}

/* Validate a tuple literal against the named tuple that supplies its type. */
static bool validate_tuple_literal_expr_against_type(ResolveContext *context,
                                                     const FengExpr *expr,
                                                     const FengTypeRef *expected_type_ref) {
    const FengDecl *tuple_decl = resolve_tuple_type_ref_decl(context, expected_type_ref);
    size_t item_index;

    if (expr == NULL || expr->kind != FENG_EXPR_TUPLE_LITERAL) {
        return true;
    }
    if (tuple_decl == NULL) {
        char *type_name = format_type_ref_name(expected_type_ref);
        bool ok = resolver_append_error(
            context,
            expr->token,
            "AE0301", format_message("tuple literal requires a named tuple target type, got '%s'",
                           type_name != NULL ? type_name : "<type>"));

        free(type_name);
        return ok;
    }
    if (expr->as.tuple_literal.count != tuple_decl->as.type_decl.member_count) {
        char *type_name = format_type_ref_name(expected_type_ref);
        bool ok = resolver_append_error(
            context,
            expr->token,
            "AE0302", format_message("tuple literal has %zu element(s) but tuple type '%s' expects %zu",
                           expr->as.tuple_literal.count,
                           type_name != NULL ? type_name : "<type>",
                           tuple_decl->as.type_decl.member_count));

        free(type_name);
        return ok;
    }

    for (item_index = 0U; item_index < expr->as.tuple_literal.count; ++item_index) {
        const FengTypeRef *field_type =
            tuple_field_type_for_instance(context, tuple_decl, expected_type_ref, item_index);

        if (field_type != NULL &&
            !validate_expr_against_expected_type(context,
                                                 expr->as.tuple_literal.items[item_index],
                                                 field_type)) {
            return false;
        }
    }

    return true;
}

static const FengDecl *resolve_function_type_decl(const ResolveContext *context,
                                                  const FengTypeRef *type_ref) {
    const FengDecl *type_decl = resolve_type_ref_decl(context, type_ref);

    if (!decl_is_function_type(type_decl)) {
        return NULL;
    }

    return type_decl;
}

static const FengDecl *resolve_abi_function_pointer_type_decl(const ResolveContext *context,
                                                              const FengTypeRef *type_ref) {
    const FengDecl *type_decl;

    if (type_ref == NULL || type_ref->kind != FENG_TYPE_REF_POINTER) {
        return NULL;
    }

    type_decl = resolve_function_type_decl(context, type_ref->as.inner);
    if (type_decl == NULL ||
        !annotations_contain_kind(type_decl->annotations,
                                  type_decl->annotation_count,
                                  FENG_ANNOTATION_ABI)) {
        return NULL;
    }

    return type_decl;
}

/* Resolve the callable-form constraint reference carried by one active type
 * parameter. The returned reference retains any concrete spec type arguments. */
static const FengTypeRef *resolve_callable_constraint_type_ref(
    const ResolveContext *context,
    InferredExprType expr_type) {
    const TypeParamEntry *type_param_entry;

    if (expr_type.kind != FENG_INFERRED_EXPR_TYPE_TYPE_REF ||
        expr_type.type_ref == NULL ||
        expr_type.type_ref->kind != FENG_TYPE_REF_NAMED ||
        expr_type.type_ref->as.named.segment_count != 1U ||
        expr_type.type_ref->as.named.type_arg_count != 0U) {
        return NULL;
    }

    type_param_entry = find_type_param(context, expr_type.type_ref->as.named.segments[0]);
    if (type_param_entry == NULL || type_param_entry->type_param == NULL ||
        type_param_entry->type_param->constraint == NULL) {
        return NULL;
    }

    return type_param_entry->type_param->constraint;
}

/* Resolve the declaration behind an active callable-form constraint. */
static const FengDecl *resolve_callable_constraint_type_decl(
    const ResolveContext *context,
    InferredExprType expr_type) {
    return resolve_function_type_decl(
        context, resolve_callable_constraint_type_ref(context, expr_type));
}

static bool inferred_expr_type_is_void(InferredExprType expr_type) {
    return expr_type.kind == FENG_INFERRED_EXPR_TYPE_BUILTIN &&
           slice_equals_cstr(expr_type.builtin_name, "void");
}

static bool function_type_decl_return_matches_inferred_type(const ResolveContext *context,
                                                            const FengTypeRef *function_type_ref,
                                                            const FengDecl *function_type_decl,
                                                            InferredExprType return_type) {
    const FengTypeRef *expected_return_type;

    if (!decl_is_function_type(function_type_decl) ||
        !inferred_expr_type_is_known(return_type)) {
        return false;
    }

    expected_return_type = function_type_decl->as.spec_decl.as.callable.return_type;
    expected_return_type = substitute_spec_member_type_ref_for_instance(
        (ResolveContext *)context,
        function_type_decl,
        function_type_ref,
        expected_return_type);
    if (expected_return_type == NULL || type_ref_is_void(expected_return_type)) {
        return inferred_expr_type_is_void(return_type);
    }

    return inferred_expr_type_matches_type_ref(context, return_type, expected_return_type);
}

/* Compare callable-shape modifiers that remain distinct after parameter type
 * normalization. `T...` is stored as `T[]`, so the variadic marker must be
 * checked alongside the substituted parameter type at every signature site. */
static bool callable_parameter_forms_match(const FengParameter *left,
                                           const FengParameter *right) {
    return left != NULL && right != NULL &&
           left->is_variadic == right->is_variadic;
}

/* Callable-form signature equality helper. Callers decide whether an exact
 * signature match enables implicit coercion or only explicit casts. */
static bool function_type_refs_have_equal_signature(const ResolveContext *context,
                                                    const FengTypeRef *src_ref,
                                                    const FengTypeRef *dst_ref) {
    const FengDecl *src_decl;
    const FengDecl *dst_decl;
    size_t i;

    if (src_ref == NULL || dst_ref == NULL) {
        return false;
    }
    src_decl = resolve_type_ref_decl(context, src_ref);
    dst_decl = resolve_type_ref_decl(context, dst_ref);
    if (!decl_is_function_type(src_decl) || !decl_is_function_type(dst_decl)) {
        return false;
    }
    if (src_decl->as.spec_decl.as.callable.param_count !=
        dst_decl->as.spec_decl.as.callable.param_count) {
        return false;
    }
    for (i = 0U; i < src_decl->as.spec_decl.as.callable.param_count; ++i) {
        const FengParameter *src_decl_param =
            &src_decl->as.spec_decl.as.callable.params[i];
        const FengParameter *dst_decl_param =
            &dst_decl->as.spec_decl.as.callable.params[i];
        const FengTypeRef *src_param = substitute_spec_member_type_ref_for_instance(
            (ResolveContext *)context,
            src_decl,
            src_ref,
            src_decl_param->type);
        const FengTypeRef *dst_param = substitute_spec_member_type_ref_for_instance(
            (ResolveContext *)context,
            dst_decl,
            dst_ref,
            dst_decl_param->type);

        if (!callable_parameter_forms_match(src_decl_param, dst_decl_param) ||
            !type_refs_semantically_equal(context, src_param, dst_param)) {
            return false;
        }
    }

    {
        const FengTypeRef *src_ret = substitute_spec_member_type_ref_for_instance(
            (ResolveContext *)context,
            src_decl,
            src_ref,
            src_decl->as.spec_decl.as.callable.return_type);
        const FengTypeRef *dst_ret = substitute_spec_member_type_ref_for_instance(
            (ResolveContext *)context,
            dst_decl,
            dst_ref,
            dst_decl->as.spec_decl.as.callable.return_type);

        return type_refs_semantically_equal(context, src_ret, dst_ret);
    }
}

static bool function_type_decl_matches_callable_signature(const ResolveContext *context,
                                                          const FengTypeRef *function_type_ref,
                                                          const FengDecl *function_type_decl,
                                                          const FengCallableSignature *callable) {
    size_t param_index;

    if (function_type_decl == NULL || callable == NULL ||
        !decl_is_function_type(function_type_decl)) {
        return false;
    }
    if (function_type_decl->as.spec_decl.as.callable.param_count != callable->param_count) {
        return false;
    }

    for (param_index = 0U;
         param_index < function_type_decl->as.spec_decl.as.callable.param_count;
         ++param_index) {
        const FengParameter *expected_decl_param =
            &function_type_decl->as.spec_decl.as.callable.params[param_index];
        const FengParameter *actual_decl_param = &callable->params[param_index];
        const FengTypeRef *expected_param = substitute_spec_member_type_ref_for_instance(
            (ResolveContext *)context,
            function_type_decl,
            function_type_ref,
            expected_decl_param->type);

        if (!callable_parameter_forms_match(expected_decl_param,
                                            actual_decl_param) ||
            !type_refs_semantically_equal(context,
                                          expected_param,
                                          actual_decl_param->type)) {
            return false;
        }
    }

    return function_type_decl_return_matches_inferred_type(
        context, function_type_ref, function_type_decl,
        callable_effective_return_type(context, callable));
}

static bool function_type_decl_matches_callable_signature_or_is_pending(
    ResolveContext *context,
    const FengTypeRef *function_type_ref,
    const FengDecl *function_type_decl,
    const FengCallableSignature *callable) {
    size_t param_index;

    if (function_type_decl_matches_callable_signature(
            context, function_type_ref, function_type_decl, callable)) {
        return true;
    }

    if (function_type_decl == NULL || callable == NULL ||
        !decl_is_function_type(function_type_decl)) {
        return false;
    }
    if (function_type_decl->as.spec_decl.as.callable.param_count != callable->param_count) {
        return false;
    }

    for (param_index = 0U;
         param_index < function_type_decl->as.spec_decl.as.callable.param_count;
         ++param_index) {
        const FengParameter *expected_decl_param =
            &function_type_decl->as.spec_decl.as.callable.params[param_index];
        const FengParameter *actual_decl_param = &callable->params[param_index];
        const FengTypeRef *expected_param = substitute_spec_member_type_ref_for_instance(
            context,
            function_type_decl,
            function_type_ref,
            expected_decl_param->type);

        if (!callable_parameter_forms_match(expected_decl_param,
                                            actual_decl_param) ||
            !type_refs_semantically_equal(context,
                                          expected_param,
                                          actual_decl_param->type)) {
            return false;
        }
    }

    return callable_return_inference_is_pending(context, callable);
}

/* Returns the canonical builtin name for an inferred expression type.
 * `pointer_size` is forwarded to canonical_builtin_type_name() so that
 * platform-dependent aliases (e.g. `int`) resolve to the correct width.
 * See docs/engineering/feng-scalar-alias-optimize.md §6.8. */
static const char *inferred_expr_type_builtin_canonical_name(InferredExprType expr_type, size_t pointer_size) {
    switch (expr_type.kind) {
        case FENG_INFERRED_EXPR_TYPE_BUILTIN:
            return canonical_builtin_type_name(expr_type.builtin_name, pointer_size);

        case FENG_INFERRED_EXPR_TYPE_TYPE_REF:
            return type_ref_builtin_canonical_name(expr_type.type_ref, pointer_size);

        case FENG_INFERRED_EXPR_TYPE_DECL:
        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
            return NULL;
    }

    return NULL;
}

static bool inferred_expr_type_is_numeric(InferredExprType expr_type) {
    /* 位宽无关，传入 0 各平台均逻辑正常，性能无损 */
    const char *builtin_name = inferred_expr_type_builtin_canonical_name(expr_type, 0U);

    return builtin_name != NULL && builtin_type_name_is_numeric(slice_from_cstr(builtin_name));
}

static bool inferred_expr_type_is_enum(const ResolveContext *context, InferredExprType expr_type) {
    const FengDecl *type_decl;

    switch (expr_type.kind) {
        case FENG_INFERRED_EXPR_TYPE_DECL:
            return decl_is_enum_type(expr_type.type_decl);

        case FENG_INFERRED_EXPR_TYPE_TYPE_REF:
            type_decl = resolve_type_ref_decl(context, expr_type.type_ref);
            return decl_is_enum_type(type_decl);

        case FENG_INFERRED_EXPR_TYPE_BUILTIN:
        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
            return false;
    }

    return false;
}

static bool inferred_expr_type_is_integer(InferredExprType expr_type) {
    /* 位宽无关，传入 0 各平台均逻辑正常，性能无损 */
    const char *builtin_name = inferred_expr_type_builtin_canonical_name(expr_type, 0U);

    return builtin_name != NULL && builtin_type_name_is_integer(slice_from_cstr(builtin_name));
}

static bool inferred_expr_type_is_float(InferredExprType expr_type) {
    return inferred_expr_type_is_numeric(expr_type) &&
           !inferred_expr_type_is_integer(expr_type);
}

static bool inferred_expr_type_is_bool(InferredExprType expr_type) {
    /* 位宽无关，传入 0 各平台均逻辑正常，性能无损 */
    const char *builtin_name = inferred_expr_type_builtin_canonical_name(expr_type, 0U);

    return builtin_name != NULL && strcmp(builtin_name, "bool") == 0;
}

static bool inferred_expr_type_is_string(InferredExprType expr_type) {
    /* 位宽无关，传入 0 各平台均逻辑正常，性能无损 */
    const char *builtin_name = inferred_expr_type_builtin_canonical_name(expr_type, 0U);

    return builtin_name != NULL && strcmp(builtin_name, "string") == 0;
}

static bool type_decl_has_field_members(const FengDecl *decl) {
    size_t member_index;

    if (decl == NULL || decl->kind != FENG_DECL_TYPE) {
        return false;
    }

    for (member_index = 0U; member_index < decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = decl->as.type_decl.members[member_index];

        if (member != NULL && member->kind == FENG_TYPE_MEMBER_FIELD) {
            return true;
        }
    }

    return false;
}

static bool inferred_expr_type_is_data_addressable_abi_value(const ResolveContext *context,
                                                             InferredExprType expr_type) {
    const char *builtin_name;
    const FengDecl *type_decl;

    switch (expr_type.kind) {
        case FENG_INFERRED_EXPR_TYPE_BUILTIN:
            builtin_name = canonical_builtin_type_name(expr_type.builtin_name, context->pointer_size);
            return builtin_name != NULL && strcmp(builtin_name, "string") != 0 &&
                   strcmp(builtin_name, "void") != 0;

        case FENG_INFERRED_EXPR_TYPE_TYPE_REF:
            if (expr_type.type_ref == NULL) {
                return false;
            }
            builtin_name = type_ref_builtin_canonical_name(expr_type.type_ref, context->pointer_size);
            if (builtin_name != NULL) {
                return strcmp(builtin_name, "string") != 0 && strcmp(builtin_name, "void") != 0;
            }
            if (expr_type.type_ref->kind != FENG_TYPE_REF_NAMED) {
                return false;
            }
            type_decl = resolve_type_ref_decl(context, expr_type.type_ref);
            if (decl_is_enum_type(type_decl)) {
                return true;
            }
            return type_decl != NULL && type_decl->kind == FENG_DECL_TYPE &&
                   type_decl_has_field_members(type_decl) &&
                   type_decl_is_abi_stable(context, type_decl, NULL);

        case FENG_INFERRED_EXPR_TYPE_DECL:
            if (decl_is_enum_type(expr_type.type_decl)) {
                return true;
            }
            return expr_type.type_decl != NULL && expr_type.type_decl->kind == FENG_DECL_TYPE &&
                   type_decl_has_field_members(expr_type.type_decl) &&
                   type_decl_is_abi_stable(context, expr_type.type_decl, NULL);

        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
            return false;
    }

    return false;
}

static bool inferred_expr_type_is_abi_array_value(const ResolveContext *context,
                                                  InferredExprType expr_type) {
    return expr_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
           expr_type.type_ref != NULL &&
           type_ref_is_abi_compatible_array(context, expr_type.type_ref, NULL);
}

static const char *format_operator_name(FengTokenKind kind) {
    switch (kind) {
        case FENG_TOKEN_PLUS:
            return "+";
        case FENG_TOKEN_MINUS:
            return "-";
        case FENG_TOKEN_STAR:
            return "*";
        case FENG_TOKEN_SLASH:
            return "/";
        case FENG_TOKEN_PERCENT:
            return "%";
        case FENG_TOKEN_PLUS_ASSIGN:
            return "+=";
        case FENG_TOKEN_MINUS_ASSIGN:
            return "-=";
        case FENG_TOKEN_STAR_ASSIGN:
            return "*=";
        case FENG_TOKEN_SLASH_ASSIGN:
            return "/=";
        case FENG_TOKEN_PERCENT_ASSIGN:
            return "%=";
        case FENG_TOKEN_NOT:
            return "!";
        case FENG_TOKEN_TILDE:
            return "~";
        case FENG_TOKEN_LT:
            return "<";
        case FENG_TOKEN_LE:
            return "<=";
        case FENG_TOKEN_GT:
            return ">";
        case FENG_TOKEN_GE:
            return ">=";
        case FENG_TOKEN_EQ:
            return "==";
        case FENG_TOKEN_NE:
            return "!=";
        case FENG_TOKEN_AND_AND:
            return "&&";
        case FENG_TOKEN_OR_OR:
            return "||";
        case FENG_TOKEN_AMP:
            return "&";
        case FENG_TOKEN_AMP_ASSIGN:
            return "&=";
        case FENG_TOKEN_PIPE:
            return "|";
        case FENG_TOKEN_PIPE_ASSIGN:
            return "|=";
        case FENG_TOKEN_CARET:
            return "^";
        case FENG_TOKEN_CARET_ASSIGN:
            return "^=";
        case FENG_TOKEN_SHL:
            return "<<";
        case FENG_TOKEN_SHL_ASSIGN:
            return "<<=";
        case FENG_TOKEN_SHR:
            return ">>";
        case FENG_TOKEN_SHR_ASSIGN:
            return ">>=";
        default:
            return "?";
    }
}

static FengTokenKind assignment_operator_binary_operator(FengTokenKind op) {
    switch (op) {
        case FENG_TOKEN_PLUS_ASSIGN:
            return FENG_TOKEN_PLUS;
        case FENG_TOKEN_MINUS_ASSIGN:
            return FENG_TOKEN_MINUS;
        case FENG_TOKEN_STAR_ASSIGN:
            return FENG_TOKEN_STAR;
        case FENG_TOKEN_SLASH_ASSIGN:
            return FENG_TOKEN_SLASH;
        case FENG_TOKEN_PERCENT_ASSIGN:
            return FENG_TOKEN_PERCENT;
        case FENG_TOKEN_AMP_ASSIGN:
            return FENG_TOKEN_AMP;
        case FENG_TOKEN_PIPE_ASSIGN:
            return FENG_TOKEN_PIPE;
        case FENG_TOKEN_CARET_ASSIGN:
            return FENG_TOKEN_CARET;
        case FENG_TOKEN_SHL_ASSIGN:
            return FENG_TOKEN_SHL;
        case FENG_TOKEN_SHR_ASSIGN:
            return FENG_TOKEN_SHR;
        default:
            return FENG_TOKEN_ERROR;
    }
}

static bool assignment_operator_is_numeric_compound(FengTokenKind op) {
    switch (op) {
        case FENG_TOKEN_PLUS_ASSIGN:
        case FENG_TOKEN_MINUS_ASSIGN:
        case FENG_TOKEN_STAR_ASSIGN:
        case FENG_TOKEN_SLASH_ASSIGN:
        case FENG_TOKEN_PERCENT_ASSIGN:
            return true;
        default:
            return false;
    }
}

static bool assignment_operator_is_bitwise_compound(FengTokenKind op) {
    switch (op) {
        case FENG_TOKEN_AMP_ASSIGN:
        case FENG_TOKEN_PIPE_ASSIGN:
        case FENG_TOKEN_CARET_ASSIGN:
        case FENG_TOKEN_SHL_ASSIGN:
        case FENG_TOKEN_SHR_ASSIGN:
            return true;
        default:
            return false;
    }
}

static bool unary_expr_type_is_valid(FengTokenKind op, InferredExprType operand_type) {
    switch (op) {
        case FENG_TOKEN_MINUS:
            return inferred_expr_type_is_numeric(operand_type);

        case FENG_TOKEN_NOT:
            return inferred_expr_type_is_bool(operand_type);

        case FENG_TOKEN_TILDE:
            return inferred_expr_type_is_integer(operand_type);

        default:
            return false;
    }
}

static bool binary_expr_types_are_valid(ResolveContext *context,
                                        FengTokenKind op,
                                        InferredExprType left_type,
                                        InferredExprType right_type) {
    switch (op) {
        case FENG_TOKEN_PLUS:
            return inferred_expr_types_equal(context, left_type, right_type) &&
                   (inferred_expr_type_is_numeric(left_type) || inferred_expr_type_is_string(left_type));

        case FENG_TOKEN_MINUS:
        case FENG_TOKEN_STAR:
        case FENG_TOKEN_SLASH:
        case FENG_TOKEN_PERCENT:
            return inferred_expr_types_equal(context, left_type, right_type) &&
                   inferred_expr_type_is_numeric(left_type);

        case FENG_TOKEN_LT:
        case FENG_TOKEN_LE:
        case FENG_TOKEN_GT:
        case FENG_TOKEN_GE:
            return inferred_expr_types_equal(context, left_type, right_type) &&
                   inferred_expr_type_is_numeric(left_type);

        case FENG_TOKEN_EQ:
        case FENG_TOKEN_NE:
            return inferred_expr_type_is_known(left_type) &&
                   inferred_expr_type_is_known(right_type) &&
                   inferred_expr_types_equal(context, left_type, right_type);

        case FENG_TOKEN_AND_AND:
        case FENG_TOKEN_OR_OR:
            return inferred_expr_type_is_bool(left_type) && inferred_expr_type_is_bool(right_type);

        case FENG_TOKEN_AMP:
        case FENG_TOKEN_PIPE:
        case FENG_TOKEN_CARET:
        case FENG_TOKEN_SHL:
        case FENG_TOKEN_SHR:
            return inferred_expr_types_equal(context, left_type, right_type) &&
                   inferred_expr_type_is_integer(left_type);

        default:
            return false;
    }
}

static bool expr_is_top_level_function_reference(ResolveContext *context, const FengExpr *expr) {
    if (context == NULL || expr == NULL) {
        return false;
    }

    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER:
            return resolver_find_local_name_entry(context, expr->as.identifier) == NULL &&
                   find_function_overload_set(context->function_sets,
                                              context->function_set_count,
                                              expr->as.identifier) != NULL;

        case FENG_EXPR_MEMBER:
            {
                ResolvedModuleMemberTarget target;

                return resolve_module_member_target(context, expr, &target) &&
                       find_module_public_function_decl(target.module,
                                                        target.member_name) != NULL;
            }

        default:
            return false;
    }
}

static bool expr_is_callable_like_address_of_operand(ResolveContext *context,
                                                     const FengExpr *expr,
                                                     InferredExprType operand_type) {
    if (expr == NULL) {
        return false;
    }

    if (expr_is_top_level_function_reference(context, expr) || expr->kind == FENG_EXPR_LAMBDA ||
        classify_callable_source(context, expr) ==
            FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE) {
        return true;
    }

    return operand_type.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA ||
           (operand_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
            resolve_function_type_decl(context, operand_type.type_ref) != NULL);
}

static bool validate_unary_expr(ResolveContext *context, const FengExpr *expr) {
    InferredExprType operand_type;
    const char *operator_name;
    char *operand_type_name;
    char *message;

    if (expr->as.unary.op == FENG_TOKEN_AMP) {
        operand_type = infer_expr_type(context, expr->as.unary.operand);
        if (inferred_expr_type_is_data_addressable_abi_value(context, operand_type) ||
            inferred_expr_type_is_string(operand_type) ||
            inferred_expr_type_is_abi_array_value(context, operand_type) ||
            expr_is_callable_like_address_of_operand(context,
                                                    expr->as.unary.operand,
                                                    operand_type)) {
            return true;
        }

        operand_type_name = format_inferred_expr_type_name(operand_type, context->pointer_size);
        message = format_message(
            "unary operator '&' requires an ABI-compatible scalar or @abi value, a string, an ABI-compatible array, or a top-level @abi function, got '%s'",
            operand_type_name != NULL ? operand_type_name : "<unknown>");
        free(operand_type_name);
        return resolver_append_error(context, expr->token, "AE0018", message);
    }

    operand_type = infer_expr_type(context, expr->as.unary.operand);
    if (unary_expr_type_is_valid(expr->as.unary.op, operand_type)) {
        return true;
    }

    operator_name = format_operator_name(expr->as.unary.op);
    operand_type_name = format_inferred_expr_type_name(operand_type, context->pointer_size);
    {
        const char *fmt;

        switch (expr->as.unary.op) {
            case FENG_TOKEN_MINUS:
                fmt = "unary operator '%s' requires a numeric operand, got '%s'";
                break;
            case FENG_TOKEN_TILDE:
                fmt = "unary operator '%s' requires an integer operand, got '%s'";
                break;
            case FENG_TOKEN_NOT:
            default:
                fmt = "unary operator '%s' requires a bool operand, got '%s'";
                break;
        }
        message = format_message(fmt,
                                 operator_name,
                                 operand_type_name != NULL ? operand_type_name : "<unknown>");
    }
    free(operand_type_name);
    return resolver_append_error(context, expr->token, "AE1018", message);
}

static int canonical_integer_bit_width(const char *canonical_name) {
    if (canonical_name == NULL) {
        return 0;
    }
    if (strcmp(canonical_name, "i8") == 0 || strcmp(canonical_name, "u8") == 0) {
        return 8;
    }
    if (strcmp(canonical_name, "i16") == 0 || strcmp(canonical_name, "u16") == 0) {
        return 16;
    }
    if (strcmp(canonical_name, "i32") == 0 || strcmp(canonical_name, "u32") == 0) {
        return 32;
    }
    if (strcmp(canonical_name, "i64") == 0 || strcmp(canonical_name, "u64") == 0) {
        return 64;
    }
    return 0;
}

static bool validate_integer_shift_rhs_range(ResolveContext *context,
                                             FengToken anchor,
                                             InferredExprType left_type,
                                             const FengExpr *right_expr) {
    FengConstValue shift_value;

    if (!evaluate_constant_expr(context, right_expr, &shift_value) ||
        shift_value.kind != FENG_CONST_INT) {
        return true;
    }

    int64_t shift_amount = shift_value.i;
    int bit_width = canonical_integer_bit_width(
        inferred_expr_type_builtin_canonical_name(left_type, context->pointer_size));

    if (bit_width <= 0 ||
        (shift_amount >= 0 && shift_amount < (int64_t)bit_width)) {
        return true;
    }

    char *lt_name = format_inferred_expr_type_name(left_type, context->pointer_size);
    char *msg = format_message(
        "shift amount %lld is out of range for type '%s' (must be in [0, %d))",
        (long long)shift_amount,
        lt_name != NULL ? lt_name : "<unknown>",
        bit_width);

    free(lt_name);
    return resolver_append_error(context, anchor, "AE0019", msg);
}

static bool validate_division_or_modulo_rhs_zero(ResolveContext *context,
                                                 FengToken anchor,
                                                 FengTokenKind op,
                                                 InferredExprType left_type,
                                                 InferredExprType right_type,
                                                 const FengExpr *right_expr,
                                                 const char *context_label) {
    FengConstValue rhs_value;
    const char *kind_word;

    if (!evaluate_constant_expr(context, right_expr, &rhs_value)) {
        return true;
    }

    if (op == FENG_TOKEN_SLASH &&
        inferred_expr_type_is_integer(left_type) &&
        inferred_expr_type_is_integer(right_type) &&
        rhs_value.kind == FENG_CONST_INT && rhs_value.i == 0) {
        kind_word = "division";
    } else if (op == FENG_TOKEN_PERCENT &&
               inferred_expr_type_is_integer(left_type) &&
               inferred_expr_type_is_integer(right_type) &&
               rhs_value.kind == FENG_CONST_INT && rhs_value.i == 0) {
        kind_word = "modulo";
    } else if (op == FENG_TOKEN_PERCENT &&
               inferred_expr_type_is_float(left_type) &&
               inferred_expr_type_is_float(right_type) &&
               rhs_value.kind == FENG_CONST_FLOAT && rhs_value.f == 0.0) {
        kind_word = "modulo";
    } else {
        return true;
    }

    return resolver_append_error(
        context,
        anchor,
        "AE1001", format_message("%s by zero in %s '%s' expression",
                       kind_word,
                       context_label,
                       format_operator_name(op)));
}

static bool validate_compound_assignment(ResolveContext *context, const FengStmt *stmt) {
    InferredExprType left_type = infer_expr_type(context, stmt->as.assign.target);
    InferredExprType right_type = infer_expr_type(context, stmt->as.assign.value);
    FengTokenKind binary_op = assignment_operator_binary_operator(stmt->as.assign.op);
    const char *operator_name = format_operator_name(stmt->as.assign.op);
    char *left_type_name;
    char *right_type_name;
    char *message;

    if (binary_op == FENG_TOKEN_ERROR) {
        return resolver_append_error(context,
                                     stmt->token,
                                     "AE1002", format_message("unsupported compound assignment operator '%s'",
                                                    operator_name));
    }

    /* Compound-assignment literal adaptation: when the right-hand side is a
     * pure numeric literal and the left-hand side has a resolved scalar type,
     * adapt the literal to that type.  The result is hung on the literal
     * node's type field for codegen to read directly.  Adaptation failure
     * (out-of-range) keeps the default inferred type, so the subsequent
     * equality check reports a type-mismatch error as designed. */
    if (expr_is_pure_numeric_literal_expr_for_target_adaptation(stmt->as.assign.value) &&
        inferred_expr_type_is_numeric(left_type)) {
        if (numeric_literal_fits_inferred_target(context, stmt->as.assign.value, left_type)) {
            FengTypeRef *synth = create_type_ref_from_inferred_type(&left_type,
                                                                    stmt->as.assign.value->token);
            if (synth != NULL) {
                FengTypeRef *clone = clone_type_ref_for_inference(synth);
                free_synthetic_type_ref(synth);
                if (clone != NULL &&
                    analysis_track_synthetic_type_ref(context->analysis, clone)) {
                    ((FengExpr *)stmt->as.assign.value)->type = clone;
                } else {
                    free_synthetic_type_ref(clone);
                }
            }
            right_type = left_type;
        }
    }

    if (assignment_operator_is_numeric_compound(stmt->as.assign.op) &&
        inferred_expr_types_equal(context, left_type, right_type) &&
        inferred_expr_type_is_numeric(left_type)) {
        if ((binary_op == FENG_TOKEN_SHL || binary_op == FENG_TOKEN_SHR) &&
            !validate_integer_shift_rhs_range(context,
                                              stmt->token,
                                              left_type,
                                              stmt->as.assign.value)) {
            return false;
        }
        return validate_division_or_modulo_rhs_zero(context,
                                                    stmt->token,
                                                    binary_op,
                                                    left_type,
                                                    right_type,
                                                    stmt->as.assign.value,
                                                    "compile-time compound");
    }

    if (assignment_operator_is_bitwise_compound(stmt->as.assign.op) &&
        inferred_expr_types_equal(context, left_type, right_type) &&
        inferred_expr_type_is_integer(left_type)) {
        if (binary_op == FENG_TOKEN_SHL || binary_op == FENG_TOKEN_SHR) {
            return validate_integer_shift_rhs_range(context,
                                                    stmt->token,
                                                    left_type,
                                                    stmt->as.assign.value);
        }
        return true;
    }

    left_type_name = format_inferred_expr_type_name(left_type, context->pointer_size);
    right_type_name = format_inferred_expr_type_name(right_type, context->pointer_size);

    if (assignment_operator_is_numeric_compound(stmt->as.assign.op)) {
        message = format_message(
            "compound assignment operator '%s' requires operands of the same numeric type, got '%s' and '%s'",
            operator_name,
            left_type_name != NULL ? left_type_name : "<unknown>",
            right_type_name != NULL ? right_type_name : "<unknown>");
    } else {
        message = format_message(
            "compound assignment operator '%s' requires operands of the same integer type, got '%s' and '%s'",
            operator_name,
            left_type_name != NULL ? left_type_name : "<unknown>",
            right_type_name != NULL ? right_type_name : "<unknown>");
    }

    free(left_type_name);
    free(right_type_name);
    return resolver_append_error(context, stmt->token, "AE1020", message);
}

static bool validate_binary_expr(ResolveContext *context, const FengExpr *expr) {
    /* Read the derivation result filled by the prior infer_expr_type pass in
     * resolve_expr's binary branch.  This keeps validate_binary_expr pure —
     * no infer_expr_type calls — so derivation and validation are two
     * independent functions, each doing one job.  NULL operands or NULL
     * expr->type yield UNKNOWN, which binary_expr_types_are_valid rejects. */
    InferredExprType left_type =
        (expr->as.binary.left != NULL && expr->as.binary.left->type != NULL)
            ? inferred_expr_type_from_type_ref(expr->as.binary.left->type)
            : inferred_expr_type_unknown();
    InferredExprType right_type =
        (expr->as.binary.right != NULL && expr->as.binary.right->type != NULL)
            ? inferred_expr_type_from_type_ref(expr->as.binary.right->type)
            : inferred_expr_type_unknown();
    const char *operator_name = format_operator_name(expr->as.binary.op);
    char *left_type_name;
    char *right_type_name;
    char *message;

    if ((expr->as.binary.op == FENG_TOKEN_EQ || expr->as.binary.op == FENG_TOKEN_NE) &&
        (inferred_expr_type_is_union_view(context, left_type) ||
         inferred_expr_type_is_union_view(context, right_type))) {
        return resolver_append_error(
            context,
            expr->token,
            "AE0604", format_message("binary operator '%s' requires union-form operands to be narrowed to a single member first",
                           operator_name));
    }

    if (binary_expr_types_are_valid(context, expr->as.binary.op, left_type, right_type)) {
        if (expr->as.binary.op == FENG_TOKEN_SHL || expr->as.binary.op == FENG_TOKEN_SHR) {
            return validate_integer_shift_rhs_range(context,
                                                    expr->token,
                                                    left_type,
                                                    expr->as.binary.right);
        }
        return validate_division_or_modulo_rhs_zero(context,
                                                    expr->token,
                                                    expr->as.binary.op,
                                                    left_type,
                                                    right_type,
                                                    expr->as.binary.right,
                                                    "compile-time");
    }

    left_type_name = format_inferred_expr_type_name(left_type, context->pointer_size);
    right_type_name = format_inferred_expr_type_name(right_type, context->pointer_size);

    switch (expr->as.binary.op) {
        case FENG_TOKEN_PLUS:
            message = format_message(
                "binary operator '%s' requires operands of the same numeric or string type, got '%s' and '%s'",
                operator_name,
                left_type_name != NULL ? left_type_name : "<unknown>",
                right_type_name != NULL ? right_type_name : "<unknown>");
            break;

        case FENG_TOKEN_MINUS:
        case FENG_TOKEN_STAR:
        case FENG_TOKEN_SLASH:
        case FENG_TOKEN_PERCENT:
        case FENG_TOKEN_LT:
        case FENG_TOKEN_LE:
        case FENG_TOKEN_GT:
        case FENG_TOKEN_GE:
            message = format_message(
                "binary operator '%s' requires operands of the same numeric type, got '%s' and '%s'",
                operator_name,
                left_type_name != NULL ? left_type_name : "<unknown>",
                right_type_name != NULL ? right_type_name : "<unknown>");
            break;

        case FENG_TOKEN_EQ:
        case FENG_TOKEN_NE:
            message = format_message("binary operator '%s' requires operands of the same type, got '%s' and '%s'",
                                     operator_name,
                                     left_type_name != NULL ? left_type_name : "<unknown>",
                                     right_type_name != NULL ? right_type_name : "<unknown>");
            break;

        case FENG_TOKEN_AND_AND:
        case FENG_TOKEN_OR_OR:
            message = format_message("binary operator '%s' requires bool operands, got '%s' and '%s'",
                                     operator_name,
                                     left_type_name != NULL ? left_type_name : "<unknown>",
                                     right_type_name != NULL ? right_type_name : "<unknown>");
            break;

        case FENG_TOKEN_AMP:
        case FENG_TOKEN_PIPE:
        case FENG_TOKEN_CARET:
        case FENG_TOKEN_SHL:
        case FENG_TOKEN_SHR:
            message = format_message(
                "binary operator '%s' requires operands of the same integer type, got '%s' and '%s'",
                operator_name,
                left_type_name != NULL ? left_type_name : "<unknown>",
                right_type_name != NULL ? right_type_name : "<unknown>");
            break;

        default:
            message = format_message("binary operator '%s' is not supported in this context",
                                     operator_name);
            break;
    }

    free(left_type_name);
    free(right_type_name);
    return resolver_append_error(context, expr->token, "AE1019", message);
}

static const FengExpr *block_yield_expression(const FengBlock *block) {
    FengSemanticResultBlockFlow flow;

    flow = feng_semantic_classify_result_block(block);
    return flow.kind == FENG_SEMANTIC_RESULT_BLOCK_VALUE
               ? flow.result_expr
               : NULL;
}

static bool block_exits_via_return_or_throw(const FengBlock *block) {
    return feng_semantic_classify_result_block(block).kind ==
           FENG_SEMANTIC_RESULT_BLOCK_RETURN_OR_THROW;
}

static InferredExprType block_yield_inferred_type(ResolveContext *context, const FengBlock *block) {
    const FengExpr *yield = block_yield_expression(block);

    return yield != NULL ? infer_expr_type(context, yield) : inferred_expr_type_unknown();
}

static bool validate_block_yields_expression(ResolveContext *context,
                                             const FengBlock *block,
                                             FengToken anchor,
                                             const char *ctx_label) {
    if (block_yield_expression(block) != NULL) {
        return true;
    }
    /* A block whose reachable paths all return from the owning callable or
     * escape through throw needs no branch-result value. */
    if (block_exits_via_return_or_throw(block)) {
        return true;
    }
    return resolver_append_error(
        context,
        anchor,
        "AE1101", format_message(
            "%s branch block must end with an expression statement on every normally completing path, or every reachable path must exit through return/throw",
            ctx_label));
}

/* Check a previously evaluated numeric constant against one concrete target.
 * Keeping this predicate shared prevents scalar and union targets from
 * acquiring different literal-adaptation rules. */
static bool numeric_const_value_adapts_to_target(const ResolveContext *context,
                                                 FengConstValue value,
                                                 const FengTypeRef *target) {
    const char *canonical_target;
    bool target_is_float;

    if (context == NULL || target == NULL) {
        return false;
    }
    canonical_target =
        type_ref_builtin_canonical_name(target, context->pointer_size);
    if (canonical_target == NULL) {
        return false;
    }
    target_is_float = strcmp(canonical_target, "f32") == 0 ||
                      strcmp(canonical_target, "f64") == 0;
    if (value.kind == FENG_CONST_INT) {
        return target_is_float ||
               integer_literal_fits_canonical_target(value.i,
                                                     canonical_target);
    }
    if (value.kind == FENG_CONST_FLOAT) {
        return target_is_float;
    }
    return false;
}

/* Select the first union member to which a pure numeric literal can adapt.
 * The returned type ref is borrowed from declaration or resolver storage and
 * is suitable for immediate matching or persistence. */
static const FengTypeRef *select_literal_expr_union_member_target(
    ResolveContext *context,
    const FengExpr *literal_expr,
    const FengDecl *union_decl,
    const FengTypeRef *union_type_ref) {
    const FengUnionSpecInfo *info = feng_semantic_lookup_union_spec_info(context->analysis,
                                                                         union_decl);
    FengConstValue value;
    bool evaluated;

    if (info == NULL || literal_expr == NULL) {
        return NULL;
    }
    evaluated = evaluate_constant_expr(context, literal_expr, &value);
    if (!evaluated || (value.kind != FENG_CONST_INT && value.kind != FENG_CONST_FLOAT)) {
        return NULL;
    }
    for (size_t index = 0U; index < info->member_count; ++index) {
        const FengTypeRef *declared_member_type_ref = info->members[index].type_ref;
        const FengTypeRef *member_type_ref = substitute_spec_member_type_ref_for_instance(
            context, union_decl, union_type_ref, declared_member_type_ref);
        if (!numeric_const_value_adapts_to_target(context,
                                                  value,
                                                  member_type_ref)) {
            continue;
        }
        return member_type_ref;
    }
    return NULL;
}

/* Select the first non-literal branch with a known type as the implicit
 * target.  A NULL result means that all value-producing branches are numeric
 * literals (or otherwise have no known type), so each branch must retain its
 * default inference and the caller must perform the ordinary equality check. */
static bool select_implicit_branch_result_target(
    ResolveContext *context,
    const FengExpr *const *results,
    size_t result_count,
    const FengTypeRef **out_target) {
    size_t index;

    if (out_target != NULL) {
        *out_target = NULL;
    }
    for (index = 0U; index < result_count; ++index) {
        InferredExprType result_type;
        FengTypeRef *target;

        if (results[index] == NULL ||
            expr_is_pure_numeric_literal_expr_for_target_adaptation(results[index])) {
            continue;
        }
        result_type = branch_result_inferred_type(context, results[index]);
        if (!inferred_expr_type_is_known(result_type)) {
            continue;
        }
        target = create_type_ref_from_inferred_type(&result_type,
                                                    results[index]->token);
        if (target == NULL) {
            continue;
        }
        if (!resolver_track_synthetic_type_ref(context, target)) {
            free_synthetic_type_ref(target);
            return false;
        }
        if (out_target != NULL) {
            *out_target = target;
        }
        return true;
    }
    return true;
}

/* Fit every value-producing branch to one explicit or implicitly selected
 * target.  Matching is checked for the complete set before coercions are
 * committed, so an invalid expression cannot leave partially recorded branch
 * conversions.  When no implicit target exists (the all-literal case), the
 * caller retains default inference and performs its existing equality check. */
static bool fit_branch_results_to_target(ResolveContext *context,
                                         const FengExpr *branching_expr,
                                         const FengExpr *const *results,
                                         size_t result_count,
                                         const FengTypeRef *explicit_target,
                                         bool *out_all_conform) {
    const FengTypeRef *target = explicit_target;
    size_t index;
    bool previous_suppress_commit;

    if (out_all_conform != NULL) {
        *out_all_conform = false;
    }
    if (result_count == 0U) {
        if (out_all_conform != NULL) {
            *out_all_conform = true;
        }
        return true;
    }
    if (target == NULL &&
        !select_implicit_branch_result_target(context,
                                              results,
                                              result_count,
                                              &target)) {
        return false;
    }
    if (target == NULL) {
        return true;
    }

    previous_suppress_commit = context->suppress_literal_type_commit;
    context->suppress_literal_type_commit = true;
    for (index = 0U; index < result_count; ++index) {
        if (results[index] != NULL &&
            !expr_matches_expected_type_ref(context, results[index], target)) {
            context->suppress_literal_type_commit = previous_suppress_commit;
            return true;
        }
    }
    context->suppress_literal_type_commit = previous_suppress_commit;
    for (index = 0U; index < result_count; ++index) {
        if (results[index] != NULL &&
            !validate_expr_against_expected_type(context, results[index], target)) {
            return false;
        }
    }
    if (!persist_branch_expression_type(context, branching_expr, target)) {
        return false;
    }
    if (out_all_conform != NULL) {
        *out_all_conform = true;
    }
    return true;
}

static bool validate_if_expr(ResolveContext *context, const FengExpr *expr) {
    InferredExprType condition_type = infer_expr_type(context, expr->as.if_expr.condition);
    InferredExprType then_type;
    InferredExprType else_type;

    if (!inferred_expr_type_is_bool(condition_type)) {
        char *condition_type_name = format_inferred_expr_type_name(condition_type, context->pointer_size);
        char *message = format_message("if expression condition must have type 'bool', got '%s'",
                                       condition_type_name != NULL ? condition_type_name : "<unknown>");

        free(condition_type_name);
        return resolver_append_error(
                   context,
                   expr->as.if_expr.condition->token,
                   "AE1102",
                   message) &&
               false;
    }

    if (expr->as.if_expr.else_block == NULL) {
        return resolver_append_error(
            context,
            expr->token,
            "AE1101", format_message("if expressions require an else branch"));
    }

    if (!validate_block_yields_expression(context,
                                          expr->as.if_expr.then_block,
                                          expr->token,
                                          "if expression then") ||
        !validate_block_yields_expression(context,
                                          expr->as.if_expr.else_block,
                                          expr->token,
                                          "if expression else")) {
        return false;
    }

    {
        const FengExpr *results[2];
        size_t result_count = 0U;
        bool all_results_conform = false;

        if (!block_exits_via_return_or_throw(expr->as.if_expr.then_block)) {
            results[result_count++] =
                block_yield_expression(expr->as.if_expr.then_block);
        }
        if (!block_exits_via_return_or_throw(expr->as.if_expr.else_block)) {
            results[result_count++] =
                block_yield_expression(expr->as.if_expr.else_block);
        }
        if (!fit_branch_results_to_target(
                context,
                expr,
                results,
                result_count,
                context->current_expr_expected_type_ref,
                &all_results_conform)) {
            return false;
        }
        if (all_results_conform) {
            return true;
        }
    }
    if (context->deferred_call_argument_target_depth > 0U) {
        return true;
    }

    {
        bool then_exits = block_exits_via_return_or_throw(expr->as.if_expr.then_block);
        bool else_exits = block_exits_via_return_or_throw(expr->as.if_expr.else_block);

        /* Return/throw-only branches never produce a result value, so they do
         * not participate in the type-consistency check. */
        if (then_exits || else_exits) {
            return true;
        }
    }

    then_type = branch_result_inferred_type(
        context, block_yield_expression(expr->as.if_expr.then_block));
    else_type = branch_result_inferred_type(
        context, block_yield_expression(expr->as.if_expr.else_block));

    if (inferred_expr_types_equal(context, then_type, else_type)) {
        return true;
    }

    {
        char *then_type_name = format_inferred_expr_type_name(then_type, context->pointer_size);
        char *else_type_name = format_inferred_expr_type_name(else_type, context->pointer_size);
        char *message = format_message("if expression branches must have the same type, got '%s' and '%s'",
                                       then_type_name != NULL ? then_type_name : "<unknown>",
                                       else_type_name != NULL ? else_type_name : "<unknown>");
        bool result;

        free(then_type_name);
        free(else_type_name);
        result = resolver_append_error(context, expr->token, "AE0034", message);
        if (result && context->current_expr_expected_type_ref != NULL) {
            result = persist_branch_expression_type(
                context, expr, context->current_expr_expected_type_ref);
        }
        return result;
    }
}

static bool validate_try_expr(ResolveContext *context,
                              const FengExpr *expr,
                              bool result_required) {
    InferredExprType body_type;
    const FengExpr **results;
    size_t result_count = 0U;
    bool all_results_conform = false;

    if (expr == NULL || expr->kind != FENG_EXPR_TRY ||
        expr->as.try_expr.clause_count == 0U || !result_required) {
        return true;
    }

    results = (const FengExpr **)calloc(expr->as.try_expr.clause_count + 1U,
                                        sizeof(*results));
    if (results == NULL) {
        return false;
    }
    results[result_count++] = expr->as.try_expr.body;
    for (size_t clause_index = 0U;
         clause_index < expr->as.try_expr.clause_count;
         ++clause_index) {
        const FengTryCatchClause *clause = &expr->as.try_expr.clauses[clause_index];
        const FengExpr *result_expr = block_yield_expression(clause->body);

        if (result_expr != NULL && !block_exits_via_return_or_throw(clause->body)) {
            results[result_count++] = result_expr;
        }
    }
    if (!fit_branch_results_to_target(context,
                                      expr,
                                      results,
                                      result_count,
                                      context->current_expr_expected_type_ref,
                                      &all_results_conform)) {
        free(results);
        return false;
    }
    free(results);
    if (all_results_conform) {
        return true;
    }
    if (context->deferred_call_argument_target_depth > 0U) {
        return true;
    }

    /* When fitting fails (or all results are literals without a target), keep
     * the established try diagnostic while comparing independently inferred
     * result types. */
    body_type = branch_result_inferred_type(context, expr->as.try_expr.body);

    for (size_t clause_index = 0U;
         clause_index < expr->as.try_expr.clause_count;
         ++clause_index) {
        const FengTryCatchClause *clause = &expr->as.try_expr.clauses[clause_index];
        const FengExpr *result_expr = block_yield_expression(clause->body);
        InferredExprType result_type;

        if (result_expr == NULL) {
            if (block_exits_via_return_or_throw(clause->body)) {
                continue;
            }
            if (inferred_expr_type_is_known(body_type) &&
                inferred_expr_type_is_void(body_type)) {
                continue;
            }
            (void)resolver_append_error(
                context,
                clause->token,
                "AE1401", format_message(
                    "catch clause must produce a final result expression on every normally completing path or exit every reachable path through return/throw"));
            return false;
        }

        result_type = branch_result_inferred_type(context, result_expr);
        if (inferred_expr_type_is_known(body_type) &&
            inferred_expr_type_is_known(result_type) &&
            !inferred_expr_types_equal(context, body_type, result_type)) {
            char *body_type_name = format_inferred_expr_type_name(body_type, context->pointer_size);
            char *result_type_name = format_inferred_expr_type_name(result_type, context->pointer_size);
            char *message = format_message(
                "catch clause result type '%s' does not match try expression type '%s'",
                result_type_name != NULL ? result_type_name : "<unknown>",
                body_type_name != NULL ? body_type_name : "<unknown>");

            free(body_type_name);
            free(result_type_name);
            (void)resolver_append_error(context, clause->token, "AE0036", message);
            return false;
        }
    }

    return true;
}

/* Validate that a value-producing try-expression catch either produces a
 * result on normal completion or exits every path through return/throw.
 * Result type fitting runs once for all value-producing branches. */
static bool validate_try_catch_clause_result_presence(
    ResolveContext *context,
    const FengExpr *try_expr,
    const FengTryCatchClause *clause,
    InferredExprType body_type,
    bool result_required) {
    const FengExpr *result_expr;

    if (context == NULL || try_expr == NULL || clause == NULL || !result_required) {
        return true;
    }

    result_expr = block_yield_expression(clause->body);
    if (result_expr == NULL) {
        if (block_exits_via_return_or_throw(clause->body)) {
            return true;
        }
        if (inferred_expr_type_is_known(body_type) &&
            inferred_expr_type_is_void(body_type)) {
            return true;
        }
        (void)resolver_append_error(
            context,
            clause->token,
            "AE1401", format_message(
                "catch clause must produce a final result expression on every normally completing path or exit every reachable path through return/throw"));
        return false;
    }
    return true;
}

/* Match label literal extraction.
 *
 * Per docs/specifications/feng-flow.md, a match label single value must be a literal, or a `let`
 * binding whose initializer is itself a literal (no operator-based constant folding,
 * no propagation across multiple bindings). Range labels share the same rules and
 * are restricted to integer endpoints. */
typedef enum MatchConstKind {
    MATCH_CONST_INT = 0,
    MATCH_CONST_BOOL,
    MATCH_CONST_STRING,
    MATCH_CONST_ENUM
} MatchConstKind;

typedef struct MatchConstValue {
    MatchConstKind kind;
    int64_t i;
    bool b;
    FengSlice s;
    FengToken token;
} MatchConstValue;

static bool match_label_literal_from_literal_expr(const FengExpr *expr, MatchConstValue *out) {
    if (expr == NULL || out == NULL) {
        return false;
    }
    switch (expr->kind) {
        case FENG_EXPR_INTEGER:
            out->kind = MATCH_CONST_INT;
            out->i = expr->as.integer;
            out->token = expr->token;
            return true;
        case FENG_EXPR_BOOL:
            out->kind = MATCH_CONST_BOOL;
            out->b = expr->as.boolean;
            out->token = expr->token;
            return true;
        case FENG_EXPR_STRING:
            out->kind = MATCH_CONST_STRING;
            out->s = expr->as.string;
            out->token = expr->token;
            return true;
        case FENG_EXPR_UNARY:
            /* Allow `-INTEGER_LITERAL` as a single negative integer literal. */
            if (expr->as.unary.op == FENG_TOKEN_MINUS &&
                expr->as.unary.operand != NULL &&
                expr->as.unary.operand->kind == FENG_EXPR_INTEGER) {
                int64_t v = expr->as.unary.operand->as.integer;

                out->kind = MATCH_CONST_INT;
                /* Mirror unary-minus const-eval: negate via unsigned to avoid UB on
                 * INT64_MIN. */
                out->i = (int64_t)(-(uint64_t)v);
                out->token = expr->token;
                return true;
            }
            return false;
        default:
            return false;
    }
}

static bool extract_match_label_literal(ResolveContext *context,
                                        const FengExpr *expr,
                                        MatchConstValue *out) {
    if (expr == NULL) {
        return false;
    }
    if (match_label_literal_from_literal_expr(expr, out)) {
        return true;
    }
    if (expr->kind == FENG_EXPR_IDENTIFIER) {
        const LocalNameEntry *local =
            resolver_find_local_name_entry(context, expr->as.identifier);

        if (local != NULL) {
            if (local->mutability != FENG_MUTABILITY_LET || local->source_expr == NULL) {
                return false;
            }
            if (!match_label_literal_from_literal_expr(local->source_expr, out)) {
                return false;
            }
            out->token = expr->token;
            return true;
        }

        /* 惰性歧义检测(规范 §7.1):match 标签前先做跨来源歧义检测。match
         * 标签可能直接引用裸名常量(import let + 本地 let 同名),需要独立
         * 检测。 */
        if (!report_name_ambiguity_if_any(context,
                                           expr->token,
                                           expr->as.identifier,
                                           SYMBOL_LOOKUP_VALUE)) {
            return false;
        }

        {
            const VisibleValueEntry *visible =
                find_visible_value(context->visible_values,
                                   context->visible_value_count,
                                   expr->as.identifier);

            if (visible == NULL || visible->is_function || visible->decl == NULL ||
                visible->decl->kind != FENG_DECL_GLOBAL_BINDING) {
                return false;
            }
            if (visible->decl->as.binding.mutability != FENG_MUTABILITY_LET ||
                visible->decl->as.binding.initializer == NULL) {
                return false;
            }
            if (!match_label_literal_from_literal_expr(visible->decl->as.binding.initializer, out)) {
                return false;
            }
            out->token = expr->token;
            return true;
        }
    }
    return false;
}

static bool match_target_type_is_allowed(const ResolveContext *context,
                                         InferredExprType target_type) {
    return inferred_expr_type_is_integer(target_type) ||
           inferred_expr_type_is_bool(target_type) ||
           inferred_expr_type_is_string(target_type) ||
           inferred_expr_type_is_enum(context, target_type);
}

static const char *match_const_kind_name(MatchConstKind kind) {
    switch (kind) {
        case MATCH_CONST_INT:
            return "integer";
        case MATCH_CONST_BOOL:
            return "bool";
        case MATCH_CONST_STRING:
            return "string";
        case MATCH_CONST_ENUM:
            return "enum";
    }
    return "unknown";
}

static bool match_const_kind_matches_target(const ResolveContext *context,
                                            MatchConstKind kind,
                                            InferredExprType target_type) {
    switch (kind) {
        case MATCH_CONST_INT:
            return inferred_expr_type_is_integer(target_type);
        case MATCH_CONST_BOOL:
            return inferred_expr_type_is_bool(target_type);
        case MATCH_CONST_STRING:
            return inferred_expr_type_is_string(target_type);
        case MATCH_CONST_ENUM:
            return inferred_expr_type_is_enum(context, target_type);
    }
    return false;
}

/* Aggregated label record used for cross-branch overlap detection. Single values are
 * stored as [v, v]; ranges are stored as [low, high]. The branch index is preserved
 * so that diagnostic messages can refer to "branch N" pairs. */
typedef struct MatchLabelRecord {
    size_t branch_index;
    FengToken token;
    MatchConstKind kind;
    /* INT: low/high are valid (low == high for single value). */
    int64_t low;
    int64_t high;
    /* BOOL */
    bool b;
    /* STRING */
    FengSlice s;
    /* ENUM: enum item reference label. enum_decl is the resolved enum type decl
     * (must match the match target's enum decl); enum_item_name is the item name
     * slice from the label; enum_item_value is the underlying int value. */
    const FengDecl *enum_decl;
    FengSlice enum_item_name;
    int64_t enum_item_value;
} MatchLabelRecord;

static bool slices_equal(FengSlice a, FengSlice b) {
    return a.length == b.length &&
           (a.length == 0U || memcmp(a.data, b.data, a.length) == 0);
}

static bool match_label_records_overlap(const MatchLabelRecord *a, const MatchLabelRecord *b) {
    if (a->kind != b->kind) {
        return false;
    }
    switch (a->kind) {
        case MATCH_CONST_INT:
            return !(a->high < b->low || b->high < a->low);
        case MATCH_CONST_BOOL:
            return a->b == b->b;
        case MATCH_CONST_STRING:
            return slices_equal(a->s, b->s);
        case MATCH_CONST_ENUM:
            /* Overlap requires same enum decl and same item name. Different
             * enums sharing the same underlying int value do not overlap. */
            return a->enum_decl == b->enum_decl &&
                   slices_equal(a->enum_item_name, b->enum_item_name);
    }
    return false;
}

static bool validate_match_label_record_target(ResolveContext *context,
                                               InferredExprType target_type,
                                               const MatchLabelRecord *record) {
    if (!match_const_kind_matches_target(context, record->kind, target_type)) {
        char *target_name = format_inferred_expr_type_name(target_type, context->pointer_size);
        char *message = format_message(
            "match label of type '%s' is not comparable with target type '%s'",
            match_const_kind_name(record->kind),
            target_name != NULL ? target_name : "<unknown>");

        free(target_name);
        return resolver_append_error(context, record->token, "AE0037", message);
    }
    return true;
}

static bool collect_match_branch_label_records(ResolveContext *context,
                                               const FengMatchBranch *branch,
                                               size_t branch_index,
                                               MatchLabelRecord **records,
                                               size_t *record_count,
                                               size_t *record_capacity) {
    size_t label_index;

    for (label_index = 0U; label_index < branch->label_count; ++label_index) {
        const FengMatchLabel *label = &branch->labels[label_index];
        MatchLabelRecord record;

        record.branch_index = branch_index;

        if (label->kind == FENG_MATCH_LABEL_RANGE) {
            MatchConstValue lo;
            MatchConstValue hi;

            if (!extract_match_label_literal(context, label->range_low, &lo) ||
                !extract_match_label_literal(context, label->range_high, &hi)) {
                return resolver_append_error(
                    context,
                    label->token,
                    "AE1103", format_message("match range label endpoints must be integer literals or 'let' bindings to integer literals"));
            }
            if (lo.kind != MATCH_CONST_INT || hi.kind != MATCH_CONST_INT) {
                return resolver_append_error(
                    context,
                    label->token,
                    "AE1103", format_message("match range label endpoints must be integer values"));
            }
            if (lo.i > hi.i) {
                return resolver_append_error(
                    context,
                    label->token,
                    "AE1104", format_message("match range label requires low <= high, got %lld and %lld",
                                   (long long)lo.i,
                                   (long long)hi.i));
            }
            record.token = label->token;
            record.kind = MATCH_CONST_INT;
            record.low = lo.i;
            record.high = hi.i;
        } else {
            MatchConstValue value;

            if (!extract_match_label_literal(context, label->value, &value)) {
                return resolver_append_error(
                    context,
                    label->value != NULL ? label->value->token : label->token,
                    "AE1105", format_message("match label must be a literal or a 'let' binding to a literal"));
            }
            record.token = value.token;
            record.kind = value.kind;
            switch (value.kind) {
                case MATCH_CONST_INT:
                    record.low = value.i;
                    record.high = value.i;
                    break;
                case MATCH_CONST_BOOL:
                    record.b = value.b;
                    break;
                case MATCH_CONST_STRING:
                    record.s = value.s;
                    break;
                case MATCH_CONST_ENUM:
                    /* ENUM labels are not produced by the int/bool/string
                     * collect path; they are handled by the enum match path.
                     * Unreachable here. */
                    break;
            }
        }

        {
            if (*record_count == *record_capacity) {
                size_t new_capacity = (*record_capacity == 0U) ? 4U : (*record_capacity * 2U);
                MatchLabelRecord *grown =
                    (MatchLabelRecord *)realloc(*records, new_capacity * sizeof(MatchLabelRecord));

                if (grown == NULL) {
                    return false;
                }
                *records = grown;
                *record_capacity = new_capacity;
            }
            (*records)[*record_count] = record;
            *record_count += 1U;
        }
    }
    return true;
}

static bool validate_match_label_records(ResolveContext *context,
                                         InferredExprType target_type,
                                         const MatchLabelRecord *records,
                                         size_t record_count) {
    size_t i;
    size_t j;

    for (i = 0U; i < record_count; ++i) {
        if (!validate_match_label_record_target(context, target_type, &records[i])) {
            return false;
        }
    }
    for (i = 0U; i < record_count; ++i) {
        for (j = i + 1U; j < record_count; ++j) {
            if (match_label_records_overlap(&records[i], &records[j])) {
                return resolver_append_error(
                    context,
                    records[j].token,
                    "AE1106", format_message("match label overlaps with an earlier label and is unreachable"));
            }
        }
    }
    return true;
}

/* Return an expression's inferred type, falling back to a result fact captured
 * while its lexical branch scope was active. */
static InferredExprType branch_result_inferred_type(ResolveContext *context,
                                                    const FengExpr *expr) {
    InferredExprType inferred = infer_expr_type(context, expr);

    if (!inferred_expr_type_is_known(inferred) && context != NULL &&
        context->analysis != NULL && expr != NULL) {
        inferred = inferred_expr_type_from_type_fact(
            feng_semantic_lookup_type_fact(context->analysis, expr));
    }
    return inferred;
}

/* Persist the selected result type on a branching expression so later
 * inference and code generation observe the same contextual result type. */
static bool persist_branch_expression_type(ResolveContext *context,
                                           const FengExpr *expr,
                                           const FengTypeRef *type_ref) {
    FengTypeRef *persistent_type_ref;

    if (context == NULL || expr == NULL || type_ref == NULL) {
        return true;
    }
    persistent_type_ref = clone_type_ref_for_inference(type_ref);
    if (persistent_type_ref != NULL) {
        /* Branch-result targets can be synthesized after the program-wide
         * alias-normalization phase (for example, an inferred `int`). Keep
         * every persisted result type in the same canonical form consumed by
         * later semantic queries and Codegen. */
        normalize_type_ref(persistent_type_ref, context->pointer_size);
    }
    if (persistent_type_ref == NULL ||
        !analysis_track_synthetic_type_ref(context->analysis,
                                           persistent_type_ref)) {
        free_synthetic_type_ref(persistent_type_ref);
        return resolver_append_error(
            context,
            expr->token,
            "IE0001",
            format_message("out of memory while persisting branch expression type"));
    }
    ((FengExpr *)expr)->type = persistent_type_ref;
    return true;
}

/* Resolve one expression-result block in its lexical scope and record the
 * trailing expression type before the scope is popped. */
static bool resolve_branch_result_block(ResolveContext *context,
                                        const FengBlock *block,
                                        bool allow_self) {
    const FengExpr *yield;
    bool ok;

    if (block == NULL) {
        return true;
    }
    if (!resolver_push_scope(context)) {
        return false;
    }
    yield = block_yield_expression(block);
    ok = true;
    for (size_t statement_index = 0U;
         statement_index < block->statement_count;
         ++statement_index) {
        const FengStmt *statement = block->statements[statement_index];
        const FengTypeRef *previous_expected =
            context->current_expr_expected_type_ref;
        bool is_result_statement =
            yield != NULL && statement != NULL &&
            statement->kind == FENG_STMT_EXPR &&
            statement->as.expr == yield;

        /* A value-expression target belongs only to the block's final result
         * expression. Earlier statements establish locals or control flow in
         * the same lexical block but are not themselves result candidates. */
        if (!is_result_statement) {
            context->current_expr_expected_type_ref = NULL;
        }
        ok = resolve_stmt(context, statement, allow_self);
        context->current_expr_expected_type_ref = previous_expected;
        if (!ok) {
            break;
        }
    }
    if (ok && !block_exits_via_return_or_throw(block)) {
        if (yield != NULL) {
            InferredExprType yield_type = infer_expr_type(context, yield);

            ok = record_type_fact_for_site(context, yield, yield_type);
        }
    }
    resolver_pop_scope(context);
    return ok;
}

/* Resolve one named match branch through the shared result-block path. */
static bool resolve_match_branch_body(ResolveContext *context,
                                      const FengMatchBranch *branch,
                                      bool allow_self) {
    return resolve_branch_result_block(context,
                                       branch != NULL ? branch->body : NULL,
                                       allow_self);
}

static const UnionNarrowingSet *resolver_create_union_narrowing(
    ResolveContext *context,
    const FengDecl *union_decl,
    const bool *active_members,
    size_t member_count) {
    UnionNarrowingSet *set;
    bool *active_copy;

    if (context == NULL || union_decl == NULL || active_members == NULL || member_count == 0U) {
        return NULL;
    }
    set = (UnionNarrowingSet *)calloc(1U, sizeof(*set));
    if (set == NULL) {
        return NULL;
    }
    active_copy = (bool *)malloc(member_count * sizeof(*active_copy));
    if (active_copy == NULL) {
        free(set);
        return NULL;
    }
    memcpy(active_copy, active_members, member_count * sizeof(*active_copy));
    set->union_decl = union_decl;
    set->active_members = active_copy;
    set->member_count = member_count;
    if (!append_raw((void **)&context->union_narrowings,
                    &context->union_narrowing_count,
                    &context->union_narrowing_capacity,
                    sizeof(set),
                    &set)) {
        free(active_copy);
        free(set);
        return NULL;
    }
    return set;
}

static size_t union_active_member_count(const bool *active_members, size_t member_count) {
    size_t count = 0U;

    if (active_members == NULL) {
        return 0U;
    }
    for (size_t index = 0U; index < member_count; ++index) {
        if (active_members[index]) {
            ++count;
        }
    }
    return count;
}

static size_t union_first_active_member_index(const bool *active_members, size_t member_count) {
    if (active_members == NULL) {
        return member_count;
    }
    for (size_t index = 0U; index < member_count; ++index) {
        if (active_members[index]) {
            return index;
        }
    }
    return member_count;
}

static bool resolve_union_match_label_index(ResolveContext *context,
                                            const FengUnionSpecInfo *info,
                                            const FengTypeRef *union_spec_type_ref,
                                            const FengMatchLabel *label,
                                            size_t *out_index) {
    if (out_index != NULL) {
        *out_index = info != NULL ? info->member_count : 0U;
    }
    if (label == NULL || label->kind != FENG_MATCH_LABEL_TYPE || label->type == NULL) {
        return resolver_append_error(
            context,
            label != NULL ? label->token : context->program->module_token,
            "AE0605", format_message("union-form match labels must be union member types or 'else'"));
    }
    if (!resolve_type_ref(context, label->type, false)) {
        return false;
    }
    if (info == NULL) {
        return false;
    }
    for (size_t index = 0U; index < info->member_count; ++index) {
        const FengTypeRef *member_type_ref = substitute_spec_member_type_ref_for_instance(
            context,
            info->spec_decl,
            union_spec_type_ref,
            info->members[index].type_ref);

        if (type_refs_semantically_equal(context, label->type, member_type_ref)) {
            if (out_index != NULL) {
                *out_index = index;
            }
            /* Validate -> chain: each subsequent type must be a direct member
             * of the previous type's union-form spec. */
            if (label->type_chain_count > 0U) {
                const FengDecl *parent_decl = resolve_type_ref_decl(context, label->type);
                const FengUnionSpecInfo *parent_info = NULL;
                const FengTypeRef *parent_type_ref = label->type;

                if (parent_decl == NULL || parent_decl->kind != FENG_DECL_SPEC ||
                    parent_decl->as.spec_decl.form != FENG_SPEC_FORM_UNION) {
                    char *name = format_type_ref_name(label->type);
                    bool chain_ok = resolver_append_error(
                        context, label->token, "AE1116",
                        format_message("type '%s' in -> chain is not a union-form spec",
                                       name != NULL ? name : "<type>"));
                    free(name);
                    return chain_ok;
                }
                parent_info = feng_semantic_lookup_union_spec_info(context->analysis, parent_decl);
                if (parent_info == NULL) {
                    return resolver_append_error(
                        context, label->token, "AE0606",
                        format_message("union-form spec metadata is unavailable"));
                }
                for (size_t ci = 0U; ci < label->type_chain_count; ++ci) {
                    const FengTypeRef *chain_type = label->type_chain[ci];
                    size_t chain_member_index = parent_info->member_count;
                    bool found = false;

                    if (!resolve_type_ref(context, (FengTypeRef *)chain_type, false)) {
                        return false;
                    }
                    for (size_t mi = 0U; mi < parent_info->member_count; ++mi) {
                        const FengTypeRef *pm_ref = substitute_spec_member_type_ref_for_instance(
                            context, parent_info->spec_decl, parent_type_ref,
                            parent_info->members[mi].type_ref);

                        if (type_refs_semantically_equal(context, chain_type, pm_ref)) {
                            chain_member_index = mi;
                            found = true;
                            break;
                        }
                    }
                    if (!found) {
                        char *chain_name = format_type_ref_name(chain_type);
                        char *parent_name = format_type_ref_name(parent_type_ref);
                        bool err_ok = resolver_append_error(
                            context, chain_type->token, "AE1117",
                            format_message("type '%s' is not a direct member of '%s'",
                                           chain_name != NULL ? chain_name : "<type>",
                                           parent_name != NULL ? parent_name : "<type>"));
                        free(chain_name);
                        free(parent_name);
                        return err_ok;
                    }
                    /* Advance to next level if more chain elements follow. */
                    if (ci + 1U < label->type_chain_count) {
                        parent_decl = resolve_type_ref_decl(context, chain_type);
                        if (parent_decl == NULL || parent_decl->kind != FENG_DECL_SPEC ||
                            parent_decl->as.spec_decl.form != FENG_SPEC_FORM_UNION) {
                            char *name = format_type_ref_name(chain_type);
                            bool chain_ok = resolver_append_error(
                                context, chain_type->token, "AE1116",
                                format_message("type '%s' in -> chain is not a union-form spec",
                                               name != NULL ? name : "<type>"));
                            free(name);
                            return chain_ok;
                        }
                        parent_info = feng_semantic_lookup_union_spec_info(context->analysis, parent_decl);
                        if (parent_info == NULL) {
                            return resolver_append_error(
                                context, chain_type->token, "AE0606",
                                format_message("union-form spec metadata is unavailable"));
                        }
                        parent_type_ref = chain_type;
                        (void)chain_member_index;
                    }
                }
            }
            return true;
        }
    }
    {
        char *label_name = format_type_ref_name(label->type);
        bool ok = resolver_append_error(
            context,
            label->token,
            "AE0605", format_message("type label '%s' is not a member of the target union-form spec",
                           label_name != NULL ? label_name : "<type>"));

        free(label_name);
        return ok;
    }
}

/* Resolve a chain branch body with binding narrowed to the deepest chain type.
 * Unlike resolve_union_match_block_with_narrowing, this function does not
 * create a UnionNarrowingSet — it simply binds the name to the concrete type
 * at the end of the -> chain. */
static bool resolve_union_match_block_with_deepest_narrowing(
    ResolveContext *context,
    const FengBlock *block,
    bool allow_self,
    const FengExpr *target_expr,
    const FengTypeRef *deepest_type_ref,
    FengSlice binding_name,
    FengToken binding_token,
    FengMutability binding_mutability) {
    bool ok;

    if (block == NULL) {
        return true;
    }
    if (!resolver_push_scope(context)) {
        return false;
    }
    ok = true;
    if (deepest_type_ref != NULL) {
        ok = resolver_declare_local_entry(
            context,
            binding_token,
            binding_name,
            inferred_expr_type_from_type_ref(deepest_type_ref),
            binding_mutability,
            target_expr,
            NULL);
    }
    if (ok) {
        ok = resolve_branch_result_block(context, block, allow_self);
    }
    resolver_pop_scope(context);
    return ok;
}

static bool resolve_union_match_block_with_narrowing(ResolveContext *context,
                                                     const FengBlock *block,
                                                     bool allow_self,
                                                     const FengExpr *target_expr,
                                                     InferredExprType original_type,
                                                     const FengUnionSpecInfo *info,
                                                     const FengTypeRef *union_spec_type_ref,
                                                     const bool *active_members,
                                                     bool has_binding,
                                                     FengSlice binding_name,
                                                     FengToken binding_token,
                                                     FengMutability binding_mutability) {
    bool ok;
    bool pushed_binding_scope = false;
    size_t active_count = union_active_member_count(active_members,
                                                    info != NULL ? info->member_count : 0U);

    if (block == NULL) {
        return true;
    }
    if (has_binding) {
        if (!resolver_push_scope(context)) {
            return false;
        }
        pushed_binding_scope = true;
    }
    ok = true;
    /* Only add a narrowed binding when the branch explicitly declares one. */
    if (has_binding && info != NULL && active_count > 0U) {
        if (active_count == 1U) {
            size_t member_index = union_first_active_member_index(active_members, info->member_count);
            const FengTypeRef *member_type_ref = substitute_spec_member_type_ref_for_instance(
                context,
                info->spec_decl,
                union_spec_type_ref,
                info->members[member_index].type_ref);

            ok = resolver_declare_local_entry(
                context,
                binding_token,
                binding_name,
                inferred_expr_type_from_type_ref(member_type_ref),
                binding_mutability,
                target_expr,
                NULL);
        } else {
            const UnionNarrowingSet *narrowing = resolver_create_union_narrowing(
                context,
                info->spec_decl,
                active_members,
                info->member_count);

            ok = narrowing != NULL &&
                 resolver_declare_local_entry(context,
                                              binding_token,
                                              binding_name,
                                              original_type,
                                              binding_mutability,
                                              target_expr,
                                              narrowing);
        }
    }
    if (ok) {
        ok = resolve_branch_result_block(context, block, allow_self);
    }
    if (pushed_binding_scope) {
        resolver_pop_scope(context);
    }
    return ok;
}

/* Collect match result expressions in source order (ordinary branches first,
 * else last) and fit them through the shared branching-expression rules. */
static bool fit_match_branch_results_to_target(
    ResolveContext *context,
    const FengExpr *match_expr,
    const FengMatchBranch *branches,
    size_t branch_count,
    const FengBlock *else_block,
    const FengTypeRef *explicit_target,
    bool *out_all_conform) {
    const FengExpr **results;
    size_t result_count = 0U;
    size_t index;
    bool ok;

    if (out_all_conform != NULL) {
        *out_all_conform = false;
    }
    results = (const FengExpr **)calloc(branch_count + 1U, sizeof(*results));
    if (results == NULL) {
        return false;
    }
    for (index = 0U; index < branch_count; ++index) {
        if (!block_exits_via_return_or_throw(branches[index].body)) {
            const FengExpr *yield = block_yield_expression(branches[index].body);

            if (yield != NULL) {
                results[result_count++] = yield;
            }
        }
    }
    if (else_block != NULL && !block_exits_via_return_or_throw(else_block)) {
        const FengExpr *yield = block_yield_expression(else_block);

        if (yield != NULL) {
            results[result_count++] = yield;
        }
    }
    ok = fit_branch_results_to_target(context,
                                      match_expr,
                                      results,
                                      result_count,
                                      explicit_target,
                                      out_all_conform);
    free(results);
    return ok;
}

/* Validate independently inferred match results when no implicit target was
 * selected (the all-literal case), or emit the established branch-mismatch
 * diagnostic after target fitting failed. Else remains the comparison base to
 * preserve the existing diagnostic anchor and wording. */
static bool validate_match_default_result_types(
    ResolveContext *context,
    const FengExpr *match_expr,
    const FengMatchBranch *branches,
    size_t branch_count,
    const FengBlock *else_block) {
    InferredExprType expected = inferred_expr_type_unknown();
    size_t index;

    if (else_block != NULL && !block_exits_via_return_or_throw(else_block)) {
        expected = branch_result_inferred_type(
            context, block_yield_expression(else_block));
    }
    if (!inferred_expr_type_is_known(expected)) {
        for (index = 0U; index < branch_count; ++index) {
            if (block_exits_via_return_or_throw(branches[index].body)) {
                continue;
            }
            expected = branch_result_inferred_type(
                context, block_yield_expression(branches[index].body));
            if (inferred_expr_type_is_known(expected)) {
                break;
            }
        }
    }
    if (!inferred_expr_type_is_known(expected)) {
        return true;
    }

    for (index = 0U; index < branch_count; ++index) {
        InferredExprType branch_type;

        if (block_exits_via_return_or_throw(branches[index].body)) {
            continue;
        }
        branch_type = branch_result_inferred_type(
            context, block_yield_expression(branches[index].body));
        if (!inferred_expr_type_is_known(branch_type) ||
            inferred_expr_types_equal(context, expected, branch_type)) {
            continue;
        }
        {
            char *expected_name = format_inferred_expr_type_name(
                expected, context->pointer_size);
            char *branch_name = format_inferred_expr_type_name(
                branch_type, context->pointer_size);
            bool result = resolver_append_error(
                context,
                branches[index].token,
                "AE1108",
                format_message(
                    "match expression branches must have the same type, got '%s' and '%s'",
                    expected_name != NULL ? expected_name : "<unknown>",
                    branch_name != NULL ? branch_name : "<unknown>"));

            free(expected_name);
            free(branch_name);
            if (result && context->current_expr_expected_type_ref != NULL) {
                result = persist_branch_expression_type(
                    context,
                    match_expr,
                    context->current_expr_expected_type_ref);
            }
            return result;
        }
    }
    return true;
}

static bool resolve_and_validate_union_match_common(ResolveContext *context,
                                                    const FengExpr *match_expr,
                                                    const FengExpr *target,
                                                    InferredExprType target_type,
                                                    const FengDecl *union_decl,
                                                    const FengTypeRef *union_spec_type_ref,
                                                    const FengMatchBranch *branches,
                                                    size_t branch_count,
                                                    const FengBlock *else_block,
                                                    FengToken anchor,
                                                    bool is_expression_form,
                                                    bool allow_self) {
    const FengUnionSpecInfo *info = feng_semantic_lookup_union_spec_info(context->analysis,
                                                                         union_decl);
    const LocalNameEntry *target_local = NULL;
    bool *active_members = NULL;
    bool *covered_members = NULL;
    bool *chain_covered_members = NULL;
    bool ok = true;
    bool all_results_conform = false;

    if (info == NULL || info->member_count == 0U) {
        return resolver_append_error(context,
                                     target != NULL ? target->token : anchor,
                                     "AE0606", format_message("union-form spec metadata is unavailable"));
    }

    active_members = (bool *)malloc(info->member_count * sizeof(*active_members));
    covered_members = (bool *)calloc(info->member_count, sizeof(*covered_members));
    chain_covered_members = (bool *)calloc(info->member_count, sizeof(*chain_covered_members));
    if (active_members == NULL || covered_members == NULL || chain_covered_members == NULL) {
        free(active_members);
        free(covered_members);
        free(chain_covered_members);
        return false;
    }
    for (size_t index = 0U; index < info->member_count; ++index) {
        active_members[index] = true;
    }

    /* Inherit active-member narrowing from an outer binding on the same
     * union spec so nested match sees only the already-narrowed members. */
    if (target != NULL && target->kind == FENG_EXPR_IDENTIFIER) {
        target_local = resolver_find_local_name_entry(context, target->as.identifier);
        if (target_local != NULL &&
            target_local->union_narrowing != NULL &&
            target_local->union_narrowing->union_decl == union_decl &&
            target_local->union_narrowing->member_count == info->member_count) {
            memcpy(active_members,
                   target_local->union_narrowing->active_members,
                   info->member_count * sizeof(*active_members));
        }
    }

    for (size_t branch_index = 0U; branch_index < branch_count && ok; ++branch_index) {
        bool *branch_members = (bool *)calloc(info->member_count, sizeof(*branch_members));
        bool *chain_members = (bool *)calloc(info->member_count, sizeof(*chain_members));

        if (branch_members == NULL || chain_members == NULL) {
            free(branch_members);
            free(chain_members);
            ok = false;
            break;
        }
        for (size_t label_index = 0U;
             ok && label_index < branches[branch_index].label_count;
             ++label_index) {
            const FengMatchLabel *label = &branches[branch_index].labels[label_index];
            size_t member_index = info->member_count;

            ok = resolve_union_match_label_index(context,
                                                 info,
                                                 union_spec_type_ref,
                                                 label,
                                                 &member_index);
            if (!ok) {
                break;
            }
            if (member_index >= info->member_count) {
                ok = false;
                break;
            }
            if (!active_members[member_index]) {
                ok = resolver_append_error(
                    context,
                    label->token,
                    "AE0607", format_message("union match label overlaps with an earlier label and is unreachable"));
                break;
            }
            if (label->type_chain_count > 0U) {
                /* Chain label: allow sharing with other chain labels on the
                 * same first-level member. Reject if already covered by a
                 * non-chain label or duplicated within the same branch. */
                if (covered_members[member_index] && !chain_members[member_index]) {
                    ok = resolver_append_error(
                        context, label->token, "AE0607",
                        format_message("union match label overlaps with an earlier label and is unreachable"));
                    break;
                }
                if (branch_members[member_index] && !chain_members[member_index]) {
                    ok = resolver_append_error(
                        context, label->token, "AE0607",
                        format_message("union match branch lists the same member more than once"));
                    break;
                }
                chain_members[member_index] = true;
            } else {
                /* Non-chain label: reject if already covered or in branch. */
                if (covered_members[member_index]) {
                    ok = resolver_append_error(
                        context, label->token, "AE0607",
                        format_message("union match label overlaps with an earlier label and is unreachable"));
                    break;
                }
                if (branch_members[member_index]) {
                    ok = resolver_append_error(
                        context, label->token, "AE0607",
                        format_message("union match branch lists the same member more than once"));
                    break;
                }
            }
            branch_members[member_index] = true;
        }
        if (ok) {
            for (size_t index = 0U; index < info->member_count; ++index) {
                if (branch_members[index] && !chain_members[index]) {
                    covered_members[index] = true;
                }
            }
            /* For chain branches, narrow to the deepest type in the chain. */
            {
                bool has_chain = false;
                size_t chain_member_index = info->member_count;
                const FengTypeRef *deepest_type_ref = NULL;

                for (size_t index = 0U; index < info->member_count; ++index) {
                    if (chain_members[index]) {
                        has_chain = true;
                        chain_member_index = index;
                        chain_covered_members[index] = true;
                        break;
                    }
                }
                if (has_chain) {
                    /* Find the deepest type in the chain for narrowing. */
                    for (size_t label_index = 0U; label_index < branches[branch_index].label_count; ++label_index) {
                        const FengMatchLabel *label = &branches[branch_index].labels[label_index];

                        if (label->type_chain_count > 0U) {
                            deepest_type_ref = label->type_chain[label->type_chain_count - 1U];
                            break;
                        }
                    }
                    if (deepest_type_ref != NULL && branches[branch_index].has_binding) {
                        /* Narrow binding to deepest chain type. */
                        ok = resolve_union_match_block_with_deepest_narrowing(
                            context,
                            branches[branch_index].body,
                            allow_self,
                            target,
                            deepest_type_ref,
                            branches[branch_index].binding_name,
                            branches[branch_index].binding_token,
                            branches[branch_index].binding_mutability);
                    } else {
                        /* Chain branch without binding: narrow to first-level member. */
                        bool *narrow_members = (bool *)calloc(info->member_count, sizeof(*narrow_members));

                        if (narrow_members == NULL) {
                            ok = false;
                        } else {
                            narrow_members[chain_member_index] = true;
                            ok = resolve_union_match_block_with_narrowing(
                                context, branches[branch_index].body, allow_self,
                                target, target_type, info, union_spec_type_ref,
                                narrow_members,
                                false, (FengSlice){NULL, 0U},
                                branches[branch_index].token,
                                FENG_MUTABILITY_LET);
                            free(narrow_members);
                        }
                    }
                } else {
                    ok = resolve_union_match_block_with_narrowing(context,
                                                                  branches[branch_index].body,
                                                                  allow_self,
                                                                  target,
                                                                  target_type,
                                                                  info,
                                                                  union_spec_type_ref,
                                                                  branch_members,
                                                                  branches[branch_index].has_binding,
                                                                  branches[branch_index].binding_name,
                                                                  branches[branch_index].binding_token,
                                                                  branches[branch_index].binding_mutability);
                }
            }
        }
        if (ok && is_expression_form) {
            ok = validate_block_yields_expression(context,
                                                  branches[branch_index].body,
                                                  branches[branch_index].token,
                                                  "match expression");
        }
        free(branch_members);
        free(chain_members);
    }

    /* Post-pass: update covered_members for chain-covered first-level members.
     * A first-level member with chain branches is considered covered when at
     * least one chain branch targets it. Full sub-member exhaustiveness is
     * delegated to the match expression's else-branch requirement. */
    if (ok) {
        for (size_t index = 0U; index < info->member_count; ++index) {
            if (chain_covered_members[index]) {
                covered_members[index] = true;
            }
        }
    }

    if (ok && else_block != NULL) {
        bool *else_members = (bool *)malloc(info->member_count * sizeof(*else_members));

        if (else_members == NULL) {
            ok = false;
        } else {
            for (size_t index = 0U; index < info->member_count; ++index) {
                else_members[index] = active_members[index] && !covered_members[index];
            }
            ok = resolve_union_match_block_with_narrowing(context,
                                                          else_block,
                                                          allow_self,
                                                          target,
                                                          target_type,
                                                          info,
                                                          union_spec_type_ref,
                                                          else_members,
                                                          false,
                                                          (FengSlice){NULL, 0U},
                                                          anchor,
                                                          FENG_MUTABILITY_LET);
            free(else_members);
        }
        if (ok && is_expression_form) {
            ok = validate_block_yields_expression(context, else_block, anchor, "match expression else");
        }
    } else if (ok && is_expression_form) {
        ok = resolver_append_error(context,
                                   anchor,
                                   "AE1108", format_message("match expressions require an else branch"));
    }

    free(active_members);
    free(covered_members);
    free(chain_covered_members);
    if (!ok) {
        return false;
    }

    if (is_expression_form &&
        !fit_match_branch_results_to_target(
            context,
            match_expr,
            branches,
            branch_count,
            else_block,
            context->current_expr_expected_type_ref,
            &all_results_conform)) {
        return false;
    }

    if (is_expression_form && !all_results_conform &&
        context->deferred_call_argument_target_depth == 0U) {
        return validate_match_default_result_types(context,
                                                   match_expr,
                                                   branches,
                                                   branch_count,
                                                   else_block);
    }

    return true;
}

static bool ensure_enum_decl_info(ResolveContext *context, const FengDecl *enum_decl);

static bool resolve_and_validate_enum_match_common(ResolveContext *context,
                                                    const FengExpr *match_expr,
                                                    const FengExpr *target,
                                                    InferredExprType target_type,
                                                    const FengDecl *enum_decl,
                                                    const FengMatchBranch *branches,
                                                    size_t branch_count,
                                                    const FengBlock *else_block,
                                                    FengToken anchor,
                                                    bool is_expression_form,
                                                    bool allow_self) {
    MatchLabelRecord *records = NULL;
    size_t record_count = 0U;
    size_t record_capacity = 0U;
    size_t branch_index;
    bool ok = true;
    bool all_results_conform = false;

    (void)target;

    if (!ensure_enum_decl_info(context, enum_decl)) {
        free(records);
        return false;
    }

    for (branch_index = 0U; branch_index < branch_count && ok; ++branch_index) {
        const FengMatchBranch *branch = &branches[branch_index];
        size_t label_index;

        if (branch->has_binding) {
            ok = resolver_append_error(
                context,
                branch->token,
                "AE1107", format_message("match enum target requires enum item reference label of the form 'EnumName.ItemName'"));
            break;
        }

        for (label_index = 0U; label_index < branch->label_count; ++label_index) {
            const FengMatchLabel *label = &branch->labels[label_index];
            const FengTypeRef *type_ref;
            MatchLabelRecord record;

            record.branch_index = branch_index;
            record.token = label->token;
            record.kind = MATCH_CONST_ENUM;
            record.low = 0;
            record.high = 0;
            record.b = false;
            record.s = (FengSlice){NULL, 0U};
            record.enum_decl = NULL;
            record.enum_item_name = (FengSlice){NULL, 0U};
            record.enum_item_value = 0;

            if (label->kind == FENG_MATCH_LABEL_RANGE) {
                ok = resolver_append_error(
                    context,
                    label->token,
                    "AE1111", format_message("match enum target does not support range labels"));
                break;
            }

            if (label->kind != FENG_MATCH_LABEL_TYPE || label->type == NULL) {
                ok = resolver_append_error(
                    context,
                    label->token,
                    "AE1107", format_message("match enum target requires enum item reference label of the form 'EnumName.ItemName'"));
                break;
            }

            type_ref = label->type;
            if (type_ref->kind != FENG_TYPE_REF_NAMED ||
                type_ref->as.named.segment_count != 2U ||
                type_ref->as.named.type_arg_count != 0U) {
                ok = resolver_append_error(
                    context,
                    label->token,
                    "AE1107", format_message("match enum target requires enum item reference label of the form 'EnumName.ItemName'"));
                break;
            }

            {
                FengSlice enum_name = type_ref->as.named.segments[0];
                FengSlice item_name = type_ref->as.named.segments[1];
                /* Enum has no generic params; arity = 0 for precise lookup */
                const FengDecl *label_enum_decl =
                    find_visible_type_decl(context->visible_types,
                                           context->visible_type_count,
                                           enum_name, 0U);

                if (label_enum_decl == NULL || !decl_is_enum_type(label_enum_decl)) {
                    ok = resolver_append_error(
                        context,
                        label->token,
                        "AE1107", format_message("match enum target requires enum item reference label of the form 'EnumName.ItemName'"));
                    break;
                }

                if (label_enum_decl != enum_decl) {
                    ok = resolver_append_error(
                        context,
                        label->token,
                        "AE1109", format_message("match label references enum '%.*s' but target type is enum '%.*s'",
                                       (int)label_enum_decl->as.enum_decl.name.length,
                                       label_enum_decl->as.enum_decl.name.data,
                                       (int)enum_decl->as.enum_decl.name.length,
                                       enum_decl->as.enum_decl.name.data));
                    break;
                }

                {
                    const FengEnumItem *item = find_enum_item_decl(enum_decl, item_name);

                    if (item == NULL) {
                        ok = resolver_append_error(
                            context,
                            label->token,
                            "AE0404", format_message("enum '%.*s' has no item '%.*s'",
                                           (int)enum_decl->as.enum_decl.name.length,
                                           enum_decl->as.enum_decl.name.data,
                                           (int)item_name.length,
                                           item_name.data));
                        break;
                    }

                    {
                        const FengSemanticEnumItemInfo *item_info =
                            feng_semantic_find_enum_item_info(context->analysis,
                                                              enum_decl,
                                                              item_name);

                        if (item_info == NULL) {
                            ok = false;
                            break;
                        }

                        record.enum_decl = enum_decl;
                        record.enum_item_name = item_name;
                        record.enum_item_value = item_info->value;
                    }
                }
            }

            if (record_count == record_capacity) {
                size_t new_capacity = (record_capacity == 0U) ? 4U : (record_capacity * 2U);
                MatchLabelRecord *grown =
                    (MatchLabelRecord *)realloc(records, new_capacity * sizeof(MatchLabelRecord));

                if (grown == NULL) {
                    ok = false;
                    break;
                }
                records = grown;
                record_capacity = new_capacity;
            }
            records[record_count] = record;
            record_count += 1U;
        }

        if (!ok) {
            break;
        }

        if (!resolve_match_branch_body(context, branch, allow_self)) {
            ok = false;
            break;
        }
        if (is_expression_form &&
            !validate_block_yields_expression(context,
                                              branch->body,
                                              branch->token,
                                              "match expression")) {
            ok = false;
            break;
        }
    }

    if (ok) {
        ok = validate_match_label_records(context, target_type, records, record_count);
    }

    free(records);

    if (!ok) {
        return false;
    }

    if (else_block != NULL) {
        if (!resolve_branch_result_block(context,
                                         else_block,
                                         allow_self)) {
            return false;
        }
        if (is_expression_form &&
            !validate_block_yields_expression(context, else_block, anchor, "match expression else")) {
            return false;
        }
    } else if (is_expression_form) {
        return resolver_append_error(
            context,
            anchor,
            "AE1108", format_message("match expressions require an else branch"));
    }

    if (is_expression_form &&
        !fit_match_branch_results_to_target(
            context,
            match_expr,
            branches,
            branch_count,
            else_block,
            context->current_expr_expected_type_ref,
            &all_results_conform)) {
        return false;
    }

    if (is_expression_form && !all_results_conform &&
        context->deferred_call_argument_target_depth == 0U) {
        ok = validate_match_default_result_types(context,
                                                 match_expr,
                                                 branches,
                                                 branch_count,
                                                 else_block);
    }

    return ok;
}

static bool resolve_and_validate_enum_match_common(ResolveContext *context,
                                                    const FengExpr *match_expr,
                                                    const FengExpr *target,
                                                    InferredExprType target_type,
                                                    const FengDecl *enum_decl,
                                                    const FengMatchBranch *branches,
                                                    size_t branch_count,
                                                    const FengBlock *else_block,
                                                    FengToken anchor,
                                                    bool is_expression_form,
                                                    bool allow_self);

static bool ensure_enum_decl_info(ResolveContext *context, const FengDecl *enum_decl);

static bool resolve_and_validate_match_common(ResolveContext *context,
                                              const FengExpr *match_expr,
                                              const FengExpr *target,
                                              const FengMatchBranch *branches,
                                              size_t branch_count,
                                              const FengBlock *else_block,
                                              FengToken anchor,
                                              bool is_expression_form,
                                              bool allow_self) {
    InferredExprType target_type;
    MatchLabelRecord *records = NULL;
    size_t record_count = 0U;
    size_t record_capacity = 0U;
    size_t branch_index;
    bool ok = true;
    bool all_results_conform = false;

    if (!resolve_expr(context, (FengExpr *)target, allow_self)) {
        return false;
    }

    target_type = infer_expr_type(context, target);
    if (inferred_expr_type_is_known(target_type)) {
        const FengDecl *union_decl = NULL;

        if (target_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
            union_decl = resolve_union_spec_type_ref_decl(context, target_type.type_ref);
        } else if (target_type.kind == FENG_INFERRED_EXPR_TYPE_DECL &&
                   target_type.type_decl != NULL &&
                   target_type.type_decl->kind == FENG_DECL_SPEC &&
                   target_type.type_decl->as.spec_decl.form == FENG_SPEC_FORM_UNION) {
            union_decl = target_type.type_decl;
        }
        if (union_decl != NULL) {
            const FengTypeRef *union_spec_type_ref =
                target_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF
                    ? target_type.type_ref
                    : NULL;

            if (union_spec_type_ref == NULL && target != NULL &&
                target->kind == FENG_EXPR_IDENTIFIER) {
                const LocalNameEntry *target_local =
                    resolver_find_local_name_entry(context, target->as.identifier);

                if (target_local != NULL &&
                    target_local->type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
                    union_spec_type_ref = target_local->type.type_ref;
                }
            }

            if (union_spec_type_ref == NULL && context->analysis != NULL && target != NULL) {
                const FengSemanticTypeFact *target_fact =
                    feng_semantic_lookup_type_fact(context->analysis, target);

                if (target_fact != NULL &&
                    target_fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF) {
                    union_spec_type_ref = target_fact->type_ref;
                }
            }

            if (union_spec_type_ref != NULL &&
                resolve_union_spec_type_ref_decl(context, union_spec_type_ref) != union_decl) {
                union_spec_type_ref = NULL;
            }

            return resolve_and_validate_union_match_common(context,
                                                           match_expr,
                                                           target,
                                                           target_type,
                                                           union_decl,
                                                           union_spec_type_ref,
                                                           branches,
                                                           branch_count,
                                                           else_block,
                                                           anchor,
                                                           is_expression_form,
                                                           allow_self);
        }
    }
    if (inferred_expr_type_is_known(target_type) &&
        inferred_expr_type_is_enum(context, target_type)) {
        const FengDecl *enum_decl = target_type.type_decl;

        if (enum_decl == NULL && target_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
            enum_decl = resolve_type_ref_decl(context, target_type.type_ref);
        }
        if (enum_decl != NULL && decl_is_enum_type(enum_decl)) {
            return resolve_and_validate_enum_match_common(context,
                                                          match_expr,
                                                          target,
                                                          target_type,
                                                          enum_decl,
                                                          branches,
                                                          branch_count,
                                                          else_block,
                                                          anchor,
                                                          is_expression_form,
                                                          allow_self);
        }
    }
    if (inferred_expr_type_is_known(target_type) && !match_target_type_is_allowed(context, target_type)) {
        char *target_name = format_inferred_expr_type_name(target_type, context->pointer_size);
        char *message = format_message(
            "match target type '%s' is not allowed; allowed types are integers, 'string', 'bool' and enum",
            target_name != NULL ? target_name : "<unknown>");

        free(target_name);
        return resolver_append_error(context, target->token, "AE0050", message);
    }

    for (branch_index = 0U; branch_index < branch_count && ok; ++branch_index) {
        if (inferred_expr_type_is_known(target_type) &&
            !collect_match_branch_label_records(context,
                                                &branches[branch_index],
                                                branch_index,
                                                &records,
                                                &record_count,
                                                &record_capacity)) {
            ok = false;
            break;
        }
        if (!resolve_match_branch_body(context,
                                       &branches[branch_index],
                                       allow_self)) {
            ok = false;
            break;
        }
        if (is_expression_form &&
            !validate_block_yields_expression(context,
                                              branches[branch_index].body,
                                              branches[branch_index].token,
                                              "match expression")) {
            ok = false;
            break;
        }
    }

    if (ok && inferred_expr_type_is_known(target_type)) {
        ok = validate_match_label_records(context, target_type, records, record_count);
    }

    free(records);

    if (!ok) {
        return false;
    }

    if (else_block != NULL) {
        if (!resolve_branch_result_block(context,
                                         else_block,
                                         allow_self)) {
            return false;
        }
        if (is_expression_form &&
            !validate_block_yields_expression(context, else_block, anchor, "match expression else")) {
            return false;
        }
    } else if (is_expression_form) {
        return resolver_append_error(
            context,
            anchor,
            "AE1108", format_message("match expressions require an else branch"));
    }

    if (is_expression_form &&
        !fit_match_branch_results_to_target(
            context,
            match_expr,
            branches,
            branch_count,
            else_block,
            context->current_expr_expected_type_ref,
            &all_results_conform)) {
        return false;
    }

    if (is_expression_form && !all_results_conform &&
        context->deferred_call_argument_target_depth == 0U) {
        return validate_match_default_result_types(context,
                                                   match_expr,
                                                   branches,
                                                   branch_count,
                                                   else_block);
    }

    return true;
}

/* Visible match binding record collected from a condition expression.
 * Each entry remembers the owning match_op expression so that, when the
 * binding is registered in if/while body scope, the narrowed type can be
 * recomputed from the match_op's target type and active member subset. */
typedef struct VisibleMatchBinding {
    FengSlice name;
    FengMutability mutability;
    const FengExpr *match_op;
} VisibleMatchBinding;

typedef struct VisibleMatchBindingSet {
    VisibleMatchBinding *items;
    size_t count;
    size_t capacity;
} VisibleMatchBindingSet;

/* Recursively collect match bindings that are visible in if/while body scope.
 * Per docs/specifications/feng-flow.md §3.3:
 * - `A && B` collects both sides (union of bindings)
 * - `A || B` subtree yields empty (can't guarantee either side bound)
 * - `!A` subtree yields empty (negation doesn't preserve binding)
 * - GROUP transparently passes through (Feng has no GROUP node; grouped
 *   expressions are returned directly by parse_group_or_cast)
 * - `match v: T` yields v when has_binding
 * - all other operators yield empty (no truth propagation) */
static bool collect_visible_match_bindings(const FengExpr *expr,
                                           VisibleMatchBindingSet *out) {
    if (expr == NULL || out == NULL) {
        return true;
    }
    switch (expr->kind) {
        case FENG_EXPR_BINARY:
            if (expr->as.binary.op == FENG_TOKEN_AND_AND) {
                return collect_visible_match_bindings(expr->as.binary.left, out) &&
                       collect_visible_match_bindings(expr->as.binary.right, out);
            }
            return true;
        case FENG_EXPR_UNARY:
            /* `!` subtree yields empty per visibility rule. */
            return true;
        case FENG_EXPR_MATCH_OP:
            if (expr->as.match_op.has_binding) {
                VisibleMatchBinding binding;
                binding.name = expr->as.match_op.binding_name;
                binding.mutability = expr->as.match_op.binding_mutability;
                binding.match_op = expr;
                return append_raw((void **)&out->items,
                                  &out->count,
                                  &out->capacity,
                                  sizeof(binding),
                                  &binding);
            }
            return true;
        default:
            return true;
    }
}

static void free_visible_match_binding_set(VisibleMatchBindingSet *set) {
    if (set == NULL) {
        return;
    }
    free(set->items);
    set->items = NULL;
    set->count = 0U;
    set->capacity = 0U;
}

/* Resolve an infix match operator expression `target match pattern`.
 * Validates target type, each label's structure, binding constraints, and
 * label-target compatibility. The result type is always bool (set by
 * infer_expr_type). The optional binding variable is NOT registered into
 * scope here; visibility-based scope registration happens at if/while
 * condition handling via collect_visible_match_bindings. */
static bool resolve_and_validate_match_op(ResolveContext *context,
                                          const FengExpr *expr,
                                          bool allow_self) {
    const FengExpr *target = expr->as.match_op.target;
    InferredExprType target_type;
    const FengDecl *union_decl = NULL;
    const FengTypeRef *union_spec_type_ref = NULL;
    const FengUnionSpecInfo *info = NULL;
    bool has_binding = expr->as.match_op.has_binding;
    size_t label_index;
    bool *covered_members = NULL;
    bool ok = true;

    if (!resolve_expr(context, (FengExpr *)target, allow_self)) {
        return false;
    }

    target_type = infer_expr_type(context, target);

    /* Detect union-form target. Same detection logic as
     * resolve_and_validate_match_common so the binding's narrowed subset
     * can be computed consistently. */
    if (inferred_expr_type_is_known(target_type)) {
        if (target_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
            union_decl = resolve_union_spec_type_ref_decl(context, target_type.type_ref);
        } else if (target_type.kind == FENG_INFERRED_EXPR_TYPE_DECL &&
                   target_type.type_decl != NULL &&
                   target_type.type_decl->kind == FENG_DECL_SPEC &&
                   target_type.type_decl->as.spec_decl.form == FENG_SPEC_FORM_UNION) {
            union_decl = target_type.type_decl;
        }
        if (union_decl != NULL) {
            union_spec_type_ref = (target_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF)
                ? target_type.type_ref : NULL;

            if (union_spec_type_ref == NULL && target->kind == FENG_EXPR_IDENTIFIER) {
                const LocalNameEntry *target_local =
                    resolver_find_local_name_entry(context, target->as.identifier);
                if (target_local != NULL &&
                    target_local->type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
                    union_spec_type_ref = target_local->type.type_ref;
                }
            }
            if (union_spec_type_ref == NULL && context->analysis != NULL) {
                const FengSemanticTypeFact *target_fact =
                    feng_semantic_lookup_type_fact(context->analysis, target);
                if (target_fact != NULL &&
                    target_fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF) {
                    union_spec_type_ref = target_fact->type_ref;
                }
            }
            if (union_spec_type_ref != NULL &&
                resolve_union_spec_type_ref_decl(context, union_spec_type_ref) != union_decl) {
                union_spec_type_ref = NULL;
            }
        }
    }

    /* Binding constraint: only valid when target is union-form spec and all
     * labels are union member type patterns. AE1009 otherwise. */
    if (has_binding) {
        if (union_decl == NULL) {
            return resolver_append_error(
                context,
                expr->token,
                "AE1009", format_message("infix match binding requires all labels to be union member type patterns"));
        }
        for (label_index = 0U; label_index < expr->as.match_op.label_count; ++label_index) {
            const FengMatchLabel *label = &expr->as.match_op.labels[label_index];
            if (label->kind != FENG_MATCH_LABEL_TYPE) {
                return resolver_append_error(
                    context,
                    label->token,
                    "AE1009", format_message("infix match binding requires all labels to be union member type patterns"));
            }
        }
    }

    /* Resolve each label's children (value / range endpoints / type_ref). */
    for (label_index = 0U; label_index < expr->as.match_op.label_count; ++label_index) {
        const FengMatchLabel *label = &expr->as.match_op.labels[label_index];
        switch (label->kind) {
            case FENG_MATCH_LABEL_VALUE:
                if (label->value != NULL &&
                    !resolve_expr(context, label->value, allow_self)) {
                    return false;
                }
                break;
            case FENG_MATCH_LABEL_RANGE:
                if (label->range_low != NULL &&
                    !resolve_expr(context, label->range_low, allow_self)) {
                    return false;
                }
                if (label->range_high != NULL &&
                    !resolve_expr(context, label->range_high, allow_self)) {
                    return false;
                }
                break;
            case FENG_MATCH_LABEL_TYPE:
                /* Dispatch based on the target's static type, mirroring the
                 * block-form match paths:
                 *  - union-form target: type label is a union member type;
                 *    resolve as a normal type ref (covers single-segment
                 *    `int` / `UserType` and qualified `b.Error` /
                 *    `demo.base.Error`). The union-specific validation
                 *    below (resolve_union_match_label_index) verifies
                 *    membership. This path mirrors the block-form
                 *    resolve_and_validate_union_match_common.
                 *  - enum target: type label is an enum item reference of
                 *    the form `EnumName.ItemName`. Calling resolve_type_ref
                 *    would reject it as `unknown type` (the second segment
                 *    is an item name, not a type); skip and let the
                 *    enum-specific validation below read enum/item names
                 *    directly from segments — mirroring the block-form
                 *    resolve_and_validate_enum_match_common.
                 *  - other targets (int / string / bool): type labels are
                 *    not legal here. Skip resolve_type_ref and let the
                 *    shared collect_match_branch_label_records path reject
                 *    the label with AE1105 (same diagnostic the block form
                 *    emits), instead of the misleading AE1013 `unknown
                 *    type` that resolve_type_ref would produce for a
                 *    2-segment `EnumName.ItemName` form. */
                if (union_decl != NULL) {
                    if (!resolve_type_ref(context, label->type, false)) {
                        return false;
                    }
                }
                break;
        }
    }

    if (!inferred_expr_type_is_known(target_type)) {
        /* Cannot validate further without target type info. */
        return true;
    }

    if (union_decl != NULL) {
        info = feng_semantic_lookup_union_spec_info(context->analysis, union_decl);
        if (info == NULL || info->member_count == 0U) {
            return resolver_append_error(
                context,
                target != NULL ? target->token : expr->token,
                "AE0606", format_message("union-form spec metadata is unavailable"));
        }
        covered_members = (bool *)calloc(info->member_count, sizeof(*covered_members));
        if (covered_members == NULL) {
            return false;
        }
        bool *chain_members = (bool *)calloc(info->member_count, sizeof(*chain_members));

        if (chain_members == NULL) {
            free(covered_members);
            return false;
        }
        for (label_index = 0U;
             label_index < expr->as.match_op.label_count && ok;
             ++label_index) {
            const FengMatchLabel *label = &expr->as.match_op.labels[label_index];
            size_t member_index = info->member_count;

            ok = resolve_union_match_label_index(context,
                                                 info,
                                                 union_spec_type_ref,
                                                 label,
                                                 &member_index);
            if (!ok) {
                break;
            }
            if (member_index >= info->member_count) {
                ok = false;
                break;
            }
            if (label->type_chain_count > 0U) {
                /* Chain label: allow sharing with other chain labels on the
                 * same first-level member. Reject if already covered by a
                 * non-chain label. */
                if (covered_members[member_index] && !chain_members[member_index]) {
                    ok = resolver_append_error(
                        context, label->token, "AE0607",
                        format_message("union match label overlaps with an earlier label and is unreachable"));
                    break;
                }
                chain_members[member_index] = true;
            } else {
                /* Non-chain label: reject if already covered. */
                if (covered_members[member_index]) {
                    ok = resolver_append_error(
                        context,
                        label->token,
                        "AE0607", format_message("union match label overlaps with an earlier label and is unreachable"));
                    break;
                }
                covered_members[member_index] = true;
            }
        }
        free(covered_members);
        free(chain_members);
        if (!ok) {
            return false;
        }
        return true;
    }

    if (inferred_expr_type_is_enum(context, target_type)) {
        const FengDecl *enum_decl = target_type.type_decl;
        MatchLabelRecord *records = NULL;
        size_t record_count = 0U;
        size_t record_capacity = 0U;

        if (enum_decl == NULL && target_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
            enum_decl = resolve_type_ref_decl(context, target_type.type_ref);
        }
        if (enum_decl == NULL || !decl_is_enum_type(enum_decl)) {
            char *target_name = format_inferred_expr_type_name(target_type, context->pointer_size);
            char *message = format_message(
                "match target type '%s' is not allowed; allowed types are integers, 'string', 'bool' and enum",
                target_name != NULL ? target_name : "<unknown>");
            free(target_name);
            return resolver_append_error(context, target->token, "AE0050", message);
        }
        if (!ensure_enum_decl_info(context, enum_decl)) {
            return false;
        }

        /* Enum labels must be `EnumName.ItemName` references; reuse the same
         * validation as resolve_and_validate_enum_match_common by wrapping
         * match_op labels into a single branch. */
        for (label_index = 0U;
             label_index < expr->as.match_op.label_count && ok;
             ++label_index) {
            const FengMatchLabel *label = &expr->as.match_op.labels[label_index];
            const FengTypeRef *type_ref;
            MatchLabelRecord record;

            record.branch_index = 0U;
            record.token = label->token;
            record.kind = MATCH_CONST_ENUM;
            record.low = 0;
            record.high = 0;
            record.b = false;
            record.s = (FengSlice){NULL, 0U};
            record.enum_decl = NULL;
            record.enum_item_name = (FengSlice){NULL, 0U};
            record.enum_item_value = 0;

            if (label->kind == FENG_MATCH_LABEL_RANGE) {
                ok = resolver_append_error(
                    context,
                    label->token,
                    "AE1111", format_message("match enum target does not support range labels"));
                break;
            }
            if (label->kind != FENG_MATCH_LABEL_TYPE || label->type == NULL) {
                ok = resolver_append_error(
                    context,
                    label->token,
                    "AE1107", format_message("match enum target requires enum item reference label of the form 'EnumName.ItemName'"));
                break;
            }
            type_ref = label->type;
            if (type_ref->kind != FENG_TYPE_REF_NAMED ||
                type_ref->as.named.segment_count != 2U ||
                type_ref->as.named.type_arg_count != 0U) {
                ok = resolver_append_error(
                    context,
                    label->token,
                    "AE1107", format_message("match enum target requires enum item reference label of the form 'EnumName.ItemName'"));
                break;
            } else {
                FengSlice enum_name = type_ref->as.named.segments[0];
                FengSlice item_name = type_ref->as.named.segments[1];
                /* Enum has no generic params; arity = 0 for precise lookup */
                const FengDecl *label_enum_decl =
                    find_visible_type_decl(context->visible_types,
                                           context->visible_type_count,
                                           enum_name, 0U);

                if (label_enum_decl == NULL || !decl_is_enum_type(label_enum_decl)) {
                    ok = resolver_append_error(
                        context,
                        label->token,
                        "AE1107", format_message("match enum target requires enum item reference label of the form 'EnumName.ItemName'"));
                    break;
                }
                if (label_enum_decl != enum_decl) {
                    ok = resolver_append_error(
                        context,
                        label->token,
                        "AE1109", format_message("match label references enum '%.*s' but target type is enum '%.*s'",
                                       (int)label_enum_decl->as.enum_decl.name.length,
                                       label_enum_decl->as.enum_decl.name.data,
                                       (int)enum_decl->as.enum_decl.name.length,
                                       enum_decl->as.enum_decl.name.data));
                    break;
                }
                {
                    const FengEnumItem *item = find_enum_item_decl(enum_decl, item_name);
                    const FengSemanticEnumItemInfo *item_info;

                    if (item == NULL) {
                        ok = resolver_append_error(
                            context,
                            label->token,
                            "AE0404", format_message("enum '%.*s' has no item '%.*s'",
                                           (int)enum_decl->as.enum_decl.name.length,
                                           enum_decl->as.enum_decl.name.data,
                                           (int)item_name.length,
                                           item_name.data));
                        break;
                    }
                    item_info = feng_semantic_find_enum_item_info(context->analysis,
                                                                   enum_decl,
                                                                   item_name);
                    if (item_info == NULL) {
                        ok = false;
                        break;
                    }
                    record.enum_decl = enum_decl;
                    record.enum_item_name = item_name;
                    record.enum_item_value = item_info->value;
                }
            }

            if (record_count == record_capacity) {
                size_t new_capacity = (record_capacity == 0U) ? 4U : (record_capacity * 2U);
                MatchLabelRecord *grown =
                    (MatchLabelRecord *)realloc(records, new_capacity * sizeof(MatchLabelRecord));
                if (grown == NULL) {
                    ok = false;
                    break;
                }
                records = grown;
                record_capacity = new_capacity;
            }
            records[record_count] = record;
            record_count += 1U;
        }

        if (ok) {
            ok = validate_match_label_records(context, target_type, records, record_count);
        }
        free(records);
        if (!ok) {
            return false;
        }
        return true;
    }

    if (match_target_type_is_allowed(context, target_type)) {
        /* int / bool / string target: reuse MatchLabelRecord collection by
         * wrapping match_op labels into a single throwaway branch. */
        FengMatchBranch temp_branch;
        MatchLabelRecord *records = NULL;
        size_t record_count = 0U;
        size_t record_capacity = 0U;

        temp_branch.token = expr->token;
        temp_branch.labels = expr->as.match_op.labels;
        temp_branch.label_count = expr->as.match_op.label_count;
        temp_branch.body = NULL;
        temp_branch.has_binding = false;
        temp_branch.binding_name = (FengSlice){NULL, 0U};
        memset(&temp_branch.binding_token, 0, sizeof(temp_branch.binding_token));
        temp_branch.binding_mutability = FENG_MUTABILITY_LET;

        ok = collect_match_branch_label_records(context,
                                                 &temp_branch,
                                                 0U,
                                                 &records,
                                                 &record_count,
                                                 &record_capacity);
        if (ok) {
            ok = validate_match_label_records(context, target_type, records, record_count);
        }
        free(records);
        if (!ok) {
            return false;
        }
        return true;
    }

    {
        char *target_name = format_inferred_expr_type_name(target_type, context->pointer_size);
        char *message = format_message(
            "match target type '%s' is not allowed; allowed types are integers, 'string', 'bool' and enum",
            target_name != NULL ? target_name : "<unknown>");

        free(target_name);
        return resolver_append_error(context, target->token, "AE0050", message);
    }
}

/* Register a visible match binding into the current scope. Computes the
 * narrowed member subset from the match_op's target type and labels; for
 * single-member subsets binds to that member's type directly, for multi-
 * member subsets binds to the union's original type with a narrowing set. */
static bool register_visible_match_binding(ResolveContext *context,
                                           const VisibleMatchBinding *binding) {
    const FengExpr *match_op = binding->match_op;
    const FengExpr *target = match_op->as.match_op.target;
    InferredExprType target_type;
    const FengDecl *union_decl = NULL;
    const FengTypeRef *union_spec_type_ref = NULL;
    const FengUnionSpecInfo *info = NULL;
    bool *active_members = NULL;
    size_t member_index;
    size_t label_index;
    bool ok;

    if (match_op == NULL || target == NULL) {
        return false;
    }
    target_type = infer_expr_type(context, target);
    if (!inferred_expr_type_is_known(target_type)) {
        return false;
    }
    if (target_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        union_decl = resolve_union_spec_type_ref_decl(context, target_type.type_ref);
        union_spec_type_ref = target_type.type_ref;
    } else if (target_type.kind == FENG_INFERRED_EXPR_TYPE_DECL &&
               target_type.type_decl != NULL &&
               target_type.type_decl->kind == FENG_DECL_SPEC &&
               target_type.type_decl->as.spec_decl.form == FENG_SPEC_FORM_UNION) {
        union_decl = target_type.type_decl;
        if (target->kind == FENG_EXPR_IDENTIFIER) {
            const LocalNameEntry *target_local =
                resolver_find_local_name_entry(context, target->as.identifier);
            if (target_local != NULL &&
                target_local->type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
                union_spec_type_ref = target_local->type.type_ref;
            }
        }
        if (union_spec_type_ref == NULL && context->analysis != NULL) {
            const FengSemanticTypeFact *target_fact =
                feng_semantic_lookup_type_fact(context->analysis, target);
            if (target_fact != NULL &&
                target_fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF) {
                union_spec_type_ref = target_fact->type_ref;
            }
        }
    }
    if (union_decl == NULL) {
        return false;
    }
    if (union_spec_type_ref != NULL &&
        resolve_union_spec_type_ref_decl(context, union_spec_type_ref) != union_decl) {
        union_spec_type_ref = NULL;
    }
    info = feng_semantic_lookup_union_spec_info(context->analysis, union_decl);
    if (info == NULL || info->member_count == 0U) {
        return false;
    }
    active_members = (bool *)calloc(info->member_count, sizeof(*active_members));
    if (active_members == NULL) {
        return false;
    }
    for (label_index = 0U; label_index < match_op->as.match_op.label_count; ++label_index) {
        const FengMatchLabel *label = &match_op->as.match_op.labels[label_index];
        size_t resolved_index = info->member_count;

        if (!resolve_union_match_label_index(context,
                                              info,
                                              union_spec_type_ref,
                                              label,
                                              &resolved_index)) {
            free(active_members);
            return false;
        }
        if (resolved_index >= info->member_count) {
            free(active_members);
            return false;
        }
        active_members[resolved_index] = true;
    }
    /* Check if any label has a chain for deepest-type narrowing. */
    const FengTypeRef *deepest_chain_type = NULL;

    for (label_index = 0U; label_index < match_op->as.match_op.label_count; ++label_index) {
        const FengMatchLabel *label = &match_op->as.match_op.labels[label_index];

        if (label->type_chain_count > 0U) {
            deepest_chain_type = label->type_chain[label->type_chain_count - 1U];
            break;
        }
    }
    {
        size_t active_count = union_active_member_count(active_members, info->member_count);
        if (active_count == 0U) {
            free(active_members);
            return false;
        }
        if (active_count == 1U) {
            if (deepest_chain_type != NULL) {
                /* Chain label: narrow to deepest type in chain. */
                ok = resolver_declare_local_entry(
                    context,
                    match_op->as.match_op.binding_token,
                    binding->name,
                    inferred_expr_type_from_type_ref(deepest_chain_type),
                    binding->mutability,
                    target,
                    NULL);
            } else {
                member_index = union_first_active_member_index(active_members, info->member_count);
                const FengTypeRef *member_type_ref = substitute_spec_member_type_ref_for_instance(
                    context,
                    info->spec_decl,
                    union_spec_type_ref,
                    info->members[member_index].type_ref);
                ok = resolver_declare_local_entry(
                    context,
                    match_op->as.match_op.binding_token,
                    binding->name,
                    inferred_expr_type_from_type_ref(member_type_ref),
                    binding->mutability,
                    target,
                    NULL);
            }
        } else {
            const UnionNarrowingSet *narrowing = resolver_create_union_narrowing(
                context,
                info->spec_decl,
                active_members,
                info->member_count);
            ok = narrowing != NULL &&
                 resolver_declare_local_entry(
                     context,
                     match_op->as.match_op.binding_token,
                     binding->name,
                     target_type,
                     binding->mutability,
                     target,
                     narrowing);
        }
    }
    free(active_members);
    return ok;
}

static bool type_ref_is_numeric(const FengTypeRef *type_ref, size_t pointer_size) {
    const char *builtin_name = type_ref_builtin_canonical_name(type_ref, pointer_size);

    return builtin_name != NULL && builtin_type_name_is_numeric(slice_from_cstr(builtin_name));
}

static bool array_cast_writability_subset(const FengTypeRef *source,
                                          const FengTypeRef *target) {
    /* docs/specifications/feng-builtin-type.md §5: an array cast may STRIP `!` from any
     * layer but must never ADD `!`. Element type and depth must match. */
    if (source == NULL || target == NULL) {
        return false;
    }
    if (source->kind != target->kind) {
        return false;
    }
    if (source->kind != FENG_TYPE_REF_ARRAY) {
        /* Inner-most layer reached. Element types must match exactly. */
        return type_ref_equals(source, target);
    }
    if (target->array_element_writable && !source->array_element_writable) {
        return false;
    }
    return array_cast_writability_subset(source->as.inner, target->as.inner);
}

static bool cast_expr_types_are_valid(ResolveContext *context,
                                      InferredExprType value_type,
                                      const FengTypeRef *target_type) {
    const char *target_builtin = type_ref_builtin_canonical_name(target_type, context->pointer_size);
    const FengDecl *source_callable_spec = NULL;
    const FengDecl *target_callable_spec = NULL;

    if (inferred_expr_type_matches_type_ref(context, value_type, target_type)) {
        return true;
    }
    if (value_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        source_callable_spec = resolve_callable_spec_type_ref_decl(context, value_type.type_ref);
        target_callable_spec = resolve_callable_spec_type_ref_decl(context, target_type);
        if (source_callable_spec != NULL && target_callable_spec != NULL &&
            function_type_refs_have_equal_signature(context, value_type.type_ref, target_type)) {
            return true;
        }
    }
    if (inferred_tuple_type_has_equal_shape(context, value_type, target_type)) {
        return true;
    }
    if (inferred_expr_type_is_enum(context, value_type) && target_builtin != NULL &&
        builtin_type_name_is_integer(slice_from_cstr(target_builtin))) {
        return true;
    }
    if (inferred_expr_type_is_numeric(value_type) && type_ref_is_numeric(target_type, context->pointer_size)) {
        return true;
    }
    /* Array writability strip: source is a known array type, target is also
     * an array of identical element type and depth, and target's writability
     * mask is a subset of source's. */
    if (target_type != NULL && target_type->kind == FENG_TYPE_REF_ARRAY &&
        value_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
        value_type.type_ref != NULL &&
        value_type.type_ref->kind == FENG_TYPE_REF_ARRAY) {
        return array_cast_writability_subset(value_type.type_ref, target_type);
    }
    return false;
}

static bool validate_cast_expr(ResolveContext *context, const FengExpr *expr) {
    InferredExprType value_type;
    const FengDecl *target_callable_spec;
    char *value_type_name;
    char *target_type_name;
    char *message;

    target_callable_spec = resolve_function_type_decl(context,
                                                      expr->as.cast.type);
    if (target_callable_spec != NULL) {
        CallableValueResolution resolution = resolve_expr_callable_value(
            context,
            expr->as.cast.value,
            expr->as.cast.type);

        /* A cast target is an explicit callable-form context. It may form an
         * unbound top-level function or bound method value directly; generic
         * sources must already carry explicit callable-local type arguments. */
        if (resolution.kind == FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE) {
            record_callable_spec_coercion_site(context,
                                               expr->as.cast.value,
                                               expr->as.cast.type);
            return true;
        }
    }

    value_type = infer_expr_type(context, expr->as.cast.value);
    if (expr->as.cast.value != NULL &&
        expr->as.cast.value->kind == FENG_EXPR_TUPLE_LITERAL) {
        return validate_tuple_literal_expr_against_type(context,
                                                        expr->as.cast.value,
                                                        expr->as.cast.type);
    }
    if (cast_expr_types_are_valid(context, value_type, expr->as.cast.type)) {
        record_object_spec_coercion_site_if_applicable(
            context,
            expr->as.cast.value,
            expr->as.cast.type,
            FENG_SPEC_OBJECT_SUBJECT_STORAGE_BOX_OWNER);
        return true;
    }

    value_type_name = format_inferred_expr_type_name(value_type, context->pointer_size);
    target_type_name = format_type_ref_name(expr->as.cast.type);
    message = format_message("cast from '%s' to '%s' is not allowed",
                             value_type_name != NULL ? value_type_name : "<unknown>",
                             target_type_name != NULL ? target_type_name : "<type>");
    free(value_type_name);
    free(target_type_name);
    return resolver_append_error(context, expr->token, "AE1023", message);
}

static bool validate_index_expr(ResolveContext *context, const FengExpr *expr) {
    InferredExprType object_type;
    char *object_type_name;
    InferredExprType index_type;
    char *index_type_name;
    char *message;

    if (expr->as.index.object != NULL &&
        expr->as.index.object->kind == FENG_EXPR_GENERIC_TARGET) {
        char *target_name = format_expr_target_name(
            expr->as.index.object->as.generic_target.target);
        bool ok = resolver_append_error(
            context,
            expr->as.index.object->token,
            "AE1016",
            format_message(
                "explicit generic target '%s' cannot be used as an index target",
                target_name != NULL ? target_name : "<expression>"));

        free(target_name);
        return ok && false;
    }

    if (resolve_indexed_array_element_type_ref(context, expr->as.index.object) == NULL) {
        object_type = infer_expr_type(context, expr->as.index.object);
        object_type_name = format_inferred_expr_type_name(object_type, context->pointer_size);
        message = format_message("index expression target must have array type, got '%s'",
                                 object_type_name != NULL ? object_type_name : "<unknown>");
        free(object_type_name);
        return resolver_append_error(context, expr->token, "AE1021", message) && false;
    }

    index_type = infer_expr_type(context, expr->as.index.index);
    if (inferred_expr_type_is_integer(index_type)) {
        return true;
    }

    index_type_name = format_inferred_expr_type_name(index_type, context->pointer_size);
    message = format_message("index expression requires an integer operand, got '%s'",
                             index_type_name != NULL ? index_type_name : "<unknown>");
    free(index_type_name);
    return resolver_append_error(context, expr->token, "AE1022", message) && false;
}

static bool validate_stmt_condition_expr(ResolveContext *context,
                                         const FengExpr *condition,
                                         const char *code,
                                         const char *statement_kind) {
    InferredExprType condition_type;
    char *condition_type_name;
    char *message;

    if (condition == NULL) {
        return true;
    }

    condition_type = infer_expr_type(context, condition);
    if (inferred_expr_type_is_bool(condition_type)) {
        return true;
    }

    condition_type_name = format_inferred_expr_type_name(condition_type, context->pointer_size);
    message = format_message("%s condition must have type 'bool', got '%s'",
                             statement_kind,
                             condition_type_name != NULL ? condition_type_name : "<unknown>");
    free(condition_type_name);
    return resolver_append_error(context, condition->token, code, message);
}

static bool validate_return_stmt(ResolveContext *context, const FengStmt *stmt) {
    InferredExprType return_type;
    char *expected_type_name;
    char *existing_type_name;
    char *return_type_name;
    char *message;
    char *expr_name;

    if (context->current_callable_signature == NULL) {
        return true;
    }

    if (context->current_callable_body_member != NULL &&
        (context->current_callable_body_member->kind == FENG_TYPE_MEMBER_CONSTRUCTOR ||
         context->current_callable_body_member->kind == FENG_TYPE_MEMBER_FINALIZER) &&
        stmt->as.return_value != NULL) {
        const char *member_kind_name =
            (context->current_callable_body_member->kind == FENG_TYPE_MEMBER_CONSTRUCTOR)
                ? "constructor"
                : "finalizer";
        return resolver_append_error(
            context,
            stmt->token,
            "AE0501", format_message("%s body must use 'return;' without a value", member_kind_name));
    }

    if (stmt->as.return_value != NULL &&
        expr_is_borrowed_data_pointer_value(context, stmt->as.return_value, 0U)) {
        expr_name = format_expr_target_name(stmt->as.return_value);
        if (!resolver_append_error(
                context,
                stmt->as.return_value->token,
                "AE1314", format_message(
                    "expression '%s' is a borrowed data pointer formed by '&'; borrowed data pointers are only guaranteed valid for the current extern call and cannot be returned; retain the original owner instead of returning the raw pointer",
                    expr_name != NULL ? expr_name : "<expression>"))) {
            free(expr_name);
            return false;
        }

        free(expr_name);
        return true;
    }

    if (context->current_callable_signature->return_type != NULL) {
        if (stmt->as.return_value == NULL) {
            if (type_ref_is_void(context->current_callable_signature->return_type)) {
                return true;
            }

            expected_type_name =
                format_type_ref_name(context->current_callable_signature->return_type);
            message = format_message("return statement does not match expected type '%s'",
                                     expected_type_name != NULL ? expected_type_name : "<type>");
            free(expected_type_name);
            return resolver_append_error(context, stmt->token, "AE0501", message) && false;
        }

        if (type_ref_is_void(context->current_callable_signature->return_type)) {
            return resolver_append_error(
                       context,
                       stmt->token,
                       "AE0501",
                       duplicate_cstr("return statement does not match expected type 'void'")) &&
                   false;
        }

        return validate_expr_against_expected_type(context,
                                                   stmt->as.return_value,
                                                   context->current_callable_signature->return_type);
    }

    context->current_callable_saw_return = true;
    if (stmt->as.return_value != NULL && stmt->as.return_value->kind == FENG_EXPR_LAMBDA) {
        return report_lambda_requires_callable_spec_target(context,
                                                           stmt->as.return_value,
                                                           "a return statement");
    }
    return_type = stmt->as.return_value != NULL ? infer_expr_type(context, stmt->as.return_value)
                                                : inferred_expr_type_builtin("void");
    if (stmt->as.return_value != NULL &&
        return_type.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA) {
        return report_lambda_requires_callable_spec_target(context,
                                                           stmt->as.return_value,
                                                           "a return statement");
    }
    if (stmt->as.return_value != NULL &&
        !validate_untyped_callable_value_expr(context,
                                              stmt->as.return_value)) {
        return false;
    }
    if (stmt->as.return_value != NULL &&
        !validate_untyped_tuple_literal_expr(context, stmt->as.return_value)) {
        return false;
    }
    if (!inferred_expr_type_is_known(return_type)) {
        return true;
    }
    /* A block Lambda can receive its callable target only after overload
     * selection. Persist each value-return type while the real lexical scope
     * is active so that delayed target validation does not need to replay
     * body-local bindings with a second scope model. */
    if (stmt->as.return_value != NULL &&
        context->lambda_frame_count > 0U &&
        !record_type_fact_for_site(
            context, stmt->as.return_value, return_type)) {
        return false;
    }
    if (!inferred_expr_type_is_known(context->current_callable_inferred_return_type)) {
        context->current_callable_inferred_return_type = return_type;
        return true;
    }
    if (inferred_expr_types_equal(context,
                                  context->current_callable_inferred_return_type,
                                  return_type)) {
        return true;
    }

    existing_type_name =
        format_inferred_expr_type_name(context->current_callable_inferred_return_type, context->pointer_size);
    return_type_name = format_inferred_expr_type_name(return_type, context->pointer_size);
    message = format_message("callable '%.*s' has conflicting inferred return types '%s' and '%s'",
                             (int)context->current_callable_signature->name.length,
                             context->current_callable_signature->name.data,
                             existing_type_name != NULL ? existing_type_name : "<type>",
                             return_type_name != NULL ? return_type_name : "<type>");
    free(existing_type_name);
    free(return_type_name);
    return resolver_append_error(context, stmt->token, "AE0504", message) && false;
}

/* Structured control-flow outcomes used by the compile-time callable
 * fallthrough check. A statement can expose more than one outcome because
 * different branches may return, throw, transfer loop control, or complete
 * normally. Nested loops consume their own break/continue outcomes. */
typedef enum CallableFlowOutcome {
    CALLABLE_FLOW_NORMAL = 1U << 0U,
    CALLABLE_FLOW_RETURN = 1U << 1U,
    CALLABLE_FLOW_THROW = 1U << 2U,
    CALLABLE_FLOW_BREAK = 1U << 3U,
    CALLABLE_FLOW_CONTINUE = 1U << 4U,
    /* A locally provable infinite path. Callable fallthrough treats it as
     * terminal, while expression result blocks deliberately do not accept it
     * as a substitute for the user-approved return/throw outcomes. */
    CALLABLE_FLOW_NONTERMINATING = 1U << 5U
} CallableFlowOutcome;

typedef unsigned CallableFlowOutcomes;

static CallableFlowOutcomes callable_expr_flow(const FengExpr *expr);
static CallableFlowOutcomes callable_block_flow(const FengBlock *block);

/* Sequence a following operation only across paths on which the preceding
 * operation completed normally; all already-terminal outcomes are retained. */
static CallableFlowOutcomes callable_flow_sequence(CallableFlowOutcomes preceding,
                                                   CallableFlowOutcomes following) {
    CallableFlowOutcomes result = preceding & ~CALLABLE_FLOW_NORMAL;

    if ((preceding & CALLABLE_FLOW_NORMAL) != 0U) {
        result |= following;
    }
    return result;
}

/* Return true only for the exact boolean literal required by the function
 * specification. Optimizer constant folding deliberately does not affect
 * language-level fallthrough acceptance. */
static bool callable_expr_is_true_literal(const FengExpr *expr) {
    return expr != NULL && expr->kind == FENG_EXPR_BOOL && expr->as.boolean;
}

/* Return true for the two catch-all forms: anonymous `catch { ... }` and
 * bound `catch error: unknown { ... }`. Semantic validation separately keeps
 * either form last in its catch sequence. */
static bool callable_catch_clause_matches_all(
    const FengTryCatchClause *clause) {
    return clause != NULL &&
           (clause->type == NULL || type_ref_is_unknown(clause->type));
}

/* Merge the outcomes of one expression. Calls conservatively expose both a
 * normal and an exceptional result; this makes surrounding catch bodies
 * reachable without introducing an exception-effect runtime mechanism. */
static CallableFlowOutcomes callable_expr_flow(const FengExpr *expr) {
    CallableFlowOutcomes flow;
    size_t index;

    if (expr == NULL) {
        return CALLABLE_FLOW_NORMAL;
    }

    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER:
        case FENG_EXPR_SELF:
        case FENG_EXPR_BOOL:
        case FENG_EXPR_INTEGER:
        case FENG_EXPR_FLOAT:
        case FENG_EXPR_STRING:
        case FENG_EXPR_LAMBDA:
            return CALLABLE_FLOW_NORMAL;

        case FENG_EXPR_ARRAY_LITERAL:
            flow = CALLABLE_FLOW_NORMAL;
            for (index = 0U; index < expr->as.array_literal.count; ++index) {
                flow = callable_flow_sequence(
                    flow, callable_expr_flow(expr->as.array_literal.items[index]));
            }
            return flow;

        case FENG_EXPR_TUPLE_LITERAL:
            flow = CALLABLE_FLOW_NORMAL;
            for (index = 0U; index < expr->as.tuple_literal.count; ++index) {
                flow = callable_flow_sequence(
                    flow, callable_expr_flow(expr->as.tuple_literal.items[index]));
            }
            return flow;

        case FENG_EXPR_OBJECT_LITERAL:
            flow = callable_expr_flow(expr->as.object_literal.target);
            for (index = 0U; index < expr->as.object_literal.field_count; ++index) {
                flow = callable_flow_sequence(
                    flow,
                    callable_expr_flow(expr->as.object_literal.fields[index].value));
            }
            return flow;

        case FENG_EXPR_GENERIC_TARGET:
            return callable_expr_flow(expr->as.generic_target.target);

        case FENG_EXPR_CALL:
            flow = callable_expr_flow(expr->as.call.callee);
            for (index = 0U; index < expr->as.call.arg_count; ++index) {
                flow = callable_flow_sequence(
                    flow, callable_expr_flow(expr->as.call.args[index]));
            }
            return callable_flow_sequence(
                flow, CALLABLE_FLOW_NORMAL | CALLABLE_FLOW_THROW);

        case FENG_EXPR_MEMBER:
            return callable_expr_flow(expr->as.member.object);

        case FENG_EXPR_INDEX:
            return callable_flow_sequence(
                callable_expr_flow(expr->as.index.object),
                callable_expr_flow(expr->as.index.index));

        case FENG_EXPR_UNARY:
            return callable_expr_flow(expr->as.unary.operand);

        case FENG_EXPR_BINARY: {
            CallableFlowOutcomes left = callable_expr_flow(expr->as.binary.left);
            CallableFlowOutcomes right = callable_expr_flow(expr->as.binary.right);

            if (expr->as.binary.op == FENG_TOKEN_AND_AND ||
                expr->as.binary.op == FENG_TOKEN_OR_OR) {
                CallableFlowOutcomes result = left & ~CALLABLE_FLOW_NORMAL;

                if ((left & CALLABLE_FLOW_NORMAL) != 0U) {
                    bool must_evaluate_right =
                        expr->as.binary.left != NULL &&
                        expr->as.binary.left->kind == FENG_EXPR_BOOL &&
                        ((expr->as.binary.op == FENG_TOKEN_AND_AND &&
                          expr->as.binary.left->as.boolean) ||
                         (expr->as.binary.op == FENG_TOKEN_OR_OR &&
                          !expr->as.binary.left->as.boolean));

                    result |= right;
                    if (!must_evaluate_right) {
                        result |= CALLABLE_FLOW_NORMAL;
                    }
                }
                return result;
            }
            return callable_flow_sequence(left, right);
        }

        case FENG_EXPR_CAST:
            return callable_expr_flow(expr->as.cast.value);

        case FENG_EXPR_IF: {
            CallableFlowOutcomes condition =
                callable_expr_flow(expr->as.if_expr.condition);
            CallableFlowOutcomes result = condition & ~CALLABLE_FLOW_NORMAL;

            if ((condition & CALLABLE_FLOW_NORMAL) != 0U) {
                result |= callable_block_flow(expr->as.if_expr.then_block);
                result |= callable_block_flow(expr->as.if_expr.else_block);
            }
            return result;
        }

        case FENG_EXPR_MATCH: {
            CallableFlowOutcomes target =
                callable_expr_flow(expr->as.match_expr.target);
            CallableFlowOutcomes result = target & ~CALLABLE_FLOW_NORMAL;

            if ((target & CALLABLE_FLOW_NORMAL) != 0U) {
                for (index = 0U;
                     index < expr->as.match_expr.branch_count;
                     ++index) {
                    result |= callable_block_flow(
                        expr->as.match_expr.branches[index].body);
                }
                result |= callable_block_flow(expr->as.match_expr.else_block);
            }
            return result;
        }

        case FENG_EXPR_TRY: {
            CallableFlowOutcomes body =
                callable_expr_flow(expr->as.try_expr.body);
            CallableFlowOutcomes result = body & ~CALLABLE_FLOW_THROW;
            bool catches_all = false;

            if ((body & CALLABLE_FLOW_THROW) != 0U) {
                for (index = 0U;
                     index < expr->as.try_expr.clause_count;
                     ++index) {
                    result |= callable_block_flow(
                        expr->as.try_expr.clauses[index].body);
                    if (callable_catch_clause_matches_all(
                            &expr->as.try_expr.clauses[index])) {
                        catches_all = true;
                        break;
                    }
                }
                if (!catches_all) {
                    result |= CALLABLE_FLOW_THROW;
                }
            }
            return result;
        }

        case FENG_EXPR_ARRAY_NEW:
            return callable_expr_flow(expr->as.array_new.size);

        case FENG_EXPR_MATCH_OP:
            return callable_expr_flow(expr->as.match_op.target);
    }

    return CALLABLE_FLOW_NORMAL;
}

/* Merge the outcomes of one statement, consuming loop-local transfers at the
 * loop that owns them. */
static CallableFlowOutcomes callable_stmt_flow(const FengStmt *stmt) {
    CallableFlowOutcomes flow;
    CallableFlowOutcomes body;
    size_t index;

    if (stmt == NULL) {
        return CALLABLE_FLOW_NORMAL;
    }

    switch (stmt->kind) {
        case FENG_STMT_BLOCK:
            return callable_block_flow(stmt->as.block);

        case FENG_STMT_BINDING:
            return callable_expr_flow(stmt->as.binding.initializer);

        case FENG_STMT_ASSIGN:
            return callable_flow_sequence(
                callable_expr_flow(stmt->as.assign.target),
                callable_expr_flow(stmt->as.assign.value));

        case FENG_STMT_EXPR:
        case FENG_STMT_TRY:
            return callable_expr_flow(stmt->as.expr);

        case FENG_STMT_IF:
            flow = 0U;
            for (index = 0U;
                 index < stmt->as.if_stmt.clause_count;
                 ++index) {
                flow |= callable_expr_flow(
                            stmt->as.if_stmt.clauses[index].condition) &
                        ~CALLABLE_FLOW_NORMAL;
                flow |= callable_block_flow(
                    stmt->as.if_stmt.clauses[index].block);
            }
            if (stmt->as.if_stmt.else_block != NULL) {
                flow |= callable_block_flow(stmt->as.if_stmt.else_block);
            } else {
                flow |= CALLABLE_FLOW_NORMAL;
            }
            return flow;

        case FENG_STMT_MATCH:
            flow = callable_expr_flow(stmt->as.match_stmt.target) &
                   ~CALLABLE_FLOW_NORMAL;
            for (index = 0U;
                 index < stmt->as.match_stmt.branch_count;
                 ++index) {
                flow |= callable_block_flow(
                    stmt->as.match_stmt.branches[index].body);
            }
            if (stmt->as.match_stmt.else_block != NULL) {
                flow |= callable_block_flow(stmt->as.match_stmt.else_block);
            } else {
                flow |= CALLABLE_FLOW_NORMAL;
            }
            return flow;

        case FENG_STMT_WHILE: {
            CallableFlowOutcomes condition =
                callable_expr_flow(stmt->as.while_stmt.condition);
            CallableFlowOutcomes result = condition & ~CALLABLE_FLOW_NORMAL;

            if ((condition & CALLABLE_FLOW_NORMAL) == 0U) {
                return result;
            }
            body = callable_block_flow(stmt->as.while_stmt.body);
            result |= body & (CALLABLE_FLOW_RETURN |
                              CALLABLE_FLOW_THROW |
                              CALLABLE_FLOW_NONTERMINATING);
            if (!callable_expr_is_true_literal(stmt->as.while_stmt.condition)) {
                result |= CALLABLE_FLOW_NORMAL;
            } else {
                if ((body & CALLABLE_FLOW_BREAK) != 0U) {
                    result |= CALLABLE_FLOW_NORMAL;
                }
                if ((body & (CALLABLE_FLOW_NORMAL |
                             CALLABLE_FLOW_CONTINUE)) != 0U) {
                    result |= CALLABLE_FLOW_NONTERMINATING;
                }
            }
            return result;
        }

        case FENG_STMT_FOR: {
            CallableFlowOutcomes prefix = callable_stmt_flow(
                stmt->as.for_stmt.init);
            CallableFlowOutcomes result;

            if (stmt->as.for_stmt.is_for_in) {
                CallableFlowOutcomes iterator =
                    callable_expr_flow(stmt->as.for_stmt.iter_expr);

                body = callable_block_flow(stmt->as.for_stmt.body);
                result = CALLABLE_FLOW_NORMAL |
                         (body & (CALLABLE_FLOW_RETURN |
                                  CALLABLE_FLOW_THROW |
                                  CALLABLE_FLOW_NONTERMINATING));
                return callable_flow_sequence(
                    prefix, callable_flow_sequence(iterator, result));
            }

            {
                CallableFlowOutcomes condition =
                    callable_expr_flow(stmt->as.for_stmt.condition);
                CallableFlowOutcomes update =
                    callable_stmt_flow(stmt->as.for_stmt.update);
                bool condition_is_true =
                    stmt->as.for_stmt.condition == NULL ||
                    callable_expr_is_true_literal(stmt->as.for_stmt.condition);

                result = condition & ~CALLABLE_FLOW_NORMAL;
                if ((condition & CALLABLE_FLOW_NORMAL) != 0U) {
                    body = callable_block_flow(stmt->as.for_stmt.body);
                    result |= body &
                              (CALLABLE_FLOW_RETURN |
                               CALLABLE_FLOW_THROW |
                               CALLABLE_FLOW_NONTERMINATING);
                    if ((body & (CALLABLE_FLOW_NORMAL |
                                 CALLABLE_FLOW_CONTINUE)) != 0U) {
                        result |= update & (CALLABLE_FLOW_RETURN |
                                            CALLABLE_FLOW_THROW |
                                            CALLABLE_FLOW_NONTERMINATING);
                        if (condition_is_true &&
                            (update & CALLABLE_FLOW_NORMAL) != 0U) {
                            result |= CALLABLE_FLOW_NONTERMINATING;
                        }
                    }
                    if (!condition_is_true ||
                        (body & CALLABLE_FLOW_BREAK) != 0U) {
                        result |= CALLABLE_FLOW_NORMAL;
                    }
                }
                return callable_flow_sequence(prefix, result);
            }
        }

        case FENG_STMT_RETURN:
            flow = callable_expr_flow(stmt->as.return_value);
            return (flow & ~CALLABLE_FLOW_NORMAL) |
                   (((flow & CALLABLE_FLOW_NORMAL) != 0U)
                        ? CALLABLE_FLOW_RETURN
                        : 0U);

        case FENG_STMT_THROW:
            flow = callable_expr_flow(stmt->as.throw_value);
            return (flow & ~CALLABLE_FLOW_NORMAL) |
                   (((flow & CALLABLE_FLOW_NORMAL) != 0U)
                        ? CALLABLE_FLOW_THROW
                        : 0U);

        case FENG_STMT_BREAK:
            return CALLABLE_FLOW_BREAK;

        case FENG_STMT_CONTINUE:
            return CALLABLE_FLOW_CONTINUE;

        case FENG_STMT_DEFER:
            return CALLABLE_FLOW_NORMAL;
    }

    return CALLABLE_FLOW_NORMAL;
}

/* Evaluate a block in source order. Statements after paths that have already
 * terminated do not affect those paths or make an unreachable break count. */
static CallableFlowOutcomes callable_block_flow(const FengBlock *block) {
    CallableFlowOutcomes flow = CALLABLE_FLOW_NORMAL;
    size_t index;

    if (block == NULL) {
        return flow;
    }
    for (index = 0U; index < block->statement_count; ++index) {
        flow = callable_flow_sequence(
            flow, callable_stmt_flow(block->statements[index]));
    }
    return flow;
}

/* Classify one expression result block from its complete reachable control
 * flow. Semantic validation and Codegen call this shared pure AST query so a
 * trailing token pattern can never make the two phases disagree. */
FengSemanticResultBlockFlow feng_semantic_classify_result_block(
    const FengBlock *block) {
    FengSemanticResultBlockFlow result = {
        FENG_SEMANTIC_RESULT_BLOCK_MISSING,
        NULL
    };
    CallableFlowOutcomes outcomes;
    const FengStmt *last = NULL;

    if (block == NULL) {
        return result;
    }
    if (block->statement_count > 0U) {
        last = block->statements[block->statement_count - 1U];
    }
    outcomes = callable_block_flow(block);

    if ((outcomes & CALLABLE_FLOW_NORMAL) != 0U ||
        ((outcomes & (CALLABLE_FLOW_BREAK | CALLABLE_FLOW_CONTINUE)) != 0U &&
         last != NULL && last->kind == FENG_STMT_EXPR)) {
        /* An unconsumed break/continue is already rejected by the expression
         * branch boundary. Preserve a syntactic final result solely for
         * diagnostic recovery so that invalid input does not cascade into an
         * unrelated missing-result/type error. Legal loop-local transfers are
         * consumed by callable_stmt_flow before reaching this point. */
        if (last != NULL && last->kind == FENG_STMT_EXPR) {
            result.kind = FENG_SEMANTIC_RESULT_BLOCK_VALUE;
            result.result_expr = last->as.expr;
        }
        return result;
    }

    if (outcomes != 0U &&
        (outcomes & ~(CALLABLE_FLOW_RETURN | CALLABLE_FLOW_THROW)) == 0U) {
        result.kind = FENG_SEMANTIC_RESULT_BLOCK_RETURN_OR_THROW;
    }
    return result;
}

/* Return true exactly when the callable body retains a normal path to its
 * closing brace. */
static bool callable_body_can_fall_through(const FengBlock *body) {
    return (callable_block_flow(body) & CALLABLE_FLOW_NORMAL) != 0U;
}

/* Normalize a source enum literal only after proving that its mathematical
 * signed value fits the language's fixed i32 enum representation. */
static bool enum_source_literal_as_i32(const FengEnumItem *item,
                                       int64_t *out_value) {
    const uint64_t negative_limit = (uint64_t)INT32_MAX + UINT64_C(1);

    if (item == NULL || out_value == NULL ||
        !item->has_explicit_value_literal) {
        return false;
    }

    if (item->explicit_value_is_negative) {
        if (item->explicit_value_magnitude > negative_limit) {
            return false;
        }
        *out_value = item->explicit_value_magnitude == negative_limit
                         ? (int64_t)INT32_MIN
                         : -(int64_t)item->explicit_value_magnitude;
        return true;
    }

    if (item->explicit_value_magnitude > (uint64_t)INT32_MAX) {
        return false;
    }
    *out_value = (int64_t)item->explicit_value_magnitude;
    return true;
}

static const FengDecl *resolve_inferred_expr_type_decl(const ResolveContext *context,
                                                       InferredExprType expr_type) {
    switch (expr_type.kind) {
        case FENG_INFERRED_EXPR_TYPE_DECL:
            return expr_type.type_decl;

        case FENG_INFERRED_EXPR_TYPE_TYPE_REF:
            return resolve_type_ref_decl(context, expr_type.type_ref);

        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
        case FENG_INFERRED_EXPR_TYPE_BUILTIN:
        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
            return NULL;
    }

    return NULL;
}

static bool ensure_enum_decl_info(ResolveContext *context, const FengDecl *enum_decl) {
    bool saw_explicit = false;
    bool saw_implicit = false;
    int64_t *values = NULL;
    size_t item_index;

    if (context == NULL || context->analysis == NULL || !decl_is_enum_type(enum_decl)) {
        return true;
    }
    if (feng_semantic_lookup_enum_info(context->analysis, enum_decl) != NULL) {
        return true;
    }

    if (enum_decl->as.enum_decl.item_count > 0U) {
        values = (int64_t *)malloc(enum_decl->as.enum_decl.item_count * sizeof(*values));
        if (values == NULL) {
            return false;
        }
    }

    for (item_index = 0U; item_index < enum_decl->as.enum_decl.item_count; ++item_index) {
        const FengEnumItem *item = &enum_decl->as.enum_decl.items[item_index];
        int64_t normalized_value;
        size_t previous_index;

        if (item->has_explicit_value) {
            saw_explicit = true;
        } else {
            saw_implicit = true;
        }
        if (saw_explicit && saw_implicit) {
            free(values);
            return resolver_append_error(
                context,
                item->token,
                "AE0401", format_message("enum '%.*s' cannot mix explicit and implicit item values",
                               (int)enum_decl->as.enum_decl.name.length,
                               enum_decl->as.enum_decl.name.data));
        }

        for (previous_index = 0U; previous_index < item_index; ++previous_index) {
            if (slice_equals(enum_decl->as.enum_decl.items[previous_index].name, item->name)) {
                free(values);
                return resolver_append_error(
                    context,
                    item->token,
                    "AE0402", format_message("enum '%.*s' has duplicate item name '%.*s'",
                                   (int)enum_decl->as.enum_decl.name.length,
                                   enum_decl->as.enum_decl.name.data,
                                   (int)item->name.length,
                                   item->name.data));
            }
        }

        if (item->has_explicit_value && item->has_explicit_value_literal) {
            if (!enum_source_literal_as_i32(item, &normalized_value)) {
                free(values);
                return resolver_append_error(
                    context,
                    item->explicit_value_token,
                    "AE0405", format_message(
                        "enum '%.*s' item '%.*s' value %.*s is outside the 'i32' range",
                        (int)enum_decl->as.enum_decl.name.length,
                        enum_decl->as.enum_decl.name.data,
                        (int)item->name.length,
                        item->name.data,
                        (int)item->explicit_value_source.length,
                        item->explicit_value_source.data));
            }
            values[item_index] = normalized_value;
        } else {
            values[item_index] = item->has_explicit_value
                                     ? item->explicit_value
                                     : (int64_t)item_index;
        }
        for (previous_index = 0U; previous_index < item_index; ++previous_index) {
            if (values[previous_index] == values[item_index]) {
                int64_t duplicate_value = values[item_index];

                free(values);
                return resolver_append_error(
                    context,
                    item->token,
                    "AE0403", format_message("enum '%.*s' has duplicate item value %lld",
                                   (int)enum_decl->as.enum_decl.name.length,
                                   enum_decl->as.enum_decl.name.data,
                                   (long long)duplicate_value));
            }
        }
    }

    for (item_index = 0U; item_index < enum_decl->as.enum_decl.item_count; ++item_index) {
        if (!feng_semantic_record_enum_item_info(context->analysis,
                                                 enum_decl,
                                                 &enum_decl->as.enum_decl.items[item_index],
                                                 item_index,
                                                 values[item_index])) {
            free(values);
            return false;
        }
    }

    free(values);
    return true;
}

static bool record_type_fact_for_site(ResolveContext *context,
                                      const void *site,
                                      InferredExprType expr_type) {
    if (context == NULL || context->analysis == NULL || site == NULL ||
        !inferred_expr_type_is_known(expr_type)) {
        return true;
    }

    switch (expr_type.kind) {
        case FENG_INFERRED_EXPR_TYPE_BUILTIN: {
            const char *canonical_name = canonical_builtin_type_name(
                expr_type.builtin_name, context->pointer_size);
            FengSlice recorded_name = canonical_name != NULL
                                          ? slice_from_cstr(canonical_name)
                                          : expr_type.builtin_name;

            /* Type facts are consumed after expression inference by symbol
             * export and Codegen. Store the same width-explicit identity used
             * by normal type resolution so aliases such as `int` cannot leak
             * into those later compiler phases. */
            return feng_semantic_record_type_fact(context->analysis,
                                                  site,
                                                  FENG_SEMANTIC_TYPE_FACT_BUILTIN,
                                                  recorded_name,
                                                  NULL,
                                                  NULL);
        }

        case FENG_INFERRED_EXPR_TYPE_TYPE_REF: {
            /* The type_ref carried by InferredExprType may be a synthetic
             * type_ref owned by the ResolveContext (e.g., the instance_ref
             * built by infer_call_expr_type for constructor calls with
             * explicit generic arguments).  Type facts outlive the
             * ResolveContext (they live in the Analysis), so we must clone
             * the type_ref and transfer ownership to Analysis-level
             * lifetime before storing the pointer in the fact. */
            FengTypeRef *clone = clone_type_ref_for_inference(expr_type.type_ref);

            if (clone == NULL) {
                return false;
            }
            if (!analysis_track_synthetic_type_ref(context->analysis, clone)) {
                free_synthetic_type_ref(clone);
                return false;
            }
            return feng_semantic_record_type_fact(context->analysis,
                                                  site,
                                                  FENG_SEMANTIC_TYPE_FACT_TYPE_REF,
                                                  (FengSlice){0},
                                                  clone,
                                                  NULL);
        }

        case FENG_INFERRED_EXPR_TYPE_DECL:
            return feng_semantic_record_type_fact(context->analysis,
                                                  site,
                                                  FENG_SEMANTIC_TYPE_FACT_DECL,
                                                  (FengSlice){0},
                                                  NULL,
                                                  expr_type.type_decl);

        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
            return true;
    }

    return true;
}

static const FengTypeMember *find_type_field_member(const FengDecl *type_decl, FengSlice name) {
    size_t member_index;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }

    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];

        if (!member->is_static &&
            member->kind == FENG_TYPE_MEMBER_FIELD &&
            slice_equals(member->as.field.name, name)) {
            return member;
        }
    }

    return NULL;
}

static const FengTypeMember *find_type_static_field_member(const FengDecl *type_decl, FengSlice name) {
    size_t member_index;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }

    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];

        if (member->is_static &&
            member->kind == FENG_TYPE_MEMBER_FIELD &&
            slice_equals(member->as.field.name, name)) {
            return member;
        }
    }

    return NULL;
}

static const FengTypeMember *find_type_let_field_member(const FengDecl *type_decl, FengSlice name) {
    const FengTypeMember *member = find_type_field_member(type_decl, name);

    if (member == NULL || member->as.field.mutability != FENG_MUTABILITY_LET) {
        return NULL;
    }

    return member;
}

static const FengTypeMember *find_instance_member(const FengDecl *type_decl, FengSlice name) {
    size_t member_index;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }

    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];

        if (!member->is_static &&
            member->kind == FENG_TYPE_MEMBER_FIELD &&
            slice_equals(member->as.field.name, name)) {
            return member;
        }
        if (!member->is_static &&
            member->kind == FENG_TYPE_MEMBER_METHOD &&
            slice_equals(member->as.callable.name, name)) {
            return member;
        }
    }

    return NULL;
}

/* Forward declaration: defined later in the spec satisfaction section. */
static bool spec_collect_closure(const ResolveContext *ctx,
                                 const FengDecl *spec_decl,
                                 const FengDecl ***out_set,
                                 size_t *out_count,
                                 size_t *out_capacity);

/* Find a field/method member declared on an object-form spec, walking parent
 * specs. When requested, out_declaring_spec identifies the object-form spec
 * that originally declares the selected member; spec-seal accessibility is
 * defined by that declaration rather than by the receiver's derived spec
 * view. Callable-form specs have no member surface and return NULL here. */
static const FengTypeMember *find_spec_object_member_with_owner(
    const ResolveContext *context,
    const FengDecl *spec_decl,
    FengSlice name,
    bool include_static,
    const FengDecl **out_declaring_spec) {
    const FengDecl **closure = NULL;
    size_t closure_count = 0U;
    size_t closure_capacity = 0U;
    const FengTypeMember *result = NULL;
    size_t i;
    size_t j;

    if (out_declaring_spec != NULL) {
        *out_declaring_spec = NULL;
    }
    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return NULL;
    }
    if (!spec_collect_closure(context, spec_decl, &closure, &closure_count, &closure_capacity)) {
        free(closure);
        return NULL;
    }

    for (i = 0U; i < closure_count && result == NULL; ++i) {
        const FengDecl *current = closure[i];

        if (current->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            continue;
        }
        for (j = 0U; j < current->as.spec_decl.as.object.member_count; ++j) {
            const FengTypeMember *member = current->as.spec_decl.as.object.members[j];

            if (member->is_static && !include_static) {
                continue;
            }
            if (member->kind == FENG_TYPE_MEMBER_FIELD &&
                slice_equals(member->as.field.name, name)) {
                result = member;
                if (out_declaring_spec != NULL) {
                    *out_declaring_spec = current;
                }
                break;
            }
            if (member->kind == FENG_TYPE_MEMBER_METHOD &&
                slice_equals(member->as.callable.name, name)) {
                result = member;
                if (out_declaring_spec != NULL) {
                    *out_declaring_spec = current;
                }
                break;
            }
        }
    }

    free(closure);
    return result;
}

/* Return the first matching object-spec member without applying access
 * filtering. Callers that expose a member to source code must additionally
 * use find_accessible_spec_object_member or spec_member_is_accessible_from. */
static const FengTypeMember *find_spec_object_member(const ResolveContext *context,
                                                     const FengDecl *spec_decl,
                                                     FengSlice name,
                                                     bool include_static) {
    return find_spec_object_member_with_owner(context,
                                              spec_decl,
                                              name,
                                              include_static,
                                              NULL);
}

/* Find one field in an exact instance/static object-spec member surface. */
static const FengTypeMember *find_spec_object_field_with_owner(
    const ResolveContext *context,
    const FengDecl *spec_decl,
    FengSlice name,
    bool require_static,
    const FengDecl **out_declaring_spec) {
    const FengDecl **closure = NULL;
    size_t closure_count = 0U;
    size_t closure_capacity = 0U;
    const FengTypeMember *result = NULL;

    if (out_declaring_spec != NULL) {
        *out_declaring_spec = NULL;
    }
    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT ||
        !spec_collect_closure(context,
                              spec_decl,
                              &closure,
                              &closure_count,
                              &closure_capacity)) {
        free(closure);
        return NULL;
    }
    for (size_t closure_index = 0U;
         closure_index < closure_count && result == NULL;
         ++closure_index) {
        const FengDecl *current = closure[closure_index];

        for (size_t member_index = 0U;
             member_index < current->as.spec_decl.as.object.member_count;
             ++member_index) {
            const FengTypeMember *candidate =
                current->as.spec_decl.as.object.members[member_index];

            if (candidate == NULL ||
                candidate->kind != FENG_TYPE_MEMBER_FIELD ||
                candidate->is_static != require_static ||
                !slice_equals(candidate->as.field.name, name)) {
                continue;
            }
            result = candidate;
            if (out_declaring_spec != NULL) {
                *out_declaring_spec = current;
            }
            break;
        }
    }
    free(closure);
    return result;
}

/* Exact instantiated surface for one member selected through a spec value or
 * generic constraint. `declaring_spec_type_ref` carries the owner arguments
 * after object-parent or intersection-member projection; member signature
 * substitution must use this ref rather than the outer constraint ref. */
typedef struct SpecMemberSurface {
    const FengTypeMember *member;
    const FengDecl *declaring_spec;
    const FengTypeRef *declaring_spec_type_ref;
} SpecMemberSurface;

/* Find the first named member while preserving the exact generic path from
 * `spec_type_ref` to the spec that declares it. Object-form parents and
 * intersection-form members are both type-ref edges, so the same recursive
 * substitution rule handles direct, inherited, nested, reordered and fixed
 * owner arguments. Declaration validation has already rejected cycles. */
static bool find_spec_member_surface_for_instance(
    ResolveContext *context,
    const FengDecl *spec_decl,
    const FengTypeRef *spec_type_ref,
    FengSlice name,
    bool include_static,
    SpecMemberSurface *out_surface) {
    if (out_surface == NULL || spec_decl == NULL ||
        spec_decl->kind != FENG_DECL_SPEC) {
        return false;
    }

    if (spec_decl->as.spec_decl.form == FENG_SPEC_FORM_OBJECT) {
        const FengDecl *declaring_spec = NULL;
        const FengTypeMember *member = find_spec_object_member_with_owner(
            context, spec_decl, name, include_static, &declaring_spec);
        const FengTypeRef *declaring_ref = spec_type_ref;

        if (member == NULL || declaring_spec == NULL) {
            return false;
        }
        if (declaring_spec != spec_decl) {
            declaring_ref = instantiate_parent_spec_ref_for_instance(
                context, spec_decl, spec_type_ref, declaring_spec);
        }
        out_surface->member = member;
        out_surface->declaring_spec = declaring_spec;
        out_surface->declaring_spec_type_ref = declaring_ref;
        return true;
    }

    if (spec_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
        size_t member_index;

        for (member_index = 0U;
             member_index < spec_decl->as.spec_decl.as.intersection_form.member_count;
             ++member_index) {
            const FengTypeRef *declared_member_ref =
                spec_decl->as.spec_decl.as.intersection_form.members[member_index];
            const FengTypeRef *member_ref =
                substitute_spec_member_type_ref_for_instance(
                    context, spec_decl, spec_type_ref, declared_member_ref);
            const FengDecl *member_decl = resolve_type_ref_decl(context, member_ref);

            if (member_decl != NULL && member_decl->kind == FENG_DECL_SPEC &&
                find_spec_member_surface_for_instance(context,
                                                      member_decl,
                                                      member_ref,
                                                      name,
                                                      include_static,
                                                      out_surface)) {
                return true;
            }
        }
    }

    return false;
}

/* Resolve a bare active type parameter to its complete declared spec
 * constraint. The constraint ref, not the parameter name, is the root of all
 * subsequent owner-argument projection. */
static bool resolve_generic_param_spec_constraint(
    const ResolveContext *context,
    InferredExprType owner_type,
    const FengDecl **out_spec_decl,
    const FengTypeRef **out_spec_type_ref) {
    const TypeParamEntry *type_param;
    const FengDecl *constraint_decl;

    if (out_spec_decl == NULL || out_spec_type_ref == NULL) {
        return false;
    }
    *out_spec_decl = NULL;
    *out_spec_type_ref = NULL;
    if (owner_type.kind != FENG_INFERRED_EXPR_TYPE_TYPE_REF ||
        owner_type.type_ref == NULL ||
        owner_type.type_ref->kind != FENG_TYPE_REF_NAMED ||
        owner_type.type_ref->as.named.segment_count != 1U ||
        owner_type.type_ref->as.named.type_arg_count != 0U) {
        return false;
    }

    type_param = find_type_param(
        context, owner_type.type_ref->as.named.segments[0]);
    if (type_param == NULL || type_param->type_param == NULL ||
        type_param->type_param->constraint == NULL) {
        return false;
    }
    constraint_decl = resolve_type_ref_decl(
        context, type_param->type_param->constraint);
    if (constraint_decl == NULL || constraint_decl->kind != FENG_DECL_SPEC) {
        return false;
    }

    *out_spec_decl = constraint_decl;
    *out_spec_type_ref = type_param->type_param->constraint;
    return true;
}

/* Resolve one member selected from a generic parameter value through the
 * parameter's exact constraint instance. */
static bool find_generic_param_spec_member_surface(
    ResolveContext *context,
    InferredExprType owner_type,
    FengSlice name,
    bool include_static,
    SpecMemberSurface *out_surface) {
    const FengDecl *constraint_decl = NULL;
    const FengTypeRef *constraint_ref = NULL;

    return resolve_generic_param_spec_constraint(context,
                                                 owner_type,
                                                 &constraint_decl,
                                                 &constraint_ref) &&
           find_spec_member_surface_for_instance(context,
                                                 constraint_decl,
                                                 constraint_ref,
                                                 name,
                                                 include_static,
                                                 out_surface);
}

/* Build the semantic identity of the current generic type declaration using
 * its own active parameters, for example Helper<T> while resolving Helper. */
static FriendTypeIdentity *build_friend_subject_for_type_decl(
    const FengDecl *type_decl) {
    FriendTypeIdentity *identity;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }
    identity = (FriendTypeIdentity *)calloc(1U, sizeof(*identity));
    if (identity == NULL) {
        return NULL;
    }
    identity->kind = FRIEND_TYPE_IDENTITY_NAMED;
    identity->as.named.decl = type_decl;
    identity->as.named.type_arg_count =
        type_decl->as.type_decl.type_param_count;
    if (identity->as.named.type_arg_count == 0U) {
        return identity;
    }
    identity->as.named.type_args = (FriendTypeIdentity **)calloc(
        identity->as.named.type_arg_count,
        sizeof(*identity->as.named.type_args));
    if (identity->as.named.type_args == NULL) {
        friend_type_identity_free(identity);
        return NULL;
    }
    for (size_t index = 0U;
         index < identity->as.named.type_arg_count;
         ++index) {
        FriendTypeIdentity *arg =
            (FriendTypeIdentity *)calloc(1U, sizeof(*arg));

        if (arg == NULL) {
            friend_type_identity_free(identity);
            return NULL;
        }
        arg->kind = FRIEND_TYPE_IDENTITY_ACTIVE_PARAM;
        arg->as.active_param = &type_decl->as.type_decl.type_params[index];
        identity->as.named.type_args[index] = arg;
    }
    return identity;
}

/* Build the exact type whose lexical implementation context currently owns
 * friend authority. Same-package fit methods keep their existing target-type
 * branch; ordinary type implementation contexts use their explicit owner. */
static FriendTypeIdentity *build_current_friend_subject(
    const ResolveContext *context) {
    if (context == NULL) {
        return NULL;
    }
    if (context->current_fit_decl != NULL) {
        if (context->current_callable_member == NULL ||
            context->current_callable_member->kind != FENG_TYPE_MEMBER_METHOD ||
            context->current_fit_target_type_ref == NULL) {
            return NULL;
        }
        return build_friend_type_identity(context,
                                          context->current_fit_target_type_ref,
                                          NULL,
                                          0U,
                                          false);
    }
    return build_friend_subject_for_type_decl(
        context->current_type_implementation_owner);
}

/* Release a temporary vector of materialized owner arguments. */
static void free_friend_owner_type_args(FriendTypeIdentity **type_args,
                                        size_t type_arg_count) {
    for (size_t index = 0U; index < type_arg_count; ++index) {
        friend_type_identity_free(type_args[index]);
    }
    free(type_args);
}

/* Materialize the annotated owner's generic arguments from the receiver or
 * static owner at the access site. Parent-spec members first project the
 * concrete child-spec instance to the declaring parent surface. */
static bool build_friend_owner_type_args(
    ResolveContext *context,
    const struct FengFriendMemberInfo *info,
    const FengDecl *access_owner_decl,
    InferredExprType owner_instance,
    FriendTypeIdentity ***out_type_args,
    size_t *out_type_arg_count) {
    const FengTypeRef *owner_ref = NULL;
    FriendTypeIdentity **type_args = NULL;

    if (out_type_args == NULL || out_type_arg_count == NULL || info == NULL) {
        return false;
    }
    *out_type_args = NULL;
    *out_type_arg_count = 0U;
    if (info->owner_type_param_count == 0U) {
        return true;
    }
    if (owner_instance.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        owner_ref = owner_instance.type_ref;
    }
    if (info->owner_decl != NULL &&
        info->owner_decl->kind == FENG_DECL_SPEC &&
        access_owner_decl != NULL &&
        access_owner_decl != info->owner_decl &&
        access_owner_decl->kind == FENG_DECL_SPEC) {
        owner_ref = instantiate_parent_spec_ref_for_instance(
            context,
            access_owner_decl,
            owner_ref,
            info->owner_decl);
    }
    type_args = (FriendTypeIdentity **)calloc(
        info->owner_type_param_count, sizeof(*type_args));
    if (type_args == NULL) {
        return false;
    }
    if (info->owner_decl != NULL &&
        info->owner_decl->kind == FENG_DECL_FIT &&
        owner_ref != NULL && owner_ref->kind == FENG_TYPE_REF_ARRAY &&
        info->owner_type_param_count == 1U) {
        type_args[0] = build_friend_type_identity(context,
                                                  owner_ref->as.inner,
                                                  NULL,
                                                  0U,
                                                  false);
    } else if (owner_ref != NULL &&
               owner_ref->kind == FENG_TYPE_REF_NAMED &&
               owner_ref->as.named.type_arg_count ==
                   info->owner_type_param_count) {
        for (size_t index = 0U;
             index < info->owner_type_param_count;
             ++index) {
            type_args[index] = build_friend_type_identity(
                context,
                owner_ref->as.named.type_args[index],
                NULL,
                0U,
                false);
            if (type_args[index] == NULL) {
                free_friend_owner_type_args(type_args,
                                            info->owner_type_param_count);
                return false;
            }
        }
    } else {
        free(type_args);
        return false;
    }
    if (type_args[0] == NULL) {
        free_friend_owner_type_args(type_args,
                                    info->owner_type_param_count);
        return false;
    }
    *out_type_args = type_args;
    *out_type_arg_count = info->owner_type_param_count;
    return true;
}

/* Remember one fit method that used a friend authorization so its declaration
 * module can be checked after inferred member signatures are complete. */
static bool record_friend_fit_access(
    ResolveContext *context,
    const struct FengFriendMemberInfo *info_const) {
    struct FengFriendMemberInfo *info =
        (struct FengFriendMemberInfo *)info_const;
    FriendFitAccess access;

    if (context == NULL || info == NULL ||
        context->current_fit_decl == NULL ||
        context->current_callable_member == NULL) {
        return true;
    }
    for (size_t index = 0U; index < info->fit_access_count; ++index) {
        if (info->fit_accesses[index].module == context->module &&
            info->fit_accesses[index].callable_member ==
                context->current_callable_member) {
            return true;
        }
    }
    access.module = context->module;
    access.program = context->program;
    access.callable_member = context->current_callable_member;
    return append_raw((void **)&info->fit_accesses,
                      &info->fit_access_count,
                      &info->fit_access_capacity,
                      sizeof(access),
                      &access);
}

/* Query the owner-module signature rule after its recursive scan has run.
 * Before inference completes, access is provisionally accepted and recorded;
 * the post-pass reports any invalid cross-module fit use. */
static bool friend_member_signature_visible_from_module(
    const struct FengFriendMemberInfo *info,
    const FengSemanticModule *consumer_module) {
    if (info == NULL || consumer_module == NULL ||
        consumer_module == info->owner_module || !info->signature_checked ||
        info->owner_private_signature_decl == NULL) {
        return true;
    }
    return false;
}

/* Check the compile-time-only friend branch for one explicitly seal member.
 * It replaces only the member-level seal test; all enclosing type/spec/fit
 * visibility and ordinary lookup rules are enforced by the caller first. */
static bool friend_seal_member_is_accessible_from(
    ResolveContext *context,
    const FengDecl *access_owner_decl,
    InferredExprType owner_instance,
    const FengTypeMember *member) {
    const struct FengFriendMemberInfo *info;
    FriendTypeIdentity *subject;
    FriendTypeIdentity **owner_type_args = NULL;
    size_t owner_type_arg_count = 0U;
    bool accessible = false;

    if (context == NULL || member == NULL ||
        member->visibility != FENG_VISIBILITY_PRIVATE) {
        return false;
    }
    info = find_friend_member_info(context->analysis, member);
    if (info == NULL || info->friend_type_count == 0U) {
        return false;
    }
    if (context->current_fit_decl != NULL) {
        if (context->module == NULL || info->owner_module == NULL ||
            context->module->origin != FENG_SEMANTIC_MODULE_ORIGIN_LOCAL ||
            info->owner_module->origin != FENG_SEMANTIC_MODULE_ORIGIN_LOCAL) {
            return false;
        }
    }
    subject = build_current_friend_subject(context);
    if (subject == NULL ||
        !build_friend_owner_type_args(context,
                                      info,
                                      access_owner_decl,
                                      owner_instance,
                                      &owner_type_args,
                                      &owner_type_arg_count)) {
        friend_type_identity_free(subject);
        return false;
    }
    for (size_t index = 0U; index < info->friend_type_count; ++index) {
        if (normalized_friend_type_matches_subject(info->friend_types[index],
                                                   owner_type_args,
                                                   owner_type_arg_count,
                                                   subject)) {
            accessible = true;
            break;
        }
    }
    free_friend_owner_type_args(owner_type_args, owner_type_arg_count);
    friend_type_identity_free(subject);
    return accessible;
}

/* Record a fit authorization only after member/overload resolution selected
 * this exact declaration. Candidate visibility probes must remain side-effect
 * free so an unselected friend overload cannot trigger AE1338. */
static bool record_selected_friend_fit_access(
    ResolveContext *context,
    const FengDecl *access_owner_decl,
    InferredExprType owner_instance,
    const FengTypeMember *member) {
    const struct FengFriendMemberInfo *info;

    if (context == NULL || context->current_fit_decl == NULL || member == NULL ||
        !friend_seal_member_is_accessible_from(context,
                                               access_owner_decl,
                                               owner_instance,
                                               member)) {
        return true;
    }
    info = find_friend_member_info(context->analysis, member);
    return info == NULL || record_friend_fit_access(context, info);
}

/* Resolve the type implementation context used only by spec-seal access.
 * A fit method contributes its target type even for a static fit method,
 * where current_type_decl is intentionally not populated. */
static const FengDecl *current_spec_implementation_type(
    const ResolveContext *context) {
    if (context == NULL || context->current_callable_member == NULL) {
        return NULL;
    }
    if (context->current_fit_decl != NULL &&
        context->current_fit_target_type_ref != NULL) {
        return resolve_type_ref_decl(context,
                                     context->current_fit_target_type_ref);
    }
    return context->current_type_decl;
}

/* A spec member is public unless explicitly seal. Seal access is granted
 * only to a member/static/fit method whose implementation type nominally
 * satisfies the member's original declaring spec. This predicate never
 * consults or widens the concrete implementation member visibility. */
static bool spec_member_is_accessible_from(
    ResolveContext *context,
    const FengDecl *access_spec,
    const FengDecl *declaring_spec,
    InferredExprType owner_instance,
    const FengTypeMember *member) {
    const FengDecl *implementation_type;

    if (member == NULL) {
        return false;
    }
    if (member->visibility != FENG_VISIBILITY_PRIVATE) {
        return true;
    }
    implementation_type = current_spec_implementation_type(context);
    return (implementation_type != NULL && declaring_spec != NULL &&
            type_decl_satisfies_spec_decl(context,
                                          implementation_type,
                                          declaring_spec)) ||
           friend_seal_member_is_accessible_from(context,
                                                 access_spec,
                                                 owner_instance,
                                                 member);
}

/* Find one accessible field in an exact instance/static object-spec surface. */
static const FengTypeMember *find_accessible_spec_object_field(
    ResolveContext *context,
    const FengDecl *spec_decl,
    InferredExprType owner_instance,
    FengSlice name,
    bool require_static,
    const FengDecl **out_declaring_spec) {
    const FengDecl *declaring_spec = NULL;
    const FengTypeMember *member = find_spec_object_field_with_owner(
        context,
        spec_decl,
        name,
        require_static,
        &declaring_spec);

    if (out_declaring_spec != NULL) {
        *out_declaring_spec = NULL;
    }
    if (member == NULL ||
        !spec_member_is_accessible_from(context,
                                        spec_decl,
                                        declaring_spec,
                                        owner_instance,
                                        member)) {
        return NULL;
    }
    if (out_declaring_spec != NULL) {
        *out_declaring_spec = declaring_spec;
    }
    return member;
}

/* Find the first same-name member accessible at the current source point.
 * The complete closure is scanned so an inaccessible seal overload cannot
 * hide a later accessible overload with the same name. */
static const FengTypeMember *find_accessible_spec_object_member(
    ResolveContext *context,
    const FengDecl *spec_decl,
    InferredExprType owner_instance,
    FengSlice name,
    bool include_static,
    const FengDecl **out_declaring_spec) {
    const FengDecl **closure = NULL;
    size_t closure_count = 0U;
    size_t closure_capacity = 0U;
    const FengTypeMember *result = NULL;

    if (out_declaring_spec != NULL) {
        *out_declaring_spec = NULL;
    }
    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT ||
        !spec_collect_closure(context,
                              spec_decl,
                              &closure,
                              &closure_count,
                              &closure_capacity)) {
        free(closure);
        return NULL;
    }

    for (size_t i = 0U; i < closure_count && result == NULL; ++i) {
        const FengDecl *current = closure[i];

        if (current->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            continue;
        }
        for (size_t j = 0U;
             j < current->as.spec_decl.as.object.member_count;
             ++j) {
            const FengTypeMember *candidate =
                current->as.spec_decl.as.object.members[j];
            FengSlice candidate_name;

            if (candidate->is_static && !include_static) {
                continue;
            }
            if (candidate->kind == FENG_TYPE_MEMBER_FIELD) {
                candidate_name = candidate->as.field.name;
            } else if (candidate->kind == FENG_TYPE_MEMBER_METHOD) {
                candidate_name = candidate->as.callable.name;
            } else {
                continue;
            }
            if (!slice_equals(candidate_name, name) ||
                !spec_member_is_accessible_from(context,
                                                spec_decl,
                                                current,
                                                owner_instance,
                                                candidate)) {
                continue;
            }
            result = candidate;
            if (out_declaring_spec != NULL) {
                *out_declaring_spec = current;
            }
            break;
        }
    }

    free(closure);
    return result;
}

/* Report one source-level access failure for an existing spec-seal member. */
static bool report_inaccessible_spec_member(
    ResolveContext *context,
    FengToken token,
    const FengDecl *declaring_spec,
    const FengTypeMember *member) {
    FengSlice member_name;
    FengSlice spec_name;

    if (member == NULL || declaring_spec == NULL) {
        return true;
    }
    member_name = member->kind == FENG_TYPE_MEMBER_FIELD
                      ? member->as.field.name
                      : member->as.callable.name;
    spec_name = declaring_spec->as.spec_decl.name;
    return resolver_append_error(
        context,
        token,
        "AE0708",
        format_message(
            "seal member '%.*s' of spec '%.*s' is only accessible from a type or fit implementation that satisfies that spec",
            (int)member_name.length,
            member_name.data,
            (int)spec_name.length,
            spec_name.data));
}

/* Find a member on either a concrete type or an object-form spec. Returns NULL
 * for callable-form specs and other declaration kinds. */
static const FengTypeMember *find_decl_instance_member(const ResolveContext *context,
                                                       const FengDecl *decl,
                                                       FengSlice name) {
    if (decl == NULL) {
        return NULL;
    }
    if (decl->kind == FENG_DECL_TYPE) {
        return find_instance_member(decl, name);
    }
    if (decl->kind == FENG_DECL_SPEC) {
        return find_spec_object_member(context, decl, name, /*include_static=*/false);
    }
    return NULL;
}

static bool field_has_declaration_initializer(const FengTypeMember *member) {
    return member != NULL && member->kind == FENG_TYPE_MEMBER_FIELD &&
           (member->as.field.initializer != NULL || member->as.field.declaration_bound);
}

/* One ordinary-object or union instance on the current default-zero expansion
 * path. Generic owner arguments are retained so distinct closed instances do
 * not become a false cycle merely because they share one origin declaration. */
typedef struct DefaultZeroExpansionFrame {
    const FengDecl *type_decl;
    const FengTypeRef *instance_type_ref;
} DefaultZeroExpansionFrame;

/* Compile-time-only state for the finite default-zero predicate. */
typedef struct DefaultZeroExpansionState {
    DefaultZeroExpansionFrame *frames;
    size_t frame_count;
    size_t frame_capacity;
    bool out_of_memory;
} DefaultZeroExpansionState;

/* Return whether a declaration uses ordinary managed-object semantics. Tuple
 * and @value declarations have inline zero storage and their layout cycles
 * are rejected independently by the value-layout semantic pass. */
static bool decl_uses_ordinary_object_semantics(const FengDecl *decl) {
    return decl != NULL && decl->kind == FENG_DECL_TYPE &&
           !decl->as.type_decl.is_tuple && !decl->as.type_decl.is_value;
}

/* Return whether a declaration contributes a recursive edge to default-zero
 * expansion. Union defaults follow their first direct member by language
 * rule; this is intentionally independent of any standard-library type name. */
static bool decl_expands_default_zero_recursively(const FengDecl *decl) {
    return decl_uses_ordinary_object_semantics(decl) ||
           (decl != NULL && decl->kind == FENG_DECL_SPEC &&
            decl->as.spec_decl.form == FENG_SPEC_FORM_UNION);
}

/* Resolve the effective type of one field. Explicit field types are closed
 * through the current owner instance; inferred fields use the semantic fact
 * already recorded for the member, with inference as a declaration-order
 * fallback while the owning module is still being resolved. */
static InferredExprType default_zero_field_type(
    ResolveContext *context,
    const FengDecl *owner_type_decl,
    InferredExprType owner_type,
    const FengTypeMember *field) {
    InferredExprType field_type = inferred_expr_type_unknown();

    if (field == NULL || field->kind != FENG_TYPE_MEMBER_FIELD) {
        return field_type;
    }
    if (field->as.field.type != NULL) {
        field_type = inferred_expr_type_from_type_ref(
            substitute_type_ref_for_owner_instance(context,
                                                   owner_type_decl,
                                                   owner_type,
                                                   field->as.field.type));
        return field_type;
    }
    field_type = inferred_expr_type_from_type_fact(
        feng_semantic_lookup_type_fact(context->analysis, field));
    if (!inferred_expr_type_is_known(field_type) &&
        field->as.field.initializer != NULL) {
        field_type = infer_expr_type(context, field->as.field.initializer);
    }
    return field_type;
}

/* Compare one candidate instance with a frame already on the expansion path.
 * Non-generic declarations are identified by declaration alone. A missing
 * generic instance surface is treated conservatively as the same instance;
 * valid closed construction and binding paths normally retain both refs. */
static bool default_zero_frame_matches(
    const ResolveContext *context,
    const DefaultZeroExpansionFrame *frame,
    const FengDecl *type_decl,
    const FengTypeRef *instance_type_ref) {
    if (frame == NULL || frame->type_decl != type_decl) {
        return false;
    }
    if (type_decl == NULL ||
        ((type_decl->kind == FENG_DECL_TYPE &&
          type_decl->as.type_decl.type_param_count == 0U) ||
         (type_decl->kind == FENG_DECL_SPEC &&
          type_decl->as.spec_decl.type_param_count == 0U))) {
        return true;
    }
    if (frame->instance_type_ref == NULL || instance_type_ref == NULL) {
        return true;
    }
    return type_refs_semantically_equal(context,
                                        frame->instance_type_ref,
                                        instance_type_ref);
}

/* Append one frame without imposing an arbitrary recursion-depth limit. */
static bool default_zero_push_frame(DefaultZeroExpansionState *state,
                                    DefaultZeroExpansionFrame frame) {
    DefaultZeroExpansionFrame *grown;
    size_t capacity;

    if (state->frame_count < state->frame_capacity) {
        state->frames[state->frame_count++] = frame;
        return true;
    }
    capacity = state->frame_capacity == 0U ? 8U : state->frame_capacity * 2U;
    grown = (DefaultZeroExpansionFrame *)realloc(
        state->frames, capacity * sizeof(*grown));
    if (grown == NULL) {
        state->out_of_memory = true;
        return false;
    }
    state->frames = grown;
    state->frame_capacity = capacity;
    state->frames[state->frame_count++] = frame;
    return true;
}

/* Determine whether a value of `type` can be produced by finite recursive
 * default-zero expansion. Arrays and pointers are terminal: an empty array
 * does not construct an element, and a pointer default does not construct a
 * pointee. Builtins, enums, callable/object/intersection specs, tuples and
 * @value types are likewise handled by their own finite default
 * representation. Union-form specs are not terminal: their default follows
 * the first direct member, regardless of the union's source-level name. */
static bool default_zero_type_is_finite(
    ResolveContext *context,
    InferredExprType type,
    DefaultZeroExpansionState *state) {
    const FengDecl *type_decl = NULL;
    const FengTypeRef *instance_type_ref = NULL;
    InferredExprType owner_type;
    size_t frame_index;
    size_t field_index;

    if (type.kind == FENG_INFERRED_EXPR_TYPE_BUILTIN ||
        type.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA ||
        type.kind == FENG_INFERRED_EXPR_TYPE_UNKNOWN) {
        return true;
    }
    if (type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        instance_type_ref = type.type_ref;
        if (instance_type_ref == NULL ||
            instance_type_ref->kind == FENG_TYPE_REF_ARRAY ||
            instance_type_ref->kind == FENG_TYPE_REF_POINTER) {
            return true;
        }
        if (instance_type_ref->kind != FENG_TYPE_REF_NAMED ||
            type_ref_builtin_canonical_name(instance_type_ref,
                                            context->pointer_size) != NULL) {
            return true;
        }
        if (instance_type_ref->as.named.segment_count == 1U &&
            instance_type_ref->as.named.type_arg_count == 0U &&
            find_type_param(context,
                            instance_type_ref->as.named.segments[0]) != NULL) {
            return true;
        }
        type_decl = resolve_type_ref_decl(context, instance_type_ref);
    } else if (type.kind == FENG_INFERRED_EXPR_TYPE_DECL) {
        type_decl = type.type_decl;
    }
    if (!decl_expands_default_zero_recursively(type_decl)) {
        return true;
    }

    for (frame_index = 0U; frame_index < state->frame_count; ++frame_index) {
        if (default_zero_frame_matches(context,
                                       &state->frames[frame_index],
                                       type_decl,
                                       instance_type_ref)) {
            return false;
        }
    }
    if (!default_zero_push_frame(
            state,
            (DefaultZeroExpansionFrame){type_decl, instance_type_ref})) {
        return false;
    }

    owner_type = instance_type_ref != NULL
                     ? inferred_expr_type_from_type_ref(instance_type_ref)
                     : inferred_expr_type_from_decl(type_decl);
    if (type_decl->kind == FENG_DECL_SPEC) {
        const FengTypeRef *first_member_type_ref;
        InferredExprType first_member_type;
        bool finite;

        if (type_decl->as.spec_decl.as.union_form.member_count == 0U) {
            --state->frame_count;
            return true;
        }
        first_member_type_ref = substitute_type_ref_for_owner_instance(
            context,
            type_decl,
            owner_type,
            type_decl->as.spec_decl.as.union_form.members[0U]);
        first_member_type = inferred_expr_type_from_type_ref(
            first_member_type_ref);
        finite = default_zero_type_is_finite(context,
                                             first_member_type,
                                             state);
        --state->frame_count;
        return finite;
    }
    for (field_index = 0U;
         field_index < type_decl->as.type_decl.member_count;
         ++field_index) {
        const FengTypeMember *field =
            type_decl->as.type_decl.members[field_index];
        InferredExprType field_type;

        if (field == NULL || field->kind != FENG_TYPE_MEMBER_FIELD ||
            field->is_static) {
            continue;
        }
        field_type = default_zero_field_type(context,
                                             type_decl,
                                             owner_type,
                                             field);
        if (!default_zero_type_is_finite(context, field_type, state)) {
            --state->frame_count;
            return false;
        }
    }
    --state->frame_count;
    return true;
}

/* Reject one declaration binding that would request a non-terminating default
 * zero. A binding initializer bypasses this check at the caller. */
static bool validate_binding_default_zero_target(
    ResolveContext *context,
    const FengTypeRef *type_ref,
    FengToken binding_token) {
    DefaultZeroExpansionState state = {0};
    bool finite = default_zero_type_is_finite(
        context, inferred_expr_type_from_type_ref(type_ref), &state);

    free(state.frames);
    if (state.out_of_memory) {
        return resolver_append_error(
            context,
            binding_token,
            "IE0001",
            format_message("out of memory while checking default zero value"));
    }
    if (!finite) {
        char *type_name = format_type_ref_name(type_ref);
        bool ok = resolver_append_error(
            context,
            binding_token,
            "AE0332",
            format_message(
                "type '%s' has no finite default zero value; provide an initializer",
                type_name != NULL ? type_name : "<unknown>"));

        free(type_name);
        return ok;
    }
    return true;
}

/* Reject an array creation whose element type cannot be initialized to a
 * finite default zero value.  The qualification is purely static and does
 * not depend on whether the length is constant, zero, positive, or dynamic. */
static bool validate_array_new_default_zero_element(
    ResolveContext *context,
    const FengTypeRef *element_type_ref) {
    DefaultZeroExpansionState state = {0};
    bool finite;

    if (element_type_ref == NULL) {
        return true;
    }
    finite = default_zero_type_is_finite(
        context,
        inferred_expr_type_from_type_ref(element_type_ref),
        &state);
    free(state.frames);
    if (state.out_of_memory) {
        return resolver_append_error(
            context,
            element_type_ref->token,
            "IE0001",
            format_message(
                "out of memory while checking array element default zero value"));
    }
    if (!finite) {
        char *type_name = format_type_ref_name(element_type_ref);
        bool ok = resolver_append_error(
            context,
            element_type_ref->token,
            "AE0332",
            format_message(
                "array creation element type '%s' has no finite default zero value; provide explicit element values instead",
                type_name != NULL ? type_name : "<unknown>"));

        free(type_name);
        return ok;
    }
    return true;
}

/* Validate the member-declaration phase of one object construction. Only a
 * field declaration initializer supplies its phase-one value directly.
 * Constructor-body and object-literal writes happen later and therefore do
 * not cancel a required field default. */
static bool validate_construction_default_zero_requirements(
    ResolveContext *context,
    const FengExpr *target_expr,
    const FengDecl *type_decl,
    InferredExprType owner_type) {
    size_t field_index;

    if (!decl_uses_ordinary_object_semantics(type_decl)) {
        return true;
    }
    for (field_index = 0U;
         field_index < type_decl->as.type_decl.member_count;
         ++field_index) {
        const FengTypeMember *field =
            type_decl->as.type_decl.members[field_index];
        DefaultZeroExpansionState state = {0};
        InferredExprType field_type;
        bool finite;

        if (field == NULL || field->kind != FENG_TYPE_MEMBER_FIELD ||
            field->is_static || field_has_declaration_initializer(field)) {
            continue;
        }
        field_type = default_zero_field_type(context,
                                             type_decl,
                                             owner_type,
                                             field);
        finite = default_zero_type_is_finite(context, field_type, &state);
        free(state.frames);
        if (state.out_of_memory) {
            return resolver_append_error(
                context,
                target_expr != NULL ? target_expr->token
                                    : context->program->module_token,
                "IE0001",
                format_message(
                    "out of memory while checking construction default values"));
        }
        if (!finite) {
            return resolver_append_error(
                context,
                target_expr != NULL ? target_expr->token
                                    : context->program->module_token,
                "AE0332",
                format_message(
                    "construction of type '%.*s' requires a non-terminating default zero value for field '%.*s'; provide a field declaration initializer",
                    (int)type_decl->as.type_decl.name.length,
                    type_decl->as.type_decl.name.data,
                    (int)field->as.field.name.length,
                    field->as.field.name.data));
        }
    }
    return true;
}

static bool constructor_has_imported_bound_name(const FengTypeMember *constructor,
                                                FengSlice field_name) {
    size_t index;

    if (constructor == NULL || constructor->kind != FENG_TYPE_MEMBER_CONSTRUCTOR) {
        return false;
    }
    for (index = 0U; index < constructor->as.callable.bound_member_count; ++index) {
        if (slice_equals(constructor->as.callable.bound_member_names[index], field_name)) {
            return true;
        }
    }
    return false;
}

static bool expr_is_direct_self_member(const FengExpr *expr, FengSlice *out_name) {
    if (expr == NULL || expr->kind != FENG_EXPR_MEMBER || expr->as.member.object == NULL ||
        expr->as.member.object->kind != FENG_EXPR_SELF) {
        return false;
    }

    if (out_name != NULL) {
        *out_name = expr->as.member.member;
    }
    return true;
}

static const FengTypeMember *find_direct_self_let_target_member(const FengDecl *type_decl,
                                                                const FengExpr *expr) {
    FengSlice name;

    if (!expr_is_direct_self_member(expr, &name)) {
        return NULL;
    }

    return find_type_let_field_member(type_decl, name);
}

static bool type_member_is_public(const FengTypeMember *member) {
    return member != NULL && member->visibility != FENG_VISIBILITY_PRIVATE;
}

/* Return whether one target type directly expands the specified source type.
 * All three source forms are normalized to the same resolved_source_decl. */
static bool type_decl_directly_mixes_source(const FengDecl *target_type,
                                            const FengDecl *source_type) {
    size_t mixin_index;

    if (target_type == NULL || source_type == NULL ||
        target_type->kind != FENG_DECL_TYPE ||
        source_type->kind != FENG_DECL_TYPE) {
        return false;
    }
    for (mixin_index = 0U;
         mixin_index < target_type->as.type_decl.mixin_count;
         ++mixin_index) {
        if (target_type->as.type_decl.mixins[mixin_index].resolved_source_decl ==
            source_type) {
            return true;
        }
    }
    return false;
}

/* Identify exactly the private member shapes that can receive direct mix
 * authorization. Ordinary seal members never pass this predicate. */
bool feng_semantic_member_is_mixable_seal_capability(
    const FengTypeMember *member) {
    if (member == NULL ||
        member->visibility != FENG_VISIBILITY_PRIVATE ||
        !member->is_mixable) {
        return false;
    }
    return (member->kind == FENG_TYPE_MEMBER_METHOD && member->is_static) ||
           (member->kind == FENG_TYPE_MEMBER_FIELD && !member->is_static);
}

/* Check direct mix authorization independently of the declaration provider.
 * The source may own the method directly or expose it through a visible fit. */
bool feng_semantic_type_has_mixable_seal_access(
    const FengDecl *target_type,
    const FengDecl *source_type,
    const FengTypeMember *member) {
    return feng_semantic_member_is_mixable_seal_capability(member) &&
           type_decl_directly_mixes_source(target_type, source_type);
}

/* Resolve the direct-mix access subject for a source-level method body.
 * Constructors, field initializers, top-level functions, and fit methods do
 * not acquire this authorization. */
static const FengDecl *current_mixable_seal_access_type(
    const ResolveContext *context) {
    if (context == NULL || context->current_fit_decl != NULL ||
        context->current_type_decl == NULL ||
        context->current_callable_member == NULL ||
        context->current_callable_member->kind != FENG_TYPE_MEMBER_METHOD) {
        return NULL;
    }
    return context->current_type_decl;
}

/* Check the special source-member access branch for one seal mix capability. */
static bool mixable_seal_member_is_accessible_from(
    const ResolveContext *context,
    const FengDecl *source_type,
    const FengTypeMember *member) {
    return feng_semantic_type_has_mixable_seal_access(
        current_mixable_seal_access_type(context), source_type, member);
}

/* Apply ordinary fit-member visibility plus the direct mix exception. The
 * fit declaration itself must already have passed its normal visibility
 * filter before this helper is called. */
static bool fit_member_is_accessible_from(ResolveContext *context,
                                          const FengDecl *source_type,
                                          InferredExprType owner_instance,
                                          const FengDecl *fit_decl,
                                          const FengTypeMember *member) {
    if (type_member_is_public(member)) {
        return true;
    }
    if (context != NULL && fit_decl != NULL &&
        context->current_fit_decl == fit_decl) {
        return true;
    }
    return mixable_seal_member_is_accessible_from(
               context, source_type, member) ||
           friend_seal_member_is_accessible_from(context,
                                                 source_type,
                                                 owner_instance,
                                                 member);
}

/* When the resolver is inside a fit-block function body, accessing the target
 * type's private members (`seal` fields or `seal` methods) is forbidden, regardless
 * of whether the target lives in the same package as the fit declaration.
 * Members contributed by the fit block itself live on the fit decl, not on the
 * target type, so this helper only consults the target type's own member set.
 * See docs/specifications/feng-fit.md §4 / §5. */
static bool fit_body_blocks_private_access(const ResolveContext *context,
                                           const FengDecl *owner_type_decl,
                                           const FengTypeMember *member) {
    const FengDecl *fit_target;

    if (context == NULL || context->current_fit_decl == NULL ||
        owner_type_decl == NULL || member == NULL ||
        type_member_is_public(member)) {
        return false;
    }
    if (owner_type_decl->kind != FENG_DECL_TYPE) {
        return false;
    }
    fit_target = resolve_type_ref_decl(context,
                                       context->current_fit_decl->as.fit_decl.target);
    return fit_target != NULL && fit_target == owner_type_decl;
}

/* A seal type member is private to its owning type. Module and package
 * identity do not widen that domain, and a fit body is not the target type
 * itself even though it temporarily carries the target as current_type_decl. */
static bool type_member_is_accessible_from(ResolveContext *context,
                                           const FengDecl *owner_type_decl,
                                           InferredExprType owner_instance,
                                           const FengTypeMember *member) {
    return member != NULL &&
           (type_member_is_public(member) ||
            (context != NULL && owner_type_decl != NULL &&
             context->current_type_decl == owner_type_decl &&
             context->current_fit_decl == NULL) ||
            mixable_seal_member_is_accessible_from(
                context, owner_type_decl, member) ||
            friend_seal_member_is_accessible_from(context,
                                                  owner_type_decl,
                                                  owner_instance,
                                                  member));
}

static size_t count_declared_constructors(const FengDecl *type_decl) {
    size_t member_index;
    size_t count = 0U;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return 0U;
    }

    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        if (type_decl->as.type_decl.members[member_index]->kind ==
            FENG_TYPE_MEMBER_CONSTRUCTOR) {
            ++count;
        }
    }

    return count;
}

/* Find the @iterable method on a type decl. Returns NULL if not found. */
static const FengTypeMember *find_iterable_method(const FengDecl *type_decl) {
    size_t member_index;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }
    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];
        if (member->kind == FENG_TYPE_MEMBER_METHOD &&
            annotations_contain_kind(member->annotations, member->annotation_count,
                                     FENG_ANNOTATION_ITERABLE)) {
            return member;
        }
    }
    return NULL;
}

/* Find the @iterator method on a type decl. Returns NULL if not found. */
static const FengTypeMember *find_iterator_method(const FengDecl *type_decl) {
    size_t member_index;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }
    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];
        if (member->kind == FENG_TYPE_MEMBER_METHOD &&
            annotations_contain_kind(member->annotations, member->annotation_count,
                                     FENG_ANNOTATION_ITERATOR)) {
            return member;
        }
    }
    return NULL;
}

/* Visitor callback for finding @iterable method in fit blocks. */
static bool fit_iterable_visitor(const FengTypeMember *member,
                                 const FengSemanticModule *fit_module,
                                 const FengDecl *fit_decl,
                                 void *userdata) {
    (void)fit_module;
    (void)fit_decl;
    if (annotations_contain_kind(member->annotations, member->annotation_count,
                                 FENG_ANNOTATION_ITERABLE)) {
        *(const FengTypeMember **)userdata = member;
        return false;
    }
    return true;
}

/* Visitor callback for finding @iterator method in fit blocks. */
static bool fit_iterator_visitor(const FengTypeMember *member,
                                 const FengSemanticModule *fit_module,
                                 const FengDecl *fit_decl,
                                 void *userdata) {
    (void)fit_module;
    (void)fit_decl;
    if (annotations_contain_kind(member->annotations, member->annotation_count,
                                 FENG_ANNOTATION_ITERATOR)) {
        *(const FengTypeMember **)userdata = member;
        return false;
    }
    return true;
}

/* Validate @iterable/@iterator annotation constraints on a type declaration.
 * Called after all members have been resolved so return types are available. */
static bool validate_iterator_annotations(ResolveContext *context, const FengDecl *type_decl) {
    size_t member_index;
    const FengTypeMember *iterable_method = NULL;
    const FengTypeMember *iterator_method = NULL;
    size_t iterable_count = 0U;
    size_t iterator_count = 0U;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return true;
    }

    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];
        bool has_iterable = annotations_contain_kind(
            member->annotations, member->annotation_count, FENG_ANNOTATION_ITERABLE);
        bool has_iterator = annotations_contain_kind(
            member->annotations, member->annotation_count, FENG_ANNOTATION_ITERATOR);

        if (!has_iterable && !has_iterator) {
            continue;
        }

        /* @iterable/@iterator must be on methods only. */
        if (member->kind != FENG_TYPE_MEMBER_METHOD) {
            FengAnnotationKind ann_kind = has_iterable
                ? FENG_ANNOTATION_ITERABLE : FENG_ANNOTATION_ITERATOR;
            const FengAnnotation *ann = find_annotation_of_kind(
                member->annotations, member->annotation_count, ann_kind);
            return resolver_append_error(
                context,
                ann != NULL ? ann->token : member->token,
                "AE1315", format_message(
                    "@%s can only be applied to methods",
                    has_iterable ? "iterable" : "iterator")) &&
                   false;
        }

        if (has_iterable) {
            iterable_count++;
            iterable_method = member;
        }
        if (has_iterator) {
            iterator_count++;
            iterator_method = member;
        }
    }

    if (iterable_count == 0U && iterator_count == 0U) {
        return true;
    }

    /* Multiple @iterable methods. */
    if (iterable_count > 1U) {
        return resolver_append_error(
            context,
            iterable_method->token,
            "AE0319", format_message(
                "type '%.*s' has multiple @iterable methods",
                (int)decl_typeish_name(type_decl).length,
                decl_typeish_name(type_decl).data)) &&
               false;
    }

    /* Multiple @iterator methods. */
    if (iterator_count > 1U) {
        return resolver_append_error(
            context,
            iterator_method->token,
            "AE0320", format_message(
                "type '%.*s' has multiple @iterator methods",
                (int)decl_typeish_name(type_decl).length,
                decl_typeish_name(type_decl).data)) &&
               false;
    }

    /* Same type has both @iterable and @iterator. */
    if (iterable_count > 0U && iterator_count > 0U) {
        return resolver_append_error(
            context,
            iterator_method->token,
            "AE0321", format_message(
                "type '%.*s' cannot have both @iterable and @iterator",
                (int)decl_typeish_name(type_decl).length,
                decl_typeish_name(type_decl).data)) &&
               false;
    }

    /* Validate @iterable method constraints. */
    if (iterable_method != NULL) {
        const FengDecl *return_type_decl;

        /* Must take no parameters (implicit self only). */
        if (iterable_method->as.callable.param_count > 0U) {
            return resolver_append_error(
                context,
                iterable_method->token,
                "AE0322", format_message("@iterable method must take no parameters")) &&
                   false;
        }

        /* Return type must have exactly one @iterator method. */
        return_type_decl = resolve_type_ref_decl(context,
                                                  iterable_method->as.callable.return_type);
        if (return_type_decl == NULL || find_iterator_method(return_type_decl) == NULL) {
            return resolver_append_error(
                context,
                iterable_method->token,
                "AE0323", format_message(
                    "return type of @iterable method has no @iterator method")) &&
                   false;
        }
    }

    /* Validate @iterator method constraints. */
    if (iterator_method != NULL) {
        const FengDecl *return_type_decl;
        const FengTypeMember *first_field;

        /* Must take no parameters (implicit self only). */
        if (iterator_method->as.callable.param_count > 0U) {
            return resolver_append_error(
                context,
                iterator_method->token,
                "AE0324", format_message("@iterator method must take no parameters")) &&
                   false;
        }

        /* Return type must be a named tuple of (bool, E). */
        return_type_decl = resolve_type_ref_decl(context,
                                                  iterator_method->as.callable.return_type);
        if (!decl_is_tuple_type(return_type_decl)) {
            return resolver_append_error(
                context,
                iterator_method->token,
                "AE0325", format_message(
                    "@iterator method must return a named tuple type of the form (bool, E)")) &&
                   false;
        }

        /* Tuple must have exactly 2 field members. */
        {
            size_t field_count = 0U;
            size_t mi;
            for (mi = 0U; mi < return_type_decl->as.type_decl.member_count; ++mi) {
                if (return_type_decl->as.type_decl.members[mi]->kind == FENG_TYPE_MEMBER_FIELD) {
                    field_count++;
                }
            }
            if (field_count != 2U) {
                return resolver_append_error(
                    context,
                    iterator_method->token,
                    "AE0325", format_message(
                        "@iterator method must return a named tuple type of the form (bool, E)")) &&
                       false;
            }
        }

        /* First field must be bool. */
        first_field = tuple_field_member_at(return_type_decl, 0U);
        if (first_field == NULL || first_field->as.field.type == NULL ||
            first_field->as.field.type->kind != FENG_TYPE_REF_NAMED ||
            first_field->as.field.type->as.named.segment_count != 1U) {
            return resolver_append_error(
                context,
                iterator_method->token,
                "AE0325", format_message(
                    "@iterator method must return a named tuple type of the form (bool, E)")) &&
                   false;
        }
        {
            FengSlice first_seg = first_field->as.field.type->as.named.segments[0];
            if (first_seg.length != 4U || memcmp(first_seg.data, "bool", 4U) != 0) {
                return resolver_append_error(
                    context,
                    iterator_method->token,
                    "AE0325", format_message(
                        "@iterator method must return a named tuple type of the form (bool, E)")) &&
                       false;
            }
        }
    }

    return true;
}

/* Reject method-level type parameters on constructors and finalizers. These
 * special members may use owner type parameters, but never introduce a
 * callable-local generic scope of their own. */
static bool validate_special_member_type_params(
    ResolveContext *context,
    const FengTypeMember *member) {
    const FengCallableSignature *callable;
    const FengTypeParam *first_param;

    if (context == NULL || member == NULL ||
        (member->kind != FENG_TYPE_MEMBER_CONSTRUCTOR &&
         member->kind != FENG_TYPE_MEMBER_FINALIZER)) {
        return true;
    }

    callable = &member->as.callable;
    if (callable->type_param_count == 0U) {
        return true;
    }
    first_param = &callable->type_params[0];

    if (member->kind == FENG_TYPE_MEMBER_CONSTRUCTOR) {
        return resolver_append_error(
            context,
            first_param->token,
            "AE0316", format_message(
                "constructor '%.*s' cannot declare type parameters",
                (int)callable->name.length,
                callable->name.data));
    }

    return resolver_append_error(
        context,
        first_param->token,
        "AE0316", format_message(
            "finalizer '~%.*s' cannot declare type parameters",
            (int)callable->name.length,
            callable->name.data));
}

/* Validate finalizer eligibility and uniqueness for one concrete or generic
 * owner type. Generic ownership alone does not prohibit a finalizer. */
static bool validate_type_finalizer_constraints(ResolveContext *context, const FengDecl *type_decl) {
    size_t member_index;
    const FengTypeMember *first_finalizer = NULL;
    bool type_has_abi;
    bool type_has_value;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return true;
    }

    type_has_abi = annotations_contain_kind(type_decl->annotations,
                                            type_decl->annotation_count,
                                            FENG_ANNOTATION_ABI);
    type_has_value = annotations_contain_kind(type_decl->annotations,
                                              type_decl->annotation_count,
                                              FENG_ANNOTATION_VALUE);

    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];

        if (member->kind != FENG_TYPE_MEMBER_FINALIZER) {
            continue;
        }

        if (type_has_abi) {
            return resolver_append_error(
                context,
                member->token,
                "AE0317", format_message(
                    "type '%.*s' is marked as @abi and cannot declare a finalizer",
                    (int)decl_typeish_name(type_decl).length,
                    decl_typeish_name(type_decl).data));
        }

        /* @value types use value semantics (copy-on-assign); a finalizer
         * would run on every copy and risk double-free of shared resources.
         * Types that need cleanup should use ordinary `type` (heap object,
         * reference semantics, single release). See §2.3. */
        if (type_has_value) {
            return resolver_append_error(
                context,
                member->token,
                "AE1328", format_message(
                    "type '%.*s' is marked as @value and cannot declare a finalizer",
                    (int)decl_typeish_name(type_decl).length,
                    decl_typeish_name(type_decl).data));
        }

        if (first_finalizer != NULL) {
            return resolver_append_error(
                context,
                member->token,
                "AE0318", format_message(
                    "type '%.*s' declares more than one finalizer",
                    (int)decl_typeish_name(type_decl).length,
                    decl_typeish_name(type_decl).data));
        }

        first_finalizer = member;
    }

    return true;
}

static bool function_type_decl_is_abi_callable_type(const FengDecl *function_type_decl) {
    return function_type_decl != NULL && decl_is_function_type(function_type_decl) &&
           annotations_contain_kind(function_type_decl->annotations,
                                    function_type_decl->annotation_count,
                                    FENG_ANNOTATION_ABI);
}

static bool function_decl_is_abi_callable_value(const FengDecl *decl) {
    return decl != NULL && decl->kind == FENG_DECL_FUNCTION &&
           (decl->is_extern ||
            annotations_contain_kind(decl->annotations,
                                     decl->annotation_count,
                                     FENG_ANNOTATION_ABI));
}

static bool method_member_is_abi_callable_value(const FengTypeMember *member) {
    return member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD &&
           annotations_contain_kind(member->annotations,
                                    member->annotation_count,
                                    FENG_ANNOTATION_ABI);
}

static bool inferred_expr_type_can_match_abi_callable_type(InferredExprType type) {
    return type.kind != FENG_INFERRED_EXPR_TYPE_LAMBDA;
}

static bool current_callable_is_inside_exception_handler(const ResolveContext *context) {
    return context != NULL && context->exception_capture_depth > 0U;
}

static void note_current_callable_exception_escape(ResolveContext *context) {
    if (context == NULL || context->current_callable_signature == NULL ||
        current_callable_is_inside_exception_handler(context)) {
        return;
    }

    context->current_callable_has_escaping_exception = true;
}

static void note_callable_exception_escape(ResolveContext *context,
                                          const FengCallableSignature *callable) {
    if (!callable_may_escape_exception(context, callable)) {
        return;
    }

    note_current_callable_exception_escape(context);
}

/* Resolve the return type supplied by the current callable-form spec target
 * for a lambda expression. An untyped lambda deliberately has no target
 * return contract at this stage. */
static const FengTypeRef *lambda_target_return_type(ResolveContext *context) {
    const FengTypeRef *target;
    const FengDecl *function_type_decl;

    if (context == NULL) {
        return NULL;
    }
    target = context->current_expr_expected_type_ref;
    function_type_decl = resolve_function_type_decl(context, target);
    if (function_type_decl == NULL) {
        return NULL;
    }
    return substitute_spec_member_type_ref_for_instance(
        context,
        function_type_decl,
        target,
        function_type_decl->as.spec_decl.as.callable.return_type);
}

static InferredExprType infer_block_return_type(ResolveContext *context,
                                                const FengBlock *block);

typedef enum LambdaReturnTargetCheckMode {
    LAMBDA_RETURN_TARGET_MATCH_ONLY = 0,
    LAMBDA_RETURN_TARGET_VALIDATE
} LambdaReturnTargetCheckMode;

static bool lambda_return_values_fit_target_in_block(
    ResolveContext *context,
    const FengBlock *block,
    const FengTypeRef *target_return_type,
    LambdaReturnTargetCheckMode mode,
    bool *saw_return);

static bool lambda_return_values_fit_target_in_expr(
    ResolveContext *context,
    const FengExpr *expr,
    const FengTypeRef *target_return_type,
    LambdaReturnTargetCheckMode mode,
    bool *saw_return);

/* Visit expression-owned blocks without crossing a nested Lambda callable
 * boundary. Only return statements found in those blocks are target-checked;
 * ordinary subexpressions retain their existing validation path. */
static bool lambda_return_values_fit_target_in_expr(
    ResolveContext *context,
    const FengExpr *expr,
    const FengTypeRef *target_return_type,
    LambdaReturnTargetCheckMode mode,
    bool *saw_return) {
    size_t index;

    if (expr == NULL) {
        return true;
    }
    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER:
        case FENG_EXPR_SELF:
        case FENG_EXPR_BOOL:
        case FENG_EXPR_INTEGER:
        case FENG_EXPR_FLOAT:
        case FENG_EXPR_STRING:
        case FENG_EXPR_LAMBDA:
            return true;

        case FENG_EXPR_ARRAY_LITERAL:
            for (index = 0U; index < expr->as.array_literal.count; ++index) {
                if (!lambda_return_values_fit_target_in_expr(
                        context,
                        expr->as.array_literal.items[index],
                        target_return_type,
                        mode,
                        saw_return)) {
                    return false;
                }
            }
            return true;

        case FENG_EXPR_TUPLE_LITERAL:
            for (index = 0U; index < expr->as.tuple_literal.count; ++index) {
                if (!lambda_return_values_fit_target_in_expr(
                        context,
                        expr->as.tuple_literal.items[index],
                        target_return_type,
                        mode,
                        saw_return)) {
                    return false;
                }
            }
            return true;

        case FENG_EXPR_OBJECT_LITERAL:
            if (!lambda_return_values_fit_target_in_expr(
                    context,
                    expr->as.object_literal.target,
                    target_return_type,
                    mode,
                    saw_return)) {
                return false;
            }
            for (index = 0U;
                 index < expr->as.object_literal.field_count;
                 ++index) {
                if (!lambda_return_values_fit_target_in_expr(
                        context,
                        expr->as.object_literal.fields[index].value,
                        target_return_type,
                        mode,
                        saw_return)) {
                    return false;
                }
            }
            return true;

        case FENG_EXPR_GENERIC_TARGET:
            return lambda_return_values_fit_target_in_expr(
                context,
                expr->as.generic_target.target,
                target_return_type,
                mode,
                saw_return);

        case FENG_EXPR_CALL:
            if (!lambda_return_values_fit_target_in_expr(
                    context,
                    expr->as.call.callee,
                    target_return_type,
                    mode,
                    saw_return)) {
                return false;
            }
            for (index = 0U; index < expr->as.call.arg_count; ++index) {
                if (!lambda_return_values_fit_target_in_expr(
                        context,
                        expr->as.call.args[index],
                        target_return_type,
                        mode,
                        saw_return)) {
                    return false;
                }
            }
            return true;

        case FENG_EXPR_MEMBER:
            return lambda_return_values_fit_target_in_expr(
                context,
                expr->as.member.object,
                target_return_type,
                mode,
                saw_return);

        case FENG_EXPR_INDEX:
            return lambda_return_values_fit_target_in_expr(
                       context,
                       expr->as.index.object,
                       target_return_type,
                       mode,
                       saw_return) &&
                   lambda_return_values_fit_target_in_expr(
                       context,
                       expr->as.index.index,
                       target_return_type,
                       mode,
                       saw_return);

        case FENG_EXPR_UNARY:
            return lambda_return_values_fit_target_in_expr(
                context,
                expr->as.unary.operand,
                target_return_type,
                mode,
                saw_return);

        case FENG_EXPR_BINARY:
            return lambda_return_values_fit_target_in_expr(
                       context,
                       expr->as.binary.left,
                       target_return_type,
                       mode,
                       saw_return) &&
                   lambda_return_values_fit_target_in_expr(
                       context,
                       expr->as.binary.right,
                       target_return_type,
                       mode,
                       saw_return);

        case FENG_EXPR_CAST:
            return lambda_return_values_fit_target_in_expr(
                context,
                expr->as.cast.value,
                target_return_type,
                mode,
                saw_return);

        case FENG_EXPR_IF:
            return lambda_return_values_fit_target_in_expr(
                       context,
                       expr->as.if_expr.condition,
                       target_return_type,
                       mode,
                       saw_return) &&
                   lambda_return_values_fit_target_in_block(
                       context,
                       expr->as.if_expr.then_block,
                       target_return_type,
                       mode,
                       saw_return) &&
                   lambda_return_values_fit_target_in_block(
                       context,
                       expr->as.if_expr.else_block,
                       target_return_type,
                       mode,
                       saw_return);

        case FENG_EXPR_MATCH:
            if (!lambda_return_values_fit_target_in_expr(
                    context,
                    expr->as.match_expr.target,
                    target_return_type,
                    mode,
                    saw_return)) {
                return false;
            }
            for (index = 0U;
                 index < expr->as.match_expr.branch_count;
                 ++index) {
                const FengMatchBranch *branch =
                    &expr->as.match_expr.branches[index];
                size_t label_index;

                for (label_index = 0U;
                     label_index < branch->label_count;
                     ++label_index) {
                    const FengMatchLabel *label = &branch->labels[label_index];

                    if (!lambda_return_values_fit_target_in_expr(
                            context,
                            label->value,
                            target_return_type,
                            mode,
                            saw_return) ||
                        !lambda_return_values_fit_target_in_expr(
                            context,
                            label->range_low,
                            target_return_type,
                            mode,
                            saw_return) ||
                        !lambda_return_values_fit_target_in_expr(
                            context,
                            label->range_high,
                            target_return_type,
                            mode,
                            saw_return)) {
                        return false;
                    }
                }
                if (!lambda_return_values_fit_target_in_block(
                        context,
                        branch->body,
                        target_return_type,
                        mode,
                        saw_return)) {
                    return false;
                }
            }
            return lambda_return_values_fit_target_in_block(
                context,
                expr->as.match_expr.else_block,
                target_return_type,
                mode,
                saw_return);

        case FENG_EXPR_TRY:
            if (!lambda_return_values_fit_target_in_expr(
                    context,
                    expr->as.try_expr.body,
                    target_return_type,
                    mode,
                    saw_return)) {
                return false;
            }
            for (index = 0U;
                 index < expr->as.try_expr.clause_count;
                 ++index) {
                if (!lambda_return_values_fit_target_in_block(
                        context,
                        expr->as.try_expr.clauses[index].body,
                        target_return_type,
                        mode,
                        saw_return)) {
                    return false;
                }
            }
            return true;

        case FENG_EXPR_ARRAY_NEW:
            return lambda_return_values_fit_target_in_expr(
                context,
                expr->as.array_new.size,
                target_return_type,
                mode,
                saw_return);

        case FENG_EXPR_MATCH_OP:
            if (!lambda_return_values_fit_target_in_expr(
                    context,
                    expr->as.match_op.target,
                    target_return_type,
                    mode,
                    saw_return)) {
                return false;
            }
            for (index = 0U; index < expr->as.match_op.label_count; ++index) {
                const FengMatchLabel *label = &expr->as.match_op.labels[index];

                if (!lambda_return_values_fit_target_in_expr(
                        context,
                        label->value,
                        target_return_type,
                        mode,
                        saw_return) ||
                    !lambda_return_values_fit_target_in_expr(
                        context,
                        label->range_low,
                        target_return_type,
                        mode,
                        saw_return) ||
                    !lambda_return_values_fit_target_in_expr(
                        context,
                        label->range_high,
                        target_return_type,
                        mode,
                        saw_return)) {
                    return false;
                }
            }
            return true;
    }

    return true;
}

/* Check only returns owned by the current block Lambda. Nested Lambda
 * expressions are values and therefore remain independent callable bodies. */
static bool lambda_return_values_fit_target_in_stmt(
    ResolveContext *context,
    const FengStmt *stmt,
    const FengTypeRef *target_return_type,
    LambdaReturnTargetCheckMode mode,
    bool *saw_return) {
    size_t index;

    if (stmt == NULL) {
        return true;
    }
    switch (stmt->kind) {
        case FENG_STMT_BLOCK:
            return lambda_return_values_fit_target_in_block(
                context,
                stmt->as.block,
                target_return_type,
                mode,
                saw_return);

        case FENG_STMT_IF:
            for (index = 0U;
                 index < stmt->as.if_stmt.clause_count;
                 ++index) {
                if (!lambda_return_values_fit_target_in_expr(
                        context,
                        stmt->as.if_stmt.clauses[index].condition,
                        target_return_type,
                        mode,
                        saw_return) ||
                    !lambda_return_values_fit_target_in_block(
                        context,
                        stmt->as.if_stmt.clauses[index].block,
                        target_return_type,
                        mode,
                        saw_return)) {
                    return false;
                }
            }
            return lambda_return_values_fit_target_in_block(
                context,
                stmt->as.if_stmt.else_block,
                target_return_type,
                mode,
                saw_return);

        case FENG_STMT_MATCH:
            if (!lambda_return_values_fit_target_in_expr(
                    context,
                    stmt->as.match_stmt.target,
                    target_return_type,
                    mode,
                    saw_return)) {
                return false;
            }
            for (index = 0U;
                 index < stmt->as.match_stmt.branch_count;
                 ++index) {
                if (!lambda_return_values_fit_target_in_block(
                        context,
                        stmt->as.match_stmt.branches[index].body,
                        target_return_type,
                        mode,
                        saw_return)) {
                    return false;
                }
            }
            return lambda_return_values_fit_target_in_block(
                context,
                stmt->as.match_stmt.else_block,
                target_return_type,
                mode,
                saw_return);

        case FENG_STMT_WHILE:
            return lambda_return_values_fit_target_in_expr(
                       context,
                       stmt->as.while_stmt.condition,
                       target_return_type,
                       mode,
                       saw_return) &&
                   lambda_return_values_fit_target_in_block(
                       context,
                       stmt->as.while_stmt.body,
                       target_return_type,
                       mode,
                       saw_return);

        case FENG_STMT_FOR:
            if (!lambda_return_values_fit_target_in_stmt(
                    context,
                    stmt->as.for_stmt.init,
                    target_return_type,
                    mode,
                    saw_return) ||
                !lambda_return_values_fit_target_in_stmt(
                    context,
                    stmt->as.for_stmt.update,
                    target_return_type,
                    mode,
                    saw_return) ||
                !lambda_return_values_fit_target_in_expr(
                    context,
                    stmt->as.for_stmt.condition,
                    target_return_type,
                    mode,
                    saw_return) ||
                !lambda_return_values_fit_target_in_expr(
                    context,
                    stmt->as.for_stmt.iter_expr,
                    target_return_type,
                    mode,
                    saw_return)) {
                return false;
            }
            return lambda_return_values_fit_target_in_block(
                context,
                stmt->as.for_stmt.body,
                target_return_type,
                mode,
                saw_return);

        case FENG_STMT_TRY:
            return lambda_return_values_fit_target_in_expr(
                context,
                stmt->as.expr,
                target_return_type,
                mode,
                saw_return);

        case FENG_STMT_RETURN: {
            const FengExpr *value = stmt->as.return_value;
            bool target_is_void = type_ref_is_void(target_return_type);
            bool matches;

            if (!lambda_return_values_fit_target_in_expr(
                    context,
                    value,
                    target_return_type,
                    mode,
                    saw_return)) {
                return false;
            }
            if (saw_return != NULL) {
                *saw_return = true;
            }
            if (value == NULL || target_is_void) {
                bool shape_matches = (value == NULL) == target_is_void;

                if (!shape_matches &&
                    mode == LAMBDA_RETURN_TARGET_VALIDATE) {
                    char *target_name =
                        format_type_ref_name(target_return_type);

                    (void)resolver_append_error(
                        context,
                        stmt->token,
                        "AE0501",
                        format_message(
                            "return statement does not match expected type '%s'",
                            target_name != NULL ? target_name : "<type>"));
                    free(target_name);
                }
                return shape_matches;
            }
            matches = expr_matches_expected_type_ref(
                context, value, target_return_type);
            if (mode == LAMBDA_RETURN_TARGET_MATCH_ONLY || matches) {
                if (mode == LAMBDA_RETURN_TARGET_VALIDATE && matches) {
                    return validate_expr_against_expected_type(
                        context, value, target_return_type);
                }
                return matches;
            }
            (void)validate_expr_against_expected_type(
                context, value, target_return_type);
            return false;
        }

        case FENG_STMT_DEFER:
            return lambda_return_values_fit_target_in_block(
                context,
                stmt->as.defer_block,
                target_return_type,
                mode,
                saw_return);

        case FENG_STMT_BINDING:
            return lambda_return_values_fit_target_in_expr(
                context,
                stmt->as.binding.initializer,
                target_return_type,
                mode,
                saw_return);

        case FENG_STMT_ASSIGN:
            return lambda_return_values_fit_target_in_expr(
                       context,
                       stmt->as.assign.target,
                       target_return_type,
                       mode,
                       saw_return) &&
                   lambda_return_values_fit_target_in_expr(
                       context,
                       stmt->as.assign.value,
                       target_return_type,
                       mode,
                       saw_return);

        case FENG_STMT_EXPR:
            return lambda_return_values_fit_target_in_expr(
                context,
                stmt->as.expr,
                target_return_type,
                mode,
                saw_return);

        case FENG_STMT_THROW:
            return lambda_return_values_fit_target_in_expr(
                context,
                stmt->as.throw_value,
                target_return_type,
                mode,
                saw_return);

        case FENG_STMT_BREAK:
        case FENG_STMT_CONTINUE:
            return true;
    }

    return true;
}

/* Visit all current-Lambda return values in source order. */
static bool lambda_return_values_fit_target_in_block(
    ResolveContext *context,
    const FengBlock *block,
    const FengTypeRef *target_return_type,
    LambdaReturnTargetCheckMode mode,
    bool *saw_return) {
    size_t index;

    if (block == NULL || target_return_type == NULL) {
        return true;
    }
    for (index = 0U; index < block->statement_count; ++index) {
        if (!lambda_return_values_fit_target_in_stmt(
                context,
                block->statements[index],
                target_return_type,
                mode,
                saw_return)) {
            return false;
        }
    }
    return true;
}

/* Enforce the return-value shape and normal-fallthrough contract supplied by
 * one callable-form target for a block lambda. The body has already passed
 * ordinary expression and return-type validation before this check runs. */
static bool validate_block_lambda_return_contract(
    ResolveContext *context,
    const FengExpr *lambda_expr,
    const FengTypeRef *target_return_type) {
    bool target_is_void;
    if (context == NULL || lambda_expr == NULL ||
        lambda_expr->kind != FENG_EXPR_LAMBDA ||
        !lambda_expr->as.lambda.is_block_body ||
        target_return_type == NULL) {
        return true;
    }

    target_is_void = type_ref_is_void(target_return_type);
    if (!lambda_return_values_fit_target_in_block(
            context,
            lambda_expr->as.lambda.body_block,
            target_return_type,
            LAMBDA_RETURN_TARGET_VALIDATE,
            NULL)) {
        return false;
    }
    if (!target_is_void &&
        callable_body_can_fall_through(lambda_expr->as.lambda.body_block)) {
        (void)resolver_append_error(
            context,
            lambda_expr->token,
            "AE0515",
            duplicate_cstr(
                "non-void block lambda can reach the end of its body without returning a value"));
        return false;
    }
    return true;
}

/* Recreate a resolved Lambda's local type scope when its callable target only
 * becomes known after call-overload selection. No body expression is emitted
 * or resolved again; this pass only commits target-directed return fitting. */
static bool validate_block_lambda_return_contract_in_fresh_scope(
    ResolveContext *context,
    const FengExpr *lambda_expr,
    const FengTypeRef *target_return_type) {
    bool ok = true;
    size_t param_index;

    if (context == NULL || lambda_expr == NULL ||
        lambda_expr->kind != FENG_EXPR_LAMBDA ||
        !lambda_expr->as.lambda.is_block_body) {
        return true;
    }
    if (!resolver_push_scope(context)) {
        return false;
    }
    for (param_index = 0U;
         param_index < lambda_expr->as.lambda.param_count && ok;
         ++param_index) {
        ok = resolver_add_local_typed_name(
            context,
            lambda_expr->as.lambda.params[param_index].name,
            inferred_expr_type_from_type_ref(
                lambda_expr->as.lambda.params[param_index].type),
            lambda_expr->as.lambda.params[param_index].mutability);
    }
    if (ok) {
        ok = validate_block_lambda_return_contract(
            context, lambda_expr, target_return_type);
    }
    resolver_pop_scope(context);
    return ok;
}

/* Validate every direct block-lambda argument against the instantiated
 * callable-form parameter that made the call applicable. Ordinary argument
 * type matching has already selected this callable surface. */
static bool validate_function_type_call_block_lambda_arguments(
    ResolveContext *context,
    const FengDecl *function_type_decl,
    const FengTypeRef *function_type_ref,
    FengExpr *const *args,
    size_t arg_count) {
    const FengParameter *params;
    size_t param_count;
    bool is_variadic;
    size_t fixed_count;
    size_t arg_index;

    if (context == NULL || !decl_is_function_type(function_type_decl)) {
        return true;
    }
    params = function_type_decl->as.spec_decl.as.callable.params;
    param_count = function_type_decl->as.spec_decl.as.callable.param_count;
    is_variadic = param_count > 0U && params[param_count - 1U].is_variadic;
    fixed_count = is_variadic ? param_count - 1U : param_count;

    for (arg_index = 0U; arg_index < arg_count; ++arg_index) {
        const FengExpr *arg = args != NULL ? args[arg_index] : NULL;
        const FengTypeRef *declared_param_type;
        const FengTypeRef *param_type;
        const FengDecl *param_function_type_decl;
        const FengTypeRef *target_return_type;

        if (arg == NULL || arg->kind != FENG_EXPR_LAMBDA ||
            !arg->as.lambda.is_block_body) {
            continue;
        }
        if (arg_index < fixed_count || arg->is_prepacked_variadic_arg) {
            if (arg_index >= param_count) {
                continue;
            }
            declared_param_type = params[arg_index].type;
        } else {
            declared_param_type = params[fixed_count].type->as.inner;
        }
        param_type = substitute_spec_member_type_ref_for_instance(
            context,
            function_type_decl,
            function_type_ref,
            declared_param_type);
        param_function_type_decl = resolve_function_type_decl(context, param_type);
        if (param_function_type_decl == NULL) {
            continue;
        }
        target_return_type = substitute_spec_member_type_ref_for_instance(
            context,
            param_function_type_decl,
            param_type,
            param_function_type_decl->as.spec_decl.as.callable.return_type);
        if (!validate_block_lambda_return_contract_in_fresh_scope(
                context, arg, target_return_type)) {
            return false;
        }
    }
    return true;
}

/* Saved callable-body state while a lambda body is being analysed. The
 * synthetic signature makes every lambda an explicit callable boundary even
 * in secondary analyses that revisit its body. */
typedef struct LambdaCallableContext {
    const FengTypeMember *body_member;
    const FengCallableSignature *signature;
    InferredExprType inferred_return;
    bool saw_return;
    bool has_escaping_exception;
    size_t exception_capture_depth;
    size_t loop_depth;
    ExpressionBranchBoundary expression_branch_boundary;
    size_t defer_depth;
    bool self_capturable;
    FengCallableSignature synthetic_signature;
} LambdaCallableContext;

/* Enter the independent callable-body context of one lambda without changing
 * its enclosing lexical member identity or allocating temporary storage. */
static void lambda_enter_callable_context(ResolveContext *context,
                                          const FengExpr *expr,
                                          LambdaCallableContext *saved) {
    saved->body_member = context->current_callable_body_member;
    saved->signature = context->current_callable_signature;
    saved->inferred_return = context->current_callable_inferred_return_type;
    saved->saw_return = context->current_callable_saw_return;
    saved->has_escaping_exception = context->current_callable_has_escaping_exception;
    saved->exception_capture_depth = context->exception_capture_depth;
    saved->loop_depth = context->loop_depth;
    saved->expression_branch_boundary = context->expression_branch_boundary;
    saved->defer_depth = context->defer_depth;
    saved->self_capturable = context->self_capturable;

    memset(&saved->synthetic_signature, 0, sizeof(saved->synthetic_signature));
    saved->synthetic_signature.token = expr->token;
    saved->synthetic_signature.params = expr->as.lambda.params;
    saved->synthetic_signature.param_count = expr->as.lambda.param_count;
    saved->synthetic_signature.return_type = NULL;
    saved->synthetic_signature.body = expr->as.lambda.is_block_body
                                          ? expr->as.lambda.body_block
                                          : NULL;

    context->current_callable_body_member = NULL;
    context->current_callable_signature = &saved->synthetic_signature;
    context->current_callable_inferred_return_type = inferred_expr_type_unknown();
    context->current_callable_saw_return = false;
    context->current_callable_has_escaping_exception = false;
    context->exception_capture_depth = 0U;
    context->loop_depth = 0U;
    context->expression_branch_boundary = EXPRESSION_BRANCH_BOUNDARY_NONE;
    context->defer_depth = 0U;
}

/* Restore the enclosing callable-body state after a lambda-body analysis. */
static void lambda_leave_callable_context(ResolveContext *context,
                                          const LambdaCallableContext *saved) {
    context->current_callable_body_member = saved->body_member;
    context->current_callable_signature = saved->signature;
    context->current_callable_inferred_return_type = saved->inferred_return;
    context->current_callable_saw_return = saved->saw_return;
    context->current_callable_has_escaping_exception = saved->has_escaping_exception;
    context->exception_capture_depth = saved->exception_capture_depth;
    context->loop_depth = saved->loop_depth;
    context->expression_branch_boundary = saved->expression_branch_boundary;
    context->defer_depth = saved->defer_depth;
    context->self_capturable = saved->self_capturable;
}

static bool lambda_expr_may_escape_exception(ResolveContext *context, const FengExpr *expr) {
    LambdaCallableContext callable_context;
    bool escapes = false;
    size_t param_index;
    bool ok = true;

    /* Exception escape is a derived analysis of a body already accepted by
     * primary resolution. Replaying an invalid body would only duplicate its
     * diagnostics and cannot contribute a usable exception fact. */
    if (context == NULL || expr == NULL || expr->kind != FENG_EXPR_LAMBDA ||
        context->error_count == NULL || *context->error_count > 0U) {
        return false;
    }

    if (!resolver_push_scope(context)) {
        return false;
    }

    lambda_enter_callable_context(context, expr, &callable_context);

    for (param_index = 0U; param_index < expr->as.lambda.param_count && ok; ++param_index) {
        ok = resolver_add_local_typed_name(
            context,
            expr->as.lambda.params[param_index].name,
            inferred_expr_type_from_type_ref(expr->as.lambda.params[param_index].type),
            expr->as.lambda.params[param_index].mutability);
    }

    if (ok) {
        if (expr->as.lambda.is_block_body) {
            ok = resolve_block_contents(context, expr->as.lambda.body_block, context->self_capturable);
        } else {
            ok = resolve_expr(context, expr->as.lambda.body, context->self_capturable);
        }
    }
    escapes = ok && context->current_callable_has_escaping_exception;
    lambda_leave_callable_context(context, &callable_context);

    resolver_pop_scope(context);
    return escapes;
}

static bool callable_value_expr_may_escape_exception(ResolveContext *context,
                                                     const FengExpr *expr,
                                                     const FengTypeRef *expected_type_ref,
                                                     size_t depth) {
    CallableValueResolution resolution;

    if (context == NULL || expr == NULL || depth > 32U) {
        return false;
    }

    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER: {
            const LocalNameEntry *local_entry =
                resolver_find_local_name_entry(context, expr->as.identifier);

            if (local_entry != NULL) {
                const FengTypeRef *source_type_ref =
                    local_entry->type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF
                        ? local_entry->type.type_ref
                        : expected_type_ref;

                if (local_entry->type.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA) {
                    return lambda_expr_may_escape_exception(context, local_entry->type.lambda_expr);
                }
                if (local_entry->source_expr != NULL) {
                    return callable_value_expr_may_escape_exception(
                        context, local_entry->source_expr, source_type_ref, depth + 1U);
                }
                return false;
            }

            {
                const VisibleValueEntry *visible_value =
                    find_visible_value(context->visible_values,
                                       context->visible_value_count,
                                       expr->as.identifier);

                if (visible_value != NULL && !visible_value->is_function && visible_value->decl != NULL &&
                    visible_value->decl->kind == FENG_DECL_GLOBAL_BINDING &&
                    visible_value->decl->as.binding.initializer != NULL) {
                    const FengTypeRef *source_type_ref = visible_value->decl->as.binding.type != NULL
                                                             ? visible_value->decl->as.binding.type
                                                             : expected_type_ref;

                    return callable_value_expr_may_escape_exception(context,
                                                                    visible_value->decl->as.binding.initializer,
                                                                    source_type_ref,
                                                                    depth + 1U);
                }
            }
            break;
        }

        case FENG_EXPR_MEMBER: {
            ResolvedModuleMemberTarget target;

            if (resolve_module_member_target(context, expr, &target)) {
                const FengDecl *binding_decl =
                    find_module_public_binding_decl(target.module,
                                                    target.member_name);

                if (binding_decl != NULL &&
                    binding_decl->kind == FENG_DECL_GLOBAL_BINDING &&
                    binding_decl->as.binding.initializer != NULL) {
                    const FengTypeRef *source_type_ref =
                        binding_decl->as.binding.type != NULL
                            ? binding_decl->as.binding.type
                            : expected_type_ref;

                    return callable_value_expr_may_escape_exception(
                        context,
                        binding_decl->as.binding.initializer,
                        source_type_ref,
                        depth + 1U);
                }
            }
            break;
        }

        case FENG_EXPR_LAMBDA:
            return lambda_expr_may_escape_exception(context, expr);

        case FENG_EXPR_IF: {
            const FengExpr *then_yield = block_yield_expression(expr->as.if_expr.then_block);
            const FengExpr *else_yield = block_yield_expression(expr->as.if_expr.else_block);

            return (then_yield != NULL && callable_value_expr_may_escape_exception(
                                              context, then_yield, expected_type_ref, depth + 1U)) ||
                   (else_yield != NULL && callable_value_expr_may_escape_exception(
                                              context, else_yield, expected_type_ref, depth + 1U));
        }

        case FENG_EXPR_MATCH: {
            size_t branch_index;
            const FengExpr *else_yield = block_yield_expression(expr->as.match_expr.else_block);

            for (branch_index = 0U; branch_index < expr->as.match_expr.branch_count; ++branch_index) {
                const FengExpr *branch_yield =
                    block_yield_expression(expr->as.match_expr.branches[branch_index].body);

                if (branch_yield != NULL && callable_value_expr_may_escape_exception(
                                                context, branch_yield, expected_type_ref, depth + 1U)) {
                    return true;
                }
            }

            return else_yield != NULL && callable_value_expr_may_escape_exception(
                                             context, else_yield, expected_type_ref, depth + 1U);
        }

        case FENG_EXPR_TRY: {
            if (callable_value_expr_may_escape_exception(
                    context, expr->as.try_expr.body, expected_type_ref, depth + 1U)) {
                return true;
            }
            for (size_t clause_index = 0U;
                 clause_index < expr->as.try_expr.clause_count;
                 ++clause_index) {
                const FengExpr *clause_yield =
                    block_yield_expression(expr->as.try_expr.clauses[clause_index].body);

                if (clause_yield != NULL && callable_value_expr_may_escape_exception(
                                                context,
                                                clause_yield,
                                                expected_type_ref,
                                                depth + 1U)) {
                    return true;
                }
            }
            return false;
        }

        case FENG_EXPR_CAST:
            return callable_value_expr_may_escape_exception(
                context, expr->as.cast.value, expected_type_ref, depth + 1U);

        case FENG_EXPR_MATCH_OP: {
            /* infix match operator yields bool, not a callable value; never
             * escapes exception via the bool result. */
            (void)expected_type_ref;
            (void)depth;
            return false;
        }

        default:
            break;
    }

    if (expected_type_ref == NULL) {
        return false;
    }

    resolution = resolve_expr_callable_value(context, expr, expected_type_ref);
    if (resolution.kind != FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE) {
        return false;
    }
    if (resolution.callable != NULL) {
        return callable_may_escape_exception(context, resolution.callable);
    }
    if (resolution.lambda_expr != NULL) {
        return lambda_expr_may_escape_exception(context, resolution.lambda_expr);
    }

    return false;
}

static void note_callable_value_expr_exception_escape(ResolveContext *context,
                                                      const FengExpr *callee) {
    InferredExprType callee_type;
    const FengTypeRef *expected_type_ref = NULL;

    if (context == NULL || callee == NULL) {
        return;
    }

    callee_type = infer_expr_type(context, callee);
    if (callee_type.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA) {
        if (lambda_expr_may_escape_exception(context, callee_type.lambda_expr)) {
            note_current_callable_exception_escape(context);
        }
        return;
    }

    if (callee_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        expected_type_ref = callee_type.type_ref;
    }

    if (callable_value_expr_may_escape_exception(context, callee, expected_type_ref, 0U)) {
        note_current_callable_exception_escape(context);
    }
}

/* G4-12: Returns true when type_ref is a direct reference to one of the
 * callable's own type parameters (single-segment, no type args).  Such
 * positions accept any argument type (wildcard) during overload matching. */
static bool param_type_is_type_param_ref(const FengCallableSignature *callable,
                                         const FengTypeRef *type_ref) {
    size_t i;

    if (callable == NULL || callable->type_param_count == 0U) {
        return false;
    }
    if (type_ref == NULL ||
        type_ref->kind != FENG_TYPE_REF_NAMED ||
        type_ref->as.named.segment_count != 1U ||
        type_ref->as.named.type_arg_count != 0U) {
        return false;
    }
    for (i = 0U; i < callable->type_param_count; ++i) {
        if (slice_equals(callable->type_params[i].name, type_ref->as.named.segments[0])) {
            return true;
        }
    }
    return false;
}

/* Policy gate for the new wrapped-shape inference path. Only top-level extern
 * calls may enable recursive matching such as `T[]` <- `int[]`; all ordinary
 * Feng call sites remain on the narrower pre-existing direct-`T` behavior. */
static bool call_expr_allows_wrapped_generic_extern_inference(const FengExpr *call_expr) {
    const FengResolvedCallable *resolved_callable;

    if (call_expr == NULL || call_expr->kind != FENG_EXPR_CALL) {
        return false;
    }
    /* Wrapped-shape inference such as `T[]` -> `int[]` is a targeted extension
     * for top-level generic extern calls. Ordinary Feng call resolution keeps
     * the pre-existing direct-`T` inference surface unchanged. */
    resolved_callable = &call_expr->as.call.resolved_callable;
    return resolved_callable->kind == FENG_RESOLVED_CALLABLE_FUNCTION &&
           resolved_callable->function_decl != NULL &&
           resolved_callable->function_decl->is_extern;
}

/* Resolve one of the callable's declared type parameters by name. This is a
 * small shared lookup helper used by the generic argument collectors below. */
static bool callable_find_type_param_index(const FengCallableSignature *callable,
                                           FengSlice name,
                                           size_t *out_index) {
    size_t i;

    if (callable == NULL || out_index == NULL) {
        return false;
    }
    for (i = 0U; i < callable->type_param_count; ++i) {
        if (slice_equals(callable->type_params[i].name, name)) {
            *out_index = i;
            return true;
        }
    }
    return false;
}

/* Shape probe: report whether a parameter type still mentions the callable's
 * own type params anywhere inside it. Callers use this to skip wrapped-shape
 * inference work for fully concrete parameter types. */
static bool callable_type_ref_contains_type_params(const FengCallableSignature *callable,
                                                   const FengTypeRef *type_ref) {
    size_t i;

    if (type_ref == NULL) {
        return false;
    }
    if (param_type_is_type_param_ref(callable, type_ref)) {
        return true;
    }

    switch (type_ref->kind) {
        case FENG_TYPE_REF_POINTER:
        case FENG_TYPE_REF_ARRAY:
            return callable_type_ref_contains_type_params(callable, type_ref->as.inner);

        case FENG_TYPE_REF_NAMED:
            for (i = 0U; i < type_ref->as.named.type_arg_count; ++i) {
                if (callable_type_ref_contains_type_params(callable,
                                                           type_ref->as.named.type_args[i])) {
                    return true;
                }
            }
            return false;
    }

    return false;
}

/* Policy-free helper: project an argument expression into a comparable type-ref
 * shape for generic argument collection. This was added in this change because
 * the new wrapped-shape inference path reuses a single type-ref unifier, while
 * call arguments arrive as expressions rather than ready-made type refs. This
 * helper does not decide whether wrapped inference is allowed; extern-only
 * gating happens at the callers that pass `allow_wrapped_inference` into
 * callable_collect_call_type_args / the parameter-matching helpers. */
static const FengTypeRef *callable_arg_type_ref_from_expr(ResolveContext *context,
                                                          const FengExpr *arg_expr,
                                                          FengTypeRef **owned_type_ref) {
    InferredExprType arg_type;

    if (owned_type_ref != NULL) {
        *owned_type_ref = NULL;
    }
    if (context == NULL || arg_expr == NULL) {
        return NULL;
    }

    arg_type = infer_expr_type(context, arg_expr);
    if (arg_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        return arg_type.type_ref;
    }
    if (owned_type_ref == NULL) {
        return NULL;
    }

    *owned_type_ref = create_type_ref_from_inferred_type(&arg_type, arg_expr->token);
    return *owned_type_ref;
}

static bool expr_is_existing_array_for_expected_type_ref(ResolveContext *context,
                                                         const FengExpr *expr,
                                                         const FengTypeRef *expected_array_type) {
    FengTypeRef *owned_type_ref = NULL;
    const FengTypeRef *actual_type_ref;
    bool matches;

    if (context == NULL || expr == NULL || expected_array_type == NULL ||
        expected_array_type->kind != FENG_TYPE_REF_ARRAY) {
        return false;
    }

    actual_type_ref = callable_arg_type_ref_from_expr(context, expr, &owned_type_ref);
    matches = actual_type_ref != NULL &&
              actual_type_ref->kind == FENG_TYPE_REF_ARRAY &&
              type_refs_semantically_equal(context, expected_array_type, actual_type_ref);

    if (owned_type_ref != NULL) {
        free_synthetic_type_ref(owned_type_ref);
    }
    return matches;
 }

/* Structural unification helper shared by both direct-`T` inference and the
 * narrower wrapped-shape inference path. It is intentionally generic; whether
 * wrapped shapes such as `T[]` may reach here is decided before the call. */
static bool callable_collect_type_args_from_type_refs(ResolveContext *context,
                                                      const FengCallableSignature *callable,
                                                      const FengTypeRef *param_type,
                                                      const FengTypeRef *actual_type,
                                                      FengTypeRef **type_args,
                                                      bool *owned_type_args) {
    size_t type_arg_index;

    if (context == NULL || callable == NULL || param_type == NULL || actual_type == NULL ||
        type_args == NULL || owned_type_args == NULL) {
        return false;
    }

    if (param_type_is_type_param_ref(callable, param_type)) {
        if (!callable_find_type_param_index(callable,
                                            param_type->as.named.segments[0],
                                            &type_arg_index)) {
            return false;
        }
        if (type_args[type_arg_index] == NULL) {
            type_args[type_arg_index] = clone_type_ref_for_inference(actual_type);
            if (type_args[type_arg_index] == NULL) {
                return false;
            }
            owned_type_args[type_arg_index] = true;
            return true;
        }
        return type_refs_semantically_equal(context,
                                            type_args[type_arg_index],
                                            actual_type);
    }

    if (param_type->kind != actual_type->kind) {
        return false;
    }

    switch (param_type->kind) {
        case FENG_TYPE_REF_POINTER:
            return callable_collect_type_args_from_type_refs(context,
                                                             callable,
                                                             param_type->as.inner,
                                                             actual_type->as.inner,
                                                             type_args,
                                                             owned_type_args);

        case FENG_TYPE_REF_ARRAY:
            if (param_type->array_element_writable != actual_type->array_element_writable) {
                return false;
            }
            return callable_collect_type_args_from_type_refs(context,
                                                             callable,
                                                             param_type->as.inner,
                                                             actual_type->as.inner,
                                                             type_args,
                                                             owned_type_args);

        case FENG_TYPE_REF_NAMED: {
            const FengDecl *param_decl = resolve_type_ref_decl(context, param_type);
            const FengDecl *actual_decl = resolve_type_ref_decl(context, actual_type);
            size_t i;

            if (param_decl != NULL || actual_decl != NULL) {
                if (param_decl != actual_decl) {
                    return false;
                }
            } else if (!type_ref_equals(param_type, actual_type)) {
                return false;
            }

            if (param_type->as.named.type_arg_count != actual_type->as.named.type_arg_count) {
                return false;
            }
            for (i = 0U; i < param_type->as.named.type_arg_count; ++i) {
                if (!callable_collect_type_args_from_type_refs(context,
                                                               callable,
                                                               param_type->as.named.type_args[i],
                                                               actual_type->as.named.type_args[i],
                                                               type_args,
                                                               owned_type_args)) {
                    return false;
                }
            }
            return true;
        }
    }

    return false;
}

/* Thin adapter: recover the argument's type-ref shape, then feed the generic
 * type-ref unifier above. Like the helpers it calls, this is not extern-only;
 * the extern-only boundary remains the wrapped-inference gate at the caller. */
static bool callable_collect_type_args_from_arg_expr(ResolveContext *context,
                                                     const FengCallableSignature *callable,
                                                     const FengTypeRef *param_type,
                                                     const FengExpr *arg_expr,
                                                     FengTypeRef **type_args,
                                                     bool *owned_type_args) {
    FengTypeRef *owned_actual_type_ref = NULL;
    const FengTypeRef *actual_type_ref = callable_arg_type_ref_from_expr(context,
                                                                         arg_expr,
                                                                         &owned_actual_type_ref);
    bool ok;

    if (arg_expr != NULL && arg_expr->kind == FENG_EXPR_TUPLE_LITERAL) {
        const FengDecl *tuple_decl = resolve_tuple_type_ref_decl(context, param_type);
        size_t item_index;

        if (tuple_decl == NULL ||
            arg_expr->as.tuple_literal.count != tuple_decl->as.type_decl.member_count) {
            return false;
        }
        for (item_index = 0U; item_index < arg_expr->as.tuple_literal.count; ++item_index) {
            const FengTypeRef *field_type =
                tuple_field_type_for_instance(context, tuple_decl, param_type, item_index);
            InferredExprType item_type =
                infer_expr_type(context, arg_expr->as.tuple_literal.items[item_index]);
            FengTypeRef *owned_item_type_ref = create_type_ref_from_inferred_type(
                &item_type,
                arg_expr->as.tuple_literal.items[item_index]->token);

            if (field_type == NULL || owned_item_type_ref == NULL) {
                free_synthetic_type_ref(owned_item_type_ref);
                return false;
            }
            ok = callable_collect_type_args_from_type_refs(context,
                                                           callable,
                                                           field_type,
                                                           owned_item_type_ref,
                                                           type_args,
                                                           owned_type_args);
            free_synthetic_type_ref(owned_item_type_ref);
            if (!ok) {
                return false;
            }
        }
        return true;
    }

    if (actual_type_ref == NULL) {
        return false;
    }
    ok = callable_collect_type_args_from_type_refs(context,
                                                   callable,
                                                   param_type,
                                                   actual_type_ref,
                                                   type_args,
                                                   owned_type_args);
    if (owned_actual_type_ref != NULL) {
        free_synthetic_type_ref(owned_actual_type_ref);
    }
    return ok;
}

/* Collect missing callable type arguments by structurally comparing the
 * caller-view return type with the current expression target. Earlier explicit
 * and argument-derived bindings remain authoritative; target inference fills
 * only unbound slots, while ordinary expected-type validation checks the final
 * result compatibility after overload selection. */
static bool callable_collect_missing_type_args_from_target_refs(
    ResolveContext *context,
    const FengCallableSignature *callable,
    const FengTypeRef *return_type,
    const FengTypeRef *target_type,
    FengTypeRef **type_args,
    bool *owned_type_args) {
    size_t type_arg_index;

    if (context == NULL || callable == NULL || return_type == NULL ||
        target_type == NULL || type_args == NULL || owned_type_args == NULL) {
        return false;
    }

    if (param_type_is_type_param_ref(callable, return_type)) {
        if (!callable_find_type_param_index(callable,
                                            return_type->as.named.segments[0],
                                            &type_arg_index)) {
            return false;
        }
        if (type_args[type_arg_index] != NULL) {
            return true;
        }
        type_args[type_arg_index] = clone_type_ref_for_inference(target_type);
        if (type_args[type_arg_index] == NULL) {
            return false;
        }
        owned_type_args[type_arg_index] = true;
        return true;
    }

    if (return_type->kind != target_type->kind) {
        return false;
    }
    switch (return_type->kind) {
        case FENG_TYPE_REF_POINTER:
        case FENG_TYPE_REF_ARRAY:
            return callable_collect_missing_type_args_from_target_refs(
                context,
                callable,
                return_type->as.inner,
                target_type->as.inner,
                type_args,
                owned_type_args);

        case FENG_TYPE_REF_NAMED: {
            const FengDecl *return_decl = resolve_type_ref_decl(context, return_type);
            const FengDecl *target_decl = resolve_type_ref_decl(context, target_type);
            size_t index;

            if (return_decl != NULL || target_decl != NULL) {
                if (return_decl != target_decl) {
                    return false;
                }
            } else if (!type_ref_equals(return_type, target_type)) {
                return false;
            }
            if (return_type->as.named.type_arg_count !=
                target_type->as.named.type_arg_count) {
                return false;
            }
            for (index = 0U;
                 index < return_type->as.named.type_arg_count;
                 ++index) {
                if (!callable_collect_missing_type_args_from_target_refs(
                        context,
                        callable,
                        return_type->as.named.type_args[index],
                        target_type->as.named.type_args[index],
                        type_args,
                        owned_type_args)) {
                    return false;
                }
            }
            return true;
        }
    }
    return false;
}

/* Merge the current expression target into callable type arguments through
 * the caller-view return type. The target path supports both direct T and
 * nested shapes such as Composite<T>; explicit generic calls deliberately
 * skip this inference source and only validate their result afterward. */
static bool callable_collect_type_args_from_target(
    ResolveContext *context,
    bool has_explicit_type_args,
    const FengCallableSignature *callable,
    const FengTypeRef *target_inference_return_type,
    FengTypeRef **type_args,
    bool *owned_type_args) {
    const FengTypeRef *expected_type;

    if (context == NULL || callable == NULL ||
        type_args == NULL || owned_type_args == NULL) {
        return false;
    }
    if (has_explicit_type_args ||
        target_inference_return_type == NULL ||
        !callable_type_ref_contains_type_params(callable,
                                                target_inference_return_type)) {
        return true;
    }

    expected_type = context->current_expr_expected_type_ref;
    if (expected_type == NULL) {
        return true;
    }
    return callable_collect_missing_type_args_from_target_refs(
        context,
        callable,
        target_inference_return_type,
        expected_type,
        type_args,
        owned_type_args);
}

/* Central type-argument collector for a call expression. It merges three
 * sources in order: explicit type args, call-argument types, and the current
 * target type. Wrapped call-argument shapes remain guarded by
 * `allow_wrapped_inference`; return-to-target inference always uses the full
 * structural shape required by the generic specification.
 *
 * During ordinary overload applicability probing, direct `T` positions keep
 * the first inferred binding and deliberately tolerate later incompatible
 * argument types; the selected-call metadata path passes
 * preserve_first_direct_binding=true to reproduce that established decision
 * exactly. Other consumers retain strict unification. */
static bool callable_collect_call_type_args(ResolveContext *context,
                                            const FengExpr *call_expr,
                                            const FengCallableSignature *callable,
                                            const FengTypeRef *target_inference_return_type,
                                            bool allow_wrapped_inference,
                                            bool preserve_first_direct_binding,
                                            FengTypeRef **type_args,
                                            bool *owned_type_args) {
    size_t type_param_index;
    size_t arg_index;

    if (context == NULL || call_expr == NULL || call_expr->kind != FENG_EXPR_CALL ||
        callable == NULL || type_args == NULL || owned_type_args == NULL) {
        return false;
    }

    for (type_param_index = 0U;
         type_param_index < callable->type_param_count &&
         call_expr->as.call.has_explicit_type_args &&
         type_param_index < call_expr->as.call.explicit_type_arg_count;
         ++type_param_index) {
        type_args[type_param_index] =
            clone_type_ref_for_inference(call_expr->as.call.explicit_type_args[type_param_index]);
        if (type_args[type_param_index] == NULL) {
            return false;
        }
        owned_type_args[type_param_index] = true;
    }

    for (arg_index = 0U;
         arg_index < callable->param_count && arg_index < call_expr->as.call.arg_count;
         ++arg_index) {
        const FengTypeRef *param_type = callable->params[arg_index].type;

        if (param_type_is_type_param_ref(callable, param_type)) {
            /* When explicit type args are provided, the type param already
             * has a concrete binding.  Try to adapt literal / untyped args to
             * the explicit type so that e.g. Util.id<i32>(41),
             * Util.id<Pair>((1, 2)), or onclick<Func>((id: int) -> foo())
             * works regardless of the literal's default inference.
             * expr_matches_expected_type_ref dispatches by expression kind
             * (numeric, tuple, lambda, array) and safely returns false for
             * expressions that cannot be adapted.
             *
             * If adaptation succeeds, skip inference to avoid spurious
             * failures (e.g. tuple literal against bare type param T).
             * If adaptation fails, fall through to inference so that genuine
             * type mismatches (e.g. string arg against explicit i32) are
             * caught by the normal type-argument conflict check. */
            if (call_expr->as.call.has_explicit_type_args &&
                call_expr->as.call.args[arg_index] != NULL) {
                size_t tp_index = 0U;
                if (callable_find_type_param_index(
                        callable,
                        param_type->as.named.segments[0],
                        &tp_index) &&
                    tp_index < call_expr->as.call.explicit_type_arg_count &&
                    type_args[tp_index] != NULL &&
                    expr_matches_expected_type_ref(
                        context,
                        call_expr->as.call.args[arg_index],
                        type_args[tp_index])) {
                    continue;
                }
            }
            if (!callable_collect_type_args_from_arg_expr(context,
                                                          callable,
                                                          param_type,
                                                          call_expr->as.call.args[arg_index],
                                                          type_args,
                                                          owned_type_args)) {
                if (!preserve_first_direct_binding) {
                    return false;
                }
            }
            continue;
        }
        if ((!allow_wrapped_inference &&
             !call_expr->as.call.args[arg_index]->is_prepacked_variadic_arg) ||
            !callable_type_ref_contains_type_params(callable, param_type)) {
            continue;
        }
        /* Wrapped-shape inference such as `T[]` -> `int[]` remains scoped to
         * generic extern calls, except that explicit prepacked variadic arrays
         * necessarily expose the normalized T[] parameter shape. */
        if (!callable_collect_type_args_from_arg_expr(context,
                                                      callable,
                                                      param_type,
                                                      call_expr->as.call.args[arg_index],
                                                      type_args,
                                                      owned_type_args)) {
            return false;
        }
    }

    return callable_collect_type_args_from_target(
        context,
        call_expr->as.call.has_explicit_type_args,
        callable,
        target_inference_return_type,
        type_args,
        owned_type_args);
}

/* Overload match priority tiers, shared by every resolve_*_overload path.
 * With explicit type args the existing 0/1/2 ranking is preserved (an explicit
 * arity match is best). Without explicit type args, a non-generic candidate is
 * always preferred over a generic one: non-generic exact match (0) beats
 * non-generic inexact match (1), which in turn beats any generic,
 * inference-matched candidate (2). */
static int compute_overload_match_priority(bool has_explicit_type_args,
                                            size_t explicit_type_arg_count,
                                            size_t type_param_count,
                                            bool exactly_match) {
    if (has_explicit_type_args) {
        if (type_param_count == explicit_type_arg_count) {
            return 0;
        }
        return type_param_count > 0U ? 1 : 2;
    }
    if (type_param_count > 0U) {
        return 2;
    }
    return exactly_match ? 0 : 1;
}

/* Return the explicit prepacked-variadic argument index, if one is present. */
static bool find_prepacked_variadic_arg(FengExpr *const *args,
                                        size_t arg_count,
                                        size_t *out_index) {
    size_t index;

    if (out_index != NULL) {
        *out_index = 0U;
    }
    for (index = 0U; index < arg_count; ++index) {
        if (args != NULL && args[index] != NULL &&
            args[index]->is_prepacked_variadic_arg) {
            if (out_index != NULL) {
                *out_index = index;
            }
            return true;
        }
    }
    return false;
}

/* Validate the call-shape constraints that do not require expression typing. */
static PrepackedVariadicRejection prepacked_variadic_shape_rejection(
    FengExpr *const *args,
    size_t arg_count,
    bool is_variadic,
    size_t fixed_count) {
    size_t spread_index;

    if (!find_prepacked_variadic_arg(args, arg_count, &spread_index)) {
        return FENG_PREPACKED_VARIADIC_REJECTION_NONE;
    }
    if (!is_variadic) {
        return FENG_PREPACKED_VARIADIC_REJECTION_TARGET_NOT_VARIADIC;
    }
    if (spread_index != fixed_count || spread_index + 1U != arg_count) {
        return FENG_PREPACKED_VARIADIC_REJECTION_NOT_FIRST_VARIADIC;
    }
    return FENG_PREPACKED_VARIADIC_REJECTION_NONE;
}

/* Preserve the most specific rejection observed while probing overloads. */
static void merge_prepacked_variadic_rejection(
    PrepackedVariadicRejection *target,
    PrepackedVariadicRejection candidate) {
    if (target != NULL && candidate > *target) {
        *target = candidate;
    }
}

/* Top-level callable matcher. Ordinary parameters still use the normal
 * expected-type check; only parameter shapes that mention type params may
 * divert into generic argument collection, and only when the caller has opted
 * into wrapped inference. */
static bool callable_parameters_match_args(ResolveContext *context,
                                           const FengCallableSignature *callable,
                                           FengExpr *const *args,
                                           size_t arg_count,
                                           const FengTypeRef *const *explicit_type_args,
                                           size_t explicit_type_arg_count,
                                           bool allow_wrapped_inference,
                                           bool *out_rejected_existing_array_for_variadic,
                                           PrepackedVariadicRejection *out_prepacked_variadic_rejection) {
    size_t arg_index;
    FengTypeRef **type_args = NULL;
    bool *owned_type_args = NULL;
    bool ok = true;
    bool is_variadic = callable->param_count > 0U &&
                       callable->params[callable->param_count - 1U].is_variadic;
    size_t fixed_count = is_variadic ? callable->param_count - 1U : callable->param_count;
    PrepackedVariadicRejection spread_rejection =
        prepacked_variadic_shape_rejection(args, arg_count, is_variadic, fixed_count);
    /* Suppress literal type commit during overload candidate probing so that
     * each candidate test does not overwrite the literal node's type field. */
    bool saved_suppress = context->suppress_literal_type_commit;
    context->suppress_literal_type_commit = true;

    if (out_rejected_existing_array_for_variadic != NULL) {
        *out_rejected_existing_array_for_variadic = false;
    }
    if (out_prepacked_variadic_rejection != NULL) {
        *out_prepacked_variadic_rejection = spread_rejection;
    }
    if (spread_rejection != FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
        context->suppress_literal_type_commit = saved_suppress;
        return false;
    }

    if (is_variadic) {
        if (arg_count < fixed_count) {
            context->suppress_literal_type_commit = saved_suppress;
            return false;
        }
    } else {
        if (callable->param_count != arg_count) {
            context->suppress_literal_type_commit = saved_suppress;
            return false;
        }
    }
    if (callable->type_param_count > 0U) {
        type_args = calloc(callable->type_param_count, sizeof *type_args);
        owned_type_args = calloc(callable->type_param_count, sizeof *owned_type_args);
        if (type_args == NULL || owned_type_args == NULL) {
            free(type_args);
            free(owned_type_args);
            context->suppress_literal_type_commit = saved_suppress;
            return false;
        }
        if (explicit_type_args != NULL &&
            explicit_type_arg_count == callable->type_param_count) {
            for (arg_index = 0U;
                 arg_index < callable->type_param_count;
                 ++arg_index) {
                type_args[arg_index] =
                    clone_type_ref_for_inference(explicit_type_args[arg_index]);
                if (type_args[arg_index] == NULL) {
                    ok = false;
                    break;
                }
                owned_type_args[arg_index] = true;
            }
            if (!ok) {
                goto cleanup;
            }
        }
    }

    for (arg_index = 0U; arg_index < arg_count; ++arg_index) {
        const FengTypeRef *param_type;

        if (arg_index < fixed_count || args[arg_index]->is_prepacked_variadic_arg) {
            param_type = callable->params[arg_index].type;
        } else {
            /* Variadic position: match against element type T (stored as T[]->inner). */
            param_type = callable->params[fixed_count].type->as.inner;
        }
        param_type = substitute_type_ref_for_explicit_callable_args(
            context,
            callable,
            explicit_type_args,
            explicit_type_arg_count,
            param_type);

        /* When the param type is a bare type parameter (e.g., T), skip the
         * lambda guard — the concrete type is not yet known at probing time
         * and the explicit type arg (if any) will drive adaptation later in
         * callable_collect_call_type_args. */
        if (args[arg_index] != NULL &&
            args[arg_index]->kind == FENG_EXPR_LAMBDA &&
            !param_type_is_type_param_ref(callable, param_type) &&
            resolve_function_type_decl(context, param_type) == NULL) {
            ok = false;
            break;
        }

        /* G4-12: a type-parameter position accepts any argument type, but the
         * inferred type argument must still be collected so that the declared
         * constraint (if any) can be validated after the loop. When inference
         * fails for this argument we keep the historical accept-by-default
         * behavior — the type argument stays NULL, the constraint check below
         * skips it, and the final applicability decision is left to the
         * post-selection witness materializer. */
        if (arg_index < fixed_count && param_type_is_type_param_ref(callable, param_type)) {
            (void)callable_collect_type_args_from_arg_expr(context,
                                                          callable,
                                                          param_type,
                                                          args[arg_index],
                                                          type_args,
                                                          owned_type_args);
            continue;
        }

        /* A prepacked variadic array provides the concrete shape of the
         * normalized T[] parameter, so generic variadic element types can be
         * collected without enabling wrapped inference for ordinary args. */
        if (args[arg_index]->is_prepacked_variadic_arg &&
            callable_type_ref_contains_type_params(callable, param_type)) {
            ok = callable_collect_type_args_from_arg_expr(context,
                                                          callable,
                                                          param_type,
                                                          args[arg_index],
                                                          type_args,
                                                          owned_type_args);
            if (!ok) {
                if (out_prepacked_variadic_rejection != NULL) {
                    *out_prepacked_variadic_rejection =
                        FENG_PREPACKED_VARIADIC_REJECTION_TYPE_MISMATCH;
                }
                break;
            }
            continue;
        }

        if (allow_wrapped_inference &&
            arg_index < fixed_count &&
            callable_type_ref_contains_type_params(callable, param_type)) {
            ok = callable_collect_type_args_from_arg_expr(context,
                                                          callable,
                                                          param_type,
                                                          args[arg_index],
                                                          type_args,
                                                          owned_type_args);
            if (!ok) {
                break;
            }
            continue;
        }

        if (!expr_matches_expected_type_ref(context, args[arg_index], param_type)) {
            if (out_prepacked_variadic_rejection != NULL &&
                args[arg_index]->is_prepacked_variadic_arg) {
                *out_prepacked_variadic_rejection =
                    FENG_PREPACKED_VARIADIC_REJECTION_TYPE_MISMATCH;
            }
            if (out_rejected_existing_array_for_variadic != NULL &&
                is_variadic &&
                arg_count == callable->param_count &&
                arg_index == fixed_count &&
                expr_is_existing_array_for_expected_type_ref(
                    context,
                    args[arg_index],
                    callable->params[fixed_count].type)) {
                *out_rejected_existing_array_for_variadic = true;
            }
            ok = false;
            break;
        }
    }

    if (ok && callable->type_param_count > 0U) {
        ok = callable_collect_type_args_from_target(
            context,
            explicit_type_arg_count > 0U,
            callable,
            callable->return_type,
            type_args,
            owned_type_args);
    }

    /* A generic candidate is applicable only when every inferred type argument
     * satisfies its declared constraint; otherwise the candidate is dropped so
     * it cannot compete with non-generic overloads. */
    if (ok && callable->type_param_count > 0U) {
        size_t type_param_index;
        for (type_param_index = 0U;
             type_param_index < callable->type_param_count;
             ++type_param_index) {
            if (type_args[type_param_index] == NULL) {
                continue;
            }
            if (!generic_type_arg_satisfies_constraint(context,
                                                       callable,
                                                       type_param_index,
                                                       type_args,
                                                       NULL,
                                                       NULL,
                                                       inferred_expr_type_unknown())) {
                ok = false;
                break;
            }
        }
    }

cleanup:
    if (owned_type_args != NULL) {
        for (arg_index = 0U; arg_index < callable->type_param_count; ++arg_index) {
            if (owned_type_args[arg_index]) {
                free_synthetic_type_ref(type_args[arg_index]);
            }
        }
    }
    free(type_args);
    free(owned_type_args);
    context->suppress_literal_type_commit = saved_suppress;
    return ok;
}

/* Owner-instance-aware matcher for methods / fit methods. It first substitutes
 * owner type params into each parameter shape, then applies the same matching
 * policy as the top-level helper above, including the extern-only wrapped
 * inference gate carried by `allow_wrapped_inference`. */
static bool callable_parameters_match_args_for_owner_instance(
    ResolveContext *context,
    const FengCallableSignature *callable,
    const FengDecl *owner_type_decl,
    const FengDecl *fit_decl,
    InferredExprType owner_type,
    FengExpr *const *args,
    size_t arg_count,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count,
    bool allow_wrapped_inference,
    bool *out_rejected_existing_array_for_variadic,
    PrepackedVariadicRejection *out_prepacked_variadic_rejection) {
    size_t arg_index;
    FengTypeRef **type_args = NULL;
    bool *owned_type_args = NULL;
    bool ok = true;
    bool is_variadic = callable->param_count > 0U &&
                       callable->params[callable->param_count - 1U].is_variadic;
    size_t fixed_count = is_variadic ? callable->param_count - 1U : callable->param_count;
    PrepackedVariadicRejection spread_rejection =
        prepacked_variadic_shape_rejection(args, arg_count, is_variadic, fixed_count);
    /* Suppress literal type commit during overload candidate probing so that
     * each candidate test does not overwrite the literal node's type field. */
    bool saved_suppress = context->suppress_literal_type_commit;
    context->suppress_literal_type_commit = true;

    if (out_rejected_existing_array_for_variadic != NULL) {
        *out_rejected_existing_array_for_variadic = false;
    }
    if (out_prepacked_variadic_rejection != NULL) {
        *out_prepacked_variadic_rejection = spread_rejection;
    }
    if (spread_rejection != FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
        context->suppress_literal_type_commit = saved_suppress;
        return false;
    }

    if (is_variadic) {
        if (arg_count < fixed_count) {
            context->suppress_literal_type_commit = saved_suppress;
            return false;
        }
    } else {
        if (callable->param_count != arg_count) {
            context->suppress_literal_type_commit = saved_suppress;
            return false;
        }
    }
    if (callable->type_param_count > 0U) {
        type_args = calloc(callable->type_param_count, sizeof *type_args);
        owned_type_args = calloc(callable->type_param_count, sizeof *owned_type_args);
        if (type_args == NULL || owned_type_args == NULL) {
            free(type_args);
            free(owned_type_args);
            context->suppress_literal_type_commit = saved_suppress;
            return false;
        }
        if (explicit_type_args != NULL &&
            explicit_type_arg_count == callable->type_param_count) {
            for (arg_index = 0U;
                 arg_index < callable->type_param_count;
                 ++arg_index) {
                type_args[arg_index] =
                    clone_type_ref_for_inference(explicit_type_args[arg_index]);
                if (type_args[arg_index] == NULL) {
                    ok = false;
                    break;
                }
                owned_type_args[arg_index] = true;
            }
            if (!ok) {
                goto cleanup;
            }
        }
    }

    for (arg_index = 0U; arg_index < arg_count; ++arg_index) {
        const FengTypeRef *param_type;

        if (arg_index < fixed_count || args[arg_index]->is_prepacked_variadic_arg) {
            param_type = callable->params[arg_index].type;
        } else {
            /* Variadic position: match against element type T (stored as T[]->inner). */
            param_type = callable->params[fixed_count].type->as.inner;
        }

        /* Owner and fit substitutions apply equally to fixed parameters, a
         * prepacked T[] group, and each ordinary variadic element T. */
        param_type = substitute_type_ref_for_owner_instance(context,
                                                            owner_type_decl,
                                                            owner_type,
                                                            param_type);
        param_type = substitute_type_ref_for_fit_instance(context,
                                                          fit_decl,
                                                          owner_type,
                                                          param_type);
        param_type = substitute_type_ref_for_explicit_callable_args(
            context,
            callable,
            explicit_type_args,
            explicit_type_arg_count,
            param_type);

        /* A still-open direct method type parameter accepts the argument and
         * contributes to inference. Explicit arguments have already replaced
         * this surface and therefore follow the ordinary compatibility path. */
        if (arg_index < fixed_count && param_type_is_type_param_ref(callable, param_type)) {
            (void)callable_collect_type_args_from_arg_expr(context,
                                                          callable,
                                                          param_type,
                                                          args[arg_index],
                                                          type_args,
                                                          owned_type_args);
            continue;
        }
        if (args[arg_index] != NULL &&
            args[arg_index]->kind == FENG_EXPR_LAMBDA &&
            resolve_function_type_decl(context, param_type) == NULL) {
            ok = false;
            break;
        }
        if (args[arg_index]->is_prepacked_variadic_arg &&
            callable_type_ref_contains_type_params(callable, param_type)) {
            ok = callable_collect_type_args_from_arg_expr(context,
                                                          callable,
                                                          param_type,
                                                          args[arg_index],
                                                          type_args,
                                                          owned_type_args);
            if (!ok) {
                if (out_prepacked_variadic_rejection != NULL) {
                    *out_prepacked_variadic_rejection =
                        FENG_PREPACKED_VARIADIC_REJECTION_TYPE_MISMATCH;
                }
                break;
            }
            continue;
        }
        if (allow_wrapped_inference &&
            arg_index < fixed_count &&
            callable_type_ref_contains_type_params(callable, param_type)) {
            ok = callable_collect_type_args_from_arg_expr(context,
                                                          callable,
                                                          param_type,
                                                          args[arg_index],
                                                          type_args,
                                                          owned_type_args);
            if (!ok) {
                break;
            }
            continue;
        }
        if (!expr_matches_expected_type_ref(context, args[arg_index], param_type)) {
            if (out_prepacked_variadic_rejection != NULL &&
                args[arg_index]->is_prepacked_variadic_arg) {
                *out_prepacked_variadic_rejection =
                    FENG_PREPACKED_VARIADIC_REJECTION_TYPE_MISMATCH;
            }
            if (out_rejected_existing_array_for_variadic != NULL &&
                is_variadic &&
                arg_count == callable->param_count &&
                arg_index == fixed_count) {
                const FengTypeRef *array_param_type = substitute_type_ref_for_owner_instance(
                    context,
                    owner_type_decl,
                    owner_type,
                    callable->params[fixed_count].type);

                array_param_type = substitute_type_ref_for_fit_instance(context,
                                                                        fit_decl,
                                                                        owner_type,
                                                                        array_param_type);
                if (expr_is_existing_array_for_expected_type_ref(context,
                                                                 args[arg_index],
                                                                 array_param_type)) {
                    *out_rejected_existing_array_for_variadic = true;
                }
            }
            ok = false;
            break;
        }
    }

    if (ok && callable->type_param_count > 0U) {
        const FengTypeRef *target_inference_return_type =
            substitute_type_ref_for_owner_instance(context,
                                                   owner_type_decl,
                                                   owner_type,
                                                   callable->return_type);

        target_inference_return_type = substitute_type_ref_for_fit_instance(
            context,
            fit_decl,
            owner_type,
            target_inference_return_type);
        ok = callable_collect_type_args_from_target(
            context,
            explicit_type_arg_count > 0U,
            callable,
            target_inference_return_type,
            type_args,
            owned_type_args);
    }

    /* A generic candidate is applicable only when every inferred type argument
     * satisfies its declared constraint; otherwise the candidate is dropped so
     * it cannot compete with non-generic overloads. */
    if (ok && callable->type_param_count > 0U) {
        size_t type_param_index;
        for (type_param_index = 0U;
             type_param_index < callable->type_param_count;
             ++type_param_index) {
            if (type_args[type_param_index] == NULL) {
                continue;
            }
            if (!generic_type_arg_satisfies_constraint(context,
                                                       callable,
                                                       type_param_index,
                                                       type_args,
                                                       owner_type_decl,
                                                       fit_decl,
                                                       owner_type)) {
                ok = false;
                break;
            }
        }
    }

cleanup:
    if (owned_type_args != NULL) {
        for (arg_index = 0U; arg_index < callable->type_param_count; ++arg_index) {
            if (owned_type_args[arg_index]) {
                free_synthetic_type_ref(type_args[arg_index]);
            }
        }
    }
    free(type_args);
    free(owned_type_args);
    context->suppress_literal_type_commit = saved_suppress;
    return ok;
}

static bool callable_parameters_exactly_match_args(
    ResolveContext *context,
    const FengCallableSignature *callable,
    FengExpr *const *args,
    size_t arg_count) {
    size_t arg_index;
    bool is_variadic;
    size_t fixed_count;

    if (context == NULL || callable == NULL || callable->type_param_count != 0U) {
        return false;
    }
    is_variadic = callable->param_count > 0U &&
                  callable->params[callable->param_count - 1U].is_variadic;
    fixed_count = is_variadic ? callable->param_count - 1U : callable->param_count;
    if (prepacked_variadic_shape_rejection(args, arg_count, is_variadic, fixed_count) !=
        FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
        return false;
    }
    if (is_variadic) {
        if (arg_count < fixed_count) {
            return false;
        }
    } else if (callable->param_count != arg_count) {
        return false;
    }

    for (arg_index = 0U; arg_index < arg_count; ++arg_index) {
        const FengTypeRef *param_type =
            arg_index < fixed_count || args[arg_index]->is_prepacked_variadic_arg
                ? callable->params[arg_index].type
                : callable->params[fixed_count].type->as.inner;

        if (!inferred_expr_type_exactly_matches_type_ref(context,
                                                         infer_expr_type(context, args[arg_index]),
                                                         param_type)) {
            return false;
        }
    }
    return true;
}

static bool callable_parameters_exactly_match_args_for_owner_instance(
    ResolveContext *context,
    const FengCallableSignature *callable,
    const FengDecl *owner_type_decl,
    const FengDecl *fit_decl,
    InferredExprType owner_type,
    FengExpr *const *args,
    size_t arg_count) {
    size_t arg_index;
    bool is_variadic;
    size_t fixed_count;

    if (context == NULL || callable == NULL || callable->type_param_count != 0U) {
        return false;
    }
    is_variadic = callable->param_count > 0U &&
                  callable->params[callable->param_count - 1U].is_variadic;
    fixed_count = is_variadic ? callable->param_count - 1U : callable->param_count;
    if (prepacked_variadic_shape_rejection(args, arg_count, is_variadic, fixed_count) !=
        FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
        return false;
    }
    if (is_variadic) {
        if (arg_count < fixed_count) {
            return false;
        }
    } else if (callable->param_count != arg_count) {
        return false;
    }

    for (arg_index = 0U; arg_index < arg_count; ++arg_index) {
        const FengTypeRef *param_type =
            arg_index < fixed_count || args[arg_index]->is_prepacked_variadic_arg
                ? callable->params[arg_index].type
                : callable->params[fixed_count].type->as.inner;

        param_type = substitute_type_ref_for_owner_instance(context,
                                                            owner_type_decl,
                                                            owner_type,
                                                            param_type);
        param_type = substitute_type_ref_for_fit_instance(context,
                                                          fit_decl,
                                                          owner_type,
                                                          param_type);
        if (!inferred_expr_type_exactly_matches_type_ref(context,
                                                         infer_expr_type(context, args[arg_index]),
                                                         param_type)) {
            return false;
        }
    }
    return true;
}

/* Compare two callable signatures after independently closing each declaring
 * owner instance. This is required when equivalent intersection requirements
 * originate from different object-form member specs. */
static bool callable_signatures_equal_for_owner_instances(
    ResolveContext *context,
    const FengCallableSignature *left,
    const FengDecl *left_owner_type_decl,
    InferredExprType left_owner_type,
    const FengCallableSignature *right,
    const FengDecl *right_owner_type_decl,
    InferredExprType right_owner_type) {
    size_t param_index;
    const FengTypeRef *left_return;
    const FengTypeRef *right_return;

    if (left == NULL || right == NULL) {
        return false;
    }
    if (left->type_param_count != right->type_param_count ||
        left->param_count != right->param_count) {
        return false;
    }

    for (param_index = 0U; param_index < left->param_count; ++param_index) {
        if (left->params[param_index].is_variadic !=
            right->params[param_index].is_variadic) {
            return false;
        }
        const FengTypeRef *left_param = substitute_type_ref_for_owner_instance(
            context,
            left_owner_type_decl,
            left_owner_type,
            left->params[param_index].type);
        const FengTypeRef *right_param = substitute_type_ref_for_owner_instance(
            context,
            right_owner_type_decl,
            right_owner_type,
            right->params[param_index].type);

        if (!type_refs_semantically_equal(context, left_param, right_param)) {
            return false;
        }
    }

    if (left->return_type == NULL || right->return_type == NULL) {
        return left->return_type == NULL && right->return_type == NULL;
    }

    left_return = substitute_type_ref_for_owner_instance(context,
                                                         left_owner_type_decl,
                                                         left_owner_type,
                                                         left->return_type);
    right_return = substitute_type_ref_for_owner_instance(context,
                                                          right_owner_type_decl,
                                                          right_owner_type,
                                                          right->return_type);
    return type_refs_semantically_equal(context, left_return, right_return);
}

static bool validate_loop_control_stmt(ResolveContext *context,
                                       const FengStmt *stmt,
                                       const char *keyword) {
    FengToken token = stmt != NULL ? stmt->token : context->program->module_token;

    if (context != NULL && context->loop_depth > 0U) {
        return true;
    }

    if (context != NULL) {
        switch (context->expression_branch_boundary) {
            case EXPRESSION_BRANCH_BOUNDARY_IF:
                return resolver_append_error(
                    context,
                    token,
                    "AE1110",
                    format_message(
                        "'%s' cannot appear directly inside an 'if' expression block or inside its nested ordinary blocks when targeting a loop outside the expression; place it inside a loop declared within the branch",
                        keyword));
            case EXPRESSION_BRANCH_BOUNDARY_MATCH:
                return resolver_append_error(
                    context,
                    token,
                    "AE1110",
                    format_message(
                        "'%s' cannot appear directly inside a 'match' expression block or inside its nested ordinary blocks when targeting a loop outside the expression; place it inside a loop declared within the branch",
                        keyword));
            case EXPRESSION_BRANCH_BOUNDARY_CATCH:
                return resolver_append_error(
                    context,
                    token,
                    "AE1405",
                    format_message(
                        "'%s' cannot appear directly inside a catch block or inside its nested ordinary blocks when targeting a loop outside the try expression; place it inside a loop declared within the branch",
                        keyword));
            case EXPRESSION_BRANCH_BOUNDARY_NONE:
                break;
        }
    }

    return resolver_append_error(
        context,
        token,
        "AE1201", format_message("'%s' statement is only allowed inside a 'while' or 'for' loop",

                       keyword));
}

static bool inferred_expr_type_is_exception_payload(const ResolveContext *context,
                                                    InferredExprType type,
                                                    const char **out_reason);
static InferredExprType resolve_expr_owner_type(ResolveContext *context,
                                                const FengExpr *expr,
                                                const FengDecl **out_type_decl,
                                                const FengSemanticModule **out_provider_module);
static const FengTypeMember *find_fit_method_member_for_owner_type(ResolveContext *ctx,
                                                                   const FengDecl *owner_type_decl,
                                                                   InferredExprType owner_type,
                                                                   FengSlice name);

static bool throw_expr_is_callable_value(ResolveContext *context,
                                         const FengExpr *expr,
                                         const char **out_reason) {
    if (expr == NULL) {
        return false;
    }

    if (expr->kind == FENG_EXPR_LAMBDA) {
        if (out_reason != NULL) {
            *out_reason = "function values cannot be thrown as exceptions";
        }
        return true;
    }

    if (expr->kind == FENG_EXPR_IDENTIFIER) {
        const LocalNameEntry *local_entry = resolver_find_local_name_entry(context, expr->as.identifier);
        const VisibleValueEntry *visible_value;

        if (local_entry != NULL && local_entry->type.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA) {
            if (out_reason != NULL) {
                *out_reason = "function values cannot be thrown as exceptions";
            }
            return true;
        }
        if (find_function_overload_set(context->function_sets,
                                       context->function_set_count,
                                       expr->as.identifier) != NULL) {
            if (out_reason != NULL) {
                *out_reason = "function values cannot be thrown as exceptions";
            }
            return true;
        }
        visible_value = find_visible_value(context->visible_values,
                                           context->visible_value_count,
                                           expr->as.identifier);
        if (visible_value != NULL && visible_value->is_function) {
            if (out_reason != NULL) {
                *out_reason = "function values cannot be thrown as exceptions";
            }
            return true;
        }
    }

    if (expr->kind == FENG_EXPR_MEMBER) {
        const FengExpr *object = expr->as.member.object;
        ResolvedModuleMemberTarget module_target;

        if (resolve_module_member_target(context, expr, &module_target) &&
            find_module_public_function_decl(module_target.module,
                                             module_target.member_name) != NULL) {
            if (out_reason != NULL) {
                *out_reason = "function values cannot be thrown as exceptions";
            }
            return true;
        }

        {
            const FengDecl *owner_type_decl = NULL;
            const FengSemanticModule *provider_module = NULL;
            InferredExprType owner_type =
                resolve_expr_owner_type(context, object, &owner_type_decl, &provider_module);
            const FengTypeMember *member = NULL;

            (void)provider_module;
            if (owner_type_decl != NULL && owner_type_decl->kind == FENG_DECL_TYPE) {
                member = find_instance_member(owner_type_decl, expr->as.member.member);
                if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD) {
                    if (out_reason != NULL) {
                        *out_reason = "member methods cannot be thrown as exceptions";
                    }
                    return true;
                }
            }
            if (owner_type_decl != NULL && owner_type_decl->kind == FENG_DECL_SPEC) {
                member = find_spec_object_member(context, owner_type_decl, expr->as.member.member, /*include_static=*/false);
                if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD) {
                    if (out_reason != NULL) {
                        *out_reason = "member methods cannot be thrown as exceptions";
                    }
                    return true;
                }
            }
            member = find_fit_method_member_for_owner_type(context,
                                                           owner_type_decl,
                                                           owner_type,
                                                           expr->as.member.member);
            if (member != NULL) {
                if (out_reason != NULL) {
                    *out_reason = "member methods cannot be thrown as exceptions";
                }
                return true;
            }
        }
    }

    return false;
}

/* Return whether a type reference still contains a type parameter that is
 * open in the current semantic scope. Closed generic arguments recurse to
 * false and therefore retain their concrete nominal exception identity. */
static bool exception_type_ref_contains_open_type_param(
    const ResolveContext *context,
    const FengTypeRef *type_ref) {
    size_t type_arg_index;

    if (context == NULL || type_ref == NULL) {
        return false;
    }
    switch (type_ref->kind) {
        case FENG_TYPE_REF_POINTER:
        case FENG_TYPE_REF_ARRAY:
            return exception_type_ref_contains_open_type_param(
                context, type_ref->as.inner);

        case FENG_TYPE_REF_NAMED:
            if (type_ref->as.named.segment_count == 1U &&
                type_ref->as.named.type_arg_count == 0U &&
                find_type_param(context, type_ref->as.named.segments[0]) != NULL) {
                return true;
            }
            for (type_arg_index = 0U;
                 type_arg_index < type_ref->as.named.type_arg_count;
                 ++type_arg_index) {
                if (exception_type_ref_contains_open_type_param(
                        context, type_ref->as.named.type_args[type_arg_index])) {
                    return true;
                }
            }
            return false;
    }

    return false;
}

/* Classify the finite set of concrete exception payload types shared by
 * throw expressions and typed catch clauses. Reasons are deliberately
 * context-neutral so both sites report the same classification decision. */
static bool type_ref_is_exception_payload(const ResolveContext *context,
                                          const FengTypeRef *type_ref,
                                          const char **out_reason) {
    const FengDecl *decl;

    if (type_ref == NULL) {
        return true;
    }
    if (type_ref_is_unknown(type_ref)) {
        return true;
    }

    switch (type_ref->kind) {
        case FENG_TYPE_REF_POINTER:
            if (out_reason != NULL) {
                *out_reason = "pointer values cannot be thrown or used as concrete catch types";
            }
            return false;

        case FENG_TYPE_REF_ARRAY:
            if (out_reason != NULL) {
                *out_reason = "array values have no closed-type exception identity";
            }
            return false;

        case FENG_TYPE_REF_NAMED:
            if (type_ref_is_void(type_ref)) {
                if (out_reason != NULL) {
                    *out_reason = "void is not an exception payload type";
                }
                return false;
            }
            if (exception_type_ref_contains_open_type_param(context, type_ref)) {
                if (out_reason != NULL) {
                    *out_reason = "open generic types have no concrete exception identity";
                }
                return false;
            }
            if (type_ref_builtin_canonical_name(type_ref, context->pointer_size) != NULL) {
                return true;
            }
            decl = resolve_type_ref_decl(context, type_ref);
            if (decl == NULL) {
                /* Resolution reports the primary unknown-type diagnostic. */
                return true;
            }
            if (decl->kind == FENG_DECL_SPEC) {
                if (out_reason != NULL) {
                    *out_reason = "spec values have no concrete exception identity";
                }
                return false;
            }
            if (decl->kind == FENG_DECL_TYPE || decl->kind == FENG_DECL_ENUM) {
                return true;
            }
            if (out_reason != NULL) {
                *out_reason = "callable values are not exception payload types";
            }
            return false;
    }

    return false;
}

/* Classify one inferred throw operand through the same concrete payload gate
 * used by typed catch clauses. Callable expressions with no representable
 * type reference are rejected here or by throw_expr_is_callable_value. */
static bool inferred_expr_type_is_exception_payload(const ResolveContext *context,
                                                    InferredExprType type,
                                                    const char **out_reason) {
    switch (type.kind) {
        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
            /* Unknown types are reported through other diagnostics; do not
             * pile on a second throwability error here. */
            return true;

        case FENG_INFERRED_EXPR_TYPE_BUILTIN:
            return true;

        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
            if (out_reason != NULL) {
                *out_reason = "function values cannot be thrown as exceptions";
            }
            return false;

        case FENG_INFERRED_EXPR_TYPE_TYPE_REF:
            return type_ref_is_exception_payload(context, type.type_ref, out_reason);

        case FENG_INFERRED_EXPR_TYPE_DECL:
            if (type.type_decl != NULL && type.type_decl->kind == FENG_DECL_SPEC) {
                if (out_reason != NULL) {
                    *out_reason = "spec values have no concrete exception identity";
                }
                return false;
            }
            if (type.type_decl != NULL && type.type_decl->kind == FENG_DECL_TYPE &&
                type.type_decl->as.type_decl.type_param_count > 0U) {
                if (out_reason != NULL) {
                    *out_reason = "open generic types have no concrete exception identity";
                }
                return false;
            }
            return type.type_decl != NULL &&
                   (type.type_decl->kind == FENG_DECL_TYPE ||
                    type.type_decl->kind == FENG_DECL_ENUM);
    }

    return true;
}

static bool validate_throw_stmt(ResolveContext *context, const FengStmt *stmt) {
    InferredExprType throw_type;
    const char *reason = NULL;

    throw_type = infer_expr_type(context, stmt != NULL ? stmt->as.throw_value : NULL);

    if (throw_expr_is_callable_value(context, stmt != NULL ? stmt->as.throw_value : NULL, &reason)) {
        char *type_name = format_inferred_expr_type_name(throw_type, context->pointer_size);
        char *message = format_message(
            "throw expression of type '%s' is not throwable: %s",
            type_name != NULL ? type_name : "<unknown>",
            reason != NULL ? reason : "function values cannot be thrown as exceptions");

        free(type_name);
        return resolver_append_error(context, stmt->token, "AE0076", message);
    }

    if (inferred_expr_type_is_known(throw_type) && inferred_expr_type_is_void(throw_type)) {
        return resolver_append_error(
            context,
            stmt->token,
            "AE1402", format_message("throw statement requires a non-void expression"));
    }

    if (!inferred_expr_type_is_exception_payload(context, throw_type, &reason)) {
        char *type_name = format_inferred_expr_type_name(throw_type, context->pointer_size);
        char *message = format_message(
            "throw expression of type '%s' is not throwable: %s",
            type_name != NULL ? type_name : "<unknown>",
            reason != NULL ? reason : "value is not a Feng-managed value");

        free(type_name);
        return resolver_append_error(context, stmt->token, "AE0076", message);
    }

    return true;
}


static ConstructorResolution resolve_accessible_constructor_overload(
    ResolveContext *context,
    const FengDecl *type_decl,
    const FengSemanticModule *provider_module,
    FengExpr *const *args,
    size_t arg_count,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count) {
    size_t member_index;
    ConstructorResolution result;
    bool use_owner_substitution = false;
    FengTypeRef synthetic_owner_ref;
    InferredExprType owner_type;

    memset(&result, 0, sizeof(result));
    (void)provider_module;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return result;
    }

    if (explicit_type_args != NULL &&
        explicit_type_arg_count > 0U &&
        type_decl->as.type_decl.type_param_count > 0U &&
        explicit_type_arg_count == type_decl->as.type_decl.type_param_count) {
        memset(&synthetic_owner_ref, 0, sizeof(synthetic_owner_ref));
        synthetic_owner_ref.kind = FENG_TYPE_REF_NAMED;
        synthetic_owner_ref.as.named.type_args = (FengTypeRef **)explicit_type_args;
        synthetic_owner_ref.as.named.type_arg_count = explicit_type_arg_count;
        memset(&owner_type, 0, sizeof(owner_type));
        owner_type.kind = FENG_INFERRED_EXPR_TYPE_TYPE_REF;
        owner_type.type_ref = &synthetic_owner_ref;
        use_owner_substitution = true;
    }

    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];

        if (member->kind != FENG_TYPE_MEMBER_CONSTRUCTOR) {
            continue;
        }
        if (!type_member_is_accessible_from(
                context,
                type_decl,
                use_owner_substitution
                    ? owner_type
                    : inferred_expr_type_from_decl(type_decl),
                member) ||
            fit_body_blocks_private_access(context, type_decl, member)) {
            continue;
        }
        PrepackedVariadicRejection spread_rejection =
            FENG_PREPACKED_VARIADIC_REJECTION_NONE;
        if (use_owner_substitution) {
            if (!callable_parameters_match_args_for_owner_instance(
                    context, &member->as.callable, type_decl, NULL, owner_type,
                    args, arg_count, NULL, 0U, false, NULL, &spread_rejection)) {
                merge_prepacked_variadic_rejection(
                    &result.prepacked_variadic_rejection, spread_rejection);
                continue;
            }
        } else {
            if (!callable_parameters_match_args(
                    context, &member->as.callable, args, arg_count, NULL, 0U,
                    false, NULL, &spread_rejection)) {
                merge_prepacked_variadic_rejection(
                    &result.prepacked_variadic_rejection, spread_rejection);
                continue;
            }
        }

        if (result.kind == FENG_CONSTRUCTOR_RESOLUTION_NONE) {
            result.kind = FENG_CONSTRUCTOR_RESOLUTION_UNIQUE;
            result.constructor = member;
            continue;
        }

        result.kind = FENG_CONSTRUCTOR_RESOLUTION_AMBIGUOUS;
        result.constructor = NULL;
    }

    return result;
}

/* current_module_has_local_function / find_imported_module_with_public_function
 * 已删除:由通用查找 collect_symbol_candidates + report_name_ambiguity_if_any
 * 在使用点统一处理(规范 §7.1 惰性碰撞,错误码 AE0005)。 */

static FunctionCallResolution resolve_top_level_function_overload(
    ResolveContext *context,
    const FunctionOverloadSetEntry *overload_set,
    FengExpr *const *args,
    size_t arg_count,
    bool has_explicit_type_args,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count) {
    size_t decl_index;
    FunctionCallResolution result;

    memset(&result, 0, sizeof(result));
    if (overload_set == NULL) {
        return result;
    }

    for (decl_index = 0U; decl_index < overload_set->decl_count; ++decl_index) {
        const FengDecl *decl = overload_set->decls[decl_index];

        if (decl == NULL || decl->kind != FENG_DECL_FUNCTION) {
            continue;
        }
        bool rejected_existing_array_for_variadic = false;
        PrepackedVariadicRejection spread_rejection =
            FENG_PREPACKED_VARIADIC_REJECTION_NONE;

        if (!callable_parameters_match_args(context,
                                            &decl->as.function_decl,
                                            args,
                                            arg_count,
                                            explicit_type_args,
                                            explicit_type_arg_count,
                                            decl->is_extern,
                                            &rejected_existing_array_for_variadic,
                                            &spread_rejection)) {
            if (rejected_existing_array_for_variadic) {
                result.rejected_existing_array_for_variadic = true;
            }
            merge_prepacked_variadic_rejection(
                &result.prepacked_variadic_rejection, spread_rejection);
            continue;
        }

        int priority = compute_overload_match_priority(
            has_explicit_type_args,
            explicit_type_arg_count,
            decl->as.function_decl.type_param_count,
            callable_parameters_exactly_match_args(context,
                                                   &decl->as.function_decl,
                                                   args,
                                                   arg_count));

        if (result.kind == FENG_FUNCTION_CALL_RESOLUTION_NONE ||
            priority < result.match_priority) {
            result.kind = FENG_FUNCTION_CALL_RESOLUTION_UNIQUE;
            result.match_priority = priority;
            result.decl = decl;
            result.callable = &decl->as.function_decl;
            continue;
        }
        if (priority > result.match_priority) {
            continue;
        }

        result.kind = FENG_FUNCTION_CALL_RESOLUTION_AMBIGUOUS;
        result.decl = NULL;
        result.callable = NULL;
    }

    return result;
}

/* Match a generic callable value after its callable-local type arguments have
 * been supplied explicitly. Owner and fit substitutions are applied before
 * callable-local substitution, mirroring the ordinary call-resolution order.
 * The target callable-form spec never participates in type-argument inference. */
static bool function_type_decl_matches_explicit_callable_signature(
    ResolveContext *context,
    const FengTypeRef *function_type_ref,
    const FengDecl *function_type_decl,
    const FengCallableSignature *callable,
    const FengDecl *owner_type_decl,
    const FengDecl *fit_decl,
    InferredExprType owner_type,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count) {
    size_t param_index;
    const FengTypeRef *expected_return;
    InferredExprType actual_return;

    if (context == NULL || function_type_decl == NULL || callable == NULL ||
        !decl_is_function_type(function_type_decl) ||
        explicit_type_args == NULL ||
        callable->type_param_count != explicit_type_arg_count ||
        function_type_decl->as.spec_decl.as.callable.param_count !=
            callable->param_count) {
        return false;
    }

    for (param_index = 0U;
         param_index < callable->type_param_count;
         ++param_index) {
        if (explicit_type_args[param_index] == NULL ||
            !generic_type_arg_satisfies_constraint(
                context,
                callable,
                param_index,
                (FengTypeRef *const *)explicit_type_args,
                owner_type_decl,
                fit_decl,
                owner_type)) {
            return false;
        }
    }

    for (param_index = 0U; param_index < callable->param_count; ++param_index) {
        const FengParameter *expected_decl_param =
            &function_type_decl->as.spec_decl.as.callable.params[param_index];
        const FengParameter *actual_decl_param = &callable->params[param_index];
        const FengTypeRef *expected_param =
            substitute_spec_member_type_ref_for_instance(
                context,
                function_type_decl,
                function_type_ref,
                expected_decl_param->type);
        const FengTypeRef *actual_param =
            substitute_type_ref_for_owner_instance(
                context,
                owner_type_decl,
                owner_type,
                actual_decl_param->type);

        actual_param = substitute_type_ref_for_fit_instance(
            context, fit_decl, owner_type, actual_param);
        actual_param = substitute_type_ref_for_explicit_callable_args(
            context,
            callable,
            explicit_type_args,
            explicit_type_arg_count,
            actual_param);
        if (!callable_parameter_forms_match(expected_decl_param,
                                            actual_decl_param) ||
            !type_refs_semantically_equal(context,
                                          expected_param,
                                          actual_param)) {
            return false;
        }
    }

    expected_return = substitute_spec_member_type_ref_for_instance(
        context,
        function_type_decl,
        function_type_ref,
        function_type_decl->as.spec_decl.as.callable.return_type);
    actual_return = callable_effective_return_type(context, callable);
    if (actual_return.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        actual_return.type_ref = substitute_type_ref_for_owner_instance(
            context,
            owner_type_decl,
            owner_type,
            actual_return.type_ref);
        actual_return.type_ref = substitute_type_ref_for_fit_instance(
            context,
            fit_decl,
            owner_type,
            actual_return.type_ref);
        actual_return.type_ref = substitute_type_ref_for_explicit_callable_args(
            context,
            callable,
            explicit_type_args,
            explicit_type_arg_count,
            actual_return.type_ref);
    }
    if (inferred_expr_type_matches_type_ref(context,
                                            actual_return,
                                            expected_return)) {
        return true;
    }
    return callable_return_inference_is_pending(context, callable);
}

static CallableValueResolution resolve_top_level_function_value_overload(
    ResolveContext *context,
    const FunctionOverloadSetEntry *overload_set,
    const FengTypeRef *expected_type_ref,
    const FengDecl *function_type_decl,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count) {
    size_t decl_index;
    CallableValueResolution result;
    bool requires_abi_callable;

    memset(&result, 0, sizeof(result));
    if (overload_set == NULL || function_type_decl == NULL) {
        return result;
    }

    requires_abi_callable =
        function_type_decl_is_abi_callable_type(function_type_decl);

    for (decl_index = 0U; decl_index < overload_set->decl_count; ++decl_index) {
        const FengDecl *decl = overload_set->decls[decl_index];

        bool signature_matches;

        if (decl == NULL || decl->kind != FENG_DECL_FUNCTION ||
            (requires_abi_callable && !function_decl_is_abi_callable_value(decl))) {
            continue;
        }
        signature_matches = explicit_type_args != NULL
                                ? function_type_decl_matches_explicit_callable_signature(
                                      context,
                                      expected_type_ref,
                                      function_type_decl,
                                      &decl->as.function_decl,
                                      NULL,
                                      NULL,
                                      inferred_expr_type_unknown(),
                                      explicit_type_args,
                                      explicit_type_arg_count)
                                : function_type_decl_matches_callable_signature_or_is_pending(
                                      context,
                                      expected_type_ref,
                                      function_type_decl,
                                      &decl->as.function_decl);
        if (!signature_matches) {
            continue;
        }

        if (result.kind == FENG_CALLABLE_VALUE_RESOLUTION_NONE) {
            result.kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
            result.callable = &decl->as.function_decl;
            result.callable_decl = decl;
            result.callable_member = NULL;
            result.callable_owner_type_decl = NULL;
            result.callable_fit_decl = NULL;
            result.callable_type_args = explicit_type_args;
            result.callable_type_arg_count = explicit_type_arg_count;
            result.lambda_expr = NULL;
            continue;
        }

        result.kind = FENG_CALLABLE_VALUE_RESOLUTION_AMBIGUOUS;
        result.callable = NULL;
        result.callable_decl = NULL;
        result.callable_member = NULL;
        result.callable_owner_type_decl = NULL;
        result.callable_fit_decl = NULL;
        result.callable_type_args = NULL;
        result.callable_type_arg_count = 0U;
        result.lambda_expr = NULL;
    }

    return result;
}

static CallableValueResolution resolve_module_public_function_value_overload(
    ResolveContext *context,
    const FengSemanticModule *module,
    FengSlice name,
    const FengTypeRef *expected_type_ref,
    const FengDecl *function_type_decl,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count) {
    size_t program_index;
    CallableValueResolution result;
    bool requires_abi_callable;

    memset(&result, 0, sizeof(result));
    if (module == NULL || function_type_decl == NULL) {
        return result;
    }

    requires_abi_callable =
        function_type_decl_is_abi_callable_type(function_type_decl);

    for (program_index = 0U; program_index < module->program_count; ++program_index) {
        const FengProgram *program = module->programs[program_index];
        size_t decl_index;

        for (decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
            const FengDecl *decl = program->declarations[decl_index];
            bool signature_matches;

            if (decl->kind != FENG_DECL_FUNCTION || !decl_is_public(decl) ||
                !slice_equals(decl->as.function_decl.name, name) ||
                (requires_abi_callable && !function_decl_is_abi_callable_value(decl))) {
                continue;
            }
            signature_matches = explicit_type_args != NULL
                                    ? function_type_decl_matches_explicit_callable_signature(
                                          context,
                                          expected_type_ref,
                                          function_type_decl,
                                          &decl->as.function_decl,
                                          NULL,
                                          NULL,
                                          inferred_expr_type_unknown(),
                                          explicit_type_args,
                                          explicit_type_arg_count)
                                    : function_type_decl_matches_callable_signature_or_is_pending(
                                          context,
                                          expected_type_ref,
                                          function_type_decl,
                                          &decl->as.function_decl);
            if (!signature_matches) {
                continue;
            }

            if (result.kind == FENG_CALLABLE_VALUE_RESOLUTION_NONE) {
                result.kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
                result.callable = &decl->as.function_decl;
                result.callable_decl = decl;
                result.callable_member = NULL;
                result.callable_owner_type_decl = NULL;
                result.callable_fit_decl = NULL;
                result.callable_type_args = explicit_type_args;
                result.callable_type_arg_count = explicit_type_arg_count;
                result.lambda_expr = NULL;
                continue;
            }

            result.kind = FENG_CALLABLE_VALUE_RESOLUTION_AMBIGUOUS;
            result.callable = NULL;
            result.callable_decl = NULL;
            result.callable_member = NULL;
            result.callable_owner_type_decl = NULL;
            result.callable_fit_decl = NULL;
            result.callable_type_args = NULL;
            result.callable_type_arg_count = 0U;
            result.lambda_expr = NULL;
        }
    }

    return result;
}

static bool function_type_decl_matches_owner_callable_signature(
    ResolveContext *context,
    const FengTypeRef *function_type_ref,
    const FengDecl *function_type_decl,
    const FengCallableSignature *callable,
    const FengDecl *owner_type_decl,
    const FengDecl *fit_decl,
    InferredExprType owner_type);

static CallableValueResolution resolve_accessible_method_value_overload(
    ResolveContext *context,
    const FengDecl *type_decl,
    const FengSemanticModule *provider_module,
    InferredExprType owner_type,
    FengSlice name,
    const FengTypeRef *expected_type_ref,
    const FengDecl *function_type_decl,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count,
    bool require_static) {
    size_t member_index;
    CallableValueResolution result;
    bool requires_abi_callable;

    memset(&result, 0, sizeof(result));
    (void)provider_module;
    if (type_decl == NULL || function_type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return result;
    }

    requires_abi_callable =
        function_type_decl_is_abi_callable_type(function_type_decl);

    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];
        bool signature_matches;

        if (member->is_static != require_static ||
            member->kind != FENG_TYPE_MEMBER_METHOD ||
            !slice_equals(member->as.callable.name, name) ||
            !type_member_is_accessible_from(context,
                                            type_decl,
                                            owner_type,
                                            member) ||
            fit_body_blocks_private_access(context, type_decl, member) ||
            (requires_abi_callable && !method_member_is_abi_callable_value(member))) {
            continue;
        }
        /* Method-local generic parameters are never inferred from the target
         * callable shape. Static references without an explicit generic
         * target therefore cannot select a generic method candidate. */
        if (require_static && explicit_type_args == NULL &&
            member->as.callable.type_param_count > 0U) {
            continue;
        }
        signature_matches = explicit_type_args != NULL
                                ? function_type_decl_matches_explicit_callable_signature(
                                      context,
                                      expected_type_ref,
                                      function_type_decl,
                                      &member->as.callable,
                                      type_decl,
                                      NULL,
                                      owner_type,
                                      explicit_type_args,
                                      explicit_type_arg_count)
                                : function_type_decl_matches_owner_callable_signature(
                                      context,
                                      expected_type_ref,
                                      function_type_decl,
                                      &member->as.callable,
                                      type_decl,
                                      NULL,
                                      owner_type);
        if (!signature_matches) {
            continue;
        }

        if (result.kind == FENG_CALLABLE_VALUE_RESOLUTION_NONE) {
            result.kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
            result.callable = &member->as.callable;
            result.callable_decl = NULL;
            result.callable_member = member;
            result.callable_owner_type_decl = type_decl;
            result.callable_fit_decl = NULL;
            result.callable_type_args = explicit_type_args;
            result.callable_type_arg_count = explicit_type_arg_count;
            result.lambda_expr = NULL;
            continue;
        }

        result.kind = FENG_CALLABLE_VALUE_RESOLUTION_AMBIGUOUS;
        result.callable = NULL;
        result.callable_decl = NULL;
        result.callable_member = NULL;
        result.callable_owner_type_decl = NULL;
        result.callable_fit_decl = NULL;
        result.callable_type_args = NULL;
        result.callable_type_arg_count = 0U;
        result.lambda_expr = NULL;
    }

    return result;
}

/* A visitor over one exact object-form spec requirement. Returning false
 * stops traversal after the current requirement. */
typedef bool (*SpecMethodSurfaceVisitor)(
    ResolveContext *context,
    const SpecMemberSurface *surface,
    void *userdata);

/* Visit the exact method surface of one object- or intersection-form spec
 * instance. Intersection members and object parents are both type-ref edges;
 * following them through the same substitution path preserves the original
 * requirement declaration and its fully projected owner instance without
 * building a flattened scratch snapshot. */
static bool visit_spec_method_surfaces(
    ResolveContext *context,
    const FengDecl *current_spec_decl,
    const FengTypeRef *current_spec_type_ref,
    FengSlice name,
    bool require_static,
    SpecMethodSurfaceVisitor visitor,
    void *userdata) {
    if (context == NULL || current_spec_decl == NULL ||
        current_spec_decl->kind != FENG_DECL_SPEC || visitor == NULL) {
        return true;
    }

    if (current_spec_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
        for (size_t member_index = 0U;
             member_index <
                 current_spec_decl->as.spec_decl.as.intersection_form.member_count;
             ++member_index) {
            const FengTypeRef *member_type_ref =
                substitute_spec_member_type_ref_for_instance(
                    context,
                    current_spec_decl,
                    current_spec_type_ref,
                    current_spec_decl->as.spec_decl.as.intersection_form
                        .members[member_index]);
            const FengDecl *member_decl =
                resolve_type_ref_decl(context, member_type_ref);

            if (member_decl != NULL && member_decl->kind == FENG_DECL_SPEC &&
                !visit_spec_method_surfaces(context,
                                            member_decl,
                                            member_type_ref,
                                            name,
                                            require_static,
                                            visitor,
                                            userdata)) {
                return false;
            }
        }
        return true;
    }

    if (current_spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return true;
    }
    for (size_t member_index = 0U;
         member_index < current_spec_decl->as.spec_decl.as.object.member_count;
         ++member_index) {
        const FengTypeMember *member =
            current_spec_decl->as.spec_decl.as.object.members[member_index];
        SpecMemberSurface surface;

        if (member == NULL || member->kind != FENG_TYPE_MEMBER_METHOD ||
            member->is_static != require_static ||
            !slice_equals(member->as.callable.name, name)) {
            continue;
        }
        surface.member = member;
        surface.declaring_spec = current_spec_decl;
        surface.declaring_spec_type_ref = current_spec_type_ref;
        if (!visitor(context, &surface, userdata)) {
            return false;
        }
    }

    for (size_t parent_index = 0U;
         parent_index < current_spec_decl->as.spec_decl.parent_spec_count;
         ++parent_index) {
        const FengTypeRef *parent_type_ref =
            substitute_spec_member_type_ref_for_instance(
                context,
                current_spec_decl,
                current_spec_type_ref,
                current_spec_decl->as.spec_decl.parent_specs[parent_index]);
        const FengDecl *parent_decl =
            resolve_type_ref_decl(context, parent_type_ref);

        if (parent_decl != NULL && parent_decl->kind == FENG_DECL_SPEC &&
            !visit_spec_method_surfaces(context,
                                        parent_decl,
                                        parent_type_ref,
                                        name,
                                        require_static,
                                        visitor,
                                        userdata)) {
            return false;
        }
    }
    return true;
}

/* Access-only view of a same-name spec method surface. It is used while the
 * member expression itself is resolved, before an enclosing call performs
 * argument-based overload selection. */
typedef struct SpecMethodAccessProbe {
    const FengDecl *access_spec_decl;
    InferredExprType access_owner_type;
    bool has_accessible_method;
    const FengDecl *inaccessible_declaring_spec;
    const FengTypeMember *inaccessible_member;
} SpecMethodAccessProbe;

/* Find any accessible requirement and retain the first inaccessible one only
 * for a stable source-level access diagnostic. */
static bool spec_method_access_probe_visitor(
    ResolveContext *context,
    const SpecMemberSurface *surface,
    void *userdata) {
    SpecMethodAccessProbe *probe = (SpecMethodAccessProbe *)userdata;

    if (probe == NULL || surface == NULL || surface->member == NULL ||
        surface->declaring_spec == NULL) {
        return true;
    }
    if (spec_member_is_accessible_from(context,
                                       probe->access_spec_decl,
                                       surface->declaring_spec,
                                       probe->access_owner_type,
                                       surface->member)) {
        probe->has_accessible_method = true;
        return false;
    }
    if (probe->inaccessible_member == NULL) {
        probe->inaccessible_declaring_spec = surface->declaring_spec;
        probe->inaccessible_member = surface->member;
    }
    return true;
}

/* Probe static or instance method accessibility across the exact spec
 * surface without performing signature selection. */
static SpecMethodAccessProbe probe_spec_method_access(
    ResolveContext *context,
    const FengDecl *spec_decl,
    InferredExprType owner_type,
    FengSlice name,
    bool require_static) {
    SpecMethodAccessProbe probe;

    memset(&probe, 0, sizeof(probe));
    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        (spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT &&
         spec_decl->as.spec_decl.form != FENG_SPEC_FORM_INTERSECTION)) {
        return probe;
    }
    probe.access_spec_decl = spec_decl;
    probe.access_owner_type = owner_type;
    (void)visit_spec_method_surfaces(
        context,
        spec_decl,
        owner_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF
            ? owner_type.type_ref
            : NULL,
        name,
        require_static,
        spec_method_access_probe_visitor,
        &probe);
    return probe;
}

/* Immutable inputs and mutable result carried by one target-typed spec
 * method-value surface traversal. */
typedef struct SpecMethodValueResolveState {
    const FengDecl *access_spec_decl;
    InferredExprType access_owner_type;
    const FengTypeRef *expected_type_ref;
    const FengDecl *function_type_decl;
    bool require_accessible;
    CallableValueResolution *result;
} SpecMethodValueResolveState;

/* Select the first exact target-signature match from a spec method surface.
 * Intersection validation has already merged equivalent requirements, so the
 * first matching declaration is the authoritative merged slot identity. */
static bool spec_method_value_surface_visitor(
    ResolveContext *context,
    const SpecMemberSurface *surface,
    void *userdata) {
    SpecMethodValueResolveState *state =
        (SpecMethodValueResolveState *)userdata;
    InferredExprType owner_type;

    if (state == NULL || state->result == NULL || surface == NULL ||
        surface->member == NULL || surface->declaring_spec == NULL) {
        return true;
    }
    owner_type = surface->declaring_spec_type_ref != NULL
                     ? inferred_expr_type_from_type_ref(
                           surface->declaring_spec_type_ref)
                     : inferred_expr_type_from_decl(surface->declaring_spec);
    if ((state->require_accessible &&
         !spec_member_is_accessible_from(context,
                                         state->access_spec_decl,
                                         surface->declaring_spec,
                                         state->access_owner_type,
                                         surface->member)) ||
        !function_type_decl_matches_owner_callable_signature(
            context,
            state->expected_type_ref,
            state->function_type_decl,
            &surface->member->as.callable,
            surface->declaring_spec,
            NULL,
            owner_type)) {
        return true;
    }

    state->result->kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
    state->result->callable = &surface->member->as.callable;
    state->result->callable_member = surface->member;
    state->result->callable_owner_type_decl = surface->declaring_spec;
    state->result->callable_owner_instance_type_ref =
        surface->declaring_spec_type_ref;
    return false;
}

/* Resolve one target-typed method value from an object-form or
 * intersection-form spec surface. The traversal mirrors direct spec calls:
 * child/member-first projection, original requirement identity and exact
 * instantiated signatures. `require_static` selects the instance/static
 * surface; `require_accessible` applies the ordinary access filter or leaves
 * it disabled for a diagnostic-only fallback. */
static CallableValueResolution resolve_spec_method_value_overload(
    ResolveContext *context,
    const FengDecl *spec_decl,
    InferredExprType owner_type,
    FengSlice name,
    const FengTypeRef *expected_type_ref,
    const FengDecl *function_type_decl,
    bool require_static,
    bool require_accessible) {
    CallableValueResolution result;
    SpecMethodValueResolveState state;

    memset(&result, 0, sizeof(result));
    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        (spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT &&
         spec_decl->as.spec_decl.form != FENG_SPEC_FORM_INTERSECTION) ||
        function_type_decl == NULL) {
        return result;
    }
    state.access_spec_decl = spec_decl;
    state.access_owner_type = owner_type;
    state.expected_type_ref = expected_type_ref;
    state.function_type_decl = function_type_decl;
    state.require_accessible = require_accessible;
    state.result = &result;
    (void)visit_spec_method_surfaces(
        context,
        spec_decl,
        owner_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF
            ? owner_type.type_ref
            : NULL,
        name,
        require_static,
        spec_method_value_surface_visitor,
        &state);
    return result;
}

/* Complete compile-time result for one constrained type-parameter static
 * method call. The ordinary overload result is accompanied only by facts
 * needed to select the stable access/missing-overload diagnostic. */
typedef struct SpecMethodCallResolution {
    FunctionCallResolution call;
    bool has_accessible_named_method;
    bool has_matching_inaccessible_method;
    const FengDecl *inaccessible_declaring_spec;
    const FengTypeMember *inaccessible_member;
} SpecMethodCallResolution;

/* Compile-time candidate-selection state shared by all requirements visited
 * for one constrained static method call. */
typedef struct SpecMethodCallResolveState {
    const FengDecl *access_spec_decl;
    InferredExprType access_owner_type;
    FengExpr *const *args;
    size_t arg_count;
    bool has_explicit_type_args;
    const FengTypeRef *const *explicit_type_args;
    size_t explicit_type_arg_count;
    SpecMethodCallResolution *result;
    SpecMemberSurface primary_surface;
    bool has_primary_surface;
} SpecMethodCallResolveState;

/* Evaluate one exact static requirement as an overload candidate. Access is
 * filtered before overload selection, while a matching inaccessible
 * requirement is retained solely for the final AE0708 diagnostic. */
static bool spec_method_call_surface_visitor(
    ResolveContext *context,
    const SpecMemberSurface *surface,
    void *userdata) {
    SpecMethodCallResolveState *state =
        (SpecMethodCallResolveState *)userdata;
    FunctionCallResolution *call;
    InferredExprType owner_type;
    bool accessible;
    bool rejected_existing_array_for_variadic = false;
    PrepackedVariadicRejection spread_rejection =
        FENG_PREPACKED_VARIADIC_REJECTION_NONE;
    int priority;

    if (state == NULL || state->result == NULL || surface == NULL ||
        surface->member == NULL || surface->declaring_spec == NULL) {
        return true;
    }
    call = &state->result->call;
    owner_type = surface->declaring_spec_type_ref != NULL
                     ? inferred_expr_type_from_type_ref(
                           surface->declaring_spec_type_ref)
                     : inferred_expr_type_from_decl(surface->declaring_spec);
    accessible = spec_member_is_accessible_from(
        context,
        state->access_spec_decl,
        surface->declaring_spec,
        state->access_owner_type,
        surface->member);
    if (accessible) {
        state->result->has_accessible_named_method = true;
    }
    if (!callable_parameters_match_args_for_owner_instance(
            context,
            &surface->member->as.callable,
            surface->declaring_spec,
            NULL,
            owner_type,
            state->args,
            state->arg_count,
            state->explicit_type_args,
            state->explicit_type_arg_count,
            false,
            &rejected_existing_array_for_variadic,
            &spread_rejection)) {
        if (accessible) {
            if (rejected_existing_array_for_variadic) {
                call->rejected_existing_array_for_variadic = true;
            }
            merge_prepacked_variadic_rejection(
                &call->prepacked_variadic_rejection,
                spread_rejection);
        }
        return true;
    }
    if (!accessible) {
        if (!state->result->has_matching_inaccessible_method) {
            state->result->has_matching_inaccessible_method = true;
            state->result->inaccessible_declaring_spec =
                surface->declaring_spec;
            state->result->inaccessible_member = surface->member;
        }
        return true;
    }

    priority = compute_overload_match_priority(
        state->has_explicit_type_args,
        state->explicit_type_arg_count,
        surface->member->as.callable.type_param_count,
        callable_parameters_exactly_match_args_for_owner_instance(
            context,
            &surface->member->as.callable,
            surface->declaring_spec,
            NULL,
            owner_type,
            state->args,
            state->arg_count));
    if (call->kind == FENG_FUNCTION_CALL_RESOLUTION_NONE ||
        priority < call->match_priority) {
        call->kind = FENG_FUNCTION_CALL_RESOLUTION_UNIQUE;
        call->match_priority = priority;
        call->decl = NULL;
        call->callable = &surface->member->as.callable;
        call->member = surface->member;
        call->owner_type_decl = surface->declaring_spec;
        call->fit_decl = NULL;
        call->owner_instance_type_ref = surface->declaring_spec_type_ref;
        state->primary_surface = *surface;
        state->has_primary_surface = true;
        return true;
    }
    if (priority > call->match_priority) {
        return true;
    }

    if (state->has_primary_surface) {
        InferredExprType primary_owner =
            state->primary_surface.declaring_spec_type_ref != NULL
                ? inferred_expr_type_from_type_ref(
                      state->primary_surface.declaring_spec_type_ref)
                : inferred_expr_type_from_decl(
                      state->primary_surface.declaring_spec);

        if (callable_signatures_equal_for_owner_instances(
                context,
                &state->primary_surface.member->as.callable,
                state->primary_surface.declaring_spec,
                primary_owner,
                &surface->member->as.callable,
                surface->declaring_spec,
                owner_type)) {
            return true;
        }
    }

    call->kind = FENG_FUNCTION_CALL_RESOLUTION_AMBIGUOUS;
    call->decl = NULL;
    call->callable = NULL;
    call->member = NULL;
    call->owner_type_decl = NULL;
    call->fit_decl = NULL;
    call->owner_instance_type_ref = NULL;
    return true;
}

/* Resolve a direct static method call through the exact requirement surface
 * of an object- or intersection-form constraint. This is the single resolver
 * used by both forms; only their surface composition and witness view differ. */
static SpecMethodCallResolution resolve_spec_method_call_overload(
    ResolveContext *context,
    const FengDecl *spec_decl,
    InferredExprType owner_type,
    FengSlice name,
    FengExpr *const *args,
    size_t arg_count,
    bool require_static,
    bool has_explicit_type_args,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count) {
    SpecMethodCallResolution result;
    SpecMethodCallResolveState state;

    memset(&result, 0, sizeof(result));
    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        (spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT &&
         spec_decl->as.spec_decl.form != FENG_SPEC_FORM_INTERSECTION)) {
        return result;
    }
    memset(&state, 0, sizeof(state));
    state.access_spec_decl = spec_decl;
    state.access_owner_type = owner_type;
    state.args = args;
    state.arg_count = arg_count;
    state.has_explicit_type_args = has_explicit_type_args;
    state.explicit_type_args = explicit_type_args;
    state.explicit_type_arg_count = explicit_type_arg_count;
    state.result = &result;
    (void)visit_spec_method_surfaces(
        context,
        spec_decl,
        owner_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF
            ? owner_type.type_ref
            : NULL,
        name,
        require_static,
        spec_method_call_surface_visitor,
        &state);
    return result;
}

static bool function_type_parameters_match_args(ResolveContext *context,
                                                const FengDecl *type_decl,
                                                FengExpr *const *args,
                                                size_t arg_count,
                                                bool *out_rejected_existing_array_for_variadic,
                                                PrepackedVariadicRejection *out_prepacked_variadic_rejection) {
    size_t arg_index;
    bool is_variadic;
    size_t fixed_count;

    if (out_rejected_existing_array_for_variadic != NULL) {
        *out_rejected_existing_array_for_variadic = false;
    }
    if (out_prepacked_variadic_rejection != NULL) {
        *out_prepacked_variadic_rejection = FENG_PREPACKED_VARIADIC_REJECTION_NONE;
    }

    if (!decl_is_function_type(type_decl)) {
        return false;
    }
    is_variadic = type_decl->as.spec_decl.as.callable.param_count > 0U &&
                  type_decl->as.spec_decl.as.callable
                      .params[type_decl->as.spec_decl.as.callable.param_count - 1U]
                      .is_variadic;
    fixed_count = is_variadic ? type_decl->as.spec_decl.as.callable.param_count - 1U
                              : type_decl->as.spec_decl.as.callable.param_count;

    {
        PrepackedVariadicRejection spread_rejection =
            prepacked_variadic_shape_rejection(args, arg_count, is_variadic, fixed_count);
        if (out_prepacked_variadic_rejection != NULL) {
            *out_prepacked_variadic_rejection = spread_rejection;
        }
        if (spread_rejection != FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
            return false;
        }
    }

    if (is_variadic) {
        if (arg_count < fixed_count) {
            return false;
        }
    } else if (type_decl->as.spec_decl.as.callable.param_count != arg_count) {
        return false;
    }

    for (arg_index = 0U; arg_index < arg_count; ++arg_index) {
        const FengTypeRef *param_type =
            arg_index < fixed_count || args[arg_index]->is_prepacked_variadic_arg
                ? type_decl->as.spec_decl.as.callable.params[arg_index].type
                : type_decl->as.spec_decl.as.callable.params[fixed_count].type->as.inner;

        if (args[arg_index] != NULL &&
            args[arg_index]->kind == FENG_EXPR_LAMBDA &&
            resolve_function_type_decl(context, param_type) == NULL) {
            return false;
        }
        if (!expr_matches_expected_type_ref(context, args[arg_index], param_type)) {
            if (out_prepacked_variadic_rejection != NULL &&
                args[arg_index]->is_prepacked_variadic_arg) {
                *out_prepacked_variadic_rejection =
                    FENG_PREPACKED_VARIADIC_REJECTION_TYPE_MISMATCH;
            }
            if (out_rejected_existing_array_for_variadic != NULL &&
                is_variadic &&
                arg_count == type_decl->as.spec_decl.as.callable.param_count &&
                arg_index == fixed_count &&
                expr_is_existing_array_for_expected_type_ref(
                    context,
                    args[arg_index],
                    type_decl->as.spec_decl.as.callable.params[fixed_count].type)) {
                *out_rejected_existing_array_for_variadic = true;
            }
            return false;
        }
    }

    return true;
}

static bool function_type_parameters_match_args_for_instance(
    ResolveContext *context,
    const FengDecl *type_decl,
    InferredExprType owner_type,
    FengExpr *const *args,
    size_t arg_count,
    bool *out_rejected_existing_array_for_variadic,
    PrepackedVariadicRejection *out_prepacked_variadic_rejection) {
    size_t arg_index;
    bool is_variadic;
    size_t fixed_count;

    if (out_rejected_existing_array_for_variadic != NULL) {
        *out_rejected_existing_array_for_variadic = false;
    }
    if (out_prepacked_variadic_rejection != NULL) {
        *out_prepacked_variadic_rejection = FENG_PREPACKED_VARIADIC_REJECTION_NONE;
    }

    if (!decl_is_function_type(type_decl)) {
        return false;
    }
    is_variadic = type_decl->as.spec_decl.as.callable.param_count > 0U &&
                  type_decl->as.spec_decl.as.callable
                      .params[type_decl->as.spec_decl.as.callable.param_count - 1U]
                      .is_variadic;
    fixed_count = is_variadic ? type_decl->as.spec_decl.as.callable.param_count - 1U
                              : type_decl->as.spec_decl.as.callable.param_count;

    {
        PrepackedVariadicRejection spread_rejection =
            prepacked_variadic_shape_rejection(args, arg_count, is_variadic, fixed_count);
        if (out_prepacked_variadic_rejection != NULL) {
            *out_prepacked_variadic_rejection = spread_rejection;
        }
        if (spread_rejection != FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
            return false;
        }
    }

    if (is_variadic) {
        if (arg_count < fixed_count) {
            return false;
        }
    } else if (type_decl->as.spec_decl.as.callable.param_count != arg_count) {
        return false;
    }

    for (arg_index = 0U; arg_index < arg_count; ++arg_index) {
        const FengTypeRef *declared_param_type =
            arg_index < fixed_count || args[arg_index]->is_prepacked_variadic_arg
                ? type_decl->as.spec_decl.as.callable.params[arg_index].type
                : type_decl->as.spec_decl.as.callable.params[fixed_count].type->as.inner;
        const FengTypeRef *param_type = substitute_type_ref_for_owner_instance(
            context,
            type_decl,
            owner_type,
            declared_param_type);

        if (args[arg_index] != NULL &&
            args[arg_index]->kind == FENG_EXPR_LAMBDA &&
            resolve_function_type_decl(context, param_type) == NULL) {
            return false;
        }
        if (!expr_matches_expected_type_ref(context, args[arg_index], param_type)) {
            if (out_prepacked_variadic_rejection != NULL &&
                args[arg_index]->is_prepacked_variadic_arg) {
                *out_prepacked_variadic_rejection =
                    FENG_PREPACKED_VARIADIC_REJECTION_TYPE_MISMATCH;
            }
            if (out_rejected_existing_array_for_variadic != NULL &&
                is_variadic &&
                arg_count == type_decl->as.spec_decl.as.callable.param_count &&
                arg_index == fixed_count) {
                const FengTypeRef *array_param_type = substitute_type_ref_for_owner_instance(
                    context,
                    type_decl,
                    owner_type,
                    type_decl->as.spec_decl.as.callable.params[fixed_count].type);

                if (expr_is_existing_array_for_expected_type_ref(context,
                                                                 args[arg_index],
                                                                 array_param_type)) {
                    *out_rejected_existing_array_for_variadic = true;
                }
            }
            return false;
        }
    }

    return true;
}

static FunctionCallResolution resolve_module_public_function_overload(
    ResolveContext *context,
    const FengSemanticModule *module,
    FengSlice name,
    FengExpr *const *args,
    size_t arg_count,
    bool has_explicit_type_args,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count) {
    size_t program_index;
    FunctionCallResolution result;

    memset(&result, 0, sizeof(result));
    if (module == NULL) {
        return result;
    }

    for (program_index = 0U; program_index < module->program_count; ++program_index) {
        const FengProgram *program = module->programs[program_index];
        size_t decl_index;

        for (decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
            const FengDecl *decl = program->declarations[decl_index];

            if (decl->kind != FENG_DECL_FUNCTION || !decl_is_public(decl) ||
                !slice_equals(decl->as.function_decl.name, name)) {
                continue;
            }
            bool rejected_existing_array_for_variadic = false;
            PrepackedVariadicRejection spread_rejection =
                FENG_PREPACKED_VARIADIC_REJECTION_NONE;

            if (!callable_parameters_match_args(context,
                                                &decl->as.function_decl,
                                                args,
                                                arg_count,
                                                explicit_type_args,
                                                explicit_type_arg_count,
                                                decl->is_extern,
                                                &rejected_existing_array_for_variadic,
                                                &spread_rejection)) {
                if (rejected_existing_array_for_variadic) {
                    result.rejected_existing_array_for_variadic = true;
                }
                merge_prepacked_variadic_rejection(
                    &result.prepacked_variadic_rejection, spread_rejection);
                continue;
            }

            int priority = compute_overload_match_priority(
                has_explicit_type_args,
                explicit_type_arg_count,
                decl->as.function_decl.type_param_count,
                callable_parameters_exactly_match_args(context,
                                                       &decl->as.function_decl,
                                                       args,
                                                       arg_count));

            if (result.kind == FENG_FUNCTION_CALL_RESOLUTION_NONE ||
                priority < result.match_priority) {
                result.kind = FENG_FUNCTION_CALL_RESOLUTION_UNIQUE;
                result.match_priority = priority;
                result.decl = decl;
                result.callable = &decl->as.function_decl;
                continue;
            }
            if (priority > result.match_priority) {
                continue;
            }

            result.kind = FENG_FUNCTION_CALL_RESOLUTION_AMBIGUOUS;
            result.decl = NULL;
            result.callable = NULL;
        }
    }

    return result;
}

static const FengTypeMember *find_type_method_member(const FengDecl *type_decl, FengSlice name) {
    size_t member_index;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }

    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];

        if (!member->is_static &&
            member->kind == FENG_TYPE_MEMBER_METHOD &&
            slice_equals(member->as.callable.name, name)) {
            return member;
        }
    }

    return NULL;
}

static const FengTypeMember *find_type_static_method_member(const FengDecl *type_decl, FengSlice name) {
    size_t member_index;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }

    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];

        if (member->is_static &&
            member->kind == FENG_TYPE_MEMBER_METHOD &&
            slice_equals(member->as.callable.name, name)) {
            return member;
        }
    }

    return NULL;
}

static const FengTypeMember *find_type_static_member(const FengDecl *type_decl, FengSlice name) {
    const FengTypeMember *member = find_type_static_field_member(type_decl, name);

    if (member != NULL) {
        return member;
    }
    return find_type_static_method_member(type_decl, name);
}

/* Visit every fit-body method member that targets `type_decl` and is visible from
 * the current resolve context. Callback returns false to stop iteration; iteration
 * function returns false only when stopped by the callback. */
typedef bool (*FitMethodVisitor)(const FengTypeMember *member,
                                 const FengSemanticModule *fit_module,
                                 const FengDecl *fit_decl,
                                 void *userdata);

static bool fit_decl_is_visible_from(const ResolveContext *ctx,
                                     const FengSemanticModule *fit_module,
                                     const FengDecl *fit_decl) {
    if (ctx == NULL || fit_module == NULL || fit_decl == NULL) {
        return false;
    }
    if (fit_module == ctx->module) {
        return true;
    }
    /* Cross-module fits become effective in the consumer only when (a) the
     * fit itself is `open fit`, and (b) the consumer file imported the fit's
     * owning module via `use`. Mirrors docs/specifications/feng-fit.md §4: "其他 mod 通过
     * use 引入当前模块后，该契约关系在其作用域内生效". */
    return fit_decl->visibility == FENG_VISIBILITY_PUBLIC &&
           module_is_import_visible_from(ctx, fit_module);
}

static bool visit_visible_fit_methods_for_type(const ResolveContext *ctx,
                                               const FengDecl *type_decl,
                                               FengSlice name,
                                               bool require_name_match,
                                               bool require_static,
                                               FitMethodVisitor visitor,
                                               void *userdata) {
    size_t module_index;
    size_t program_index;
    size_t decl_index;
    size_t member_index;

    if (ctx == NULL || ctx->analysis == NULL || !decl_is_named_fit_target(type_decl)) {
        return true;
    }

    for (module_index = 0U; module_index < ctx->analysis->module_count; ++module_index) {
        const FengSemanticModule *m = &ctx->analysis->modules[module_index];

        for (program_index = 0U; program_index < m->program_count; ++program_index) {
            const FengProgram *prog = m->programs[program_index];

            if (prog == NULL) {
                continue;
            }
            for (decl_index = 0U; decl_index < prog->declaration_count; ++decl_index) {
                const FengDecl *fd = prog->declarations[decl_index];

                if (fd == NULL || fd->kind != FENG_DECL_FIT) {
                    continue;
                }
                if (!fit_decl_is_visible_from(ctx, m, fd)) {
                    continue;
                }
                if (resolve_type_ref_decl(ctx, fd->as.fit_decl.target) != type_decl) {
                    continue;
                }
                for (member_index = 0U; member_index < fd->as.fit_decl.member_count; ++member_index) {
                    const FengTypeMember *member = fd->as.fit_decl.members[member_index];

                    if (member == NULL || member->kind != FENG_TYPE_MEMBER_METHOD ||
                        member->is_static != require_static) {
                        continue;
                    }
                    if (require_name_match &&
                        !slice_equals(member->as.callable.name, name)) {
                        continue;
                    }
                    if (!visitor(member, m, fd, userdata)) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

static bool visit_visible_fit_methods_for_owner_type(const ResolveContext *ctx,
                                                     const FengDecl *owner_type_decl,
                                                     InferredExprType owner_type,
                                                     FengSlice name,
                                                     bool require_name_match,
                                                     bool require_static,
                                                     FitMethodVisitor visitor,
                                                     void *userdata) {
    size_t module_index;
    size_t program_index;
    size_t decl_index;
    size_t member_index;

    if (ctx == NULL || ctx->analysis == NULL) {
        return true;
    }

    for (module_index = 0U; module_index < ctx->analysis->module_count; ++module_index) {
        const FengSemanticModule *m = &ctx->analysis->modules[module_index];

        for (program_index = 0U; program_index < m->program_count; ++program_index) {
            const FengProgram *prog = m->programs[program_index];

            if (prog == NULL) {
                continue;
            }
            for (decl_index = 0U; decl_index < prog->declaration_count; ++decl_index) {
                const FengDecl *fd = prog->declarations[decl_index];
                bool visible;
                bool target_matches;

                if (fd == NULL || fd->kind != FENG_DECL_FIT) {
                    continue;
                }
                visible = fit_decl_is_visible_from(ctx, m, fd);
                target_matches = visible &&
                                 fit_decl_target_matches_owner_type(ctx,
                                                                    fd,
                                                                    owner_type_decl,
                                                                    owner_type);
                if (!visible) {
                    continue;
                }
                if (!target_matches) {
                    continue;
                }
                for (member_index = 0U; member_index < fd->as.fit_decl.member_count; ++member_index) {
                    const FengTypeMember *member = fd->as.fit_decl.members[member_index];

                    if (member == NULL || member->kind != FENG_TYPE_MEMBER_METHOD ||
                        member->is_static != require_static) {
                        continue;
                    }
                    if (require_name_match &&
                        !slice_equals(member->as.callable.name, name)) {
                        continue;
                    }
                    if (!visitor(member, m, fd, userdata)) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

/* Match one method-value candidate after substituting the concrete owner and
 * fit target into its declared parameter and return surfaces. */
static bool function_type_decl_matches_owner_callable_signature(
    ResolveContext *context,
    const FengTypeRef *function_type_ref,
    const FengDecl *function_type_decl,
    const FengCallableSignature *callable,
    const FengDecl *owner_type_decl,
    const FengDecl *fit_decl,
    InferredExprType owner_type) {
    size_t param_index;
    const FengTypeRef *expected_return;
    InferredExprType actual_return;

    if (function_type_decl == NULL || callable == NULL ||
        !decl_is_function_type(function_type_decl) ||
        function_type_decl->as.spec_decl.as.callable.param_count !=
            callable->param_count) {
        return false;
    }
    for (param_index = 0U; param_index < callable->param_count; ++param_index) {
        const FengParameter *expected_decl_param =
            &function_type_decl->as.spec_decl.as.callable.params[param_index];
        const FengParameter *actual_decl_param = &callable->params[param_index];
        const FengTypeRef *expected_param =
            substitute_spec_member_type_ref_for_instance(
                context,
                function_type_decl,
                function_type_ref,
                expected_decl_param->type);
        const FengTypeRef *actual_param = substitute_type_ref_for_owner_instance(
            context,
            owner_type_decl,
            owner_type,
            actual_decl_param->type);

        actual_param = substitute_type_ref_for_fit_instance(context,
                                                            fit_decl,
                                                            owner_type,
                                                            actual_param);
        if (!callable_parameter_forms_match(expected_decl_param,
                                            actual_decl_param) ||
            !type_refs_semantically_equal(context, expected_param, actual_param)) {
            return false;
        }
    }

    expected_return = substitute_spec_member_type_ref_for_instance(
        context,
        function_type_decl,
        function_type_ref,
        function_type_decl->as.spec_decl.as.callable.return_type);
    actual_return = callable_effective_return_type(context, callable);
    if (actual_return.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        actual_return.type_ref = substitute_type_ref_for_owner_instance(
            context,
            owner_type_decl,
            owner_type,
            actual_return.type_ref);
        actual_return.type_ref = substitute_type_ref_for_fit_instance(
            context,
            fit_decl,
            owner_type,
            actual_return.type_ref);
    }
    return inferred_expr_type_matches_type_ref(context,
                                               actual_return,
                                               expected_return);
}

typedef struct FitMethodValueResolveCtx {
    ResolveContext *context;
    const FengTypeRef *expected_type_ref;
    const FengDecl *function_type_decl;
    const FengDecl *owner_type_decl;
    InferredExprType owner_type;
    bool requires_abi_callable;
    const FengTypeRef *const *explicit_type_args;
    size_t explicit_type_arg_count;
    bool require_static;
    CallableValueResolution result;
} FitMethodValueResolveCtx;

/* Collect one visible fit-body candidate for a target-typed method value. */
static bool fit_method_value_resolve_visitor(
    const FengTypeMember *member,
    const FengSemanticModule *fit_module,
    const FengDecl *fit_decl,
    void *userdata) {
    FitMethodValueResolveCtx *state = (FitMethodValueResolveCtx *)userdata;

    (void)fit_module;
    bool signature_matches;

    if (member == NULL || member->is_static != state->require_static ||
        !fit_member_is_accessible_from(state->context,
                                       state->owner_type_decl,
                                       state->owner_type,
                                       fit_decl,
                                       member)) {
        return true;
    }
    if (state->requires_abi_callable &&
        !method_member_is_abi_callable_value(member)) {
        return true;
    }
    if (state->require_static && state->explicit_type_args == NULL &&
        member->as.callable.type_param_count > 0U) {
        return true;
    }
    signature_matches = state->explicit_type_args != NULL
                            ? function_type_decl_matches_explicit_callable_signature(
                                  state->context,
                                  state->expected_type_ref,
                                  state->function_type_decl,
                                  &member->as.callable,
                                  state->owner_type_decl,
                                  fit_decl,
                                  state->owner_type,
                                  state->explicit_type_args,
                                  state->explicit_type_arg_count)
                            : function_type_decl_matches_owner_callable_signature(
                                  state->context,
                                  state->expected_type_ref,
                                  state->function_type_decl,
                                  &member->as.callable,
                                  state->owner_type_decl,
                                  fit_decl,
                                  state->owner_type);
    if (!signature_matches) {
        return true;
    }
    if (state->result.kind == FENG_CALLABLE_VALUE_RESOLUTION_NONE) {
        state->result.kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
        state->result.callable = &member->as.callable;
        state->result.callable_member = member;
        state->result.callable_owner_type_decl = state->owner_type_decl;
        state->result.callable_fit_decl = fit_decl;
        state->result.callable_type_args = state->explicit_type_args;
        state->result.callable_type_arg_count =
            state->explicit_type_arg_count;
        return true;
    }

    state->result.kind = FENG_CALLABLE_VALUE_RESOLUTION_AMBIGUOUS;
    state->result.callable = NULL;
    state->result.callable_member = NULL;
    state->result.callable_owner_type_decl = NULL;
    state->result.callable_fit_decl = NULL;
    state->result.callable_type_args = NULL;
    state->result.callable_type_arg_count = 0U;
    return true;
}

/* Resolve visible fit-body methods as method-value candidates. */
static CallableValueResolution resolve_accessible_fit_method_value_overload(
    ResolveContext *context,
    const FengDecl *owner_type_decl,
    InferredExprType owner_type,
    FengSlice name,
    const FengTypeRef *expected_type_ref,
    const FengDecl *function_type_decl,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count,
    bool require_static) {
    FitMethodValueResolveCtx state;

    memset(&state, 0, sizeof state);
    state.context = context;
    state.expected_type_ref = expected_type_ref;
    state.function_type_decl = function_type_decl;
    state.owner_type_decl = owner_type_decl;
    state.owner_type = owner_type;
    state.requires_abi_callable =
        function_type_decl_is_abi_callable_type(function_type_decl);
    state.explicit_type_args = explicit_type_args;
    state.explicit_type_arg_count = explicit_type_arg_count;
    state.require_static = require_static;
    (void)visit_visible_fit_methods_for_owner_type(
        context,
        owner_type_decl,
        owner_type,
        name,
        true,
        require_static,
        fit_method_value_resolve_visitor,
        &state);
    return state.result;
}

/* Merge the type-owned and visible-fit halves of one target-typed member
 * reference. Any match on both independent declaration surfaces remains an
 * ambiguity, matching the existing method-value overload rule. */
static CallableValueResolution merge_callable_value_resolutions(
    CallableValueResolution primary,
    CallableValueResolution extension) {
    CallableValueResolution result;

    if (primary.kind == FENG_CALLABLE_VALUE_RESOLUTION_NONE) {
        return extension;
    }
    if (extension.kind == FENG_CALLABLE_VALUE_RESOLUTION_NONE) {
        return primary;
    }
    memset(&result, 0, sizeof(result));
    result.kind = FENG_CALLABLE_VALUE_RESOLUTION_AMBIGUOUS;
    return result;
}

/* Resolve `Concrete.method` against the same type-owned and visible-fit
 * static member surface used by direct calls. Generic owner arguments are
 * part of owner_type; method-local arguments, when present, are explicit. */
static CallableValueResolution resolve_concrete_static_method_value(
    ResolveContext *context,
    const ResolvedTypeTarget *target,
    FengSlice name,
    const FengTypeRef *expected_type_ref,
    const FengDecl *function_type_decl,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count) {
    CallableValueResolution owned;
    CallableValueResolution fit;
    InferredExprType owner_type;

    memset(&owned, 0, sizeof(owned));
    memset(&fit, 0, sizeof(fit));
    if (target == NULL ||
        (target->type_decl == NULL && !target->is_builtin_type_name) ||
        (target->type_decl != NULL &&
         target->type_decl->kind != FENG_DECL_TYPE)) {
        return owned;
    }
    /* A generic concrete owner has no anonymous or target-inferred instance;
     * its complete owner argument list must be present on the type target. */
    if (target->type_decl != NULL &&
        target->type_decl->as.type_decl.type_param_count > 0U &&
        target->type_ref == NULL) {
        return owned;
    }
    owner_type = resolved_type_target_owner_type(target);
    if (target->type_decl != NULL) {
        owned = resolve_accessible_method_value_overload(
            context,
            target->type_decl,
            target->provider_module,
            owner_type,
            name,
            expected_type_ref,
            function_type_decl,
            explicit_type_args,
            explicit_type_arg_count,
            true);
    }
    fit = resolve_accessible_fit_method_value_overload(
        context,
        target->type_decl,
        owner_type,
        name,
        expected_type_ref,
        function_type_decl,
        explicit_type_args,
        explicit_type_arg_count,
        true);
    return merge_callable_value_resolutions(owned, fit);
}

typedef struct FitFirstMethodCtx {
    ResolveContext *context;
    const FengDecl *source_type;
    InferredExprType owner_type;
    bool enforce_static_access;
    const FengTypeMember *result;
} FitFirstMethodCtx;

static bool fit_first_method_visitor(const FengTypeMember *member,
                                     const FengSemanticModule *fit_module,
                                     const FengDecl *fit_decl,
                                     void *userdata) {
    FitFirstMethodCtx *st = (FitFirstMethodCtx *)userdata;

    (void)fit_module;
    if (!fit_member_is_accessible_from(
            st->context,
            st->source_type,
            st->owner_type,
            fit_decl,
            member)) {
        return true;
    }
    st->result = member;
    return false;
}

static const FengTypeMember *find_fit_method_member_for_type(ResolveContext *ctx,
                                                             const FengDecl *type_decl,
                                                             FengSlice name) {
    FitFirstMethodCtx st;

    memset(&st, 0, sizeof(st));
    st.context = ctx;
    st.source_type = type_decl;
    st.owner_type = inferred_expr_type_from_decl(type_decl);
    (void)visit_visible_fit_methods_for_type(ctx, type_decl, name, true, false,
                                             fit_first_method_visitor, &st);
    return st.result;
}

static const FengTypeMember *find_fit_static_method_member_for_type(ResolveContext *ctx,
                                                                    const FengDecl *type_decl,
                                                                    FengSlice name) {
    FitFirstMethodCtx st;

    memset(&st, 0, sizeof(st));
    st.context = ctx;
    st.source_type = type_decl;
    st.owner_type = inferred_expr_type_from_decl(type_decl);
    st.enforce_static_access = true;
    (void)visit_visible_fit_methods_for_type(ctx, type_decl, name, true, true,
                                             fit_first_method_visitor, &st);
    return st.result;
}

static const FengTypeMember *find_fit_method_member_for_owner_type(ResolveContext *ctx,
                                                                   const FengDecl *owner_type_decl,
                                                                   InferredExprType owner_type,
                                                                   FengSlice name) {
    FitFirstMethodCtx st;

    memset(&st, 0, sizeof(st));
    st.context = ctx;
    st.source_type = owner_type_decl;
    st.owner_type = owner_type;
    (void)visit_visible_fit_methods_for_owner_type(ctx,
                                                    owner_type_decl,
                                                    owner_type,
                                                    name,
                                                    true,
                                                    false,
                                                    fit_first_method_visitor,
                                                    &st);
    return st.result;
}

static const FengTypeMember *find_fit_static_method_member_for_owner_type(ResolveContext *ctx,
                                                                          const FengDecl *owner_type_decl,
                                                                          InferredExprType owner_type,
                                                                          FengSlice name) {
    FitFirstMethodCtx st;

    memset(&st, 0, sizeof(st));
    st.context = ctx;
    st.source_type = owner_type_decl;
    st.owner_type = owner_type;
    st.enforce_static_access = true;
    (void)visit_visible_fit_methods_for_owner_type(ctx,
                                                    owner_type_decl,
                                                    owner_type,
                                                    name,
                                                    true,
                                                    true,
                                                    fit_first_method_visitor,
                                                    &st);
    return st.result;
}

static const FengTypeMember *find_accessible_type_field_member(ResolveContext *context,
                                                               const FengDecl *type_decl,
                                                               const FengSemanticModule *provider_module,
                                                               InferredExprType owner_type,
                                                               FengSlice name) {
    const FengTypeMember *member = find_type_field_member(type_decl, name);

    (void)provider_module;
    if (!type_member_is_accessible_from(context,
                                        type_decl,
                                        owner_type,
                                        member)) {
        return NULL;
    }
    if (fit_body_blocks_private_access(context, type_decl, member)) {
        return NULL;
    }
    return member;
}

static const FengTypeMember *find_accessible_type_method_member(ResolveContext *context,
                                                                const FengDecl *type_decl,
                                                                const FengSemanticModule *provider_module,
                                                                InferredExprType owner_type,
                                                                FengSlice name) {
    size_t member_index;

    (void)provider_module;
    if (type_decl != NULL && type_decl->kind == FENG_DECL_TYPE) {
        for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
            const FengTypeMember *member = type_decl->as.type_decl.members[member_index];

            if (!member->is_static &&
                member->kind == FENG_TYPE_MEMBER_METHOD &&
                slice_equals(member->as.callable.name, name) &&
                type_member_is_accessible_from(context,
                                               type_decl,
                                               owner_type,
                                               member) &&
                !fit_body_blocks_private_access(context, type_decl, member)) {
                return member;
            }
        }
    }
    /* Fall back to any visible fit-body method for this type. */
    return find_fit_method_member_for_owner_type(context,
                                                 type_decl,
                                                 owner_type,
                                                 name);
}

/* Find any instance member with this name that is visible from the current
 * type domain. This is a name-level precheck only; call and method-value
 * resolution still select the matching method signature afterwards. */
static const FengTypeMember *find_accessible_type_instance_member(
    ResolveContext *context,
    const FengDecl *type_decl,
    const FengSemanticModule *provider_module,
    InferredExprType owner_type,
    FengSlice name) {
    const FengTypeMember *field = find_type_field_member(type_decl, name);

    if (type_member_is_accessible_from(context,
                                       type_decl,
                                       owner_type,
                                       field) &&
        !fit_body_blocks_private_access(context, type_decl, field)) {
        return field;
    }
    return find_accessible_type_method_member(context,
                                              type_decl,
                                              provider_module,
                                              owner_type,
                                              name);
}

/* Static fields and methods share the Type.member access path. Return any
 * visible declaration with the requested name without choosing an overload. */
static const FengTypeMember *find_accessible_type_static_member(
    ResolveContext *context,
    const FengDecl *type_decl,
    InferredExprType owner_type,
    FengSlice name) {
    size_t member_index;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }
    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];
        FengSlice member_name;

        if (!member->is_static ||
            (member->kind != FENG_TYPE_MEMBER_FIELD &&
             member->kind != FENG_TYPE_MEMBER_METHOD)) {
            continue;
        }
        member_name = member->kind == FENG_TYPE_MEMBER_FIELD
                          ? member->as.field.name
                          : member->as.callable.name;
        if (slice_equals(member_name, name) &&
            type_member_is_accessible_from(context,
                                           type_decl,
                                           owner_type,
                                           member) &&
            !fit_body_blocks_private_access(context, type_decl, member)) {
            return member;
        }
    }
    return NULL;
}

typedef struct FitMethodCountCtx {
    size_t count;
} FitMethodCountCtx;

static bool fit_method_count_visitor(const FengTypeMember *member,
                                     const FengSemanticModule *fit_module,
                                     const FengDecl *fit_decl,
                                     void *userdata) {
    FitMethodCountCtx *st = (FitMethodCountCtx *)userdata;

    (void)member;
    (void)fit_module;
    (void)fit_decl;
    ++st->count;
    return true;
}

static size_t count_accessible_method_overloads(ResolveContext *context,
                                                const FengDecl *type_decl,
                                                const FengSemanticModule *provider_module,
                                                InferredExprType owner_type,
                                                FengSlice name) {
    size_t member_index;
    size_t count = 0U;
    FitMethodCountCtx st;

    (void)provider_module;
    if (type_decl == NULL) {
        st.count = 0U;
        (void)visit_visible_fit_methods_for_owner_type(context,
                                                       NULL,
                                                       owner_type,
                                                       name,
                                                       true,
                                                       false,
                                                       fit_method_count_visitor,
                                                       &st);
        return st.count;
    }

    if (type_decl->kind == FENG_DECL_SPEC) {
        const FengDecl **closure = NULL;
        size_t closure_count = 0U;
        size_t closure_capacity = 0U;
        size_t i;
        size_t j;

        if (type_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
            const FengIntersectionSpecInfo *info =
                feng_semantic_lookup_intersection_spec_info(context->analysis,
                                                            type_decl);

            if (info == NULL) {
                return 0U;
            }
            for (i = 0U; i < info->flattened_member_count; ++i) {
                const FengDecl *member_decl = info->flattened_members[i];

                closure = NULL;
                closure_count = 0U;
                closure_capacity = 0U;
                if (!spec_collect_closure(context,
                                          member_decl,
                                          &closure,
                                          &closure_count,
                                          &closure_capacity)) {
                    free(closure);
                    continue;
                }
                for (j = 0U; j < closure_count; ++j) {
                    const FengDecl *current = closure[j];

                    if (current == NULL ||
                        current->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
                        continue;
                    }
                    for (size_t member_index = 0U;
                         member_index <
                             current->as.spec_decl.as.object.member_count;
                         ++member_index) {
                        const FengTypeMember *member =
                            current->as.spec_decl.as.object
                                .members[member_index];

                        if (member != NULL && !member->is_static &&
                            member->kind == FENG_TYPE_MEMBER_METHOD &&
                            slice_equals(member->as.callable.name, name)) {
                            ++count;
                        }
                    }
                }
                free(closure);
            }
            return count;
        }
        if (type_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            return 0U;
        }
        if (!spec_collect_closure(context, type_decl, &closure, &closure_count, &closure_capacity)) {
            free(closure);
            return 0U;
        }
        for (i = 0U; i < closure_count; ++i) {
            const FengDecl *current = closure[i];

            if (current->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
                continue;
            }
            for (j = 0U; j < current->as.spec_decl.as.object.member_count; ++j) {
                const FengTypeMember *member = current->as.spec_decl.as.object.members[j];

                if (member->kind == FENG_TYPE_MEMBER_METHOD &&
                    slice_equals(member->as.callable.name, name)) {
                    ++count;
                }
            }
        }
        free(closure);
        return count;
    }

    if (!decl_is_named_fit_target(type_decl)) {
        return 0U;
    }

    if (type_decl->kind == FENG_DECL_TYPE) {
        for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
            const FengTypeMember *member = type_decl->as.type_decl.members[member_index];

            if (!member->is_static &&
                member->kind == FENG_TYPE_MEMBER_METHOD &&
                slice_equals(member->as.callable.name, name) &&
                type_member_is_accessible_from(context,
                                               type_decl,
                                               owner_type,
                                               member) &&
                !fit_body_blocks_private_access(context, type_decl, member)) {
                ++count;
            }
        }
    }

    st.count = 0U;
    (void)visit_visible_fit_methods_for_type(context, type_decl, name, true, false,
                                             fit_method_count_visitor, &st);
    return count + st.count;
}

typedef struct FitOverloadResolveCtx {
    ResolveContext *context;
    const FengDecl *owner_type_decl;
    InferredExprType owner_type;
    FengExpr *const *args;
    size_t arg_count;
    bool has_explicit_type_args;
    const FengTypeRef *const *explicit_type_args;
    size_t explicit_type_arg_count;
    bool enforce_static_access;
    FunctionCallResolution result;
} FitOverloadResolveCtx;

static bool fit_overload_resolve_visitor(const FengTypeMember *member,
                                         const FengSemanticModule *fit_module,
                                         const FengDecl *fit_decl,
                                         void *userdata) {
    FitOverloadResolveCtx *st = (FitOverloadResolveCtx *)userdata;

    (void)fit_module;
    if (!fit_member_is_accessible_from(st->context,
                                       st->owner_type_decl,
                                       st->owner_type,
                                       fit_decl,
                                       member)) {
        return true;
    }
    {
        bool rejected_existing_array_for_variadic = false;
        PrepackedVariadicRejection spread_rejection =
            FENG_PREPACKED_VARIADIC_REJECTION_NONE;

        if (!callable_parameters_match_args_for_owner_instance(
                st->context,
                &member->as.callable,
                st->owner_type_decl,
                fit_decl,
                st->owner_type,
                st->args,
                st->arg_count,
                st->explicit_type_args,
                st->explicit_type_arg_count,
                false,
                &rejected_existing_array_for_variadic,
                &spread_rejection)) {
            if (rejected_existing_array_for_variadic) {
                st->result.rejected_existing_array_for_variadic = true;
            }
            merge_prepacked_variadic_rejection(
                &st->result.prepacked_variadic_rejection, spread_rejection);
            return true;
        }
    }
    int priority = compute_overload_match_priority(
        st->has_explicit_type_args,
        st->explicit_type_arg_count,
        member->as.callable.type_param_count,
        callable_parameters_exactly_match_args_for_owner_instance(
            st->context,
            &member->as.callable,
            st->owner_type_decl,
            fit_decl,
            st->owner_type,
            st->args,
            st->arg_count));

    if (st->result.kind == FENG_FUNCTION_CALL_RESOLUTION_NONE ||
        priority < st->result.match_priority) {
        st->result.kind = FENG_FUNCTION_CALL_RESOLUTION_UNIQUE;
        st->result.match_priority = priority;
        st->result.decl = NULL;
        st->result.callable = &member->as.callable;
        st->result.member = member;
        st->result.owner_type_decl = st->owner_type_decl;
        st->result.fit_decl = fit_decl;
        return true;
    }
    if (priority > st->result.match_priority) {
        return true;
    }
    st->result.kind = FENG_FUNCTION_CALL_RESOLUTION_AMBIGUOUS;
    st->result.callable = NULL;
    st->result.member = NULL;
    st->result.owner_type_decl = NULL;
    st->result.fit_decl = NULL;
    return true;
}

static FunctionCallResolution resolve_accessible_method_overload(
    ResolveContext *context,
    const FengDecl *type_decl,
    const FengSemanticModule *provider_module,
    InferredExprType owner_type,
    FengSlice name,
    FengExpr *const *args,
    size_t arg_count,
    bool has_explicit_type_args,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count) {
    size_t member_index;
    FunctionCallResolution result;
    FitOverloadResolveCtx st;

    memset(&result, 0, sizeof(result));
    (void)provider_module;
    if (type_decl == NULL) {
        st.context = context;
        st.owner_type_decl = NULL;
        st.owner_type = owner_type;
        st.args = args;
        st.arg_count = arg_count;
        st.has_explicit_type_args = has_explicit_type_args;
        st.explicit_type_args = explicit_type_args;
        st.explicit_type_arg_count = explicit_type_arg_count;
        st.enforce_static_access = false;
        st.result = result;
        (void)visit_visible_fit_methods_for_owner_type(context,
                                                       NULL,
                                                       owner_type,
                                                       name,
                                                       true,
                                                       false,
                                                       fit_overload_resolve_visitor,
                                                       &st);
        return st.result;
    }

    if (type_decl->kind == FENG_DECL_SPEC &&
        (type_decl->as.spec_decl.form == FENG_SPEC_FORM_OBJECT ||
         type_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION)) {
        return resolve_spec_method_call_overload(
                   context,
                   type_decl,
                   owner_type,
                   name,
                   args,
                   arg_count,
                   false,
                   has_explicit_type_args,
                   explicit_type_args,
                   explicit_type_arg_count)
            .call;
    }

    if (!decl_is_named_fit_target(type_decl)) {
        return result;
    }

    if (type_decl->kind == FENG_DECL_TYPE) {
        for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
            const FengTypeMember *member = type_decl->as.type_decl.members[member_index];

            bool rejected_existing_array_for_variadic = false;
            PrepackedVariadicRejection spread_rejection =
                FENG_PREPACKED_VARIADIC_REJECTION_NONE;

            if (member->is_static ||
                member->kind != FENG_TYPE_MEMBER_METHOD ||
                !slice_equals(member->as.callable.name, name) ||
                !type_member_is_accessible_from(context,
                                                type_decl,
                                                owner_type,
                                                member) ||
                fit_body_blocks_private_access(context, type_decl, member) ||
                !callable_parameters_match_args_for_owner_instance(context,
                                                                   &member->as.callable,
                                                                   type_decl,
                                                                   NULL,
                                                                   owner_type,
                                                                   args,
                                                                   arg_count,
                                                                   explicit_type_args,
                                                                   explicit_type_arg_count,
                                                                   false,
                                                                   &rejected_existing_array_for_variadic,
                                                                   &spread_rejection)) {
                if (rejected_existing_array_for_variadic) {
                    result.rejected_existing_array_for_variadic = true;
                }
                merge_prepacked_variadic_rejection(
                    &result.prepacked_variadic_rejection, spread_rejection);
                continue;
            }

            int priority = compute_overload_match_priority(
                has_explicit_type_args,
                explicit_type_arg_count,
                member->as.callable.type_param_count,
                callable_parameters_exactly_match_args_for_owner_instance(
                    context,
                    &member->as.callable,
                    type_decl,
                    NULL,
                    owner_type,
                    args,
                    arg_count));

            if (result.kind == FENG_FUNCTION_CALL_RESOLUTION_NONE ||
                priority < result.match_priority) {
                result.kind = FENG_FUNCTION_CALL_RESOLUTION_UNIQUE;
                result.match_priority = priority;
                result.decl = NULL;
                result.callable = &member->as.callable;
                result.member = member;
                result.owner_type_decl = type_decl;
                continue;
            }
            if (priority > result.match_priority) {
                continue;
            }

            result.kind = FENG_FUNCTION_CALL_RESOLUTION_AMBIGUOUS;
            result.callable = NULL;
            result.member = NULL;
            result.owner_type_decl = NULL;
        }
    }

    st.context = context;
    st.owner_type_decl = type_decl;
    st.owner_type = owner_type;
    st.args = args;
    st.arg_count = arg_count;
    st.has_explicit_type_args = has_explicit_type_args;
    st.explicit_type_args = explicit_type_args;
    st.explicit_type_arg_count = explicit_type_arg_count;
    st.enforce_static_access = false;
    st.result = result;
    (void)visit_visible_fit_methods_for_type(context, type_decl, name, true, false,
                                             fit_overload_resolve_visitor, &st);
    return st.result;
}

static FunctionCallResolution resolve_accessible_static_method_overload(
    ResolveContext *context,
    const FengDecl *type_decl,
    const FengSemanticModule *provider_module,
    InferredExprType owner_type,
    FengSlice name,
    FengExpr *const *args,
    size_t arg_count,
    bool has_explicit_type_args,
    const FengTypeRef *const *explicit_type_args,
    size_t explicit_type_arg_count) {
    size_t member_index;
    FunctionCallResolution result;
    FitOverloadResolveCtx st;

    memset(&result, 0, sizeof(result));
    (void)provider_module;
    if (type_decl == NULL) {
        st.context = context;
        st.owner_type_decl = NULL;
        st.owner_type = owner_type;
        st.args = args;
        st.arg_count = arg_count;
        st.has_explicit_type_args = has_explicit_type_args;
        st.explicit_type_args = explicit_type_args;
        st.explicit_type_arg_count = explicit_type_arg_count;
        st.enforce_static_access = true;
        st.result = result;
        (void)visit_visible_fit_methods_for_owner_type(context,
                                                       NULL,
                                                       owner_type,
                                                       name,
                                                       true,
                                                       true,
                                                       fit_overload_resolve_visitor,
                                                       &st);
        return st.result;
    }

    if (type_decl->kind != FENG_DECL_TYPE) {
        return result;
    }

    for (member_index = 0U; member_index < type_decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[member_index];
        bool rejected_existing_array_for_variadic = false;
        PrepackedVariadicRejection spread_rejection =
            FENG_PREPACKED_VARIADIC_REJECTION_NONE;

        if (!member->is_static ||
            member->kind != FENG_TYPE_MEMBER_METHOD ||
            !slice_equals(member->as.callable.name, name) ||
            !type_member_is_accessible_from(context,
                                            type_decl,
                                            owner_type,
                                            member) ||
            fit_body_blocks_private_access(context, type_decl, member) ||
            !callable_parameters_match_args_for_owner_instance(context,
                                                               &member->as.callable,
                                                               type_decl,
                                                               NULL,
                                                               owner_type,
                                                               args,
                                                               arg_count,
                                                               explicit_type_args,
                                                               explicit_type_arg_count,
                                                               false,
                                                               &rejected_existing_array_for_variadic,
                                                               &spread_rejection)) {
            if (rejected_existing_array_for_variadic) {
                result.rejected_existing_array_for_variadic = true;
            }
            merge_prepacked_variadic_rejection(
                &result.prepacked_variadic_rejection, spread_rejection);
            continue;
        }

        int priority = compute_overload_match_priority(
            has_explicit_type_args,
            explicit_type_arg_count,
            member->as.callable.type_param_count,
            callable_parameters_exactly_match_args_for_owner_instance(
                context,
                &member->as.callable,
                type_decl,
                NULL,
                owner_type,
                args,
                arg_count));

        if (result.kind == FENG_FUNCTION_CALL_RESOLUTION_NONE ||
            priority < result.match_priority) {
            result.kind = FENG_FUNCTION_CALL_RESOLUTION_UNIQUE;
            result.match_priority = priority;
            result.decl = NULL;
            result.callable = &member->as.callable;
            result.member = member;
            result.owner_type_decl = type_decl;
            result.fit_decl = NULL;
            continue;
        }
        if (priority > result.match_priority) {
            continue;
        }

        result.kind = FENG_FUNCTION_CALL_RESOLUTION_AMBIGUOUS;
        result.callable = NULL;
        result.member = NULL;
        result.owner_type_decl = NULL;
        result.fit_decl = NULL;
    }

    st.context = context;
    st.owner_type_decl = type_decl;
    st.owner_type = owner_type;
    st.args = args;
    st.arg_count = arg_count;
    st.has_explicit_type_args = has_explicit_type_args;
    st.explicit_type_args = explicit_type_args;
    st.explicit_type_arg_count = explicit_type_arg_count;
    st.enforce_static_access = true;
    st.result = result;
    (void)visit_visible_fit_methods_for_type(context, type_decl, name, true, true,
                                             fit_overload_resolve_visitor, &st);
    return st.result;
}

static InferredExprType resolve_expr_owner_type(ResolveContext *context,
                                                const FengExpr *expr,
                                                const FengDecl **out_type_decl,
                                                const FengSemanticModule **out_provider_module) {
    InferredExprType owner_type = infer_expr_type(context, expr);
    const FengDecl *type_decl = resolve_inferred_expr_type_decl(context, owner_type);

    if (out_type_decl != NULL) {
        *out_type_decl = type_decl;
    }
    if (out_provider_module != NULL) {
        *out_provider_module = find_decl_provider_module(context->analysis, type_decl);
    }

    return owner_type;
}

static void record_object_arg_coercion_sites(ResolveContext *context,
                                             FengExpr *const *args,
                                             size_t arg_count,
                                             const FengParameter *params,
                                             size_t param_count,
                                             FengSpecObjectSubjectStorageKind preferred_storage);

static void record_callable_spec_coercion_site(ResolveContext *context,
                                               const FengExpr *expr,
                                               const FengTypeRef *expected_type_ref);

static void record_spec_member_access(ResolveContext *context,
                                      const FengExpr *expr,
                                      const FengDecl *spec_decl,
                                      const FengTypeMember *member);

static void compute_spec_witness_if_absent(ResolveContext *context,
                                           const FengDecl *type_decl,
                                           InferredExprType source_type,
                                           const FengTypeRef *source_type_ref,
                                           const FengDecl *spec_decl,
                                           const FengTypeRef *spec_type_ref,
                                           FengToken err_token);

static bool report_existing_array_rejected_for_variadic_call(ResolveContext *context,
                                                             const FengExpr *callee) {
    char *target_name = format_expr_target_name(callee);
    bool ok = resolver_append_error(
        context,
        callee != NULL ? callee->token : (FengToken){0},
        "AE0505", format_message(
            "call target '%s' does not accept an existing array at a variadic argument position; use explicit '...array' forwarding for the complete variadic group",
            target_name != NULL ? target_name : "<expression>"));

    free(target_name);
    return ok;
}

/* Report the most specific semantic failure for an explicit `...expr`. */
static bool report_prepacked_variadic_rejection(
    ResolveContext *context,
    const FengExpr *callee,
    PrepackedVariadicRejection rejection) {
    const char *message;

    switch (rejection) {
        case FENG_PREPACKED_VARIADIC_REJECTION_TARGET_NOT_VARIADIC:
            message = "prepacked variadic forwarding requires a variadic call target";
            break;
        case FENG_PREPACKED_VARIADIC_REJECTION_NOT_FIRST_VARIADIC:
            message = "prepacked variadic forwarding must begin at the first variadic argument position";
            break;
        case FENG_PREPACKED_VARIADIC_REJECTION_TYPE_MISMATCH:
            message = "prepacked variadic argument must match the target readonly variadic array type";
            break;
        case FENG_PREPACKED_VARIADIC_REJECTION_NONE:
            return true;
    }

    return resolver_append_error(
        context,
        callee != NULL ? callee->token : (FengToken){0},
        "AE0524",
        format_message("%s", message));
}

/* Re-check a selected generic callable after explicit type arguments are
 * known.  Candidate probing infers method/function parameters from actuals;
 * this final check substitutes the caller's explicit arguments and verifies
 * the complete normalized variadic array type without changing ordinary
 * generic-call diagnostics. */
static bool validate_explicit_prepacked_variadic_argument(
    ResolveContext *context,
    const FengExpr *call_expr) {
    const FengResolvedCallable *resolved;
    const FengCallableSignature *callable = NULL;
    const FengTypeRef *expected_type;
    FengTypeRef *substituted_type;
    InferredExprType owner_type;
    size_t spread_index;

    if (context == NULL || call_expr == NULL ||
        call_expr->kind != FENG_EXPR_CALL ||
        !call_expr->as.call.has_explicit_type_args ||
        !find_prepacked_variadic_arg(call_expr->as.call.args,
                                     call_expr->as.call.arg_count,
                                     &spread_index)) {
        return true;
    }

    resolved = &call_expr->as.call.resolved_callable;
    if (resolved->kind == FENG_RESOLVED_CALLABLE_FUNCTION &&
        resolved->function_decl != NULL) {
        callable = &resolved->function_decl->as.function_decl;
    } else if ((resolved->kind == FENG_RESOLVED_CALLABLE_TYPE_METHOD ||
                resolved->kind == FENG_RESOLVED_CALLABLE_FIT_METHOD ||
                resolved->kind == FENG_RESOLVED_CALLABLE_TYPE_STATIC_METHOD ||
                resolved->kind == FENG_RESOLVED_CALLABLE_FIT_STATIC_METHOD ||
                resolved->kind == FENG_RESOLVED_CALLABLE_SPEC_METHOD ||
                resolved->kind == FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD) &&
               resolved->member != NULL) {
        callable = &resolved->member->as.callable;
    }

    if (callable == NULL ||
        callable->type_param_count != call_expr->as.call.explicit_type_arg_count ||
        spread_index >= callable->param_count) {
        return true;
    }

    expected_type = callable->params[spread_index].type;
    memset(&owner_type, 0, sizeof(owner_type));
    if (resolved->owner_instance_type_ref != NULL) {
        owner_type.kind = FENG_INFERRED_EXPR_TYPE_TYPE_REF;
        owner_type.type_ref = resolved->owner_instance_type_ref;
        owner_type.type_decl = resolved->owner_type_decl;
        expected_type = substitute_type_ref_for_owner_instance(
            context, resolved->owner_type_decl, owner_type, expected_type);
        expected_type = substitute_type_ref_for_fit_instance(
            context, resolved->fit_decl, owner_type, expected_type);
    }

    substituted_type = clone_type_ref_substituting_type_params(
        context->program,
        expected_type,
        callable->type_params,
        callable->type_param_count,
        call_expr->as.call.explicit_type_args);
    if (substituted_type == NULL) {
        return resolver_append_error(
            context,
            call_expr->token,
            "IE0001",
            format_message("out of memory while validating prepacked variadic argument"));
    }

    if (!expr_matches_expected_type_ref(
            context, call_expr->as.call.args[spread_index], substituted_type)) {
        free_synthetic_type_ref(substituted_type);
        return report_prepacked_variadic_rejection(
            context,
            call_expr->as.call.callee,
            FENG_PREPACKED_VARIADIC_REJECTION_TYPE_MISMATCH);
    }

    free_synthetic_type_ref(substituted_type);
    return true;
}

static bool validate_callable_typed_expr_call(ResolveContext *context,
                                              const FengExpr *callee,
                                              FengExpr *const *args,
                                              size_t arg_count) {
    InferredExprType callee_type = infer_expr_type(context, callee);
    const FengDecl *callee_type_decl = resolve_inferred_expr_type_decl(context, callee_type);
    const FengTypeRef *callee_constraint_ref =
        resolve_callable_constraint_type_ref(context, callee_type);
    const FengDecl *callee_constraint_decl =
        resolve_function_type_decl(context, callee_constraint_ref);
    char *target_name = NULL;
    bool rejected_existing_array_for_variadic = false;
    PrepackedVariadicRejection spread_rejection =
        FENG_PREPACKED_VARIADIC_REJECTION_NONE;

    if (callee != NULL &&
        (callee->kind == FENG_EXPR_LAMBDA ||
         callee_type.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA)) {
        return report_lambda_requires_callable_spec_target(context,
                                                           callee,
                                                           "a call expression");
    }

    if (callee_type_decl != NULL && decl_is_function_type(callee_type_decl)) {
        if (function_type_parameters_match_args_for_instance(context,
                                                             callee_type_decl,
                                                             callee_type,
                                                             args,
                                                             arg_count,
                                                             &rejected_existing_array_for_variadic,
                                                             &spread_rejection)) {
            if (!validate_borrowed_data_pointer_call_arguments(
                    context,
                    callee,
                    args,
                    arg_count,
                    callee_type_decl->as.spec_decl.as.callable.params,
                    callee_type_decl->as.spec_decl.as.callable.param_count,
                    false)) {
                return false;
            }
            note_callable_value_expr_exception_escape(context, callee);
            record_object_arg_coercion_sites(context, args, arg_count,
                                             callee_type_decl->as.spec_decl.as.callable.params,
                                             callee_type_decl->as.spec_decl.as.callable.param_count,
                                             FENG_SPEC_OBJECT_SUBJECT_STORAGE_BOX_OWNER);
            return validate_function_type_call_block_lambda_arguments(
                context,
                callee_type_decl,
                callee_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF
                    ? callee_type.type_ref
                    : NULL,
                args,
                arg_count);
        }

        if (spread_rejection != FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
            return report_prepacked_variadic_rejection(context, callee, spread_rejection);
        }
        if (rejected_existing_array_for_variadic) {
            return report_existing_array_rejected_for_variadic_call(context, callee);
        }

        target_name = format_expr_target_name(callee);
        if (!resolver_append_error(
                context,
                callee->token,
                "AE0506", format_message("call target '%s' has no function type overload accepting %zu argument(s)",
                               target_name != NULL ? target_name : "<expression>",
                               arg_count))) {
            free(target_name);
            return false;
        }

        free(target_name);
        return true;
    }

    if (callee_constraint_decl != NULL) {
        if (function_type_parameters_match_args(context,
                                                callee_constraint_decl,
                                                args,
                                                arg_count,
                                                &rejected_existing_array_for_variadic,
                                                &spread_rejection)) {
            if (!validate_borrowed_data_pointer_call_arguments(
                    context,
                    callee,
                    args,
                    arg_count,
                    callee_constraint_decl->as.spec_decl.as.callable.params,
                    callee_constraint_decl->as.spec_decl.as.callable.param_count,
                    false)) {
                return false;
            }
            note_callable_value_expr_exception_escape(context, callee);
            record_object_arg_coercion_sites(
                context,
                args,
                arg_count,
                callee_constraint_decl->as.spec_decl.as.callable.params,
                callee_constraint_decl->as.spec_decl.as.callable.param_count,
                FENG_SPEC_OBJECT_SUBJECT_STORAGE_BOX_OWNER);
            return validate_function_type_call_block_lambda_arguments(
                context,
                callee_constraint_decl,
                callee_constraint_ref,
                args,
                arg_count);
        }

        if (spread_rejection != FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
            return report_prepacked_variadic_rejection(context, callee, spread_rejection);
        }
        if (rejected_existing_array_for_variadic) {
            return report_existing_array_rejected_for_variadic_call(context, callee);
        }

        target_name = format_expr_target_name(callee);
        if (!resolver_append_error(
                context,
                callee->token,
                "AE0506", format_message("call target '%s' has no function type overload accepting %zu argument(s)",
                               target_name != NULL ? target_name : "<expression>",
                               arg_count))) {
            free(target_name);
            return false;
        }

        free(target_name);
        return true;
    }

    if (!inferred_expr_type_is_known(callee_type)) {
        return true;
    }

    target_name = format_expr_target_name(callee);
    if (!resolver_append_error(context,
                               callee->token,
                               "AE0507", format_message("expression '%s' is not callable",
                                              target_name != NULL ? target_name : "<expression>"))) {
        free(target_name);
        return false;
    }

    free(target_name);
    return true;
}

/* Walk a block body and unify the inferred return-statement types into a
 * single result. Returns inferred_expr_type_unknown() when the block has no
 * returns (effectively void) or when return types disagree. */

static InferredExprType infer_stmt_return_type(ResolveContext *context, const FengStmt *stmt) {
    InferredExprType current = inferred_expr_type_unknown();

    if (stmt == NULL) {
        return current;
    }

    switch (stmt->kind) {
        case FENG_STMT_RETURN:
            return stmt->as.return_value != NULL
                       ? infer_expr_type(context, stmt->as.return_value)
                       : inferred_expr_type_builtin("void");
        case FENG_STMT_BLOCK:
            return infer_block_return_type(context, stmt->as.block);
        case FENG_STMT_IF: {
            size_t clause_index;
            bool any_known = false;

            for (clause_index = 0U; clause_index < stmt->as.if_stmt.clause_count; ++clause_index) {
                InferredExprType branch =
                    infer_block_return_type(context, stmt->as.if_stmt.clauses[clause_index].block);

                if (inferred_expr_type_is_known(branch)) {
                    if (!any_known) {
                        current = branch;
                        any_known = true;
                    } else if (!inferred_expr_types_equal(context, current, branch)) {
                        return inferred_expr_type_unknown();
                    }
                }
            }
            if (stmt->as.if_stmt.else_block != NULL) {
                InferredExprType branch =
                    infer_block_return_type(context, stmt->as.if_stmt.else_block);

                if (inferred_expr_type_is_known(branch)) {
                    if (!any_known) {
                        current = branch;
                    } else if (!inferred_expr_types_equal(context, current, branch)) {
                        return inferred_expr_type_unknown();
                    }
                }
            }
            return current;
        }
        case FENG_STMT_WHILE:
            return infer_block_return_type(context, stmt->as.while_stmt.body);
        case FENG_STMT_MATCH: {
            size_t branch_index;
            bool any_known = false;

            for (branch_index = 0U; branch_index < stmt->as.match_stmt.branch_count; ++branch_index) {
                InferredExprType branch = infer_block_return_type(
                    context, stmt->as.match_stmt.branches[branch_index].body);

                if (inferred_expr_type_is_known(branch)) {
                    if (!any_known) {
                        current = branch;
                        any_known = true;
                    } else if (!inferred_expr_types_equal(context, current, branch)) {
                        return inferred_expr_type_unknown();
                    }
                }
            }
            if (stmt->as.match_stmt.else_block != NULL) {
                InferredExprType branch =
                    infer_block_return_type(context, stmt->as.match_stmt.else_block);

                if (inferred_expr_type_is_known(branch)) {
                    if (!any_known) {
                        current = branch;
                    } else if (!inferred_expr_types_equal(context, current, branch)) {
                        return inferred_expr_type_unknown();
                    }
                }
            }
            return current;
        }
        case FENG_STMT_FOR:
            return infer_block_return_type(context, stmt->as.for_stmt.body);
        default:
            return current;
    }
}

static InferredExprType infer_block_return_type(ResolveContext *context, const FengBlock *block) {
    size_t index;
    InferredExprType current = inferred_expr_type_unknown();
    bool any_known = false;

    if (block == NULL) {
        return current;
    }

    for (index = 0U; index < block->statement_count; ++index) {
        const FengStmt *stmt = block->statements[index];
        InferredExprType stmt_type;

        if (stmt == NULL) {
            continue;
        }
        /* Bring local bindings into scope so subsequent `return` expressions
         * can resolve identifiers introduced by `let`/`var` statements. */
        if (stmt->kind == FENG_STMT_BINDING) {
            if (stmt->as.binding.is_destructure) {
                InferredExprType initializer_type;
                const FengDecl *tuple_decl = NULL;
                const FengTypeRef *tuple_type_ref = NULL;

                if (stmt->as.binding.initializer != NULL &&
                    stmt->as.binding.initializer->kind == FENG_EXPR_TUPLE_LITERAL) {
                    (void)add_destructure_locals_from_tuple_literal(context,
                                                                    &stmt->as.binding,
                                                                    stmt->as.binding.initializer,
                                                                    true,
                                                                    false);
                    continue;
                }

                initializer_type = infer_expr_type(context, stmt->as.binding.initializer);
                if (initializer_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
                    tuple_type_ref = initializer_type.type_ref;
                    tuple_decl = resolve_tuple_type_ref_decl(context, tuple_type_ref);
                } else if (initializer_type.kind == FENG_INFERRED_EXPR_TYPE_DECL &&
                           decl_is_tuple_type(initializer_type.type_decl)) {
                    tuple_decl = initializer_type.type_decl;
                }
                if (tuple_decl != NULL) {
                    (void)add_destructure_locals_from_tuple_type(context,
                                                                 &stmt->as.binding,
                                                                 tuple_decl,
                                                                 tuple_type_ref,
                                                                 true,
                                                                 false);
                }
                continue;
            }
            InferredExprType binding_type = stmt->as.binding.type != NULL
                                                ? inferred_expr_type_from_type_ref(stmt->as.binding.type)
                                                : infer_expr_type(context, stmt->as.binding.initializer);
            (void)resolver_add_local_typed_name(context,
                                                stmt->as.binding.name,
                                                binding_type,
                                                stmt->as.binding.mutability);
            continue;
        }

        stmt_type = infer_stmt_return_type(context, stmt);
        if (inferred_expr_type_is_known(stmt_type)) {
            if (!any_known) {
                current = stmt_type;
                any_known = true;
            } else if (!inferred_expr_types_equal(context, current, stmt_type)) {
                return inferred_expr_type_unknown();
            }
        }
    }
    return current;
}

static InferredExprType infer_lambda_body_type(ResolveContext *context, const FengExpr *expr) {
    size_t param_index;
    bool ok = true;
    InferredExprType body_type = inferred_expr_type_unknown();

    if (expr == NULL || expr->kind != FENG_EXPR_LAMBDA) {
        return inferred_expr_type_unknown();
    }

    if (!resolver_push_scope(context)) {
        return inferred_expr_type_unknown();
    }

    for (param_index = 0U; param_index < expr->as.lambda.param_count && ok; ++param_index) {
        ok = resolver_add_local_typed_name(context,
                                           expr->as.lambda.params[param_index].name,
                                           inferred_expr_type_from_type_ref(
                                               expr->as.lambda.params[param_index].type),
                                           expr->as.lambda.params[param_index].mutability);
    }
    if (ok) {
        if (expr->as.lambda.is_block_body) {
            body_type = infer_block_return_type(context, expr->as.lambda.body_block);
            if (!inferred_expr_type_is_known(body_type)) {
                /* A block lambda with no return statements yields void. */
                body_type = inferred_expr_type_builtin("void");
            }
        } else {
            body_type = infer_expr_type(context, expr->as.lambda.body);
        }
    }

    resolver_pop_scope(context);
    return ok ? body_type : inferred_expr_type_unknown();
}

/* Build the caller-view owner instance for an explicitly instantiated generic
 * constructor. The resolver owns the returned tree; callers that publish it
 * beyond ResolveContext lifetime must clone it into FengSemanticAnalysis. */
static FengTypeRef *synthesize_constructor_owner_instance_type_ref(
    ResolveContext *context,
    const FengExpr *expr,
    const FengDecl *type_decl) {
    FengTypeRef *instance_ref;
    FengSlice *segments;
    size_t segment_count = 0U;

    if (context == NULL || expr == NULL || expr->kind != FENG_EXPR_CALL ||
        type_decl == NULL || type_decl->kind != FENG_DECL_TYPE ||
        type_decl->as.type_decl.type_param_count == 0U ||
        !expr->as.call.has_explicit_type_args ||
        expr->as.call.explicit_type_arg_count !=
            type_decl->as.type_decl.type_param_count) {
        return NULL;
    }

    segments = expr_path_segments_alloc(expr->as.call.callee, &segment_count);
    if (segments == NULL || segment_count == 0U) {
        free(segments);
        segment_count = 1U;
        segments = (FengSlice *)malloc(sizeof(*segments));
        if (segments == NULL) {
            return NULL;
        }
        segments[0] = type_decl->as.type_decl.name;
    }

    instance_ref = (FengTypeRef *)calloc(1U, sizeof(*instance_ref));
    if (instance_ref == NULL) {
        free(segments);
        return NULL;
    }
    instance_ref->token = expr->token;
    instance_ref->kind = FENG_TYPE_REF_NAMED;
    instance_ref->as.named.segments = segments;
    instance_ref->as.named.segment_count = segment_count;
    instance_ref->as.named.type_arg_count =
        expr->as.call.explicit_type_arg_count;
    instance_ref->as.named.type_args = (FengTypeRef **)calloc(
        expr->as.call.explicit_type_arg_count,
        sizeof(*instance_ref->as.named.type_args));
    if (instance_ref->as.named.type_args == NULL) {
        free_synthetic_type_ref(instance_ref);
        return NULL;
    }
    for (size_t arg_index = 0U;
         arg_index < expr->as.call.explicit_type_arg_count;
         ++arg_index) {
        instance_ref->as.named.type_args[arg_index] =
            clone_type_ref_for_inference(
                expr->as.call.explicit_type_args[arg_index]);
        if (instance_ref->as.named.type_args[arg_index] == NULL) {
            free_synthetic_type_ref(instance_ref);
            return NULL;
        }
    }
    if (!resolver_track_synthetic_type_ref(context, instance_ref)) {
        free_synthetic_type_ref(instance_ref);
        return NULL;
    }
    return instance_ref;
}

static InferredExprType infer_call_expr_type(ResolveContext *context, const FengExpr *expr) {
    const FengExpr *callee;
    ResolvedTypeTarget target;
    InferredExprType callee_type;
    const FengDecl *callee_type_decl;

    if (expr == NULL || expr->kind != FENG_EXPR_CALL) {
        return inferred_expr_type_unknown();
    }

    callee = expr->as.call.callee;
    target = resolve_type_target_expr(context, callee, false);
    {
        size_t wanted_arity = expr->as.call.has_explicit_type_args
                                  ? expr->as.call.explicit_type_arg_count
                                  : 0U;
        ResolvedTypeTarget precise =
            resolve_type_target_expr_exact_arity(context, callee, wanted_arity);

        if (precise.type_decl != NULL) {
            target = precise;
        }
    }

    if (target.type_decl != NULL) {
        FengTypeRef *instance_ref =
            synthesize_constructor_owner_instance_type_ref(
                context, expr, target.type_decl);

        if (instance_ref != NULL) {
            return inferred_expr_type_from_type_ref(instance_ref);
        }
        return inferred_expr_type_from_decl(target.type_decl);
    }
    if (callee == NULL) {
        return inferred_expr_type_unknown();
    }

    if (callee->kind == FENG_EXPR_IDENTIFIER) {
        const FunctionOverloadSetEntry *overload_set =
            find_function_overload_set(context->function_sets,
                                       context->function_set_count,
                                       callee->as.identifier);

        if (overload_set != NULL) {
            FunctionCallResolution resolution =
                resolve_top_level_function_overload(context,
                                                    overload_set,
                                                    expr->as.call.args,
                                                    expr->as.call.arg_count,
                                                    expr->as.call.has_explicit_type_args,
                                                    (const FengTypeRef *const *)expr->as.call.explicit_type_args,
                                                    expr->as.call.explicit_type_arg_count);

            if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE &&
                resolution.callable != NULL) {
                InferredExprType return_type;

                if (resolution.callable->return_type != NULL) {
                    const FengTypeRef *return_type_ref =
                        substitute_callable_return_type_for_call(context,
                                                                 NULL,
                                                                 NULL,
                                                                 inferred_expr_type_unknown(),
                                                                 expr,
                                                                 resolution.callable,
                                                                 resolution.decl != NULL &&
                                                                 resolution.decl->is_extern);

                    return_type = inferred_expr_type_from_return_type_ref(return_type_ref);
                } else {
                    return_type = callable_effective_return_type(context, resolution.callable);
                }

                if (inferred_expr_type_is_known(return_type)) {
                    return return_type;
                }
            }
        }
    }

    if (callee->kind == FENG_EXPR_MEMBER) {
        const FengExpr *object = callee->as.member.object;

        {
            ResolvedTypeTarget static_target = resolve_type_target_expr(context, object, false);

            if (static_target.type_decl != NULL &&
                static_target.type_decl->kind == FENG_DECL_TYPE) {
                InferredExprType owner_type = resolved_type_target_owner_type(&static_target);
                FunctionCallResolution resolution =
                    resolve_accessible_static_method_overload(context,
                                                              static_target.type_decl,
                                                              static_target.provider_module,
                                                              owner_type,
                                                              callee->as.member.member,
                                                              expr->as.call.args,
                                                              expr->as.call.arg_count,
                                                              expr->as.call.has_explicit_type_args,
                                                              (const FengTypeRef *const *)expr->as.call.explicit_type_args,
                                                              expr->as.call.explicit_type_arg_count);

                if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE &&
                    resolution.callable != NULL) {
                    InferredExprType return_type;

                    if (resolution.callable->return_type != NULL) {
                        const FengTypeRef *return_type_ref =
                            substitute_callable_return_type_for_call(context,
                                                                     resolution.owner_type_decl,
                                                                     resolution.fit_decl,
                                                                     owner_type,
                                                                     expr,
                                                                     resolution.callable,
                                                                     false);

                        return_type = inferred_expr_type_from_return_type_ref(return_type_ref);
                    } else {
                        return_type = callable_effective_return_type(context, resolution.callable);
                    }

                    if (inferred_expr_type_is_known(return_type)) {
                        return return_type;
                    }
                }
            } else if (static_target.is_builtin_type_name) {
                InferredExprType owner_type = inferred_expr_type_builtin(
                    static_target.builtin_name.data != NULL ? static_target.builtin_name.data : "");
                FunctionCallResolution resolution =
                    resolve_accessible_static_method_overload(context,
                                                              NULL,
                                                              NULL,
                                                              owner_type,
                                                              callee->as.member.member,
                                                              expr->as.call.args,
                                                              expr->as.call.arg_count,
                                                              expr->as.call.has_explicit_type_args,
                                                              (const FengTypeRef *const *)expr->as.call.explicit_type_args,
                                                              expr->as.call.explicit_type_arg_count);

                if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE &&
                    resolution.callable != NULL) {
                    InferredExprType return_type;

                    if (resolution.callable->return_type != NULL) {
                        const FengTypeRef *return_type_ref =
                            substitute_callable_return_type_for_call(context,
                                                                     NULL,
                                                                     resolution.fit_decl,
                                                                     owner_type,
                                                                     expr,
                                                                     resolution.callable,
                                                                     false);

                        return_type = inferred_expr_type_from_return_type_ref(return_type_ref);
                    } else {
                        return_type = callable_effective_return_type(context, resolution.callable);
                    }

                    if (inferred_expr_type_is_known(return_type)) {
                        return return_type;
                    }
                }
            } else if (static_target.is_generic_type_param &&
                       static_target.constraint_spec_decl != NULL) {
                /* G4 / IC01: close the return type through the same exact
                 * requirement selected by call validation. Before that
                 * sidecar exists, use the same overload resolver as a pure
                 * inference probe rather than falling back to the first
                 * same-name object-spec member. */
                const FengResolvedCallable *recorded =
                    &expr->as.call.resolved_callable;
                SpecMethodCallResolution spec_result =
                    resolve_spec_method_call_overload(
                        context,
                        static_target.constraint_spec_decl,
                        static_target.constraint_spec_type_ref != NULL
                            ? inferred_expr_type_from_type_ref(
                                  static_target.constraint_spec_type_ref)
                            : inferred_expr_type_from_decl(
                                  static_target.constraint_spec_decl),
                        callee->as.member.member,
                        expr->as.call.args,
                        expr->as.call.arg_count,
                        true,
                        expr->as.call.has_explicit_type_args,
                        (const FengTypeRef *const *)
                            expr->as.call.explicit_type_args,
                        expr->as.call.explicit_type_arg_count);
                const FengCallableSignature *spec_sig =
                    spec_result.call.callable;
                const FengDecl *declaring_spec =
                    spec_result.call.owner_type_decl;
                const FengTypeRef *declaring_spec_instance =
                    spec_result.call.owner_instance_type_ref;

                if (recorded->kind ==
                        FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD &&
                    recorded->member != NULL &&
                    recorded->owner_type_decl != NULL) {
                    spec_sig = &recorded->member->as.callable;
                    declaring_spec = recorded->owner_type_decl;
                    declaring_spec_instance =
                        recorded->owner_instance_type_ref;
                }
                if (spec_sig != NULL && declaring_spec != NULL) {
                    InferredExprType return_type = inferred_expr_type_unknown();

                    if (spec_sig->return_type != NULL) {
                        InferredExprType declaring_owner =
                            declaring_spec_instance != NULL
                                ? inferred_expr_type_from_type_ref(
                                      declaring_spec_instance)
                                : inferred_expr_type_from_decl(declaring_spec);
                        const FengTypeRef *closed_return =
                            substitute_callable_return_type_for_call(
                                context,
                                declaring_spec,
                                NULL,
                                declaring_owner,
                                expr,
                                spec_sig,
                                false);

                        if (closed_return != NULL) {
                            return_type =
                                inferred_expr_type_from_type_ref(closed_return);
                        }
                    }
                    if (inferred_expr_type_is_known(return_type)) {
                        return return_type;
                    }
                }
            }
        }

        {
            ResolvedModuleMemberTarget module_target;

            if (resolve_module_member_target(
                    context, callee, &module_target)) {
                FunctionCallResolution resolution =
                    resolve_module_public_function_overload(
                        context,
                        module_target.module,
                        module_target.member_name,
                        expr->as.call.args,
                        expr->as.call.arg_count,
                        expr->as.call.has_explicit_type_args,
                        (const FengTypeRef *const *)
                            expr->as.call.explicit_type_args,
                        expr->as.call.explicit_type_arg_count);

                if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE &&
                    resolution.callable != NULL) {
                    InferredExprType return_type;

                    if (resolution.callable->return_type != NULL) {
                        const FengTypeRef *return_type_ref =
                            substitute_callable_return_type_for_call(
                                context,
                                NULL,
                                NULL,
                                inferred_expr_type_unknown(),
                                expr,
                                resolution.callable,
                                resolution.decl != NULL &&
                                    resolution.decl->is_extern);

                        return_type =
                            inferred_expr_type_from_return_type_ref(
                                return_type_ref);
                    } else {
                        return_type = callable_effective_return_type(
                            context, resolution.callable);
                    }

                    if (inferred_expr_type_is_known(return_type)) {
                        return return_type;
                    }
                }
            }
        }

        {
            const FengDecl *owner_type_decl = NULL;
            const FengSemanticModule *provider_module = NULL;
            InferredExprType owner_type;
            FunctionCallResolution resolution;

            owner_type = resolve_expr_owner_type(context, object, &owner_type_decl, &provider_module);
            resolution = resolve_accessible_method_overload(context,
                                                            owner_type_decl,
                                                            provider_module,
                                                            owner_type,
                                                            callee->as.member.member,
                                                            expr->as.call.args,
                                                            expr->as.call.arg_count,
                                                            expr->as.call.has_explicit_type_args,
                                                            (const FengTypeRef *const *)expr->as.call.explicit_type_args,
                                                            expr->as.call.explicit_type_arg_count);
            if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE &&
                resolution.callable != NULL) {
                InferredExprType return_type;

                if (resolution.callable->return_type != NULL) {
                    InferredExprType callable_owner_type =
                        resolution.owner_instance_type_ref != NULL
                            ? inferred_expr_type_from_type_ref(
                                  resolution.owner_instance_type_ref)
                            : owner_type;
                    const FengTypeRef *return_type_ref =
                        substitute_callable_return_type_for_call(context,
                                                                 resolution.owner_type_decl != NULL
                                                                     ? resolution.owner_type_decl
                                                                     : owner_type_decl,
                                                                 resolution.fit_decl,
                                                                 callable_owner_type,
                                                                 expr,
                                                                 resolution.callable,
                                                                 false);

                    return_type = inferred_expr_type_from_return_type_ref(return_type_ref);
                } else {
                    return_type = callable_effective_return_type(context, resolution.callable);
                }

                if (inferred_expr_type_is_known(return_type)) {
                    return return_type;
                }
            }

            /* G4: inference for v.method() where v: T must perform the same
             * argument-based overload selection as validation. A name-only
             * surface lookup would always expose the first overload and give
             * later bool/string calls the wrong return type. */
            if (resolution.kind != FENG_FUNCTION_CALL_RESOLUTION_UNIQUE &&
                owner_type_decl == NULL) {
                const FengDecl *constraint_decl = NULL;
                const FengTypeRef *constraint_ref = NULL;

                if (resolve_generic_param_spec_constraint(
                        context,
                        owner_type,
                        &constraint_decl,
                        &constraint_ref) &&
                    (constraint_decl->as.spec_decl.form ==
                         FENG_SPEC_FORM_OBJECT ||
                     constraint_decl->as.spec_decl.form ==
                         FENG_SPEC_FORM_INTERSECTION)) {
                    InferredExprType constraint_owner =
                        inferred_expr_type_from_type_ref(constraint_ref);
                    FunctionCallResolution constrained =
                        resolve_accessible_method_overload(
                            context,
                            constraint_decl,
                            find_decl_provider_module(
                                context->analysis, constraint_decl),
                            constraint_owner,
                            callee->as.member.member,
                            expr->as.call.args,
                            expr->as.call.arg_count,
                            expr->as.call.has_explicit_type_args,
                            (const FengTypeRef *const *)
                                expr->as.call.explicit_type_args,
                            expr->as.call.explicit_type_arg_count);

                    if (constrained.kind ==
                            FENG_FUNCTION_CALL_RESOLUTION_UNIQUE &&
                        constrained.callable != NULL &&
                        constrained.callable->return_type != NULL) {
                        InferredExprType declaring_owner =
                            constrained.owner_instance_type_ref != NULL
                                ? inferred_expr_type_from_type_ref(
                                      constrained.owner_instance_type_ref)
                                : constraint_owner;
                        const FengTypeRef *closed_return =
                            substitute_callable_return_type_for_call(
                                context,
                                constrained.owner_type_decl,
                                NULL,
                                declaring_owner,
                                expr,
                                constrained.callable,
                                false);

                        if (closed_return != NULL) {
                            return inferred_expr_type_from_type_ref(
                                closed_return);
                        }
                    }
                }
            }
        }
    }

    callee_type = infer_expr_type(context, callee);
    callee_type_decl = resolve_inferred_expr_type_decl(context, callee_type);
    if (callee_type_decl != NULL &&
        function_type_parameters_match_args_for_instance(context,
                                                         callee_type_decl,
                                                         callee_type,
                                                         expr->as.call.args,
                                                         expr->as.call.arg_count,
                                                         NULL,
                                                         NULL)) {
        return inferred_expr_type_from_return_type_ref(
            substitute_type_ref_for_owner_instance(
                context,
                callee_type_decl,
                callee_type,
                callee_type_decl->as.spec_decl.as.callable.return_type));
    }

    callee_type_decl = resolve_callable_constraint_type_decl(context, callee_type);
    if (callee_type_decl != NULL &&
        function_type_parameters_match_args(context,
                                            callee_type_decl,
                                            expr->as.call.args,
                                            expr->as.call.arg_count,
                                            NULL,
                                            NULL)) {
        return inferred_expr_type_from_return_type_ref(
            callee_type_decl->as.spec_decl.as.callable.return_type);
    }

    return inferred_expr_type_unknown();
}

static bool callable_return_inference_is_pending(ResolveContext *context,
                                                 const FengCallableSignature *callable) {
    return callable != NULL && callable->return_type == NULL &&
           !inferred_expr_type_is_known(callable_effective_return_type(context, callable));
}

static bool expr_type_inference_is_pending(ResolveContext *context, const FengExpr *expr) {
    size_t index;

    if (expr == NULL) {
        return false;
    }

    switch (expr->kind) {
        case FENG_EXPR_CALL: {
            const FengExpr *callee = expr->as.call.callee;

            if (callee == NULL) {
                return false;
            }

            if (callee->kind == FENG_EXPR_IDENTIFIER) {
                const FunctionOverloadSetEntry *overload_set =
                    find_function_overload_set(context->function_sets,
                                               context->function_set_count,
                                               callee->as.identifier);

                if (overload_set != NULL) {
                    FunctionCallResolution resolution =
                        resolve_top_level_function_overload(context,
                                                            overload_set,
                                                            expr->as.call.args,
                                                            expr->as.call.arg_count,
                                                            expr->as.call.has_explicit_type_args,
                                                            (const FengTypeRef *const *)expr->as.call.explicit_type_args,
                                                            expr->as.call.explicit_type_arg_count);

                    if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE &&
                        callable_return_inference_is_pending(context, resolution.callable)) {
                        return true;
                    }
                }
            }

            if (callee->kind == FENG_EXPR_MEMBER) {
                const FengExpr *object = callee->as.member.object;
                ResolvedModuleMemberTarget module_target;

                if (resolve_module_member_target(
                        context, callee, &module_target)) {
                    FunctionCallResolution resolution =
                        resolve_module_public_function_overload(
                            context,
                            module_target.module,
                            module_target.member_name,
                            expr->as.call.args,
                            expr->as.call.arg_count,
                            expr->as.call.has_explicit_type_args,
                            (const FengTypeRef *const *)
                                expr->as.call.explicit_type_args,
                            expr->as.call.explicit_type_arg_count);

                    if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE &&
                        callable_return_inference_is_pending(
                            context, resolution.callable)) {
                        return true;
                    }
                }

                {
                    const FengDecl *owner_type_decl = NULL;
                    const FengSemanticModule *provider_module = NULL;
                    InferredExprType owner_type;
                    FunctionCallResolution resolution;

                    owner_type = resolve_expr_owner_type(context, object, &owner_type_decl, &provider_module);
                    resolution = resolve_accessible_method_overload(context,
                                                                    owner_type_decl,
                                                                    provider_module,
                                                                    owner_type,
                                                                    callee->as.member.member,
                                                                    expr->as.call.args,
                                                                    expr->as.call.arg_count,
                                                                    expr->as.call.has_explicit_type_args,
                                                                    (const FengTypeRef *const *)expr->as.call.explicit_type_args,
                                                                    expr->as.call.explicit_type_arg_count);
                    if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE &&
                        callable_return_inference_is_pending(context, resolution.callable)) {
                        return true;
                    }
                }
            }

            if (callee->kind == FENG_EXPR_LAMBDA) {
                return expr_type_inference_is_pending(context, callee->as.lambda.body);
            }

            return expr_type_inference_is_pending(context, callee);
        }

        case FENG_EXPR_ARRAY_LITERAL:
            for (index = 0U; index < expr->as.array_literal.count; ++index) {
                if (expr_type_inference_is_pending(context, expr->as.array_literal.items[index])) {
                    return true;
                }
            }
            return false;

        case FENG_EXPR_TUPLE_LITERAL:
            for (index = 0U; index < expr->as.tuple_literal.count; ++index) {
                if (expr_type_inference_is_pending(context, expr->as.tuple_literal.items[index])) {
                    return true;
                }
            }
            return false;

        case FENG_EXPR_ARRAY_NEW:
            return expr_type_inference_is_pending(context, expr->as.array_new.size);

        case FENG_EXPR_OBJECT_LITERAL:
            if (expr_type_inference_is_pending(context, expr->as.object_literal.target)) {
                return true;
            }
            for (index = 0U; index < expr->as.object_literal.field_count; ++index) {
                if (expr_type_inference_is_pending(context,
                                                   expr->as.object_literal.fields[index].value)) {
                    return true;
                }
            }
            return false;

        case FENG_EXPR_GENERIC_TARGET:
            return expr_type_inference_is_pending(context, expr->as.generic_target.target);

        case FENG_EXPR_MEMBER:
            return expr_type_inference_is_pending(context, expr->as.member.object);

        case FENG_EXPR_INDEX:
            return expr_type_inference_is_pending(context, expr->as.index.object) ||
                   expr_type_inference_is_pending(context, expr->as.index.index);

        case FENG_EXPR_UNARY:
            return expr_type_inference_is_pending(context, expr->as.unary.operand);

        case FENG_EXPR_BINARY:
            return expr_type_inference_is_pending(context, expr->as.binary.left) ||
                   expr_type_inference_is_pending(context, expr->as.binary.right);

        case FENG_EXPR_LAMBDA:
            return expr->as.lambda.is_block_body
                       ? false /* block body return inference uses synthetic signature path */
                       : expr_type_inference_is_pending(context, expr->as.lambda.body);

        case FENG_EXPR_CAST:
            return expr_type_inference_is_pending(context, expr->as.cast.value);

        case FENG_EXPR_IF: {
            const FengExpr *then_yield = block_yield_expression(expr->as.if_expr.then_block);
            const FengExpr *else_yield = block_yield_expression(expr->as.if_expr.else_block);

            return expr_type_inference_is_pending(context, expr->as.if_expr.condition) ||
                   (then_yield != NULL && expr_type_inference_is_pending(context, then_yield)) ||
                   (else_yield != NULL && expr_type_inference_is_pending(context, else_yield));
        }

        case FENG_EXPR_MATCH: {
            const FengExpr *else_yield = block_yield_expression(expr->as.match_expr.else_block);

            if (expr_type_inference_is_pending(context, expr->as.match_expr.target) ||
                (else_yield != NULL && expr_type_inference_is_pending(context, else_yield))) {
                return true;
            }
            for (index = 0U; index < expr->as.match_expr.branch_count; ++index) {
                const FengExpr *branch_yield =
                    block_yield_expression(expr->as.match_expr.branches[index].body);

                if (branch_yield != NULL &&
                    expr_type_inference_is_pending(context, branch_yield)) {
                    return true;
                }
            }
            return false;
        }

        case FENG_EXPR_TRY:
            if (expr_type_inference_is_pending(context, expr->as.try_expr.body)) {
                return true;
            }
            for (index = 0U; index < expr->as.try_expr.clause_count; ++index) {
                const FengExpr *clause_yield =
                    block_yield_expression(expr->as.try_expr.clauses[index].body);

                if (clause_yield != NULL && expr_type_inference_is_pending(context, clause_yield)) {
                    return true;
                }
            }
            return false;

        case FENG_EXPR_MATCH_OP:
            /* infix match operator always yields bool; no pending inference. */
            return false;

        case FENG_EXPR_IDENTIFIER:
        case FENG_EXPR_SELF:
        case FENG_EXPR_BOOL:
        case FENG_EXPR_INTEGER:
        case FENG_EXPR_FLOAT:
        case FENG_EXPR_STRING:
            return false;
    }

    return false;
}

static bool validate_instance_member_expr(ResolveContext *context, const FengExpr *expr) {
    const FengDecl *owner_type_decl = NULL;
    const FengSemanticModule *provider_module = NULL;
    const FengTypeMember *member;
    InferredExprType owner_type;
    const char *builtin_name;

    {
        ResolvedTypeTarget type_target = resolve_type_target_expr(context, expr->as.member.object, false);

        if (type_target.is_generic_type_param &&
            type_target.constraint_spec_decl != NULL) {
            const FengDecl *declaring_spec = NULL;
            InferredExprType constraint_owner =
                type_target.constraint_spec_type_ref != NULL
                    ? inferred_expr_type_from_type_ref(
                          type_target.constraint_spec_type_ref)
                    : inferred_expr_type_from_decl(
                          type_target.constraint_spec_decl);
            SpecMethodAccessProbe method_probe = probe_spec_method_access(
                context,
                type_target.constraint_spec_decl,
                constraint_owner,
                expr->as.member.member,
                true);
            const FengTypeMember *accessible_field =
                find_accessible_spec_object_field(
                    context,
                    type_target.constraint_spec_decl,
                    constraint_owner,
                    expr->as.member.member,
                    /*require_static=*/true,
                    &declaring_spec);

            if (method_probe.has_accessible_method) {
                return true;
            }
            if (accessible_field != NULL) {
                if (!record_selected_friend_fit_access(
                        context,
                        type_target.constraint_spec_decl,
                        constraint_owner,
                        accessible_field)) {
                    return false;
                }
                record_spec_member_access(context,
                                          expr,
                                          type_target.constraint_spec_decl,
                                          accessible_field);
                return true;
            }
            if (method_probe.inaccessible_member != NULL) {
                return report_inaccessible_spec_member(
                    context,
                    expr->token,
                    method_probe.inaccessible_declaring_spec,
                    method_probe.inaccessible_member);
            }
            {
                const FengTypeMember *existing_field =
                    find_spec_object_field_with_owner(
                        context,
                        type_target.constraint_spec_decl,
                        expr->as.member.member,
                        /*require_static=*/true,
                        &declaring_spec);

                if (existing_field != NULL &&
                    existing_field->visibility == FENG_VISIBILITY_PRIVATE) {
                    return report_inaccessible_spec_member(context,
                                                           expr->token,
                                                           declaring_spec,
                                                           existing_field);
                }
            }
        }

        if (type_target.type_decl != NULL && type_target.type_decl->kind == FENG_DECL_TYPE) {
            const FengTypeMember *static_member =
                find_type_static_member(type_target.type_decl, expr->as.member.member);
            const FengTypeMember *accessible_static_member =
                find_accessible_type_static_member(context,
                                                   type_target.type_decl,
                                                   resolved_type_target_owner_type(
                                                       &type_target),
                                                   expr->as.member.member);

            if (accessible_static_member != NULL) {
                if (accessible_static_member->kind == FENG_TYPE_MEMBER_FIELD &&
                    !record_selected_friend_fit_access(
                        context,
                        type_target.type_decl,
                        resolved_type_target_owner_type(&type_target),
                        accessible_static_member)) {
                    return false;
                }
                return true;
            }
            if (find_fit_static_method_member_for_type(
                    context,
                    type_target.type_decl,
                    expr->as.member.member) != NULL) {
                return true;
            }
            if (static_member != NULL) {
                return resolver_append_error(
                    context,
                    expr->token,
                    "AE0305", format_message("static member '%.*s' of type '%.*s' is not accessible from the current type scope",
                                   static_member->kind == FENG_TYPE_MEMBER_FIELD
                                       ? (int)static_member->as.field.name.length
                                       : (int)static_member->as.callable.name.length,
                                   static_member->kind == FENG_TYPE_MEMBER_FIELD
                                       ? static_member->as.field.name.data
                                       : static_member->as.callable.name.data,
                                   (int)type_target.type_decl->as.type_decl.name.length,
                                   type_target.type_decl->as.type_decl.name.data));
            }
            return resolver_append_error(
                context,
                expr->token,
                "AE0309", format_message("type '%.*s' has no static member '%.*s'",
                               (int)type_target.type_decl->as.type_decl.name.length,
                               type_target.type_decl->as.type_decl.name.data,
                               (int)expr->as.member.member.length,
                               expr->as.member.member.data));
        }

        if (decl_is_enum_type(type_target.type_decl)) {
            if (!ensure_enum_decl_info(context, type_target.type_decl)) {
                return false;
            }
            if (feng_semantic_find_enum_item_info(context->analysis,
                                                  type_target.type_decl,
                                                  expr->as.member.member) != NULL) {
                return true;
            }
            if (find_fit_static_method_member_for_type(context,
                                                       type_target.type_decl,
                                                       expr->as.member.member) != NULL) {
                return true;
            }
            return resolver_append_error(
                context,
                expr->token,
                "AE0404", format_message("enum '%.*s' has no item '%.*s'",
                               (int)type_target.type_decl->as.enum_decl.name.length,
                               type_target.type_decl->as.enum_decl.name.data,
                               (int)expr->as.member.member.length,
                               expr->as.member.member.data));
        }

        if (type_target.is_builtin_type_name) {
            InferredExprType target_type = inferred_expr_type_builtin(
                type_target.builtin_name.data != NULL ? type_target.builtin_name.data : "");

            if (find_fit_static_method_member_for_owner_type(context,
                                                             NULL,
                                                             target_type,
                                                             expr->as.member.member) != NULL) {
                return true;
            }
            return resolver_append_error(
                context,
                expr->token,
                "AE0309", format_message("type '%.*s' has no static member '%.*s'",
                               (int)type_target.builtin_name.length,
                               type_target.builtin_name.data,
                               (int)expr->as.member.member.length,
                               expr->as.member.member.data));
        }
    }

    owner_type = resolve_expr_owner_type(context,
                                         expr->as.member.object,
                                         &owner_type_decl,
                                         &provider_module);
    if (!inferred_expr_type_is_known(owner_type)) {
        return true;
    }

    if (owner_type_decl == NULL) {
        char *owner_name = NULL;

        if (find_fit_method_member_for_owner_type(context,
                                                  NULL,
                                                  owner_type,
                                                  expr->as.member.member) != NULL) {
            return true;
        }

        if (find_fit_static_method_member_for_owner_type(context,
                                                         NULL,
                                                         owner_type,
                                                         expr->as.member.member) != NULL) {
            return resolver_append_error(
                context,
                expr->token,
                "AE0310", format_message("static member '%.*s' must be accessed through its type",
                               (int)expr->as.member.member.length,
                               expr->as.member.member.data));
        }

        builtin_name = inferred_expr_type_builtin_canonical_name(owner_type, context->pointer_size);
        if (builtin_name == NULL) {
            if (owner_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
                owner_type.type_ref != NULL &&
                owner_type.type_ref->kind == FENG_TYPE_REF_NAMED &&
                owner_type.type_ref->as.named.segment_count == 1U &&
                owner_type.type_ref->as.named.type_arg_count == 0U &&
                find_type_param(context, owner_type.type_ref->as.named.segments[0]) != NULL) {
                if (resolve_union_spec_type_ref_decl(context, owner_type.type_ref) != NULL) {
                    return resolver_append_error(
                        context,
                        expr->token,
                        "AE0604", format_message("union-form constrained value must be narrowed to a single member before accessing member '%.*s'",
                                       (int)expr->as.member.member.length,
                                       expr->as.member.member.data));
                }
                return true;
            }
            owner_name = format_inferred_expr_type_name(owner_type, context->pointer_size);
            if (owner_name == NULL) {
                return true;
            }
            {
                bool ok = resolver_append_error(
                    context,
                    expr->token,
                    "AE0306", format_message("type '%s' has no member '%.*s'",
                                   owner_name,
                                   (int)expr->as.member.member.length,
                                   expr->as.member.member.data));

                free(owner_name);
                return ok;
            }
        }

        return resolver_append_error(
            context,
            expr->token,
            "AE0306", format_message("type '%s' has no member '%.*s'",
                           builtin_name,
                           (int)expr->as.member.member.length,
                           expr->as.member.member.data));
    }

    if (owner_type_decl->kind == FENG_DECL_SPEC) {
        FengSlice owner_name = decl_typeish_name(owner_type_decl);

        if (owner_type_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            if (owner_type_decl->as.spec_decl.form == FENG_SPEC_FORM_UNION) {
                return resolver_append_error(
                    context,
                    expr->token,
                    "AE0604", format_message("union-form spec '%.*s' must be narrowed to a single member before accessing member '%.*s'",
                                   (int)owner_name.length,
                                   owner_name.data,
                                   (int)expr->as.member.member.length,
                                   expr->as.member.member.data));
            }
            if (owner_type_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
                /* Intersection-form spec values expose the merged method set
                 * of all flattened member specs. Look up the member through
                 * each flattened member's object-spec closure. */
                const FengIntersectionSpecInfo *info =
                    feng_semantic_lookup_intersection_spec_info(context->analysis,
                                                                owner_type_decl);
                if (info != NULL) {
                    const FengTypeMember *inaccessible_member = NULL;
                    const FengDecl *inaccessible_declaring_spec = NULL;

                    for (size_t i = 0U; i < info->flattened_member_count; ++i) {
                        const FengDecl *member_decl = info->flattened_members[i];
                        const FengDecl *declaring_spec = NULL;
                        const FengTypeMember *member_i =
                            find_accessible_spec_object_member(
                                context,
                                member_decl,
                                owner_type,
                                expr->as.member.member,
                                /*include_static=*/false,
                                &declaring_spec);
                        if (member_i != NULL) {
                            if (member_i->kind == FENG_TYPE_MEMBER_FIELD &&
                                !record_selected_friend_fit_access(
                                    context,
                                    member_decl,
                                    owner_type,
                                    member_i)) {
                                return false;
                            }
                            record_spec_member_access(context, expr,
                                                      owner_type_decl, member_i);
                            return true;
                        }
                        if (inaccessible_member == NULL) {
                            inaccessible_member =
                                find_spec_object_member_with_owner(
                                    context,
                                    member_decl,
                                    expr->as.member.member,
                                    /*include_static=*/false,
                                    &inaccessible_declaring_spec);
                        }
                    }
                    if (inaccessible_member != NULL &&
                        inaccessible_member->visibility == FENG_VISIBILITY_PRIVATE) {
                        return report_inaccessible_spec_member(
                            context,
                            expr->token,
                            inaccessible_declaring_spec,
                            inaccessible_member);
                    }
                }
                return resolver_append_error(
                    context,
                    expr->token,
                    "AE1008", format_message("spec '%.*s' has no member '%.*s'",
                                   (int)owner_name.length,
                                   owner_name.data,
                                   (int)expr->as.member.member.length,
                                   expr->as.member.member.data));
            }
            return resolver_append_error(
                context,
                expr->token,
                "AE1008", format_message("spec '%.*s' is callable-form and has no member '%.*s'",
                               (int)owner_name.length,
                               owner_name.data,
                               (int)expr->as.member.member.length,
                               expr->as.member.member.data));
        }

        {
            const FengDecl *declaring_spec = NULL;

            member = find_accessible_spec_object_member(
                context,
                owner_type_decl,
                owner_type,
                expr->as.member.member,
                /*include_static=*/false,
                &declaring_spec);
            if (member != NULL) {
                if (member->kind == FENG_TYPE_MEMBER_FIELD &&
                    !record_selected_friend_fit_access(context,
                                                       owner_type_decl,
                                                       owner_type,
                                                       member)) {
                    return false;
                }
                record_spec_member_access(context, expr, owner_type_decl, member);
                return true;
            }
            member = find_spec_object_member_with_owner(
                context,
                owner_type_decl,
                expr->as.member.member,
                /*include_static=*/false,
                &declaring_spec);
            if (member != NULL &&
                member->visibility == FENG_VISIBILITY_PRIVATE) {
                return report_inaccessible_spec_member(context,
                                                       expr->token,
                                                       declaring_spec,
                                                       member);
            }
        }
        return resolver_append_error(
            context,
            expr->token,
            "AE1008", format_message("spec '%.*s' has no member '%.*s'",
                           (int)owner_name.length,
                           owner_name.data,
                           (int)expr->as.member.member.length,
                           expr->as.member.member.data));
    }

    if (owner_type_decl->kind != FENG_DECL_TYPE) {
        if (owner_type_decl->kind == FENG_DECL_ENUM) {
            const FengTypeMember *fit_member =
                find_fit_method_member_for_type(context, owner_type_decl, expr->as.member.member);

            if (fit_member != NULL) {
                return true;
            }
            if (find_fit_static_method_member_for_type(context,
                                                       owner_type_decl,
                                                       expr->as.member.member) != NULL) {
                return resolver_append_error(
                    context,
                    expr->token,
                    "AE0310", format_message("static member '%.*s' must be accessed through its type",
                                   (int)expr->as.member.member.length,
                                   expr->as.member.member.data));
            }
        }
        {
            FengSlice owner_name = decl_typeish_name(owner_type_decl);
            return resolver_append_error(
                context,
                expr->token,
                "AE0306", format_message("type '%.*s' has no member '%.*s'",
                               (int)owner_name.length,
                               owner_name.data,
                               (int)expr->as.member.member.length,
                               expr->as.member.member.data));
        }
    }

    member = find_instance_member(owner_type_decl, expr->as.member.member);
    {
        const FengTypeMember *accessible_member =
            find_accessible_type_instance_member(context,
                                                 owner_type_decl,
                                                 provider_module,
                                                 owner_type,
                                                 expr->as.member.member);

        if (accessible_member != NULL) {
            if (accessible_member->kind == FENG_TYPE_MEMBER_FIELD &&
                !record_selected_friend_fit_access(context,
                                                   owner_type_decl,
                                                   owner_type,
                                                   accessible_member)) {
                return false;
            }
            return true;
        }
    }
    if (member == NULL) {
        if (find_type_static_member(owner_type_decl, expr->as.member.member) != NULL ||
            find_fit_static_method_member_for_type(context,
                                                   owner_type_decl,
                                                   expr->as.member.member) != NULL) {
            return resolver_append_error(
                context,
                expr->token,
                "AE0310", format_message("static member '%.*s' must be accessed through its type",
                               (int)expr->as.member.member.length,
                               expr->as.member.member.data));
        }
        return resolver_append_error(
            context,
            expr->token,
            "AE0306", format_message("type '%.*s' has no member '%.*s'",
                           (int)owner_type_decl->as.type_decl.name.length,
                           owner_type_decl->as.type_decl.name.data,
                           (int)expr->as.member.member.length,
                           expr->as.member.member.data));
    }

    if (fit_body_blocks_private_access(context, owner_type_decl, member)) {
        return resolver_append_error(
            context,
            expr->token,
            "AE0307", format_message("fit body cannot access private member '%.*s' of target type '%.*s'",
                           member->kind == FENG_TYPE_MEMBER_FIELD ? (int)member->as.field.name.length
                                                                  : (int)member->as.callable.name.length,
                           member->kind == FENG_TYPE_MEMBER_FIELD ? member->as.field.name.data
                                                                  : member->as.callable.name.data,
                           (int)owner_type_decl->as.type_decl.name.length,
                           owner_type_decl->as.type_decl.name.data));
    }

    return resolver_append_error(
        context,
        expr->token,
        "AE0308", format_message("member '%.*s' of type '%.*s' is not accessible from the current type scope",
                       member->kind == FENG_TYPE_MEMBER_FIELD ? (int)member->as.field.name.length
                                                              : (int)member->as.callable.name.length,
                       member->kind == FENG_TYPE_MEMBER_FIELD ? member->as.field.name.data
                                                              : member->as.callable.name.data,
                       (int)owner_type_decl->as.type_decl.name.length,
                       owner_type_decl->as.type_decl.name.data));
}

static bool append_unique_slice(FengSlice **items, size_t *count, size_t *capacity, FengSlice value) {
    if (find_slice_index(*items, *count, value) < *count) {
        return true;
    }

    return append_slice(items, count, capacity, value);
}

static void resolver_clear_current_constructor_bindings(ResolveContext *context) {
    free(context->current_constructor_bound_names);
    context->current_constructor_bound_names = NULL;
    context->current_constructor_bound_count = 0U;
    context->current_constructor_bound_capacity = 0U;
}

static bool resolver_current_constructor_has_bound_name(const ResolveContext *context, FengSlice name) {
    return find_slice_index(context->current_constructor_bound_names,
                            context->current_constructor_bound_count,
                            name) < context->current_constructor_bound_count;
}

static bool resolver_current_constructor_add_bound_name(ResolveContext *context, FengSlice name) {
    return append_unique_slice(&context->current_constructor_bound_names,
                               &context->current_constructor_bound_count,
                               &context->current_constructor_bound_capacity,
                               name);
}

static bool constructor_block_binds_let_field(const FengDecl *type_decl,
                                             const FengBlock *block,
                                             FengSlice field_name);

static bool constructor_stmt_binds_let_field(const FengDecl *type_decl,
                                            const FengStmt *stmt,
                                            FengSlice field_name) {
    if (stmt == NULL) return false;

    switch (stmt->kind) {
        case FENG_STMT_BLOCK:
            return constructor_block_binds_let_field(type_decl, stmt->as.block, field_name);
        case FENG_STMT_ASSIGN: {
            const FengTypeMember *member = find_direct_self_let_target_member(type_decl,
                                                                              stmt->as.assign.target);
            return member != NULL &&
                   member->as.field.name.length == field_name.length &&
                   memcmp(member->as.field.name.data, field_name.data, field_name.length) == 0;
        }
        case FENG_STMT_IF:
            for (size_t i = 0U; i < stmt->as.if_stmt.clause_count; ++i) {
                if (constructor_block_binds_let_field(type_decl,
                                                      stmt->as.if_stmt.clauses[i].block,
                                                      field_name)) {
                    return true;
                }
            }
            return constructor_block_binds_let_field(type_decl,
                                                     stmt->as.if_stmt.else_block,
                                                     field_name);
        case FENG_STMT_MATCH:
            for (size_t i = 0U; i < stmt->as.match_stmt.branch_count; ++i) {
                if (constructor_block_binds_let_field(type_decl,
                                                      stmt->as.match_stmt.branches[i].body,
                                                      field_name)) {
                    return true;
                }
            }
            return constructor_block_binds_let_field(type_decl,
                                                     stmt->as.match_stmt.else_block,
                                                     field_name);
        case FENG_STMT_WHILE:
            return constructor_block_binds_let_field(type_decl,
                                                     stmt->as.while_stmt.body,
                                                     field_name);
        case FENG_STMT_FOR:
            return constructor_stmt_binds_let_field(type_decl,
                                                    stmt->as.for_stmt.init,
                                                    field_name) ||
                   constructor_stmt_binds_let_field(type_decl,
                                                    stmt->as.for_stmt.update,
                                                    field_name) ||
                   constructor_block_binds_let_field(type_decl,
                                                     stmt->as.for_stmt.body,
                                                     field_name);
        case FENG_STMT_BINDING:
        case FENG_STMT_EXPR:
        case FENG_STMT_TRY:
        case FENG_STMT_RETURN:
        case FENG_STMT_THROW:
        case FENG_STMT_BREAK:
        case FENG_STMT_CONTINUE:
        case FENG_STMT_DEFER:
            return false;
    }
    return false;
}

static bool constructor_block_binds_let_field(const FengDecl *type_decl,
                                             const FengBlock *block,
                                             FengSlice field_name) {
    if (block == NULL) return false;
    for (size_t i = 0U; i < block->statement_count; ++i) {
        if (constructor_stmt_binds_let_field(type_decl, block->statements[i], field_name)) {
            return true;
        }
    }
    return false;
}

static bool constructor_binds_let_field(const FengDecl *type_decl,
                                        const FengTypeMember *constructor,
                                        FengSlice field_name) {
    if (constructor_has_imported_bound_name(constructor, field_name)) {
        return true;
    }
    return constructor != NULL &&
           constructor->kind == FENG_TYPE_MEMBER_CONSTRUCTOR &&
           constructor_block_binds_let_field(type_decl,
                                             constructor->as.callable.body,
                                             field_name);
}

static bool validate_let_field_object_literal_binding(ResolveContext *context,
                                                      const FengDecl *type_decl,
                                                      const FengSemanticModule *provider_module,
                                                      const FengExpr *target_expr,
                                                      const FengObjectFieldInit *field) {
    const FengTypeMember *let_field = find_type_let_field_member(type_decl, field->name);
    const FengTypeMember *selected_constructor = NULL;
    ConstructorResolution resolution;

    if (let_field == NULL) {
        return true;
    }

    if (field_has_declaration_initializer(let_field)) {
        return resolver_append_error(
            context,
            field->token,
            "AE0102", format_message("object literal field '%.*s' repeats final binding of let member '%.*s' already completed by declaration initializer",
                           (int)field->name.length,
                           field->name.data,
                           (int)field->name.length,
                           field->name.data));
    }

    if (count_declared_constructors(type_decl) > 0U) {
        if (target_expr != NULL && target_expr->kind == FENG_EXPR_CALL) {
            resolution = resolve_accessible_constructor_overload(context,
                                                                 type_decl,
                                                                 provider_module,
                                                                 target_expr->as.call.args,
                                                                 target_expr->as.call.arg_count,
                                                                 target_expr->as.call.has_explicit_type_args
                                                                     ? (const FengTypeRef *const *)target_expr->as.call.explicit_type_args
                                                                     : NULL,
                                                                 target_expr->as.call.has_explicit_type_args
                                                                     ? target_expr->as.call.explicit_type_arg_count
                                                                     : 0U);
        } else {
            resolution = resolve_accessible_constructor_overload(context,
                                                                 type_decl,
                                                                 provider_module,
                                                                 NULL,
                                                                 0U,
                                                                 NULL,
                                                                 0U);
        }
        if (resolution.kind == FENG_CONSTRUCTOR_RESOLUTION_UNIQUE) {
            selected_constructor = resolution.constructor;
        }
    }

    if (constructor_binds_let_field(type_decl, selected_constructor, field->name)) {
        return resolver_append_error(
            context,
            field->token,
            "AE0102", format_message("object literal field '%.*s' repeats final binding of let member '%.*s' already completed by constructor '%.*s'",
                           (int)field->name.length,
                           field->name.data,
                           (int)field->name.length,
                           field->name.data,
                           (int)selected_constructor->as.callable.name.length,
                           selected_constructor->as.callable.name.data));
    }

    return true;
}

static bool validate_self_let_assignment(ResolveContext *context, const FengStmt *stmt) {
    const FengTypeMember *field_member;

    if (context->current_type_decl == NULL) {
        return true;
    }

    field_member = find_direct_self_let_target_member(context->current_type_decl, stmt->as.assign.target);
    if (field_member == NULL) {
        return true;
    }

    if (context->current_callable_body_member == NULL ||
        context->current_callable_body_member->kind != FENG_TYPE_MEMBER_CONSTRUCTOR) {
        return resolver_append_error(
            context,
            stmt->as.assign.target->token,
            "AE0103", format_message("let member '%.*s' cannot be directly assigned outside constructors",
                           (int)field_member->as.field.name.length,
                           field_member->as.field.name.data));
    }

    if (field_has_declaration_initializer(field_member)) {
        return resolver_append_error(
            context,
            stmt->as.assign.target->token,
            "AE0102", format_message("constructor assignment repeats final binding of let member '%.*s' already completed by declaration initializer",
                           (int)field_member->as.field.name.length,
                           field_member->as.field.name.data));
    }

    if (resolver_current_constructor_has_bound_name(context, field_member->as.field.name)) {
        return resolver_append_error(
            context,
            stmt->as.assign.target->token,
            "AE0102", format_message("constructor assignment repeats final binding of let member '%.*s' more than once in constructor '%.*s'",
                           (int)field_member->as.field.name.length,
                           field_member->as.field.name.data,
                           (int)context->current_callable_body_member->as.callable.name.length,
                           context->current_callable_body_member->as.callable.name.data));
    }

    return resolver_current_constructor_add_bound_name(context, field_member->as.field.name);
}

static const FengTypeRef *resolve_indexed_array_element_type_ref(ResolveContext *context,
                                                                 const FengExpr *object_expr) {
    InferredExprType object_type;

    if (object_expr == NULL) {
        return NULL;
    }

    object_type = infer_expr_type(context, object_expr);
    if (object_type.kind != FENG_INFERRED_EXPR_TYPE_TYPE_REF || object_type.type_ref == NULL) {
        return NULL;
    }
    if (object_type.type_ref->kind != FENG_TYPE_REF_ARRAY) {
        return NULL;
    }

    return object_type.type_ref->as.inner;
}

static InferredExprType infer_array_literal_expr_type(ResolveContext *context, const FengExpr *expr) {
    size_t item_index;
    InferredExprType element_type;
    const FengTypeRef *array_type_ref;

    if (expr == NULL || expr->kind != FENG_EXPR_ARRAY_LITERAL || expr->as.array_literal.count == 0U) {
        return inferred_expr_type_unknown();
    }

    /* Array literal element adaptation (§10.3.5): same strategy as
     * validate_array_literal_expr.  Nested arrays only reach this function
     * (inner arrays are not individually passed through resolve_expr →
     * validate_array_literal_expr), so the adaptation must be self-contained
     * here. */
    if (context->current_expr_expected_type_ref != NULL &&
        context->current_expr_expected_type_ref->kind == FENG_TYPE_REF_ARRAY &&
        context->current_expr_expected_type_ref->as.inner != NULL) {
        InferredExprType target =
            inferred_expr_type_from_type_ref(context->current_expr_expected_type_ref->as.inner);
        if (inferred_expr_type_is_numeric(target)) {
            for (item_index = 0U; item_index < expr->as.array_literal.count; ++item_index) {
                const FengExpr *item = expr->as.array_literal.items[item_index];
                if (expr_is_pure_numeric_literal_expr_for_target_adaptation(item) &&
                    numeric_literal_fits_inferred_target(context, item, target)) {
                    fill_expr_type_from_inferred(context, (FengExpr *)item, &target);
                }
            }
        }
    } else {
        InferredExprType target;
        bool found_target = false;

        memset(&target, 0, sizeof(target));
        for (item_index = 0U; item_index < expr->as.array_literal.count; ++item_index) {
            const FengExpr *item = expr->as.array_literal.items[item_index];
            if (!expr_is_pure_numeric_literal_expr_for_target_adaptation(item)) {
                target = infer_expr_type(context, item);
                if (inferred_expr_type_is_known(target) &&
                    inferred_expr_type_is_numeric(target)) {
                    found_target = true;
                }
                break;
            }
        }
        if (found_target) {
            for (item_index = 0U; item_index < expr->as.array_literal.count; ++item_index) {
                const FengExpr *item = expr->as.array_literal.items[item_index];
                if (expr_is_pure_numeric_literal_expr_for_target_adaptation(item) &&
                    numeric_literal_fits_inferred_target(context, item, target)) {
                    fill_expr_type_from_inferred(context, (FengExpr *)item, &target);
                }
            }
        }
    }

    element_type = infer_expr_type(context, expr->as.array_literal.items[0]);
    if (!inferred_expr_type_is_known(element_type)) {
        return inferred_expr_type_unknown();
    }

    for (item_index = 1U; item_index < expr->as.array_literal.count; ++item_index) {
        InferredExprType item_type = infer_expr_type(context, expr->as.array_literal.items[item_index]);

        if (!inferred_expr_type_is_known(item_type) ||
            !inferred_expr_types_equal(context, element_type, item_type)) {
            return inferred_expr_type_unknown();
        }
    }

    array_type_ref = synthesize_array_type_ref(context, &element_type,
                                               false,
                                               expr->token);
    return array_type_ref != NULL ? inferred_expr_type_from_type_ref(array_type_ref)
                                  : inferred_expr_type_unknown();
}

/* Report the ordinary target mismatch for a target-sensitive aggregate after
 * pure matching has rejected it. This is also the fallback when the generic
 * validator cannot infer a complete aggregate type from an invalid value. */
static bool append_expr_expected_type_mismatch(ResolveContext *context,
                                               const FengExpr *expr,
                                               const FengTypeRef *expected_type_ref) {
    char *expr_name = format_expr_target_name(expr);
    char *type_name = format_type_ref_name(expected_type_ref);
    bool ok = resolver_append_error(
        context,
        expr->token,
        "AE1003", format_message("expression '%s' does not match expected type '%s'",
                       expr_name != NULL ? expr_name : "<expression>",
                       type_name != NULL ? type_name : "<type>"));

    free(expr_name);
    free(type_name);
    return ok;
}

static bool validate_array_literal_expr(ResolveContext *context, const FengExpr *expr) {
    size_t item_index;
    InferredExprType element_type = inferred_expr_type_unknown();

    if (expr == NULL || expr->kind != FENG_EXPR_ARRAY_LITERAL) {
        return true;
    }

    /* An explicit target owns element compatibility diagnostics. Propagate its
     * immediate element type uniformly at every nesting level, then stop after
     * the first item that emitted a root diagnostic so an outer array cannot
     * add a derived mismatch for the same failure. */
    if (context->current_expr_expected_type_ref != NULL) {
        const FengTypeRef *expected_type_ref =
            context->current_expr_expected_type_ref;

        if (expected_type_ref->kind != FENG_TYPE_REF_ARRAY ||
            expected_type_ref->as.inner == NULL) {
            if (expr_matches_expected_type_ref(context,
                                               expr,
                                               expected_type_ref)) {
                return true;
            }
            return append_expr_expected_type_mismatch(context,
                                                      expr,
                                                      expected_type_ref);
        }
        for (item_index = 0U; item_index < expr->as.array_literal.count; ++item_index) {
            size_t errors_before = context->error_count != NULL
                                       ? *context->error_count
                                       : 0U;
            const FengExpr *item = expr->as.array_literal.items[item_index];

            if (!expr_matches_expected_type_ref(context,
                                                item,
                                                expected_type_ref->as.inner)) {
                if (!validate_expr_against_expected_type(
                        context,
                        item,
                        expected_type_ref->as.inner)) {
                    return false;
                }
                if (context->error_count == NULL ||
                    *context->error_count == errors_before) {
                    return append_expr_expected_type_mismatch(
                        context, item, expected_type_ref->as.inner);
                }
            }
            if (context->error_count != NULL &&
                *context->error_count > errors_before) {
                return true;
            }
        }
        return true;
    }

    /* A call argument has no parameter target until overload selection. Its
     * literal remains structurally resolved, while candidate matching decides
     * applicability without committing this provisional no-target error. */
    if (context->deferred_call_argument_target_depth > 0U) {
        return true;
    }

    /* Without an explicit target, find the first non-literal element's
     * inferred numeric type and adapt pure numeric literals to it. If every
     * element is a literal, each retains its default inferred type. */
    {
        InferredExprType target;
        bool found_target = false;

        memset(&target, 0, sizeof(target));
        for (item_index = 0U; item_index < expr->as.array_literal.count; ++item_index) {
            const FengExpr *item = expr->as.array_literal.items[item_index];
            if (!expr_is_pure_numeric_literal_expr_for_target_adaptation(item)) {
                target = infer_expr_type(context, item);
                if (inferred_expr_type_is_known(target) &&
                    inferred_expr_type_is_numeric(target)) {
                    found_target = true;
                }
                break;
            }
        }
        if (found_target) {
            for (item_index = 0U; item_index < expr->as.array_literal.count; ++item_index) {
                const FengExpr *item = expr->as.array_literal.items[item_index];
                if (expr_is_pure_numeric_literal_expr_for_target_adaptation(item) &&
                    numeric_literal_fits_inferred_target(context, item, target)) {
                    fill_expr_type_from_inferred(context, (FengExpr *)item, &target);
                }
            }
        }
    }

    for (item_index = 0U; item_index < expr->as.array_literal.count; ++item_index) {
        InferredExprType item_type = infer_expr_type(context, expr->as.array_literal.items[item_index]);

        if (!inferred_expr_type_is_known(item_type)) {
            continue;
        }

        if (!inferred_expr_type_is_known(element_type)) {
            element_type = item_type;
            continue;
        }

        if (!inferred_expr_types_equal(context, element_type, item_type)) {
            char *type_name = format_inferred_expr_type_name(element_type, context->pointer_size);
            bool ok = resolver_append_error(
                context,
                expr->as.array_literal.items[item_index]->token,
                "AE0201", format_message("array literal element at index %zu does not match expected type '%s'",
                               item_index,
                               type_name != NULL ? type_name : "<type>"));

            free(type_name);
            return ok;
        }
    }

    return true;
}

static bool append_assignment_target_not_writable_error(ResolveContext *context,
                                                        const FengExpr *target) {
    char *target_name = format_expr_target_name(target);
    bool ok = resolver_append_error(
        context,
        target->token,
        "AE0104", format_message("assignment target '%s' is not writable",
                       target_name != NULL ? target_name : "<expression>"));

    free(target_name);
    return ok;
}

static bool validate_assignment_target_writable(ResolveContext *context, const FengExpr *target) {
    if (target == NULL) {
        return true;
    }

    switch (target->kind) {
        case FENG_EXPR_IDENTIFIER: {
            const LocalNameEntry *local_entry =
                resolver_find_local_name_entry(context, target->as.identifier);
            const VisibleValueEntry *visible_value;

            if (local_entry != NULL) {
                return mutability_is_writable(local_entry->mutability)
                           ? true
                           : append_assignment_target_not_writable_error(context, target);
            }

            visible_value = find_visible_value(context->visible_values,
                                               context->visible_value_count,
                                               target->as.identifier);
            if (visible_value != NULL) {
                if (!visible_value->is_function &&
                    visible_value->decl != NULL &&
                    visible_value->decl->kind == FENG_DECL_GLOBAL_BINDING &&
                    mutability_is_writable(visible_value->mutability)) {
                    return true;
                }
                return append_assignment_target_not_writable_error(context,
                                                                   target);
            }

            if (find_visible_type_any_arity(context->visible_types,
                                            context->visible_type_count,
                                            target->as.identifier) != NULL ||
                find_type_param(context, target->as.identifier) != NULL) {
                return append_assignment_target_not_writable_error(context,
                                                                   target);
            }

            /* Name resolution has already emitted AE0001 for an unknown
             * identifier, or AE0904 for a bare module alias. Neither denotes
             * a value whose mutability can be checked, so do not append a
             * derived AE0104 diagnostic for the same invalid target. */
            return true;
        }

        case FENG_EXPR_MEMBER: {
            const FengExpr *object = target->as.member.object;
            ResolvedTypeTarget static_target = resolve_type_target_expr(context, object, false);

            if (static_target.type_decl != NULL && static_target.type_decl->kind == FENG_DECL_TYPE) {
                const FengTypeMember *static_field =
                    find_type_static_field_member(static_target.type_decl, target->as.member.member);

                if (static_field != NULL && static_field->as.field.mutability == FENG_MUTABILITY_VAR) {
                    return true;
                }
                if (static_field != NULL) {
                    return append_assignment_target_not_writable_error(context, target);
                }
            }

            /* G4: T.field assignment through a generic type parameter's
             * constraint spec — the field's mutability is taken from the
             * spec's declared `static var` / `static let` qualifier. */
            if (static_target.is_generic_type_param &&
                static_target.constraint_spec_decl != NULL) {
                const FengTypeMember *spec_member =
                    find_spec_object_field_with_owner(
                        context,
                        static_target.constraint_spec_decl,
                        target->as.member.member,
                        /*require_static=*/true,
                        NULL);

                if (spec_member != NULL) {
                    if (spec_member->as.field.mutability == FENG_MUTABILITY_VAR) {
                        return true;
                    }
                    return append_assignment_target_not_writable_error(context, target);
                }
            }

            if (decl_is_enum_type(static_target.type_decl)) {
                return append_assignment_target_not_writable_error(context, target);
            }

            {
                ResolvedModuleMemberTarget module_target;

                if (resolve_module_member_target(
                        context, target, &module_target)) {
                    const FengDecl *binding_decl =
                        find_module_public_binding_decl(
                            module_target.module,
                            module_target.member_name);

                    if (binding_decl != NULL &&
                        binding_decl->kind == FENG_DECL_GLOBAL_BINDING &&
                        mutability_is_writable(
                            binding_decl->as.binding.mutability)) {
                        return true;
                    }

                    return append_assignment_target_not_writable_error(
                        context, target);
                }
            }

            if (context->current_type_decl != NULL &&
                find_direct_self_let_target_member(context->current_type_decl, target) != NULL) {
                return true;
            }

            {
                const FengDecl *owner_type_decl = resolve_inferred_expr_type_decl(
                    context, infer_expr_type(context, target->as.member.object));

                if (owner_type_decl != NULL) {
                    const FengTypeMember *member =
                        find_decl_instance_member(context, owner_type_decl, target->as.member.member);

                    if (member == NULL && owner_type_decl->kind == FENG_DECL_SPEC &&
                        owner_type_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
                        /* Intersection-form spec: search each flattened member's
                         * closure for the field accessor to determine its
                         * mutability. */
                        const FengIntersectionSpecInfo *info =
                            feng_semantic_lookup_intersection_spec_info(
                                context->analysis, owner_type_decl);
                        if (info != NULL) {
                            for (size_t mi = 0U;
                                 mi < info->flattened_member_count && member == NULL;
                                 ++mi) {
                                member = find_spec_object_member(context,
                                                                 info->flattened_members[mi],
                                                                 target->as.member.member,
                                                                 /*include_static=*/false);
                            }
                        }
                    }

                    if (member != NULL && member->kind == FENG_TYPE_MEMBER_FIELD &&
                        member->as.field.mutability == FENG_MUTABILITY_VAR) {
                        return true;
                    }

                    if (member != NULL) {
                        return append_assignment_target_not_writable_error(context, target);
                    }
                }
            }

            return true;
        }

        case FENG_EXPR_INDEX:
            if (!validate_index_expr(context, target)) {
                return false;
            }
            /* docs/specifications/feng-builtin-type.md §5: writes via `[i] =` are only legal
             * when the indexed array layer is marked writable (`T[!]`). */
            {
                InferredExprType object_type =
                    infer_expr_type(context, target->as.index.object);
                if (object_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
                    object_type.type_ref != NULL &&
                    object_type.type_ref->kind == FENG_TYPE_REF_ARRAY &&
                    !object_type.type_ref->array_element_writable) {
                    return append_assignment_target_not_writable_error(context, target);
                }
            }
            return true;

        default:
            return append_assignment_target_not_writable_error(context, target);
    }
}

static char *format_expr_target_name(const FengExpr *expr) {
    if (expr == NULL) {
        return duplicate_cstr("<expression>");
    }

    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER:
            return format_module_name(&expr->as.identifier, 1U);

        case FENG_EXPR_MEMBER: {
            char *object_name = format_expr_target_name(expr->as.member.object);
            size_t object_length = object_name != NULL ? strlen(object_name) : 12U;
            const char *fallback = "<expression>";
            char *buffer = (char *)malloc(object_length + 1U + expr->as.member.member.length + 1U);

            if (buffer == NULL) {
                free(object_name);
                return NULL;
            }

            if (object_name != NULL) {
                memcpy(buffer, object_name, object_length);
            } else {
                memcpy(buffer, fallback, object_length);
            }
            buffer[object_length] = '.';
            memcpy(buffer + object_length + 1U,
                   expr->as.member.member.data,
                   expr->as.member.member.length);
            buffer[object_length + 1U + expr->as.member.member.length] = '\0';
            free(object_name);
            return buffer;
        }

        case FENG_EXPR_UNARY:
            if (expr->as.unary.op == FENG_TOKEN_AMP) {
                char *operand_name = format_expr_target_name(expr->as.unary.operand);
                size_t operand_length = operand_name != NULL ? strlen(operand_name) : 12U;
                const char *fallback = "<expression>";
                char *buffer = (char *)malloc(operand_length + 2U);

                if (buffer == NULL) {
                    free(operand_name);
                    return NULL;
                }

                buffer[0] = '&';
                if (operand_name != NULL) {
                    memcpy(buffer + 1U, operand_name, operand_length);
                } else {
                    memcpy(buffer + 1U, fallback, operand_length);
                }
                buffer[operand_length + 1U] = '\0';
                free(operand_name);
                return buffer;
            }
            return duplicate_cstr("<expression>");

        case FENG_EXPR_CALL:
            return format_expr_target_name(expr->as.call.callee);

        case FENG_EXPR_GENERIC_TARGET:
            return format_expr_target_name(expr->as.generic_target.target);

        case FENG_EXPR_TUPLE_LITERAL:
            return duplicate_cstr("<tuple literal>");

        default:
            return duplicate_cstr("<expression>");
    }
}

static bool synthesize_type_ref_from_generic_target_expr(ResolveContext *context,
                                                         const FengExpr *target_expr,
                                                         const FengExpr *generic_expr,
                                                         FengTypeRef **out_ref) {
    size_t segment_count = 0U;
    FengSlice *segments = NULL;
    FengTypeRef **type_args = NULL;
    FengTypeRef *type_ref = NULL;

    if (out_ref == NULL) {
        return false;
    }
    *out_ref = NULL;
    if (context == NULL || target_expr == NULL || generic_expr == NULL ||
        generic_expr->kind != FENG_EXPR_GENERIC_TARGET) {
        return true;
    }

    segments = expr_path_segments_alloc(target_expr, &segment_count);
    if (segments == NULL || segment_count == 0U) {
        free(segments);
        return true;
    }

    if (generic_expr->as.generic_target.type_arg_count > 0U) {
        type_args = (FengTypeRef **)calloc(generic_expr->as.generic_target.type_arg_count,
                                          sizeof(*type_args));
        if (type_args == NULL) {
            free(segments);
            return false;
        }
        for (size_t index = 0U;
             index < generic_expr->as.generic_target.type_arg_count;
             ++index) {
            type_args[index] = clone_type_ref_for_inference(
                generic_expr->as.generic_target.type_args[index]);
            if (type_args[index] == NULL) {
                for (size_t free_index = 0U; free_index < index; ++free_index) {
                    free_synthetic_type_ref(type_args[free_index]);
                }
                free(type_args);
                free(segments);
                return false;
            }
        }
    }

    type_ref = (FengTypeRef *)calloc(1U, sizeof(*type_ref));
    if (type_ref == NULL) {
        for (size_t index = 0U;
             index < generic_expr->as.generic_target.type_arg_count;
             ++index) {
            free_synthetic_type_ref(type_args[index]);
        }
        free(type_args);
        free(segments);
        return false;
    }
    type_ref->token = generic_expr->token;
    type_ref->kind = FENG_TYPE_REF_NAMED;
    type_ref->as.named.segments = segments;
    type_ref->as.named.segment_count = segment_count;
    type_ref->as.named.type_args = type_args;
    type_ref->as.named.type_arg_count = generic_expr->as.generic_target.type_arg_count;

    if (!resolver_track_synthetic_type_ref(context, type_ref)) {
        free_synthetic_type_ref(type_ref);
        return false;
    }
    *out_ref = type_ref;
    return true;
}

/* Resolve a direct type target by the arity known at its use site.
 * A zero result means no exact declaration exists; callers may then retain a
 * name-only result solely for existing mismatch diagnostics. */
static ResolvedTypeTarget resolve_type_target_expr_exact_arity(ResolveContext *context,
                                                               const FengExpr *target_expr,
                                                               size_t type_param_count) {
    ResolvedTypeTarget result;

    memset(&result, 0, sizeof(result));
    if (target_expr == NULL) {
        return result;
    }

    if (target_expr->kind == FENG_EXPR_IDENTIFIER) {
        const VisibleTypeEntry *entry =
            find_visible_type(context->visible_types,
                              context->visible_type_count,
                              target_expr->as.identifier,
                              type_param_count);

        if (entry != NULL) {
            result.type_decl = entry->decl;
            result.provider_module = entry->provider_module;
        }
        return result;
    }

    if (target_expr->kind == FENG_EXPR_MEMBER) {
        if (target_expr->as.member.object != NULL &&
            target_expr->as.member.object->kind == FENG_EXPR_IDENTIFIER) {
            const AliasEntry *alias =
                find_unshadowed_alias(context, target_expr->as.member.object->as.identifier);

            if (alias != NULL) {
                result.type_decl =
                    find_module_public_type_decl(alias->target_module,
                                                 target_expr->as.member.member,
                                                 type_param_count);
                result.provider_module = result.type_decl != NULL ? alias->target_module : NULL;
            }
        }

        if (result.type_decl == NULL) {
            size_t path_segment_count = 0U;
            FengSlice *path_segments = expr_path_segments_alloc(target_expr, &path_segment_count);

            if (path_segments != NULL && path_segment_count > 1U) {
                size_t module_index = find_module_index_by_path(context->analysis,
                                                                path_segments,
                                                                path_segment_count - 1U);

                if (module_index < context->analysis->module_count &&
                    module_is_full_path_visible_from(context,
                                                     &context->analysis->modules[module_index])) {
                    result.type_decl = find_module_public_type_decl(
                        &context->analysis->modules[module_index],
                        path_segments[path_segment_count - 1U],
                        type_param_count);
                    result.provider_module = result.type_decl != NULL
                        ? &context->analysis->modules[module_index]
                        : NULL;
                }
            }
            free(path_segments);
        }
    }
    return result;
}

static ResolvedTypeTarget resolve_type_target_expr(ResolveContext *context,
                                                   const FengExpr *target_expr,
                                                   bool follow_call_callee) {
    ResolvedTypeTarget result;

    memset(&result, 0, sizeof(result));
    if (target_expr == NULL) {
        return result;
    }

    switch (target_expr->kind) {
        case FENG_EXPR_IDENTIFIER: {
            const VisibleTypeEntry *entry = find_visible_type(
                context->visible_types,
                context->visible_type_count,
                target_expr->as.identifier,
                0U);

            if (entry == NULL) {
                entry = find_visible_type_any_arity(context->visible_types,
                                                    context->visible_type_count,
                                                    target_expr->as.identifier);
            }

            if (entry != NULL) {
                result.type_decl = entry->decl;
                result.provider_module = entry->provider_module;
            } else {
                const char *builtin_name = canonical_builtin_type_name(target_expr->as.identifier, context->pointer_size);

                if (builtin_name != NULL) {
                    result.is_builtin_type_name = true;
                    result.builtin_name = slice_from_cstr(builtin_name);
                } else {
                    /* G4: generic type parameter. The identifier may name a
                     * type parameter bound by the enclosing generic function
                     * (or generic type context). When its constraint is a
                     * spec, static member access (e.g., T.make()) dispatches
                     * through the constraint's witness table. */
                    const TypeParamEntry *tp = find_type_param(context, target_expr->as.identifier);

                    if (tp != NULL) {
                        result.is_generic_type_param = true;
                        if (tp->type_param != NULL && tp->type_param->constraint != NULL) {
                            const FengDecl *constraint_spec = NULL;

                            if (tp->type_param->constraint->kind == FENG_TYPE_REF_NAMED) {
                                const FengTypeRef *cref = tp->type_param->constraint;
                                FengSlice name_slice = cref->as.named.segment_count > 0U
                                    ? cref->as.named.segments[cref->as.named.segment_count - 1U]
                                    : slice_from_cstr("");
                                /* Precise lookup: arity from constraint's type_arg_count */
                                const VisibleTypeEntry *c_entry =
                                    find_visible_type(context->visible_types,
                                                      context->visible_type_count,
                                                      name_slice,
                                                      cref->as.named.type_arg_count);

                                if (c_entry != NULL && c_entry->decl != NULL &&
                                    c_entry->decl->kind == FENG_DECL_SPEC) {
                                    constraint_spec = c_entry->decl;
                                }
                            }
                            result.constraint_spec_decl = constraint_spec;
                            result.constraint_spec_type_ref =
                                constraint_spec != NULL
                                    ? tp->type_param->constraint
                                    : NULL;
                        }
                    }
                }
            }
            return result;
        }

        case FENG_EXPR_MEMBER:
            if (target_expr->as.member.object != NULL &&
                target_expr->as.member.object->kind == FENG_EXPR_IDENTIFIER) {
                const AliasEntry *alias =
                    find_unshadowed_alias(context, target_expr->as.member.object->as.identifier);

                if (alias != NULL) {
                    result.type_decl = find_module_public_type_decl(alias->target_module,
                                                                    target_expr->as.member.member,
                                                                    0U);
                    if (result.type_decl == NULL) {
                        result.type_decl = find_module_public_type_decl_any_arity(
                            alias->target_module, target_expr->as.member.member);
                    }
                    result.provider_module = result.type_decl != NULL ? alias->target_module : NULL;
                }
            }

            if (result.type_decl == NULL) {
                size_t path_segment_count = 0U;
                FengSlice *path_segments = expr_path_segments_alloc(target_expr, &path_segment_count);

                if (path_segments != NULL && path_segment_count > 1U) {
                    size_t module_index = find_module_index_by_path(context->analysis,
                                                                    path_segments,
                                                                    path_segment_count - 1U);

                    if (module_index < context->analysis->module_count &&
                        module_is_full_path_visible_from(context,
                                                         &context->analysis->modules[module_index])) {
                        result.type_decl = find_module_public_type_decl(
                            &context->analysis->modules[module_index],
                            path_segments[path_segment_count - 1U],
                            0U);
                        if (result.type_decl == NULL) {
                            result.type_decl = find_module_public_type_decl_any_arity(
                                &context->analysis->modules[module_index],
                                path_segments[path_segment_count - 1U]);
                        }
                        result.provider_module = result.type_decl != NULL
                            ? &context->analysis->modules[module_index]
                            : NULL;
                    }
                }
                free(path_segments);
            }
            return result;

        case FENG_EXPR_CALL:
            if (follow_call_callee) {
                size_t wanted_arity = target_expr->as.call.has_explicit_type_args
                                          ? target_expr->as.call.explicit_type_arg_count
                                          : 0U;

                result = resolve_type_target_expr_exact_arity(
                    context, target_expr->as.call.callee, wanted_arity);
                if (result.type_decl != NULL) {
                    return result;
                }
                return resolve_type_target_expr(context, target_expr->as.call.callee, true);
            }
            return result;

        case FENG_EXPR_GENERIC_TARGET: {
            FengTypeRef *type_ref = NULL;

            result = resolve_type_target_expr_exact_arity(
                context,
                target_expr->as.generic_target.target,
                target_expr->as.generic_target.type_arg_count);
            if (result.type_decl == NULL) {
                result = resolve_type_target_expr(context,
                                                  target_expr->as.generic_target.target,
                                                  false);
            }
            if (result.type_decl != NULL &&
                synthesize_type_ref_from_generic_target_expr(context,
                                                            target_expr->as.generic_target.target,
                                                            target_expr,
                                                            &type_ref)) {
                result.type_ref = type_ref;
            }
            return result;
        }

        default:
            return result;
    }
}

static InferredExprType resolved_type_target_owner_type(const ResolvedTypeTarget *target) {
    if (target == NULL) {
        return inferred_expr_type_unknown();
    }
    if (target->type_ref != NULL) {
        return inferred_expr_type_from_type_ref(target->type_ref);
    }
    if (target->is_builtin_type_name) {
        return inferred_expr_type_builtin(target->builtin_name.data != NULL
                                              ? target->builtin_name.data
                                              : "");
    }
    return inferred_expr_type_from_decl(target->type_decl);
}

/* Fill missing provenance on a closed type copy. Substituted nodes may
 * already belong to another program and must retain that independent scope. */
static void bind_type_ref_resolution_program(FengTypeRef *type_ref,
                                             const FengProgram *program) {
    if (type_ref == NULL) {
        return;
    }
    if (type_ref->resolution_program == NULL) {
        type_ref->resolution_program = program;
    }
    if (type_ref->kind == FENG_TYPE_REF_NAMED) {
        for (size_t index = 0U; index < type_ref->as.named.type_arg_count; ++index) {
            bind_type_ref_resolution_program(type_ref->as.named.type_args[index],
                                              type_ref->resolution_program);
        }
    } else {
        bind_type_ref_resolution_program(type_ref->as.inner,
                                          type_ref->resolution_program);
    }
}

/* Returns the semantic type of one module-level binding, including inferred
 * initializer facts recorded for bindings without an explicit type. */
static InferredExprType infer_global_binding_decl_type(ResolveContext *context,
                                                       const FengDecl *binding_decl) {
    InferredExprType result = inferred_expr_type_unknown();

    if (binding_decl == NULL || binding_decl->kind != FENG_DECL_GLOBAL_BINDING) {
        return inferred_expr_type_unknown();
    }
    if (binding_decl->as.binding.type != NULL) {
        result = inferred_expr_type_from_type_ref(binding_decl->as.binding.type);
    } else if (context != NULL && context->analysis != NULL) {
        result = inferred_expr_type_from_type_fact(
            feng_semantic_lookup_type_fact(context->analysis, &binding_decl->as.binding));
    }
    if (result.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
        result.type_ref != NULL && result.type_ref->resolution_program == NULL) {
        const FengProgram *program = find_decl_provider_program(context->analysis, binding_decl);
        FengTypeRef *copy = clone_type_ref_for_inference(result.type_ref);

        /* Resolved-call and member sidecars may borrow this closed type after
         * the current file resolver is released. */
        if (copy == NULL || !analysis_track_synthetic_type_ref(context->analysis, copy)) {
            free_synthetic_type_ref(copy);
            return inferred_expr_type_unknown();
        }
        bind_type_ref_resolution_program(copy, program);
        result.type_ref = copy;
    }
    return result;
}

static InferredExprType infer_identifier_expr_type(ResolveContext *context, FengSlice name) {
    const LocalNameEntry *local_entry = resolver_find_local_name_entry(context, name);

    if (local_entry != NULL) {
        return local_entry->type;
    }

    {
        const VisibleValueEntry *visible_value =
            find_visible_value(context->visible_values, context->visible_value_count, name);

        if (visible_value != NULL && !visible_value->is_function &&
            visible_value->decl != NULL &&
            visible_value->decl->kind == FENG_DECL_GLOBAL_BINDING) {
            return infer_global_binding_decl_type(context, visible_value->decl);
        }
    }

    return inferred_expr_type_unknown();
}

static InferredExprType infer_member_expr_type(ResolveContext *context, const FengExpr *expr) {
    ResolvedTypeTarget type_target = resolve_type_target_expr(context, expr->as.member.object, false);

    /* G4: generic type parameter static field access (T.field where T: S
     * and S declares `static let field`). Close the field type through the
     * exact constraint/declaring-spec instance instead of parameter names. */
    if (type_target.is_generic_type_param &&
        type_target.constraint_spec_decl != NULL) {
        const FengDecl *declaring_spec = NULL;
        const FengTypeMember *member =
            find_spec_object_field_with_owner(
                context,
                type_target.constraint_spec_decl,
                expr->as.member.member,
                /*require_static=*/true,
                &declaring_spec);

        if (member != NULL) {
            const FengTypeRef *declaring_spec_instance =
                constraint_member_declaring_spec_instance(
                    context,
                    &type_target,
                    declaring_spec);
            const FengTypeRef *closed_field =
                substitute_spec_member_type_ref_for_instance(
                    context,
                    declaring_spec,
                    declaring_spec_instance,
                    member->as.field.type);

            if (closed_field != NULL) {
                return inferred_expr_type_from_type_ref(closed_field);
            }
            return inferred_expr_type_unknown();
        }
    }

    if (type_target.type_decl != NULL && type_target.type_decl->kind == FENG_DECL_TYPE) {
        const FengTypeMember *static_field =
            find_type_static_field_member(type_target.type_decl, expr->as.member.member);

        if (static_field != NULL) {
            InferredExprType owner_type = resolved_type_target_owner_type(&type_target);

            if (static_field->as.field.type != NULL) {
                return inferred_expr_type_from_type_ref(
                    substitute_type_ref_for_owner_instance(context,
                                                           type_target.type_decl,
                                                           owner_type,
                                                           static_field->as.field.type));
            }

            if (context->analysis != NULL) {
                const FengSemanticTypeFact *fact =
                    feng_semantic_lookup_type_fact(context->analysis, static_field);

                if (fact != NULL && fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF) {
                    return inferred_expr_type_from_type_ref(
                        substitute_type_ref_for_owner_instance(context,
                                                               type_target.type_decl,
                                                               owner_type,
                                                               fact->type_ref));
                }
                return inferred_expr_type_from_type_fact(fact);
            }
        }
    }

    if (decl_is_enum_type(type_target.type_decl) &&
        find_enum_item_decl(type_target.type_decl, expr->as.member.member) != NULL) {
        return inferred_expr_type_from_decl(type_target.type_decl);
    }

    {
        ResolvedModuleMemberTarget module_target;

        if (resolve_module_member_target(context, expr, &module_target)) {
            const FengDecl *binding_decl =
                find_module_public_binding_decl(module_target.module,
                                                module_target.member_name);

            if (binding_decl != NULL &&
                binding_decl->kind == FENG_DECL_GLOBAL_BINDING) {
                return infer_global_binding_decl_type(context, binding_decl);
            }

            return inferred_expr_type_unknown();
        }
    }

    InferredExprType owner_type = infer_expr_type(context, expr->as.member.object);
    const FengDecl *owner_type_decl;
    const FengTypeMember *field_member;

    {
        SpecMemberSurface surface;

        memset(&surface, 0, sizeof(surface));
        if (find_generic_param_spec_member_surface(
                context,
                owner_type,
                expr->as.member.member,
                /*include_static=*/false,
                &surface) &&
            surface.member->kind == FENG_TYPE_MEMBER_FIELD) {
            const FengTypeRef *closed_field =
                substitute_spec_member_type_ref_for_instance(
                    context,
                    surface.declaring_spec,
                    surface.declaring_spec_type_ref,
                    surface.member->as.field.type);

            return closed_field != NULL
                       ? inferred_expr_type_from_type_ref(closed_field)
                       : inferred_expr_type_unknown();
        }
    }

    owner_type_decl = resolve_inferred_expr_type_decl(context, owner_type);

    if (owner_type_decl == NULL) {
        return inferred_expr_type_unknown();
    }

    field_member = find_type_field_member(owner_type_decl, expr->as.member.member);
    if (field_member == NULL && owner_type_decl->kind == FENG_DECL_SPEC) {
        const FengTypeMember *spec_member =
            find_spec_object_member(context, owner_type_decl, expr->as.member.member, /*include_static=*/false);

        if (spec_member == NULL &&
            owner_type_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
            /* Intersection-form spec: search each flattened member's closure
             * for the field accessor. */
            const FengIntersectionSpecInfo *info =
                feng_semantic_lookup_intersection_spec_info(context->analysis,
                                                            owner_type_decl);
            if (info != NULL) {
                for (size_t mi = 0U; mi < info->flattened_member_count && spec_member == NULL; ++mi) {
                    spec_member = find_spec_object_member(context,
                                                          info->flattened_members[mi],
                                                          expr->as.member.member,
                                                          /*include_static=*/false);
                }
            }
        }
        if (spec_member != NULL && spec_member->kind == FENG_TYPE_MEMBER_FIELD) {
            field_member = spec_member;
        }
    }
    if (field_member == NULL) {
        return inferred_expr_type_unknown();
    }

    if (field_member->as.field.type != NULL) {
        return inferred_expr_type_from_type_ref(
            substitute_type_ref_for_owner_instance(context,
                                                   owner_type_decl,
                                                   owner_type,
                                                   field_member->as.field.type));
    }

    if (context->analysis != NULL) {
        const FengSemanticTypeFact *fact =
            feng_semantic_lookup_type_fact(context->analysis, field_member);

        if (fact != NULL && fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF) {
            return inferred_expr_type_from_type_ref(
                substitute_type_ref_for_owner_instance(context,
                                                       owner_type_decl,
                                                       owner_type,
                                                       fact->type_ref));
        }
        return inferred_expr_type_from_type_fact(fact);
    }

    return inferred_expr_type_unknown();
}

static bool exprs_structurally_equal(const FengExpr *a, const FengExpr *b) {
    if (a == b) {
        return true;
    }
    if (a == NULL || b == NULL || a->kind != b->kind) {
        return false;
    }
    switch (a->kind) {
        case FENG_EXPR_SELF:
            return true;
        case FENG_EXPR_IDENTIFIER:
            return slice_equals(a->as.identifier, b->as.identifier);
        case FENG_EXPR_MEMBER:
            return slice_equals(a->as.member.member, b->as.member.member) &&
                   exprs_structurally_equal(a->as.member.object, b->as.member.object);
        default:
            return false;
    }
}

static InferredExprType lookup_expr_narrowing(const ResolveContext *context,
                                              const FengExpr *expr) {
    size_t i;

    for (i = context->expr_narrowing_count; i > 0U; --i) {
        if (exprs_structurally_equal(expr, context->expr_narrowings[i - 1U].target_expr)) {
            return context->expr_narrowings[i - 1U].narrowed_type;
        }
    }
    return inferred_expr_type_unknown();
}

/* Check whether a pure numeric literal expression fits a target type
 * described by InferredExprType (as opposed to FengTypeRef).  Used by
 * the binary-operation literal adaptation path in infer_expr_type. */
static bool numeric_literal_fits_inferred_target(ResolveContext *context,
                                                 const FengExpr *literal_expr,
                                                 InferredExprType target_type) {
    const char *canonical = inferred_expr_type_builtin_canonical_name(
        target_type, context->pointer_size);
    FengConstValue value;
    bool target_is_float;

    if (canonical == NULL) return false;
    target_is_float = strcmp(canonical, "f32") == 0 || strcmp(canonical, "f64") == 0;
    if (!evaluate_constant_expr(context, literal_expr, &value)) return false;
    if (value.kind == FENG_CONST_INT) {
        return target_is_float || integer_literal_fits_canonical_target(value.i, canonical);
    }
    if (value.kind == FENG_CONST_FLOAT) {
        return target_is_float;
    }
    return false;
}

/* Fill expr->type from an InferredExprType, storing the derivation result on
 * the AST node so validation can read it directly without re-invoking
 * infer_expr_type.  BUILTIN synthesizes a named FengTypeRef (analysis-
 * tracked); TYPE_REF borrows via clone; DECL/LAMBDA/UNKNOWN leave expr->type
 * unchanged (such operands are invalid in binary operations anyway).  Does
 * not overwrite a non-NULL expr->type (e.g., already set by adaptation). */
static void fill_expr_type_from_inferred(ResolveContext *context,
                                         FengExpr *expr,
                                         const InferredExprType *type) {
    FengTypeRef *synth;
    FengTypeRef *clone;

    if (expr == NULL || expr->type != NULL || type == NULL) {
        return;
    }
    synth = create_type_ref_from_inferred_type(type, expr->token);
    if (synth == NULL) {
        return;
    }
    clone = clone_type_ref_for_inference(synth);
    free_synthetic_type_ref(synth);
    if (clone != NULL &&
        analysis_track_synthetic_type_ref(context->analysis, clone)) {
        expr->type = clone;
    } else {
        free_synthetic_type_ref(clone);
    }
}

static InferredExprType infer_expr_type(ResolveContext *context, const FengExpr *expr) {
    size_t index;

    if (expr == NULL) {
        return inferred_expr_type_unknown();
    }

    if (context->expr_narrowing_count > 0U) {
        InferredExprType narrowed = lookup_expr_narrowing(context, expr);

        if (inferred_expr_type_is_known(narrowed)) {
            return narrowed;
        }
    }

    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER:
            return infer_identifier_expr_type(context, expr->as.identifier);

        case FENG_EXPR_SELF:
            return context->current_type_decl != NULL
                       ? inferred_expr_type_from_decl(context->current_type_decl)
                       : context->current_fit_target_type_ref != NULL
                           ? inferred_expr_type_from_fit_target_type_ref(
                                 context->current_fit_target_type_ref)
                       : inferred_expr_type_unknown();

        case FENG_EXPR_BOOL:
            return inferred_expr_type_builtin("bool");

        case FENG_EXPR_INTEGER:
            /* If adaptation has already set expr->type (e.g., by binary-expr
             * adaptation, compound-assignment adaptation, or if-expr branch
             * adaptation), return the adapted type instead of the default. */
            if (expr->type != NULL) {
                return inferred_expr_type_from_type_ref(expr->type);
            }
            return inferred_expr_type_builtin("int");

        case FENG_EXPR_FLOAT:
            if (expr->type != NULL) {
                return inferred_expr_type_from_type_ref(expr->type);
            }
            return inferred_expr_type_builtin("double");

        case FENG_EXPR_STRING:
            return inferred_expr_type_builtin("string");

        case FENG_EXPR_ARRAY_LITERAL:
            return infer_array_literal_expr_type(context, expr);

        case FENG_EXPR_TUPLE_LITERAL:
            return inferred_expr_type_unknown();

        case FENG_EXPR_ARRAY_NEW: {
            const FengTypeRef *elem_ref = expr->as.array_new.element_type;
            if (elem_ref == NULL) {
                return inferred_expr_type_unknown();
            }
            InferredExprType elem_type = inferred_expr_type_from_type_ref(elem_ref);
            const FengTypeRef *arr_ref = synthesize_array_type_ref(
                context, &elem_type,
                false,
                expr->token);
            return arr_ref != NULL ? inferred_expr_type_from_type_ref(arr_ref)
                                   : inferred_expr_type_unknown();
        }

        case FENG_EXPR_LAMBDA:
            return inferred_expr_type_is_known(infer_lambda_body_type(context, expr))
                       ? inferred_expr_type_from_lambda(expr)
                       : inferred_expr_type_unknown();

        case FENG_EXPR_INDEX: {
            const FengTypeRef *element_type_ref =
                resolve_indexed_array_element_type_ref(context, expr->as.index.object);

            return element_type_ref != NULL &&
                           inferred_expr_type_is_integer(infer_expr_type(context, expr->as.index.index))
                       ? inferred_expr_type_from_type_ref(element_type_ref)
                                            : inferred_expr_type_unknown();
        }

        case FENG_EXPR_OBJECT_LITERAL: {
            ResolvedTypeTarget target =
                resolve_type_target_expr(context, expr->as.object_literal.target, true);
            InferredExprType target_type =
                infer_expr_type(context, expr->as.object_literal.target);

            /* Preserve the complete instantiated target (for example
             * Cell<int>) instead of collapsing it to the generic declaration
             * Cell<T>. Member access and method-value matching both require
             * those concrete owner arguments for type-parameter substitution. */
            if (inferred_expr_type_is_known(target_type)) {
                return target_type;
            }
            return target.type_decl != NULL
                       ? resolved_type_target_owner_type(&target)
                       : inferred_expr_type_unknown();
        }

        case FENG_EXPR_GENERIC_TARGET:
            return inferred_expr_type_unknown();

        case FENG_EXPR_CALL:
            return infer_call_expr_type(context, expr);

        case FENG_EXPR_MEMBER:
            return infer_member_expr_type(context, expr);

        case FENG_EXPR_UNARY: {
            InferredExprType operand_type = infer_expr_type(context, expr->as.unary.operand);

            if (expr->as.unary.op == FENG_TOKEN_AMP) {
                if (inferred_expr_type_is_string(operand_type)) {
                    InferredExprType byte_type = inferred_expr_type_builtin("byte");
                    const FengTypeRef *pointer_type_ref =
                        synthesize_pointer_type_ref_from_inferred_type(
                            context,
                            &byte_type,
                            expr->token);

                    return pointer_type_ref != NULL
                               ? inferred_expr_type_from_type_ref(pointer_type_ref)
                               : inferred_expr_type_unknown();
                }

                if (inferred_expr_type_is_abi_array_value(context, operand_type)) {
                    const FengTypeRef *pointer_type_ref =
                        synthesize_pointer_type_ref_from_inner_type_ref(
                            context,
                            operand_type.type_ref->as.inner,
                            expr->token);

                    return pointer_type_ref != NULL
                               ? inferred_expr_type_from_type_ref(pointer_type_ref)
                               : inferred_expr_type_unknown();
                }

                if (inferred_expr_type_is_data_addressable_abi_value(context, operand_type)) {
                    const FengTypeRef *pointer_type_ref =
                        synthesize_pointer_type_ref_from_inferred_type(
                            context,
                            &operand_type,
                            expr->token);

                    return pointer_type_ref != NULL
                               ? inferred_expr_type_from_type_ref(pointer_type_ref)
                               : inferred_expr_type_unknown();
                }

                return inferred_expr_type_unknown();
            }

            if (expr->as.unary.op == FENG_TOKEN_MINUS &&
                inferred_expr_type_is_numeric(operand_type)) {
                return operand_type;
            }
            if (expr->as.unary.op == FENG_TOKEN_TILDE &&
                inferred_expr_type_is_integer(operand_type)) {
                return operand_type;
            }
            if (expr->as.unary.op == FENG_TOKEN_NOT &&
                inferred_expr_type_is_bool(operand_type)) {
                return inferred_expr_type_builtin("bool");
            }

            return inferred_expr_type_unknown();
        }

        case FENG_EXPR_BINARY: {
            InferredExprType left_type = infer_expr_type(context, expr->as.binary.left);
            InferredExprType right_type = infer_expr_type(context, expr->as.binary.right);
            InferredExprType result_type = inferred_expr_type_unknown();

            /* Binary-operation literal adaptation: when one operand is a
             * pure numeric literal and the other side has a resolved scalar
             * type, adapt the literal to that type.  The result is hung on
             * the literal node's type field for codegen to read directly.
             * When both sides are literals, no adaptation is triggered —
             * each keeps its default inferred type. */
            if (expr_is_pure_numeric_literal_expr_for_target_adaptation(expr->as.binary.right) &&
                !expr_is_pure_numeric_literal_expr_for_target_adaptation(expr->as.binary.left) &&
                inferred_expr_type_is_numeric(left_type)) {
                if (numeric_literal_fits_inferred_target(context, expr->as.binary.right, left_type)) {
                    FengTypeRef *synth = create_type_ref_from_inferred_type(&left_type,
                                                                            expr->token);
                    if (synth != NULL) {
                        /* Clone and transfer to Analysis lifetime so the type
                         * survives ResolveContext teardown for codegen. */
                        FengTypeRef *clone = clone_type_ref_for_inference(synth);
                        free_synthetic_type_ref(synth);
                        if (clone != NULL &&
                            analysis_track_synthetic_type_ref(context->analysis, clone)) {
                            ((FengExpr *)expr->as.binary.right)->type = clone;
                        } else {
                            free_synthetic_type_ref(clone);
                        }
                    }
                    right_type = left_type;
                }
            } else if (expr_is_pure_numeric_literal_expr_for_target_adaptation(expr->as.binary.left) &&
                       !expr_is_pure_numeric_literal_expr_for_target_adaptation(expr->as.binary.right) &&
                       inferred_expr_type_is_numeric(right_type)) {
                if (numeric_literal_fits_inferred_target(context, expr->as.binary.left, right_type)) {
                    FengTypeRef *synth = create_type_ref_from_inferred_type(&right_type,
                                                                            expr->token);
                    if (synth != NULL) {
                        /* Clone and transfer to Analysis lifetime so the type
                         * survives ResolveContext teardown for codegen. */
                        FengTypeRef *clone = clone_type_ref_for_inference(synth);
                        free_synthetic_type_ref(synth);
                        if (clone != NULL &&
                            analysis_track_synthetic_type_ref(context->analysis, clone)) {
                            ((FengExpr *)expr->as.binary.left)->type = clone;
                        } else {
                            free_synthetic_type_ref(clone);
                        }
                    }
                    left_type = right_type;
                }
            }

            switch (expr->as.binary.op) {
                case FENG_TOKEN_PLUS:
                    if (inferred_expr_types_equal(context, left_type, right_type) &&
                        (inferred_expr_type_is_numeric(left_type) ||
                         inferred_expr_type_is_string(left_type))) {
                        result_type = left_type;
                    }
                    break;

                case FENG_TOKEN_MINUS:
                case FENG_TOKEN_STAR:
                case FENG_TOKEN_SLASH:
                case FENG_TOKEN_PERCENT:
                    if (inferred_expr_types_equal(context, left_type, right_type) &&
                        inferred_expr_type_is_numeric(left_type)) {
                        result_type = left_type;
                    }
                    break;

                case FENG_TOKEN_LT:
                case FENG_TOKEN_LE:
                case FENG_TOKEN_GT:
                case FENG_TOKEN_GE:
                    if (inferred_expr_types_equal(context, left_type, right_type) &&
                        inferred_expr_type_is_numeric(left_type)) {
                        result_type = inferred_expr_type_builtin("bool");
                    }
                    break;

                case FENG_TOKEN_EQ:
                case FENG_TOKEN_NE:
                    if (inferred_expr_type_is_known(left_type) &&
                        inferred_expr_type_is_known(right_type) &&
                        inferred_expr_types_equal(context, left_type, right_type)) {
                        result_type = inferred_expr_type_builtin("bool");
                    }
                    break;

                case FENG_TOKEN_AND_AND:
                case FENG_TOKEN_OR_OR:
                    if (inferred_expr_type_is_bool(left_type) &&
                        inferred_expr_type_is_bool(right_type)) {
                        result_type = inferred_expr_type_builtin("bool");
                    }
                    break;

                case FENG_TOKEN_AMP:
                case FENG_TOKEN_PIPE:
                case FENG_TOKEN_CARET:
                case FENG_TOKEN_SHL:
                case FENG_TOKEN_SHR:
                    if (inferred_expr_types_equal(context, left_type, right_type) &&
                        inferred_expr_type_is_integer(left_type)) {
                        result_type = left_type;
                    }
                    break;

                default:
                    break;
            }

            /* Fill derivation results onto the AST nodes so validation can
             * read them directly without re-invoking infer_expr_type.  The
             * outer binary reads the inner binary's expr->type; the operands
             * carry their post-adaptation type.  fill_expr_type_from_inferred
             * skips nodes already filled (e.g., by adaptation above). */
            fill_expr_type_from_inferred(context, (FengExpr *)expr->as.binary.left, &left_type);
            fill_expr_type_from_inferred(context, (FengExpr *)expr->as.binary.right, &right_type);
            fill_expr_type_from_inferred(context, (FengExpr *)expr, &result_type);
            return result_type;
        }

        case FENG_EXPR_CAST:
            if (expr->as.cast.value != NULL &&
                expr->as.cast.value->kind == FENG_EXPR_TUPLE_LITERAL &&
                tuple_literal_matches_tuple_type_ref(context,
                                                     expr->as.cast.value,
                                                     expr->as.cast.type)) {
                return inferred_expr_type_from_type_ref(expr->as.cast.type);
            }
            if (resolve_function_type_decl(context, expr->as.cast.type) != NULL &&
                resolve_expr_callable_value(context,
                                            expr->as.cast.value,
                                            expr->as.cast.type).kind ==
                    FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE) {
                return inferred_expr_type_from_type_ref(expr->as.cast.type);
            }
            return cast_expr_types_are_valid(context,
                                             infer_expr_type(context, expr->as.cast.value),
                                             expr->as.cast.type)
                       ? inferred_expr_type_from_type_ref(expr->as.cast.type)
                       : inferred_expr_type_unknown();

        case FENG_EXPR_IF: {
            InferredExprType condition_type = infer_expr_type(context, expr->as.if_expr.condition);
            InferredExprType then_type;
            InferredExprType else_type;

            if (expr->type != NULL) {
                return inferred_expr_type_from_type_ref(expr->type);
            }
            if (!inferred_expr_type_is_bool(condition_type)) {
                return inferred_expr_type_unknown();
            }

            then_type = block_yield_inferred_type(context, expr->as.if_expr.then_block);
            else_type = block_yield_inferred_type(context, expr->as.if_expr.else_block);

            /* Return/throw-only branches contribute no yield value, so their
             * inferred type is unknown. Pick the first known branch type;
             * when neither branch yields, the result type stays unknown. */
            if (inferred_expr_type_is_known(then_type)) {
                return then_type;
            }
            return else_type;
        }

        case FENG_EXPR_MATCH: {
            if (expr->type != NULL) {
                return inferred_expr_type_from_type_ref(expr->type);
            }
            InferredExprType result_type =
                block_yield_inferred_type(context, expr->as.match_expr.else_block);

            /* If the else branch exits without a result (or its type is
             * otherwise unknown), fall back to the first known branch type. */
            if (!inferred_expr_type_is_known(result_type)) {
                for (index = 0U; index < expr->as.match_expr.branch_count; ++index) {
                    if (block_exits_via_return_or_throw(expr->as.match_expr.branches[index].body)) {
                        continue;
                    }
                    result_type =
                        block_yield_inferred_type(context, expr->as.match_expr.branches[index].body);
                    if (inferred_expr_type_is_known(result_type)) {
                        break;
                    }
                }
            }

            if (!inferred_expr_type_is_known(result_type)) {
                return result_type;
            }

            for (index = 0U; index < expr->as.match_expr.branch_count; ++index) {
                InferredExprType branch_type;

                /* Return/throw-only branches do not produce a result value,
                 * so they do not participate in type consistency checks. */
                if (block_exits_via_return_or_throw(expr->as.match_expr.branches[index].body)) {
                    continue;
                }
                branch_type =
                    block_yield_inferred_type(context, expr->as.match_expr.branches[index].body);

                if (!inferred_expr_type_is_known(branch_type)) {
                    continue;
                }
                if (!inferred_expr_types_equal(context, result_type, branch_type)) {
                    return inferred_expr_type_unknown();
                }
            }

            return result_type;
        }

        case FENG_EXPR_TRY: {
            if (expr->type != NULL) {
                return inferred_expr_type_from_type_ref(expr->type);
            }
            return infer_expr_type(context, expr->as.try_expr.body);
        }

        case FENG_EXPR_MATCH_OP: {
            /* infix match operator always yields bool */
            return inferred_expr_type_builtin("bool");
        }

        default:
            return inferred_expr_type_unknown();
    }
}

static bool lambda_expr_matches_function_type(ResolveContext *context,
                                              const FengExpr *expr,
                                              const FengTypeRef *function_type_ref,
                                              const FengDecl *function_type_decl) {
    size_t param_index;
    bool ok = true;
    bool matches = false;

    if (expr == NULL || expr->kind != FENG_EXPR_LAMBDA || function_type_decl == NULL ||
        !decl_is_function_type(function_type_decl)) {
        return false;
    }
    if (expr->as.lambda.param_count != function_type_decl->as.spec_decl.as.callable.param_count) {
        return false;
    }

    for (param_index = 0U; param_index < expr->as.lambda.param_count; ++param_index) {
        const FengParameter *expected_decl_param =
            &function_type_decl->as.spec_decl.as.callable.params[param_index];
        const FengParameter *actual_decl_param =
            &expr->as.lambda.params[param_index];
        const FengTypeRef *expected_param = substitute_spec_member_type_ref_for_instance(
            context,
            function_type_decl,
            function_type_ref,
            expected_decl_param->type);

        if (!callable_parameter_forms_match(expected_decl_param,
                                            actual_decl_param) ||
            !type_refs_semantically_equal(context,
                                          actual_decl_param->type,
                                          expected_param)) {
            return false;
        }
    }

    if (!resolver_push_scope(context)) {
        return false;
    }

    for (param_index = 0U; param_index < expr->as.lambda.param_count && ok; ++param_index) {
        ok = resolver_add_local_typed_name(context,
                                           expr->as.lambda.params[param_index].name,
                                           inferred_expr_type_from_type_ref(
                                               expr->as.lambda.params[param_index].type),
                                           expr->as.lambda.params[param_index].mutability);
    }
    if (ok) {
        const FengTypeRef *expected_return = substitute_spec_member_type_ref_for_instance(
            context,
            function_type_decl,
            function_type_ref,
            function_type_decl->as.spec_decl.as.callable.return_type);

        if (expr->as.lambda.is_block_body) {
            InferredExprType expected =
                inferred_expr_type_from_return_type_ref(expected_return);
            bool expected_is_void = inferred_expr_type_is_void(expected);
            bool saw_return = false;
            bool return_values_match;
            bool saved_suppress_literal_type_commit =
                context->suppress_literal_type_commit;

            /* Candidate probing reads return-expression facts captured while
             * the Lambda's real lexical scopes were active and must not
             * commit a candidate-specific literal type. */
            context->suppress_literal_type_commit = true;
            return_values_match =
                lambda_return_values_fit_target_in_block(
                    context,
                    expr->as.lambda.body_block,
                    expected_return,
                    LAMBDA_RETURN_TARGET_MATCH_ONLY,
                    &saw_return);
            context->suppress_literal_type_commit =
                saved_suppress_literal_type_commit;
            matches = inferred_expr_type_is_known(expected) &&
                      return_values_match &&
                      (expected_is_void || saw_return ||
                       !callable_body_can_fall_through(
                           expr->as.lambda.body_block));
        } else {
            matches = expr_matches_expected_type_ref(
                context,
                expr->as.lambda.body,
                expected_return);
        }
    }

    resolver_pop_scope(context);
    return ok && matches;
}

static bool lambda_expr_signature_matches_lambda_expr(ResolveContext *context,
                                                      const FengExpr *left,
                                                      const FengExpr *right) {
    size_t param_index;
    InferredExprType left_body_type;
    InferredExprType right_body_type;

    if (left == NULL || right == NULL || left->kind != FENG_EXPR_LAMBDA ||
        right->kind != FENG_EXPR_LAMBDA || left->as.lambda.param_count != right->as.lambda.param_count) {
        return false;
    }

    for (param_index = 0U; param_index < left->as.lambda.param_count; ++param_index) {
        const FengParameter *left_param = &left->as.lambda.params[param_index];
        const FengParameter *right_param = &right->as.lambda.params[param_index];

        if (!callable_parameter_forms_match(left_param, right_param) ||
            !type_refs_semantically_equal(context,
                                          left_param->type,
                                          right_param->type)) {
            return false;
        }
    }

    left_body_type = infer_lambda_body_type(context, left);
    right_body_type = infer_lambda_body_type(context, right);
    return inferred_expr_type_is_known(left_body_type) &&
           inferred_expr_type_is_known(right_body_type) &&
           inferred_expr_types_equal(context, left_body_type, right_body_type);
}

/* Resolve `function<T...>`, `object.method<T...>`, or
 * `Concrete.method<T...>` against a target callable form. The explicit
 * arguments close only the selected source callable's own generic parameters;
 * no target-driven inference is performed here. */
static CallableValueResolution resolve_explicit_generic_callable_value(
    ResolveContext *context,
    const FengExpr *expr,
    const FengTypeRef *expected_type_ref,
    const FengDecl *function_type_decl) {
    CallableValueResolution result;
    const FengExpr *target;
    const FengTypeRef *const *explicit_type_args;
    size_t explicit_type_arg_count;

    memset(&result, 0, sizeof(result));
    if (context == NULL || expr == NULL ||
        expr->kind != FENG_EXPR_GENERIC_TARGET ||
        function_type_decl == NULL) {
        return result;
    }
    target = expr->as.generic_target.target;
    explicit_type_args = (const FengTypeRef *const *)
        expr->as.generic_target.type_args;
    explicit_type_arg_count = expr->as.generic_target.type_arg_count;

    if (target != NULL && target->kind == FENG_EXPR_IDENTIFIER) {
        const FunctionOverloadSetEntry *overload_set;

        /* A local callable value is already a closed value and cannot acquire
         * callable-local type arguments through generic-target syntax. */
        if (resolver_find_local_name_entry(context,
                                           target->as.identifier) != NULL) {
            return result;
        }
        overload_set = find_function_overload_set(context->function_sets,
                                                  context->function_set_count,
                                                  target->as.identifier);
        return resolve_top_level_function_value_overload(
            context,
            overload_set,
            expected_type_ref,
            function_type_decl,
            explicit_type_args,
            explicit_type_arg_count);
    }

    if (target != NULL && target->kind == FENG_EXPR_MEMBER) {
        const FengExpr *object = target->as.member.object;
        ResolvedModuleMemberTarget module_target;

        if (resolve_module_member_target(
                context, target, &module_target)) {
            return resolve_module_public_function_value_overload(
                context,
                module_target.module,
                module_target.member_name,
                expected_type_ref,
                function_type_decl,
                explicit_type_args,
                explicit_type_arg_count);
        }

        {
            ResolvedTypeTarget static_target =
                resolve_type_target_expr(context, object, false);

            if (static_target.type_decl != NULL ||
                static_target.is_builtin_type_name) {
                return resolve_concrete_static_method_value(
                    context,
                    &static_target,
                    target->as.member.member,
                    expected_type_ref,
                    function_type_decl,
                    explicit_type_args,
                    explicit_type_arg_count);
            }
        }

        {
            const FengDecl *owner_type_decl = NULL;
            const FengSemanticModule *provider_module = NULL;
            InferredExprType owner_type = resolve_expr_owner_type(
                context,
                object,
                &owner_type_decl,
                &provider_module);
            CallableValueResolution method_result;
            CallableValueResolution fit_result;

            memset(&method_result, 0, sizeof(method_result));
            if (owner_type_decl != NULL &&
                owner_type_decl->kind == FENG_DECL_TYPE) {
                method_result = resolve_accessible_method_value_overload(
                    context,
                    owner_type_decl,
                    provider_module,
                    owner_type,
                    target->as.member.member,
                    expected_type_ref,
                    function_type_decl,
                    explicit_type_args,
                    explicit_type_arg_count,
                    false);
            }
            fit_result = resolve_accessible_fit_method_value_overload(
                context,
                owner_type_decl,
                owner_type,
                target->as.member.member,
                expected_type_ref,
                function_type_decl,
                explicit_type_args,
                explicit_type_arg_count,
                false);
            return merge_callable_value_resolutions(method_result,
                                                    fit_result);
        }
    }

    return result;
}

static CallableValueResolution resolve_expr_callable_value(ResolveContext *context,
                                                           const FengExpr *expr,
                                                           const FengTypeRef *expected_type_ref) {
    CallableValueResolution result;
    const FengDecl *function_type_decl;
    InferredExprType recorded_expr_type;
    bool requires_abi_callable;

    memset(&result, 0, sizeof(result));
    function_type_decl = resolve_function_type_decl(context, expected_type_ref);
    if (expr == NULL || function_type_decl == NULL) {
        return result;
    }

    requires_abi_callable =
        function_type_decl_is_abi_callable_type(function_type_decl);

    /* Delayed block-Lambda target checks run after the Lambda's lexical
     * scopes have been popped.  Prefer the exact expression-site fact saved
     * while that scope was active; recreating lookup from an identifier name
     * can otherwise lose a child local or resolve a same-name parameter.
     * Overload and Lambda sources have no closed type fact here and continue
     * through the normal source-specific resolution below. */
    recorded_expr_type = inferred_expr_type_from_type_fact(
        context != NULL && context->analysis != NULL
            ? feng_semantic_lookup_type_fact(context->analysis, expr)
            : NULL);
    if (inferred_expr_type_is_known(recorded_expr_type) &&
        inferred_expr_type_matches_type_ref(context,
                                            recorded_expr_type,
                                            expected_type_ref) &&
        (!requires_abi_callable ||
         inferred_expr_type_can_match_abi_callable_type(recorded_expr_type))) {
        result.kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
        return result;
    }

    switch (expr->kind) {
        case FENG_EXPR_GENERIC_TARGET:
            return resolve_explicit_generic_callable_value(context,
                                                           expr,
                                                           expected_type_ref,
                                                           function_type_decl);

        case FENG_EXPR_IDENTIFIER: {
            const LocalNameEntry *local_entry =
                resolver_find_local_name_entry(context, expr->as.identifier);
            const FunctionOverloadSetEntry *overload_set;
            InferredExprType expr_type;

            if (local_entry != NULL) {
                if (inferred_expr_type_matches_type_ref(context, local_entry->type, expected_type_ref) &&
                    (!requires_abi_callable ||
                     inferred_expr_type_can_match_abi_callable_type(local_entry->type))) {
                    result.kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
                    result.callable_decl = NULL;
                    result.callable_member = NULL;
                    result.callable_owner_type_decl = NULL;
                    result.callable_fit_decl = NULL;
                    result.lambda_expr = local_entry->type.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA
                                             ? local_entry->type.lambda_expr
                                             : NULL;
                }
                return result;
            }

            overload_set = find_function_overload_set(context->function_sets,
                                                      context->function_set_count,
                                                      expr->as.identifier);
            if (overload_set != NULL) {
                return resolve_top_level_function_value_overload(context,
                                                                 overload_set,
                                                                 expected_type_ref,
                                                                 function_type_decl,
                                                                 NULL,
                                                                 0U);
            }

            expr_type = infer_identifier_expr_type(context, expr->as.identifier);
            if (inferred_expr_type_is_known(expr_type) &&
                inferred_expr_type_matches_type_ref(context, expr_type, expected_type_ref)) {
                result.kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
                result.callable_decl = NULL;
                result.callable_member = NULL;
                result.callable_owner_type_decl = NULL;
                result.callable_fit_decl = NULL;
            }
            return result;
        }

        case FENG_EXPR_MEMBER: {
            const FengExpr *object = expr->as.member.object;
            InferredExprType expr_type;
            ResolvedModuleMemberTarget module_target;

            if (resolve_module_member_target(
                    context, expr, &module_target)) {
                result = resolve_module_public_function_value_overload(
                    context,
                    module_target.module,
                    module_target.member_name,
                    expected_type_ref,
                    function_type_decl,
                    NULL,
                    0U);
                if (result.kind != FENG_CALLABLE_VALUE_RESOLUTION_NONE) {
                    return result;
                }

                expr_type = infer_member_expr_type(context, expr);
                if (inferred_expr_type_is_known(expr_type) &&
                    inferred_expr_type_matches_type_ref(
                        context, expr_type, expected_type_ref)) {
                    result.kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
                    result.callable_decl = NULL;
                    result.callable_member = NULL;
                    result.callable_owner_type_decl = NULL;
                    result.callable_fit_decl = NULL;
                }
                return result;
            }

            {
                ResolvedTypeTarget static_target =
                    resolve_type_target_expr(context, object, false);

                if (static_target.type_decl != NULL ||
                    static_target.is_builtin_type_name) {
                    return resolve_concrete_static_method_value(
                        context,
                        &static_target,
                        expr->as.member.member,
                        expected_type_ref,
                        function_type_decl,
                        NULL,
                        0U);
                }
                if (static_target.is_generic_type_param &&
                    static_target.constraint_spec_decl != NULL &&
                    (static_target.constraint_spec_decl->as.spec_decl.form ==
                         FENG_SPEC_FORM_OBJECT ||
                     static_target.constraint_spec_decl->as.spec_decl.form ==
                         FENG_SPEC_FORM_INTERSECTION)) {
                    InferredExprType constraint_owner =
                        static_target.constraint_spec_type_ref != NULL
                            ? inferred_expr_type_from_type_ref(
                                  static_target.constraint_spec_type_ref)
                            : inferred_expr_type_from_decl(
                                  static_target.constraint_spec_decl);

                    return resolve_spec_method_value_overload(
                        context,
                        static_target.constraint_spec_decl,
                        constraint_owner,
                        expr->as.member.member,
                        expected_type_ref,
                        function_type_decl,
                        true,
                        true);
                }
            }

            {
                const FengDecl *owner_type_decl = NULL;
                const FengDecl *generic_constraint_decl = NULL;
                const FengTypeRef *generic_constraint_ref = NULL;
                const FengSemanticModule *provider_module = NULL;
                InferredExprType owner_type;
                CallableValueResolution fit_result;

                owner_type = resolve_expr_owner_type(context,
                                                     object,
                                                     &owner_type_decl,
                                                     &provider_module);
                if (owner_type_decl != NULL && owner_type_decl->kind == FENG_DECL_TYPE) {
                    result = resolve_accessible_method_value_overload(context,
                                                                      owner_type_decl,
                                                                      provider_module,
                                                                      owner_type,
                                                                      expr->as.member.member,
                                                                      expected_type_ref,
                                                                      function_type_decl,
                                                                      NULL,
                                                                      0U,
                                                                      false);
                } else if (owner_type_decl != NULL &&
                           owner_type_decl->kind == FENG_DECL_SPEC &&
                           (owner_type_decl->as.spec_decl.form ==
                                FENG_SPEC_FORM_OBJECT ||
                            owner_type_decl->as.spec_decl.form ==
                                FENG_SPEC_FORM_INTERSECTION)) {
                    result = resolve_spec_method_value_overload(
                        context,
                        owner_type_decl,
                        owner_type,
                        expr->as.member.member,
                        expected_type_ref,
                        function_type_decl,
                        false,
                        true);
                } else if (owner_type_decl == NULL &&
                           resolve_generic_param_spec_constraint(
                               context,
                               owner_type,
                               &generic_constraint_decl,
                               &generic_constraint_ref) &&
                           (generic_constraint_decl->as.spec_decl.form ==
                                FENG_SPEC_FORM_OBJECT ||
                            generic_constraint_decl->as.spec_decl.form ==
                                FENG_SPEC_FORM_INTERSECTION)) {
                    result = resolve_spec_method_value_overload(
                        context,
                        generic_constraint_decl,
                        inferred_expr_type_from_type_ref(
                            generic_constraint_ref),
                        expr->as.member.member,
                        expected_type_ref,
                        function_type_decl,
                        false,
                        true);
                    if (result.kind ==
                        FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE) {
                        /* Keep the complete constraint surface alongside the
                         * selected requirement. The coercion sidecar records
                         * the receiver expression separately as T. */
                        result.callable_owner_type_decl =
                            generic_constraint_decl;
                    }
                }
                memset(&fit_result, 0, sizeof(fit_result));
                if (generic_constraint_decl == NULL &&
                    (owner_type_decl == NULL ||
                     owner_type_decl->kind != FENG_DECL_SPEC)) {
                    fit_result = resolve_accessible_fit_method_value_overload(
                        context,
                        owner_type_decl,
                        owner_type,
                        expr->as.member.member,
                        expected_type_ref,
                        function_type_decl,
                        NULL,
                        0U,
                        false);
                }
                result = merge_callable_value_resolutions(result,
                                                          fit_result);
                if (result.kind != FENG_CALLABLE_VALUE_RESOLUTION_NONE) {
                    return result;
                }
            }

            expr_type = infer_member_expr_type(context, expr);
            if (inferred_expr_type_is_known(expr_type) &&
                inferred_expr_type_matches_type_ref(context, expr_type, expected_type_ref)) {
                result.kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
                result.callable_decl = NULL;
                result.callable_member = NULL;
                result.callable_owner_type_decl = NULL;
                result.callable_fit_decl = NULL;
            }
            return result;
        }

        case FENG_EXPR_LAMBDA:
            if (requires_abi_callable) {
                return result;
            }
            if (lambda_expr_matches_function_type(context,
                                                  expr,
                                                  expected_type_ref,
                                                  function_type_decl)) {
                result.kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
                result.callable_decl = NULL;
                result.callable_member = NULL;
                result.callable_owner_type_decl = NULL;
                result.callable_fit_decl = NULL;
                result.lambda_expr = expr;
            }
            return result;

        default: {
            InferredExprType expr_type = infer_expr_type(context, expr);

            if (inferred_expr_type_is_known(expr_type) &&
                inferred_expr_type_matches_type_ref(context, expr_type, expected_type_ref)) {
                result.kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
                result.callable_decl = NULL;
                result.callable_member = NULL;
                result.callable_owner_type_decl = NULL;
                result.callable_fit_decl = NULL;
            } else if (expr_type_inference_is_pending(context, expr)) {
                result.kind = FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
                result.callable_decl = NULL;
                result.callable_member = NULL;
                result.callable_owner_type_decl = NULL;
                result.callable_fit_decl = NULL;
            }
            return result;
        }
    }
}

static bool expr_matches_expected_type_ref_when_inference_unknown(
    ResolveContext *context,
    const FengExpr *expr,
    const FengTypeRef *expected_type_ref) {
    size_t item_index;

    if (expr == NULL || expected_type_ref == NULL) {
        return false;
    }
    if (expected_type_ref->kind != FENG_TYPE_REF_ARRAY) {
        return false;
    }

    if (expr->kind == FENG_EXPR_ARRAY_NEW) {
        InferredExprType element_type =
            inferred_expr_type_from_type_ref(expr->as.array_new.element_type);

        return inferred_expr_type_is_known(element_type) &&
               inferred_expr_type_matches_type_ref(context,
                                                  element_type,
                                                  expected_type_ref->as.inner);
    }

    if (expr->kind != FENG_EXPR_ARRAY_LITERAL) {
        return false;
    }

    for (item_index = 0U; item_index < expr->as.array_literal.count; ++item_index) {
        if (!expr_matches_expected_type_ref(context,
                                            expr->as.array_literal.items[item_index],
                                            expected_type_ref->as.inner)) {
            return false;
        }
    }

    return true;
}

/* Compile-time range check for an integer literal against a canonical integer target.
 * Per docs/specifications/feng-builtin-type.md §17: literals that overflow the target are compile errors. */
static bool integer_literal_fits_canonical_target(int64_t value, const char *canonical_target) {
    if (canonical_target == NULL) {
        return false;
    }
    if (strcmp(canonical_target, "i8") == 0) {
        return value >= INT8_MIN && value <= INT8_MAX;
    }
    if (strcmp(canonical_target, "i16") == 0) {
        return value >= INT16_MIN && value <= INT16_MAX;
    }
    if (strcmp(canonical_target, "i32") == 0) {
        return value >= INT32_MIN && value <= INT32_MAX;
    }
    if (strcmp(canonical_target, "i64") == 0) {
        return true;
    }
    if (strcmp(canonical_target, "u8") == 0) {
        return value >= 0 && value <= (int64_t)UINT8_MAX;
    }
    if (strcmp(canonical_target, "u16") == 0) {
        return value >= 0 && value <= (int64_t)UINT16_MAX;
    }
    if (strcmp(canonical_target, "u32") == 0) {
        return value >= 0 && value <= (int64_t)UINT32_MAX;
    }
    if (strcmp(canonical_target, "u64") == 0) {
        return value >= 0;
    }
    return false;
}

/* ---------------------------------------------------------------------------
 * Compile-time constant evaluation (per docs/specifications/feng-expression.md §3.x and §6.x)
 *
 * Folds integer/float/bool literals, unary `-` `~` `!`, binary arithmetic
 * (`+ - * / %`), bitwise (`& | ^ << >>`), comparisons (`< <= > >= == !=`),
 * logical (`&& ||`), cast `(T)expr` against numeric targets, and identifier
 * references that bind immutably to a foldable initializer.
 *
 * Diagnostics emitted at compile-time:
 *   - integer division/modulo by zero
 *   - integer overflow during + - and * (per i64 semantics; range-narrowing is
 *     deferred to numeric_literal_adapts_to_target's target-type check)
 *
 * Identifier propagation honours immutability: only `let` bindings whose
 * initializer is itself foldable participate. Cycles are guarded via the
 * stack-threaded ConstEvalGuard chain.
 * --------------------------------------------------------------------------- */

static FengConstValue const_int_value(int64_t v) {
    FengConstValue r;
    r.kind = FENG_CONST_INT;
    r.i = v;
    r.integer_is_unsigned = false;
    r.f = 0.0;
    r.b = false;
    return r;
}

/* Preserve all bits of one unsigned compile-time integer without forcing the
 * upper half of the u64 domain through signed-overflow arithmetic. */
static FengConstValue const_uint_value(uint64_t v) {
    FengConstValue r = const_int_value((int64_t)v);

    r.integer_is_unsigned = true;
    return r;
}

/* Refine a folded integer with an already resolved Feng integer type.  The
 * parser stores every integer literal in one int64_t bit container, so the
 * semantic type is the source of truth for whether the upper half of that
 * container belongs to an unsigned value. */
static void const_integer_apply_inferred_type(
    const ResolveContext *context,
    InferredExprType type,
    FengConstValue *value) {
    const char *canonical;

    if (context == NULL || value == NULL || value->kind != FENG_CONST_INT) {
        return;
    }
    canonical = inferred_expr_type_builtin_canonical_name(
        type, context->pointer_size);
    if (canonical_integer_bit_width(canonical) > 0) {
        value->integer_is_unsigned = canonical[0] == 'u';
    }
}

static FengConstValue const_float_value(double v) {
    FengConstValue r;
    r.kind = FENG_CONST_FLOAT;
    r.i = 0;
    r.integer_is_unsigned = false;
    r.f = v;
    r.b = false;
    return r;
}

static FengConstValue const_bool_value(bool v) {
    FengConstValue r;
    r.kind = FENG_CONST_BOOL;
    r.i = 0;
    r.integer_is_unsigned = false;
    r.f = 0.0;
    r.b = v;
    return r;
}

/* If either operand is FLOAT, promote the other from INT to FLOAT in-place. */
static bool promote_const_pair(FengConstValue *a, FengConstValue *b) {
    if (a->kind == FENG_CONST_FLOAT && b->kind == FENG_CONST_INT) {
        *b = const_float_value(b->integer_is_unsigned
                                   ? (double)(uint64_t)b->i
                                   : (double)b->i);
    } else if (b->kind == FENG_CONST_FLOAT && a->kind == FENG_CONST_INT) {
        *a = const_float_value(a->integer_is_unsigned
                                   ? (double)(uint64_t)a->i
                                   : (double)a->i);
    }
    return a->kind == b->kind;
}

/* Truncate `value` (treated as an unbounded integer) to the target builtin's bit pattern,
 * mirroring the C-style cast semantics promised by docs/specifications/feng-expression.md §3.4
 * ("整数到更小位宽整数的转换会按目标位宽截断高位"). The result is re-encoded as i64. */
static int64_t truncate_int_to_canonical(int64_t value, const char *canonical_target) {
    if (canonical_target == NULL) {
        return value;
    }
    uint64_t bits = (uint64_t)value;
    if (strcmp(canonical_target, "i8") == 0)  return (int64_t)(int8_t)bits;
    if (strcmp(canonical_target, "i16") == 0) return (int64_t)(int16_t)bits;
    if (strcmp(canonical_target, "i32") == 0) return (int64_t)(int32_t)bits;
    if (strcmp(canonical_target, "i64") == 0) return (int64_t)bits;
    if (strcmp(canonical_target, "u8") == 0)  return (int64_t)(uint64_t)(uint8_t)bits;
    if (strcmp(canonical_target, "u16") == 0) return (int64_t)(uint64_t)(uint16_t)bits;
    if (strcmp(canonical_target, "u32") == 0) return (int64_t)(uint64_t)(uint32_t)bits;
    if (strcmp(canonical_target, "u64") == 0) return (int64_t)bits;
    return value;
}

static bool guard_contains(const ConstEvalGuard *g, const FengExpr *expr) {
    while (g != NULL) {
        if (g->expr == expr) {
            return true;
        }
        g = g->prev;
    }
    return false;
}

static bool evaluate_constant_expr_inner(ResolveContext *context,
                                         const FengExpr *expr,
                                         FengConstValue *out,
                                         ConstEvalGuard *guard);

/* Resolve `name` to its compile-time foldable value when the binding is immutable and
 * has an initializer that itself folds. Returns false otherwise.
 * token 用于歧义错误定位(常量上下文中触发 AE0005 时)。 */
static bool evaluate_constant_identifier(ResolveContext *context,
                                         FengToken token,
                                         FengSlice name,
                                         FengConstValue *out,
                                         ConstEvalGuard *guard) {
    const LocalNameEntry *local = resolver_find_local_name_entry(context, name);

    if (local != NULL) {
        bool evaluated;

        if (local->mutability != FENG_MUTABILITY_LET || local->source_expr == NULL) {
            return false;
        }
        evaluated = evaluate_constant_expr_inner(
            context, local->source_expr, out, guard);
        if (evaluated) {
            const_integer_apply_inferred_type(context, local->type, out);
        }
        return evaluated;
    }

    /* 惰性歧义检测(规范 §7.1):常量上下文中的裸名值引用,同样需要做跨来源
     * 歧义检测。常量求值可能发生在 resolve_expr 之外的早期阶段(如全局 let
     * 初始值的折叠),所以这里独立检测,避免漏掉。 */
    if (!report_name_ambiguity_if_any(context, token, name, SYMBOL_LOOKUP_VALUE)) {
        return false;
    }

    {
        const VisibleValueEntry *visible =
            find_visible_value(context->visible_values, context->visible_value_count, name);

        if (visible == NULL || visible->is_function || visible->decl == NULL ||
            visible->decl->kind != FENG_DECL_GLOBAL_BINDING) {
            return false;
        }
        if (visible->decl->as.binding.mutability != FENG_MUTABILITY_LET ||
            visible->decl->as.binding.initializer == NULL) {
            return false;
        }
        {
            bool evaluated = evaluate_constant_expr_inner(
                context,
                visible->decl->as.binding.initializer,
                out,
                guard);

            if (evaluated) {
                const_integer_apply_inferred_type(
                    context,
                    infer_global_binding_decl_type(context, visible->decl),
                    out);
            }
            return evaluated;
        }
    }
}

static bool evaluate_constant_unary(ResolveContext *context,
                                    const FengExpr *expr,
                                    FengConstValue *out,
                                    ConstEvalGuard *guard) {
    FengConstValue operand;

    if (!evaluate_constant_expr_inner(context, expr->as.unary.operand, &operand, guard)) {
        return false;
    }

    switch (expr->as.unary.op) {
        case FENG_TOKEN_MINUS:
            if (operand.kind == FENG_CONST_INT) {
                /* Mirror extract_constant_integer_literal: use unsigned arithmetic to
                 * avoid signed-overflow UB on INT64_MIN. */
                uint64_t value = (uint64_t)0U - (uint64_t)operand.i;

                *out = operand.integer_is_unsigned
                           ? const_uint_value(value)
                           : const_int_value((int64_t)value);
                return true;
            }
            if (operand.kind == FENG_CONST_FLOAT) {
                *out = const_float_value(-operand.f);
                return true;
            }
            return false;
        case FENG_TOKEN_TILDE:
            if (operand.kind != FENG_CONST_INT) return false;
            *out = operand.integer_is_unsigned
                       ? const_uint_value(~(uint64_t)operand.i)
                       : const_int_value((int64_t)~(uint64_t)operand.i);
            return true;
        case FENG_TOKEN_NOT:
            if (operand.kind != FENG_CONST_BOOL) return false;
            *out = const_bool_value(!operand.b);
            return true;
        default:
            return false;
    }
}

/* Detect i64 overflow on +, -, *. Uses GCC/Clang builtins which both toolchains
 * targeted by Feng provide. */
static bool i64_add_overflow(int64_t a, int64_t b, int64_t *out) {
    return __builtin_add_overflow(a, b, out);
}

static bool i64_sub_overflow(int64_t a, int64_t b, int64_t *out) {
    return __builtin_sub_overflow(a, b, out);
}

static bool i64_mul_overflow(int64_t a, int64_t b, int64_t *out) {
    return __builtin_mul_overflow(a, b, out);
}

static bool report_const_eval_error(ResolveContext *context,
                                    const FengExpr *expr,
                                    const char *message) {
    char *copy = format_message("%s", message);
    return resolver_append_error(context, expr->token, "AE0100", copy);
}

static bool evaluate_constant_binary(ResolveContext *context,
                                     const FengExpr *expr,
                                     FengConstValue *out,
                                     ConstEvalGuard *guard) {
    FengConstValue lhs;
    FengConstValue rhs;
    FengTokenKind op = expr->as.binary.op;

    if (!evaluate_constant_expr_inner(context, expr->as.binary.left, &lhs, guard)) {
        return false;
    }
    if (!evaluate_constant_expr_inner(context, expr->as.binary.right, &rhs, guard)) {
        return false;
    }

    /* Logical operators require BOOL on both sides. */
    if (op == FENG_TOKEN_AND_AND || op == FENG_TOKEN_OR_OR) {
        if (lhs.kind != FENG_CONST_BOOL || rhs.kind != FENG_CONST_BOOL) return false;
        *out = const_bool_value(op == FENG_TOKEN_AND_AND ? (lhs.b && rhs.b) : (lhs.b || rhs.b));
        return true;
    }

    /* Bitwise & shift require INT on both sides. */
    if (op == FENG_TOKEN_AMP || op == FENG_TOKEN_PIPE || op == FENG_TOKEN_CARET) {
        if (lhs.kind != FENG_CONST_INT || rhs.kind != FENG_CONST_INT) return false;
        uint64_t l = (uint64_t)lhs.i;
        uint64_t r = (uint64_t)rhs.i;
        uint64_t v = op == FENG_TOKEN_AMP ? (l & r) : op == FENG_TOKEN_PIPE ? (l | r) : (l ^ r);
        *out = lhs.integer_is_unsigned || rhs.integer_is_unsigned
                   ? const_uint_value(v)
                   : const_int_value((int64_t)v);
        return true;
    }
    if (op == FENG_TOKEN_SHL || op == FENG_TOKEN_SHR) {
        if (lhs.kind != FENG_CONST_INT || rhs.kind != FENG_CONST_INT) return false;
        if (rhs.i < 0 || rhs.i >= 64) return false; /* type-aware diagnostic handled by validator */
        if (op == FENG_TOKEN_SHL) {
            uint64_t value = (uint64_t)lhs.i << (uint64_t)rhs.i;

            *out = lhs.integer_is_unsigned
                       ? const_uint_value(value)
                       : const_int_value((int64_t)value);
        } else {
            *out = lhs.integer_is_unsigned
                       ? const_uint_value((uint64_t)lhs.i >> (uint64_t)rhs.i)
                       : const_int_value(lhs.i >> rhs.i);
        }
        return true;
    }

    /* Comparisons: allow INT/FLOAT mixed (with promotion) or matching kinds. */
    if (op == FENG_TOKEN_LT || op == FENG_TOKEN_LE || op == FENG_TOKEN_GT ||
        op == FENG_TOKEN_GE || op == FENG_TOKEN_EQ || op == FENG_TOKEN_NE) {
        if ((lhs.kind == FENG_CONST_INT || lhs.kind == FENG_CONST_FLOAT) &&
            (rhs.kind == FENG_CONST_INT || rhs.kind == FENG_CONST_FLOAT)) {
            promote_const_pair(&lhs, &rhs);
            bool result;
            if (lhs.kind == FENG_CONST_INT) {
                if (lhs.integer_is_unsigned || rhs.integer_is_unsigned) {
                    uint64_t a = (uint64_t)lhs.i;
                    uint64_t b = (uint64_t)rhs.i;

                    switch (op) {
                        case FENG_TOKEN_LT:     result = a < b;  break;
                        case FENG_TOKEN_LE:     result = a <= b; break;
                        case FENG_TOKEN_GT:     result = a > b;  break;
                        case FENG_TOKEN_GE:     result = a >= b; break;
                        case FENG_TOKEN_EQ:     result = a == b; break;
                        default:                result = a != b; break;
                    }
                } else {
                    int64_t a = lhs.i;
                    int64_t b = rhs.i;

                    switch (op) {
                        case FENG_TOKEN_LT:     result = a < b;  break;
                        case FENG_TOKEN_LE:     result = a <= b; break;
                        case FENG_TOKEN_GT:     result = a > b;  break;
                        case FENG_TOKEN_GE:     result = a >= b; break;
                        case FENG_TOKEN_EQ:     result = a == b; break;
                        default:                result = a != b; break;
                    }
                }
            } else {
                double a = lhs.f, b = rhs.f;
                switch (op) {
                    case FENG_TOKEN_LT:     result = a < b;  break;
                    case FENG_TOKEN_LE:     result = a <= b; break;
                    case FENG_TOKEN_GT:     result = a > b;  break;
                    case FENG_TOKEN_GE:     result = a >= b; break;
                    case FENG_TOKEN_EQ:     result = a == b; break;
                    default:                result = a != b; break;
                }
            }
            *out = const_bool_value(result);
            return true;
        }
        if (lhs.kind == FENG_CONST_BOOL && rhs.kind == FENG_CONST_BOOL &&
            (op == FENG_TOKEN_EQ || op == FENG_TOKEN_NE)) {
            *out = const_bool_value(op == FENG_TOKEN_EQ ? (lhs.b == rhs.b) : (lhs.b != rhs.b));
            return true;
        }
        return false;
    }

    /* Arithmetic: +, -, *, /, %. */
    if (op == FENG_TOKEN_PLUS || op == FENG_TOKEN_MINUS || op == FENG_TOKEN_STAR ||
        op == FENG_TOKEN_SLASH || op == FENG_TOKEN_PERCENT) {
        if (!(lhs.kind == FENG_CONST_INT || lhs.kind == FENG_CONST_FLOAT) ||
            !(rhs.kind == FENG_CONST_INT || rhs.kind == FENG_CONST_FLOAT)) {
            return false;
        }
        promote_const_pair(&lhs, &rhs);
        if (lhs.kind == FENG_CONST_INT) {
            if (lhs.integer_is_unsigned || rhs.integer_is_unsigned) {
                uint64_t left = (uint64_t)lhs.i;
                uint64_t right = (uint64_t)rhs.i;
                uint64_t result = 0U;
                bool overflow = false;

                switch (op) {
                    case FENG_TOKEN_PLUS:
                        overflow = __builtin_add_overflow(left, right, &result);
                        break;
                    case FENG_TOKEN_MINUS:
                        overflow = __builtin_sub_overflow(left, right, &result);
                        break;
                    case FENG_TOKEN_STAR:
                        overflow = __builtin_mul_overflow(left, right, &result);
                        break;
                    case FENG_TOKEN_SLASH:
                        if (right == 0U) {
                            report_const_eval_error(
                                context,
                                expr,
                                "division by zero in compile-time '/' expression");
                            return false;
                        }
                        result = left / right;
                        break;
                    case FENG_TOKEN_PERCENT:
                        if (right == 0U) {
                            report_const_eval_error(
                                context,
                                expr,
                                "modulo by zero in compile-time '%' expression");
                            return false;
                        }
                        result = left % right;
                        break;
                    default:
                        return false;
                }
                if (overflow) {
                    const char *operator_name =
                        op == FENG_TOKEN_PLUS ? "+" :
                        op == FENG_TOKEN_MINUS ? "-" : "*";
                    char message[80];

                    (void)snprintf(
                        message,
                        sizeof(message),
                        "integer overflow in compile-time '%s' expression",
                        operator_name);
                    report_const_eval_error(context, expr, message);
                    return false;
                }
                *out = const_uint_value(result);
                return true;
            }
            int64_t result = 0;
            switch (op) {
                case FENG_TOKEN_PLUS:
                    if (i64_add_overflow(lhs.i, rhs.i, &result)) {
                        report_const_eval_error(context, expr,
                            "integer overflow in compile-time '+' expression");
                        return false;
                    }
                    break;
                case FENG_TOKEN_MINUS:
                    if (i64_sub_overflow(lhs.i, rhs.i, &result)) {
                        report_const_eval_error(context, expr,
                            "integer overflow in compile-time '-' expression");
                        return false;
                    }
                    break;
                case FENG_TOKEN_STAR:
                    if (i64_mul_overflow(lhs.i, rhs.i, &result)) {
                        report_const_eval_error(context, expr,
                            "integer overflow in compile-time '*' expression");
                        return false;
                    }
                    break;
                case FENG_TOKEN_SLASH:
                    if (rhs.i == 0) {
                        report_const_eval_error(context, expr,
                            "division by zero in compile-time '/' expression");
                        return false;
                    }
                    /* INT64_MIN / -1 overflows; treat as compile-time error for parity with
                     * the +, -, * checks above. */
                    if (lhs.i == INT64_MIN && rhs.i == -1) {
                        report_const_eval_error(context, expr,
                            "integer overflow in compile-time '/' expression");
                        return false;
                    }
                    result = lhs.i / rhs.i;
                    break;
                case FENG_TOKEN_PERCENT:
                    if (rhs.i == 0) {
                        report_const_eval_error(context, expr,
                            "modulo by zero in compile-time '%' expression");
                        return false;
                    }
                    if (lhs.i == INT64_MIN && rhs.i == -1) {
                        result = 0;
                    } else {
                        result = lhs.i % rhs.i;
                    }
                    break;
                default:
                    return false;
            }
            *out = const_int_value(result);
            return true;
        }
        /* FLOAT path: IEEE-754 semantics, no compile-time error on /0.0 (yields ±inf/NaN). */
        double a = lhs.f, b = rhs.f, result = 0.0;
        switch (op) {
            case FENG_TOKEN_PLUS:    result = a + b; break;
            case FENG_TOKEN_MINUS:   result = a - b; break;
            case FENG_TOKEN_STAR:    result = a * b; break;
            case FENG_TOKEN_SLASH:   result = a / b; break;
                case FENG_TOKEN_PERCENT:
                    if (b == 0.0) {
                        report_const_eval_error(context, expr,
                            "modulo by zero in compile-time '%' expression");
                        return false;
                    }
                    result = fmod(a, b);
                    break;
            default:                 return false;
        }
        *out = const_float_value(result);
        return true;
    }

    return false;
}

static bool evaluate_constant_cast(ResolveContext *context,
                                   const FengExpr *expr,
                                   FengConstValue *out,
                                   ConstEvalGuard *guard) {
    FengConstValue inner;
    const char *target;

    if (!evaluate_constant_expr_inner(context, expr->as.cast.value, &inner, guard)) {
        return false;
    }
    target = type_ref_builtin_canonical_name(expr->as.cast.type, context->pointer_size);
    if (target == NULL) {
        return false;
    }
    /* Numeric-to-numeric only (per docs/specifications/feng-expression.md §3.4). bool ↔ numeric is a
     * static error caught by cast_expr_types_are_valid; we don't fold across that boundary. */
    if (inner.kind == FENG_CONST_INT) {
        if (strcmp(target, "f32") == 0 || strcmp(target, "f64") == 0) {
            *out = const_float_value(inner.integer_is_unsigned
                                         ? (double)(uint64_t)inner.i
                                         : (double)inner.i);
            return true;
        }
        if (canonical_integer_bit_width(target) > 0) {
            int64_t value = truncate_int_to_canonical(inner.i, target);

            *out = target[0] == 'u'
                       ? const_uint_value((uint64_t)value)
                       : const_int_value(value);
            return true;
        }
        return false;
    }
    if (inner.kind == FENG_CONST_FLOAT) {
        if (strcmp(target, "f32") == 0 || strcmp(target, "f64") == 0) {
            *out = const_float_value(inner.f);
            return true;
        }
        if (canonical_integer_bit_width(target) > 0) {
            /* C-style truncation toward zero, then narrow to target bit width. */
            int64_t truncated = (int64_t)inner.f;
            int64_t value = truncate_int_to_canonical(truncated, target);

            *out = target[0] == 'u'
                       ? const_uint_value((uint64_t)value)
                       : const_int_value(value);
            return true;
        }
        return false;
    }
    return false;
}

static bool evaluate_constant_expr_inner(ResolveContext *context,
                                         const FengExpr *expr,
                                         FengConstValue *out,
                                         ConstEvalGuard *guard) {
    ConstEvalGuard frame;

    if (expr == NULL || out == NULL) {
        return false;
    }
    if (guard_contains(guard, expr)) {
        return false; /* cycle */
    }
    frame.expr = expr;
    frame.prev = guard;

    switch (expr->kind) {
        case FENG_EXPR_INTEGER:
            *out = const_int_value(expr->as.integer);
            if (expr->type != NULL) {
                const_integer_apply_inferred_type(
                    context,
                    inferred_expr_type_from_type_ref(expr->type),
                    out);
            }
            return true;
        case FENG_EXPR_FLOAT:
            *out = const_float_value(expr->as.floating);
            return true;
        case FENG_EXPR_BOOL:
            *out = const_bool_value(expr->as.boolean);
            return true;
        case FENG_EXPR_IDENTIFIER:
            return evaluate_constant_identifier(context, expr->token, expr->as.identifier, out, &frame);
        case FENG_EXPR_UNARY:
            return evaluate_constant_unary(context, expr, out, &frame);
        case FENG_EXPR_BINARY:
            return evaluate_constant_binary(context, expr, out, &frame);
        case FENG_EXPR_CAST:
            return evaluate_constant_cast(context, expr, out, &frame);
        default:
            return false;
    }
}

static bool evaluate_constant_expr(ResolveContext *context,
                                   const FengExpr *expr,
                                   FengConstValue *out) {
    return evaluate_constant_expr_inner(context, expr, out, NULL);
}

/* Validate a compile-time-known array creation length against the target
 * platform's `int` domain. The constant folder stores integer bits in i64;
 * the resolved static type determines whether those bits are signed or
 * unsigned. Dynamic expressions are deliberately left for the single
 * creation-site Codegen check. */
static bool validate_array_new_constant_size(
    ResolveContext *context,
    const FengExpr *size_expr,
    InferredExprType size_type,
    bool *out_statically_valid) {
    FengConstValue value;
    const char *canonical_name;
    const uint64_t target_max = context->pointer_size >= 8U
                                    ? (uint64_t)INT64_MAX
                                    : (uint64_t)INT32_MAX;
    uint64_t unsigned_value;
    bool is_unsigned;
    bool valid;
    char value_text[32];
    char max_text[32];

    if (out_statically_valid != NULL) {
        *out_statically_valid = false;
    }
    if (!evaluate_constant_expr(context, size_expr, &value) ||
        value.kind != FENG_CONST_INT) {
        return true;
    }

    canonical_name = inferred_expr_type_builtin_canonical_name(
        size_type, context->pointer_size);
    if (canonical_name == NULL) {
        return true;
    }
    is_unsigned = canonical_name[0] == 'u';
    unsigned_value = (uint64_t)value.i;
    valid = is_unsigned
                ? unsigned_value <= target_max
                : value.i >= 0 && (uint64_t)value.i <= target_max;
    if (valid) {
        if (out_statically_valid != NULL) {
            *out_statically_valid = true;
        }
        return true;
    }

    if (is_unsigned) {
        (void)snprintf(value_text,
                       sizeof(value_text),
                       "%llu",
                       (unsigned long long)unsigned_value);
    } else {
        (void)snprintf(value_text,
                       sizeof(value_text),
                       "%lld",
                       (long long)value.i);
    }
    (void)snprintf(max_text,
                   sizeof(max_text),
                   "%llu",
                   (unsigned long long)target_max);
    return resolver_append_error(
        context,
        size_expr->token,
        "AE0204",
        format_message(
            "array size value %s is outside the valid target 'int' range 0...%s",
            value_text,
            max_text));
}

static bool expr_is_pure_numeric_literal_expr_for_target_adaptation(const FengExpr *expr) {
    if (expr == NULL) {
        return false;
    }

    switch (expr->kind) {
        case FENG_EXPR_INTEGER:
        case FENG_EXPR_FLOAT:
            return true;

        case FENG_EXPR_UNARY:
            return expr_is_pure_numeric_literal_expr_for_target_adaptation(
                expr->as.unary.operand);

        case FENG_EXPR_BINARY:
            return expr_is_pure_numeric_literal_expr_for_target_adaptation(
                       expr->as.binary.left) &&
                   expr_is_pure_numeric_literal_expr_for_target_adaptation(
                       expr->as.binary.right);

        case FENG_EXPR_CAST:
            return expr_is_pure_numeric_literal_expr_for_target_adaptation(
                expr->as.cast.value);

        default:
            return false;
    }
}

/* Numeric literal adaptation: an integer/float literal may be implicitly retyped to any
 * compatible numeric target type, subject to compile-time range checks. This realises the
 * "如需其他精度或宽度，必须显式标注类型" contract from docs/specifications/feng-builtin-type.md §16-§17,
 * where the explicit annotation drives the literal's effective type. */
static bool numeric_literal_adapts_to_target(ResolveContext *context,
                                             const FengExpr *expr,
                                             const FengTypeRef *target) {
    FengConstValue value;

    if (!evaluate_constant_expr(context, expr, &value)) {
        return false;
    }
    return numeric_const_value_adapts_to_target(context, value, target);
}

/* Persist a literal's resolved type for codegen.  expected type refs can come
 * from declaration ASTs or from resolver-owned generic substitution results;
 * cloning unconditionally keeps this boundary independent of the source
 * lifetime and prevents temporary refs from escaping through FengExpr.type. */
static bool persist_literal_type_ref(ResolveContext *context,
                                     const FengExpr *expr,
                                     const FengTypeRef *type_ref) {
    FengTypeRef *persistent_type_ref;

    if (context == NULL || expr == NULL || type_ref == NULL) {
        return true;
    }

    persistent_type_ref = clone_type_ref_for_inference(type_ref);
    if (persistent_type_ref == NULL ||
        !analysis_track_synthetic_type_ref(context->analysis,
                                           persistent_type_ref)) {
        free_synthetic_type_ref(persistent_type_ref);
        return resolver_append_error(
            context,
            expr->token,
            "IE0001",
            format_message("out of memory while persisting numeric literal type"));
    }

    ((FengExpr *)expr)->type = persistent_type_ref;
    return true;
}

/* Check every value-producing result of an if/match/try expression against a
 * contextual target. This pure matching path is used during overload probing;
 * it intentionally records no coercion sites of its own. */
static bool branching_expr_results_match_expected_type(
    ResolveContext *context,
    const FengExpr *expr,
    const FengTypeRef *expected_type_ref) {
    size_t index;

    if (expr == NULL || expected_type_ref == NULL) {
        return false;
    }
    switch (expr->kind) {
        case FENG_EXPR_IF: {
            const FengBlock *blocks[2] = {
                expr->as.if_expr.then_block,
                expr->as.if_expr.else_block
            };

            for (index = 0U; index < 2U; ++index) {
                const FengExpr *result;

                if (block_exits_via_return_or_throw(blocks[index])) {
                    continue;
                }
                result = block_yield_expression(blocks[index]);
                if (result == NULL ||
                    !expr_matches_expected_type_ref(context,
                                                    result,
                                                    expected_type_ref)) {
                    return false;
                }
            }
            return true;
        }

        case FENG_EXPR_MATCH:
            for (index = 0U; index < expr->as.match_expr.branch_count; ++index) {
                const FengBlock *block = expr->as.match_expr.branches[index].body;
                const FengExpr *result;

                if (block_exits_via_return_or_throw(block)) {
                    continue;
                }
                result = block_yield_expression(block);
                if (result == NULL ||
                    !expr_matches_expected_type_ref(context,
                                                    result,
                                                    expected_type_ref)) {
                    return false;
                }
            }
            if (!block_exits_via_return_or_throw(expr->as.match_expr.else_block)) {
                const FengExpr *result =
                    block_yield_expression(expr->as.match_expr.else_block);

                if (result == NULL ||
                    !expr_matches_expected_type_ref(context,
                                                    result,
                                                    expected_type_ref)) {
                    return false;
                }
            }
            return true;

        case FENG_EXPR_TRY:
            if (!expr_matches_expected_type_ref(context,
                                                expr->as.try_expr.body,
                                                expected_type_ref)) {
                return false;
            }
            for (index = 0U; index < expr->as.try_expr.clause_count; ++index) {
                const FengBlock *block = expr->as.try_expr.clauses[index].body;
                const FengExpr *result;

                if (block_exits_via_return_or_throw(block)) {
                    continue;
                }
                result = block_yield_expression(block);
                if (result == NULL ||
                    !expr_matches_expected_type_ref(context,
                                                    result,
                                                    expected_type_ref)) {
                    return false;
                }
            }
            return true;

        default:
            return false;
    }
}

static bool expr_matches_expected_type_ref(ResolveContext *context,
                                           const FengExpr *expr,
                                           const FengTypeRef *expected_type_ref) {
    const FengDecl *function_type_decl = resolve_function_type_decl(context, expected_type_ref);
    InferredExprType expr_type;

    if (expr != NULL &&
        (expr->kind == FENG_EXPR_IF || expr->kind == FENG_EXPR_MATCH ||
         expr->kind == FENG_EXPR_TRY)) {
        return branching_expr_results_match_expected_type(context,
                                                          expr,
                                                          expected_type_ref);
    }

    if (expr != NULL && expr->kind == FENG_EXPR_UNARY && expr->as.unary.op == FENG_TOKEN_AMP &&
        expected_type_ref != NULL && expected_type_ref->kind == FENG_TYPE_REF_POINTER) {
        if (resolve_abi_function_pointer_type_decl(context, expected_type_ref) != NULL) {
            return expr_matches_expected_abi_function_pointer_type(context,
                                                                  expr,
                                                                  expected_type_ref);
        }
        return expr_matches_expected_address_of_data_pointer_type(context,
                                                                  expr,
                                                                  expected_type_ref);
    }

    if (function_type_decl != NULL) {
        return resolve_expr_callable_value(context, expr, expected_type_ref).kind ==
               FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE;
    }

    if (expr != NULL && expr->kind == FENG_EXPR_TUPLE_LITERAL) {
        return tuple_literal_matches_tuple_type_ref(context, expr, expected_type_ref);
    }

    /* Step 4b-γ — arrays with an expected array target drive matching
     * element-by-element / element-type-by-type so coercions can use the
     * expected inner type directly instead of relying on default inference. */
    if (expr != NULL &&
        (expr->kind == FENG_EXPR_ARRAY_LITERAL || expr->kind == FENG_EXPR_ARRAY_NEW) &&
        expected_type_ref != NULL && expected_type_ref->kind == FENG_TYPE_REF_ARRAY) {
        return expr_matches_expected_type_ref_when_inference_unknown(context,
                                                                     expr,
                                                                     expected_type_ref);
    }

    /* For numeric literal constants targeting a built-in numeric type, the literal-adaptation
     * path (with compile-time range checking per docs/specifications/feng-builtin-type.md §17) is the sole
     * authority — falling through to the default-inferred-type path would let oversized
     * literals like `let c: i32 = 9999999999;` slip past because the literal's *default*
     * inferred type happens to match the target's canonical name. */
    if (type_ref_builtin_canonical_name(expected_type_ref, context->pointer_size) != NULL) {
        FengConstValue value;
        size_t errors_before = *context->error_count;

        if (expr_is_pure_numeric_literal_expr_for_target_adaptation(expr) &&
            evaluate_constant_expr(context, expr, &value) &&
            (value.kind == FENG_CONST_INT || value.kind == FENG_CONST_FLOAT)) {
            if (numeric_literal_adapts_to_target(context, expr, expected_type_ref)) {
                /* Adaptation succeeded: hang the target type on the literal node
                 * so that codegen can read it directly.  expected_type_ref may
                 * be a resolver-owned generic substitution result, so persist
                 * an analysis-owned deep clone before storing it.
                 *
                 * When called during overload-resolution candidate probing
                 * (suppress_literal_type_commit is true), the type must NOT
                 * be set here — each probing call carries a different candidate
                 * parameter type and the last write would win non-deterministically.
                 * The correct type is committed after resolution picks the unique
                 * winner (see commit_literal_arg_adaptations_for_resolved_call). */
                if (!context->suppress_literal_type_commit &&
                    !persist_literal_type_ref(context, expr, expected_type_ref)) {
                    return false;
                }
                return true;
            }
            return false;
        }
        /* If the constant evaluator reported a compile-time error (e.g., division by zero,
         * overflow), the binding is already known invalid; treat as matched to suppress a
         * cascading inference-mismatch diagnostic. */
        if (*context->error_count > errors_before) {
            return true;
        }
    }

    expr_type = branch_result_inferred_type(context, expr);
    if (!inferred_expr_type_is_known(expr_type)) {
        if (expr_type_inference_is_pending(context, expr)) {
            return true;
        }
        return expr_matches_expected_type_ref_when_inference_unknown(context,
                                                                     expr,
                                                                     expected_type_ref);
    }

    {
        const FengDecl *target_union_decl = resolve_union_spec_type_ref_decl(context,
                                                                             expected_type_ref);

        if (target_union_decl != NULL) {
            UnionMemberSelection selection;

            if (expr_is_pure_numeric_literal_expr_for_target_adaptation(expr)) {
                const FengTypeRef *literal_member =
                    select_literal_expr_union_member_target(context,
                                                            expr,
                                                            target_union_decl,
                                                            expected_type_ref);

                if (literal_member != NULL) {
                    if (!context->suppress_literal_type_commit &&
                        !persist_literal_type_ref(context,
                                                  expr,
                                                  literal_member)) {
                        return false;
                    }
                    return true;
                }
            }

            if (inferred_expr_type_exactly_matches_type_ref(context, expr_type, expected_type_ref)) {
                return true;
            }
            selection = select_union_member_for_expr_type(context,
                                                          expr_type,
                                                          target_union_decl,
                                                          expected_type_ref);
            return selection.matched;
        }
    }

    return inferred_expr_type_matches_type_ref(context, expr_type, expected_type_ref);
}

static bool expr_is_lambda_value_without_target(ResolveContext *context, const FengExpr *expr) {
    InferredExprType expr_type;

    if (expr == NULL) {
        return false;
    }
    if (expr->kind == FENG_EXPR_LAMBDA) {
        return true;
    }

    expr_type = infer_expr_type(context, expr);
    return expr_type.kind == FENG_INFERRED_EXPR_TYPE_LAMBDA;
}

static bool report_lambda_requires_callable_spec_target(ResolveContext *context,
                                                        const FengExpr *expr,
                                                        const char *position) {
    return resolver_append_error(
        context,
        expr != NULL ? expr->token : context->program->module_token,
        "AE0520", format_message("lambda expression in %s requires an explicit callable-form spec target type",
                       position != NULL ? position : "this position"));
}

static bool expr_is_callable_value_reference(ResolveContext *context, const FengExpr *expr) {
    if (expr == NULL) {
        return false;
    }

    switch (expr->kind) {
        case FENG_EXPR_GENERIC_TARGET:
            return true;

        case FENG_EXPR_IDENTIFIER: {
            const FunctionOverloadSetEntry *overload_set;

            if (resolver_find_local_name_entry(context, expr->as.identifier) != NULL) {
                return false;
            }

            overload_set = find_function_overload_set(context->function_sets,
                                                      context->function_set_count,
                                                      expr->as.identifier);
            return overload_set != NULL;
        }

        case FENG_EXPR_MEMBER: {
            const FengExpr *object = expr->as.member.object;
            ResolvedModuleMemberTarget module_target;

            if (resolve_module_member_target(
                    context, expr, &module_target)) {
                return count_module_public_function_overloads(
                           module_target.module,
                           module_target.member_name) > 0U;
            }

            {
                ResolvedTypeTarget static_target =
                    resolve_type_target_expr(context, object, false);

                if (static_target.type_decl != NULL ||
                    static_target.is_builtin_type_name) {
                    InferredExprType owner_type;
                    size_t member_index;

                    if (static_target.type_decl != NULL &&
                        static_target.type_decl->kind == FENG_DECL_TYPE &&
                        static_target.type_decl->as.type_decl.type_param_count > 0U &&
                        static_target.type_ref == NULL) {
                        return false;
                    }
                    owner_type = resolved_type_target_owner_type(&static_target);
                    if (static_target.type_decl != NULL &&
                        static_target.type_decl->kind == FENG_DECL_TYPE) {
                        for (member_index = 0U;
                             member_index < static_target.type_decl->as.type_decl.member_count;
                             ++member_index) {
                            const FengTypeMember *member =
                                static_target.type_decl->as.type_decl.members[member_index];

                            if (member != NULL && member->is_static &&
                                member->kind == FENG_TYPE_MEMBER_METHOD &&
                                slice_equals(member->as.callable.name,
                                             expr->as.member.member) &&
                                type_member_is_accessible_from(
                                    context,
                                    static_target.type_decl,
                                    owner_type,
                                    member) &&
                                !fit_body_blocks_private_access(
                                    context,
                                    static_target.type_decl,
                                    member)) {
                                return true;
                            }
                        }
                    }
                    return find_fit_static_method_member_for_owner_type(
                               context,
                               static_target.type_decl,
                               owner_type,
                               expr->as.member.member) != NULL;
                }
                if (static_target.is_generic_type_param &&
                    static_target.constraint_spec_decl != NULL &&
                    (static_target.constraint_spec_decl->as.spec_decl.form ==
                         FENG_SPEC_FORM_OBJECT ||
                     static_target.constraint_spec_decl->as.spec_decl.form ==
                         FENG_SPEC_FORM_INTERSECTION)) {
                    InferredExprType constraint_owner =
                        static_target.constraint_spec_type_ref != NULL
                            ? inferred_expr_type_from_type_ref(
                                  static_target.constraint_spec_type_ref)
                            : inferred_expr_type_from_decl(
                                  static_target.constraint_spec_decl);
                    SpecMethodAccessProbe method_probe =
                        probe_spec_method_access(
                            context,
                            static_target.constraint_spec_decl,
                            constraint_owner,
                            expr->as.member.member,
                            /*require_static=*/true);

                    return method_probe.has_accessible_method;
                }
            }

            {
                const FengDecl *owner_type_decl = NULL;
                const FengSemanticModule *provider_module = NULL;
                InferredExprType owner_type =
                    resolve_expr_owner_type(context, object, &owner_type_decl, &provider_module);

                if (owner_type_decl == NULL) {
                    SpecMemberSurface surface;

                    memset(&surface, 0, sizeof(surface));
                    if (find_generic_param_spec_member_surface(
                            context,
                            owner_type,
                            expr->as.member.member,
                            /*include_static=*/false,
                            &surface) &&
                        surface.member != NULL &&
                        surface.member->kind == FENG_TYPE_MEMBER_METHOD &&
                        !surface.member->is_static) {
                        return true;
                    }
                }

                return count_accessible_method_overloads(context,
                                                         owner_type_decl,
                                                         provider_module,
                                                         owner_type,
                                                         expr->as.member.member) > 0U;
            }
        }

        default:
            return false;
    }
}

/* Phase S1b — SpecCoercionSite recording helpers (§6.2). */

/* Records the ordinary conversion required before a source value can be
 * stored in the selected leaf member of a union. The union sidecar chooses
 * tags; this sidecar preserves representation-changing conversions such as
 * concrete type -> object-form spec and child spec -> parent spec. */
static void record_union_leaf_spec_coercion_if_applicable(
        ResolveContext *context,
        const FengExpr *expr,
        const UnionMemberSelection *selection) {
    if (context == NULL || expr == NULL || selection == NULL ||
        !selection->matched || selection->leaf_type_ref == NULL) {
        return;
    }
    record_callable_spec_coercion_site(context, expr, selection->leaf_type_ref);
    record_object_spec_coercion_site_if_applicable(
        context,
        expr,
        selection->leaf_type_ref,
        FENG_SPEC_OBJECT_SUBJECT_STORAGE_BOX_OWNER);
}

static void record_union_coercion_site_if_applicable(ResolveContext *context,
                                                     const FengExpr *expr,
                                                     const FengTypeRef *expected_type_ref) {
    const FengDecl *target_union_decl;
    InferredExprType expr_type;
    UnionMemberSelection selection;

    if (context == NULL || context->analysis == NULL || expr == NULL || expected_type_ref == NULL) {
        return;
    }
    if (expr->kind == FENG_EXPR_ARRAY_LITERAL &&
        expected_type_ref->kind == FENG_TYPE_REF_ARRAY &&
        expected_type_ref->as.inner != NULL) {
        for (size_t index = 0U; index < expr->as.array_literal.count; ++index) {
            record_union_coercion_site_if_applicable(context,
                                                     expr->as.array_literal.items[index],
                                                     expected_type_ref->as.inner);
        }
        return;
    }

    target_union_decl = resolve_union_spec_type_ref_decl(context, expected_type_ref);
    if (target_union_decl == NULL) {
        return;
    }
    /* Target-directed literal adaptation persists the selected leaf type on
     * the complete pure constant expression. Prefer that authoritative type
     * over default inference so unary/binary literal expressions record the
     * same union member as scalar literal nodes. */
    if (expr->type != NULL &&
        expr_is_pure_numeric_literal_expr_for_target_adaptation(expr)) {
        expr_type = inferred_expr_type_from_type_ref(expr->type);
    } else {
        expr_type = infer_expr_type(context, expr);
    }
    if (!inferred_expr_type_is_known(expr_type) ||
        inferred_expr_type_exactly_matches_type_ref(context, expr_type, expected_type_ref)) {
        return;
    }
    selection = select_union_member_for_expr_type(context,
                                                  expr_type,
                                                  target_union_decl,
                                                  expected_type_ref);
    if (!selection.matched) {
        return;
    }
    (void)feng_semantic_record_union_coercion_site(context->analysis,
                                                   expr,
                                                   target_union_decl,
                                                   expected_type_ref,
                                                   selection.member_index,
                                                   selection.member_type_ref,
                                                   selection.path_indices,
                                                   selection.path_length);
    record_union_leaf_spec_coercion_if_applicable(context, expr, &selection);
}

static const FengDecl *concrete_type_decl_of_inferred(const ResolveContext *context,
                                                      InferredExprType expr_type) {
    switch (expr_type.kind) {
        case FENG_INFERRED_EXPR_TYPE_DECL:
            if (decl_is_named_fit_target(expr_type.type_decl)) {
                return expr_type.type_decl;
            }
            return NULL;
        case FENG_INFERRED_EXPR_TYPE_TYPE_REF: {
            const FengDecl *d = resolve_type_ref_decl(context, expr_type.type_ref);
            return decl_is_named_fit_target(d) ? d : NULL;
        }
        case FENG_INFERRED_EXPR_TYPE_BUILTIN:
        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
        default:
            return NULL;
    }
}

/* Records an object-form coercion site when expected_type_ref names an
 * object-form spec and expr's static type is a concrete `type` decl that
 * satisfies it. Silent no-op for any other shape (numeric coercion, builtin
 * match, lambda body inference re-entries, etc.). */
static void record_object_spec_coercion_site_if_applicable(
        ResolveContext *context,
        const FengExpr *expr,
    const FengTypeRef *expected_type_ref,
    FengSpecObjectSubjectStorageKind preferred_storage) {
    const FengDecl *target_decl;
    const FengDecl *src_type_decl;
    InferredExprType expr_type;
    const FengSpecRelation *relation;
    FengSemanticSubjectKey subject_key_for_coercion;

    if (context == NULL || context->analysis == NULL || expr == NULL ||
        expected_type_ref == NULL) {
        return;
    }
    /* Step 4b-γ — array literals targeting an array type get per-element
     * coercion sites recorded so codegen wraps each element into the spec
     * fat value before the array storage is shaped. */
    if (expr->kind == FENG_EXPR_ARRAY_LITERAL &&
        expected_type_ref->kind == FENG_TYPE_REF_ARRAY &&
        expected_type_ref->as.inner != NULL) {
        size_t i;
        for (i = 0U; i < expr->as.array_literal.count; ++i) {
            record_object_spec_coercion_site_if_applicable(context,
                                                            expr->as.array_literal.items[i],
                                                            expected_type_ref->as.inner,
                                                            preferred_storage);
        }
        return;
    }
    target_decl = resolve_type_ref_decl(context, expected_type_ref);
    if (target_decl == NULL || target_decl->kind != FENG_DECL_SPEC) {
        return;
    }
    /* Callable-form specs have their own callable hook (§8.4). */
    if (decl_is_function_type(target_decl)) {
        return;
    }
    if (target_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT &&
        target_decl->as.spec_decl.form != FENG_SPEC_FORM_INTERSECTION) {
        return;
    }
    expr_type = infer_expr_type(context, expr);
    if (target_decl->as.spec_decl.form == FENG_SPEC_FORM_OBJECT) {
        ObjectSpecUpcastPath upcast_path;

        if (find_object_spec_upcast_path(context,
                                         expr_type,
                                         expected_type_ref,
                                         &upcast_path)) {
            (void)feng_semantic_record_object_spec_upcast_site(
                context->analysis,
                expr,
                target_decl,
                expected_type_ref,
                upcast_path.parent_indices,
                upcast_path.count);
            object_spec_upcast_path_free(&upcast_path);
            return;
        }
    }
    src_type_decl = concrete_type_decl_of_inferred(context, expr_type);
    /* Build subject key: user type → TYPE_DECL key; builtin/array →
     * derive from expr_type.type_ref using the same helper that
     * compute_spec_witness_if_absent uses. */
    {
        const FengTypeRef *src_type_ref =
            (expr_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF)
                ? expr_type.type_ref
                : NULL;

        if (src_type_decl != NULL || src_type_ref != NULL) {
            if (!init_spec_witness_subject_key(src_type_decl,
                                               src_type_ref,
                                               context->pointer_size,
                                               &subject_key_for_coercion)) {
                return;
            }
        } else if (expr_type.kind == FENG_INFERRED_EXPR_TYPE_BUILTIN) {
            const char *builtin_name = canonical_builtin_type_name(expr_type.builtin_name, context->pointer_size);

            if (builtin_name == NULL) {
                return;
            }
            subject_key_for_coercion = feng_semantic_subject_key_for_builtin(builtin_name);
        } else {
            return;
        }
    }
    if (src_type_decl != NULL) {
        bool satisfies = expr_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF
            ? type_ref_satisfies_spec_type_ref(context,
                                                expr_type.type_ref,
                                                expected_type_ref)
            : type_decl_satisfies_spec_type_ref(context,
                                                src_type_decl,
                                                expected_type_ref);

        if (!satisfies) {
            /* Match must have been by exact type identity (src == target spec
             * is impossible since target is SPEC and src is TYPE), so absence
             * here means the match was a non-spec path (should not happen
             * given the SPEC target check above). Defensive no-op. */
            return;
        }
    } else if (src_type_decl == NULL) {
        /* Builtin / array path: satisfaction was already confirmed by the
         * type_ref_satisfies_spec_type_ref check in the outer resolver, so
         * we do not re-check here. */
    }
    /* Intersection-form: no single SpecRelation justifies the coercion
     * (satisfaction is per member spec, already verified by 9.5). Record
     * the site with form=INTERSECTION and skip the SpecRelation lookup and
     * the SpecWitness compute path — codegen derives the merged witness
     * from the subject's per-member witnesses directly. */
    if (target_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
        (void)feng_semantic_record_intersection_spec_coercion_site(context->analysis,
                                                                   expr,
                                                                   &subject_key_for_coercion,
                                                                   target_decl,
                                                                   expected_type_ref,
                                                                   FENG_SPEC_OBJECT_SUBJECT_STORAGE_BOX_OWNER);
        return;
    }
    relation = feng_semantic_lookup_spec_relation(context->analysis,
                                                  &subject_key_for_coercion,
                                                  target_decl);
    if (relation == NULL) {
        return;
    }

    (void)feng_semantic_record_object_spec_coercion_site(context->analysis,
                                                          expr,
                                                          &subject_key_for_coercion,
                                                          target_decl,
                                                          expected_type_ref,
                                                          relation,
                                                          FENG_SPEC_OBJECT_SUBJECT_STORAGE_BOX_OWNER);

    /* Phase S3 — materialise the (T, S) witness on first demand (§8.2). The
     * compute helper is idempotent: subsequent coercions for the same pair
     * observe the cached entry and skip recomputation, so per-coercion-site
     * conflict diagnostics fire exactly once at the first triggering site
     * (per §8.1 / §8.2 — "复用同一份 SpecWitness 结果"). */
    compute_spec_witness_if_absent(context,
                                   src_type_decl,
                                   expr_type,
                                   expr_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF
                                       ? expr_type.type_ref
                                       : NULL,
                                   target_decl,
                                   expected_type_ref,
                                   expr->token);
}

/* Records spec coercion sites for each argument of a call against the resolved
 * callee parameter list. Callable-form targets use the callable coercion
 * sidecar; object-form targets use the object-spec coercion sidecar. Arguments
 * that don't match either predicate are silently skipped. */
static void record_object_arg_coercion_sites(ResolveContext *context,
                                             FengExpr *const *args,
                                             size_t arg_count,
                                             const FengParameter *params,
                                             size_t param_count,
                                             FengSpecObjectSubjectStorageKind preferred_storage) {
    size_t i;
    bool is_variadic;
    size_t fixed_count;

    if (params == NULL || args == NULL) {
        return;
    }
    is_variadic = param_count > 0U && params[param_count - 1U].is_variadic;
    fixed_count = is_variadic ? param_count - 1U : param_count;
    if (!is_variadic && param_count != arg_count) {
        return;
    }
    if (is_variadic && arg_count < fixed_count) {
        return;
    }
    for (i = 0U; i < arg_count; ++i) {
        const FengTypeRef *param_type =
            i < fixed_count || args[i]->is_prepacked_variadic_arg
                ? params[i].type
                : params[fixed_count].type->as.inner;

        if (args[i]->kind == FENG_EXPR_IF ||
            args[i]->kind == FENG_EXPR_MATCH ||
            args[i]->kind == FENG_EXPR_TRY) {
            (void)validate_expr_against_expected_type(context,
                                                      args[i],
                                                      param_type);
            continue;
        }
        if (resolve_function_type_decl(context, param_type) != NULL) {
            record_callable_spec_coercion_site(context, args[i], param_type);
            continue;
        }
        record_union_coercion_site_if_applicable(context, args[i], param_type);
        record_object_spec_coercion_site_if_applicable(context,
                                                       args[i],
                                                       param_type,
                                                       preferred_storage);
    }
}

/* Record argument coercions against the fully selected callable instance.
 * Owner arguments and callable-local arguments are substituted in declaration
 * order before determining callable/spec coercions, so a generic method's
 * lambda and aggregate parameter surfaces use the same closed types as its
 * resolved-call metadata. */
static void record_object_arg_coercion_sites_for_resolved_call(
    ResolveContext *context,
    const FengExpr *call_expr,
    const FengCallableSignature *callable,
    const FengDecl *owner_type_decl,
    InferredExprType owner_type) {
    size_t i;
    bool is_variadic;
    size_t fixed_count;
    FengExpr *const *args;
    size_t arg_count;
    const FengParameter *params;
    size_t param_count;
    const FengResolvedCallable *resolved;

    if (call_expr == NULL || call_expr->kind != FENG_EXPR_CALL ||
        callable == NULL) {
        return;
    }
    args = call_expr->as.call.args;
    arg_count = call_expr->as.call.arg_count;
    params = callable->params;
    param_count = callable->param_count;
    resolved = &call_expr->as.call.resolved_callable;
    if (params == NULL || args == NULL) {
        return;
    }
    is_variadic = param_count > 0U && params[param_count - 1U].is_variadic;
    fixed_count = is_variadic ? param_count - 1U : param_count;
    if (!is_variadic && param_count != arg_count) {
        return;
    }
    if (is_variadic && arg_count < fixed_count) {
        return;
    }
    for (i = 0U; i < arg_count; ++i) {
        const FengTypeRef *declared_param_type =
            i < fixed_count || args[i]->is_prepacked_variadic_arg
                ? params[i].type
                : params[fixed_count].type->as.inner;
        const FengTypeRef *param_type = substitute_type_ref_for_owner_instance(
            context,
            owner_type_decl,
            owner_type,
            declared_param_type);
        param_type = substitute_type_ref_for_explicit_callable_args(
            context,
            callable,
            resolved->callable_type_args,
            resolved->callable_type_arg_count,
            param_type);
        if (args[i]->kind == FENG_EXPR_IF ||
            args[i]->kind == FENG_EXPR_MATCH ||
            args[i]->kind == FENG_EXPR_TRY) {
            (void)validate_expr_against_expected_type(context,
                                                      args[i],
                                                      param_type);
            continue;
        }
        if (resolve_function_type_decl(context, param_type) != NULL) {
            record_callable_spec_coercion_site(context, args[i], param_type);
            continue;
        }
        record_union_coercion_site_if_applicable(context, args[i], param_type);
        record_object_spec_coercion_site_if_applicable(context,
                                                       args[i],
                                                       param_type,
                                                       FENG_SPEC_OBJECT_SUBJECT_STORAGE_BOX_OWNER);
    }
}

/* Determine whether the inferred type argument at `type_param_index` satisfies
 * the declared constraint of that type parameter. Used during overload
 * candidate filtering: a generic candidate whose type argument fails its
 * constraint is excluded from the candidate set. The check mirrors the
 * applicability gate already used by the post-selection witness materializer
 * (see materialize_object_spec_constraint_witness_if_applicable), but performs
 * the type-parameter substitution itself and answers a plain boolean without
 * computing any witness. Returns true when there is nothing to validate
 * (no constraint, or a non-object-form constraint, or an uninferred type
 * argument); the caller decides how to treat the uninferred case. */
static bool generic_type_arg_satisfies_constraint(ResolveContext *context,
                                                   const FengCallableSignature *callable,
                                                   size_t type_param_index,
                                                   FengTypeRef *const *type_args,
                                                   const FengDecl *owner_type_decl,
                                                   const FengDecl *fit_decl,
                                                   InferredExprType owner_type) {
    const FengTypeParam *type_param;
    const FengTypeRef *actual_type_ref;
    const FengDecl *constraint_decl;
    FengTypeRef *owned_constraint = NULL;
    const FengTypeRef *constraint_ref;
    bool result = false;

    if (context == NULL || callable == NULL || type_args == NULL ||
        type_param_index >= callable->type_param_count) {
        return true;
    }

    type_param = &callable->type_params[type_param_index];
    if (type_param->constraint == NULL) {
        return true;
    }

    constraint_ref = instantiate_callable_constraint_for_owner_instance(
        context,
        callable,
        type_param_index,
        type_args,
        owner_type_decl,
        fit_decl,
        owner_type,
        &owned_constraint);
    if (constraint_ref == NULL) {
        return true;
    }
    if (callable->type_param_count > 0U && owned_constraint == NULL) {
        /* Preserve the existing deferred decision when another callable type
         * argument is still unknown and the constraint cannot be closed. */
        return true;
    }
    constraint_decl = resolve_type_ref_decl(context, constraint_ref);
    if (constraint_decl == NULL || constraint_decl->kind != FENG_DECL_SPEC) {
        free_synthetic_type_ref(owned_constraint);
        return true;
    }
    if (constraint_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT &&
        constraint_decl->as.spec_decl.form != FENG_SPEC_FORM_INTERSECTION) {
        /* callable-form / union-form constraints keep the pre-existing lenient
         * behavior; only object-form and intersection-form constraints are
         * enforced here. */
        free_synthetic_type_ref(owned_constraint);
        return true;
    }

    actual_type_ref = type_args[type_param_index];
    if (actual_type_ref == NULL) {
        /* The type argument could not be inferred from the call (e.g. a
         * parameter-less generic relying on explicit type args). Leave the
         * decision to the caller / later stages instead of rejecting. */
        free_synthetic_type_ref(owned_constraint);
        return true;
    }

    /* Reflexive case: when the inferred argument equals the required constraint
     * structurally (e.g. `rewrite<HasChild>(...)` binds T to the spec HasChild
     * while the constraint is also HasChild), the constraint is trivially
     * satisfied. This covers spec-as-argument and any self-referential shape
     * without needing full spec-implication analysis. */
    if (type_refs_semantically_equal(context, actual_type_ref, constraint_ref)) {
        result = true;
    } else if (actual_type_ref->kind == FENG_TYPE_REF_NAMED &&
               actual_type_ref->as.named.segment_count == 1U &&
               actual_type_ref->as.named.type_arg_count == 0U &&
               find_type_param(context, actual_type_ref->as.named.segments[0]) != NULL) {
        /* The inferred argument is itself a reference to an enclosing type
         * parameter (e.g. inside `assertEquals<T: Display>` we call
         * `format<U: Display>(first: U)` with `expected: T`). Whether the
         * candidate's constraint holds for the concrete type eventually bound
         * to T cannot be decided in isolation; the post-selection witness
         * materializer will finalize the answer at instantiation. Conservatively
         * accept so transitive generic call sites remain compilable. */
        result = true;
    } else {
        ObjectSpecUpcastPath upcast_path;

        /* A child object-form spec remains the concrete generic argument, but
         * its declared parent view satisfies the constraint surface. Reuse the
         * authoritative nominal upcast query so generic parent substitution,
         * transitive parents, and rejection of unrelated specs stay identical
         * to ordinary expected-type coercion. */
        if (constraint_decl->as.spec_decl.form == FENG_SPEC_FORM_OBJECT &&
            find_object_spec_upcast_path(
                context,
                inferred_expr_type_from_type_ref(actual_type_ref),
                constraint_ref,
                &upcast_path)) {
            object_spec_upcast_path_free(&upcast_path);
            result = true;
        } else {
            result = type_ref_satisfies_spec_type_ref(context,
                                                      actual_type_ref,
                                                      constraint_ref);
        }
    }

    free_synthetic_type_ref(owned_constraint);
    return result;
}

/* Materialize one object-spec witness for a subject without a declaration
 * identity. Builtins and arrays both enter through their authoritative
 * semantic subject key; exact generic spec instances additionally retain the
 * supplied spec type reference during satisfaction checking. */
static void materialize_non_decl_object_spec_witness_if_satisfied(
    ResolveContext *context,
    InferredExprType actual_type,
    const FengTypeRef *actual_type_ref,
    const FengDecl *spec_decl,
    const FengTypeRef *spec_type_ref,
    FengToken err_token) {
    FengSemanticSubjectKey subject_key;
    bool satisfies;

    if (context == NULL || actual_type_ref == NULL || spec_decl == NULL ||
        spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT ||
        !init_spec_witness_subject_key(NULL,
                                       actual_type_ref,
                                       context->pointer_size,
                                       &subject_key)) {
        return;
    }
    satisfies = spec_type_ref != NULL
        ? type_ref_satisfies_spec_type_ref(context,
                                           actual_type_ref,
                                           spec_type_ref)
        : subject_key_satisfies_spec_decl(context,
                                          &subject_key,
                                          spec_decl);
    if (!satisfies) {
        return;
    }
    compute_spec_witness_if_absent(context,
                                   NULL,
                                   actual_type,
                                   actual_type_ref,
                                   spec_decl,
                                   spec_type_ref,
                                   err_token);
}

/* 9.9: recursively traverse intersection-form constraint members with type-arg
 * substitution, materialising a per-member witness for each leaf object-form
 * member spec. For generic intersection constraints (e.g. ` Comparable<T>:
 * Eq<T> & Ord<T>` instantiated as `Comparable<IntBox>`), each member ref must
 * be substituted (Eq<T> -> Eq<IntBox>) so compute_spec_witness_if_absent can
 * match method signatures against the concrete type args. Nested intersection
 * members are recursively traversed, substituting at each level. */
static void materialize_intersection_constraint_member_witnesses(
    ResolveContext *context,
    const FengDecl *intersection_decl,
    const FengTypeParam *type_params,
    size_t type_param_count,
    FengTypeRef *const *type_args,
    const FengDecl *actual_type_decl,
    InferredExprType actual_type,
    const FengTypeRef *actual_type_ref,
    FengToken err_token) {
    size_t member_idx;

    if (context == NULL || intersection_decl == NULL ||
        intersection_decl->kind != FENG_DECL_SPEC ||
        intersection_decl->as.spec_decl.form != FENG_SPEC_FORM_INTERSECTION) {
        return;
    }
    for (member_idx = 0U;
         member_idx < intersection_decl->as.spec_decl.as.intersection_form.member_count;
         ++member_idx) {
        const FengTypeRef *member_ref =
            intersection_decl->as.spec_decl.as.intersection_form.members[member_idx];
        FengTypeRef *substituted_member_ref = NULL;
        const FengDecl *member_decl = NULL;
        bool tracked = false;

        if (member_ref == NULL) {
            continue;
        }
        substituted_member_ref = clone_type_ref_substituting_type_params(
            context->program,
            member_ref, type_params, type_param_count, type_args);
        if (substituted_member_ref == NULL) {
            continue;
        }
        if (!resolver_track_synthetic_type_ref(context, substituted_member_ref)) {
            free_synthetic_type_ref(substituted_member_ref);
            continue;
        }
        tracked = true;
        member_decl = resolve_type_ref_decl(context, substituted_member_ref);
        if (member_decl == NULL || member_decl->kind != FENG_DECL_SPEC) {
            continue;
        }
        if (member_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
            /* Nested intersection: recurse with the nested intersection's own
             * type params and the substituted type args from the member ref. */
            materialize_intersection_constraint_member_witnesses(
                context,
                member_decl,
                member_decl->as.spec_decl.type_params,
                member_decl->as.spec_decl.type_param_count,
                substituted_member_ref->as.named.type_args,
                actual_type_decl,
                actual_type,
                actual_type_ref,
                err_token);
        } else if (member_decl->as.spec_decl.form == FENG_SPEC_FORM_OBJECT) {
            if (actual_type_decl != NULL) {
                if (decl_is_named_fit_target(actual_type_decl)) {
                    if (!type_decl_satisfies_spec_decl(context, actual_type_decl,
                                                       member_decl)) {
                        continue;
                    }
                    compute_spec_witness_if_absent(context,
                                                   actual_type_decl,
                                                   actual_type,
                                                   actual_type_ref,
                                                   member_decl,
                                                   substituted_member_ref,
                                                   err_token);
                }
            } else {
                materialize_non_decl_object_spec_witness_if_satisfied(
                    context,
                    actual_type,
                    actual_type_ref,
                    member_decl,
                    substituted_member_ref,
                    err_token);
            }
        }
        (void)tracked;
    }
}

static void materialize_object_spec_constraint_witness_if_applicable(
    ResolveContext *context,
    const FengTypeParam *type_param,
    const FengTypeRef *actual_type_ref,
    const FengDecl *actual_type_decl,
    const FengTypeRef *instantiated_constraint,
    FengToken err_token) {
    const FengDecl *constraint_decl;

    if (context == NULL || type_param == NULL ||
        type_param->constraint == NULL) {
        return;
    }

    constraint_decl = resolve_type_ref_decl(context, type_param->constraint);
    if (constraint_decl == NULL || constraint_decl->kind != FENG_DECL_SPEC) {
        return;
    }

    /* Intersection-form constraint: materialize a per-member witness for each
     * leaf object-form member spec. Codegen's
     * cg_ensure_witness_instance_for_type assembles the merged witness by
     * aliasing slots from these per-member witnesses (see docs/engineering/feng-intersection-
     * type-draft.md §4.2). Satisfaction of the whole intersection was already
     * verified by generic_type_arg_satisfies_constraint; we still guard each
     * member defensively.
     *
     * 9.9: for generic intersection constraints (e.g. `Comparable<T>` with
     * type args from `instantiated_constraint`), each member ref must be
     * substituted with the type args so compute_spec_witness_if_absent can
     * match method signatures against concrete types. Non-generic intersections
     * fall back to the flattened_members path with spec_type_ref = NULL. */
    if (constraint_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
        bool has_type_args =
            instantiated_constraint != NULL &&
            instantiated_constraint->kind == FENG_TYPE_REF_NAMED &&
            instantiated_constraint->as.named.type_arg_count > 0U &&
            constraint_decl->as.spec_decl.type_param_count > 0U;

        if (has_type_args) {
            InferredExprType actual_type =
                inferred_expr_type_from_type_ref(actual_type_ref);
            materialize_intersection_constraint_member_witnesses(
                context,
                constraint_decl,
                constraint_decl->as.spec_decl.type_params,
                constraint_decl->as.spec_decl.type_param_count,
                instantiated_constraint->as.named.type_args,
                actual_type_decl,
                actual_type,
                actual_type_ref,
                err_token);
            return;
        }

        const FengIntersectionSpecInfo *info =
            feng_semantic_lookup_intersection_spec_info(context->analysis,
                                                        constraint_decl);
        size_t member_idx;

        if (info == NULL) {
            return;
        }
        for (member_idx = 0U; member_idx < info->flattened_member_count;
             ++member_idx) {
            const FengDecl *member_decl = info->flattened_members[member_idx];

            if (member_decl == NULL ||
                member_decl->kind != FENG_DECL_SPEC ||
                member_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
                continue;
            }
            if (decl_is_named_fit_target(actual_type_decl)) {
                if (!type_decl_satisfies_spec_decl(context, actual_type_decl,
                                                   member_decl)) {
                    continue;
                }
                compute_spec_witness_if_absent(context,
                                               actual_type_decl,
                                               inferred_expr_type_from_type_ref(actual_type_ref),
                                               actual_type_ref,
                                               member_decl,
                                               NULL,
                                               err_token);
            } else {
                materialize_non_decl_object_spec_witness_if_satisfied(
                    context,
                    inferred_expr_type_from_type_ref(actual_type_ref),
                    actual_type_ref,
                    member_decl,
                    NULL,
                    err_token);
            }
        }
        return;
    }

    if (constraint_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return;
    }

    if (decl_is_named_fit_target(actual_type_decl)) {
        if (actual_type_ref == NULL || instantiated_constraint == NULL ||
            !type_ref_satisfies_spec_type_ref(context,
                                              actual_type_ref,
                                              instantiated_constraint)) {
            return;
        }
        compute_spec_witness_if_absent(context,
                                       actual_type_decl,
                                       inferred_expr_type_from_type_ref(actual_type_ref),
                                       actual_type_ref,
                                       constraint_decl,
                                       instantiated_constraint,
                                       err_token);
        return;
    }

    materialize_non_decl_object_spec_witness_if_satisfied(
        context,
        inferred_expr_type_from_type_ref(actual_type_ref),
        actual_type_ref,
        constraint_decl,
        instantiated_constraint,
        err_token);
}

static void materialize_named_type_param_constraint_witnesses(
    ResolveContext *context,
    const FengTypeParam *type_params,
    size_t type_param_count,
    const FengTypeRef *const *type_args,
    size_t type_arg_count,
    FengToken err_token) {
    size_t i;

    if (context == NULL || type_params == NULL || type_args == NULL) {
        return;
    }

    for (i = 0U; i < type_param_count && i < type_arg_count; ++i) {
        const FengDecl *actual_type_decl = resolve_type_ref_decl(context, type_args[i]);
        const FengTypeRef *instantiated_constraint = type_params[i].constraint;

        if (instantiated_constraint != NULL && type_param_count > 0U) {
            FengTypeRef *subst = clone_type_ref_substituting_type_params(
                context->program,
                instantiated_constraint,
                type_params,
                type_param_count,
                (FengTypeRef *const *)type_args);
            if (subst != NULL) {
                if (resolver_track_synthetic_type_ref(context, subst)) {
                    instantiated_constraint = subst;
                } else {
                    free_synthetic_type_ref(subst);
                }
            }
        }

        materialize_object_spec_constraint_witness_if_applicable(context,
                                                                 &type_params[i],
                                                                 type_args[i],
                                                                 actual_type_decl,
                                                                 instantiated_constraint,
                                                                 err_token);
    }
}

static void materialize_callable_type_param_constraint_witnesses(
    ResolveContext *context,
    const FengExpr *call_expr,
    const FengCallableSignature *callable,
    const FengDecl *owner_type_decl,
    const FengDecl *fit_decl,
    InferredExprType owner_type) {
    size_t i;
    FengTypeRef **type_args = NULL;
    bool *owned_type_args = NULL;
    const FengTypeRef *target_inference_return_type;

    if (context == NULL || call_expr == NULL || callable == NULL) {
        return;
    }
    if (callable->type_param_count == 0U) {
        return;
    }

    type_args = calloc(callable->type_param_count, sizeof *type_args);
    owned_type_args = calloc(callable->type_param_count, sizeof *owned_type_args);
    if (type_args == NULL || owned_type_args == NULL) {
        free(type_args);
        free(owned_type_args);
        return;
    }
    target_inference_return_type = substitute_type_ref_for_owner_instance(
        context,
        owner_type_decl,
        owner_type,
        callable->return_type);
    target_inference_return_type = substitute_type_ref_for_fit_instance(
        context,
        fit_decl,
        owner_type,
        target_inference_return_type);
    if (!callable_collect_call_type_args(context,
                                         call_expr,
                                         callable,
                                         target_inference_return_type,
                                         call_expr_allows_wrapped_generic_extern_inference(call_expr),
                                         false,
                                         type_args,
                                         owned_type_args)) {
        goto cleanup;
    }

    for (i = 0U; i < callable->type_param_count; ++i) {
        const FengDecl *actual_type_decl = NULL;
        const FengTypeRef *actual_type_ref = NULL;
        const FengTypeRef *instantiated_constraint;
        FengTypeRef *owned_constraint = NULL;

        if (type_args[i] != NULL) {
            actual_type_ref = type_args[i];
            actual_type_decl = resolve_type_ref_decl(context, type_args[i]);
        }
        instantiated_constraint = instantiate_callable_constraint_for_owner_instance(
            context,
            callable,
            i,
            type_args,
            owner_type_decl,
            fit_decl,
            owner_type,
            &owned_constraint);
        if (owned_constraint != NULL &&
            !resolver_track_synthetic_type_ref(context, owned_constraint)) {
            free_synthetic_type_ref(owned_constraint);
            owned_constraint = NULL;
            instantiated_constraint =
                instantiate_callable_constraint_for_owner_instance(
                    context,
                    callable,
                    i,
                    NULL,
                    owner_type_decl,
                    fit_decl,
                    owner_type,
                    NULL);
        }

        materialize_object_spec_constraint_witness_if_applicable(context,
                                                                 &callable->type_params[i],
                                                                 actual_type_ref,
                                                                 actual_type_decl,
                                                                 instantiated_constraint,
                                                                 call_expr->token);
    }

cleanup:
    for (size_t k = 0U; k < callable->type_param_count; ++k) {
        if (owned_type_args[k]) {
            free_synthetic_type_ref(type_args[k]);
        }
    }
    free(type_args);
    free(owned_type_args);
}

static FengSpecCoercionCallableSource classify_callable_source(
        const ResolveContext *context, const FengExpr *expr) {
    if (expr == NULL) {
        return FENG_SPEC_COERCION_CALLABLE_SOURCE_OTHER;
    }
    switch (expr->kind) {
        case FENG_EXPR_GENERIC_TARGET:
            return classify_callable_source(context,
                                            expr->as.generic_target.target);
        case FENG_EXPR_LAMBDA:
            return FENG_SPEC_COERCION_CALLABLE_SOURCE_LAMBDA;
        case FENG_EXPR_IDENTIFIER: {
            /* If the identifier resolves to a local binding/parameter, treat
             * as a generic callable value. Otherwise, if it names a top-level
             * function (overload set), classify as TOP_LEVEL_FN. */
            if (resolver_find_local_name_entry(context, expr->as.identifier) != NULL) {
                return FENG_SPEC_COERCION_CALLABLE_SOURCE_OTHER;
            }
            if (find_function_overload_set(context->function_sets,
                                           context->function_set_count,
                                           expr->as.identifier) != NULL) {
                return FENG_SPEC_COERCION_CALLABLE_SOURCE_TOP_LEVEL_FN;
            }
            return FENG_SPEC_COERCION_CALLABLE_SOURCE_OTHER;
        }
        case FENG_EXPR_MEMBER: {
            /* Alias-qualified and full-path top-level functions report as
             * TOP_LEVEL_FN; `obj.method` reports as METHOD_VALUE. */
            ResolvedModuleMemberTarget target;

            if (resolve_module_member_target(context, expr, &target) &&
                find_module_public_function_decl(target.module,
                                                 target.member_name) != NULL) {
                return FENG_SPEC_COERCION_CALLABLE_SOURCE_TOP_LEVEL_FN;
            }
            return FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE;
        }
        default:
            return FENG_SPEC_COERCION_CALLABLE_SOURCE_OTHER;
    }
}

static void record_callable_spec_coercion_site(ResolveContext *context,
                                               const FengExpr *expr,
                                               const FengTypeRef *expected_type_ref) {
    const FengDecl *target_decl;
    CallableValueResolution resolution;
    FengSpecCoercionCallableSource source;
    const FengExpr *source_expr;
    const FengTypeRef *receiver_type_ref = NULL;
    FengTypeRef *synthetic_receiver_type_ref = NULL;

    if (context == NULL || context->analysis == NULL || expr == NULL ||
        expected_type_ref == NULL) {
        return;
    }
    target_decl = resolve_function_type_decl(context, expected_type_ref);
    if (target_decl == NULL) {
        return;
    }
    resolution = resolve_expr_callable_value(context, expr, expected_type_ref);
    if (resolution.kind != FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE) {
        return;
    }
    source_expr = expr->kind == FENG_EXPR_GENERIC_TARGET
                      ? expr->as.generic_target.target
                      : expr;
    source = classify_callable_source(context, source_expr);
    /* Member expressions can denote either method values or plain callable-
     * typed fields/values. Only keep METHOD_VALUE when semantic resolution
     * actually identified a method binding; otherwise route as OTHER. */
    if (source == FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE &&
        resolution.callable_member == NULL) {
        source = FENG_SPEC_COERCION_CALLABLE_SOURCE_OTHER;
    }
    if (source == FENG_SPEC_COERCION_CALLABLE_SOURCE_METHOD_VALUE &&
        source_expr != NULL && source_expr->kind == FENG_EXPR_MEMBER &&
        source_expr->as.member.object != NULL) {
        InferredExprType receiver_type = inferred_expr_type_unknown();

        if (resolution.callable_member != NULL &&
            resolution.callable_member->is_static) {
            ResolvedTypeTarget static_target = resolve_type_target_expr(
                context, source_expr->as.member.object, false);

            if (static_target.is_generic_type_param &&
                source_expr->as.member.object->kind ==
                    FENG_EXPR_IDENTIFIER) {
                FengSlice *segments =
                    (FengSlice *)malloc(sizeof(*segments));

                if (segments != NULL) {
                    segments[0] =
                        source_expr->as.member.object->as.identifier;
                    synthetic_receiver_type_ref =
                        create_named_type_ref_for_inference(
                            source_expr->as.member.object->token,
                            segments,
                            1U);
                    if (synthetic_receiver_type_ref == NULL) {
                        free(segments);
                    } else {
                        receiver_type_ref = synthetic_receiver_type_ref;
                    }
                }
            } else {
                receiver_type =
                    resolved_type_target_owner_type(&static_target);
            }
        } else {
            receiver_type =
                infer_expr_type(context, source_expr->as.member.object);
        }

        if (receiver_type_ref == NULL &&
            receiver_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
            receiver_type_ref = receiver_type.type_ref;
        } else if (receiver_type_ref == NULL &&
                   receiver_type.kind == FENG_INFERRED_EXPR_TYPE_BUILTIN) {
            synthetic_receiver_type_ref =
                create_type_ref_from_inferred_type(&receiver_type, expr->token);
            receiver_type_ref = synthetic_receiver_type_ref;
        } else if (receiver_type_ref == NULL &&
                   receiver_type.kind == FENG_INFERRED_EXPR_TYPE_DECL &&
                   receiver_type.type_decl != NULL &&
                   receiver_type.type_decl->kind == FENG_DECL_TYPE) {
            const FengDecl *receiver_decl = receiver_type.type_decl;
            const FengSemanticModule *receiver_module =
                find_decl_provider_module(context->analysis, receiver_decl);
            size_t module_segment_count = receiver_module != NULL
                                              ? receiver_module->segment_count : 0U;
            size_t type_param_count =
                receiver_decl->as.type_decl.type_param_count;

            synthetic_receiver_type_ref = (FengTypeRef *)calloc(
                1U, sizeof(*synthetic_receiver_type_ref));
            if (synthetic_receiver_type_ref != NULL) {
                synthetic_receiver_type_ref->token = expr->token;
                synthetic_receiver_type_ref->kind = FENG_TYPE_REF_NAMED;
                synthetic_receiver_type_ref->as.named.segments =
                    (FengSlice *)malloc((module_segment_count + 1U) * sizeof(FengSlice));
                synthetic_receiver_type_ref->as.named.type_args =
                    type_param_count > 0U
                        ? (FengTypeRef **)calloc(
                              type_param_count,
                              sizeof(*synthetic_receiver_type_ref->as.named.type_args))
                        : NULL;
                if (synthetic_receiver_type_ref->as.named.segments != NULL &&
                    (type_param_count == 0U ||
                     synthetic_receiver_type_ref->as.named.type_args != NULL)) {
                    bool complete = true;

                    /* This metadata outlives source lookup. Preserve owner
                     * identity even when only an alias makes it accessible. */
                    if (module_segment_count > 0U) {
                        memcpy(synthetic_receiver_type_ref->as.named.segments,
                               receiver_module->segments,
                               module_segment_count * sizeof(FengSlice));
                    }
                    synthetic_receiver_type_ref->as.named.segments[module_segment_count] =
                        receiver_decl->as.type_decl.name;
                    synthetic_receiver_type_ref->as.named.segment_count = module_segment_count + 1U;
                    synthetic_receiver_type_ref->as.named.type_arg_count =
                        type_param_count;
                    for (size_t index = 0U;
                         index < type_param_count;
                         ++index) {
                        FengTypeRef *arg =
                            (FengTypeRef *)calloc(1U, sizeof(*arg));

                        if (arg == NULL) {
                            complete = false;
                            break;
                        }
                        arg->token = receiver_decl->as.type_decl.type_params[index].token;
                        arg->kind = FENG_TYPE_REF_NAMED;
                        arg->as.named.segments =
                            (FengSlice *)malloc(sizeof(FengSlice));
                        if (arg->as.named.segments == NULL) {
                            free(arg);
                            complete = false;
                            break;
                        }
                        arg->as.named.segments[0] =
                            receiver_decl->as.type_decl.type_params[index].name;
                        arg->as.named.segment_count = 1U;
                        synthetic_receiver_type_ref->as.named.type_args[index] = arg;
                    }
                    if (complete) {
                        receiver_type_ref = synthetic_receiver_type_ref;
                    }
                }
            }
        }
    }
    (void)feng_semantic_record_callable_spec_coercion_site(
        context->analysis,
        expr,
        target_decl,
        expected_type_ref,
        source,
        resolution.callable_decl,
        resolution.callable_member,
        resolution.callable_owner_type_decl,
        resolution.callable_fit_decl,
        receiver_type_ref,
        resolution.callable_type_args,
        resolution.callable_type_arg_count,
        resolution.lambda_expr);
    free_synthetic_type_ref(synthetic_receiver_type_ref);
}

static void record_abi_function_pointer_site(ResolveContext *context,
                                             const FengExpr *expr,
                                             const FengTypeRef *expected_type_ref,
                                             const FengDecl *function_decl) {
    const FengDecl *target_decl;
    const FengTypeRef *target_spec_type_ref;

    if (context == NULL || context->analysis == NULL || expr == NULL ||
        expected_type_ref == NULL || function_decl == NULL) {
        return;
    }

    target_decl = resolve_abi_function_pointer_type_decl(context, expected_type_ref);
    if (target_decl == NULL) {
        return;
    }
    if (expected_type_ref->kind != FENG_TYPE_REF_POINTER || expected_type_ref->as.inner == NULL) {
        return;
    }
    target_spec_type_ref = expected_type_ref->as.inner;

    (void)feng_semantic_record_abi_function_pointer_site(context->analysis,
                                                         expr,
                                                         target_decl,
                                                         target_spec_type_ref,
                                                         function_decl);
}

/* Phase S2-a — SpecDefaultBinding recording helper (§6.3). Records a
 * default-witness site when `binding_type` resolves to an object-form or
 * callable-form spec decl. Caller is responsible for ensuring this is invoked
 * only when the slot has no initializer. Silent no-op when the type does
 * not resolve to a spec. */
static void record_spec_default_binding_if_applicable(
        ResolveContext *context,
        const void *site,
        FengSpecDefaultBindingPosition position,
        const FengTypeRef *binding_type) {
    const FengDecl *decl;
    FengSpecCoercionForm form;

    if (context == NULL || context->analysis == NULL || site == NULL ||
        binding_type == NULL) {
        return;
    }
    decl = resolve_type_ref_decl(context, binding_type);
    if (decl == NULL || decl->kind != FENG_DECL_SPEC) {
        return;
    }
    if (decl->as.spec_decl.form == FENG_SPEC_FORM_UNION) {
        return;
    }
    form = decl_is_function_type(decl) ? FENG_SPEC_COERCION_FORM_CALLABLE
                                       : FENG_SPEC_COERCION_FORM_OBJECT;
    (void)feng_semantic_record_spec_default_binding(context->analysis,
                                                    site,
                                                    position,
                                                    form,
                                                    decl);
}

/* Phase S2-b — SpecMemberAccess recording helper (§6.4). Records a member
 * access site for an `obj.member` expression whose owner static type is an
 * object-form spec. Recorded kind is METHOD_CALL for method members and
 * FIELD_READ for field members; the assignment statement resolver later
 * upgrades FIELD_READ to FIELD_WRITE for assignment LHS positions. */
static void record_spec_member_access(ResolveContext *context,
                                      const FengExpr *expr,
                                      const FengDecl *spec_decl,
                                      const FengTypeMember *member) {
    FengSpecMemberAccessKind kind;

    if (context == NULL || context->analysis == NULL || expr == NULL ||
        spec_decl == NULL || member == NULL) {
        return;
    }
    if (member->kind == FENG_TYPE_MEMBER_FIELD) {
        kind = FENG_SPEC_MEMBER_ACCESS_KIND_FIELD_READ;
    } else {
        kind = FENG_SPEC_MEMBER_ACCESS_KIND_METHOD_CALL;
    }
    (void)feng_semantic_record_spec_member_access(context->analysis,
                                                  expr,
                                                  spec_decl,
                                                  member,
                                                  kind);
}

/* Phase S4 — SpecEquality recording helper (§6.6). Records an equality
 * site for a binary `==` / `!=` expression whose operands' static type is
 * an object-form spec. The semantic conclusion is "reference-identity
 * comparison"; codegen consults the sidecar to keep spec equality
 * decoupled from the value-equality path used by string / array. */
static void record_spec_equality_if_applicable(ResolveContext *context,
                                               const FengExpr *expr) {
    InferredExprType left_type;
    const FengDecl *spec_decl;
    FengSpecEqualityOp op;

    if (context == NULL || context->analysis == NULL || expr == NULL) {
        return;
    }
    if (expr->kind != FENG_EXPR_BINARY) {
        return;
    }
    if (expr->as.binary.op != FENG_TOKEN_EQ && expr->as.binary.op != FENG_TOKEN_NE) {
        return;
    }
    /* validate_binary_expr has already asserted both operands have the
     * same static type and that the type is "known"; checking only the
     * left operand is sufficient. */
    left_type = infer_expr_type(context, expr->as.binary.left);
    spec_decl = resolve_inferred_expr_type_decl(context, left_type);
    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC) {
        return;
    }
    /* Object-form specs use the aggregate subject-identity sidecar.
     * Callable-form specs are managed closure references and take the direct
     * reference-identity lowering path in codegen. Other forms keep their
     * dedicated semantic restrictions. */
    if (spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return;
    }
    op = expr->as.binary.op == FENG_TOKEN_EQ
             ? FENG_SPEC_EQUALITY_OP_EQ
             : FENG_SPEC_EQUALITY_OP_NE;
    (void)feng_semantic_record_spec_equality(context->analysis, expr,
                                             spec_decl, op);
}

typedef enum AbiFunctionPointerAddressResolutionKind {
    ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_INVALID_SOURCE,
    ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_NO_MATCH,
    ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_UNIQUE,
    ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_AMBIGUOUS,
} AbiFunctionPointerAddressResolutionKind;

typedef struct AbiFunctionPointerAddressResolution {
    AbiFunctionPointerAddressResolutionKind kind;
    const FengDecl *function_decl;
} AbiFunctionPointerAddressResolution;

static AbiFunctionPointerAddressResolution resolve_abi_function_pointer_address(
    ResolveContext *context,
    const FengExpr *operand,
    const FengTypeRef *expected_function_type_ref,
    const FengDecl *expected_function_type_decl) {
    AbiFunctionPointerAddressResolution result;

    memset(&result, 0, sizeof(result));
    result.kind = ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_INVALID_SOURCE;
    if (context == NULL || operand == NULL || expected_function_type_ref == NULL ||
        expected_function_type_decl == NULL) {
        return result;
    }

    if (operand->kind == FENG_EXPR_IDENTIFIER) {
        const FunctionOverloadSetEntry *overload_set;

        if (resolver_find_local_name_entry(context, operand->as.identifier) != NULL) {
            return result;
        }

        overload_set = find_function_overload_set(context->function_sets,
                                                  context->function_set_count,
                                                  operand->as.identifier);
        if (overload_set == NULL) {
            return result;
        }

        result.kind = ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_NO_MATCH;
        for (size_t decl_index = 0U; decl_index < overload_set->decl_count; ++decl_index) {
            const FengDecl *decl = overload_set->decls[decl_index];

            if (decl == NULL || decl->kind != FENG_DECL_FUNCTION || decl->is_extern ||
                !annotations_contain_kind(decl->annotations,
                                          decl->annotation_count,
                                          FENG_ANNOTATION_ABI) ||
                !function_type_decl_matches_callable_signature_or_is_pending(
                    context,
                    expected_function_type_ref,
                    expected_function_type_decl,
                    &decl->as.function_decl)) {
                continue;
            }

            if (result.kind == ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_NO_MATCH) {
                result.kind = ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_UNIQUE;
                result.function_decl = decl;
                continue;
            }

            result.kind = ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_AMBIGUOUS;
            result.function_decl = NULL;
            return result;
        }

        return result;
    }

    if (operand->kind == FENG_EXPR_MEMBER) {
        ResolvedModuleMemberTarget module_target;

        if (!resolve_module_member_target(
                context, operand, &module_target)) {
            return result;
        }

        result.kind = ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_NO_MATCH;
        for (size_t program_index = 0U;
             program_index < module_target.module->program_count;
             ++program_index) {
            const FengProgram *program =
                module_target.module->programs[program_index];

            for (size_t decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
                const FengDecl *decl = program->declarations[decl_index];

                if (decl->kind != FENG_DECL_FUNCTION || !decl_is_public(decl) || decl->is_extern ||
                    !slice_equals(decl->as.function_decl.name,
                                  module_target.member_name) ||
                    !annotations_contain_kind(decl->annotations,
                                              decl->annotation_count,
                                              FENG_ANNOTATION_ABI) ||
                    !function_type_decl_matches_callable_signature_or_is_pending(
                        context,
                        expected_function_type_ref,
                        expected_function_type_decl,
                        &decl->as.function_decl)) {
                    continue;
                }

                if (result.kind == ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_NO_MATCH) {
                    result.kind = ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_UNIQUE;
                    result.function_decl = decl;
                    continue;
                }

                result.kind = ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_AMBIGUOUS;
                result.function_decl = NULL;
                return result;
            }
        }

        return result;
    }

    return result;
}

static bool expr_matches_expected_abi_function_pointer_type(ResolveContext *context,
                                                            const FengExpr *expr,
                                                            const FengTypeRef *expected_type_ref) {
    const FengDecl *expected_function_type_decl;
    AbiFunctionPointerAddressResolution resolution;

    if (expr == NULL || expr->kind != FENG_EXPR_UNARY || expr->as.unary.op != FENG_TOKEN_AMP) {
        return false;
    }

    expected_function_type_decl =
        resolve_abi_function_pointer_type_decl(context, expected_type_ref);
    if (expected_function_type_decl == NULL) {
        return false;
    }

    resolution = resolve_abi_function_pointer_address(context,
                                                      expr->as.unary.operand,
                                                      expected_type_ref->as.inner,
                                                      expected_function_type_decl);
    if (resolution.kind != ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_UNIQUE) {
        return false;
    }

    record_abi_function_pointer_site(context,
                                     expr,
                                     expected_type_ref,
                                     resolution.function_decl);
    return true;
}

static bool expr_matches_expected_address_of_data_pointer_type(
    ResolveContext *context,
    const FengExpr *expr,
    const FengTypeRef *expected_type_ref) {
    InferredExprType operand_type;

    if (expr == NULL || expr->kind != FENG_EXPR_UNARY || expr->as.unary.op != FENG_TOKEN_AMP ||
        expected_type_ref == NULL || expected_type_ref->kind != FENG_TYPE_REF_POINTER ||
        resolve_abi_function_pointer_type_decl(context, expected_type_ref) != NULL) {
        return false;
    }

    operand_type = infer_expr_type(context, expr->as.unary.operand);
    if (inferred_expr_type_is_string(operand_type)) {
        const char *builtin_name = type_ref_builtin_canonical_name(expected_type_ref->as.inner, context->pointer_size);

        return builtin_name != NULL && strcmp(builtin_name, "string") == 0;
    }

    if (inferred_expr_type_is_abi_array_value(context, operand_type)) {
        return type_refs_semantically_equal(context,
                                            operand_type.type_ref->as.inner,
                                            expected_type_ref->as.inner);
    }

    return inferred_expr_type_is_data_addressable_abi_value(context, operand_type) &&
           inferred_expr_type_matches_type_ref(context,
                                              operand_type,
                                              expected_type_ref->as.inner);
}

static bool expr_is_borrowed_data_pointer_value(ResolveContext *context,
                                                const FengExpr *expr,
                                                size_t depth) {
    InferredExprType operand_type;

    if (context == NULL || expr == NULL || depth > 32U) {
        return false;
    }

    switch (expr->kind) {
        case FENG_EXPR_UNARY:
            if (expr->as.unary.op != FENG_TOKEN_AMP) {
                return false;
            }

            operand_type = infer_expr_type(context, expr->as.unary.operand);
            if (expr_is_callable_like_address_of_operand(context,
                                                        expr->as.unary.operand,
                                                        operand_type)) {
                return false;
            }

            return inferred_expr_type_is_data_addressable_abi_value(context, operand_type) ||
                   inferred_expr_type_is_string(operand_type) ||
                   inferred_expr_type_is_abi_array_value(context, operand_type);

        case FENG_EXPR_IDENTIFIER: {
            const LocalNameEntry *local_entry =
                resolver_find_local_name_entry(context, expr->as.identifier);

            if (local_entry != NULL && local_entry->source_expr != NULL) {
                return expr_is_borrowed_data_pointer_value(context,
                                                           local_entry->source_expr,
                                                           depth + 1U);
            }

            {
                const VisibleValueEntry *visible_value =
                    find_visible_value(context->visible_values,
                                       context->visible_value_count,
                                       expr->as.identifier);

                if (visible_value != NULL && !visible_value->is_function &&
                    visible_value->decl != NULL &&
                    visible_value->decl->kind == FENG_DECL_GLOBAL_BINDING &&
                    visible_value->decl->as.binding.initializer != NULL) {
                    return expr_is_borrowed_data_pointer_value(
                        context,
                        visible_value->decl->as.binding.initializer,
                        depth + 1U);
                }
            }

            return false;
        }

        default:
            return false;
    }
}

static bool type_ref_is_data_pointer_type(ResolveContext *context,
                                          const FengTypeRef *type_ref) {
    return type_ref != NULL && type_ref->kind == FENG_TYPE_REF_POINTER &&
           resolve_abi_function_pointer_type_decl(context, type_ref) == NULL;
}

static bool validate_borrowed_data_pointer_call_arguments(
    ResolveContext *context,
    const FengExpr *callee,
    FengExpr *const *args,
    size_t arg_count,
    const FengParameter *params,
    size_t param_count,
    bool allow_borrowed_data_pointer_args) {
    size_t index;
    bool is_variadic;
    size_t fixed_count;

    if (allow_borrowed_data_pointer_args || params == NULL) {
        return true;
    }

    is_variadic = param_count > 0U && params[param_count - 1U].is_variadic;
    fixed_count = is_variadic ? param_count - 1U : param_count;
    if (is_variadic && arg_count < fixed_count) {
        return true;
    }

    for (index = 0U; index < arg_count; ++index) {
        const FengTypeRef *param_type =
            (is_variadic && index >= fixed_count) ? params[fixed_count].type->as.inner : params[index].type;
        char *callee_name;
        char *expr_name;

        if (!type_ref_is_data_pointer_type(context, param_type) ||
            !expr_is_borrowed_data_pointer_value(context, args[index], 0U)) {
            continue;
        }

        callee_name = format_expr_target_name(callee);
        expr_name = format_expr_target_name(args[index]);
        if (!resolver_append_error(
                context,
                args[index]->token,
                "AE1323", format_message(
                    "argument %zu expression '%s' is a borrowed data pointer formed by '&'; borrowed data pointers are only guaranteed valid for the current extern call and cannot be passed to non-extern callable '%s'; retain the original owner and form the pointer at the extern boundary",
                    index + 1U,
                    expr_name != NULL ? expr_name : "<expression>",
                    callee_name != NULL ? callee_name : "<callable>"))) {
            free(callee_name);
            free(expr_name);
            return false;
        }

        free(callee_name);
        free(expr_name);
        return true;
    }

    return true;
}

static bool validate_borrowed_data_pointer_object_field(ResolveContext *context,
                                                        const FengObjectFieldInit *field,
                                                        const FengTypeRef *field_type) {
    char *expr_name;

    if (field == NULL || !type_ref_is_data_pointer_type(context, field_type) ||
        !expr_is_borrowed_data_pointer_value(context, field->value, 0U)) {
        return true;
    }

    expr_name = format_expr_target_name(field->value);
    if (!resolver_append_error(
            context,
            field->token,
            "AE1324", format_message(
                "object literal field '%.*s' cannot store borrowed data pointer expression '%s'; borrowed data pointers are only guaranteed valid for the current extern call; retain the original owner instead of caching the raw pointer",
                (int)field->name.length,
                field->name.data,
                expr_name != NULL ? expr_name : "<expression>"))) {
        free(expr_name);
        return false;
    }

    free(expr_name);
    return true;
}

static bool validate_borrowed_data_pointer_assignment(ResolveContext *context,
                                                      const FengExpr *target,
                                                      const FengExpr *value,
                                                      InferredExprType target_type) {
    char *target_name;
    char *expr_name;

    if (target == NULL || value == NULL || target_type.kind != FENG_INFERRED_EXPR_TYPE_TYPE_REF ||
        !type_ref_is_data_pointer_type(context, target_type.type_ref) ||
        !expr_is_borrowed_data_pointer_value(context, value, 0U)) {
        return true;
    }

    target_name = format_expr_target_name(target);
    expr_name = format_expr_target_name(value);
    if (!resolver_append_error(
            context,
            value->token,
            "AE1325", format_message(
                "assignment target '%s' cannot store borrowed data pointer expression '%s'; borrowed data pointers are only guaranteed valid for the current extern call; retain the original owner instead of caching the raw pointer",
                target_name != NULL ? target_name : "<target>",
                expr_name != NULL ? expr_name : "<expression>"))) {
        free(target_name);
        free(expr_name);
        return false;
    }

    free(target_name);
    free(expr_name);
    return true;
}

static bool validate_expr_against_expected_abi_function_pointer_type(
    ResolveContext *context,
    const FengExpr *expr,
    const FengTypeRef *expected_type_ref) {
    const FengDecl *expected_function_type_decl;
    AbiFunctionPointerAddressResolution resolution;
    char *expr_name;
    char *type_name;

    expected_function_type_decl =
        resolve_abi_function_pointer_type_decl(context, expected_type_ref);
    if (expected_function_type_decl == NULL || expr == NULL || expr->kind != FENG_EXPR_UNARY ||
        expr->as.unary.op != FENG_TOKEN_AMP) {
        return false;
    }

    resolution = resolve_abi_function_pointer_address(context,
                                                      expr->as.unary.operand,
                                                      expected_type_ref->as.inner,
                                                      expected_function_type_decl);
    if (resolution.kind == ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_UNIQUE) {
        record_abi_function_pointer_site(context,
                                         expr,
                                         expected_type_ref,
                                         resolution.function_decl);
        return true;
    }

    expr_name = format_expr_target_name(expr);
    type_name = format_type_ref_name(expected_type_ref);

    if (resolution.kind == ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_AMBIGUOUS) {
        bool ok = resolver_append_error(
            context,
            expr->token,
            "AE0521", format_message(
                "expression '%s' has multiple overloads matching expected ABI function pointer type '%s'",
                expr_name != NULL ? expr_name : "<expression>",
                type_name != NULL ? type_name : "<type>"));

        free(expr_name);
        free(type_name);
        return ok;
    }

    {
        bool ok = resolver_append_error(
            context,
            expr->token,
            resolution.kind == ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_NO_MATCH ? "AE0230" : "AE0231",
            format_message(
                resolution.kind == ABI_FUNCTION_POINTER_ADDRESS_RESOLUTION_NO_MATCH
                    ? "expression '%s' does not match expected ABI function pointer type '%s'; ABI function pointers can only be formed from top-level @abi functions with an explicit Foo* target type"
                    : "expression '%s' cannot form expected ABI function pointer type '%s'; ABI function pointers can only be formed from top-level @abi functions with an explicit Foo* target type",
                expr_name != NULL ? expr_name : "<expression>",
                type_name != NULL ? type_name : "<type>"));

        free(expr_name);
        free(type_name);
        return ok;
    }
}

/* Record the exact member method selected for a callable value. Resolver
 * candidate probes are intentionally side-effect free; this hook runs only
 * after target-type matching produced one unique instance or static method. */
static bool record_selected_friend_callable_value_access(
    ResolveContext *context,
    const FengExpr *expr,
    const CallableValueResolution *resolution) {
    const FengExpr *source_expr = expr;
    InferredExprType owner_type;

    if (context == NULL || resolution == NULL ||
        resolution->callable_member == NULL) {
        return true;
    }
    if (source_expr != NULL && source_expr->kind == FENG_EXPR_GENERIC_TARGET) {
        source_expr = source_expr->as.generic_target.target;
    }
    if (source_expr == NULL || source_expr->kind != FENG_EXPR_MEMBER ||
        source_expr->as.member.object == NULL) {
        return true;
    }
    if (resolution->callable_member->is_static) {
        ResolvedTypeTarget static_target = resolve_type_target_expr(
            context, source_expr->as.member.object, false);

        if (static_target.is_generic_type_param &&
            static_target.constraint_spec_type_ref != NULL) {
            const FengTypeRef *declaring_instance =
                constraint_member_declaring_spec_instance(
                    context,
                    &static_target,
                    resolution->callable_owner_type_decl);

            owner_type = inferred_expr_type_from_type_ref(
                declaring_instance != NULL
                    ? declaring_instance
                    : static_target.constraint_spec_type_ref);
        } else {
            owner_type = resolved_type_target_owner_type(&static_target);
        }
    } else {
        owner_type = resolution->callable_owner_instance_type_ref != NULL
                         ? inferred_expr_type_from_type_ref(
                               resolution->callable_owner_instance_type_ref)
                         : infer_expr_type(context,
                                           source_expr->as.member.object);
    }
    return record_selected_friend_fit_access(
        context,
        resolution->callable_owner_type_decl,
        owner_type,
        resolution->callable_member);
}

/* Report the existing spec-seal diagnostic when a constrained generic
 * receiver has an exact target-signature match that normal method-value
 * resolution excluded only for accessibility. The normal filtered query has
 * already returned NONE; this fallback never contributes a callable source. */
static bool report_inaccessible_constrained_generic_method_value(
    ResolveContext *context,
    const FengExpr *expr,
    const FengTypeRef *expected_type_ref,
    bool *out_reported) {
    const FengExpr *source_expr = expr;
    const FengDecl *constraint_decl = NULL;
    const FengTypeRef *constraint_ref = NULL;
    const FengDecl *function_type_decl;
    InferredExprType receiver_type;
    InferredExprType constraint_owner;
    CallableValueResolution inaccessible;
    bool is_static_type_param_source = false;

    if (out_reported == NULL) {
        return false;
    }
    *out_reported = false;
    if (source_expr != NULL &&
        source_expr->kind == FENG_EXPR_GENERIC_TARGET) {
        source_expr = source_expr->as.generic_target.target;
    }
    if (context == NULL || source_expr == NULL ||
        source_expr->kind != FENG_EXPR_MEMBER ||
        source_expr->as.member.object == NULL) {
        return true;
    }
    {
        ResolvedTypeTarget static_target = resolve_type_target_expr(
            context, source_expr->as.member.object, false);

        if (static_target.is_generic_type_param &&
            static_target.constraint_spec_decl != NULL &&
            (static_target.constraint_spec_decl->as.spec_decl.form ==
                 FENG_SPEC_FORM_OBJECT ||
             static_target.constraint_spec_decl->as.spec_decl.form ==
                 FENG_SPEC_FORM_INTERSECTION)) {
            constraint_decl = static_target.constraint_spec_decl;
            constraint_ref = static_target.constraint_spec_type_ref;
            is_static_type_param_source = true;
        } else {
            receiver_type = infer_expr_type(
                context, source_expr->as.member.object);
            if (!resolve_generic_param_spec_constraint(context,
                                                       receiver_type,
                                                       &constraint_decl,
                                                       &constraint_ref)) {
                return true;
            }
        }
    }
    if (constraint_decl == NULL ||
        (constraint_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT &&
         constraint_decl->as.spec_decl.form !=
             FENG_SPEC_FORM_INTERSECTION)) {
        return true;
    }
    function_type_decl = resolve_function_type_decl(
        context, expected_type_ref);
    if (function_type_decl == NULL) {
        return true;
    }
    constraint_owner = inferred_expr_type_from_type_ref(constraint_ref);
    inaccessible = resolve_spec_method_value_overload(
        context,
        constraint_decl,
        constraint_owner,
        source_expr->as.member.member,
        expected_type_ref,
        function_type_decl,
        is_static_type_param_source,
        false);
    if (inaccessible.kind != FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE ||
        inaccessible.callable_member == NULL ||
        inaccessible.callable_owner_type_decl == NULL ||
        inaccessible.callable_member->visibility !=
            FENG_VISIBILITY_PRIVATE ||
        spec_member_is_accessible_from(
            context,
            constraint_decl,
            inaccessible.callable_owner_type_decl,
            constraint_owner,
            inaccessible.callable_member)) {
        return true;
    }

    *out_reported = true;
    /* A static T.method member expression is validated independently before
     * its target callable context and has already emitted AE0708. Instance
     * generic receivers need this fallback to emit that diagnostic itself. */
    if (is_static_type_param_source) {
        return true;
    }
    return report_inaccessible_spec_member(
        context,
        source_expr->token,
        inaccessible.callable_owner_type_decl,
        inaccessible.callable_member);
}

static bool validate_function_typed_expr(ResolveContext *context,
                                         const FengExpr *expr,
                                         const FengTypeRef *expected_type_ref) {
    CallableValueResolution resolution;
    char *expr_name;
    char *type_name;

    if (expr == NULL || resolve_function_type_decl(context, expected_type_ref) == NULL) {
        return true;
    }

    resolution = resolve_expr_callable_value(context, expr, expected_type_ref);
    if (resolution.kind == FENG_CALLABLE_VALUE_RESOLUTION_UNIQUE) {
        if (!record_selected_friend_callable_value_access(context,
                                                          expr,
                                                          &resolution)) {
            return false;
        }
        record_callable_spec_coercion_site(context, expr, expected_type_ref);
        return true;
    }

    if (resolution.kind == FENG_CALLABLE_VALUE_RESOLUTION_NONE) {
        bool reported = false;

        if (!report_inaccessible_constrained_generic_method_value(
                context,
                expr,
                expected_type_ref,
                &reported)) {
            return false;
        }
        if (reported) {
            return true;
        }
    }

    expr_name = format_expr_target_name(expr);
    type_name = format_type_ref_name(expected_type_ref);

    if (resolution.kind == FENG_CALLABLE_VALUE_RESOLUTION_AMBIGUOUS) {
        bool ok = resolver_append_error(
            context,
            expr->token,
            "AE0521", format_message("expression '%s' has multiple overloads matching expected function type '%s'",
                           expr_name != NULL ? expr_name : "<expression>",
                           type_name != NULL ? type_name : "<type>"));

        free(expr_name);
        free(type_name);
        return ok;
    }

    {
        bool ok = resolver_append_error(
            context,
            expr->token,
            "AE0522", format_message("expression '%s' does not match expected function type '%s'",
                           expr_name != NULL ? expr_name : "<expression>",
                           type_name != NULL ? type_name : "<type>"));

        free(expr_name);
        free(type_name);
        return ok;
    }
}

/* Validate one already-resolved branch result against a target, preserving a
 * conformance flag separately from the resolver's diagnostic-success return
 * convention. */
static bool validate_branch_result_against_expected_type(
    ResolveContext *context,
    const FengExpr *result,
    const FengTypeRef *expected_type_ref,
    bool *out_conforms) {
    bool conforms;

    if (out_conforms != NULL) {
        *out_conforms = true;
    }
    if (result == NULL) {
        return true;
    }
    conforms = expr_matches_expected_type_ref(context,
                                              result,
                                              expected_type_ref);
    if (out_conforms != NULL) {
        *out_conforms = conforms;
    }
    return validate_expr_against_expected_type(context,
                                               result,
                                               expected_type_ref);
}

/* Commit target-directed validation for every result of a branching
 * expression. The outer expression type is persisted only when all normal
 * branches conform. */
static bool validate_branching_expr_against_expected_type(
    ResolveContext *context,
    const FengExpr *expr,
    const FengTypeRef *expected_type_ref) {
    bool all_conform = true;
    size_t index;

    switch (expr->kind) {
        case FENG_EXPR_IF: {
            const FengBlock *blocks[2] = {
                expr->as.if_expr.then_block,
                expr->as.if_expr.else_block
            };

            for (index = 0U; index < 2U; ++index) {
                bool conforms = true;

                if (block_exits_via_return_or_throw(blocks[index])) {
                    continue;
                }
                if (!validate_branch_result_against_expected_type(
                        context,
                        block_yield_expression(blocks[index]),
                        expected_type_ref,
                        &conforms)) {
                    return false;
                }
                if (!conforms) {
                    all_conform = false;
                    break;
                }
            }
            break;
        }

        case FENG_EXPR_MATCH:
            for (index = 0U; index < expr->as.match_expr.branch_count; ++index) {
                const FengBlock *block = expr->as.match_expr.branches[index].body;
                bool conforms = true;

                if (block_exits_via_return_or_throw(block)) {
                    continue;
                }
                if (!validate_branch_result_against_expected_type(
                        context,
                        block_yield_expression(block),
                        expected_type_ref,
                        &conforms)) {
                    return false;
                }
                if (!conforms) {
                    all_conform = false;
                    break;
                }
            }
            if (all_conform &&
                !block_exits_via_return_or_throw(expr->as.match_expr.else_block)) {
                bool conforms = true;

                if (!validate_branch_result_against_expected_type(
                        context,
                        block_yield_expression(expr->as.match_expr.else_block),
                        expected_type_ref,
                        &conforms)) {
                    return false;
                }
                all_conform = conforms;
            }
            break;

        case FENG_EXPR_TRY:
            if (!validate_branch_result_against_expected_type(
                    context,
                    expr->as.try_expr.body,
                    expected_type_ref,
                    &all_conform)) {
                return false;
            }
            for (index = 0U;
                 all_conform && index < expr->as.try_expr.clause_count;
                 ++index) {
                const FengBlock *block = expr->as.try_expr.clauses[index].body;
                const FengExpr *result;
                bool conforms = true;

                if (block_exits_via_return_or_throw(block)) {
                    continue;
                }
                result = block_yield_expression(block);
                if (!validate_branch_result_against_expected_type(context,
                                                                  result,
                                                                  expected_type_ref,
                                                                  &conforms)) {
                    return false;
                }
                all_conform = conforms;
            }
            break;

        default:
            return true;
    }

    return !all_conform ||
           persist_branch_expression_type(context, expr, expected_type_ref);
}

static bool validate_expr_against_expected_type(ResolveContext *context,
                                                const FengExpr *expr,
                                                const FengTypeRef *expected_type_ref) {
    InferredExprType expr_type;
    char *expr_name;
    char *type_name;

    if (expr == NULL || expected_type_ref == NULL) {
        return true;
    }
    if (expr->kind == FENG_EXPR_IF || expr->kind == FENG_EXPR_MATCH ||
        expr->kind == FENG_EXPR_TRY) {
        if (expr->type != NULL &&
            type_refs_semantically_equal(context,
                                         expr->type,
                                         expected_type_ref)) {
            return true;
        }
        return validate_branching_expr_against_expected_type(context,
                                                             expr,
                                                             expected_type_ref);
    }
    if (expr->kind == FENG_EXPR_TUPLE_LITERAL) {
        return validate_tuple_literal_expr_against_type(context, expr, expected_type_ref);
    }
    if (expr->kind == FENG_EXPR_UNARY && expr->as.unary.op == FENG_TOKEN_AMP &&
        resolve_abi_function_pointer_type_decl(context, expected_type_ref) != NULL) {
        return validate_expr_against_expected_abi_function_pointer_type(context,
                                                                        expr,
                                                                        expected_type_ref);
    }
    if (resolve_function_type_decl(context, expected_type_ref) != NULL) {
        return validate_function_typed_expr(context, expr, expected_type_ref);
    }
    {
        const FengDecl *target_union_decl = resolve_union_spec_type_ref_decl(context,
                                                                             expected_type_ref);

        if (target_union_decl != NULL) {
            UnionMemberSelection selection;

            expr_type = branch_result_inferred_type(context, expr);
            if (!inferred_expr_type_is_known(expr_type)) {
                if (!expr_is_callable_value_reference(context, expr)) {
                    return true;
                }
            } else if (inferred_expr_type_exactly_matches_type_ref(context,
                                                                   expr_type,
                                                                   expected_type_ref)) {
                return true;
            } else {
                selection = select_union_member_for_expr_type(context,
                                                              expr_type,
                                                              target_union_decl,
                                                              expected_type_ref);
                if (selection.matched) {
                    (void)feng_semantic_record_union_coercion_site(context->analysis,
                                                                   expr,
                                                                   target_union_decl,
                                                                   expected_type_ref,
                                                                   selection.member_index,
                                                                   selection.member_type_ref,
                                                                   selection.path_indices,
                                                                   selection.path_length);
                    record_union_leaf_spec_coercion_if_applicable(
                        context, expr, &selection);
                    return true;
                }
                if (selection.ambiguous) {
                    char *expr_name_local = format_expr_target_name(expr);
                    char *type_name_local = format_type_ref_name(expected_type_ref);
                    bool ok = resolver_append_error(
                        context,
                        expr->token,
                        "AE0608", format_message("expression '%s' matches multiple members of union-form spec '%s'; use an explicit cast to select the target member",
                                       expr_name_local != NULL ? expr_name_local : "<expression>",
                                       type_name_local != NULL ? type_name_local : "<type>"));

                    free(expr_name_local);
                    free(type_name_local);
                    return ok;
                }
            }
        }
    }
    if (expr_matches_expected_type_ref(context, expr, expected_type_ref)) {
        record_union_coercion_site_if_applicable(context, expr, expected_type_ref);
        record_object_spec_coercion_site_if_applicable(context,
                                                       expr,
                                                       expected_type_ref,
                                                       FENG_SPEC_OBJECT_SUBJECT_STORAGE_BOX_OWNER);
        return true;
    }

    /* Intersection-form: provide a specific diagnostic identifying which
     * member spec is not satisfied, before falling through to the generic
     * AE1003 error. */
    {
        const FengDecl *target_decl = resolve_type_ref_decl(context, expected_type_ref);

        if (target_decl != NULL && target_decl->kind == FENG_DECL_SPEC &&
            target_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
            const FengIntersectionSpecInfo *info =
                feng_semantic_lookup_intersection_spec_info(context->analysis, target_decl);
            InferredExprType src_type = infer_expr_type(context, expr);
            const FengDecl *src_type_decl = concrete_type_decl_of_inferred(context, src_type);

            if (src_type_decl != NULL && info != NULL) {
                for (size_t mi = 0U; mi < info->flattened_member_count; ++mi) {
                    const FengDecl *member_decl = info->flattened_members[mi];

                    if (type_decl_satisfies_spec_decl(context, src_type_decl, member_decl)) {
                        continue;
                    }
                    {
                        bool ok = resolver_append_error(
                            context, expr->token,
                            "AE0622", format_message(
                                "type '%.*s' does not satisfy spec '%.*s' required by intersection '%.*s'",
                                (int)decl_typeish_name(src_type_decl).length,
                                decl_typeish_name(src_type_decl).data,
                                (int)member_decl->as.spec_decl.name.length,
                                member_decl->as.spec_decl.name.data,
                                (int)target_decl->as.spec_decl.name.length,
                                target_decl->as.spec_decl.name.data));
                        return ok;
                    }
                }
            }
        }
    }

    expr_type = infer_expr_type(context, expr);
    if (!inferred_expr_type_is_known(expr_type)) {
        if (!expr_is_callable_value_reference(context, expr)) {
            return true;
        }

        expr_name = format_expr_target_name(expr);
        type_name = format_type_ref_name(expected_type_ref);
        if (!resolver_append_error(context,
                                   expr->token,
                                   "AE1003", format_message("expression '%s' does not match expected type '%s'",
                                                  expr_name != NULL ? expr_name : "<expression>",
                                                  type_name != NULL ? type_name : "<type>"))) {
            free(expr_name);
            free(type_name);
            return false;
        }

        free(expr_name);
        free(type_name);
        return true;
    }

    expr_name = format_expr_target_name(expr);
    type_name = format_type_ref_name(expected_type_ref);
    if (!resolver_append_error(context,
                               expr->token,
                               "AE1003", format_message("expression '%s' does not match expected type '%s'",
                                              expr_name != NULL ? expr_name : "<expression>",
                                              type_name != NULL ? type_name : "<type>"))) {
        free(expr_name);
        free(type_name);
        return false;
    }

    free(expr_name);
    free(type_name);
    return true;
}

static char *format_inferred_expr_type_name(InferredExprType type, size_t pointer_size) {
    switch (type.kind) {
        case FENG_INFERRED_EXPR_TYPE_BUILTIN: {
            const char *builtin_name = canonical_builtin_type_name(type.builtin_name, pointer_size);

            return duplicate_cstr(builtin_name != NULL ? builtin_name : "<type>");
        }

        case FENG_INFERRED_EXPR_TYPE_TYPE_REF:
            return format_type_ref_name(type.type_ref);

        case FENG_INFERRED_EXPR_TYPE_DECL:
            if (type.type_decl != NULL) {
                FengSlice name = decl_typeish_name(type.type_decl);

                if (name.data != NULL) {
                    return format_module_name(&name, 1U);
                }
            }
            return duplicate_cstr("<type>");

        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
            return duplicate_cstr("<function>");

        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
            return duplicate_cstr("<type>");
    }

    return duplicate_cstr("<type>");
}

static bool abi_trace_contains(const AbiTrace *trace, const FengDecl *decl) {
    while (trace != NULL) {
        if (trace->decl == decl) {
            return true;
        }
        trace = trace->parent;
    }

    return false;
}

static bool type_decl_is_abi_stable(const ResolveContext *context,
                                          const FengDecl *decl,
                                          const AbiTrace *trace);

static bool type_ref_is_abi_field_pointer_target(const ResolveContext *context,
                                                 const FengTypeRef *type_ref,
                                                 const AbiTrace *trace) {
    const char *builtin_name;
    const FengDecl *type_decl;

    if (type_ref == NULL) {
        return false;
    }

    if (type_ref->kind == FENG_TYPE_REF_ARRAY) {
        return type_ref_is_abi_compatible_array(context, type_ref, trace);
    }
    if (type_ref->kind == FENG_TYPE_REF_POINTER) {
        return false;
    }

    builtin_name = type_ref_builtin_canonical_name(type_ref, context->pointer_size);
    if (builtin_name != NULL) {
        return true;
    }

    type_decl = resolve_type_ref_decl(context, type_ref);
    if (type_decl == NULL) {
        return false;
    }

    if (decl_is_enum_type(type_decl)) {
        return true;
    }

    if (type_decl->kind == FENG_DECL_TYPE) {
        return annotations_contain_kind(type_decl->annotations,
                                        type_decl->annotation_count,
                                        FENG_ANNOTATION_ABI);
    }

    return decl_is_function_type(type_decl) &&
           annotations_contain_kind(type_decl->annotations,
                                    type_decl->annotation_count,
                                    FENG_ANNOTATION_ABI);
}

static bool type_ref_is_abi_field_type(const ResolveContext *context,
                                       const FengTypeRef *type_ref,
                                       const AbiTrace *trace) {
    const char *builtin_name;
    const FengDecl *type_decl;

    if (type_ref == NULL) {
        return false;
    }

    builtin_name = type_ref_builtin_canonical_name(type_ref, context->pointer_size);
    if (builtin_name != NULL) {
        return strcmp(builtin_name, "void") != 0 && strcmp(builtin_name, "string") != 0;
    }

    type_decl = resolve_type_ref_decl(context, type_ref);
    if (decl_is_enum_type(type_decl)) {
        return true;
    }

    /* @value type: no managed header, inline layout is plain C data.
     * Allow as @abi field when the @value type is also @abi (its fields
     * are already validated as ABI-compatible). */
    if (type_ref->kind == FENG_TYPE_REF_NAMED &&
        type_decl != NULL && type_decl->kind == FENG_DECL_TYPE &&
        type_decl->as.type_decl.is_value) {
        return annotations_contain_kind(type_decl->annotations,
                                        type_decl->annotation_count,
                                        FENG_ANNOTATION_ABI);
    }

    return type_ref->kind == FENG_TYPE_REF_POINTER &&
           type_ref_is_abi_field_pointer_target(context, type_ref->as.inner, trace);
}

static bool type_ref_is_abi_compatible_array(const ResolveContext *context,
                                             const FengTypeRef *type_ref,
                                             const AbiTrace *trace) {
    const char *builtin_name;
    const FengDecl *element_decl;

    if (type_ref == NULL || type_ref->kind != FENG_TYPE_REF_ARRAY || type_ref->as.inner == NULL ||
        type_ref->as.inner->kind == FENG_TYPE_REF_ARRAY) {
        return false;
    }

    builtin_name = type_ref_builtin_canonical_name(type_ref->as.inner, context->pointer_size);
    if (builtin_name != NULL) {
        return strcmp(builtin_name, "void") != 0 && strcmp(builtin_name, "string") != 0;
    }

    if (type_ref->as.inner->kind == FENG_TYPE_REF_POINTER) {
        return true;
    }

    element_decl = resolve_type_ref_decl(context, type_ref->as.inner);
    if (decl_is_enum_type(element_decl)) {
        return true;
    }
    return element_decl != NULL && element_decl->kind == FENG_DECL_TYPE &&
           type_decl_is_abi_stable(context, element_decl, trace);
}

static bool type_ref_is_abi_stable(const ResolveContext *context,
                                         const FengTypeRef *type_ref,
                                         bool allow_void,
                                         const AbiTrace *trace) {
    const FengDecl *type_decl;
    const char *builtin_name;

    if (type_ref == NULL) {
        return allow_void;
    }

    switch (type_ref->kind) {
        case FENG_TYPE_REF_NAMED:
            if (type_ref->as.named.segment_count == 1U) {
                builtin_name = canonical_builtin_type_name(type_ref->as.named.segments[0], context->pointer_size);
                if (builtin_name != NULL) {
                    if (strcmp(builtin_name, "void") == 0) {
                        return allow_void;
                    }
                    return strcmp(builtin_name, "string") != 0;
                }
            }

            type_decl = resolve_type_ref_decl(context, type_ref);
            return type_decl_is_abi_stable(context, type_decl, trace);

        case FENG_TYPE_REF_POINTER:
            return true;

        case FENG_TYPE_REF_ARRAY:
            return type_ref_is_abi_compatible_array(context, type_ref, trace);
    }

    return false;
}

static bool inferred_expr_type_is_abi_stable(const ResolveContext *context,
                                                   InferredExprType type,
                                                   bool allow_void,
                                                   const AbiTrace *trace) {
    const char *builtin_name;

    switch (type.kind) {
        case FENG_INFERRED_EXPR_TYPE_BUILTIN:
            builtin_name = canonical_builtin_type_name(type.builtin_name, context->pointer_size);
            if (builtin_name == NULL) {
                return false;
            }
            if (strcmp(builtin_name, "void") == 0) {
                return allow_void;
            }
            return strcmp(builtin_name, "string") != 0;

        case FENG_INFERRED_EXPR_TYPE_TYPE_REF:
            return type_ref_is_abi_stable(context, type.type_ref, allow_void, trace);

        case FENG_INFERRED_EXPR_TYPE_DECL:
            return type_decl_is_abi_stable(context, type.type_decl, trace);

        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
            return false;
    }

    return false;
}

static bool type_ref_uses_c_boundary_compatible_named_types(const ResolveContext *context,
                                                            const FengTypeRef *type_ref,
                                                            bool allow_void,
                                                            bool pointer_pointee);

static bool type_decl_is_abi_stable(const ResolveContext *context,
                                          const FengDecl *decl,
                                          const AbiTrace *trace) {
    AbiTrace next_trace;
    size_t member_index;
    size_t param_index;

    if (decl_is_enum_type(decl)) {
        return true;
    }

    if (decl == NULL || (decl->kind != FENG_DECL_TYPE && decl->kind != FENG_DECL_SPEC) ||
        !annotations_contain_kind(decl->annotations, decl->annotation_count, FENG_ANNOTATION_ABI) ||
        abi_trace_contains(trace, decl)) {
        return false;
    }

    /* Object-form `spec` only constrains visible shape, not memory layout or
     * ABI value layout, so it can never be an ABI-stable type even if the
     * annotation is present. The actual diagnostic is emitted by
     * `validate_abi_type_declaration`; here we simply refuse to treat it as
     * stable so dependent types do not transitively appear ABI-stable. */
    if (decl->kind == FENG_DECL_SPEC &&
        (decl->as.spec_decl.form == FENG_SPEC_FORM_OBJECT ||
         decl->as.spec_decl.form == FENG_SPEC_FORM_UNION)) {
        return false;
    }

    next_trace.decl = decl;
    next_trace.parent = trace;

    if (count_calling_convention_annotations(decl->annotations, decl->annotation_count) != 0U) {
        return false;
    }

    if (decl_is_function_type(decl)) {
        for (param_index = 0U; param_index < decl->as.spec_decl.as.callable.param_count; ++param_index) {
            if (!type_ref_is_abi_stable(context,
                                              decl->as.spec_decl.as.callable.params[param_index].type,
                                              false,
                                              &next_trace) ||
                !type_ref_uses_c_boundary_compatible_named_types(
                    context,
                    decl->as.spec_decl.as.callable.params[param_index].type,
                    false,
                    false)) {
                return false;
            }
        }

        return type_ref_is_abi_stable(
                   context, decl->as.spec_decl.as.callable.return_type, true, &next_trace) &&
               type_ref_uses_c_boundary_compatible_named_types(
                   context,
                   decl->as.spec_decl.as.callable.return_type,
                   true,
                   false);
    }

    for (member_index = 0U; member_index < decl->as.type_decl.member_count; ++member_index) {
        const FengTypeMember *member = decl->as.type_decl.members[member_index];

        if (member->kind != FENG_TYPE_MEMBER_FIELD || member->is_static) {
            continue;
        }
        if (!type_ref_is_abi_field_type(context, member->as.field.type, &next_trace)) {
            return false;
        }
    }

    return true;
}

/* Return whether a declaration directly owns one member pointer. */
static bool semantic_decl_contains_member(const FengDecl *decl,
                                          const FengTypeMember *member) {
    FengTypeMember *const *members = NULL;
    size_t member_count = 0U;

    if (decl == NULL || member == NULL) {
        return false;
    }
    switch (decl->kind) {
        case FENG_DECL_TYPE:
            members = decl->as.type_decl.members;
            member_count = decl->as.type_decl.member_count;
            break;
        case FENG_DECL_SPEC:
            if (decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
                return false;
            }
            members = decl->as.spec_decl.as.object.members;
            member_count = decl->as.spec_decl.as.object.member_count;
            break;
        case FENG_DECL_FIT:
            members = decl->as.fit_decl.members;
            member_count = decl->as.fit_decl.member_count;
            break;
        default:
            return false;
    }
    for (size_t index = 0U; index < member_count; ++index) {
        if (members[index] == member) {
            return true;
        }
    }
    return false;
}

/* Find the source program that owns one semantic member declaration. */
static const FengProgram *semantic_member_program(
    const FengSemanticAnalysis *analysis,
    const FengTypeMember *member) {
    if (analysis == NULL || member == NULL) {
        return NULL;
    }
    for (size_t module_index = 0U;
         module_index < analysis->module_count;
         ++module_index) {
        const FengSemanticModule *module = &analysis->modules[module_index];

        for (size_t program_index = 0U;
             program_index < module->program_count;
             ++program_index) {
            const FengProgram *program = module->programs[program_index];

            for (size_t decl_index = 0U;
                 decl_index < program->declaration_count;
                 ++decl_index) {
                if (semantic_decl_contains_member(
                        program->declarations[decl_index], member)) {
                    return program;
                }
            }
        }
    }
    return NULL;
}

/* Follow a generated mixin member chain to its original declaration. */
static const FengTypeMember *semantic_mixin_source_member(
    const FengTypeMember *member) {
    while (member != NULL && member->mixin_source_member != NULL &&
           member->mixin_source_member != member) {
        member = member->mixin_source_member;
    }
    return member;
}

/* Attach the original declaration of one generated member to the latest
 * semantic error. Ordinary hand-written members require no relation. */
static bool append_mixin_member_related_location(
    ResolveContext *context,
    const FengTypeMember *member) {
    const FengTypeMember *source_member;
    const FengProgram *source_program;

    if (member == NULL || member->mixin_source_member == NULL ||
        context == NULL || context->errors == NULL ||
        context->error_count == NULL) {
        return true;
    }
    source_member = semantic_mixin_source_member(member);
    source_program = semantic_member_program(context->analysis, source_member);
    return append_latest_error_related_location(
        *context->errors,
        *context->error_count,
        source_program != NULL ? source_program->path : context->program->path,
        source_member->token,
        format_message("mixin source member is declared here"));
}

/* Attach both distinct generated sources involved in one member conflict. */
static bool append_mixin_conflict_related_locations(
    ResolveContext *context,
    const FengTypeMember *left,
    const FengTypeMember *right) {
    const FengTypeMember *left_source = semantic_mixin_source_member(left);
    const FengTypeMember *right_source = semantic_mixin_source_member(right);

    if (!append_mixin_member_related_location(context, left)) {
        return false;
    }
    if (right != NULL && right->mixin_source_member != NULL &&
        right_source != left_source) {
        return append_mixin_member_related_location(context, right);
    }
    return true;
}

/* Prefer a generated member token as the primary location of a conflict. */
static FengToken mixin_conflict_primary_token(const FengTypeMember *left,
                                              const FengTypeMember *right,
                                              FengToken fallback) {
    if (left != NULL && left->mixin_source_member != NULL) {
        return left->token;
    }
    if (right != NULL && right->mixin_source_member != NULL) {
        return right->token;
    }
    return fallback;
}

/* One declaration-local member collection shared by ordinary types and
 * object-form specs. The validators below project fields or methods from the
 * same view so declaration-local conflict rules cannot drift by owner kind. */
typedef struct DeclaredMemberSet {
    FengTypeMember *const *members;
    size_t member_count;
    FengSlice owner_name;
    const char *owner_label;
} DeclaredMemberSet;

/* Project a type or object-form spec declaration to its local member set. */
static bool declared_member_set_init(const FengDecl *decl,
                                     DeclaredMemberSet *out_set) {
    if (decl == NULL || out_set == NULL) {
        return false;
    }
    memset(out_set, 0, sizeof(*out_set));
    if (decl->kind == FENG_DECL_TYPE) {
        out_set->members = decl->as.type_decl.members;
        out_set->member_count = decl->as.type_decl.member_count;
        out_set->owner_name = decl->as.type_decl.name;
        out_set->owner_label = "type";
        return true;
    }
    if (decl->kind == FENG_DECL_SPEC &&
        decl->as.spec_decl.form == FENG_SPEC_FORM_OBJECT) {
        out_set->members = decl->as.spec_decl.as.object.members;
        out_set->member_count = decl->as.spec_decl.as.object.member_count;
        out_set->owner_name = decl->as.spec_decl.name;
        out_set->owner_label = "object-form spec";
        return true;
    }
    return false;
}

/* Validate duplicate, return-only and variadic conflicts in one declaration.
 * Static and instance methods remain independent overload sets. */
static bool validate_declared_method_overloads(ResolveContext *context,
                                               const FengDecl *decl) {
    DeclaredMemberSet set;
    size_t i;
    size_t j;
    bool ok = true;

    if (context == NULL || !declared_member_set_init(decl, &set)) {
        return true;
    }

    for (i = 0U; i < set.member_count; ++i) {
        const FengTypeMember *mi = set.members[i];
        const FengCallableSignature *si;

        if (mi == NULL || mi->kind != FENG_TYPE_MEMBER_METHOD) {
            continue;
        }
        si = &mi->as.callable;

        for (j = 0U; j < i; ++j) {
            const FengTypeMember *mj = set.members[j];
            const FengCallableSignature *sj;

            if (mj == NULL || mj->kind != FENG_TYPE_MEMBER_METHOD ||
                mi->is_static != mj->is_static) {
                continue;
            }
            sj = &mj->as.callable;
            if (!slice_equals(si->name, sj->name)) {
                continue;
            }
            if (si->type_param_count != sj->type_param_count) {
                continue;
            }
            if (parameters_equal(si, sj)) {
                bool error_ok;

                if (return_type_equals(si->return_type, sj->return_type)) {
                    error_ok = resolver_append_error(
                        context,
                        mixin_conflict_primary_token(mi, mj, si->token),
                        "AE0508", format_message(
                            "duplicate method signature '%.*s' in %s '%.*s'",
                            (int)si->name.length, si->name.data,
                            set.owner_label,
                            (int)set.owner_name.length,
                            set.owner_name.data));
                } else {
                    error_ok = resolver_append_error(
                        context,
                        mixin_conflict_primary_token(mi, mj, si->token),
                        "AE0509", format_message(
                            "method overloads in %s '%.*s' cannot differ only by return type: '%.*s'",
                            set.owner_label,
                            (int)set.owner_name.length,
                            set.owner_name.data,
                            (int)si->name.length, si->name.data));
                }
                if (error_ok) {
                    error_ok = append_mixin_conflict_related_locations(
                        context, mi, mj);
                }
                ok = error_ok && ok;
            } else if ((sig_is_variadic(si) || sig_is_variadic(sj)) &&
                       variadic_parameters_conflict(si, sj)) {
                bool error_ok = resolver_append_error(
                    context,
                    mixin_conflict_primary_token(mi, mj, si->token),
                    "AE0510", format_message(
                        "variadic method overload conflicts with existing method '%.*s' in %s '%.*s'",
                        (int)si->name.length, si->name.data,
                        set.owner_label,
                        (int)set.owner_name.length,
                        set.owner_name.data));

                if (error_ok) {
                    error_ok = append_mixin_conflict_related_locations(
                        context, mi, mj);
                }
                ok = error_ok && ok;
            }
        }
    }

    return ok;
}

/* Reject same-name fields within one declaration's instance or static member
 * surface. The two surfaces have different owners and remain independent. */
static bool validate_declared_field_name_conflicts(ResolveContext *context,
                                                   const FengDecl *decl) {
    DeclaredMemberSet set;
    bool ok = true;

    if (context == NULL || !declared_member_set_init(decl, &set)) {
        return true;
    }
    for (size_t index = 0U; index < set.member_count; ++index) {
        const FengTypeMember *field = set.members[index];

        if (field == NULL || field->kind != FENG_TYPE_MEMBER_FIELD) {
            continue;
        }
        for (size_t previous_index = 0U;
             previous_index < index;
             ++previous_index) {
            const FengTypeMember *previous = set.members[previous_index];
            bool error_ok;

            if (previous == NULL ||
                previous->kind != FENG_TYPE_MEMBER_FIELD ||
                previous->is_static != field->is_static ||
                !slice_equals(previous->as.field.name,
                              field->as.field.name)) {
                continue;
            }
            error_ok = resolver_append_error(
                context,
                mixin_conflict_primary_token(
                    field, previous, field->token),
                "AE0514",
                format_message(
                    "duplicate field '%.*s' in %s '%.*s' within the %s member surface",
                    (int)field->as.field.name.length,
                    field->as.field.name.data,
                    set.owner_label,
                    (int)set.owner_name.length,
                    set.owner_name.data,
                    field->is_static ? "static" : "instance"));
            if (error_ok) {
                error_ok = append_mixin_conflict_related_locations(
                    context, field, previous);
            }
            ok = error_ok && ok;
        }
    }
    return ok;
}

/* Reject a field and a method with the same name in one declaration's
 * instance or static surface. Declaration order does not affect the check. */
static bool validate_declared_field_method_name_conflicts(
    ResolveContext *context,
    const FengDecl *decl) {
    DeclaredMemberSet set;
    bool ok = true;

    if (context == NULL || !declared_member_set_init(decl, &set)) {
        return true;
    }

    for (size_t index = 0U; index < set.member_count; ++index) {
        const FengTypeMember *current = set.members[index];

        if (current == NULL) {
            continue;
        }
        for (size_t previous_index = 0U;
             previous_index < index;
             ++previous_index) {
            const FengTypeMember *previous = set.members[previous_index];
            const FengTypeMember *field;
            const FengTypeMember *method;
            bool error_ok;

            if (previous == NULL || current->is_static != previous->is_static) {
                continue;
            }
            if (current->kind == FENG_TYPE_MEMBER_FIELD &&
                previous->kind == FENG_TYPE_MEMBER_METHOD) {
                field = current;
                method = previous;
            } else if (current->kind == FENG_TYPE_MEMBER_METHOD &&
                       previous->kind == FENG_TYPE_MEMBER_FIELD) {
                field = previous;
                method = current;
            } else {
                continue;
            }
            if (!slice_equals(field->as.field.name,
                              method->as.callable.name)) {
                continue;
            }
            error_ok = resolver_append_error(
                context,
                mixin_conflict_primary_token(
                    current, previous, current->token),
                "AE0513",
                format_message(
                    "field '%.*s' and method '%.*s' in %s '%.*s' cannot share the same name within the %s member surface",
                    (int)field->as.field.name.length,
                    field->as.field.name.data,
                    (int)method->as.callable.name.length,
                    method->as.callable.name.data,
                    set.owner_label,
                    (int)set.owner_name.length,
                    set.owner_name.data,
                    current->is_static ? "static" : "instance"));
            if (error_ok) {
                error_ok = append_mixin_conflict_related_locations(
                    context, current, previous);
            }
            ok = error_ok && ok;
        }
    }

    return ok;
}

static bool validate_fit_member_overloads(ResolveContext *context, const FengDecl *fit_decl) {
    size_t i;
    size_t j;
    bool ok = true;
    char *target_name;

    if (context == NULL || fit_decl == NULL || fit_decl->kind != FENG_DECL_FIT) {
        return true;
    }

    target_name = format_type_ref_name(fit_decl->as.fit_decl.target);

    for (i = 0U; i < fit_decl->as.fit_decl.member_count; ++i) {
        const FengTypeMember *mi = fit_decl->as.fit_decl.members[i];
        const FengCallableSignature *si;

        if (mi == NULL || mi->kind != FENG_TYPE_MEMBER_METHOD) {
            continue;
        }
        si = &mi->as.callable;

        for (j = 0U; j < i; ++j) {
            const FengTypeMember *mj = fit_decl->as.fit_decl.members[j];
            const FengCallableSignature *sj;

            if (mj == NULL || mj->kind != FENG_TYPE_MEMBER_METHOD ||
                mi->is_static != mj->is_static) {
                continue;
            }
            sj = &mj->as.callable;
            if (!slice_equals(si->name, sj->name)) {
                continue;
            }
            if (si->type_param_count != sj->type_param_count) {
                continue;
            }
            if (parameters_equal(si, sj)) {
                bool error_ok;

                if (return_type_equals(si->return_type, sj->return_type)) {
                    error_ok = resolver_append_error(
                        context,
                        mixin_conflict_primary_token(mi, mj, si->token),
                        "AE0801", format_message(
                            "duplicate method signature '%.*s' in fit target '%s'",
                            (int)si->name.length, si->name.data,
                            target_name != NULL ? target_name : "<unknown>"));
                } else {
                    error_ok = resolver_append_error(
                        context,
                        mixin_conflict_primary_token(mi, mj, si->token),
                        "AE0802", format_message(
                            "method overloads in fit target '%s' cannot differ only by return type: '%.*s'",
                            target_name != NULL ? target_name : "<unknown>",
                            (int)si->name.length, si->name.data));
                }
                if (error_ok) {
                    error_ok = append_mixin_conflict_related_locations(
                        context, mi, mj);
                }
                ok = error_ok && ok;
            } else if ((sig_is_variadic(si) || sig_is_variadic(sj)) &&
                       variadic_parameters_conflict(si, sj)) {
                bool error_ok = resolver_append_error(
                    context,
                    mixin_conflict_primary_token(mi, mj, si->token),
                    "AE0803", format_message(
                        "variadic method overload conflicts with existing method '%.*s' in fit target '%s'",
                        (int)si->name.length, si->name.data,
                        target_name != NULL ? target_name : "<unknown>"));

                if (error_ok) {
                    error_ok = append_mixin_conflict_related_locations(
                        context, mi, mj);
                }
                ok = error_ok && ok;
            }
        }
    }

    free(target_name);
    return ok;
}

static bool validate_abi_type_declaration(ResolveContext *context, const FengDecl *decl) {
    AbiTrace trace;
    size_t callconv_count;
    size_t field_index;
    size_t param_index;
    bool has_abi;

    if (context == NULL || decl == NULL || (decl->kind != FENG_DECL_TYPE && decl->kind != FENG_DECL_SPEC)) {
        return true;
    }

    has_abi = annotations_contain_kind(decl->annotations, decl->annotation_count, FENG_ANNOTATION_ABI);
    callconv_count = count_calling_convention_annotations(decl->annotations, decl->annotation_count);

    /* Object-form `spec` only describes a visible shape contract; it does not
     * fix memory layout or ABI value layout, so it cannot enter the C ABI
     * boundary. Reject @abi and calling-convention annotations on object-form
     * spec declarations with an explicit, actionable diagnostic. */
    if (decl->kind == FENG_DECL_SPEC && decl->as.spec_decl.form == FENG_SPEC_FORM_OBJECT) {
        if (has_abi) {
            return resolver_append_error(
                context,
                decl->token,
                "AE1304", format_message(
                    "object-form spec '%.*s' cannot be marked as @abi; @abi only applies to type declarations and callable-form spec",
                    (int)decl_typeish_name(decl).length,
                    decl_typeish_name(decl).data));
        }
        if (callconv_count != 0U) {
            return resolver_append_error(
                context,
                decl->token,
                "AE1305", format_message(
                    "spec '%.*s' cannot use calling convention annotations",
                    (int)decl_typeish_name(decl).length,
                    decl_typeish_name(decl).data));
        }
        return true;
    }

    if (decl->kind == FENG_DECL_SPEC && decl->as.spec_decl.form == FENG_SPEC_FORM_UNION) {
        if (has_abi) {
            return resolver_append_error(
                context,
                decl->token,
                "AE1304", format_message(
                    "union-form spec '%.*s' cannot be marked as @abi; union values use compiler-managed aggregate layout",
                    (int)decl_typeish_name(decl).length,
                    decl_typeish_name(decl).data));
        }
        if (callconv_count != 0U) {
            return resolver_append_error(
                context,
                decl->token,
                "AE1305", format_message(
                    "spec '%.*s' cannot use calling convention annotations",
                    (int)decl_typeish_name(decl).length,
                    decl_typeish_name(decl).data));
        }
        return true;
    }

    if (!has_abi) {
        if (callconv_count != 0U) {
            return resolver_append_error(
                context,
                decl->token,
                "AE1305", format_message("type '%.*s' cannot use calling convention annotations",
                               (int)decl_typeish_name(decl).length,
                    decl_typeish_name(decl).data));
        }
        return true;
    }

    if (callconv_count != 0U) {
        return resolver_append_error(
            context,
            decl->token,
            "AE1304", format_message(
                "type '%.*s' cannot be marked as @abi because calling convention annotations do not apply to type declarations",
                (int)decl_typeish_name(decl).length,
                    decl_typeish_name(decl).data));
    }

    trace.decl = decl;
    trace.parent = NULL;

    if (decl_is_function_type(decl)) {
        for (param_index = 0U; param_index < decl->as.spec_decl.as.callable.param_count; ++param_index) {
            const FengParameter *param = &decl->as.spec_decl.as.callable.params[param_index];
            char *type_name;
            bool ok;

            if (type_ref_is_abi_stable(context, param->type, false, &trace) &&
                type_ref_uses_c_boundary_compatible_named_types(context, param->type, false, false)) {
                continue;
            }

            type_name = format_type_ref_name(param->type);
            ok = resolver_append_error(
                context,
                param->token,
                "AE1310", format_message(
                    "type '%.*s' cannot be marked as @abi because parameter '%.*s' uses non-ABI-stable type '%s'",
                    (int)decl_typeish_name(decl).length,
                    decl_typeish_name(decl).data,
                    (int)param->name.length,
                    param->name.data,
                    type_name != NULL ? type_name : "<type>"));
            free(type_name);
            return ok;
        }

        if (!type_ref_is_abi_stable(
                context, decl->as.spec_decl.as.callable.return_type, true, &trace) ||
            !type_ref_uses_c_boundary_compatible_named_types(
                context, decl->as.spec_decl.as.callable.return_type, true, false)) {
            char *type_name = format_type_ref_name(decl->as.spec_decl.as.callable.return_type);
            bool ok = resolver_append_error(
                context,
                decl->token,
                "AE1311", format_message(
                    "type '%.*s' cannot be marked as @abi because return type '%s' is not ABI-stable",
                    (int)decl_typeish_name(decl).length,
                    decl_typeish_name(decl).data,
                    type_name != NULL ? type_name : "<type>"));
            free(type_name);
            return ok;
        }

        return true;
    }

    for (field_index = 0U; field_index < decl->as.type_decl.member_count; ++field_index) {
        const FengTypeMember *member = decl->as.type_decl.members[field_index];
        char *type_name;
        bool ok;

        if (member->kind != FENG_TYPE_MEMBER_FIELD ||
            member->is_static ||
            type_ref_is_abi_field_type(context, member->as.field.type, &trace)) {
            continue;
        }

        type_name = format_type_ref_name(member->as.field.type);
        ok = resolver_append_error(
            context,
            member->token,
            "AE1312", format_message(
                "type '%.*s' cannot be marked as @abi because field '%.*s' uses non-ABI-stable type '%s'",
                (int)decl_typeish_name(decl).length,
                    decl_typeish_name(decl).data,
                (int)member->as.field.name.length,
                member->as.field.name.data,
                type_name != NULL ? type_name : "<type>"));
        free(type_name);
        return ok;
    }

    return true;
}

static bool inferred_expr_type_uses_c_boundary_compatible_named_types(
    const ResolveContext *context,
    InferredExprType type,
    bool allow_void,
    bool pointer_pointee);

static bool validate_abi_callable_signature(ResolveContext *context,
                                             FengToken token,
                                             FengSlice name,
                                             const FengAnnotation *annotations,
                                             size_t annotation_count,
                                             const FengCallableSignature *callable,
                                             const char *callable_kind,
                                             bool is_extern) {
    const FengAnnotation *calling_convention;
    size_t callconv_count;
    bool has_abi;
    size_t param_index;

    if (context == NULL || callable == NULL) {
        return true;
    }

    has_abi = annotations_contain_kind(annotations, annotation_count, FENG_ANNOTATION_ABI);
    callconv_count = count_calling_convention_annotations(annotations, annotation_count);
    calling_convention = find_calling_convention_annotation(annotations, annotation_count);

    if (!has_abi) {
        if (callconv_count != 0U && !is_extern) {
            return resolver_append_error(
                context,
                calling_convention != NULL ? calling_convention->token : token,
                "AE1316", format_message(
                    "%s '%.*s' cannot use calling convention annotations unless it is marked as @abi or declared extern",
                    callable_kind,
                    (int)name.length,
                    name.data));
        }
        return true;
    }

    if (is_extern) {
        return resolver_append_error(
            context,
            token,
            "AE1303", format_message(
                "%s '%.*s' cannot be marked as @abi because extern functions declare imported C symbols",
                callable_kind,
                (int)name.length,
                name.data));
    }

    if (callconv_count > 1U) {
        return resolver_append_error(
            context,
            token,
            "AE1306", format_message(
                "%s '%.*s' cannot be marked as @abi because it uses more than one calling convention annotation",
                callable_kind,
                (int)name.length,
                name.data));
    }

    if (calling_convention != NULL && calling_convention->arg_count != 0U) {
        return resolver_append_error(
            context,
            calling_convention->token,
            "AE1306", format_message(
                "%s '%.*s' cannot be marked as @abi because calling convention annotations on @abi declarations must not take library arguments",
                callable_kind,
                (int)name.length,
                name.data));
    }

    for (param_index = 0U; param_index < callable->param_count; ++param_index) {
        const FengParameter *param = &callable->params[param_index];
        char *type_name;
        bool ok;

        if (type_ref_is_abi_stable(context, param->type, false, NULL) &&
            type_ref_uses_c_boundary_compatible_named_types(context, param->type, false, false)) {
            continue;
        }

        type_name = format_type_ref_name(param->type);
        ok = resolver_append_error(
            context,
            param->token,
            "AE1310", format_message(
                "%s '%.*s' cannot be marked as @abi because parameter '%.*s' uses non-ABI-stable type '%s'",
                callable_kind,
                (int)name.length,
                name.data,
                (int)param->name.length,
                param->name.data,
                type_name != NULL ? type_name : "<type>"));
        free(type_name);
        return ok;
    }

    if (callable_return_inference_is_pending(context, callable)) {
        return true;
    }

    if (!inferred_expr_type_is_abi_stable(
            context, callable_effective_return_type(context, callable), true, NULL) ||
        !inferred_expr_type_uses_c_boundary_compatible_named_types(
            context, callable_effective_return_type(context, callable), true, false)) {
        char *type_name = format_inferred_expr_type_name(callable_effective_return_type(context, callable), context->pointer_size);
        bool ok = resolver_append_error(
            context,
            callable->return_type != NULL ? callable->return_type->token : token,
            "AE1311", format_message(
                "%s '%.*s' cannot be marked as @abi because return type '%s' is not ABI-stable",
                callable_kind,
                (int)name.length,
                name.data,
                type_name != NULL ? type_name : "<type>"));
        free(type_name);
        return ok;
    }

    if (callable_may_escape_exception(context, callable)) {
        return resolver_append_error(
            context,
            token,
            "AE1313", format_message(
                "%s '%.*s' cannot be marked as @abi because uncaught exceptions must not cross the @abi ABI boundary",
                callable_kind,
                (int)name.length,
                name.data));
    }

    return true;
}

static bool type_ref_uses_c_boundary_compatible_named_types(const ResolveContext *context,
                                                            const FengTypeRef *type_ref,
                                                            bool allow_void,
                                                            bool pointer_pointee) {
    const FengDecl *type_decl;
    const char *builtin_name;

    if (type_ref == NULL) {
        return allow_void;
    }

    switch (type_ref->kind) {
        case FENG_TYPE_REF_NAMED:
            builtin_name = type_ref_builtin_canonical_name(type_ref, context->pointer_size);
            if (builtin_name != NULL) {
                return strcmp(builtin_name, "void") != 0 || allow_void;
            }

            type_decl = resolve_type_ref_decl(context, type_ref);
            if (type_decl == NULL) {
                return false;
            }
            if (decl_is_enum_type(type_decl)) {
                return true;
            }
            if (type_decl->kind == FENG_DECL_TYPE) {
                return annotations_contain_kind(type_decl->annotations,
                                                type_decl->annotation_count,
                                                FENG_ANNOTATION_ABI) &&
                       (pointer_pointee || type_decl_has_field_members(type_decl));
            }

            return type_decl_is_abi_stable(context, type_decl, NULL);

        case FENG_TYPE_REF_POINTER:
            return type_ref->as.inner != NULL &&
                   type_ref_uses_c_boundary_compatible_named_types(context,
                                                                   type_ref->as.inner,
                                                                   true,
                                                                   true);

        case FENG_TYPE_REF_ARRAY:
            return type_ref->as.inner != NULL &&
                   type_ref_uses_c_boundary_compatible_named_types(context,
                                                                   type_ref->as.inner,
                                                                   false,
                                                                   false);
    }

    return false;
}

static bool type_ref_is_extern_c_abi_compatible(const ResolveContext *context,
                                                const FengTypeRef *type_ref,
                                                bool allow_void) {
    return type_ref_is_abi_stable(context, type_ref, allow_void, NULL) &&
           type_ref_uses_c_boundary_compatible_named_types(context,
                                                           type_ref,
                                                           allow_void,
                                                           false);
}

static bool inferred_expr_type_uses_c_boundary_compatible_named_types(
    const ResolveContext *context,
    InferredExprType type,
    bool allow_void,
    bool pointer_pointee) {
    const char *builtin_name;

    switch (type.kind) {
        case FENG_INFERRED_EXPR_TYPE_BUILTIN:
            builtin_name = canonical_builtin_type_name(type.builtin_name, context->pointer_size);
            return builtin_name != NULL && (strcmp(builtin_name, "void") != 0 || allow_void);

        case FENG_INFERRED_EXPR_TYPE_TYPE_REF:
            return type_ref_uses_c_boundary_compatible_named_types(context,
                                                                   type.type_ref,
                                                                   allow_void,
                                                                   pointer_pointee);

        case FENG_INFERRED_EXPR_TYPE_DECL:
            if (type.type_decl == NULL) {
                return false;
            }
            if (decl_is_enum_type(type.type_decl)) {
                return true;
            }
            if (type.type_decl->kind == FENG_DECL_TYPE) {
                return annotations_contain_kind(type.type_decl->annotations,
                                                type.type_decl->annotation_count,
                                                FENG_ANNOTATION_ABI) &&
                       (pointer_pointee || type_decl_has_field_members(type.type_decl));
            }

            return type_decl_is_abi_stable(context, type.type_decl, NULL);

        case FENG_INFERRED_EXPR_TYPE_LAMBDA:
        case FENG_INFERRED_EXPR_TYPE_UNKNOWN:
            return false;
    }

    return false;
}

static bool validate_extern_function_signature(ResolveContext *context, const FengDecl *decl) {
    const FengCallableSignature *callable;
    size_t param_index;

    if (context == NULL || !extern_function_uses_c_abi_path(decl)) {
        return true;
    }

    callable = &decl->as.function_decl;
    for (param_index = 0U; param_index < callable->param_count; ++param_index) {
        const FengParameter *param = &callable->params[param_index];
        char *type_name;

        if (type_ref_is_extern_c_abi_compatible(context, param->type, false)) {
            continue;
        }

        type_name = format_type_ref_name(param->type);
        if (!resolver_append_error(
                context,
                param->token,
                "AE1318", format_message(
                    "extern function '%.*s' parameter '%.*s' type '%s' is not C ABI-stable",
                    (int)callable->name.length,
                    callable->name.data,
                    (int)param->name.length,
                    param->name.data,
                    type_name != NULL ? type_name : "<type>"))) {
            free(type_name);
            return false;
        }

        free(type_name);
        return true;
    }

    if (!type_ref_is_extern_c_abi_compatible(context, callable->return_type, true)) {
        char *type_name = format_type_ref_name(callable->return_type);
        bool ok = resolver_append_error(
            context,
            callable->token,
            "AE1319", format_message("extern function '%.*s' return type '%s' is not C ABI-stable",
                           (int)callable->name.length,
                           callable->name.data,
                           type_name != NULL ? type_name : "<type>"));

        free(type_name);
        return ok;
    }

    return true;
}

static bool validate_abi_function_declaration(ResolveContext *context, const FengDecl *decl) {
    if (decl == NULL || decl->kind != FENG_DECL_FUNCTION) {
        return true;
    }

    return validate_abi_callable_signature(context,
                                             decl->as.function_decl.token,
                                             decl->as.function_decl.name,
                                             decl->annotations,
                                             decl->annotation_count,
                                             &decl->as.function_decl,
                                             "function",
                                             decl->is_extern);
}

static bool validate_abi_callable_member(ResolveContext *context, const FengTypeMember *member) {
    bool has_abi;
    size_t callconv_count;

    if (member == NULL || member->kind == FENG_TYPE_MEMBER_FIELD) {
        return true;
    }

    has_abi = annotations_contain_kind(member->annotations, member->annotation_count, FENG_ANNOTATION_ABI);
    callconv_count = count_calling_convention_annotations(member->annotations, member->annotation_count);

    if (member->kind == FENG_TYPE_MEMBER_CONSTRUCTOR) {
        if (!has_abi && callconv_count == 0U) {
            return true;
        }

        return resolver_append_error(
            context,
            member->token,
            "AE1317", format_message(
                "constructor '%.*s' cannot use ABI annotations",
                (int)member->as.callable.name.length,
                member->as.callable.name.data));
    }

    if (member->kind == FENG_TYPE_MEMBER_FINALIZER) {
        if (!has_abi && callconv_count == 0U) {
            return true;
        }

        return resolver_append_error(
            context,
            member->token,
            "AE1317", format_message(
                "finalizer '~%.*s' cannot use ABI annotations",
                (int)member->as.callable.name.length,
                member->as.callable.name.data));
    }

    return validate_abi_callable_signature(context,
                                             member->token,
                                             member->as.callable.name,
                                             member->annotations,
                                             member->annotation_count,
                                             &member->as.callable,
                                             "method",
                                             false);
}

static bool validate_expr_against_expected_inferred_type(ResolveContext *context,
                                                         const FengExpr *expr,
                                                         InferredExprType expected_type) {
    InferredExprType expr_type;
    char *expr_name;
    char *type_name;

    if (expr == NULL || !inferred_expr_type_is_known(expected_type)) {
        return true;
    }
    if (expected_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        return validate_expr_against_expected_type(context, expr, expected_type.type_ref);
    }

    expr_type = infer_expr_type(context, expr);
    if (!inferred_expr_type_is_known(expr_type) ||
        inferred_expr_types_equal(context, expr_type, expected_type)) {
        return true;
    }

    expr_name = format_expr_target_name(expr);
    type_name = format_inferred_expr_type_name(expected_type, context->pointer_size);
    if (!resolver_append_error(context,
                               expr->token,
                               "AE1003", format_message("expression '%s' does not match expected type '%s'",
                                              expr_name != NULL ? expr_name : "<expression>",
                                              type_name != NULL ? type_name : "<type>"))) {
        free(expr_name);
        free(type_name);
        return false;
    }

    free(expr_name);
    free(type_name);
    return true;
}

static bool validate_untyped_callable_value_expr(ResolveContext *context, const FengExpr *expr) {
    char *expr_name;

    if (expr != NULL && expr->kind == FENG_EXPR_GENERIC_TARGET) {
        bool ok;

        expr_name = format_expr_target_name(expr->as.generic_target.target);
        ok = resolver_append_error(
            context,
            expr->token,
            "AE1016",
            format_message(
                "explicit generic target '%s' cannot be used as a value expression without a callable-form spec target",
                expr_name != NULL ? expr_name : "<expression>"));
        free(expr_name);
        return ok;
    }

    if (expr_is_lambda_value_without_target(context, expr)) {
        return report_lambda_requires_callable_spec_target(context, expr, "an untyped value context");
    }

    /* Feng has no anonymous callable type. Already-bound callable values have
     * a named callable-form spec type and are not classified as references by
     * this helper; an unbound function or method reference therefore needs a
     * contextual target even when its source name has only one candidate. */
    if (!expr_is_callable_value_reference(context, expr)) {
        return true;
    }

    expr_name = format_expr_target_name(expr);
    if (!resolver_append_error(context,
                               expr != NULL ? expr->token : context->program->module_token,
                               "AE0523", format_message("expression '%s' requires an explicit target function type to form a callable value; target type must be a callable-form spec",
                                              expr_name != NULL ? expr_name : "<expression>"))) {
        free(expr_name);
        return false;
    }

    free(expr_name);
    return true;
}

static bool validate_untyped_address_of_expr(ResolveContext *context, const FengExpr *expr) {
    char *expr_name;
    InferredExprType operand_type;

    if (expr == NULL || expr->kind != FENG_EXPR_UNARY || expr->as.unary.op != FENG_TOKEN_AMP) {
        return true;
    }

    if (expr_is_top_level_function_reference(context, expr->as.unary.operand)) {
        expr_name = format_expr_target_name(expr);
        if (!resolver_append_error(
                context,
                expr->token,
                "AE1010", format_message(
                    "expression '%s' requires an explicit target Foo* type to form an ABI function pointer",
                    expr_name != NULL ? expr_name : "<expression>"))) {
            free(expr_name);
            return false;
        }

        free(expr_name);
        return true;
    }

    operand_type = infer_expr_type(context, expr->as.unary.operand);
    if (!expr_is_callable_like_address_of_operand(context, expr->as.unary.operand, operand_type)) {
        return true;
    }

    expr_name = format_expr_target_name(expr);
    if (!resolver_append_error(
            context,
            expr->token,
            "AE1010", format_message(
                "expression '%s' cannot form an ABI function pointer; ABI function pointers can only be formed from top-level @abi functions with an explicit Foo* target type",
                expr_name != NULL ? expr_name : "<expression>"))) {
        free(expr_name);
        return false;
    }

    free(expr_name);
    return true;
}

static bool validate_untyped_array_literal_expr(ResolveContext *context, const FengExpr *expr) {
    size_t item_index;

    if (expr == NULL || expr->kind != FENG_EXPR_ARRAY_LITERAL) {
        return true;
    }

    if (expr->as.array_literal.count == 0U) {
        return resolver_append_error(
            context,
            expr->token,
            "AE0203",
            format_message(
                "empty array literal requires an explicit target array type"));
    }

    /* An untyped outer array cannot supply an explicit element target to a
     * nested empty literal.  Walk the literal tree so the diagnostic belongs
     * to the exact inner '[' that first lacks a target. */
    for (item_index = 0U; item_index < expr->as.array_literal.count; ++item_index) {
        size_t errors_before = context->error_count != NULL
                                   ? *context->error_count
                                   : 0U;

        if (!validate_untyped_array_literal_expr(
                context, expr->as.array_literal.items[item_index])) {
            return false;
        }
        if (context->error_count != NULL &&
            *context->error_count > errors_before) {
            return true;
        }
    }

    return true;
}

/* Tuple literals have no anonymous type and therefore need a named target. */
static bool validate_untyped_tuple_literal_expr(ResolveContext *context, const FengExpr *expr) {
    if (expr == NULL || expr->kind != FENG_EXPR_TUPLE_LITERAL) {
        return true;
    }

    return resolver_append_error(
        context,
        expr->token,
        "AE0301", format_message("tuple literal requires an explicit named tuple target type"));
}

static bool validate_constructor_invocation(ResolveContext *context,
                                            const FengExpr *target_expr,
                                            const FengDecl *type_decl,
                                            const FengSemanticModule *provider_module,
                                            FengExpr *const *args,
                                            size_t arg_count,
                                            const FengTypeRef *const *explicit_type_args,
                                            size_t explicit_type_arg_count,
                                            const FengTypeMember **out_constructor) {
    size_t declared_constructor_count;
    ConstructorResolution resolution;

    if (out_constructor != NULL) {
        *out_constructor = NULL;
    }

    if (type_decl == NULL) {
        return true;
    }

    if (!decl_is_object_form_type(type_decl)) {
        FengSlice name = decl_typeish_name(type_decl);
        const char *kind_label = decl_is_tuple_type(type_decl)
                                     ? "tuple type"
                                     : (type_decl->kind == FENG_DECL_SPEC ? "spec" : "type");
        bool ok = resolver_append_error(
            context,
            target_expr != NULL ? target_expr->token : context->program->module_token,
            "AE0312", format_message("%s '%.*s' is not an object type and cannot be constructed",
                           kind_label,
                           (int)name.length,
                           name.data));

        return ok;
    }

    /* A bare constructor target has arity zero. A generic owner selected only
     * by the name-only diagnostic fallback is not a constructible instance:
     * constructor arguments and contextual types never infer owner type
     * parameters. */
    if (type_decl->as.type_decl.type_param_count > 0U &&
        explicit_type_arg_count == 0U) {
        return resolver_append_error(
            context,
            target_expr != NULL ? target_expr->token : context->program->module_token,
            "AE0315", format_message("type '%.*s' has no accessible constructor accepting %zu argument(s)",
                           (int)type_decl->as.type_decl.name.length,
                           type_decl->as.type_decl.name.data,
                           arg_count));
    }

    declared_constructor_count = count_declared_constructors(type_decl);
    if (declared_constructor_count == 0U) {
        if (find_prepacked_variadic_arg(args, arg_count, NULL)) {
            return report_prepacked_variadic_rejection(
                context,
                target_expr,
                FENG_PREPACKED_VARIADIC_REJECTION_TARGET_NOT_VARIADIC);
        }
        if (arg_count == 0U) {
            return true;
        }

        return resolver_append_error(
            context,
            target_expr != NULL ? target_expr->token : context->program->module_token,
            "AE0313", format_message("type '%.*s' has no constructor accepting %zu argument(s)",
                           (int)type_decl->as.type_decl.name.length,
                           type_decl->as.type_decl.name.data,
                           arg_count));
    }

    resolution = resolve_accessible_constructor_overload(
        context, type_decl, provider_module, args, arg_count,
        explicit_type_args, explicit_type_arg_count);
    if (resolution.kind == FENG_CONSTRUCTOR_RESOLUTION_UNIQUE) {
        if (resolution.constructor != NULL &&
            !validate_borrowed_data_pointer_call_arguments(
                context,
                target_expr,
                args,
                arg_count,
                resolution.constructor->as.callable.params,
                resolution.constructor->as.callable.param_count,
                false)) {
            return false;
        }
        note_callable_exception_escape(context,
                                       resolution.constructor != NULL
                                           ? &resolution.constructor->as.callable
                                           : NULL);
        if (out_constructor != NULL) {
            *out_constructor = resolution.constructor;
        }
        return true;
    }
    if (resolution.kind == FENG_CONSTRUCTOR_RESOLUTION_AMBIGUOUS) {
        return resolver_append_error(
            context,
            target_expr != NULL ? target_expr->token : context->program->module_token,
            "AE0314", format_message("type '%.*s' has multiple accessible constructors matching %zu argument(s); argument types are ambiguous",
                           (int)type_decl->as.type_decl.name.length,
                           type_decl->as.type_decl.name.data,
                           arg_count));
    }
    if (resolution.prepacked_variadic_rejection !=
        FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
        return report_prepacked_variadic_rejection(
            context, target_expr, resolution.prepacked_variadic_rejection);
    }

    return resolver_append_error(
        context,
        target_expr != NULL ? target_expr->token : context->program->module_token,
        "AE0315", format_message("type '%.*s' has no accessible constructor accepting %zu argument(s)",
                       (int)type_decl->as.type_decl.name.length,
                       type_decl->as.type_decl.name.data,
                       arg_count));
}

static bool validate_constructor_call_expr(ResolveContext *context, const FengExpr *expr) {
    ResolvedTypeTarget target = resolve_type_target_expr(context, expr->as.call.callee, false);
    const FengTypeMember *constructor_member = NULL;

    {
        size_t wanted_arity = expr->as.call.has_explicit_type_args
                                  ? expr->as.call.explicit_type_arg_count
                                  : 0U;
        ResolvedTypeTarget precise = resolve_type_target_expr_exact_arity(
            context, expr->as.call.callee, wanted_arity);

        if (precise.type_decl != NULL) {
            target = precise;
        }
    }

    if (target.type_decl == NULL) {
        return true;
    }

    if (!validate_constructor_invocation(context,
                                         expr->as.call.callee,
                                         target.type_decl,
                                         target.provider_module,
                                         expr->as.call.args,
                                         expr->as.call.arg_count,
                                         expr->as.call.has_explicit_type_args
                                             ? (const FengTypeRef *const *)expr->as.call.explicit_type_args
                                             : NULL,
                                         expr->as.call.has_explicit_type_args
                                             ? expr->as.call.explicit_type_arg_count
                                             : 0U,
                                         &constructor_member)) {
        return false;
    }

    /* A known non-object type owns the constructibility diagnostic above.
     * Do not record it as a resolved constructor or run object-only default
     * initialization checks after that diagnostic has been emitted. */
    if (!decl_is_object_form_type(target.type_decl)) {
        return true;
    }

    if (target.type_decl->kind == FENG_DECL_TYPE) {
        FengExpr *mutable_expr = (FengExpr *)expr;
        FengTypeRef *owner_instance_ref =
            synthesize_constructor_owner_instance_type_ref(
                context, expr, target.type_decl);
        InferredExprType owner_type = owner_instance_ref != NULL
                                          ? inferred_expr_type_from_type_ref(
                                                owner_instance_ref)
                                          : resolved_type_target_owner_type(
                                                &target);

        if (!validate_construction_default_zero_requirements(
                context,
                expr->as.call.callee,
                target.type_decl,
                owner_type)) {
            return false;
        }

        mutable_expr->as.call.resolved_callable.kind = FENG_RESOLVED_CALLABLE_TYPE_CONSTRUCTOR;
        mutable_expr->as.call.resolved_callable.owner_type_decl = target.type_decl;
        mutable_expr->as.call.resolved_callable.member = constructor_member;
        if (owner_instance_ref != NULL) {
            FengTypeRef *persistent_owner_ref =
                clone_type_ref_for_inference(owner_instance_ref);

            if (persistent_owner_ref == NULL ||
                !analysis_track_synthetic_type_ref(context->analysis,
                                                   persistent_owner_ref)) {
                free_synthetic_type_ref(persistent_owner_ref);
                return resolver_append_error(
                    context,
                    expr->token,
                    "IE0001",
                    format_message(
                        "out of memory while recording constructor owner type"));
            }
            mutable_expr->as.call.resolved_callable.owner_instance_type_ref =
                persistent_owner_ref;
        }
        if (expr->as.call.has_explicit_type_args) {
            materialize_named_type_param_constraint_witnesses(
                context,
                target.type_decl->as.type_decl.type_params,
                target.type_decl->as.type_decl.type_param_count,
                (const FengTypeRef *const *)expr->as.call.explicit_type_args,
                expr->as.call.explicit_type_arg_count,
                expr->token);
        }
        if (constructor_member != NULL &&
            constructor_member->kind == FENG_TYPE_MEMBER_CONSTRUCTOR) {
            record_object_arg_coercion_sites(context,
                                             expr->as.call.args,
                                             expr->as.call.arg_count,
                                             constructor_member->as.callable.params,
                                             constructor_member->as.callable.param_count,
                                             FENG_SPEC_OBJECT_SUBJECT_STORAGE_BOX_OWNER);
        }
    }
    return true;
}

/* Persist one caller-view type expression attached to a resolved call. */
static bool persist_resolved_callable_type_ref(
    ResolveContext *context,
    const FengExpr *call_expr,
    const FengTypeRef *source,
    const char *role,
    const FengTypeRef **out_ref) {
    FengTypeRef *persistent;

    if (out_ref == NULL) {
        return false;
    }
    *out_ref = NULL;
    if (source == NULL) {
        return true;
    }
    persistent = clone_type_ref_for_inference(source);
    if (persistent == NULL ||
        !analysis_track_synthetic_type_ref(context->analysis, persistent)) {
        free_synthetic_type_ref(persistent);
        return resolver_append_error(
            context,
            call_expr->token,
            "IE0001",
            format_message("out of memory while recording resolved callable %s",
                           role != NULL ? role : "type"));
    }
    *out_ref = persistent;
    return true;
}

/* Record overload-resolution metadata that is consumed after ResolveContext
 * teardown.  owner_instance_type_ref may come from the resolver's temporary
 * type-ref pool, so persist a complete clone in the analysis before attaching
 * it to the AST. */
static bool record_resolved_callable_from_resolution(
    ResolveContext *context, const FengExpr *call_expr,
    const FunctionCallResolution *resolution,
    const FengTypeRef *owner_instance_type_ref) {
    FengExpr *mutable_expr = (FengExpr *)call_expr;
    FengResolvedCallable *slot;
    const FengTypeRef *persistent_owner_ref = NULL;
    FengTypeRef *synthetic_owner_ref = NULL;

    if (mutable_expr == NULL || mutable_expr->kind != FENG_EXPR_CALL ||
        resolution == NULL ||
        resolution->kind != FENG_FUNCTION_CALL_RESOLUTION_UNIQUE) {
        return true;
    }

    if (resolution->owner_instance_type_ref != NULL) {
        owner_instance_type_ref = resolution->owner_instance_type_ref;
    }

    /* `self.method()` is inferred from the owner declaration and therefore
     * has no instance type_ref. Reconstruct the ordinary open owner instance
     * from declaration-ordered type parameters so downstream callable
     * dependency closure sees the same `Owner<T...>` shape as other calls. */
    if (owner_instance_type_ref == NULL &&
        resolution->owner_type_decl != NULL &&
        resolution->owner_type_decl->kind == FENG_DECL_TYPE &&
        resolution->owner_type_decl->as.type_decl.type_param_count > 0U &&
        context->current_type_decl == resolution->owner_type_decl) {
        const FengDecl *owner_decl = resolution->owner_type_decl;
        size_t owner_param_count =
            owner_decl->as.type_decl.type_param_count;

        synthetic_owner_ref = (FengTypeRef *)calloc(
            1U, sizeof(*synthetic_owner_ref));
        if (synthetic_owner_ref != NULL) {
            synthetic_owner_ref->token = call_expr->token;
            synthetic_owner_ref->kind = FENG_TYPE_REF_NAMED;
            synthetic_owner_ref->as.named.segments =
                (FengSlice *)malloc(sizeof(FengSlice));
            synthetic_owner_ref->as.named.type_args =
                (FengTypeRef **)calloc(
                    owner_param_count,
                    sizeof(*synthetic_owner_ref->as.named.type_args));
            if (synthetic_owner_ref->as.named.segments != NULL &&
                synthetic_owner_ref->as.named.type_args != NULL) {
                bool owner_ok = true;

                synthetic_owner_ref->as.named.segments[0] =
                    owner_decl->as.type_decl.name;
                synthetic_owner_ref->as.named.segment_count = 1U;
                synthetic_owner_ref->as.named.type_arg_count =
                    owner_param_count;
                for (size_t index = 0U;
                     index < owner_param_count;
                     ++index) {
                    FengTypeRef *arg =
                        (FengTypeRef *)calloc(1U, sizeof(*arg));

                    if (arg == NULL) {
                        owner_ok = false;
                        break;
                    }
                    arg->token = owner_decl->as.type_decl.type_params[index].token;
                    arg->kind = FENG_TYPE_REF_NAMED;
                    arg->as.named.segments =
                        (FengSlice *)malloc(sizeof(FengSlice));
                    if (arg->as.named.segments == NULL) {
                        free(arg);
                        owner_ok = false;
                        break;
                    }
                    arg->as.named.segments[0] =
                        owner_decl->as.type_decl.type_params[index].name;
                    arg->as.named.segment_count = 1U;
                    synthetic_owner_ref->as.named.type_args[index] = arg;
                }
                if (owner_ok) {
                    owner_instance_type_ref = synthetic_owner_ref;
                }
            }
        }
    }

    if (!persist_resolved_callable_type_ref(context,
                                            call_expr,
                                            owner_instance_type_ref,
                                            "owner type",
                                            &persistent_owner_ref)) {
        free_synthetic_type_ref(synthetic_owner_ref);
        return false;
    }
    free_synthetic_type_ref(synthetic_owner_ref);

    slot = &mutable_expr->as.call.resolved_callable;
    slot->owner_instance_type_ref = persistent_owner_ref;
    free((void *)slot->callable_type_args);
    slot->callable_type_args = NULL;
    slot->callable_type_arg_count = 0U;
    if (resolution->callable != NULL &&
        resolution->callable->type_param_count > 0U) {
        size_t type_arg_count =
            resolution->callable->type_param_count;
        InferredExprType owner_type = persistent_owner_ref != NULL
                                          ? inferred_expr_type_from_type_ref(
                                                persistent_owner_ref)
                                          : inferred_expr_type_unknown();
        const FengTypeRef *target_inference_return_type =
            substitute_type_ref_for_owner_instance(
                context,
                resolution->owner_type_decl,
                owner_type,
                resolution->callable->return_type);
        FengTypeRef **inferred_type_args = (FengTypeRef **)calloc(
            type_arg_count, sizeof(*inferred_type_args));
        bool *owned_type_args = (bool *)calloc(
            type_arg_count, sizeof(*owned_type_args));
        const FengTypeRef **persistent_type_args =
            (const FengTypeRef **)calloc(
                type_arg_count, sizeof(*persistent_type_args));
        bool type_args_ok = inferred_type_args != NULL &&
                            owned_type_args != NULL &&
                            persistent_type_args != NULL;
        bool type_args_incomplete = false;
        size_t incomplete_type_arg_index = 0U;

        target_inference_return_type = substitute_type_ref_for_fit_instance(
            context,
            resolution->fit_decl,
            owner_type,
            target_inference_return_type);

        if (type_args_ok) {
            type_args_ok = callable_collect_call_type_args(
                context,
                call_expr,
                resolution->callable,
                target_inference_return_type,
                resolution->decl != NULL && resolution->decl->is_extern,
                true,
                inferred_type_args,
                owned_type_args);
        }
        for (size_t index = 0U;
             index < type_arg_count && type_args_ok;
             ++index) {
            FengTypeRef *persistent_type_arg;

            if (inferred_type_args[index] == NULL) {
                type_args_incomplete = true;
                incomplete_type_arg_index = index;
                break;
            }
            persistent_type_arg =
                clone_type_ref_for_inference(inferred_type_args[index]);
            if (persistent_type_arg == NULL ||
                !analysis_track_synthetic_type_ref(
                    context->analysis, persistent_type_arg)) {
                free_synthetic_type_ref(persistent_type_arg);
                type_args_ok = false;
                break;
            }
            normalize_type_ref(persistent_type_arg, context->pointer_size);
            persistent_type_args[index] = persistent_type_arg;
        }
        for (size_t index = 0U; index < type_arg_count; ++index) {
            if (owned_type_args != NULL && owned_type_args[index]) {
                free_synthetic_type_ref(inferred_type_args[index]);
            }
        }
        free(inferred_type_args);
        free(owned_type_args);
        if (type_args_incomplete) {
            free(persistent_type_args);
            resolver_append_error(
                context,
                call_expr->token,
                "AE0525",
                format_message(
                    "cannot infer type argument %zu for generic callable '%.*s'; provide an explicit type argument or a target type",
                    incomplete_type_arg_index,
                    (int)resolution->callable->name.length,
                    resolution->callable->name.data));
            return false;
        }
        if (!type_args_ok) {
            free(persistent_type_args);
            resolver_append_error(
                context,
                call_expr->token,
                "IE0001",
                format_message(
                    "failed to persist resolved callable type arguments"));
            return false;
        }
        slot->callable_type_args = persistent_type_args;
        slot->callable_type_arg_count = type_arg_count;
    }
    if (resolution->member != NULL &&
        !record_selected_friend_fit_access(
            context,
            resolution->owner_type_decl,
            persistent_owner_ref != NULL
                ? inferred_expr_type_from_type_ref(persistent_owner_ref)
                : inferred_expr_type_from_decl(resolution->owner_type_decl),
            resolution->member)) {
        return false;
    }
    if (resolution->fit_decl != NULL) {
        slot->kind = resolution->member != NULL && resolution->member->is_static
                         ? FENG_RESOLVED_CALLABLE_FIT_STATIC_METHOD
                         : FENG_RESOLVED_CALLABLE_FIT_METHOD;
        slot->owner_type_decl = resolution->owner_type_decl;
        slot->member = resolution->member;
        slot->fit_decl = resolution->fit_decl;
        return true;
    }
    if (resolution->member != NULL &&
        resolution->owner_type_decl != NULL &&
        resolution->owner_type_decl->kind == FENG_DECL_SPEC) {
        slot->kind = resolution->member->is_static
                         ? FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD
                         : FENG_RESOLVED_CALLABLE_SPEC_METHOD;
        slot->owner_type_decl = resolution->owner_type_decl;
        slot->member = resolution->member;
        return true;
    }
    if (resolution->member != NULL) {
        slot->kind = resolution->member->is_static
                         ? FENG_RESOLVED_CALLABLE_TYPE_STATIC_METHOD
                         : FENG_RESOLVED_CALLABLE_TYPE_METHOD;
        slot->owner_type_decl = resolution->owner_type_decl;
        slot->member = resolution->member;
        return true;
    }
    if (resolution->decl != NULL) {
        slot->kind = FENG_RESOLVED_CALLABLE_FUNCTION;
        slot->function_decl = resolution->decl;
        return true;
    }
    return true;
}

/* After overload resolution picks the unique winner, commit the literal
 * argument types based on the winning candidate's parameter shapes.
 *
 * During overload-resolution candidate probing, expr_matches_expected_type_ref
 * is called multiple times per literal (once per candidate) with different
 * parameter types, and suppress_literal_type_commit prevents it from writing
 * to expr->type.  This function fills in the correct type using the winning
 * candidate's substituted parameter types, with analysis-lifetime tracking so
 * codegen can read the type after the resolve context is torn down. */
static void commit_literal_arg_adaptations_for_resolved_call(
    ResolveContext *context,
    FengExpr *const *args,
    size_t arg_count,
    const FengCallableSignature *callable,
    const FengDecl *owner_type_decl,
    const FengDecl *fit_decl,
    InferredExprType owner_type) {
    size_t i;
    bool is_variadic;
    size_t fixed_count;

    if (args == NULL || callable == NULL) {
        return;
    }
    is_variadic = callable->param_count > 0U &&
                  callable->params[callable->param_count - 1U].is_variadic;
    fixed_count = is_variadic ? callable->param_count - 1U : callable->param_count;
    if (!is_variadic && callable->param_count != arg_count) {
        return;
    }
    if (is_variadic && arg_count < fixed_count) {
        return;
    }

    for (i = 0U; i < arg_count; ++i) {
        const FengTypeRef *declared_param_type;
        const FengTypeRef *param_type;
        const FengTypeRef *literal_target;

        if (args[i] == NULL) {
            continue;
        }
        /* Only commit for pure numeric literals that need adaptation. */
        if (!expr_is_pure_numeric_literal_expr_for_target_adaptation(args[i])) {
            continue;
        }
        /* Skip type-parameter positions: the argument drives the inferred type
         * argument, not the other way around — no literal adaptation needed. */
        if (i < fixed_count &&
            param_type_is_type_param_ref(callable, callable->params[i].type)) {
            continue;
        }

        if (i < fixed_count) {
            declared_param_type = callable->params[i].type;
        } else {
            /* Variadic position: match against element type T. */
            declared_param_type = callable->params[fixed_count].type->as.inner;
        }

        param_type = substitute_type_ref_for_owner_instance(
            context, owner_type_decl, owner_type, declared_param_type);
        param_type = substitute_type_ref_for_fit_instance(
            context, fit_decl, owner_type, param_type);

        literal_target = param_type;
        if (!numeric_literal_adapts_to_target(context,
                                              args[i],
                                              literal_target)) {
            const FengDecl *target_union_decl =
                resolve_union_spec_type_ref_decl(context, param_type);

            if (target_union_decl == NULL) {
                continue;
            }
            literal_target = select_literal_expr_union_member_target(
                context,
                args[i],
                target_union_decl,
                param_type);
            if (literal_target == NULL) {
                continue;
            }
        }

        /* Adaptation succeeded. Clone the selected scalar target or union
         * leaf type to the analysis lifetime so codegen can read it after
         * ResolveContext teardown. A target identical to the declaration ref
         * already has AST lifetime and can be used directly. */
        if (literal_target != declared_param_type) {
            InferredExprType adapted =
                inferred_expr_type_from_type_ref(literal_target);
            FengTypeRef *synth = create_type_ref_from_inferred_type(&adapted,
                                                                     args[i]->token);
            if (synth != NULL) {
                FengTypeRef *clone = clone_type_ref_for_inference(synth);
                free_synthetic_type_ref(synth);
                if (clone != NULL &&
                    analysis_track_synthetic_type_ref(context->analysis, clone)) {
                    ((FengExpr *)args[i])->type = clone;
                } else {
                    free_synthetic_type_ref(clone);
                }
            }
        } else {
            ((FengExpr *)args[i])->type = literal_target;
        }
    }
}

static bool validate_function_call_expr(ResolveContext *context, const FengExpr *expr) {
    const FengExpr *callee = expr->as.call.callee;

    if (callee == NULL) {
        return true;
    }

    if (callee->kind == FENG_EXPR_MEMBER) {
        const FengExpr *object = callee->as.member.object;
        const FengDecl *owner_type_decl = NULL;
        const FengSemanticModule *provider_module = NULL;
        InferredExprType owner_type;
        FunctionCallResolution resolution;

        {
            ResolvedModuleMemberTarget module_target;

            if (resolve_module_member_target(
                    context, callee, &module_target)) {
                resolution = resolve_module_public_function_overload(context,
                                                                    module_target.module,
                                                                    module_target.member_name,
                                                                    expr->as.call.args,
                                                                    expr->as.call.arg_count,
                                                                    expr->as.call.has_explicit_type_args,
                                                                    (const FengTypeRef *const *)expr->as.call.explicit_type_args,
                                                                    expr->as.call.explicit_type_arg_count);

                if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE) {
                    if (!validate_borrowed_data_pointer_call_arguments(
                            context,
                            callee,
                            expr->as.call.args,
                            expr->as.call.arg_count,
                            resolution.callable->params,
                            resolution.callable->param_count,
                            resolution.decl != NULL && resolution.decl->is_extern)) {
                        return false;
                    }
                    note_callable_exception_escape(context, resolution.callable);
                    materialize_callable_type_param_constraint_witnesses(context,
                                                                        expr,
                                                                        resolution.callable,
                                                                        NULL,
                                                                        NULL,
                                                                        inferred_expr_type_unknown());
                    if (!record_resolved_callable_from_resolution(
                            context, expr, &resolution, NULL)) {
                        return false;
                    }
                    record_object_arg_coercion_sites_for_resolved_call(
                        context,
                        expr,
                        resolution.callable,
                        NULL,
                        inferred_expr_type_unknown());
                    commit_literal_arg_adaptations_for_resolved_call(
                        context,
                        expr->as.call.args,
                        expr->as.call.arg_count,
                        resolution.callable,
                        NULL,
                        NULL,
                        inferred_expr_type_unknown());
                    return true;
                }
                if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_AMBIGUOUS) {
                    char *member_name =
                        format_module_member_target_name(&module_target);
                    char *message = format_message(
                        "function '%s' has multiple overloads matching %zu argument(s); argument types are ambiguous",
                        member_name != NULL ? member_name : "<unknown>",
                        expr->as.call.arg_count);

                    free(member_name);
                    return resolver_append_error(context,
                                                 callee->token,
                                                 "AE0511",
                                                 message);
                }
                if (resolution.prepacked_variadic_rejection !=
                    FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
                    return report_prepacked_variadic_rejection(
                        context, callee, resolution.prepacked_variadic_rejection);
                }
                if (resolution.rejected_existing_array_for_variadic) {
                    return report_existing_array_rejected_for_variadic_call(context, callee);
                }
                if (find_module_public_function_decl(module_target.module,
                                                     module_target.member_name) != NULL) {
                    char *member_name =
                        format_module_member_target_name(&module_target);
                    char *message = format_message(
                        "function '%s' has no overload accepting %zu argument(s)",
                        member_name != NULL ? member_name : "<unknown>",
                        expr->as.call.arg_count);

                    free(member_name);
                    return resolver_append_error(context,
                                                 callee->token,
                                                 "AE0512",
                                                 message);
                }

                return validate_callable_typed_expr_call(context,
                                                         callee,
                                                         expr->as.call.args,
                                                         expr->as.call.arg_count);
            }
        }

        {
            ResolvedTypeTarget static_target = resolve_type_target_expr(context, object, false);

            if (static_target.type_decl != NULL || static_target.is_builtin_type_name) {
                FengSlice owner_name = static_target.type_decl != NULL
                                           ? decl_typeish_name(static_target.type_decl)
                                           : static_target.builtin_name;
                    InferredExprType static_owner_type = resolved_type_target_owner_type(&static_target);
                bool has_static_method = static_target.type_decl != NULL
                                             ? find_type_static_method_member(static_target.type_decl,
                                                                              callee->as.member.member) != NULL ||
                                                   find_fit_static_method_member_for_type(context,
                                                                                         static_target.type_decl,
                                                                                         callee->as.member.member) != NULL
                                             : find_fit_static_method_member_for_owner_type(context,
                                                                                           NULL,
                                                                                           static_owner_type,
                                                                                           callee->as.member.member) != NULL;
                resolution = resolve_accessible_static_method_overload(context,
                                                                       static_target.type_decl,
                                                                       static_target.provider_module,
                                                                       static_owner_type,
                                                                       callee->as.member.member,
                                                                       expr->as.call.args,
                                                                       expr->as.call.arg_count,
                                                                       expr->as.call.has_explicit_type_args,
                                                                       (const FengTypeRef *const *)expr->as.call.explicit_type_args,
                                                                       expr->as.call.explicit_type_arg_count);

                if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE) {
                    if (!validate_borrowed_data_pointer_call_arguments(context,
                                                                       callee,
                                                                       expr->as.call.args,
                                                                       expr->as.call.arg_count,
                                                                       resolution.callable->params,
                                                                       resolution.callable->param_count,
                                                                       false)) {
                        return false;
                    }
                    note_callable_exception_escape(context, resolution.callable);
                    materialize_callable_type_param_constraint_witnesses(context,
                                                                        expr,
                                                                        resolution.callable,
                                                                        static_target.type_decl,
                                                                        resolution.fit_decl,
                                                                        static_owner_type);
                    if (!record_resolved_callable_from_resolution(
                            context,
                            expr,
                            &resolution,
                            static_owner_type.type_ref)) {
                        return false;
                    }
                    record_object_arg_coercion_sites_for_resolved_call(
                        context,
                        expr,
                        resolution.callable,
                        static_target.type_decl,
                        static_owner_type);
                    commit_literal_arg_adaptations_for_resolved_call(
                        context,
                        expr->as.call.args,
                        expr->as.call.arg_count,
                        resolution.callable,
                        static_target.type_decl,
                        resolution.fit_decl,
                        static_owner_type);
                    return true;
                }
                if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_AMBIGUOUS) {
                    return resolver_append_error(
                        context,
                        callee->token,
                        "AE0511", format_message("static method '%.*s.%.*s' has multiple overloads matching %zu argument(s); argument types are ambiguous",
                                       (int)owner_name.length,
                                       owner_name.data,
                                       (int)callee->as.member.member.length,
                                       callee->as.member.member.data,
                                       expr->as.call.arg_count));
                }
                if (resolution.prepacked_variadic_rejection !=
                    FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
                    return report_prepacked_variadic_rejection(
                        context, callee, resolution.prepacked_variadic_rejection);
                }
                if (resolution.rejected_existing_array_for_variadic) {
                    return report_existing_array_rejected_for_variadic_call(context, callee);
                }
                if (has_static_method) {
                    return resolver_append_error(
                        context,
                        callee->token,
                        "AE0512", format_message("static method '%.*s.%.*s' has no overload accepting %zu argument(s)",
                                       (int)owner_name.length,
                                       owner_name.data,
                                       (int)callee->as.member.member.length,
                                       callee->as.member.member.data,
                                       expr->as.call.arg_count));
                }

                return validate_callable_typed_expr_call(context,
                                                         callee,
                                                         expr->as.call.args,
                                                         expr->as.call.arg_count);
            }

            /* G4 / IC01: T.method() dispatch via the generic type parameter's
             * complete object- or intersection-form constraint surface. The
             * resolver retains the exact declaring requirement so codegen can
             * select the ordinary or merged witness slot by identity. */
            if (static_target.is_generic_type_param &&
                static_target.constraint_spec_decl != NULL) {
                InferredExprType constraint_owner =
                    static_target.constraint_spec_type_ref != NULL
                        ? inferred_expr_type_from_type_ref(
                              static_target.constraint_spec_type_ref)
                        : inferred_expr_type_from_decl(
                              static_target.constraint_spec_decl);
                SpecMethodCallResolution spec_result =
                    resolve_spec_method_call_overload(
                        context,
                        static_target.constraint_spec_decl,
                        constraint_owner,
                        callee->as.member.member,
                        expr->as.call.args,
                        expr->as.call.arg_count,
                        true,
                        expr->as.call.has_explicit_type_args,
                        (const FengTypeRef *const *)
                            expr->as.call.explicit_type_args,
                        expr->as.call.explicit_type_arg_count);

                resolution = spec_result.call;
                if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE) {
                    const FengCallableSignature *spec_sig = resolution.callable;
                    const FengDecl *declaring_spec =
                        resolution.owner_type_decl;
                    const FengTypeRef *declaring_spec_instance =
                        resolution.owner_instance_type_ref;
                    InferredExprType declaring_owner =
                        declaring_spec_instance != NULL
                            ? inferred_expr_type_from_type_ref(
                                  declaring_spec_instance)
                            : inferred_expr_type_from_decl(declaring_spec);

                    if (!validate_borrowed_data_pointer_call_arguments(
                            context,
                            callee,
                            expr->as.call.args,
                            expr->as.call.arg_count,
                            spec_sig->params,
                            spec_sig->param_count,
                            false)) {
                        return false;
                    }
                    note_callable_exception_escape(context, spec_sig);
                    materialize_callable_type_param_constraint_witnesses(
                        context,
                        expr,
                        spec_sig,
                        declaring_spec,
                        NULL,
                        declaring_owner);
                    if (!record_resolved_callable_from_resolution(
                            context,
                            expr,
                            &resolution,
                            declaring_spec_instance)) {
                        return false;
                    }
                    record_object_arg_coercion_sites_for_resolved_call(
                        context,
                        expr,
                        spec_sig,
                        declaring_spec,
                        declaring_owner);
                    commit_literal_arg_adaptations_for_resolved_call(
                        context,
                        expr->as.call.args,
                        expr->as.call.arg_count,
                        spec_sig,
                        declaring_spec,
                        NULL,
                        declaring_owner);
                    return true;
                }
                if (resolution.kind ==
                    FENG_FUNCTION_CALL_RESOLUTION_AMBIGUOUS) {
                    return resolver_append_error(
                        context,
                        callee->token,
                        "AE0511", format_message("static method '%.*s.%.*s' has multiple overloads matching %zu argument(s); argument types are ambiguous",
                                       (int)object->as.identifier.length,
                                       object->as.identifier.data,
                                       (int)callee->as.member.member.length,
                                       callee->as.member.member.data,
                                       expr->as.call.arg_count));
                }
                if (resolution.prepacked_variadic_rejection !=
                    FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
                    return report_prepacked_variadic_rejection(
                        context,
                        callee,
                        resolution.prepacked_variadic_rejection);
                }
                if (resolution.rejected_existing_array_for_variadic) {
                    return report_existing_array_rejected_for_variadic_call(
                        context, callee);
                }
                if (spec_result.has_matching_inaccessible_method) {
                    /* The callee member-expression pass already reports the
                     * sole inaccessible surface. A second report is needed
                     * only when an accessible same-name overload caused that
                     * pass to continue, but the matching candidate itself is
                     * inaccessible. */
                    if (!spec_result.has_accessible_named_method) {
                        return true;
                    }
                    return report_inaccessible_spec_member(
                        context,
                        callee->token,
                        spec_result.inaccessible_declaring_spec,
                        spec_result.inaccessible_member);
                }
                if (spec_result.has_accessible_named_method) {
                    return resolver_append_error(
                        context,
                        callee->token,
                        "AE0512", format_message("static method '%.*s.%.*s' has no overload accepting %zu argument(s)",
                                       (int)object->as.identifier.length,
                                       object->as.identifier.data,
                                       (int)callee->as.member.member.length,
                                       callee->as.member.member.data,
                                       expr->as.call.arg_count));
                }
                return resolver_append_error(
                    context,
                    callee->token,
                    "AE0512", format_message("constraint spec has no static method '%.*s' accessible on type parameter '%.*s'",
                                   (int)callee->as.member.member.length,
                                   callee->as.member.member.data,
                                   (int)object->as.identifier.length,
                                   object->as.identifier.data));
            }
        }

        owner_type = resolve_expr_owner_type(context, object, &owner_type_decl, &provider_module);
        if (owner_type_decl != NULL &&
            (owner_type_decl->kind == FENG_DECL_TYPE ||
             owner_type_decl->kind == FENG_DECL_ENUM ||
             owner_type_decl->kind == FENG_DECL_SPEC)) {
            FengSlice owner_name = decl_typeish_name(owner_type_decl);
            const FengTypeMember *accessible_method =
                owner_type_decl->kind == FENG_DECL_TYPE
                    ? find_accessible_type_method_member(context,
                                                         owner_type_decl,
                                                         provider_module,
                                                         owner_type,
                                                         callee->as.member.member)
                    : owner_type_decl->kind == FENG_DECL_ENUM
                        ? find_fit_method_member_for_type(context,
                                                          owner_type_decl,
                                                          callee->as.member.member)
                    : find_accessible_spec_object_member(
                          context,
                          owner_type_decl,
                          owner_type,
                          callee->as.member.member,
                          /*include_static=*/false,
                          NULL);
            const FengTypeMember *field_member =
                owner_type_decl->kind == FENG_DECL_TYPE
                    ? find_type_field_member(owner_type_decl, callee->as.member.member)
                    : find_spec_object_member(context,
                                              owner_type_decl,
                                              callee->as.member.member,
                                              /*include_static=*/false);
            const FengTypeMember *accessible_field =
                owner_type_decl->kind == FENG_DECL_TYPE
                    ? find_accessible_type_field_member(context,
                                                        owner_type_decl,
                                                        provider_module,
                                                        owner_type,
                                                        callee->as.member.member)
                    : find_accessible_spec_object_member(
                          context,
                          owner_type_decl,
                          owner_type,
                          callee->as.member.member,
                          /*include_static=*/false,
                          NULL);

            if (accessible_method != NULL && accessible_method->kind != FENG_TYPE_MEMBER_METHOD) {
                accessible_method = NULL;
            }
            if (field_member != NULL && field_member->kind != FENG_TYPE_MEMBER_FIELD) {
                field_member = NULL;
            }
            if (accessible_field != NULL && accessible_field->kind != FENG_TYPE_MEMBER_FIELD) {
                accessible_field = NULL;
            }

            resolution = resolve_accessible_method_overload(context,
                                                            owner_type_decl,
                                                            provider_module,
                                                            owner_type,
                                                            callee->as.member.member,
                                                            expr->as.call.args,
                                                            expr->as.call.arg_count,
                                                            expr->as.call.has_explicit_type_args,
                                                            (const FengTypeRef *const *)expr->as.call.explicit_type_args,
                                                            expr->as.call.explicit_type_arg_count);

            if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE) {
                if (!validate_borrowed_data_pointer_call_arguments(context,
                                                                   callee,
                                                                   expr->as.call.args,
                                                                   expr->as.call.arg_count,
                                                                   resolution.callable->params,
                                                                   resolution.callable->param_count,
                                                                   false)) {
                    return false;
                }
                note_callable_exception_escape(context, resolution.callable);
                materialize_callable_type_param_constraint_witnesses(context,
                                                                    expr,
                                                                    resolution.callable,
                                                                    owner_type_decl,
                                                                    resolution.fit_decl,
                                                                    owner_type);
                if (!record_resolved_callable_from_resolution(
                        context, expr, &resolution, owner_type.type_ref)) {
                    return false;
                }
                record_object_arg_coercion_sites_for_resolved_call(
                    context,
                    expr,
                    resolution.callable,
                    owner_type_decl,
                    owner_type);
                commit_literal_arg_adaptations_for_resolved_call(
                    context,
                    expr->as.call.args,
                    expr->as.call.arg_count,
                    resolution.callable,
                    owner_type_decl,
                    resolution.fit_decl,
                    owner_type);
                return true;
            }
            if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_AMBIGUOUS) {
                return resolver_append_error(
                    context,
                    callee->token,
                    "AE0511", format_message("method '%.*s.%.*s' has multiple overloads matching %zu argument(s); argument types are ambiguous",
                                   (int)owner_name.length,
                                   owner_name.data,
                                   (int)callee->as.member.member.length,
                                   callee->as.member.member.data,
                                   expr->as.call.arg_count));
            }
            if (resolution.prepacked_variadic_rejection !=
                FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
                return report_prepacked_variadic_rejection(
                    context, callee, resolution.prepacked_variadic_rejection);
            }
            if (resolution.rejected_existing_array_for_variadic) {
                return report_existing_array_rejected_for_variadic_call(context, callee);
            }
            if (accessible_method != NULL) {
                return resolver_append_error(
                    context,
                    callee->token,
                    "AE0512", format_message("method '%.*s.%.*s' has no overload accepting %zu argument(s)",
                                   (int)owner_name.length,
                                   owner_name.data,
                                   (int)callee->as.member.member.length,
                                   callee->as.member.member.data,
                                   expr->as.call.arg_count));
            }
            if (owner_type_decl->kind == FENG_DECL_TYPE &&
                field_member != NULL && accessible_field == NULL) {
                return true;
            }
            if (owner_type_decl->kind == FENG_DECL_TYPE &&
                find_type_method_member(owner_type_decl, callee->as.member.member) != NULL) {
                return true;
            }
            if (owner_type_decl->kind == FENG_DECL_SPEC) {
                const FengTypeMember *existing_spec_member =
                    find_spec_object_member(context,
                                            owner_type_decl,
                                            callee->as.member.member,
                                            /*include_static=*/false);

                if (existing_spec_member != NULL &&
                    existing_spec_member->kind == FENG_TYPE_MEMBER_METHOD) {
                    /* The member-expression pass already emitted AE0708 for
                     * an inaccessible seal member. Avoid a secondary
                     * no-overload diagnostic for the same source token. */
                    return true;
                }
            }
            if (accessible_field != NULL) {
                return validate_callable_typed_expr_call(context,
                                                         callee,
                                                         expr->as.call.args,
                                                         expr->as.call.arg_count);
            }
        }

        /* Resolve an instance method through a generic parameter's exact
         * object-spec constraint.  The selected requirement remains a spec
         * callable, while the caller-view subject stays as the open type
         * parameter so the reifiable dependency can be closed later. */
        if (owner_type_decl == NULL &&
            owner_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
            owner_type.type_ref != NULL &&
            owner_type.type_ref->kind == FENG_TYPE_REF_NAMED &&
            owner_type.type_ref->as.named.segment_count == 1U &&
            owner_type.type_ref->as.named.type_arg_count == 0U) {
            const TypeParamEntry *type_param = find_type_param(
                context, owner_type.type_ref->as.named.segments[0]);
            const FengTypeRef *constraint_ref =
                type_param != NULL && type_param->type_param != NULL
                    ? type_param->type_param->constraint
                    : NULL;
            const FengDecl *constraint_decl =
                resolve_type_ref_decl(context, constraint_ref);

            if (constraint_decl != NULL &&
                constraint_decl->kind == FENG_DECL_SPEC &&
                constraint_decl->as.spec_decl.form == FENG_SPEC_FORM_OBJECT) {
                InferredExprType constraint_owner =
                    inferred_expr_type_from_type_ref(constraint_ref);

                resolution = resolve_accessible_method_overload(
                    context,
                    constraint_decl,
                    find_decl_provider_module(context->analysis,
                                              constraint_decl),
                    constraint_owner,
                    callee->as.member.member,
                    expr->as.call.args,
                    expr->as.call.arg_count,
                    expr->as.call.has_explicit_type_args,
                    (const FengTypeRef *const *)
                        expr->as.call.explicit_type_args,
                    expr->as.call.explicit_type_arg_count);
                if (resolution.kind ==
                    FENG_FUNCTION_CALL_RESOLUTION_UNIQUE) {
                    if (!validate_borrowed_data_pointer_call_arguments(
                            context,
                            callee,
                            expr->as.call.args,
                            expr->as.call.arg_count,
                            resolution.callable->params,
                            resolution.callable->param_count,
                            false)) {
                        return false;
                    }
                    note_callable_exception_escape(
                        context, resolution.callable);
                    materialize_callable_type_param_constraint_witnesses(
                        context,
                        expr,
                        resolution.callable,
                        resolution.owner_type_decl,
                        NULL,
                        resolution.owner_instance_type_ref != NULL
                            ? inferred_expr_type_from_type_ref(
                                  resolution.owner_instance_type_ref)
                            : constraint_owner);
                    if (!record_resolved_callable_from_resolution(
                            context,
                            expr,
                            &resolution,
                            resolution.owner_instance_type_ref)) {
                        return false;
                    }
                    record_object_arg_coercion_sites_for_resolved_call(
                        context,
                        expr,
                        resolution.callable,
                        resolution.owner_type_decl,
                        resolution.owner_instance_type_ref != NULL
                            ? inferred_expr_type_from_type_ref(
                                  resolution.owner_instance_type_ref)
                            : constraint_owner);
                    commit_literal_arg_adaptations_for_resolved_call(
                        context,
                        expr->as.call.args,
                        expr->as.call.arg_count,
                        resolution.callable,
                        resolution.owner_type_decl,
                        NULL,
                        resolution.owner_instance_type_ref != NULL
                            ? inferred_expr_type_from_type_ref(
                                  resolution.owner_instance_type_ref)
                            : constraint_owner);
                    return true;
                }
            }
        }

        if (owner_type_decl == NULL) {
            resolution = resolve_accessible_method_overload(context,
                                                            NULL,
                                                            NULL,
                                                            owner_type,
                                                            callee->as.member.member,
                                                            expr->as.call.args,
                                                            expr->as.call.arg_count,
                                                            expr->as.call.has_explicit_type_args,
                                                            (const FengTypeRef *const *)expr->as.call.explicit_type_args,
                                                            expr->as.call.explicit_type_arg_count);

            if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE) {
                if (!validate_borrowed_data_pointer_call_arguments(context,
                                                                   callee,
                                                                   expr->as.call.args,
                                                                   expr->as.call.arg_count,
                                                                   resolution.callable->params,
                                                                   resolution.callable->param_count,
                                                                   false)) {
                    return false;
                }
                note_callable_exception_escape(context, resolution.callable);
                materialize_callable_type_param_constraint_witnesses(context,
                                                                    expr,
                                                                    resolution.callable,
                                                                    NULL,
                                                                    resolution.fit_decl,
                                                                    owner_type);
                if (!record_resolved_callable_from_resolution(
                        context, expr, &resolution, owner_type.type_ref)) {
                    return false;
                }
                record_object_arg_coercion_sites_for_resolved_call(
                    context,
                    expr,
                    resolution.callable,
                    NULL,
                    owner_type);
                commit_literal_arg_adaptations_for_resolved_call(
                    context,
                    expr->as.call.args,
                    expr->as.call.arg_count,
                    resolution.callable,
                    NULL,
                    resolution.fit_decl,
                    owner_type);
                return true;
            }
            if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_AMBIGUOUS) {
                char *owner_name = format_inferred_expr_type_name(owner_type, context->pointer_size);
                bool ok = resolver_append_error(
                    context,
                    callee->token,
                    "AE0511", format_message("method '%s.%.*s' has multiple overloads matching %zu argument(s); argument types are ambiguous",
                                   owner_name != NULL ? owner_name : "<type>",
                                   (int)callee->as.member.member.length,
                                   callee->as.member.member.data,
                                   expr->as.call.arg_count));
                free(owner_name);
                return ok;
            }
            if (resolution.prepacked_variadic_rejection !=
                FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
                return report_prepacked_variadic_rejection(
                    context, callee, resolution.prepacked_variadic_rejection);
            }
            if (resolution.rejected_existing_array_for_variadic) {
                return report_existing_array_rejected_for_variadic_call(context, callee);
            }
        }

        return validate_callable_typed_expr_call(context,
                                                 callee,
                                                 expr->as.call.args,
                                                 expr->as.call.arg_count);
    }

    if (callee->kind == FENG_EXPR_IDENTIFIER) {
        if (resolver_find_local_name_entry(context, callee->as.identifier) != NULL) {
            return validate_callable_typed_expr_call(context,
                                                     callee,
                                                     expr->as.call.args,
                                                     expr->as.call.arg_count);
        }

        {
            const FunctionOverloadSetEntry *overload_set =
                find_function_overload_set(context->function_sets,
                                           context->function_set_count,
                                           callee->as.identifier);

            if (overload_set != NULL) {
                /* 惰性歧义检测(规范 §7.1):裸名 func 引用前先做跨来源歧义
                 * 检测(import vs import / import vs 本模块)。覆盖第 1/2/3
                 * 类场景。func 重载决议(第 5 类)由后续路径处理。 */
                if (!report_name_ambiguity_if_any(context,
                                                   callee->token,
                                                   callee->as.identifier,
                                                   SYMBOL_LOOKUP_VALUE)) {
                    return false;
                }

                FunctionCallResolution resolution =
                    resolve_top_level_function_overload(context,
                                                        overload_set,
                                                        expr->as.call.args,
                                                        expr->as.call.arg_count,
                                                        expr->as.call.has_explicit_type_args,
                                                        (const FengTypeRef *const *)expr->as.call.explicit_type_args,
                                                        expr->as.call.explicit_type_arg_count);

                if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_UNIQUE) {
                    if (!validate_borrowed_data_pointer_call_arguments(
                            context,
                            callee,
                            expr->as.call.args,
                            expr->as.call.arg_count,
                            resolution.callable->params,
                            resolution.callable->param_count,
                            resolution.decl != NULL && resolution.decl->is_extern)) {
                        return false;
                    }
                    note_callable_exception_escape(context, resolution.callable);
                    materialize_callable_type_param_constraint_witnesses(context,
                                                                        expr,
                                                                        resolution.callable,
                                                                        NULL,
                                                                        NULL,
                                                                        inferred_expr_type_unknown());
                    if (!record_resolved_callable_from_resolution(
                            context, expr, &resolution, NULL)) {
                        return false;
                    }
                    record_object_arg_coercion_sites_for_resolved_call(
                        context,
                        expr,
                        resolution.callable,
                        NULL,
                        inferred_expr_type_unknown());
                    commit_literal_arg_adaptations_for_resolved_call(
                        context,
                        expr->as.call.args,
                        expr->as.call.arg_count,
                        resolution.callable,
                        NULL,
                        NULL,
                        inferred_expr_type_unknown());
                    return true;
                }
                if (resolution.kind == FENG_FUNCTION_CALL_RESOLUTION_AMBIGUOUS) {
                    return resolver_append_error(
                        context,
                        callee->token,
                        "AE0511", format_message("top-level function '%.*s' has multiple overloads matching %zu argument(s); argument types are ambiguous",
                                       (int)callee->as.identifier.length,
                                       callee->as.identifier.data,
                                       expr->as.call.arg_count));
                }

                if (resolution.prepacked_variadic_rejection !=
                    FENG_PREPACKED_VARIADIC_REJECTION_NONE) {
                    return report_prepacked_variadic_rejection(
                        context, callee, resolution.prepacked_variadic_rejection);
                }
                if (resolution.rejected_existing_array_for_variadic) {
                    return report_existing_array_rejected_for_variadic_call(context, callee);
                }

                return resolver_append_error(
                    context,
                    callee->token,
                    "AE0512", format_message("top-level function '%.*s' has no overload accepting %zu argument(s)",
                                   (int)callee->as.identifier.length,
                                   callee->as.identifier.data,
                                   expr->as.call.arg_count));
            }
        }

        return validate_callable_typed_expr_call(context,
                                                 callee,
                                                 expr->as.call.args,
                                                 expr->as.call.arg_count);
    }

    return validate_callable_typed_expr_call(context,
                                             callee,
                                             expr->as.call.args,
                                             expr->as.call.arg_count);
}

static bool validate_object_literal_expr(ResolveContext *context, const FengExpr *expr) {
    ResolvedTypeTarget target;
    const FengTypeMember *constructor_member = NULL;
    char *target_name;
    FengSlice *seen_field_names = NULL;
    size_t seen_field_count = 0U;
    size_t seen_field_capacity = 0U;
    size_t field_index;

    target = resolve_type_target_expr(context, expr->as.object_literal.target, true);
    target_name = format_expr_target_name(expr->as.object_literal.target);

    /* A call-form target has already been checked by the nested call. When
     * its known type is not an object, retain that single root diagnostic at
     * the type target instead of adding a derived object-literal diagnostic. */
    if (!decl_is_object_form_type(target.type_decl) &&
        expr->as.object_literal.target->kind == FENG_EXPR_CALL &&
        target.type_decl != NULL) {
        free(target_name);
        free(seen_field_names);
        return true;
    }

    if (!decl_is_object_form_type(target.type_decl)) {
        bool ok = resolver_append_error(
            context,
            expr->token,
            "AE1004", format_message("object literal target '%s' must resolve to an object type",
                           target_name != NULL ? target_name : "<expression>"));

        free(target_name);
        free(seen_field_names);
        return ok;
    }

    if (expr->as.object_literal.target->kind != FENG_EXPR_CALL) {
        if (!validate_constructor_invocation(context,
                                             expr->as.object_literal.target,
                                             target.type_decl,
                                             target.provider_module,
                                             NULL,
                                             0U,
                                             NULL,
                                             0U,
                                             &constructor_member)) {
            free(target_name);
            free(seen_field_names);
            return false;
        }
        if (!validate_construction_default_zero_requirements(
                context,
                expr->as.object_literal.target,
                target.type_decl,
                resolved_type_target_owner_type(&target))) {
            free(target_name);
            free(seen_field_names);
            return false;
        }
    } else if (expr->as.object_literal.target->as.call.resolved_callable.kind ==
                   FENG_RESOLVED_CALLABLE_TYPE_CONSTRUCTOR) {
        constructor_member =
            expr->as.object_literal.target->as.call.resolved_callable.member;
    }

    /* Preserve semantic overload and visibility resolution for codegen.
     * Direct `Type { ... }` targets have no call node on which to store the
     * selected zero-argument constructor. */
    ((FengExpr *)expr)->as.object_literal.resolved_constructor =
        constructor_member;

    for (field_index = 0U; field_index < expr->as.object_literal.field_count; ++field_index) {
        const FengObjectFieldInit *field = &expr->as.object_literal.fields[field_index];
        const FengTypeMember *field_member;

        if (find_slice_index(seen_field_names, seen_field_count, field->name) < seen_field_count) {
            bool ok = resolver_append_error(
                context,
                field->token,
                "AE1005", format_message("duplicate object literal field '%.*s' for type '%.*s'",
                               (int)field->name.length,
                               field->name.data,
                               (int)target.type_decl->as.type_decl.name.length,
                               target.type_decl->as.type_decl.name.data));

            free(target_name);
            free(seen_field_names);
            return ok;
        }
        if (!append_slice(&seen_field_names, &seen_field_count, &seen_field_capacity, field->name)) {
            free(target_name);
            free(seen_field_names);
            return false;
        }

        field_member = find_type_field_member(target.type_decl, field->name);
        if (field_member == NULL) {
            bool ok = resolver_append_error(
                context,
                field->token,
                "AE1006", format_message("object literal field '%.*s' is not a field of type '%.*s'",
                               (int)field->name.length,
                               field->name.data,
                               (int)target.type_decl->as.type_decl.name.length,
                               target.type_decl->as.type_decl.name.data));

            free(target_name);
            free(seen_field_names);
            return ok;
        }

        if (!type_member_is_accessible_from(
                context,
                target.type_decl,
                resolved_type_target_owner_type(&target),
                field_member) ||
            fit_body_blocks_private_access(context, target.type_decl, field_member)) {
            bool ok = resolver_append_error(
                context,
                field->token,
                "AE1007", format_message("object literal field '%.*s' is not accessible for type '%.*s'",
                               (int)field->name.length,
                               field->name.data,
                               (int)target.type_decl->as.type_decl.name.length,
                               target.type_decl->as.type_decl.name.data));

            free(target_name);
            free(seen_field_names);
            return ok;
        }

        if (!record_selected_friend_fit_access(
                context,
                target.type_decl,
                resolved_type_target_owner_type(&target),
                field_member)) {
            free(target_name);
            free(seen_field_names);
            return false;
        }

        if (!validate_let_field_object_literal_binding(context,
                                                       target.type_decl,
                                                       target.provider_module,
                                                       expr->as.object_literal.target,
                                                       field)) {
            free(target_name);
            free(seen_field_names);
            return false;
        }
    }

    free(target_name);
    free(seen_field_names);
    return true;
}

static bool resolve_self_member_expr(ResolveContext *context,
                                     const FengExpr *expr,
                                     bool allow_self) {
    if (expr->kind != FENG_EXPR_MEMBER || expr->as.member.object == NULL ||
        expr->as.member.object->kind != FENG_EXPR_SELF) {
        return false;
    }

    if (!allow_self || context->current_type_decl == NULL) {
        if (allow_self && context->current_type_decl == NULL &&
            context->current_fit_target_type_ref != NULL &&
            find_fit_method_member_for_owner_type(
                context,
                NULL,
                inferred_expr_type_from_fit_target_type_ref(
                    context->current_fit_target_type_ref),
                expr->as.member.member) != NULL) {
            if (context->lambda_frame_count > 0U) {
                resolver_record_self_capture(context);
            }
            return true;
        }
        return resolve_expr(context, expr->as.member.object, allow_self);
    }

    if (context->lambda_frame_count > 0U) {
        resolver_record_self_capture(context);
    }

    if (find_instance_member(context->current_type_decl, expr->as.member.member) != NULL) {
        const FengTypeMember *self_member =
            find_instance_member(context->current_type_decl, expr->as.member.member);

        if (fit_body_blocks_private_access(context, context->current_type_decl, self_member)) {
            return resolver_append_error(
                context,
                expr->token,
                "AE0307", format_message("fit body cannot access private member '%.*s' of target type '%.*s'",
                               self_member->kind == FENG_TYPE_MEMBER_FIELD
                                   ? (int)self_member->as.field.name.length
                                   : (int)self_member->as.callable.name.length,
                               self_member->kind == FENG_TYPE_MEMBER_FIELD
                                   ? self_member->as.field.name.data
                                   : self_member->as.callable.name.data,
                               (int)context->current_type_decl->as.type_decl.name.length,
                               context->current_type_decl->as.type_decl.name.data));
        }
        return true;
    }

    if (find_fit_method_member_for_type(context, context->current_type_decl,
                                        expr->as.member.member) != NULL) {
        return true;
    }

    return resolver_append_error(
        context,
        expr->token,
        "AE0306", format_message("type '%.*s' has no member '%.*s'",
                       context->current_type_decl != NULL ? (int)context->current_type_decl->as.type_decl.name.length
                                                         : 0,
                       context->current_type_decl != NULL ? context->current_type_decl->as.type_decl.name.data : "",
                       (int)expr->as.member.member.length,
                       expr->as.member.member.data));
}

static bool append_error(FengSemanticError **errors,
                         size_t *error_count,
                         size_t *error_capacity,
                         const char *path,
                         FengToken token,
                         const char *code,
                         char *message) {
    FengSemanticError error;

    memset(&error, 0, sizeof(error));

    if (message == NULL) {
        code = "IE0001";
        message = duplicate_cstr("out of memory during semantic analysis");
        if (message == NULL) {
            return false;
        }
    }

    error.code = code;
    error.path = path;
    error.message = message;
    error.token = token;

    if (!append_raw((void **)errors,
                    error_count,
                    error_capacity,
                    sizeof(error),
                    &error)) {
        free(message);
        return false;
    }

    return true;
}

/* Attach one owned secondary source location to the most recent error. */
static bool append_latest_error_related_location(
    FengSemanticError *errors,
    size_t error_count,
    const char *path,
    FengToken token,
    char *message) {
    FengSemanticError *error;
    FengSemanticRelatedLocation *grown;
    FengSemanticRelatedLocation related;

    if (message == NULL) {
        return false;
    }
    if (errors == NULL || error_count == 0U) {
        free(message);
        return false;
    }
    error = &errors[error_count - 1U];
    grown = (FengSemanticRelatedLocation *)realloc(
        error->related_locations,
        (error->related_location_count + 1U) * sizeof(*grown));
    if (grown == NULL) {
        free(message);
        return false;
    }
    related.token = token;
    related.path = path;
    related.message = message;
    error->related_locations = grown;
    error->related_locations[error->related_location_count++] = related;
    return true;
}

static bool analysis_append_info(const FengSemanticAnalysis *analysis_const,
                                 const char *path,
                                 FengToken token,
                                 char *message) {
    FengSemanticAnalysis *analysis;
    FengSemanticInfo info;

    if (analysis_const == NULL) {
        free(message);
        return true;
    }
    analysis = (FengSemanticAnalysis *)analysis_const;
    if (message == NULL) {
        message = duplicate_cstr("out of memory during semantic analysis");
        if (message == NULL) {
            return false;
        }
    }
    info.path = path;
    info.message = message;
    info.token = token;
    if (!append_raw((void **)&analysis->infos,
                    &analysis->info_count,
                    &analysis->info_capacity,
                    sizeof(info),
                    &info)) {
        free(message);
        return false;
    }
    return true;
}

static bool append_module_program(FengSemanticModule *module, const FengProgram *program) {
    return append_raw((void **)&module->programs,
                      &module->program_count,
                      &module->program_capacity,
                      sizeof(module->programs[0]),
                      &program);
}

static bool add_module(FengSemanticAnalysis *analysis, const FengProgram *program) {
    FengSemanticModule module;

    memset(&module, 0, sizeof(module));
    module.segments = program->module_segments;
    module.segment_count = program->module_segment_count;
    module.visibility = program->module_visibility;

    if (!append_module_program(&module, program)) {
        free(module.programs);
        return false;
    }

    if (!append_raw((void **)&analysis->modules,
                    &analysis->module_count,
                    &analysis->module_capacity,
                    sizeof(module),
                    &module)) {
        free(module.programs);
        return false;
    }

    return true;
}

static bool import_public_names(const FengSemanticModule *target_module,
                                VisibleTypeEntry **visible_types,
                                size_t *visible_type_count,
                                size_t *visible_type_capacity,
                                VisibleValueEntry **visible_values,
                                size_t *visible_value_count,
                                size_t *visible_value_capacity,
                                FunctionOverloadSetEntry **function_sets,
                                size_t *function_set_count,
                                size_t *function_set_capacity) {
    FengSlice *seen_value_names = NULL;
    size_t seen_value_count = 0U;
    size_t seen_value_capacity = 0U;
    size_t program_index;
    bool ok = true;

    for (program_index = 0U; program_index < target_module->program_count && ok; ++program_index) {
        const FengProgram *target_program = target_module->programs[program_index];
        size_t decl_index;

        for (decl_index = 0U; decl_index < target_program->declaration_count && ok; ++decl_index) {
            const FengDecl *decl = target_program->declarations[decl_index];
            FengSlice name;
            size_t index;

            if (!decl_is_public(decl)) {
                continue;
            }

            switch (decl->kind) {
                case FENG_DECL_TYPE: {
                    VisibleTypeEntry entry;
                    FengOverloadCategory category = decl_overload_category(decl);
                    size_t arity = decl->as.type_decl.type_param_count;

                    name = decl->as.type_decl.name;
                    /* Dedup: find_visible_type_index checks (name, category, arity)
                     * in visible_types — already-registered entries are found immediately,
                     * replacing the separate seen_type_names dedup array. */
                    index = find_visible_type_index(*visible_types, *visible_type_count,
                                                    name, category, arity);
                    if (index < *visible_type_count) {
                        /* import_public_names 不做冲突检查(规范 §7.1 惰性碰撞)。
                         * 同名候选的惰性歧义检测由 collect_symbol_candidates +
                         * report_name_ambiguity_if_any 在使用点处理。 */
                        break;
                    }

                    entry.name = name;
                    entry.provider_module = target_module;
                    entry.provider_program = target_program;
                    entry.decl = decl;
                    ok = append_raw((void **)visible_types,
                                    visible_type_count,
                                    visible_type_capacity,
                                    sizeof(entry),
                                    &entry);
                    break;
                }

                case FENG_DECL_ENUM: {
                    VisibleTypeEntry entry;

                    name = decl->as.enum_decl.name;
                    /* NO_OVERLOADING: arity=0, name-only dedup via find_visible_type_index */
                    index = find_visible_type_index(*visible_types, *visible_type_count,
                                                    name, FENG_OVERLOAD_CATEGORY_NO_OVERLOADING, 0U);
                    if (index < *visible_type_count) {
                        /* import_public_names 不做冲突检查(规范 §7.1 惰性碰撞)。
                         * 同名候选的惰性歧义检测由 collect_symbol_candidates +
                         * report_name_ambiguity_if_any 在使用点处理。 */
                        break;
                    }

                    entry.name = name;
                    entry.provider_module = target_module;
                    entry.provider_program = target_program;
                    entry.decl = decl;
                    ok = append_raw((void **)visible_types,
                                    visible_type_count,
                                    visible_type_capacity,
                                    sizeof(entry),
                                    &entry);
                    break;
                }

                case FENG_DECL_GLOBAL_BINDING:
                case FENG_DECL_FUNCTION: {
                    VisibleValueEntry entry;
                    bool should_append_visible_value = true;
                    bool value_is_visible_from_target = false;

                    name = (decl->kind == FENG_DECL_FUNCTION) ? decl->as.function_decl.name : decl->as.binding.name;
                    if (find_slice_index(seen_value_names, seen_value_count, name) < seen_value_count) {
                        should_append_visible_value = false;
                    }
                    if (should_append_visible_value &&
                        !append_slice(&seen_value_names, &seen_value_count, &seen_value_capacity, name)) {
                        ok = false;
                        break;
                    }

                    if (should_append_visible_value) {
                        index = find_visible_value_index(*visible_values, *visible_value_count, name);
                        if (index < *visible_value_count) {
                            /* import_public_names 不做冲突检查(规范 §7.1 惰性碰撞)。
                             * 同名候选的惰性歧义检测由 collect_symbol_candidates +
                             * report_name_ambiguity_if_any 在使用点处理。
                             *
                             * 注意:value_is_visible_from_target 用于决定是否
                             * 为 target_module 的同名 func 追加重载集成员。
                             * 若 visible_values 中已有同名条目,说明是其他模块
                             * 已加入(可能是本模块或更早 import 的模块);此时
                             * 不重复添加 visible_value,但若现有条目恰好来自
                             * target_module,则视为本 import 已可见,需追加重载
                             * 集成员(场景:同一模块多个 program 各定义同名
                             * public func,作为重载集合)。 */
                            if ((*visible_values)[index].provider_module == target_module) {
                                value_is_visible_from_target = true;
                                should_append_visible_value = false;
                            } else {
                                should_append_visible_value = false;
                            }
                        }
                    }

                    if (!should_append_visible_value && decl->kind == FENG_DECL_FUNCTION) {
                        index = find_visible_value_index(*visible_values, *visible_value_count, name);
                        value_is_visible_from_target =
                            (index < *visible_value_count &&
                             (*visible_values)[index].provider_module == target_module);
                    }

                    if (should_append_visible_value) {
                        entry.name = name;
                        entry.provider_module = target_module;
                        entry.provider_program = target_program;
                        entry.decl = decl;
                        entry.mutability = decl->kind == FENG_DECL_GLOBAL_BINDING
                                               ? decl->as.binding.mutability
                                               : FENG_MUTABILITY_DEFAULT;
                        entry.is_function = (decl->kind == FENG_DECL_FUNCTION);
                        ok = append_raw((void **)visible_values,
                                        visible_value_count,
                                        visible_value_capacity,
                                        sizeof(entry),
                                        &entry);
                        if (!ok) {
                            break;
                        }
                        value_is_visible_from_target = true;
                    }

                    if (decl->kind == FENG_DECL_FUNCTION && value_is_visible_from_target) {
                        ok = append_visible_function_overload(function_sets,
                                                              function_set_count,
                                                              function_set_capacity,
                                                              target_module,
                                                              decl);
                    }
                    break;
                }

                case FENG_DECL_SPEC: {
                    VisibleTypeEntry entry;
                    FengOverloadCategory category = decl_overload_category(decl);
                    size_t arity = decl->as.spec_decl.type_param_count;

                    name = decl->as.spec_decl.name;
                    index = find_visible_type_index(*visible_types, *visible_type_count,
                                                    name, category, arity);
                    if (index < *visible_type_count) {
                        /* import_public_names 不做冲突检查(规范 §7.1 惰性碰撞)。
                         * 同名候选的惰性歧义检测由 collect_symbol_candidates +
                         * report_name_ambiguity_if_any 在使用点处理。 */
                        break;
                    }

                    entry.name = name;
                    entry.provider_module = target_module;
                    entry.provider_program = target_program;
                    entry.decl = decl;
                    ok = append_raw((void **)visible_types,
                                    visible_type_count,
                                    visible_type_capacity,
                                    sizeof(entry),
                                    &entry);
                    break;
                }

                case FENG_DECL_FIT:
                    /* fit declarations are not exported as named symbols. */
                    break;
            }
        }
    }

    free(seen_value_names);
    return ok;
}

static bool build_program_aliases(const FengSemanticAnalysis *analysis,
                                  const FengProgram *program,
                                  AliasEntry **aliases,
                                  size_t *alias_count,
                                  size_t *alias_capacity) {
    size_t use_index;

    for (use_index = 0U; use_index < program->use_count; ++use_index) {
        const FengUseDecl *use_decl = &program->uses[use_index];
        size_t target_index;
        AliasEntry entry;

        if (!use_decl->has_alias) {
            continue;
        }
        if (find_alias_index(*aliases, *alias_count, use_decl->alias) < *alias_count) {
            continue;
        }

        target_index = find_module_index_by_path(analysis, use_decl->segments, use_decl->segment_count);
        if (target_index == analysis->module_count) {
            continue;
        }

        entry.alias = use_decl->alias;
        entry.target_module = &analysis->modules[target_index];
        entry.use_decl = use_decl;
        if (!append_raw((void **)aliases,
                        alias_count,
                        alias_capacity,
                        sizeof(entry),
                        &entry)) {
            return false;
        }
    }

    return true;
}

/* Find the semantic module that owns one source program. */
static const FengSemanticModule *find_program_provider_module(
    const FengSemanticAnalysis *analysis,
    const FengProgram *program) {
    if (analysis == NULL || program == NULL) {
        return NULL;
    }
    for (size_t module_index = 0U;
         module_index < analysis->module_count;
         ++module_index) {
        const FengSemanticModule *module = &analysis->modules[module_index];

        for (size_t program_index = 0U;
             program_index < module->program_count;
             ++program_index) {
            if (module->programs[program_index] == program) {
                return module;
            }
        }
    }
    return NULL;
}

/* Append one declaration to the minimal type environment used by the public
 * @friend query. Successfully analyzed programs already guarantee that a
 * duplicate (name, arity) is either the same declaration or unambiguous. */
static bool append_friend_query_visible_type(
    VisibleTypeEntry **entries,
    size_t *count,
    size_t *capacity,
    const FengSemanticModule *provider_module,
    const FengProgram *provider_program,
    const FengDecl *decl) {
    VisibleTypeEntry entry;
    FengSlice name;
    size_t arity;

    if (decl == NULL ||
        (decl->kind != FENG_DECL_TYPE && decl->kind != FENG_DECL_ENUM &&
         decl->kind != FENG_DECL_SPEC)) {
        return true;
    }
    if (decl->kind == FENG_DECL_TYPE) {
        name = decl->as.type_decl.name;
        arity = decl->as.type_decl.type_param_count;
    } else if (decl->kind == FENG_DECL_SPEC) {
        name = decl->as.spec_decl.name;
        arity = decl->as.spec_decl.type_param_count;
    } else {
        name = decl->as.enum_decl.name;
        arity = 0U;
    }
    if (find_visible_type(*entries, *count, name, arity) != NULL) {
        return true;
    }
    entry.name = name;
    entry.provider_module = provider_module;
    entry.provider_program = provider_program;
    entry.decl = decl;
    return append_raw((void **)entries,
                      count,
                      capacity,
                      sizeof(entry),
                      &entry);
}

/* Build only the type-name portion of a program's ordinary resolver
 * environment. It is sufficient for materializing generic @friend subjects
 * and owner arguments, and does not rerun declarations or executable code. */
static bool build_friend_query_visible_types(
    const FengSemanticAnalysis *analysis,
    const FengSemanticModule *module,
    const FengProgram *program,
    VisibleTypeEntry **out_entries,
    size_t *out_count) {
    VisibleTypeEntry *entries = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    bool ok = true;

    if (analysis == NULL || module == NULL || program == NULL ||
        out_entries == NULL || out_count == NULL) {
        return false;
    }
    for (size_t program_index = 0U;
         program_index < module->program_count && ok;
         ++program_index) {
        const FengProgram *provider_program = module->programs[program_index];

        for (size_t decl_index = 0U;
             decl_index < provider_program->declaration_count && ok;
             ++decl_index) {
            ok = append_friend_query_visible_type(
                &entries,
                &count,
                &capacity,
                module,
                provider_program,
                provider_program->declarations[decl_index]);
        }
    }
    for (size_t use_index = 0U;
         use_index < program->use_count && ok;
         ++use_index) {
        const FengUseDecl *use_decl = &program->uses[use_index];
        size_t target_index;

        if (use_decl->has_alias) {
            continue;
        }
        target_index = find_module_index_by_path(
            analysis, use_decl->segments, use_decl->segment_count);
        if (target_index == analysis->module_count) {
            continue;
        }
        {
            const FengSemanticModule *target = &analysis->modules[target_index];

            for (size_t program_index = 0U;
                 program_index < target->program_count && ok;
                 ++program_index) {
                const FengProgram *provider_program =
                    target->programs[program_index];

                for (size_t decl_index = 0U;
                     decl_index < provider_program->declaration_count && ok;
                     ++decl_index) {
                    const FengDecl *decl =
                        provider_program->declarations[decl_index];

                    if (!decl_is_public(decl)) {
                        continue;
                    }
                    ok = append_friend_query_visible_type(
                        &entries,
                        &count,
                        &capacity,
                        target,
                        provider_program,
                        decl);
                }
            }
        }
    }
    if (!ok) {
        free(entries);
        return false;
    }
    *out_entries = entries;
    *out_count = count;
    return true;
}

/* Build the imported-module facts for read-only file type queries, including
 * @friend tooling and closed binding types consumed from another file. */
static bool build_friend_query_imported_modules(
    const FengSemanticAnalysis *analysis,
    const FengProgram *program,
    ImportedModuleEntry **out_entries,
    size_t *out_count) {
    ImportedModuleEntry *entries = NULL;
    size_t count = 0U;
    size_t capacity = 0U;

    if (analysis == NULL || program == NULL || out_entries == NULL ||
        out_count == NULL) {
        return false;
    }
    for (size_t use_index = 0U; use_index < program->use_count; ++use_index) {
        const FengUseDecl *use_decl = &program->uses[use_index];
        size_t target_index = find_module_index_by_path(
            analysis, use_decl->segments, use_decl->segment_count);
        ImportedModuleEntry entry;

        if (target_index == analysis->module_count) {
            continue;
        }
        entry.target_module = &analysis->modules[target_index];
        if (!append_raw((void **)&entries,
                        &count,
                        &capacity,
                        sizeof(entry),
                        &entry)) {
            free(entries);
            return false;
        }
    }
    *out_entries = entries;
    *out_count = count;
    return true;
}

/* Reconstruct only a closed type's declaring file namespace. Executable
 * scopes and consumer type parameters cannot participate in this lookup. */
static const FengDecl *resolve_type_ref_decl_in_program(
    const ResolveContext *context,
    const FengTypeRef *type_ref) {
    const FengProgram *program = type_ref->resolution_program;
    const FengSemanticModule *module = find_program_provider_module(context->analysis, program);
    VisibleTypeEntry *visible_types = NULL;
    size_t visible_type_count = 0U;
    AliasEntry *aliases = NULL;
    size_t alias_count = 0U;
    size_t alias_capacity = 0U;
    ImportedModuleEntry *imported_modules = NULL;
    size_t imported_module_count = 0U;
    ResolveContext source = {0};
    const FengDecl *decl = NULL;

    if (module != NULL &&
        build_friend_query_visible_types(context->analysis, module, program,
                                          &visible_types, &visible_type_count) &&
        build_program_aliases(context->analysis, program, &aliases,
                               &alias_count, &alias_capacity) &&
        build_friend_query_imported_modules(context->analysis, program,
                                             &imported_modules, &imported_module_count)) {
        source.analysis = context->analysis;
        source.module = module;
        source.program = program;
        source.pointer_size = context->pointer_size;
        source.visible_types = visible_types;
        source.visible_type_count = visible_type_count;
        source.aliases = aliases;
        source.alias_count = alias_count;
        source.imported_modules = imported_modules;
        source.imported_module_count = imported_module_count;
        decl = find_named_type_decl(&source, type_ref->as.named.segments,
                                     type_ref->as.named.segment_count,
                                     type_ref->as.named.type_arg_count);
    }
    free(visible_types);
    free(aliases);
    free(imported_modules);
    return decl;
}

/* Release scratch type references created while projecting generic parent
 * specs during the public @friend query. */
static void free_friend_query_synthetic_type_refs(ResolveContext *context) {
    if (context == NULL) {
        return;
    }
    for (size_t index = 0U;
         index < context->synthetic_type_ref_count;
         ++index) {
        free_synthetic_type_ref(context->synthetic_type_refs[index]);
    }
    free(context->synthetic_type_refs);
    context->synthetic_type_refs = NULL;
    context->synthetic_type_ref_count = 0U;
    context->synthetic_type_ref_capacity = 0U;
}

/* Reuse the compiler's normalized @friend predicate for source tooling.
 * The enclosing member identifies a concrete type implementation context or
 * a fit method. The temporary resolver context contains only immutable lookup
 * facts; the query never records a fit access, emits diagnostics, or changes
 * analysis. */
bool feng_semantic_member_has_friend_access(
    const FengSemanticAnalysis *analysis,
    const FengProgram *program,
    const FengDecl *access_owner_decl,
    const FengTypeRef *owner_instance_type_ref,
    const FengTypeMember *member,
    const FengDecl *enclosing_decl,
    const FengTypeMember *enclosing_member) {
    const FengSemanticModule *module;
    const struct FengFriendMemberInfo *info;
    VisibleTypeEntry *visible_types = NULL;
    size_t visible_type_count = 0U;
    AliasEntry *aliases = NULL;
    size_t alias_count = 0U;
    size_t alias_capacity = 0U;
    ImportedModuleEntry *imported_modules = NULL;
    size_t imported_module_count = 0U;
    ResolveContext context;
    const TypeParamEntry *previous_type_params = NULL;
    size_t previous_type_param_count = 0U;
    const FengDecl *fit_target_decl = NULL;
    InferredExprType owner_instance;
    bool scope_pushed = false;
    bool accessible = false;

    if (analysis == NULL || program == NULL || access_owner_decl == NULL ||
        member == NULL || enclosing_decl == NULL || enclosing_member == NULL ||
        member->visibility != FENG_VISIBILITY_PRIVATE) {
        return false;
    }
    info = find_friend_member_info(analysis, member);
    if (info == NULL || info->friend_type_count == 0U) {
        return false;
    }
    module = find_program_provider_module(analysis, program);
    if (module == NULL ||
        !build_friend_query_visible_types(analysis,
                                          module,
                                          program,
                                          &visible_types,
                                          &visible_type_count) ||
        !build_program_aliases(analysis,
                               program,
                               &aliases,
                               &alias_count,
                               &alias_capacity) ||
        !build_friend_query_imported_modules(analysis,
                                             program,
                                             &imported_modules,
                                             &imported_module_count)) {
        free(visible_types);
        free(aliases);
        free(imported_modules);
        return false;
    }

    memset(&context, 0, sizeof(context));
    context.analysis = analysis;
    context.module = module;
    context.program = program;
    context.pointer_size = analysis->pointer_size;
    context.visible_types = visible_types;
    context.visible_type_count = visible_type_count;
    context.aliases = aliases;
    context.alias_count = alias_count;
    context.imported_modules = imported_modules;
    context.imported_module_count = imported_module_count;
    context.current_callable_member = enclosing_member;

    if (enclosing_decl->kind == FENG_DECL_TYPE) {
        context.current_type_decl = enclosing_decl;
        context.current_type_implementation_owner = enclosing_decl;
        scope_pushed = resolver_push_type_params(
            &context,
            enclosing_decl->as.type_decl.type_params,
            enclosing_decl->as.type_decl.type_param_count,
            &previous_type_params,
            &previous_type_param_count);
    } else if (enclosing_decl->kind == FENG_DECL_FIT) {
        if (enclosing_member->kind != FENG_TYPE_MEMBER_METHOD) {
            free(visible_types);
            free(aliases);
            free(imported_modules);
            return false;
        }
        context.current_fit_decl = enclosing_decl;
        context.current_fit_target_type_ref = enclosing_decl->as.fit_decl.target;
        fit_target_decl = resolve_type_ref_decl(
            &context, enclosing_decl->as.fit_decl.target);
        if (fit_target_decl != NULL &&
            fit_target_decl->kind == FENG_DECL_TYPE) {
            scope_pushed = resolver_push_type_params(
                &context,
                fit_target_decl->as.type_decl.type_params,
                fit_target_decl->as.type_decl.type_param_count,
                &previous_type_params,
                &previous_type_param_count);
        }
    }

    if ((enclosing_decl->kind == FENG_DECL_TYPE || fit_target_decl != NULL) &&
        (scope_pushed ||
         (enclosing_decl->kind == FENG_DECL_TYPE
              ? enclosing_decl->as.type_decl.type_param_count == 0U
              : fit_target_decl->as.type_decl.type_param_count == 0U))) {
        memset(&owner_instance, 0, sizeof(owner_instance));
        if (owner_instance_type_ref != NULL) {
            owner_instance = inferred_expr_type_from_type_ref(
                owner_instance_type_ref);
            owner_instance.type_decl = access_owner_decl;
        } else {
            owner_instance.kind = FENG_INFERRED_EXPR_TYPE_DECL;
            owner_instance.type_decl = access_owner_decl;
        }
        accessible = friend_seal_member_is_accessible_from(
            &context, access_owner_decl, owner_instance, member);
        if (accessible && enclosing_decl->kind == FENG_DECL_FIT) {
            accessible = friend_member_signature_visible_from_module(
                info, module);
        }
    }

    if (scope_pushed) {
        resolver_pop_type_params(&context,
                                 previous_type_params,
                                 previous_type_param_count);
    }
    resolver_free_scopes(&context);
    free_friend_query_synthetic_type_refs(&context);
    free(visible_types);
    free(aliases);
    free(imported_modules);
    return accessible;
}

/* An alias is declared by this file, so only this file's own declarations
 * conflict eagerly. Other visible declarations are checked at each use. */
static bool validate_program_alias_conflicts(const FengProgram *program,
                                             FengSemanticError **errors,
                                             size_t *error_count,
                                             size_t *error_capacity) {
    size_t use_index;

    for (use_index = 0U; use_index < program->use_count; ++use_index) {
        const FengUseDecl *use_decl = &program->uses[use_index];
        const FengDecl *conflict_decl = NULL;
        char *module_name;
        char *message;

        if (!use_decl->has_alias) {
            continue;
        }

        for (size_t index = 0U; index < program->declaration_count; ++index) {
            FengSlice name;
            const FengDecl *decl = program->declarations[index];
            if (symbol_decl_name(decl, &name) && slice_equals(name, use_decl->alias)) {
                conflict_decl = decl;
                break;
            }
        }
        if (conflict_decl == NULL) {
            continue;
        }
        module_name = format_module_name(use_decl->segments, use_decl->segment_count);
        message = format_message(
            "name '%.*s' is already defined in this file, conflicts with import alias from module '%s'",
            (int)use_decl->alias.length, use_decl->alias.data,
            module_name != NULL ? module_name : "<unknown>");
        free(module_name);

        if (!append_error(errors,
                          error_count,
                          error_capacity,
                          program->path,
                          *decl_token(conflict_decl),
                          "AE0906",
                          message)) {
            return false;
        }
    }

    return true;
}

static bool resolve_type_ref(ResolveContext *context, const FengTypeRef *type_ref, bool allow_void);
static bool resolve_expr(ResolveContext *context, const FengExpr *expr, bool allow_self);
static bool resolve_stmt(ResolveContext *context, const FengStmt *stmt, bool allow_self);
static bool resolve_block_contents(ResolveContext *context,
                                   const FengBlock *block,
                                   bool allow_self);

static bool resolve_named_type_ref(ResolveContext *context,
                                   const FengTypeRef *type_ref,
                                   bool allow_void) {
    const FengSlice *segments = type_ref->as.named.segments;
    size_t segment_count = type_ref->as.named.segment_count;
    size_t type_arg_count = type_ref->as.named.type_arg_count;
    FengSlice name;
    char *qualified_name;

    if (segment_count == 0U) {
        return true;
    }

    name = segments[segment_count - 1U];

    /* G4-2: Single-segment name that matches an active type parameter.
     * Type parameters cannot take type arguments themselves. */
    if (segment_count == 1U && context->type_param_count > 0U &&
        find_type_param(context, name) != NULL) {
        if (type_arg_count > 0U) {
            return resolver_append_error(
                context,
                type_ref->token,
                "AE1012", format_message("type parameter '%.*s' cannot take type arguments",
                               (int)name.length, name.data));
        }
        return true;
    }

    /* G4-7: Type arguments present — resolve each arg and validate arity.
     * §6.4: Precise (name, arity) lookup; fallback distinguishes AE1013/1014/1015. */
    if (!validate_alias_name_reference(context, type_ref->token, segments[0])) {
        return false;
    }
    if (type_arg_count > 0U) {
        const FengDecl *base_decl;
        size_t i;
        bool ok;

        for (i = 0U; i < type_arg_count; ++i) {
            if (!resolve_type_ref(context, type_ref->as.named.type_args[i], false)) {
                return false;
            }
        }

        /* Precise lookup: (name, type_arg_count) */
        base_decl = find_named_type_decl(context, segments, segment_count, type_arg_count);
        if (base_decl == NULL) {
            const VisibleTypeEntry *any_entry = NULL;
            const FengDecl *any_decl = NULL;
            size_t expected_arity = 0U;

            /* Fallback: check if same-name type exists at any arity */
            if (segment_count == 1U) {
                any_entry = find_visible_type_any_arity(
                    context->visible_types, context->visible_type_count, name);
                if (any_entry != NULL) {
                    any_decl = any_entry->decl;
                }
            } else {
                /* Cross-module: any-arity existence check for error reporting */
                const FengSemanticModule *target_module = NULL;

                if (segment_count == 2U) {
                    const AliasEntry *mod_alias =
                        find_alias(context->aliases, context->alias_count, segments[0]);
                    if (mod_alias != NULL) {
                        target_module = mod_alias->target_module;
                    }
                }
                if (target_module == NULL) {
                    size_t mod_idx = find_module_index_by_path(
                        context->analysis, segments, segment_count - 1U);
                    if (mod_idx < context->analysis->module_count) {
                        target_module = &context->analysis->modules[mod_idx];
                    }
                }
                if (target_module != NULL) {
                    any_decl = find_module_public_type_decl_any_arity(
                        target_module, name);
                }
            }

            qualified_name = format_module_name(segments, segment_count);
            if (any_decl == NULL) {
                /* No same-name type exists → AE1013 "unknown type" */
                ok = resolver_append_error(
                    context,
                    type_ref->token,
                    "AE1013", format_message("unknown type '%s'",
                                   qualified_name != NULL ? qualified_name : "<unknown>"));
                free(qualified_name);
                return ok;
            }

            expected_arity = decl_type_param_count(any_decl);
            if (expected_arity == 0U) {
                /* Same-name type exists but is not generic → AE1014 */
                ok = resolver_append_error(
                    context,
                    type_ref->token,
                    "AE1014", format_message("'%.*s' is not a generic type and does not take type arguments",
                                   (int)name.length, name.data));
            } else {
                /* Same-name generic type exists but arity mismatch → AE1015 */
                ok = resolver_append_error(
                    context,
                    type_ref->token,
                    "AE1015", format_message("'%.*s' expects %zu type argument(s), but %zu were provided",
                                   (int)name.length, name.data,
                                   expected_arity, type_arg_count));
            }
            free(qualified_name);
            return ok;
        }

        if (base_decl->kind == FENG_DECL_TYPE) {
            materialize_named_type_param_constraint_witnesses(
                context,
                base_decl->as.type_decl.type_params,
                base_decl->as.type_decl.type_param_count,
                (const FengTypeRef *const *)type_ref->as.named.type_args,
                type_arg_count,
                type_ref->token);
        } else if (base_decl->kind == FENG_DECL_SPEC) {
            materialize_named_type_param_constraint_witnesses(
                context,
                base_decl->as.spec_decl.type_params,
                base_decl->as.spec_decl.type_param_count,
                (const FengTypeRef *const *)type_ref->as.named.type_args,
                type_arg_count,
                type_ref->token);
        }

        return true;
    }

    /* Normal named type reference (no type arguments).
     * §6.4: Precise (name, arity=0) lookup; AE0006 if generic target exists. */
    if (segment_count == 1U) {
        if (type_ref_is_unknown(type_ref)) {
            if (context->unknown_type_depth > 0U) {
                return true;
            }
            return resolver_append_error(
                context,
                type_ref->token,
                "AE1403", format_message("type 'unknown' is only valid as a catch clause type"));
        }

        if (is_builtin_type_name(name)) {
            if (!allow_void && slice_equals_cstr(name, "void")) {
                return resolver_append_error(
                    context,
                    type_ref->token,
                    "AE0502", format_message("type 'void' is only valid as a function return type"));
            }
            return true;
        }

        /* 惰性歧义检测(规范 §7.1):裸名 type/enum/spec 引用前先做跨来源
         * 歧义检测(import vs import / import vs 本模块)。覆盖第 1/2/3 类
         * 场景。 */
        if (!report_name_ambiguity_if_any(context,
                                           type_ref->token,
                                           name,
                                           SYMBOL_LOOKUP_TYPE)) {
            return false;
        }

        /* Precise lookup: (name, arity=0) */
        if (find_named_type_decl(context, segments, segment_count, 0U) != NULL) {
            return true;
        }

        /* Bare name references a generic type (arity ≠ 0) → AE0006 */
        {
            const VisibleTypeEntry *any_entry = find_visible_type_any_arity(
                context->visible_types, context->visible_type_count, name);

            if (any_entry != NULL && decl_type_param_count(any_entry->decl) > 0U) {
                return resolver_append_error(
                    context,
                    type_ref->token,
                    "AE0006", format_message("'%.*s' is a generic type and requires type arguments",
                                   (int)name.length, name.data));
            }
        }

        if (find_alias(context->aliases, context->alias_count, name) != NULL) {
            return resolver_append_error(
                context,
                type_ref->token,
                "AE0901", format_message("module alias '%.*s' cannot be used as a type by itself; use '%.*s.Name'",
                               (int)name.length,
                               name.data,
                               (int)name.length,
                               name.data));
        }
    } else {
        /* Multi-segment bare name (no type arguments) */
        if (find_named_type_decl(context, segments, segment_count, 0U) != NULL) {
            return true;
        }

        /* Cross-module: check if a generic type with this name exists → AE0006 */
        {
            const FengSemanticModule *target_module = NULL;

            if (segment_count == 2U) {
                const AliasEntry *mod_alias =
                    find_alias(context->aliases, context->alias_count, segments[0]);
                if (mod_alias != NULL) {
                    target_module = mod_alias->target_module;
                }
            }
            if (target_module == NULL) {
                size_t mod_idx = find_module_index_by_path(
                    context->analysis, segments, segment_count - 1U);
                if (mod_idx < context->analysis->module_count) {
                    target_module = &context->analysis->modules[mod_idx];
                }
            }
            if (target_module != NULL) {
                const FengDecl *any_decl = find_module_public_type_decl_any_arity(
                    target_module, name);
                if (any_decl != NULL && decl_type_param_count(any_decl) > 0U) {
                    return resolver_append_error(
                        context,
                        type_ref->token,
                        "AE0006", format_message("'%.*s' is a generic type and requires type arguments",
                                       (int)name.length, name.data));
                }
            }
        }
    }

    qualified_name = format_module_name(segments, segment_count);
    if (!resolver_append_error(context,
                               type_ref->token,
                               "AE1013", format_message("unknown type '%s'",
                                              qualified_name != NULL ? qualified_name : "<unknown>"))) {
        free(qualified_name);
        return false;
    }

    free(qualified_name);
    return true;
}

static bool resolve_type_ref(ResolveContext *context, const FengTypeRef *type_ref, bool allow_void) {
    if (type_ref == NULL) {
        return true;
    }

    switch (type_ref->kind) {
        case FENG_TYPE_REF_NAMED:
            return resolve_named_type_ref(context, type_ref, allow_void);
        case FENG_TYPE_REF_POINTER:
            return resolve_type_ref(context, type_ref->as.inner, true);
        case FENG_TYPE_REF_ARRAY:
            return resolve_type_ref(context, type_ref->as.inner, false);
    }

    return true;
}

/* Validate a public top-level member reached through either an import alias or
 * a complete module path. */
static bool resolve_module_member_expr(ResolveContext *context,
                                       const FengExpr *expr) {
    ResolvedModuleMemberTarget target;
    char *module_name;

    if (!resolve_module_member_target(context, expr, &target)) {
        return false;
    }

    if (module_exports_public_name(target.module,
                                   target.member_name,
                                   NULL,
                                   NULL)) {
        return true;
    }

    module_name = format_module_name(target.module->segments,
                                     target.module->segment_count);
    if (!resolver_append_error(
            context,
            expr->token,
            "AE0903",
            target.alias != NULL
                ? format_message(
                      "module alias '%.*s' does not export public name '%.*s' from module '%s'",
                      (int)target.alias->alias.length,
                      target.alias->alias.data,
                      (int)target.member_name.length,
                      target.member_name.data,
                      module_name != NULL ? module_name : "<unknown>")
                : format_message(
                      "module '%s' does not export public name '%.*s'",
                      module_name != NULL ? module_name : "<unknown>",
                      (int)target.member_name.length,
                      target.member_name.data))) {
        free(module_name);
        return false;
    }

    free(module_name);
    return true;
}

static bool resolve_lambda_expr(ResolveContext *context, const FengExpr *expr) {
    size_t param_index;
    size_t errors_before;
    bool effective_allow_self;
    const FengTypeRef *target_return_type;
    LambdaCaptureFrame frame;
    LambdaCallableContext callable_context;
    FengExpr *mutable_expr = (FengExpr *)expr;
    bool ok;

    target_return_type = lambda_target_return_type(context);
    errors_before = context->error_count != NULL ? *context->error_count : 0U;

    for (param_index = 0U; param_index < expr->as.lambda.param_count; ++param_index) {
        if (!resolve_type_ref(context, expr->as.lambda.params[param_index].type, false)) {
            return false;
        }
    }

    /* Snapshot scope_count before pushing the lambda's own scope: any local
     * binding found at scope <= floor is captured from outside. */
    memset(&frame, 0, sizeof(frame));
    frame.lambda = mutable_expr;
    frame.outer_scope_floor = context->scope_count;

    if (!append_raw((void **)&context->lambda_frames,
                    &context->lambda_frame_count,
                    &context->lambda_frame_capacity,
                    sizeof(frame),
                    &frame)) {
        return false;
    }

    if (!resolver_push_scope(context)) {
        --context->lambda_frame_count;
        return false;
    }

    /* Inside the lambda body, `self` is available iff the enclosing context
     * could provide it (i.e. self_capturable was true). Nested lambdas keep
     * the same capability so they can also capture self. */
    effective_allow_self = context->self_capturable;

    /* A lambda is a new callable body. Keep the lexical member identity for
     * type-implementation authorization, but do not inherit constructor or
     * finalizer body-only return/binding rules. */
    lambda_enter_callable_context(context, expr, &callable_context);

    ok = true;
    for (param_index = 0U; param_index < expr->as.lambda.param_count && ok; ++param_index) {
        ok = resolver_declare_local_typed_name(
            context,
            expr->as.lambda.params[param_index].token,
            expr->as.lambda.params[param_index].name,
            inferred_expr_type_from_type_ref(expr->as.lambda.params[param_index].type),
            expr->as.lambda.params[param_index].mutability);
    }
    if (ok) {
        if (expr->as.lambda.is_block_body) {
            ok = resolve_block_contents(context, expr->as.lambda.body_block, effective_allow_self);
        } else {
            ok = resolve_expr(context, expr->as.lambda.body, effective_allow_self);
        }
    }

    if (ok && expr->as.lambda.is_block_body && target_return_type != NULL &&
        (context->error_count == NULL || *context->error_count == errors_before)) {
        ok = validate_block_lambda_return_contract(
            context, expr, target_return_type);
    }

    lambda_leave_callable_context(context, &callable_context);

    resolver_pop_scope(context);

    /* Pop the lambda capture frame and publish its captures onto the AST so
     * later phases (and code generation) can reason about closure state. */
    {
        LambdaCaptureFrame *built = &context->lambda_frames[context->lambda_frame_count - 1U];

        if (ok) {
            free(mutable_expr->as.lambda.captures);
            mutable_expr->as.lambda.captures = built->captures;
            mutable_expr->as.lambda.capture_count = built->capture_count;
            mutable_expr->as.lambda.captures_self = built->captures_self;
        } else {
            free(built->captures);
        }
        --context->lambda_frame_count;
    }

    return ok;
}

/* Return the declaration signature selected for one direct call expression. */
static const FengCallableSignature *resolved_call_signature(
    const FengResolvedCallable *resolved) {
    if (resolved == NULL) {
        return NULL;
    }
    if (resolved->kind == FENG_RESOLVED_CALLABLE_FUNCTION &&
        resolved->function_decl != NULL) {
        return &resolved->function_decl->as.function_decl;
    }
    if (resolved->member != NULL) {
        return &resolved->member->as.callable;
    }
    return NULL;
}

/* Enforce block-lambda return contracts after overload resolution has chosen
 * a unique direct function, method, fit method, spec method, or constructor.
 * This post-selection location avoids emitting diagnostics while candidates
 * are still being probed. */
static bool validate_resolved_call_block_lambda_arguments(
    ResolveContext *context,
    const FengExpr *call_expr) {
    const FengResolvedCallable *resolved;
    const FengCallableSignature *signature;
    InferredExprType owner_type = inferred_expr_type_unknown();
    bool is_variadic;
    size_t fixed_count;
    size_t arg_index;

    if (context == NULL || call_expr == NULL ||
        call_expr->kind != FENG_EXPR_CALL) {
        return true;
    }
    resolved = &call_expr->as.call.resolved_callable;
    signature = resolved_call_signature(resolved);
    if (signature == NULL) {
        return true;
    }
    if (resolved->owner_instance_type_ref != NULL) {
        owner_type = inferred_expr_type_from_type_ref(
            resolved->owner_instance_type_ref);
    }
    is_variadic = signature->param_count > 0U &&
                  signature->params[signature->param_count - 1U].is_variadic;
    fixed_count = is_variadic ? signature->param_count - 1U
                              : signature->param_count;

    for (arg_index = 0U; arg_index < call_expr->as.call.arg_count; ++arg_index) {
        const FengExpr *arg = call_expr->as.call.args[arg_index];
        const FengTypeRef *param_type;
        const FengDecl *param_function_type_decl;
        const FengTypeRef *target_return_type;

        if (arg == NULL || arg->kind != FENG_EXPR_LAMBDA ||
            !arg->as.lambda.is_block_body) {
            continue;
        }
        if (arg_index < fixed_count || arg->is_prepacked_variadic_arg) {
            if (arg_index >= signature->param_count) {
                continue;
            }
            param_type = signature->params[arg_index].type;
        } else {
            param_type = signature->params[fixed_count].type->as.inner;
        }
        param_type = substitute_type_ref_for_owner_instance(
            context, resolved->owner_type_decl, owner_type, param_type);
        param_type = substitute_type_ref_for_fit_instance(
            context, resolved->fit_decl, owner_type, param_type);
        param_type = substitute_type_ref_for_explicit_callable_args(
            context,
            signature,
            resolved->callable_type_args,
            resolved->callable_type_arg_count,
            param_type);
        param_function_type_decl = resolve_function_type_decl(context, param_type);
        if (param_function_type_decl == NULL) {
            continue;
        }
        target_return_type = substitute_spec_member_type_ref_for_instance(
            context,
            param_function_type_decl,
            param_type,
            param_function_type_decl->as.spec_decl.as.callable.return_type);
        if (!validate_block_lambda_return_contract_in_fresh_scope(
                context, arg, target_return_type)) {
            return false;
        }
    }
    return true;
}

static bool resolve_expr(ResolveContext *context, const FengExpr *expr, bool allow_self) {
    size_t index;

    if (expr == NULL) {
        return true;
    }

    /* Check the root before module/static-member shortcuts can bypass normal
     * identifier resolution. Calls and constructors recursively resolve here. */
    {
        const FengExpr *root = expr;
        while (root != NULL && root->kind == FENG_EXPR_MEMBER) {
            root = root->as.member.object;
        }
        if (root != NULL && root->kind == FENG_EXPR_IDENTIFIER &&
            !resolver_has_local_name(context, root->as.identifier) &&
            !validate_alias_name_reference(context, root->token, root->as.identifier)) {
            return false;
        }
    }

    switch (expr->kind) {
        case FENG_EXPR_IDENTIFIER:
            {
                size_t local_scope = 0U;
                const LocalNameEntry *local = resolver_find_local_name_entry_with_scope(
                    context, expr->as.identifier, &local_scope);

                if (local != NULL) {
                    if (context->lambda_frame_count > 0U &&
                        !resolver_record_local_capture(context,
                                                       local->name,
                                                       local->mutability,
                                                       local_scope)) {
                        return false;
                    }
                    if (inferred_expr_type_is_unknown_type_ref(local->type) &&
                        context->allowed_unknown_rethrow_expr != expr) {
                        return resolver_append_error(
                            context,
                            expr->token,
                            "AE1404", format_message("unknown catch value '%.*s' can only be used in 'throw %.*s'",
                                           (int)expr->as.identifier.length,
                                           expr->as.identifier.data,
                                           (int)expr->as.identifier.length,
                                           expr->as.identifier.data));
                    }
                    return true;
                }
                /* 惰性歧义检测(规范 §7.1):裸名值引用前先做跨来源歧义检测
                 * (import vs import / import vs 本模块)。覆盖第 1/2/3 类场景。
                 * 函数调用 callee 也会经过这里,因此 L17309 的 CALL 分支检测
                 * 实际是冗余的,但作为冗余兜底保留(若 IDENTIFIER 分支漏掉某种
                 * 场景,CALL 分支仍能捕获)。 */
                if (!report_name_ambiguity_if_any(context,
                                                   expr->token,
                                                   expr->as.identifier,
                                                   SYMBOL_LOOKUP_VALUE)) {
                    return false;
                }
                if (find_visible_value(context->visible_values,
                                       context->visible_value_count,
                                       expr->as.identifier) != NULL ||
                    find_visible_type_any_arity(context->visible_types,
                                      context->visible_type_count,
                                      expr->as.identifier) != NULL) {
                    return true;
                }
                /* G4: a generic type parameter name (e.g., `T` in
                 * `func f<T: Factory<T>>()`) is admissible when used as a
                 * type-level identifier; member/call expressions on it
                 * (T.field / T.method()) are resolved via the constraint
                 * spec's witness table elsewhere. */
                if (find_type_param(context, expr->as.identifier) != NULL) {
                    return true;
                }
            }

            if (find_alias(context->aliases, context->alias_count, expr->as.identifier) != NULL) {
                return resolver_append_error(
                    context,
                    expr->token,
                    "AE0904", format_message("module alias '%.*s' must be accessed as '%.*s.name'",
                                   (int)expr->as.identifier.length,
                                   expr->as.identifier.data,
                                   (int)expr->as.identifier.length,
                                   expr->as.identifier.data));
            }

            return resolver_append_error(context,
                                         expr->token,
                                         "AE0001", format_message("undefined identifier '%.*s'",
                                                        (int)expr->as.identifier.length,
                                                        expr->as.identifier.data));

        case FENG_EXPR_SELF:
            if (allow_self) {
                if (context->lambda_frame_count > 0U) {
                    resolver_record_self_capture(context);
                }
                return true;
            }

            return resolver_append_error(context,
                                         expr->token,
                                         "AE0003", format_message("'self' is only available inside type methods and constructors"));

        case FENG_EXPR_BOOL:
        case FENG_EXPR_INTEGER:
        case FENG_EXPR_FLOAT:
        case FENG_EXPR_STRING:
            return true;

        case FENG_EXPR_ARRAY_LITERAL:
            {
                const FengTypeRef *previous_expected =
                    context->current_expr_expected_type_ref;
                const FengTypeRef *element_expected =
                    previous_expected != NULL &&
                            previous_expected->kind == FENG_TYPE_REF_ARRAY
                        ? previous_expected->as.inner
                        : NULL;
                size_t errors_before = context->error_count != NULL
                                           ? *context->error_count
                                           : 0U;
                bool items_ok = true;

                context->current_expr_expected_type_ref = element_expected;
                for (index = 0U; index < expr->as.array_literal.count; ++index) {
                    if (!resolve_expr(context,
                                      expr->as.array_literal.items[index],
                                      allow_self)) {
                        items_ok = false;
                        break;
                    }
                    if (context->error_count != NULL &&
                        *context->error_count > errors_before) {
                        break;
                    }
                }
                context->current_expr_expected_type_ref = previous_expected;
                if (!items_ok) {
                    return false;
                }
                if (context->error_count != NULL &&
                    *context->error_count > errors_before) {
                    return true;
                }
            }
            return validate_array_literal_expr(context, expr);

        case FENG_EXPR_TUPLE_LITERAL:
            for (index = 0U; index < expr->as.tuple_literal.count; ++index) {
                if (!resolve_expr(context, expr->as.tuple_literal.items[index], allow_self)) {
                    return false;
                }
            }
            return true;

        case FENG_EXPR_ARRAY_NEW: {
            if (!resolve_type_ref(context, expr->as.array_new.element_type, false)) {
                return false;
            }
            if (!validate_array_new_default_zero_element(
                    context, expr->as.array_new.element_type)) {
                return false;
            }
            /* Validate size expression is an integer expression. */
            if (!resolve_expr(context, expr->as.array_new.size, allow_self)) {
                return false;
            }
            InferredExprType size_type = infer_expr_type(context, expr->as.array_new.size);
            if (inferred_expr_type_is_known(size_type) &&
                !inferred_expr_type_is_integer(size_type)) {
                return resolver_append_error(context, expr->as.array_new.size->token,
                    "AE0202", format_message("array size must be an integer expression"));
            }
            ((FengExpr *)expr)->as.array_new.size_is_statically_valid = false;
            if (inferred_expr_type_is_known(size_type) &&
                !validate_array_new_constant_size(
                    context,
                    expr->as.array_new.size,
                    size_type,
                    &((FengExpr *)expr)->as.array_new.size_is_statically_valid)) {
                return false;
            }
            return true;
        }

        case FENG_EXPR_OBJECT_LITERAL:
            {
                ResolvedTypeTarget target;
                InferredExprType target_expr_type;

                if (!resolve_expr(context, expr->as.object_literal.target, allow_self)) {
                    return false;
                }
                if (!validate_object_literal_expr(context, expr)) {
                    return false;
                }

                target = resolve_type_target_expr(context, expr->as.object_literal.target, true);
                target_expr_type = infer_expr_type(context, expr->as.object_literal.target);
                if (!inferred_expr_type_is_known(target_expr_type)) {
                    target_expr_type = resolved_type_target_owner_type(&target);
                }
                for (index = 0U; index < expr->as.object_literal.field_count; ++index) {
                    const FengObjectFieldInit *field = &expr->as.object_literal.fields[index];
                    const FengTypeMember *field_member =
                        target.type_decl != NULL ? find_type_field_member(target.type_decl, field->name) : NULL;
                    const FengTypeRef *field_type =
                        field_member != NULL
                            ? substitute_type_ref_for_owner_instance(context,
                                                                     target.type_decl,
                                                                     target_expr_type,
                                                                     field_member->as.field.type)
                            : NULL;
                    const FengTypeRef *previous_expected =
                        context->current_expr_expected_type_ref;
                    bool field_ok;

                    context->current_expr_expected_type_ref = field_type;
                    field_ok = resolve_expr(context, field->value, allow_self);
                    context->current_expr_expected_type_ref = previous_expected;
                    if (!field_ok) {
                        return false;
                    }
                    if (field_type != NULL &&
                        !validate_expr_against_expected_type(context,
                                                            field->value,
                                                            field_type)) {
                        return false;
                    }
                    if (!validate_borrowed_data_pointer_object_field(context,
                                                                     field,
                                                                     field_type)) {
                        return false;
                    }
                }
                return true;
            }

        case FENG_EXPR_GENERIC_TARGET: {
            if (!resolve_expr(context, expr->as.generic_target.target, allow_self)) {
                return false;
            }
            for (index = 0U; index < expr->as.generic_target.type_arg_count; ++index) {
                if (!resolve_type_ref(context, expr->as.generic_target.type_args[index], false)) {
                    return false;
                }
            }
            /* Calls, type construction and target-typed callable values all
             * share this AST form. The surrounding semantic consumer decides
             * whether it is legal; an unconsumed value is rejected by the
             * untyped-callable validation path with AE1016. */
            return true;
        }

        case FENG_EXPR_CALL:
            {
                size_t errors_before = *context->error_count;
                if (!resolve_expr(context, expr->as.call.callee, allow_self)) {
                    return false;
                }
                /* An inaccessible or invalid callee has no callable signature
                 * to match; preserve its diagnostic without a secondary one. */
                if (*context->error_count > errors_before) {
                    return true;
                }
            }
            {
                const FengTypeRef *previous_expected =
                    context->current_expr_expected_type_ref;
                size_t errors_before = *context->error_count;
                bool args_ok = true;

                /* A call's outer target describes its return value, not its
                 * arguments. Parameter targets become known only after
                 * overload selection, so branch-result mismatch checks are
                 * deferred while each argument is resolved. */
                context->current_expr_expected_type_ref = NULL;
                context->deferred_call_argument_target_depth += 1U;
                for (index = 0U; index < expr->as.call.arg_count; ++index) {
                    if (!resolve_expr(context,
                                      expr->as.call.args[index],
                                      allow_self)) {
                        args_ok = false;
                        break;
                    }
                }
                context->deferred_call_argument_target_depth -= 1U;
                context->current_expr_expected_type_ref = previous_expected;
                if (!args_ok) {
                    return false;
                }
                /* Invalid arguments cannot participate in overload matching.
                 * Keep their source errors without a derived call mismatch. */
                if (*context->error_count > errors_before) {
                    return true;
                }
            }
            /* G4-13a: Resolve explicit type args (callee<T1, T2>(...) syntax). */
            if (expr->as.call.has_explicit_type_args) {
                size_t type_arg_index;
                for (type_arg_index = 0U;
                     type_arg_index < expr->as.call.explicit_type_arg_count;
                     ++type_arg_index) {
                    if (!resolve_type_ref(context,
                                         expr->as.call.explicit_type_args[type_arg_index],
                                         false)) {
                        return false;
                    }
                }
            }
            if (!validate_constructor_call_expr(context, expr) ||
                !validate_function_call_expr(context, expr)) {
                return false;
            }
            if (!validate_resolved_call_block_lambda_arguments(context, expr)) {
                return false;
            }
            if (!validate_explicit_prepacked_variadic_argument(context, expr)) {
                return false;
            }
            /* G4-13b: Arity check for explicit type args against resolved callable. */
            if (expr->as.call.has_explicit_type_args &&
                expr->as.call.resolved_callable.kind != FENG_RESOLVED_CALLABLE_NONE) {
                const FengResolvedCallable *rc = &expr->as.call.resolved_callable;
                size_t callable_type_param_count = 0U;
                if (rc->kind == FENG_RESOLVED_CALLABLE_FUNCTION &&
                    rc->function_decl != NULL) {
                    callable_type_param_count =
                        rc->function_decl->as.function_decl.type_param_count;
                } else if ((rc->kind == FENG_RESOLVED_CALLABLE_TYPE_METHOD ||
                            rc->kind == FENG_RESOLVED_CALLABLE_FIT_METHOD ||
                            rc->kind == FENG_RESOLVED_CALLABLE_TYPE_STATIC_METHOD ||
                            rc->kind == FENG_RESOLVED_CALLABLE_FIT_STATIC_METHOD ||
                            rc->kind == FENG_RESOLVED_CALLABLE_SPEC_METHOD ||
                            rc->kind == FENG_RESOLVED_CALLABLE_SPEC_STATIC_METHOD) &&
                           rc->member != NULL) {
                    callable_type_param_count =
                        rc->member->as.callable.type_param_count;
                } else if (rc->kind == FENG_RESOLVED_CALLABLE_TYPE_CONSTRUCTOR &&
                           rc->owner_type_decl != NULL &&
                           rc->owner_type_decl->kind == FENG_DECL_TYPE) {
                    /* Type<T1, T2>(...) constructor syntax: validate arity
                     * against the type declaration's type parameters. */
                    callable_type_param_count =
                        rc->owner_type_decl->as.type_decl.type_param_count;
                }
                if (expr->as.call.explicit_type_arg_count != callable_type_param_count) {
                    return resolver_append_error(
                        context,
                        expr->token,
                        rc->kind == FENG_RESOLVED_CALLABLE_TYPE_CONSTRUCTOR ? "AE0232" : "AE0233",
                        format_message(
                            rc->kind == FENG_RESOLVED_CALLABLE_TYPE_CONSTRUCTOR
                                ? "type expects %zu type argument(s) but %zu were provided"
                                : "function expects %zu type argument(s) but %zu were provided",
                            callable_type_param_count,
                            expr->as.call.explicit_type_arg_count));
                }
            }
            return true;

        case FENG_EXPR_MEMBER:
            if (resolve_module_member_expr(context, expr)) {
                return record_type_fact_for_site(
                    context, expr, infer_expr_type(context, expr));
            }
            if (expr->as.member.object != NULL && expr->as.member.object->kind == FENG_EXPR_SELF) {
                if (!resolve_self_member_expr(context, expr, allow_self)) {
                    return false;
                }
                return record_type_fact_for_site(
                    context, expr, infer_expr_type(context, expr));
            }
            {
                ResolvedTypeTarget target =
                    resolve_type_target_expr(context, expr->as.member.object, false);

                if (target.type_decl != NULL || target.is_builtin_type_name) {
                    if (!validate_instance_member_expr(context, expr)) {
                        return false;
                    }
                    return record_type_fact_for_site(
                        context, expr, infer_expr_type(context, expr));
                }
            }
            if (!resolve_expr(context, expr->as.member.object, allow_self) ||
                !validate_instance_member_expr(context, expr)) {
                return false;
            }
            return record_type_fact_for_site(
                context, expr, infer_expr_type(context, expr));

        case FENG_EXPR_INDEX:
            return resolve_expr(context, expr->as.index.object, allow_self) &&
                   resolve_expr(context, expr->as.index.index, allow_self) &&
                   validate_index_expr(context, expr);

        case FENG_EXPR_UNARY:
            return resolve_expr(context, expr->as.unary.operand, allow_self) &&
                   validate_unary_expr(context, expr);

        case FENG_EXPR_BINARY:
            if (!resolve_expr(context, expr->as.binary.left, allow_self)) {
                return false;
            }
            /* For `A && B`, B can see match bindings introduced by A (per
             * docs/specifications/feng-flow.md §3.3). Collect them from A's subtree and
             * register into a fresh scope so B's resolution finds them.
             * `||` / other operators don't propagate bindings. */
            if (expr->as.binary.op == FENG_TOKEN_AND_AND) {
                VisibleMatchBindingSet left_bindings;
                bool pushed_scope = false;
                size_t binding_index;

                left_bindings.items = NULL;
                left_bindings.count = 0U;
                left_bindings.capacity = 0U;
                if (!collect_visible_match_bindings(expr->as.binary.left, &left_bindings)) {
                    free_visible_match_binding_set(&left_bindings);
                    return false;
                }
                if (left_bindings.count > 0U) {
                    if (!resolver_push_scope(context)) {
                        free_visible_match_binding_set(&left_bindings);
                        return false;
                    }
                    pushed_scope = true;
                    for (binding_index = 0U; binding_index < left_bindings.count; ++binding_index) {
                        if (!register_visible_match_binding(context, &left_bindings.items[binding_index])) {
                            free_visible_match_binding_set(&left_bindings);
                            resolver_pop_scope(context);
                            return false;
                        }
                    }
                }
                free_visible_match_binding_set(&left_bindings);

                if (!resolve_expr(context, expr->as.binary.right, allow_self)) {
                    if (pushed_scope) {
                        resolver_pop_scope(context);
                    }
                    return false;
                }
                /* infer_expr_type and validate_binary_expr both run while the
                 * binding scope is still active so the right operand can be
                 * resolved through the binding introduced by the left side.
                 * The derive pass fills expr->type (and operands' type) so
                 * validate_binary_expr can read them directly. */
                (void)infer_expr_type(context, expr);
                if (!validate_binary_expr(context, expr)) {
                    if (pushed_scope) {
                        resolver_pop_scope(context);
                    }
                    return false;
                }
                if (pushed_scope) {
                    resolver_pop_scope(context);
                }
            } else {
                if (!resolve_expr(context, expr->as.binary.right, allow_self)) {
                    return false;
                }
                /* Derive first (fills expr->type via the binary branch's
                 * fill_expr_type_from_inferred calls), then validate — which
                 * reads the derivation result directly. */
                (void)infer_expr_type(context, expr);
                if (!validate_binary_expr(context, expr)) {
                    return false;
                }
            }
            record_spec_equality_if_applicable(context, expr);
            return true;

        case FENG_EXPR_LAMBDA:
            return resolve_lambda_expr(context, expr);

        case FENG_EXPR_CAST:
            return resolve_type_ref(context, expr->as.cast.type, false) &&
                   resolve_expr(context, expr->as.cast.value, allow_self) &&
                   validate_cast_expr(context, expr);

        case FENG_EXPR_IF: {
            ExpressionBranchBoundaryState boundary_state;
            bool ok;

            if (!resolve_expr(context, expr->as.if_expr.condition, allow_self)) {
                return false;
            }
            enter_expression_branch_boundary(
                context,
                EXPRESSION_BRANCH_BOUNDARY_IF,
                &boundary_state);
            ok = resolve_branch_result_block(context,
                                             expr->as.if_expr.then_block,
                                             allow_self) &&
                 resolve_branch_result_block(context,
                                             expr->as.if_expr.else_block,
                                             allow_self);
            leave_expression_branch_boundary(context, &boundary_state);
            return ok && validate_if_expr(context, expr);
        }

        case FENG_EXPR_MATCH: {
            ExpressionBranchBoundaryState boundary_state;
            bool ok;

            enter_expression_branch_boundary(
                context,
                EXPRESSION_BRANCH_BOUNDARY_MATCH,
                &boundary_state);
            ok = resolve_and_validate_match_common(
                context,
                expr,
                expr->as.match_expr.target,
                expr->as.match_expr.branches,
                expr->as.match_expr.branch_count,
                expr->as.match_expr.else_block,
                expr->token,
                true,
                allow_self);
            leave_expression_branch_boundary(context, &boundary_state);
            return ok;
        }

        case FENG_EXPR_MATCH_OP:
            return resolve_and_validate_match_op(context, expr, allow_self);

        case FENG_EXPR_TRY:
            return resolve_try_expr(context, expr, allow_self, true);
    }

    return true;
}

/* Add local names produced by destructuring a tuple value. */
static bool add_destructure_locals_from_tuple_type(ResolveContext *context,
                                                   const FengBinding *binding,
                                                   const FengDecl *tuple_decl,
                                                   const FengTypeRef *tuple_type_ref,
                                                   bool add_to_scope,
                                                   bool diagnose_duplicates) {
    size_t index;

    if (!decl_is_tuple_type(tuple_decl)) {
        return resolver_append_error(
            context,
            binding->token,
            "AE0108", format_message("destructuring binding initializer must be a tuple"));
    }
    if (binding->destructure_count != tuple_decl->as.type_decl.member_count) {
        return resolver_append_error(
            context,
            binding->token,
            "AE0109", format_message("destructuring binding has %zu position(s) but tuple initializer has %zu",
                           binding->destructure_count,
                           tuple_decl->as.type_decl.member_count));
    }

    for (index = 0U; index < binding->destructure_count; ++index) {
        FengSlice name = binding->destructure_names[index];
        const FengTypeRef *field_type;

        if (name.length == 0U) {
            continue;
        }

        field_type = tuple_field_type_for_instance(context, tuple_decl, tuple_type_ref, index);
        if (field_type == NULL) {
            return false;
        }
        if (add_to_scope) {
            FengToken token = binding->destructure_tokens != NULL
                                  ? binding->destructure_tokens[index]
                                  : binding->token;
            bool added = diagnose_duplicates
                             ? resolver_declare_local_typed_name_with_source(
                                   context,
                                   token,
                                   name,
                                   inferred_expr_type_from_type_ref(field_type),
                                   binding->mutability,
                                   NULL)
                             : resolver_add_local_typed_name_with_source(
                                   context,
                                   name,
                                   inferred_expr_type_from_type_ref(field_type),
                                   binding->mutability,
                                   NULL);

            if (!added) {
                return false;
            }
        }
    }

    return true;
}

/* Add local names produced by destructuring a tuple literal expression. */
static bool add_destructure_locals_from_tuple_literal(ResolveContext *context,
                                                      const FengBinding *binding,
                                                      const FengExpr *literal,
                                                      bool add_to_scope,
                                                      bool diagnose_duplicates) {
    size_t index;

    if (literal == NULL || literal->kind != FENG_EXPR_TUPLE_LITERAL) {
        return false;
    }
    if (binding->destructure_count != literal->as.tuple_literal.count) {
        return resolver_append_error(
            context,
            binding->token,
            "AE0109", format_message("destructuring binding has %zu position(s) but tuple literal has %zu",
                           binding->destructure_count,
                           literal->as.tuple_literal.count));
    }

    for (index = 0U; index < binding->destructure_count; ++index) {
        FengSlice name = binding->destructure_names[index];
        const FengExpr *item = literal->as.tuple_literal.items[index];
        InferredExprType item_type;

        if (!validate_untyped_callable_value_expr(context, item) ||
            !validate_untyped_address_of_expr(context, item) ||
            !validate_untyped_array_literal_expr(context, item) ||
            !validate_untyped_tuple_literal_expr(context, item)) {
            return false;
        }
        if (name.length == 0U) {
            continue;
        }

        item_type = infer_expr_type(context, item);
        if (add_to_scope) {
            FengToken token = binding->destructure_tokens != NULL
                                  ? binding->destructure_tokens[index]
                                  : binding->token;
            bool added = diagnose_duplicates
                             ? resolver_declare_local_typed_name_with_source(
                                   context,
                                   token,
                                   name,
                                   item_type,
                                   binding->mutability,
                                   item)
                             : resolver_add_local_typed_name_with_source(
                                   context,
                                   name,
                                   item_type,
                                   binding->mutability,
                                   item);

            if (!added) {
                return false;
            }
        }
    }

    return true;
}

/* Resolve and type-check a destructuring let/var binding. */
static bool resolve_destructure_binding(ResolveContext *context,
                                        const FengBinding *binding,
                                        bool allow_self,
                                        bool add_to_scope) {
    InferredExprType initializer_type;
    const FengDecl *tuple_decl = NULL;
    const FengTypeRef *tuple_type_ref = NULL;

    if (binding->type != NULL) {
        return resolver_append_error(
            context,
            binding->token,
            "AE0110", format_message("destructuring bindings cannot use a single type annotation"));
    }
    if (!resolve_expr(context, binding->initializer, allow_self)) {
        return false;
    }
    if (binding->initializer != NULL &&
        binding->initializer->kind == FENG_EXPR_TUPLE_LITERAL) {
        return add_destructure_locals_from_tuple_literal(context,
                                                         binding,
                                                         binding->initializer,
                                                         add_to_scope,
                                                         true);
    }

    initializer_type = infer_expr_type(context, binding->initializer);
    if (initializer_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        tuple_type_ref = initializer_type.type_ref;
        tuple_decl = resolve_tuple_type_ref_decl(context, tuple_type_ref);
    } else if (initializer_type.kind == FENG_INFERRED_EXPR_TYPE_DECL &&
               decl_is_tuple_type(initializer_type.type_decl)) {
        tuple_decl = initializer_type.type_decl;
    }

    if (tuple_decl == NULL) {
        return resolver_append_error(
            context,
            binding->token,
            "AE0108", format_message("destructuring binding initializer must be a tuple"));
    }

    return add_destructure_locals_from_tuple_type(context,
                                                  binding,
                                                  tuple_decl,
                                                  tuple_type_ref,
                                                  add_to_scope,
                                                  true);
}

static bool resolve_binding(ResolveContext *context,
                            const FengBinding *binding,
                            bool allow_self,
                            bool add_to_scope) {
    InferredExprType binding_type;
    bool initializer_added_error = false;

    if (binding->is_destructure) {
        return resolve_destructure_binding(context, binding, allow_self, add_to_scope);
    }
    if (!resolve_type_ref(context, binding->type, false)) {
        return false;
    }
    /* When the binding has a type annotation, make the expected type visible
     * to nested expression resolution (e.g., if-expr branch adaptation). */
    {
        const FengTypeRef *prev_expected_type_ref = context->current_expr_expected_type_ref;
        size_t errors_before = context->error_count != NULL
                                   ? *context->error_count
                                   : 0U;
        bool ok;

        context->current_expr_expected_type_ref = binding->type;
        ok = resolve_expr(context, binding->initializer, allow_self);
        context->current_expr_expected_type_ref = prev_expected_type_ref;
        initializer_added_error = context->error_count != NULL &&
                                  *context->error_count > errors_before;
        if (!ok) {
            return false;
        }
    }
    if (binding->type != NULL) {
        /* An initializer-local diagnostic is the actionable root cause. Do
         * not derive a second target-fitting diagnostic from an expression
         * that is already invalid. */
        if (!initializer_added_error &&
            !validate_expr_against_expected_type(
                context, binding->initializer, binding->type)) {
            return false;
        }
        if (binding->initializer == NULL) {
            if (!validate_binding_default_zero_target(context,
                                                      binding->type,
                                                      binding->token)) {
                return false;
            }
            /* Phase S2-a: `let s: S;` (or `var s: S;`) without an initializer
             * is a default-witness slot when the declared type is a spec. */
            record_spec_default_binding_if_applicable(
                context,
                binding,
                FENG_SPEC_DEFAULT_BINDING_POSITION_LOCAL_BINDING,
                binding->type);
        }
    } else {
        if (!validate_untyped_callable_value_expr(context, binding->initializer)) {
            return false;
        }
        if (!validate_untyped_address_of_expr(context, binding->initializer)) {
            return false;
        }
        if (!validate_untyped_array_literal_expr(context, binding->initializer)) {
            return false;
        }
        if (!validate_untyped_tuple_literal_expr(context, binding->initializer)) {
            return false;
        }
        /* Untyped numeric binding (let x = 123; / let x = 12.5;):
         * synthesize a FengTypeRef for the default inferred type and hang
         * it on the literal node so codegen can emit the correct width.
         * Use canonical_builtin_type_name to get the width-explicit name
         * (e.g. "int" → "i32", "double" → "f64") since the AST alias
         * normalization pass has already run by this point. */
        if (binding->initializer != NULL &&
            binding->initializer->kind == FENG_EXPR_INTEGER) {
            const char *canonical = canonical_builtin_type_name(
                slice_from_cstr("int"), context->pointer_size);
            if (canonical != NULL) {
                InferredExprType inferred = inferred_expr_type_builtin(canonical);
                FengTypeRef *synth = create_type_ref_from_inferred_type(&inferred,
                                                                        binding->initializer->token);
                if (synth != NULL) {
                    /* Clone and transfer to Analysis lifetime so the type
                     * survives ResolveContext teardown for codegen to read. */
                    FengTypeRef *clone = clone_type_ref_for_inference(synth);
                    free_synthetic_type_ref(synth);
                    if (clone != NULL &&
                        analysis_track_synthetic_type_ref(context->analysis, clone)) {
                        ((FengExpr *)binding->initializer)->type = clone;
                    } else {
                        free_synthetic_type_ref(clone);
                    }
                }
            }
        }
        if (binding->initializer != NULL &&
            binding->initializer->kind == FENG_EXPR_FLOAT) {
            const char *canonical = canonical_builtin_type_name(
                slice_from_cstr("double"), context->pointer_size);
            if (canonical != NULL) {
                InferredExprType inferred = inferred_expr_type_builtin(canonical);
                FengTypeRef *synth = create_type_ref_from_inferred_type(&inferred,
                                                                        binding->initializer->token);
                if (synth != NULL) {
                    /* Clone and transfer to Analysis lifetime so the type
                     * survives ResolveContext teardown for codegen to read. */
                    FengTypeRef *clone = clone_type_ref_for_inference(synth);
                    free_synthetic_type_ref(synth);
                    if (clone != NULL &&
                        analysis_track_synthetic_type_ref(context->analysis, clone)) {
                        ((FengExpr *)binding->initializer)->type = clone;
                    } else {
                        free_synthetic_type_ref(clone);
                    }
                }
            }
        }
    }
    binding_type = binding->type != NULL ? inferred_expr_type_from_type_ref(binding->type)
                                         : infer_expr_type(context, binding->initializer);
    if (!record_type_fact_for_site(context, binding, binding_type)) {
        return false;
    }
    if (add_to_scope) {
        return resolver_declare_local_typed_name_with_source(
            context,
            binding->token,
            binding->name,
            binding_type,
            binding->mutability,
            binding->initializer);
    }
    return true;
}

static bool resolve_block(ResolveContext *context, const FengBlock *block, bool allow_self) {
    bool ok;

    if (!resolver_push_scope(context)) {
        return false;
    }

    ok = resolve_block_contents(context, block, allow_self);
    resolver_pop_scope(context);
    return ok;
}

static bool resolve_type_ref_with_unknown_context(ResolveContext *context,
                                                  const FengTypeRef *type_ref) {
    size_t previous_unknown_depth;
    bool ok;

    if (context == NULL) {
        return true;
    }

    previous_unknown_depth = context->unknown_type_depth;
    context->unknown_type_depth += 1U;
    ok = resolve_type_ref(context, type_ref, false);
    context->unknown_type_depth = previous_unknown_depth;
    return ok;
}

static bool resolve_try_expr(ResolveContext *context,
                             const FengExpr *expr,
                             bool allow_self,
                             bool result_required) {
    size_t previous_capture_depth;
    InferredExprType body_type;
    bool ok;

    if (expr == NULL || expr->kind != FENG_EXPR_TRY) {
        return true;
    }

    previous_capture_depth = context->exception_capture_depth;
    if (expr->as.try_expr.clause_count > 0U) {
        context->exception_capture_depth += 1U;
    }
    ok = resolve_expr(context, expr->as.try_expr.body, allow_self);
    context->exception_capture_depth = previous_capture_depth;
    if (!ok) {
        return false;
    }
    body_type = infer_expr_type(context, expr->as.try_expr.body);
    if (!record_type_fact_for_site(context,
                                   expr->as.try_expr.body,
                                   body_type)) {
        return false;
    }

    for (size_t clause_index = 0U;
         clause_index < expr->as.try_expr.clause_count;
         ++clause_index) {
        const FengTryCatchClause *clause = &expr->as.try_expr.clauses[clause_index];
        bool is_anonymous = clause->type == NULL && clause->name.length == 0U;
        InferredExprType catch_type = inferred_expr_type_from_type_ref(clause->type);
        const char *catch_reason = NULL;

        if (!resolve_type_ref_with_unknown_context(context, clause->type)) {
            return false;
        }
        if ((type_ref_is_unknown(clause->type) || is_anonymous) &&
            clause_index + 1U < expr->as.try_expr.clause_count) {
            return resolver_append_error(
                context,
                clause->token,
                "AE1406", format_message("catch clause matching any exception must be the last catch clause"));
        }
        if (!is_anonymous && !type_ref_is_unknown(clause->type) &&
            !type_ref_is_exception_payload(context, clause->type, &catch_reason)) {
            char *type_name = format_type_ref_name(clause->type);
            char *message = format_message(
                "catch type '%s' is not catchable: %s",
                type_name != NULL ? type_name : "<unknown>",
                catch_reason != NULL ? catch_reason : "type is not an exception value type");

            free(type_name);
            return resolver_append_error(context, clause->token, "AE0179", message);
        }
        if (!resolver_push_scope(context)) {
            return false;
        }
        {
            ExpressionBranchBoundaryState boundary_state;

            if (result_required) {
                enter_expression_branch_boundary(
                    context,
                    EXPRESSION_BRANCH_BOUNDARY_CATCH,
                    &boundary_state);
            }
            if (is_anonymous) {
                ok = resolve_branch_result_block(context,
                                                 clause->body,
                                                 allow_self) &&
                     validate_try_catch_clause_result_presence(context,
                                       expr,
                                       clause,
                                       body_type,
                                       result_required);
            } else {
                ok = resolver_declare_local_typed_name(
                         context,
                         clause->binding_token,
                         clause->name,
                         catch_type,
                         FENG_MUTABILITY_LET) &&
                     resolve_branch_result_block(context,
                                                 clause->body,
                                                 allow_self) &&
                     validate_try_catch_clause_result_presence(context,
                                       expr,
                                       clause,
                                       body_type,
                                       result_required);
            }
            if (result_required) {
                leave_expression_branch_boundary(context, &boundary_state);
            }
        }
        resolver_pop_scope(context);
        if (!ok) {
            return false;
        }
    }

    return validate_try_expr(context, expr, result_required);
}

static bool resolve_throw_value_expr(ResolveContext *context,
                                     const FengExpr *expr,
                                     bool allow_self) {
    const FengExpr *previous_allowed_unknown_rethrow_expr;
    bool ok;

    if (context == NULL) {
        return true;
    }

    previous_allowed_unknown_rethrow_expr =
        context->allowed_unknown_rethrow_expr;
    context->allowed_unknown_rethrow_expr = expr;
    ok = resolve_expr(context, expr, allow_self);
    context->allowed_unknown_rethrow_expr =
        previous_allowed_unknown_rethrow_expr;
    return ok;
}

static bool resolve_block_contents(ResolveContext *context,
                                   const FengBlock *block,
                                   bool allow_self) {
    size_t stmt_index;

    if (block == NULL) {
        return true;
    }

    for (stmt_index = 0U; stmt_index < block->statement_count; ++stmt_index) {
        if (!resolve_stmt(context, block->statements[stmt_index], allow_self)) {
            return false;
        }
    }

    return true;
}

static bool resolve_stmt(ResolveContext *context, const FengStmt *stmt, bool allow_self) {
    size_t clause_index;

    if (stmt == NULL) {
        return true;
    }

    switch (stmt->kind) {
        case FENG_STMT_BLOCK:
            return resolve_block(context, stmt->as.block, allow_self);

        case FENG_STMT_BINDING:
            return resolve_binding(context, &stmt->as.binding, allow_self, true);

        case FENG_STMT_ASSIGN:
            if (!resolve_expr(context, stmt->as.assign.target, allow_self)) {
                return false;
            }
            /* Phase S2-b: if the LHS is a member-expression against an
             * object-form spec, the recorded site is FIELD_READ by default;
             * upgrade it to FIELD_WRITE here. No-op when the target is not
             * a recorded spec member access (e.g. plain identifier, index
             * expression, or member of a non-spec owner). */
            if (stmt->as.assign.target != NULL &&
                stmt->as.assign.target->kind == FENG_EXPR_MEMBER) {
                feng_semantic_upgrade_spec_member_access_to_write(
                    context->analysis, stmt->as.assign.target);
            }
            if (!validate_self_let_assignment(context, stmt)) {
                return false;
            }
            if (!validate_assignment_target_writable(context, stmt->as.assign.target)) {
                return false;
            }
            {
                InferredExprType target_type = infer_expr_type(context, stmt->as.assign.target);
                FengTypeRef *expected_type_ref = NULL;
                const FengTypeRef *previous_expected =
                    context->current_expr_expected_type_ref;
                bool value_ok;

                if (stmt->as.assign.op == FENG_TOKEN_ASSIGN &&
                    inferred_expr_type_is_known(target_type)) {
                    expected_type_ref = create_type_ref_from_inferred_type(
                        &target_type,
                        stmt->as.assign.target != NULL
                            ? stmt->as.assign.target->token
                            : stmt->token);
                    if (expected_type_ref != NULL &&
                        !resolver_track_synthetic_type_ref(context,
                                                           expected_type_ref)) {
                        free_synthetic_type_ref(expected_type_ref);
                        return false;
                    }
                }
                context->current_expr_expected_type_ref = expected_type_ref;
                value_ok = resolve_expr(context,
                                        stmt->as.assign.value,
                                        allow_self);
                context->current_expr_expected_type_ref = previous_expected;
                if (!value_ok) {
                    return false;
                }
                if (stmt->as.assign.op != FENG_TOKEN_ASSIGN) {
                    return validate_compound_assignment(context, stmt);
                }

                if (!validate_expr_against_expected_inferred_type(context,
                                                                  stmt->as.assign.value,
                                                                  target_type)) {
                    return false;
                }
                if (stmt->as.assign.target != NULL &&
                    stmt->as.assign.target->kind == FENG_EXPR_IDENTIFIER) {
                    LocalNameEntry *local_entry =
                        resolver_find_mutable_local_name_entry(context,
                                                               stmt->as.assign.target->as.identifier);

                    if (local_entry != NULL) {
                        local_entry->source_expr = stmt->as.assign.value;
                    }
                }
                if (stmt->as.assign.target != NULL &&
                    stmt->as.assign.target->kind == FENG_EXPR_MEMBER &&
                    !validate_borrowed_data_pointer_assignment(context,
                                                               stmt->as.assign.target,
                                                               stmt->as.assign.value,
                                                               target_type)) {
                    return false;
                }
                return true;
            }

        case FENG_STMT_TRY:
            return resolve_try_expr(context, stmt->as.expr, allow_self, false) &&
                   validate_untyped_callable_value_expr(context, stmt->as.expr) &&
                   validate_untyped_address_of_expr(context, stmt->as.expr) &&
                   validate_untyped_tuple_literal_expr(context, stmt->as.expr);

        case FENG_STMT_EXPR:
            return resolve_expr(context, stmt->as.expr, allow_self) &&
                   validate_untyped_callable_value_expr(context, stmt->as.expr) &&
                   validate_untyped_address_of_expr(context, stmt->as.expr) &&
                   validate_untyped_tuple_literal_expr(context, stmt->as.expr);

        case FENG_STMT_IF:
            for (clause_index = 0U; clause_index < stmt->as.if_stmt.clause_count; ++clause_index) {
                VisibleMatchBindingSet bindings;
                bool pushed_binding_scope = false;
                size_t binding_index;

                bindings.items = NULL;
                bindings.count = 0U;
                bindings.capacity = 0U;

                if (!resolve_expr(context, stmt->as.if_stmt.clauses[clause_index].condition, allow_self)) {
                    free_visible_match_binding_set(&bindings);
                    return false;
                }

                /* Collect visible match bindings from this clause's condition.
                 * They become visible in the if body scope (parent of the
                 * body block's own scope). Per docs/specifications/feng-flow.md §3.3, only
                 * `&&` chains propagate bindings; `||` / `!` subtrees yield
                 * empty. Register BEFORE validating the condition so the
                 * binding's type is available to infer_expr_type. */
                if (!collect_visible_match_bindings(stmt->as.if_stmt.clauses[clause_index].condition,
                                                     &bindings)) {
                    free_visible_match_binding_set(&bindings);
                    return false;
                }
                if (bindings.count > 0U) {
                    if (!resolver_push_scope(context)) {
                        free_visible_match_binding_set(&bindings);
                        return false;
                    }
                    pushed_binding_scope = true;
                    for (binding_index = 0U; binding_index < bindings.count; ++binding_index) {
                        if (!register_visible_match_binding(context, &bindings.items[binding_index])) {
                            free_visible_match_binding_set(&bindings);
                            resolver_pop_scope(context);
                            return false;
                        }
                    }
                }
                free_visible_match_binding_set(&bindings);

                if (!validate_stmt_condition_expr(context,
                                                   stmt->as.if_stmt.clauses[clause_index].condition,
                                                   "AE1102",
                                                   "if statement")) {
                    if (pushed_binding_scope) {
                        resolver_pop_scope(context);
                    }
                    return false;
                }

                if (!resolve_block(context, stmt->as.if_stmt.clauses[clause_index].block, allow_self)) {
                    if (pushed_binding_scope) {
                        resolver_pop_scope(context);
                    }
                    return false;
                }
                if (pushed_binding_scope) {
                    resolver_pop_scope(context);
                }
            }
            /* else body: per §3.3, all match bindings are NOT visible in
             * else body; resolve normally without registering bindings. */
            return resolve_block(context, stmt->as.if_stmt.else_block, allow_self);

        case FENG_STMT_MATCH:
            return resolve_and_validate_match_common(context,
                                                     NULL,
                                                     stmt->as.match_stmt.target,
                                                     stmt->as.match_stmt.branches,
                                                     stmt->as.match_stmt.branch_count,
                                                     stmt->as.match_stmt.else_block,
                                                     stmt->token,
                                                     false,
                                                     allow_self);

        case FENG_STMT_WHILE: {
            bool ok;
            VisibleMatchBindingSet bindings;
            bool pushed_binding_scope = false;
            size_t binding_index;

            bindings.items = NULL;
            bindings.count = 0U;
            bindings.capacity = 0U;

            if (!resolve_expr(context, stmt->as.while_stmt.condition, allow_self)) {
                free_visible_match_binding_set(&bindings);
                return false;
            }
            /* Collect visible match bindings from while condition. The
             * binding is semantically registered once; codegen re-emits the
             * binding on each iteration when re-evaluating the condition.
             * Register BEFORE validating the condition so the binding's type
             * is available to infer_expr_type. */
            if (!collect_visible_match_bindings(stmt->as.while_stmt.condition, &bindings)) {
                free_visible_match_binding_set(&bindings);
                return false;
            }
            if (bindings.count > 0U) {
                if (!resolver_push_scope(context)) {
                    free_visible_match_binding_set(&bindings);
                    return false;
                }
                pushed_binding_scope = true;
                for (binding_index = 0U; binding_index < bindings.count; ++binding_index) {
                    if (!register_visible_match_binding(context, &bindings.items[binding_index])) {
                        free_visible_match_binding_set(&bindings);
                        resolver_pop_scope(context);
                        return false;
                    }
                }
            }
            free_visible_match_binding_set(&bindings);

            if (!validate_stmt_condition_expr(
                    context,
                    stmt->as.while_stmt.condition,
                    "AE1202",
                    "while statement")) {
                if (pushed_binding_scope) {
                    resolver_pop_scope(context);
                }
                return false;
            }

            context->loop_depth += 1U;
            ok = resolve_block(context, stmt->as.while_stmt.body, allow_self);
            context->loop_depth -= 1U;
            if (pushed_binding_scope) {
                resolver_pop_scope(context);
            }
            return ok;
        }

        case FENG_STMT_FOR: {
            bool ok;

            if (!resolver_push_scope(context)) {
                return false;
            }

            if (stmt->as.for_stmt.is_for_in) {
                InferredExprType iter_type;
                const FengTypeRef *element_type_ref = NULL;
                bool iter_protocol_resolved = false;

                ok = resolve_expr(context, stmt->as.for_stmt.iter_expr, allow_self);
                if (ok) {
                    iter_type = infer_expr_type(context, stmt->as.for_stmt.iter_expr);
                    /* for-in 的 iter()/next() 调用由 codegen 合成，源码 AST
                     * 没有可供后续依赖收集读取的 call owner。保存已经解析的
                     * iterable 表达式类型，作为该 lowering 的语义事实。 */
                    ok = record_type_fact_for_site(
                        context,
                        stmt->as.for_stmt.iter_expr,
                        iter_type);
                }
                if (ok) {
                    if (iter_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
                        iter_type.type_ref != NULL &&
                        iter_type.type_ref->kind == FENG_TYPE_REF_ARRAY) {
                        element_type_ref = iter_type.type_ref->as.inner;
                    } else {
                        /* Try iterator protocol: resolve type decl and scan
                         * for @iterable / @iterator annotations. */
                        FengStmt *mutable_stmt = (FengStmt *)stmt;
                        const FengDecl *iter_decl = NULL;
                        const FengTypeRef *iter_type_ref = NULL;

                        if (iter_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
                            iter_type.type_ref != NULL) {
                            iter_decl = resolve_type_ref_decl(context, iter_type.type_ref);
                            iter_type_ref = iter_type.type_ref;
                        } else if (iter_type.kind == FENG_INFERRED_EXPR_TYPE_DECL) {
                            iter_decl = iter_type.type_decl;
                        }

                        {
                            const FengTypeMember *iterable_m = NULL;
                            const FengTypeMember *iterator_m = NULL;

                            /* Search type decl members first. */
                            if (iter_decl != NULL && iter_decl->kind == FENG_DECL_TYPE) {
                                iterable_m = find_iterable_method(iter_decl);
                                iterator_m = find_iterator_method(iter_decl);
                            }

                            /* If not found on type decl, search fit blocks. */
                            if (iterable_m == NULL && iterator_m == NULL) {
                                FengSlice empty_name = {NULL, 0U};
                                const FengTypeMember *fit_result = NULL;

                                (void)visit_visible_fit_methods_for_owner_type(
                                    context, iter_decl, iter_type, empty_name,
                                    false, false, fit_iterable_visitor, &fit_result);
                                if (fit_result != NULL) {
                                    iterable_m = fit_result;
                                } else {
                                    (void)visit_visible_fit_methods_for_owner_type(
                                        context, iter_decl, iter_type, empty_name,
                                        false, false, fit_iterator_visitor, &fit_result);
                                    if (fit_result != NULL) {
                                        iterator_m = fit_result;
                                    }
                                }
                            }

                            if (iterable_m != NULL) {
                                /* Container with @iterable: resolve cursor type. */
                                const FengTypeRef *cursor_type_ref =
                                    iterable_m->as.callable.return_type;
                                const FengDecl *cursor_decl = NULL;
                                const FengTypeMember *cursor_iter_m = NULL;

                                /* Substitute container type params in the cursor type ref. */
                                if (iter_decl != NULL &&
                                    iter_decl->kind == FENG_DECL_TYPE &&
                                    iter_decl->as.type_decl.type_param_count > 0U &&
                                    iter_type_ref != NULL &&
                                    iter_type_ref->kind == FENG_TYPE_REF_NAMED &&
                                    iter_type_ref->as.named.type_arg_count ==
                                        iter_decl->as.type_decl.type_param_count) {
                                    FengTypeRef *subst = clone_type_ref_substituting_type_params(
                                        context->program,
                                        cursor_type_ref,
                                        iter_decl->as.type_decl.type_params,
                                        iter_decl->as.type_decl.type_param_count,
                                        iter_type_ref->as.named.type_args);
                                    if (subst != NULL &&
                                        resolver_track_synthetic_type_ref(context, subst)) {
                                        cursor_type_ref = subst;
                                    }
                                }

                                cursor_decl = resolve_type_ref_decl(context, cursor_type_ref);
                                if (cursor_decl != NULL) {
                                    cursor_iter_m = find_iterator_method(cursor_decl);
                                }
                                if (cursor_iter_m != NULL) {
                                    const FengTypeRef *result_type_ref =
                                        cursor_iter_m->as.callable.return_type;

                                    /* Substitute cursor type params in the result type ref. */
                                    if (cursor_decl->kind == FENG_DECL_TYPE &&
                                        cursor_decl->as.type_decl.type_param_count > 0U &&
                                        cursor_type_ref->kind == FENG_TYPE_REF_NAMED &&
                                        cursor_type_ref->as.named.type_arg_count ==
                                            cursor_decl->as.type_decl.type_param_count) {
                                        FengTypeRef *subst = clone_type_ref_substituting_type_params(
                                            context->program,
                                            result_type_ref,
                                            cursor_decl->as.type_decl.type_params,
                                            cursor_decl->as.type_decl.type_param_count,
                                            cursor_type_ref->as.named.type_args);
                                        if (subst != NULL &&
                                            resolver_track_synthetic_type_ref(context, subst)) {
                                            result_type_ref = subst;
                                        }
                                    }

                                    const FengDecl *ret_tuple_decl =
                                        resolve_type_ref_decl(context, result_type_ref);
                                    const FengTypeMember *second_field =
                                        tuple_field_member_at(ret_tuple_decl, 1U);

                                    if (second_field != NULL && second_field->as.field.type != NULL) {
                                        const FengTypeRef *elem_ref = second_field->as.field.type;

                                        /* Substitute result tuple type params in element type. */
                                        if (ret_tuple_decl != NULL &&
                                            ret_tuple_decl->kind == FENG_DECL_TYPE &&
                                            ret_tuple_decl->as.type_decl.type_param_count > 0U &&
                                            result_type_ref->kind == FENG_TYPE_REF_NAMED &&
                                            result_type_ref->as.named.type_arg_count ==
                                                ret_tuple_decl->as.type_decl.type_param_count) {
                                            FengTypeRef *subst = clone_type_ref_substituting_type_params(
                                                context->program,
                                                elem_ref,
                                                ret_tuple_decl->as.type_decl.type_params,
                                                ret_tuple_decl->as.type_decl.type_param_count,
                                                result_type_ref->as.named.type_args);
                                            if (subst != NULL &&
                                                resolver_track_synthetic_type_ref(context, subst)) {
                                                elem_ref = subst;
                                            }
                                        }

                                        element_type_ref = elem_ref;
                                        mutable_stmt->as.for_stmt.iter_iterable_method = iterable_m;
                                        mutable_stmt->as.for_stmt.iter_iterator_method = cursor_iter_m;
                                        mutable_stmt->as.for_stmt.iter_cursor_type_decl = cursor_decl;
                                        /* Clone cursor/result type_refs for for_stmt storage.
                                         * The originals may be synthetic refs freed with the
                                         * ResolveContext; clones are owned by Analysis and
                                         * persist for post-analysis passes (reifiable_deps). */
                                        {
                                            FengTypeRef *pc = clone_type_ref_for_inference(cursor_type_ref);
                                            FengTypeRef *pr = clone_type_ref_for_inference(result_type_ref);

                                            if (pc != NULL && !analysis_track_synthetic_type_ref(
                                                                  context->analysis, pc)) {
                                                free_synthetic_type_ref(pc);
                                                pc = NULL;
                                            }
                                            if (pr != NULL && !analysis_track_synthetic_type_ref(
                                                                  context->analysis, pr)) {
                                                free_synthetic_type_ref(pr);
                                                pr = NULL;
                                            }
                                            mutable_stmt->as.for_stmt.iter_cursor_type_ref = pc;
                                            mutable_stmt->as.for_stmt.iter_result_type_ref = pr;
                                        }
                                        iter_protocol_resolved = true;
                                    }
                                }
                            } else if (iterator_m != NULL) {
                                /* Self-cursor: type itself has @iterator. */
                                const FengTypeRef *result_type_ref =
                                    iterator_m->as.callable.return_type;

                                /* Substitute self-cursor type params in the result type ref. */
                                if (iter_decl != NULL &&
                                    iter_decl->kind == FENG_DECL_TYPE &&
                                    iter_decl->as.type_decl.type_param_count > 0U &&
                                    iter_type_ref != NULL &&
                                    iter_type_ref->kind == FENG_TYPE_REF_NAMED &&
                                    iter_type_ref->as.named.type_arg_count ==
                                        iter_decl->as.type_decl.type_param_count) {
                                    FengTypeRef *subst = clone_type_ref_substituting_type_params(
                                        context->program,
                                        result_type_ref,
                                        iter_decl->as.type_decl.type_params,
                                        iter_decl->as.type_decl.type_param_count,
                                        iter_type_ref->as.named.type_args);
                                    if (subst != NULL &&
                                        resolver_track_synthetic_type_ref(context, subst)) {
                                        result_type_ref = subst;
                                    }
                                }

                                const FengDecl *ret_tuple_decl =
                                    resolve_type_ref_decl(context, result_type_ref);
                                const FengTypeMember *second_field =
                                    tuple_field_member_at(ret_tuple_decl, 1U);

                                if (second_field != NULL && second_field->as.field.type != NULL) {
                                    const FengTypeRef *elem_ref = second_field->as.field.type;

                                    /* Substitute result tuple type params in element type. */
                                    if (ret_tuple_decl != NULL &&
                                        ret_tuple_decl->kind == FENG_DECL_TYPE &&
                                        ret_tuple_decl->as.type_decl.type_param_count > 0U &&
                                        result_type_ref->kind == FENG_TYPE_REF_NAMED &&
                                        result_type_ref->as.named.type_arg_count ==
                                            ret_tuple_decl->as.type_decl.type_param_count) {
                                        FengTypeRef *subst = clone_type_ref_substituting_type_params(
                                            context->program,
                                            elem_ref,
                                            ret_tuple_decl->as.type_decl.type_params,
                                            ret_tuple_decl->as.type_decl.type_param_count,
                                            result_type_ref->as.named.type_args);
                                        if (subst != NULL &&
                                            resolver_track_synthetic_type_ref(context, subst)) {
                                            elem_ref = subst;
                                        }
                                    }

                                    element_type_ref = elem_ref;
                                    mutable_stmt->as.for_stmt.iter_iterable_method = NULL;
                                    mutable_stmt->as.for_stmt.iter_iterator_method = iterator_m;
                                    mutable_stmt->as.for_stmt.iter_cursor_type_decl = iter_decl;
                                    /* Clone cursor/result type_refs for persistent
                                     * for_stmt storage (same pattern as @iterable path). */
                                    {
                                        FengTypeRef *pc = clone_type_ref_for_inference(iter_type_ref);
                                        FengTypeRef *pr = clone_type_ref_for_inference(result_type_ref);

                                        if (pc != NULL && !analysis_track_synthetic_type_ref(
                                                              context->analysis, pc)) {
                                            free_synthetic_type_ref(pc);
                                            pc = NULL;
                                        }
                                        if (pr != NULL && !analysis_track_synthetic_type_ref(
                                                              context->analysis, pr)) {
                                            free_synthetic_type_ref(pr);
                                            pr = NULL;
                                        }
                                        mutable_stmt->as.for_stmt.iter_cursor_type_ref = pc;
                                        mutable_stmt->as.for_stmt.iter_result_type_ref = pr;
                                    }
                                    iter_protocol_resolved = true;
                                }
                            }
                        }

                        if (!iter_protocol_resolved) {
                            char *type_name = format_inferred_expr_type_name(iter_type, context->pointer_size);
                            ok = resolver_append_error(
                                context,
                                stmt->as.for_stmt.iter_expr->token,
                                "AE0326", format_message(
                                    "type '%s' is not iterable (no @iterable or @iterator method found)",
                                    type_name != NULL ? type_name : "<unknown>"));
                            free(type_name);
                        }
                    }
                }
                if (ok && element_type_ref != NULL) {
                    const FengBinding *binding =
                        &stmt->as.for_stmt.iter_binding;

                    if (binding->is_destructure) {
                        const FengDecl *tuple_decl =
                            resolve_tuple_type_ref_decl(context, element_type_ref);

                        ok = add_destructure_locals_from_tuple_type(
                            context,
                            binding,
                            tuple_decl,
                            element_type_ref,
                            true,
                            true);
                    } else {
                        InferredExprType element_type =
                            inferred_expr_type_from_type_ref(element_type_ref);

                        ok = resolver_declare_local_typed_name(
                            context,
                            binding->token,
                            binding->name,
                            element_type,
                            binding->mutability);
                    }
                }
            } else {
                ok = resolve_stmt(context, stmt->as.for_stmt.init, allow_self) &&
                     resolve_expr(context, stmt->as.for_stmt.condition, allow_self) &&
                     validate_stmt_condition_expr(
                         context,
                         stmt->as.for_stmt.condition,
                         "AE1202",
                         "for statement") &&
                     resolve_stmt(context, stmt->as.for_stmt.update, allow_self);
            }
            if (ok) {
                context->loop_depth += 1U;
                ok = resolve_block(context, stmt->as.for_stmt.body, allow_self);
                context->loop_depth -= 1U;
            }

            resolver_pop_scope(context);
            return ok;
        }

        case FENG_STMT_RETURN:
            if (context->defer_depth > 0U) {
                return resolver_append_error(
                    context,
                    stmt->token,
                    "AE1501", duplicate_cstr("defer block cannot contain 'return'"));
            }
            {
                const FengTypeRef *prev_expected_type_ref = context->current_expr_expected_type_ref;
                bool ok;

                context->current_expr_expected_type_ref =
                    context->current_callable_signature != NULL
                        ? context->current_callable_signature->return_type
                        : NULL;
                ok = resolve_expr(context, stmt->as.return_value, allow_self);
                context->current_expr_expected_type_ref = prev_expected_type_ref;
                if (!ok) {
                    return false;
                }
            }
            return validate_return_stmt(context, stmt);

        case FENG_STMT_THROW:
            if (context->defer_depth > 0U) {
                return resolver_append_error(
                    context,
                    stmt->token,
                    "AE1502", duplicate_cstr("defer block cannot contain 'throw'"));
            }
            if (!resolve_throw_value_expr(context, stmt->as.throw_value, allow_self)) {
                return false;
            }
            if (!validate_throw_stmt(context, stmt)) {
                return false;
            }
            note_current_callable_exception_escape(context);
            return true;

        case FENG_STMT_BREAK:
            /* docs/specifications/feng-defer.md §4.2 弱限制：defer 块直接位置禁止 break。
             * 当 defer_depth > 0 且 loop_depth == 0 时，break 处于 defer 块
             * 直接位置（不在嵌套 for/while 内）。 */
            if (context->defer_depth > 0U && context->loop_depth == 0U) {
                return resolver_append_error(
                    context,
                    stmt->token,
                    "AE1504", duplicate_cstr("defer block cannot contain 'break'"));
            }
            return validate_loop_control_stmt(context, stmt, "break");

        case FENG_STMT_CONTINUE:
            if (context->defer_depth > 0U && context->loop_depth == 0U) {
                return resolver_append_error(
                    context,
                    stmt->token,
                    "AE1505", duplicate_cstr("defer block cannot contain 'continue'"));
            }
            return validate_loop_control_stmt(context, stmt, "continue");

        case FENG_STMT_DEFER: {
            /* docs/specifications/feng-defer.md §4.2 强禁止：defer 块内任何位置禁止嵌套 defer。
             * defer_depth > 0 表示当前已在 defer 块内（含嵌套子块）。 */
            bool ok;
            size_t saved_loop_depth;
            if (context->defer_depth > 0U) {
                return resolver_append_error(
                    context,
                    stmt->token,
                    "AE1503", duplicate_cstr("defer block cannot contain nested 'defer'"));
            }
            /* docs/specifications/feng-defer.md §4.3: defer 仅在函数体或函数体内嵌套的块作用域
             * 中合法。current_callable_signature != NULL 是”当前处于函数体或
             * lambda 函数体作用域内”的判据——resolve_callable / lambda 进入
             * 函数体时会设置此字段并在退出时还原。 */
            if (context->current_callable_signature == NULL) {
                return resolver_append_error(
                    context,
                    stmt->token,
                    "AE1506", duplicate_cstr("'defer' is only allowed inside function blocks"));
            }
            /* docs/specifications/feng-defer.md §4.2：defer 块内 loop_depth 相对于 defer 块本身
             * 计算。进入 defer 块时保存外层 loop_depth 并重置为 0，使直接位置的
             * break/continue 被检测到（defer_depth>0 && loop_depth==0）；嵌套
             * for/while 会自行递增 loop_depth，其中 break/continue 合法。 */
            context->defer_depth += 1U;
            saved_loop_depth = context->loop_depth;
            context->loop_depth = 0U;
            ok = resolve_block(context, stmt->as.defer_block, allow_self);
            context->loop_depth = saved_loop_depth;
            context->defer_depth -= 1U;
            return ok;
        }
    }

    return true;
}

static bool resolve_callable(ResolveContext *context,
                             const FengCallableSignature *callable,
                             bool allow_self) {
    size_t param_index;
    bool is_constructor = context->current_callable_body_member != NULL &&
                          context->current_callable_body_member->kind ==
                              FENG_TYPE_MEMBER_CONSTRUCTOR;
    bool is_finalizer = context->current_callable_body_member != NULL &&
                        context->current_callable_body_member->kind ==
                            FENG_TYPE_MEMBER_FINALIZER;
    const FengCallableSignature *previous_callable_signature =
        context->current_callable_signature;
    InferredExprType previous_callable_inferred_return_type =
        context->current_callable_inferred_return_type;
    bool previous_callable_saw_return = context->current_callable_saw_return;
    bool previous_callable_has_escaping_exception =
        context->current_callable_has_escaping_exception;
    size_t previous_exception_capture_depth = context->exception_capture_depth;
    size_t previous_loop_depth = context->loop_depth;
    ExpressionBranchBoundary previous_expression_branch_boundary =
        context->expression_branch_boundary;
    size_t previous_defer_depth = context->defer_depth;
    bool previous_self_capturable = context->self_capturable;
    /* G4-1/G4-14: push callable-level type params (method generics). */
    const TypeParamEntry *previous_type_params = context->type_params;
    size_t previous_type_param_count = context->type_param_count;
    bool ok;

    /* G4-14: reject method type param names that collide with outer type params. */
    if (callable->type_param_count > 0U && context->type_param_count > 0U) {
        size_t ni;
        for (ni = 0U; ni < callable->type_param_count; ++ni) {
            if (find_type_param(context, callable->type_params[ni].name) != NULL) {
                return resolver_append_error(
                    context,
                    callable->type_params[ni].token,
                    "AE1017", format_message("type parameter '%.*s' shadows an outer type parameter with the same name",
                                   (int)callable->type_params[ni].name.length,
                                   callable->type_params[ni].name.data));
            }
        }
    }

    /* Push method-level type parameters into scope. */
    if (!resolver_push_type_params(context, callable->type_params,
                                   callable->type_param_count,
                                   &previous_type_params, &previous_type_param_count)) {
        return false;
    }

    /* G4-3: Validate constraints on callable-level type parameters now that
     * they are in scope (needed if a constraint itself references a sibling
     * type param). */
    if (callable->type_param_count > 0U &&
        !validate_type_param_constraints(context,
                                         callable->type_params,
                                         callable->type_param_count)) {
        resolver_pop_type_params(context, previous_type_params, previous_type_param_count);
        return false;
    }

    context->current_callable_signature = callable;
    context->current_callable_inferred_return_type = callable_effective_return_type(context, callable);
    context->current_callable_saw_return = false;
    context->current_callable_has_escaping_exception = false;
    context->exception_capture_depth = 0U;
    context->loop_depth = 0U;
    context->expression_branch_boundary = EXPRESSION_BRANCH_BOUNDARY_NONE;
    context->defer_depth = 0U;
    /* Inside a member method or constructor body, lambdas may capture self. */
    if (allow_self && context->current_type_decl != NULL) {
        context->self_capturable = true;
    }

    if (!resolve_type_ref(context, callable->return_type, true)) {
        resolver_pop_type_params(context, previous_type_params, previous_type_param_count);
        context->current_callable_inferred_return_type = previous_callable_inferred_return_type;
        context->current_callable_saw_return = previous_callable_saw_return;
        context->current_callable_has_escaping_exception = previous_callable_has_escaping_exception;
        context->exception_capture_depth = previous_exception_capture_depth;
        context->loop_depth = previous_loop_depth;
        context->expression_branch_boundary = previous_expression_branch_boundary;
        context->defer_depth = previous_defer_depth;
        context->current_callable_signature = previous_callable_signature;
        context->self_capturable = previous_self_capturable;
        return false;
    }

    for (param_index = 0U; param_index < callable->param_count; ++param_index) {
        if (!resolve_type_ref(context, callable->params[param_index].type, false)) {
            resolver_pop_type_params(context, previous_type_params, previous_type_param_count);
            context->current_callable_inferred_return_type = previous_callable_inferred_return_type;
            context->current_callable_saw_return = previous_callable_saw_return;
            context->current_callable_has_escaping_exception = previous_callable_has_escaping_exception;
            context->exception_capture_depth = previous_exception_capture_depth;
            context->loop_depth = previous_loop_depth;
            context->expression_branch_boundary = previous_expression_branch_boundary;
            context->defer_depth = previous_defer_depth;
            context->current_callable_signature = previous_callable_signature;
            context->self_capturable = previous_self_capturable;
            return false;
        }
    }

    if (callable->body == NULL) {
        resolver_pop_type_params(context, previous_type_params, previous_type_param_count);
        context->current_callable_inferred_return_type = previous_callable_inferred_return_type;
        context->current_callable_saw_return = previous_callable_saw_return;
        context->current_callable_has_escaping_exception = previous_callable_has_escaping_exception;
        context->exception_capture_depth = previous_exception_capture_depth;
        context->loop_depth = previous_loop_depth;
        context->expression_branch_boundary = previous_expression_branch_boundary;
        context->defer_depth = previous_defer_depth;
        context->current_callable_signature = previous_callable_signature;
        context->self_capturable = previous_self_capturable;
        return true;
    }

    if (is_constructor) {
        resolver_clear_current_constructor_bindings(context);
    }

    if (!resolver_push_scope(context)) {
        if (is_constructor) {
            resolver_clear_current_constructor_bindings(context);
        }
        resolver_pop_type_params(context, previous_type_params, previous_type_param_count);
        context->current_callable_inferred_return_type = previous_callable_inferred_return_type;
        context->current_callable_saw_return = previous_callable_saw_return;
        context->current_callable_has_escaping_exception = previous_callable_has_escaping_exception;
        context->exception_capture_depth = previous_exception_capture_depth;
        context->loop_depth = previous_loop_depth;
        context->expression_branch_boundary = previous_expression_branch_boundary;
        context->defer_depth = previous_defer_depth;
        context->current_callable_signature = previous_callable_signature;
        context->self_capturable = previous_self_capturable;
        return false;
    }

    ok = true;
    for (param_index = 0U; param_index < callable->param_count && ok; ++param_index) {
        ok = resolver_declare_local_typed_name(
            context,
            callable->params[param_index].token,
            callable->params[param_index].name,
            inferred_expr_type_from_type_ref(callable->params[param_index].type),
            callable->params[param_index].mutability);
    }
    if (ok) {
        ok = resolve_block_contents(context, callable->body, allow_self);
    }

    resolver_pop_scope(context);
    if (is_constructor) {
        resolver_clear_current_constructor_bindings(context);
    }
    if (ok && !is_constructor && !is_finalizer) {
        InferredExprType resolved_return_type =
            callable->return_type != NULL
                ? inferred_expr_type_from_return_type_ref(callable->return_type)
                : context->current_callable_saw_return
                      ? context->current_callable_inferred_return_type
                      : inferred_expr_type_builtin("void");

        if (inferred_expr_type_is_known(resolved_return_type) &&
            !inferred_expr_type_is_void(resolved_return_type) &&
            callable_body_can_fall_through(callable->body)) {
            (void)resolver_append_error(
                context,
                callable->token,
                "AE0515",
                format_message(
                    "non-void callable '%.*s' can reach the end of its body without returning a value",
                    (int)callable->name.length,
                    callable->name.data));
            ok = false;
        }
    }
    if (ok && callable->return_type == NULL && !is_constructor) {
        InferredExprType inferred_return_type =
            context->current_callable_saw_return ? context->current_callable_inferred_return_type
                                                : inferred_expr_type_builtin("void");

        if (inferred_expr_type_is_known(inferred_return_type) &&
            !cache_callable_return_type(context, callable, inferred_return_type)) {
            ok = false;
        }
    }
    if (ok && !cache_callable_exception_escape(
                  context, callable, context->current_callable_has_escaping_exception)) {
        ok = false;
    }
    if (ok) {
        InferredExprType resolved_return_type = callable->return_type != NULL
                                                    ? inferred_expr_type_from_type_ref(callable->return_type)
                                                    : inferred_expr_type_builtin("void");

        if (!is_constructor && callable->return_type == NULL && context->current_callable_saw_return) {
            resolved_return_type = context->current_callable_inferred_return_type;
        }

        if (!record_type_fact_for_site(context, callable, resolved_return_type)) {
            ok = false;
        }
    }
    resolver_pop_type_params(context, previous_type_params, previous_type_param_count);
    context->current_callable_inferred_return_type = previous_callable_inferred_return_type;
    context->current_callable_saw_return = previous_callable_saw_return;
    context->current_callable_has_escaping_exception = previous_callable_has_escaping_exception;
    context->exception_capture_depth = previous_exception_capture_depth;
    context->loop_depth = previous_loop_depth;
    context->expression_branch_boundary = previous_expression_branch_boundary;
    context->defer_depth = previous_defer_depth;
    context->current_callable_signature = previous_callable_signature;
    context->self_capturable = previous_self_capturable;
    return ok;
}

/* ===== Contract validation: spec parent specs / type-declared specs / fit ===== */

static bool slice_eq(FengSlice a, FengSlice b) {
    return a.length == b.length &&
           (a.length == 0U || memcmp(a.data, b.data, a.length) == 0);
}

static bool spec_parent_reaches_recursive(const ResolveContext *ctx,
                                          const FengDecl *current,
                                          const FengDecl *target,
                                          const FengDecl ***visited,
                                          size_t *visited_count,
                                          size_t *visited_capacity) {
    size_t i;

    if (current == NULL || current->kind != FENG_DECL_SPEC) {
        return false;
    }

    for (i = 0U; i < current->as.spec_decl.parent_spec_count; ++i) {
        const FengDecl *next = resolve_type_ref_decl(ctx, current->as.spec_decl.parent_specs[i]);
        size_t j;
        bool seen;

        if (next == NULL || next->kind != FENG_DECL_SPEC) {
            continue;
        }
        if (next == target) {
            return true;
        }
        seen = false;
        for (j = 0U; j < *visited_count; ++j) {
            if ((*visited)[j] == next) {
                seen = true;
                break;
            }
        }
        if (seen) {
            continue;
        }
        if (!append_raw((void **)visited, visited_count, visited_capacity,
                        sizeof(**visited), &next)) {
            return false;
        }
        if (spec_parent_reaches_recursive(ctx, next, target, visited, visited_count,
                                          visited_capacity)) {
            return true;
        }
    }
    return false;
}

static bool spec_collect_closure(const ResolveContext *ctx,
                                 const FengDecl *spec_decl,
                                 const FengDecl ***out_set,
                                 size_t *out_count,
                                 size_t *out_capacity) {
    size_t i;
    size_t k;

    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC) {
        return true;
    }
    for (k = 0U; k < *out_count; ++k) {
        if ((*out_set)[k] == spec_decl) {
            return true;
        }
    }
    /* Recurse into parent specs first so that closure order matches the
     * codegen UserSpec member registration order (parents before self).
     * This keeps witness->members[] indices aligned with s->members[]. */
    for (i = 0U; i < spec_decl->as.spec_decl.parent_spec_count; ++i) {
        const FengDecl *next = resolve_type_ref_decl(ctx, spec_decl->as.spec_decl.parent_specs[i]);

        if (next == NULL || next->kind != FENG_DECL_SPEC) {
            continue;
        }
        if (!spec_collect_closure(ctx, next, out_set, out_count, out_capacity)) {
            return false;
        }
    }
    if (!append_raw((void **)out_set, out_count, out_capacity,
                    sizeof(**out_set), &spec_decl)) {
        return false;
    }
    return true;
}

static bool validate_spec_parent_spec_list(ResolveContext *context, const FengDecl *spec_decl) {
    size_t i;
    size_t j;

    for (i = 0U; i < spec_decl->as.spec_decl.parent_spec_count; ++i) {
        const FengTypeRef *r = spec_decl->as.spec_decl.parent_specs[i];
        const FengDecl *resolved = resolve_type_ref_decl(context, r);

        if (resolved == NULL || resolved->kind != FENG_DECL_SPEC) {
            char *target_name = format_type_ref_name(r);
            bool ok = resolver_append_error(
                context, r->token,
                "AE0613", format_message(
                    "spec '%.*s' parent spec list must contain only spec types but found '%s'",
                    (int)spec_decl->as.spec_decl.name.length,
                    spec_decl->as.spec_decl.name.data,
                    target_name != NULL ? target_name : "<unknown>"));

            free(target_name);
            return ok;
        }
        if (resolved->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            return resolver_append_error(
                context,
                r->token,
                "AE0613", format_message("object-form spec parent list can only contain object-form specs"));
        }
        for (j = 0U; j < i; ++j) {
            const FengDecl *prev = resolve_type_ref_decl(context, spec_decl->as.spec_decl.parent_specs[j]);

            if (prev == resolved) {
                return resolver_append_error(
                    context, r->token,
                    "AE0614", format_message(
                        "spec '%.*s' lists '%.*s' more than once in its parent spec list",
                        (int)spec_decl->as.spec_decl.name.length,
                        spec_decl->as.spec_decl.name.data,
                        (int)resolved->as.spec_decl.name.length,
                        resolved->as.spec_decl.name.data));
            }
        }
    }

    {
        const FengDecl **visited = NULL;
        size_t visited_count = 0U;
        size_t visited_capacity = 0U;
        bool cycle = spec_parent_reaches_recursive(context, spec_decl, spec_decl,
                                                   &visited, &visited_count, &visited_capacity);

        free(visited);
        if (cycle) {
            return resolver_append_error(
                context, spec_decl->token,
                "AE0614", format_message(
                    "spec '%.*s' forms a cycle through its parent spec list",
                    (int)spec_decl->as.spec_decl.name.length,
                    spec_decl->as.spec_decl.name.data));
        }
    }
    return true;
}

/* Validate that an object-form spec only declares contract members: fields and
 * method signatures. Constructor and finalizer declarations are syntactically
 * representable, but semantically belong only to concrete type definitions. */
static bool validate_object_spec_member_kinds(ResolveContext *context, const FengDecl *spec_decl) {
    size_t i;

    if (context == NULL || spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return true;
    }

    for (i = 0U; i < spec_decl->as.spec_decl.as.object.member_count; ++i) {
        const FengTypeMember *member = spec_decl->as.spec_decl.as.object.members[i];

        if (member == NULL) {
            continue;
        }
        if (member->kind == FENG_TYPE_MEMBER_FINALIZER) {
            if (!resolver_append_error(
                    context,
                    member->token,
                    "AE0620", format_message(
                        "object-form spec '%.*s' cannot declare a finalizer",
                        (int)spec_decl->as.spec_decl.name.length,
                        spec_decl->as.spec_decl.name.data))) {
                return false;
            }
            return false;
        }
    }

    return true;
}

/* Reject callable-local type parameters on object-form spec methods before
 * their signatures enter ordinary resolution. The parser and AST continue to
 * preserve this syntactically valid shape, but the current witness ABI cannot
 * route a dynamically selected implementation together with that
 * implementation's matching descriptor subtree. */
static bool validate_object_spec_method_type_params(
    ResolveContext *context,
    const FengTypeMember *member) {
    const FengCallableSignature *callable;

    if (context == NULL || member == NULL ||
        member->kind != FENG_TYPE_MEMBER_METHOD) {
        return true;
    }
    callable = &member->as.callable;
    if (callable->type_param_count == 0U) {
        return true;
    }
    return resolver_append_error(
               context,
               callable->type_params[0].token,
               "AE0331",
               format_message(
                   "object-form spec method '%.*s' cannot declare type parameters",
                   (int)callable->name.length,
                   callable->name.data)) &&
           false;
}

static const FengTypeMember *type_find_field(const FengDecl *type_decl, FengSlice name) {
    size_t i;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }
    for (i = 0U; i < type_decl->as.type_decl.member_count; ++i) {
        const FengTypeMember *m = type_decl->as.type_decl.members[i];

        if (!m->is_static &&
            m->kind == FENG_TYPE_MEMBER_FIELD &&
            slice_eq(m->as.field.name, name)) {
            return m;
        }
    }
    return NULL;
}

/* Requirement visibility compatibility is intentionally asymmetric: a
 * public spec requirement cannot be implemented by a seal member, while a
 * seal requirement may use either a public/default or seal implementation.
 * Every satisfaction and witness path must reuse this predicate. */
static bool spec_requirement_accepts_implementation(
    const FengTypeMember *spec_member,
    const FengTypeMember *implementation_member) {
    return spec_member != NULL && implementation_member != NULL &&
           (spec_member->visibility == FENG_VISIBILITY_PRIVATE ||
            implementation_member->visibility != FENG_VISIBILITY_PRIVATE);
}

/* Return whether a fit declared in the current package may use private
 * members owned by `target_type_decl` as spec requirement implementations.
 * Imported modules come from dependency packages; their private field
 * skeletons exist only for layout recovery and must not become witnesses. */
static bool fit_may_use_target_private_implementations(
    const ResolveContext *ctx,
    const FengDecl *target_type_decl) {
    const FengSemanticModule *target_module;

    if (ctx == NULL || ctx->analysis == NULL || target_type_decl == NULL) {
        return false;
    }
    target_module = find_decl_provider_module(ctx->analysis, target_type_decl);
    return target_module != NULL &&
           target_module->origin == FENG_SEMANTIC_MODULE_ORIGIN_LOCAL;
}

/* Close one requirement member surface against its object-spec owner, when
 * the caller is comparing a concrete generic spec instance. */
static const FengTypeRef *close_spec_requirement_member_type_ref(
    ResolveContext *ctx,
    const FengDecl *spec_decl,
    const FengTypeRef *spec_type_ref,
    const FengTypeRef *member_type_ref) {
    if (spec_decl == NULL || spec_type_ref == NULL) {
        return member_type_ref;
    }
    return substitute_spec_member_type_ref_for_instance(
        ctx, spec_decl, spec_type_ref, member_type_ref);
}

/* Close one implementation member surface against the concrete subject and
 * an optional array-fit target. Declaration-time comparisons without a
 * concrete subject intentionally retain the original owner parameter names. */
static const FengTypeRef *close_spec_implementation_member_type_ref(
    ResolveContext *ctx,
    const FengDecl *source_type_decl,
    const FengTypeRef *source_type_ref,
    const FengDecl *fit_decl,
    const FengTypeRef *member_type_ref) {
    const FengTypeRef *closed = member_type_ref;
    InferredExprType source_type;

    if (source_type_ref == NULL) {
        return closed;
    }
    source_type = inferred_expr_type_from_type_ref(source_type_ref);
    closed = substitute_type_ref_for_owner_instance(
        ctx, source_type_decl, source_type, closed);
    return substitute_type_ref_for_fit_instance(
        ctx, fit_decl, source_type, closed);
}

/* Compare one object-spec requirement and implementation callable after
 * closing both optional owner instances. All satisfaction and witness paths
 * share this routine so owner substitution and signature comparison cannot
 * diverge between declaration validation and runtime slot selection. */
static bool callable_signatures_match_for_satisfaction_instances(
    ResolveContext *ctx,
    const FengDecl *spec_decl,
    const FengTypeRef *spec_type_ref,
    const FengDecl *source_type_decl,
    const FengTypeRef *source_type_ref,
    const FengDecl *fit_decl,
    const FengCallableSignature *spec_sig,
    const FengCallableSignature *type_sig) {
    size_t index;

    if (ctx == NULL || spec_sig == NULL || type_sig == NULL ||
        spec_sig->type_param_count != type_sig->type_param_count ||
        spec_sig->param_count != type_sig->param_count) {
        return false;
    }
    for (index = 0U; index < spec_sig->param_count; ++index) {
        const FengTypeRef *expected = close_spec_requirement_member_type_ref(
            ctx,
            spec_decl,
            spec_type_ref,
            spec_sig->params[index].type);
        const FengTypeRef *actual = close_spec_implementation_member_type_ref(
            ctx,
            source_type_decl,
            source_type_ref,
            fit_decl,
            type_sig->params[index].type);
        if (spec_sig->params[index].is_variadic !=
            type_sig->params[index].is_variadic) {
            return false;
        }
        if (!type_refs_semantically_equal(ctx, expected, actual)) {
            return false;
        }
    }
    {
        const FengTypeRef *expected = close_spec_requirement_member_type_ref(
            ctx, spec_decl, spec_type_ref, spec_sig->return_type);
        const FengTypeRef *actual = close_spec_implementation_member_type_ref(
            ctx,
            source_type_decl,
            source_type_ref,
            fit_decl,
            type_sig->return_type);
        if (!type_refs_semantically_equal(ctx, expected, actual)) {
            return false;
        }
    }
    return true;
}

static bool callable_signatures_match_for_satisfaction(const ResolveContext *ctx,
                                                       const FengCallableSignature *spec_sig,
                                                       const FengCallableSignature *type_sig) {
    return callable_signatures_match_for_satisfaction_instances(
        (ResolveContext *)ctx,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        spec_sig,
        type_sig);
}

static bool callable_signatures_match_for_satisfaction_in_spec_ref(
    ResolveContext *ctx,
    const FengDecl *spec_decl,
    const FengTypeRef *spec_type_ref,
    const FengCallableSignature *spec_sig,
    const FengCallableSignature *type_sig) {
    return callable_signatures_match_for_satisfaction_instances(
        ctx,
        spec_decl,
        spec_type_ref,
        NULL,
        NULL,
        NULL,
        spec_sig,
        type_sig);
}

/* Compare one requirement and implementation after closing both their spec
 * owner and concrete subject owner. This is used only after a nominal
 * relation has already been proved; it selects the declaration for a witness
 * slot without re-proving structural satisfaction. */
static bool callable_signatures_match_for_witness_instances(
    ResolveContext *ctx,
    const FengDecl *source_type_decl,
    const FengTypeRef *source_type_ref,
    const FengDecl *fit_decl,
    const FengDecl *spec_decl,
    const FengTypeRef *spec_type_ref,
    const FengCallableSignature *spec_sig,
    const FengCallableSignature *impl_sig) {
    return callable_signatures_match_for_satisfaction_instances(
        ctx,
        spec_decl,
        spec_type_ref,
        source_type_decl,
        source_type_ref,
        fit_decl,
        spec_sig,
        impl_sig);
}

/* Select one type-owned witness implementation against closed owner/spec
 * instances. Declaration-time validation remains authoritative for whether
 * the nominal relationship is legal. */
static const FengTypeMember *type_find_matching_method_for_witness(
    ResolveContext *ctx,
    const FengDecl *type_decl,
    const FengTypeRef *source_type_ref,
    const FengDecl *spec_decl,
    const FengTypeRef *spec_type_ref,
    const FengTypeMember *spec_member) {
    size_t member_index;

    if (ctx == NULL || type_decl == NULL || type_decl->kind != FENG_DECL_TYPE ||
        spec_decl == NULL || spec_type_ref == NULL || spec_member == NULL ||
        spec_member->kind != FENG_TYPE_MEMBER_METHOD) {
        return NULL;
    }
    for (member_index = 0U;
         member_index < type_decl->as.type_decl.member_count;
         ++member_index) {
        const FengTypeMember *member =
            type_decl->as.type_decl.members[member_index];

        if (member->kind == FENG_TYPE_MEMBER_METHOD &&
            member->is_static == spec_member->is_static &&
            slice_eq(member->as.callable.name,
                     spec_member->as.callable.name) &&
            spec_requirement_accepts_implementation(spec_member, member) &&
            callable_signatures_match_for_witness_instances(
                ctx,
                type_decl,
                source_type_ref,
                NULL,
                spec_decl,
                spec_type_ref,
                &spec_member->as.callable,
                &member->as.callable)) {
            return member;
        }
    }
    return NULL;
}

static const FengTypeMember *type_find_matching_method(
    const ResolveContext *ctx,
    const FengDecl *type_decl,
    const FengTypeMember *spec_member,
    const FengTypeMember *const *extra_methods,
    size_t extra_count) {
    const FengCallableSignature *spec_sig = &spec_member->as.callable;
    size_t i;

    if (type_decl != NULL && type_decl->kind == FENG_DECL_TYPE) {
        for (i = 0U; i < type_decl->as.type_decl.member_count; ++i) {
            const FengTypeMember *m = type_decl->as.type_decl.members[i];

            if (m->is_static == spec_member->is_static &&
                m->kind == FENG_TYPE_MEMBER_METHOD &&
                slice_eq(m->as.callable.name, spec_sig->name) &&
                spec_requirement_accepts_implementation(spec_member, m) &&
                callable_signatures_match_for_satisfaction(ctx, spec_sig, &m->as.callable)) {
                return m;
            }
        }
    }
    for (i = 0U; i < extra_count; ++i) {
        const FengTypeMember *m = extra_methods[i];

        if (m->is_static == spec_member->is_static &&
            m->kind == FENG_TYPE_MEMBER_METHOD &&
            slice_eq(m->as.callable.name, spec_sig->name) &&
            spec_requirement_accepts_implementation(spec_member, m) &&
            callable_signatures_match_for_satisfaction(ctx, spec_sig, &m->as.callable)) {
            return m;
        }
    }
    return NULL;
}

static const FengTypeMember *type_find_matching_method_in_spec_ref(
    ResolveContext *ctx,
    const FengDecl *type_decl,
    const FengDecl *spec_decl,
    const FengTypeRef *spec_type_ref,
    const FengTypeMember *spec_member,
    const FengTypeMember *const *extra_methods,
    size_t extra_count,
    bool require_static,
    bool allow_type_private_implementations,
    bool require_compatible_visibility) {
    const FengCallableSignature *spec_sig = &spec_member->as.callable;
    size_t i;

    if (type_decl != NULL && type_decl->kind == FENG_DECL_TYPE) {
        for (i = 0U; i < type_decl->as.type_decl.member_count; ++i) {
            const FengTypeMember *m = type_decl->as.type_decl.members[i];

            if (m->is_static == require_static &&
                m->kind == FENG_TYPE_MEMBER_METHOD &&
                slice_eq(m->as.callable.name, spec_sig->name) &&
                (allow_type_private_implementations ||
                 m->visibility != FENG_VISIBILITY_PRIVATE) &&
                (!require_compatible_visibility ||
                 spec_requirement_accepts_implementation(spec_member, m)) &&
                callable_signatures_match_for_satisfaction_in_spec_ref(
                    ctx, spec_decl, spec_type_ref, spec_sig, &m->as.callable)) {
                return m;
            }
        }
    }
    for (i = 0U; i < extra_count; ++i) {
        const FengTypeMember *m = extra_methods[i];

        if (m->is_static == require_static &&
            m->kind == FENG_TYPE_MEMBER_METHOD &&
            slice_eq(m->as.callable.name, spec_sig->name) &&
            (!require_compatible_visibility ||
             spec_requirement_accepts_implementation(spec_member, m)) &&
            callable_signatures_match_for_satisfaction_in_spec_ref(
                ctx, spec_decl, spec_type_ref, spec_sig, &m->as.callable)) {
            return m;
        }
    }
    return NULL;
}

static const FengTypeMember *type_find_method_by_name(
    const FengDecl *type_decl,
    FengSlice name,
    const FengTypeMember *const *extra_methods,
    size_t extra_count,
    bool allow_type_private_implementations) {
    size_t i;

    if (type_decl != NULL && type_decl->kind == FENG_DECL_TYPE) {
        for (i = 0U; i < type_decl->as.type_decl.member_count; ++i) {
            const FengTypeMember *m = type_decl->as.type_decl.members[i];

            if (!m->is_static &&
                m->kind == FENG_TYPE_MEMBER_METHOD &&
                (allow_type_private_implementations ||
                 m->visibility != FENG_VISIBILITY_PRIVATE) &&
                slice_eq(m->as.callable.name, name)) {
                return m;
            }
        }
    }
    for (i = 0U; i < extra_count; ++i) {
        const FengTypeMember *m = extra_methods[i];

        if (!m->is_static &&
            m->kind == FENG_TYPE_MEMBER_METHOD &&
            slice_eq(m->as.callable.name, name)) {
            return m;
        }
    }
    return NULL;
}

typedef struct VisibleFitMethodMatchCtx {
    const ResolveContext *ctx;
    const FengDecl *spec_decl;
    const FengTypeRef *spec_type_ref;
    const FengTypeMember *spec_member;
    bool require_compatible_visibility;
    const FengTypeMember *match;
} VisibleFitMethodMatchCtx;

static bool visible_fit_matching_method_visitor(const FengTypeMember *member,
                                                const FengSemanticModule *fit_module,
                                                const FengDecl *fit_decl,
                                                void *userdata) {
    VisibleFitMethodMatchCtx *st = (VisibleFitMethodMatchCtx *)userdata;

    (void)fit_module;
    (void)fit_decl;
    if (st->require_compatible_visibility &&
        !spec_requirement_accepts_implementation(st->spec_member, member)) {
        return true;
    }
    if (callable_signatures_match_for_satisfaction_in_spec_ref(
            (ResolveContext *)st->ctx,
            st->spec_decl,
            st->spec_type_ref,
            &st->spec_member->as.callable,
            &member->as.callable)) {
        st->match = member;
        return false;
    }
    return true;
}

static const FengTypeMember *find_visible_fit_matching_method_in_spec_ref(
    const ResolveContext *ctx,
    const FengDecl *type_decl,
    const FengDecl *spec_decl,
    const FengTypeRef *spec_type_ref,
    const FengTypeMember *spec_member,
    bool require_static,
    bool require_compatible_visibility) {
    VisibleFitMethodMatchCtx st;

    if (ctx == NULL || !decl_is_named_fit_target(type_decl) ||
        spec_decl == NULL || spec_member == NULL ||
        spec_member->kind != FENG_TYPE_MEMBER_METHOD) {
        return NULL;
    }

    memset(&st, 0, sizeof(st));
    st.ctx = ctx;
    st.spec_decl = spec_decl;
    st.spec_type_ref = spec_type_ref;
    st.spec_member = spec_member;
    st.require_compatible_visibility = require_compatible_visibility;

    (void)visit_visible_fit_methods_for_type(ctx,
                                             type_decl,
                                             spec_member->as.callable.name,
                                             true,
                                             require_static,
                                             visible_fit_matching_method_visitor,
                                             &st);
    return st.match;
}

static bool verify_type_satisfies_spec(ResolveContext *ctx,
                                       const FengDecl *type_decl,
                                       const FengDecl *relation_owner_decl,
                                       const FengDecl *spec_decl,
                                       const FengTypeRef *spec_type_ref,
                                       FengToken err_token,
                                       const FengTypeMember *const *extra_methods,
                                       size_t extra_count,
                                       bool allow_type_private_implementations) {
    size_t i;

    if (spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return true;
    }

    for (i = 0U; i < spec_decl->as.spec_decl.as.object.member_count; ++i) {
        const FengTypeMember *spec_m = spec_decl->as.spec_decl.as.object.members[i];

        if (spec_m->kind == FENG_TYPE_MEMBER_FIELD) {
            const FengTypeMember *t = spec_m->is_static
                ? find_type_static_field_member(type_decl, spec_m->as.field.name)
                : type_find_field(type_decl, spec_m->as.field.name);

            if (t != NULL && !allow_type_private_implementations &&
                t->visibility == FENG_VISIBILITY_PRIVATE) {
                t = NULL;
            }

            if (t == NULL) {
                return resolver_append_error(
                    ctx, err_token,
                    "AE0701", format_message(
                        "type '%.*s' is missing field '%.*s' required by spec '%.*s'",
                        (int)decl_typeish_name(type_decl).length,
                        decl_typeish_name(type_decl).data,
                        (int)spec_m->as.field.name.length, spec_m->as.field.name.data,
                        (int)spec_decl->as.spec_decl.name.length,
                        spec_decl->as.spec_decl.name.data));
            }
            if (!spec_requirement_accepts_implementation(spec_m, t)) {
                return resolver_append_error(
                    ctx,
                    err_token,
                    "AE0707",
                    format_message(
                        "type '%.*s' member '%.*s' has visibility 'seal' and cannot satisfy public member required by spec '%.*s'",
                        (int)decl_typeish_name(type_decl).length,
                        decl_typeish_name(type_decl).data,
                        (int)spec_m->as.field.name.length,
                        spec_m->as.field.name.data,
                        (int)spec_decl->as.spec_decl.name.length,
                        spec_decl->as.spec_decl.name.data));
            }
            if (t->as.field.mutability != spec_m->as.field.mutability) {
                return resolver_append_error(
                    ctx, err_token,
                    "AE0702", format_message(
                        "type '%.*s' field '%.*s' mutability does not match spec '%.*s' (expected '%s')",
                        (int)decl_typeish_name(type_decl).length,
                        decl_typeish_name(type_decl).data,
                        (int)spec_m->as.field.name.length, spec_m->as.field.name.data,
                        (int)spec_decl->as.spec_decl.name.length,
                        spec_decl->as.spec_decl.name.data,
                        spec_m->as.field.mutability == FENG_MUTABILITY_LET ? "let" : "var"));
            }
            {
                const FengTypeRef *expected_field_type = substitute_spec_member_type_ref_for_instance(
                    ctx,
                    spec_decl,
                    spec_type_ref,
                    spec_m->as.field.type);
                if (!type_refs_semantically_equal(ctx, t->as.field.type, expected_field_type)) {
                    char *expected = format_type_ref_name(expected_field_type);
                    char *actual = format_type_ref_name(t->as.field.type);
                    bool ok = resolver_append_error(
                        ctx, err_token,
                        "AE0703", format_message(
                            "type '%.*s' field '%.*s' type '%s' does not match spec '%.*s' field type '%s'",
                            (int)decl_typeish_name(type_decl).length,
                            decl_typeish_name(type_decl).data,
                            (int)spec_m->as.field.name.length, spec_m->as.field.name.data,
                            actual != NULL ? actual : "<unknown>",
                            (int)spec_decl->as.spec_decl.name.length,
                            spec_decl->as.spec_decl.name.data,
                            expected != NULL ? expected : "<unknown>"));

                    free(expected);
                    free(actual);
                    return ok;
                }
            }
            if (!feng_semantic_record_spec_implementation_selection(
                    ctx->analysis,
                    ctx->module,
                    relation_owner_decl,
                    spec_decl,
                    spec_m,
                    t)) {
                return resolver_append_error(
                    ctx,
                    err_token,
                    "IE0001",
                    format_message(
                        "out of memory while recording spec implementation selection"));
            }
        } else if (spec_m->kind == FENG_TYPE_MEMBER_METHOD) {
            const FengTypeMember *match = type_find_matching_method_in_spec_ref(
                ctx,
                type_decl,
                spec_decl,
                spec_type_ref,
                spec_m,
                extra_methods,
                extra_count,
                spec_m->is_static,
                allow_type_private_implementations,
                /*require_compatible_visibility=*/true);

            if (match == NULL) {
                match = find_visible_fit_matching_method_in_spec_ref(
                    ctx,
                    type_decl,
                    spec_decl,
                    spec_type_ref,
                    spec_m,
                    spec_m->is_static,
                    /*require_compatible_visibility=*/true);
            }

            if (match == NULL) {
                const FengTypeMember *incompatible =
                    type_find_matching_method_in_spec_ref(
                        ctx,
                        type_decl,
                        spec_decl,
                        spec_type_ref,
                        spec_m,
                        extra_methods,
                        extra_count,
                        spec_m->is_static,
                        allow_type_private_implementations,
                        /*require_compatible_visibility=*/false);

                if (incompatible == NULL) {
                    incompatible = find_visible_fit_matching_method_in_spec_ref(
                        ctx,
                        type_decl,
                        spec_decl,
                        spec_type_ref,
                        spec_m,
                        spec_m->is_static,
                        /*require_compatible_visibility=*/false);
                }
                if (incompatible != NULL &&
                    !spec_requirement_accepts_implementation(spec_m,
                                                             incompatible)) {
                    return resolver_append_error(
                        ctx,
                        err_token,
                        "AE0707",
                        format_message(
                            "type '%.*s' member '%.*s' has visibility 'seal' and cannot satisfy public member required by spec '%.*s'",
                            (int)decl_typeish_name(type_decl).length,
                            decl_typeish_name(type_decl).data,
                            (int)spec_m->as.callable.name.length,
                            spec_m->as.callable.name.data,
                            (int)spec_decl->as.spec_decl.name.length,
                            spec_decl->as.spec_decl.name.data));
                }
                const FengTypeMember *named;

                if (spec_m->is_static) {
                    named = find_type_static_method_member(
                        type_decl, spec_m->as.callable.name);
                    if (named != NULL && !allow_type_private_implementations &&
                        named->visibility == FENG_VISIBILITY_PRIVATE) {
                        named = NULL;
                    }
                } else {
                    named = type_find_method_by_name(
                        type_decl,
                        spec_m->as.callable.name,
                        extra_methods,
                        extra_count,
                        allow_type_private_implementations);
                }

                if (named == NULL && spec_m->is_static) {
                    named = find_fit_static_method_member_for_type(
                        ctx,
                        type_decl,
                        spec_m->as.callable.name);
                } else if (named == NULL) {
                    named = find_fit_method_member_for_type(
                        ctx,
                        type_decl,
                        spec_m->as.callable.name);
                }

                if (named != NULL) {
                    return resolver_append_error(
                        ctx, err_token,
                        "AE0704", format_message(
                            "type '%.*s' method '%.*s' signature does not match spec '%.*s'",
                            (int)decl_typeish_name(type_decl).length,
                            decl_typeish_name(type_decl).data,
                            (int)spec_m->as.callable.name.length,
                            spec_m->as.callable.name.data,
                            (int)spec_decl->as.spec_decl.name.length,
                            spec_decl->as.spec_decl.name.data));
                }
                return resolver_append_error(
                    ctx, err_token,
                    "AE0705", format_message(
                        "type '%.*s' is missing method '%.*s' required by spec '%.*s'",
                        (int)decl_typeish_name(type_decl).length,
                        decl_typeish_name(type_decl).data,
                        (int)spec_m->as.callable.name.length,
                        spec_m->as.callable.name.data,
                        (int)spec_decl->as.spec_decl.name.length,
                        spec_decl->as.spec_decl.name.data));
            }
            if (!feng_semantic_record_spec_implementation_selection(
                    ctx->analysis,
                    ctx->module,
                    relation_owner_decl,
                    spec_decl,
                    spec_m,
                    match)) {
                return resolver_append_error(
                    ctx,
                    err_token,
                    "IE0001",
                    format_message(
                        "out of memory while recording spec implementation selection"));
            }
        }
    }
    return true;
}

/* Return whether one closed relation head is exactly the requested spec
 * instance, either directly or through the existing object-spec parent path. */
static bool spec_relation_head_instance_matches(
    const ResolveContext *ctx,
    const FengTypeRef *head_instance_ref,
    const FengTypeRef *spec_type_ref) {
    const FengDecl *head_decl;
    const FengDecl *spec_decl;
    ObjectSpecUpcastPath upcast_path;
    bool matches;

    if (ctx == NULL || head_instance_ref == NULL || spec_type_ref == NULL) {
        return false;
    }
    head_decl = resolve_type_ref_decl(ctx, head_instance_ref);
    spec_decl = resolve_type_ref_decl(ctx, spec_type_ref);
    if (head_decl == NULL || spec_decl == NULL ||
        head_decl->kind != FENG_DECL_SPEC || spec_decl->kind != FENG_DECL_SPEC) {
        return false;
    }
    if (head_decl == spec_decl) {
        return type_refs_semantically_equal(ctx,
                                            head_instance_ref,
                                            spec_type_ref);
    }
    matches = find_object_spec_upcast_path(
        ctx,
        inferred_expr_type_from_type_ref(head_instance_ref),
        spec_type_ref,
        &upcast_path);
    if (matches) {
        object_spec_upcast_path_free(&upcast_path);
    }
    return matches;
}

/* Close one declared-spec or fit-spec template against the concrete subject.
 * The relation source supplies provenance; current and imported declarations
 * use the same structured AST templates restored by the Symbol reader. */
static FengTypeRef *instantiate_spec_relation_template(
    const ResolveContext *ctx,
    const FengDecl *source_type_decl,
    const FengTypeRef *source_type_ref,
    const FengSpecRelationSource *source,
    const FengTypeRef *template_ref) {
    const FengTypeParam *type_params = NULL;
    size_t type_param_count = 0U;
    FengTypeRef *const *type_args = NULL;

    if (ctx == NULL || source == NULL || template_ref == NULL) {
        return NULL;
    }
    if (source->kind == FENG_SPEC_RELATION_SOURCE_DECLARED_HEAD ||
        source->kind == FENG_SPEC_RELATION_SOURCE_DECLARED_PARENT) {
        if (source_type_decl == NULL ||
            source_type_decl->kind != FENG_DECL_TYPE) {
            return NULL;
        }
        type_params = source_type_decl->as.type_decl.type_params;
        type_param_count = source_type_decl->as.type_decl.type_param_count;
    } else {
        const FengDecl *fit_decl = source->via_fit_decl;

        if (fit_decl == NULL || fit_decl->kind != FENG_DECL_FIT) {
            return NULL;
        }
        if (source_type_decl != NULL &&
            source_type_decl->kind == FENG_DECL_TYPE) {
            /* Generic fit target parameters are the target type's declared
             * parameters; fit syntax does not introduce a parallel list. */
            type_params = source_type_decl->as.type_decl.type_params;
            type_param_count = source_type_decl->as.type_decl.type_param_count;
        }
    }

    if (type_param_count > 0U) {
        FengTypeRef *closed_fit_target = NULL;

        /* Open generic declaration contexts retain the relation template.
         * Exact comparison below can prove only an equally open target; a
         * concrete mismatched instance still fails without guessing args. */
        if (source_type_ref == NULL) {
            return clone_type_ref_for_inference(template_ref);
        }
        if (source_type_ref->kind != FENG_TYPE_REF_NAMED ||
            source_type_ref->as.named.type_arg_count != type_param_count) {
            return NULL;
        }
        type_args = source_type_ref->as.named.type_args;
        if (source->kind == FENG_SPEC_RELATION_SOURCE_FIT_HEAD ||
            source->kind == FENG_SPEC_RELATION_SOURCE_FIT_PARENT) {
            closed_fit_target = clone_type_ref_substituting_type_params(
                ctx->program,
                source->via_fit_decl->as.fit_decl.target,
                type_params,
                type_param_count,
                type_args);
            if (closed_fit_target == NULL ||
                !type_refs_semantically_equal(ctx,
                                              closed_fit_target,
                                              source_type_ref)) {
                free_synthetic_type_ref(closed_fit_target);
                return NULL;
            }
            free_synthetic_type_ref(closed_fit_target);
        }
    } else if ((source->kind == FENG_SPEC_RELATION_SOURCE_FIT_HEAD ||
                source->kind == FENG_SPEC_RELATION_SOURCE_FIT_PARENT) &&
               source_type_ref != NULL &&
               !type_refs_semantically_equal(ctx,
                                             source->via_fit_decl->as.fit_decl.target,
                                             source_type_ref)) {
        return NULL;
    }

    return clone_type_ref_substituting_type_params(ctx->program, template_ref,
                                                   type_params,
                                                   type_param_count,
                                                   type_args);
}

/* Close every head template represented by one relation source and compare
 * the resulting direct or transitive spec instance with the requested type. */
static bool spec_relation_source_instantiates_type_ref(
    const ResolveContext *ctx,
    const FengDecl *source_type_decl,
    const FengTypeRef *source_type_ref,
    const FengSpecRelationSource *source,
    const FengTypeRef *spec_type_ref) {
    FengTypeRef *const *head_refs = NULL;
    size_t head_ref_count = 0U;
    size_t head_index;

    if (ctx == NULL || source == NULL || spec_type_ref == NULL ||
        source->via_spec_decl == NULL) {
        return false;
    }
    if (source->kind == FENG_SPEC_RELATION_SOURCE_DECLARED_HEAD ||
        source->kind == FENG_SPEC_RELATION_SOURCE_DECLARED_PARENT) {
        if (source_type_decl == NULL || source_type_decl->kind != FENG_DECL_TYPE) {
            return false;
        }
        head_refs = source_type_decl->as.type_decl.declared_specs;
        head_ref_count = source_type_decl->as.type_decl.declared_spec_count;
    } else {
        const FengDecl *fit_decl = source->via_fit_decl;

        if (fit_decl == NULL || fit_decl->kind != FENG_DECL_FIT) {
            return false;
        }
        head_refs = fit_decl->as.fit_decl.specs;
        head_ref_count = fit_decl->as.fit_decl.spec_count;
    }

    for (head_index = 0U; head_index < head_ref_count; ++head_index) {
        const FengTypeRef *head_ref = head_refs[head_index];
        const FengDecl *head_decl = resolve_type_ref_decl(ctx, head_ref);
        FengTypeRef *head_instance_ref;
        bool matches;

        if (head_decl != source->via_spec_decl) {
            continue;
        }
        head_instance_ref = instantiate_spec_relation_template(ctx,
                                                               source_type_decl,
                                                               source_type_ref,
                                                               source,
                                                               head_ref);
        if (head_instance_ref == NULL) {
            continue;
        }
        matches = spec_relation_head_instance_matches(ctx,
                                                      head_instance_ref,
                                                      spec_type_ref);
        free_synthetic_type_ref(head_instance_ref);
        if (matches) {
            return true;
        }
    }
    return false;
}

/* Prove one exact object-spec instance from the existing nominal relation
 * index. Structural satisfaction remains a declaration-time responsibility. */
static bool subject_satisfies_spec_type_ref(
    const ResolveContext *ctx,
    const FengDecl *source_type_decl,
    const FengTypeRef *source_type_ref,
    const FengSemanticSubjectKey *subject_key,
    const FengTypeRef *spec_type_ref) {
    const FengDecl *spec_decl;
    const FengSpecRelation *relation;
    size_t source_index;

    if (ctx == NULL || ctx->analysis == NULL || subject_key == NULL ||
        spec_type_ref == NULL) {
        return false;
    }
    spec_decl = resolve_type_ref_decl(ctx, spec_type_ref);
    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC) {
        return false;
    }
    if (spec_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
        return subject_key_satisfies_spec_decl(ctx, subject_key, spec_decl);
    }
    if (spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return false;
    }

    relation = feng_semantic_lookup_spec_relation(ctx->analysis,
                                                  subject_key,
                                                  spec_decl);
    if (relation == NULL) {
        return false;
    }
    for (source_index = 0U;
         source_index < relation->source_count;
         ++source_index) {
        const FengSpecRelationSource *source = &relation->sources[source_index];

        if (spec_relation_source_visible_from_context(ctx, source) &&
            spec_relation_source_instantiates_type_ref(ctx,
                                                       source_type_decl,
                                                       source_type_ref,
                                                       source,
                                                       spec_type_ref)) {
            return true;
        }
    }
    return false;
}

/* Declaration-only adapter for non-generic inferred subjects. Concrete
 * generic subjects must use type_ref_satisfies_spec_type_ref so their type
 * arguments participate in nominal relation closing. */
static bool type_decl_satisfies_spec_type_ref(const ResolveContext *ctx,
                                              const FengDecl *type_decl,
                                              const FengTypeRef *spec_type_ref) {
    FengSemanticSubjectKey subject_key;

    if (ctx == NULL || type_decl == NULL || spec_type_ref == NULL ||
        !decl_is_named_fit_target(type_decl)) {
        return false;
    }
    subject_key = feng_semantic_subject_key_for_type_decl(type_decl);
    return subject_satisfies_spec_type_ref(ctx,
                                           type_decl,
                                           NULL,
                                           &subject_key,
                                           spec_type_ref);
}

static bool type_ref_satisfies_spec_type_ref(const ResolveContext *ctx,
                                             const FengTypeRef *source_type_ref,
                                             const FengTypeRef *spec_type_ref) {
    const FengDecl *source_type_decl;
    const FengDecl *spec_decl;
    FengSemanticSubjectKey subject_key;

    if (ctx == NULL || source_type_ref == NULL || spec_type_ref == NULL) {
        return false;
    }
    source_type_decl = resolve_type_ref_decl(ctx, source_type_ref);
    spec_decl = resolve_type_ref_decl(ctx, spec_type_ref);
    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC) {
        return false;
    }

    if (source_type_decl != NULL &&
        source_type_decl->kind != FENG_DECL_TYPE &&
        !decl_is_enum_type(source_type_decl)) {
        return false;
    }
    if (!init_spec_witness_subject_key(source_type_decl,
                                       source_type_ref,
                                       ctx->pointer_size,
                                       &subject_key)) {
        return false;
    }
    return subject_satisfies_spec_type_ref(ctx,
                                           source_type_decl,
                                           source_type_ref,
                                           &subject_key,
                                           spec_type_ref);
}

/* One exact member requirement in an object-form spec instance. The owner
 * type ref is already projected through every generic parent edge and remains
 * compiler-owned by ResolveContext when synthetic. */
typedef struct ObjectSpecRequirementSurface {
    const FengTypeMember *member;
    const FengDecl *declaring_spec;
    const FengTypeRef *declaring_spec_type_ref;
} ObjectSpecRequirementSurface;

/* Compiler-only collection of a child-first logical requirement surface. */
typedef struct ObjectSpecRequirementSet {
    ObjectSpecRequirementSurface *items;
    size_t count;
    size_t capacity;
    const FengDecl **active_specs;
    size_t active_spec_count;
    size_t active_spec_capacity;
} ObjectSpecRequirementSet;

/* Return the closed owner view used to compare one requirement signature. */
static InferredExprType object_spec_requirement_owner_type(
    const ObjectSpecRequirementSurface *surface) {
    if (surface != NULL && surface->declaring_spec_type_ref != NULL) {
        return inferred_expr_type_from_type_ref(
            surface->declaring_spec_type_ref);
    }
    return inferred_expr_type_from_decl(
        surface != NULL ? surface->declaring_spec : NULL);
}

/* Compare two object-spec requirements after closing both owner instances.
 * Only truly equivalent declarations collapse; legal overloads remain. */
static bool object_spec_requirements_semantically_equivalent(
    ResolveContext *context,
    const ObjectSpecRequirementSurface *left,
    const ObjectSpecRequirementSurface *right) {
    const FengTypeMember *left_member;
    const FengTypeMember *right_member;

    if (left == NULL || right == NULL || left->member == NULL ||
        right->member == NULL || left->declaring_spec == NULL ||
        right->declaring_spec == NULL) {
        return false;
    }
    left_member = left->member;
    right_member = right->member;
    if (left_member->kind != right_member->kind ||
        left_member->is_static != right_member->is_static) {
        return false;
    }
    if (left_member->kind == FENG_TYPE_MEMBER_FIELD) {
        const FengTypeRef *left_type;
        const FengTypeRef *right_type;

        if (!slice_equals(left_member->as.field.name,
                          right_member->as.field.name) ||
            left_member->as.field.mutability !=
                right_member->as.field.mutability) {
            return false;
        }
        left_type = substitute_spec_member_type_ref_for_instance(
            context,
            left->declaring_spec,
            left->declaring_spec_type_ref,
            left_member->as.field.type);
        right_type = substitute_spec_member_type_ref_for_instance(
            context,
            right->declaring_spec,
            right->declaring_spec_type_ref,
            right_member->as.field.type);
        return type_refs_semantically_equal(context, left_type, right_type);
    }
    if (left_member->kind != FENG_TYPE_MEMBER_METHOD ||
        !slice_equals(left_member->as.callable.name,
                      right_member->as.callable.name)) {
        return false;
    }
    return callable_signatures_equal_for_owner_instances(
        context,
        &left_member->as.callable,
        left->declaring_spec,
        object_spec_requirement_owner_type(left),
        &right_member->as.callable,
        right->declaring_spec,
        object_spec_requirement_owner_type(right));
}

/* Append one requirement unless an earlier child-first declaration already
 * represents the same closed requirement. */
static bool object_spec_requirement_set_add(
    ResolveContext *context,
    ObjectSpecRequirementSet *set,
    ObjectSpecRequirementSurface candidate) {
    if (set == NULL || candidate.member == NULL) {
        return false;
    }
    for (size_t index = 0U; index < set->count; ++index) {
        const FengTypeMember *existing = set->items[index].member;

        if (object_spec_requirements_semantically_equivalent(
                context, &set->items[index], &candidate)) {
            return true;
        }
        /* Invalid same-surface field collisions are rejected during spec
         * declaration validation. Before that validation has run, preserve
         * the historical child-first fallback only within the same surface;
         * instance and static owners must never be collapsed into one slot. */
        if (existing != NULL &&
            (existing->kind != FENG_TYPE_MEMBER_METHOD ||
             candidate.member->kind != FENG_TYPE_MEMBER_METHOD) &&
            existing->is_static == candidate.member->is_static) {
            FengSlice existing_name =
                existing->kind == FENG_TYPE_MEMBER_FIELD
                    ? existing->as.field.name
                    : existing->as.callable.name;
            FengSlice candidate_name =
                candidate.member->kind == FENG_TYPE_MEMBER_FIELD
                    ? candidate.member->as.field.name
                    : candidate.member->as.callable.name;

            if (slice_equals(existing_name, candidate_name)) {
                return true;
            }
        }
    }
    if (set->count == set->capacity) {
        size_t new_capacity = set->capacity == 0U ? 8U : set->capacity * 2U;
        ObjectSpecRequirementSurface *grown = realloc(
            set->items, new_capacity * sizeof(*grown));

        if (grown == NULL) {
            return false;
        }
        set->items = grown;
        set->capacity = new_capacity;
    }
    set->items[set->count++] = candidate;
    return true;
}

/* Recursively accumulate one object-form spec instance. Own declarations are
 * visited before parent edges, making an equivalent child declaration the
 * single logical representative without treating the relation as OOP. */
static bool collect_object_spec_requirement_surfaces(
    ResolveContext *context,
    const FengDecl *spec_decl,
    const FengTypeRef *spec_type_ref,
    ObjectSpecRequirementSet *out_set) {
    bool ok = true;

    if (context == NULL || spec_decl == NULL || out_set == NULL ||
        spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return false;
    }
    for (size_t index = 0U; index < out_set->active_spec_count; ++index) {
        if (out_set->active_specs[index] == spec_decl) {
            /* AE0614 is recorded by the parent-list validator. This collector
             * only needs to stop the already-invalid edge from recursing. */
            return true;
        }
    }
    if (!append_raw((void **)&out_set->active_specs,
                    &out_set->active_spec_count,
                    &out_set->active_spec_capacity,
                    sizeof(*out_set->active_specs),
                    &spec_decl)) {
        return false;
    }
    for (size_t member_index = 0U;
         member_index < spec_decl->as.spec_decl.as.object.member_count;
         ++member_index) {
        const FengTypeMember *member =
            spec_decl->as.spec_decl.as.object.members[member_index];

        if (member == NULL ||
            (member->kind != FENG_TYPE_MEMBER_FIELD &&
             member->kind != FENG_TYPE_MEMBER_METHOD)) {
            continue;
        }
        if (!object_spec_requirement_set_add(
                context,
                out_set,
                (ObjectSpecRequirementSurface){
                    .member = member,
                    .declaring_spec = spec_decl,
                    .declaring_spec_type_ref = spec_type_ref,
                })) {
            ok = false;
            break;
        }
    }
    for (size_t parent_index = 0U; ok &&
         parent_index < spec_decl->as.spec_decl.parent_spec_count;
         ++parent_index) {
        const FengTypeRef *parent_ref =
            substitute_spec_member_type_ref_for_instance(
                context,
                spec_decl,
                spec_type_ref,
                spec_decl->as.spec_decl.parent_specs[parent_index]);
        const FengDecl *parent_decl = resolve_type_ref_decl(context, parent_ref);

        if (parent_decl == NULL || parent_decl->kind != FENG_DECL_SPEC ||
            parent_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            continue;
        }
        if (!collect_object_spec_requirement_surfaces(
                context, parent_decl, parent_ref, out_set)) {
            ok = false;
        }
    }
    out_set->active_spec_count--;
    return ok;
}

/* Release one compiler-only logical requirement collection. */
static void object_spec_requirement_set_free(
    ObjectSpecRequirementSet *set) {
    if (set == NULL) {
        return;
    }
    free(set->items);
    free(set->active_specs);
    memset(set, 0, sizeof(*set));
}

/* Phase S3 — SpecWitness compute (§6.5 / §8.1 / §8.2).
 *
 * Materialises one (T, S) witness on first demand. The walk follows S's
 * child-first logical requirement surface (deduplicated only by exact closed
 * requirement identity) and resolves each member against T's visible face:
 * T's own members + every fit visible from the resolve
 * context's module (per fit_decl_is_visible_from). Method candidates are
 * filtered by exact signature match per §6.5; ambiguity between distinct
 * visible-face implementations of the same (name, params, return) raises
 * §8.1 conflict at the triggering coercion site.
 *
 * Missing-implementation slots (no candidate at all) record a NULL
 * impl_member without emitting an error: the missing-member diagnostic is
 * already produced by verify_type_satisfies_spec / fit validation; the
 * NULL slot exists only so codegen can detect the gap. */

typedef struct WitnessFitCandidate {
    const FengTypeMember *method;
    const FengDecl *fit_decl;
    const FengSemanticModule *fit_module;
} WitnessFitCandidate;

typedef struct WitnessFitCollectCtx {
    const ResolveContext *ctx;
    const FengDecl *source_type_decl;
    const FengTypeRef *source_type_ref;
    const FengTypeMember *spec_member;
    const FengCallableSignature *spec_sig;
    const FengDecl *spec_decl;
    const FengTypeRef *spec_type_ref;
    WitnessFitCandidate *items;
    size_t count;
    size_t capacity;
    bool oom;
} WitnessFitCollectCtx;

static bool witness_fit_collect_visitor(const FengTypeMember *member,
                                        const FengSemanticModule *fit_module,
                                        const FengDecl *fit_decl,
                                        void *userdata) {
    WitnessFitCollectCtx *st = (WitnessFitCollectCtx *)userdata;

    if (!spec_requirement_accepts_implementation(st->spec_member, member)) {
        return true;
    }
    if (st->spec_decl != NULL && st->spec_type_ref != NULL) {
        if (!callable_signatures_match_for_witness_instances(
                (ResolveContext *)st->ctx,
                st->source_type_decl,
                st->source_type_ref,
                fit_decl,
                st->spec_decl,
                st->spec_type_ref,
                st->spec_sig,
                &member->as.callable)) {
            return true;
        }
    } else if (!callable_signatures_match_for_satisfaction(
                   st->ctx,
                   st->spec_sig,
                   &member->as.callable)) {
        return true;
    }
    if (st->count == st->capacity) {
        size_t new_cap = st->capacity == 0U ? 4U : st->capacity * 2U;
        WitnessFitCandidate *grown = realloc(st->items, new_cap * sizeof(*grown));

        if (grown == NULL) {
            st->oom = true;
            return false;
        }
        st->items = grown;
        st->capacity = new_cap;
    }
    st->items[st->count].method = member;
    st->items[st->count].fit_decl = fit_decl;
    st->items[st->count].fit_module = fit_module;
    ++st->count;
    return true;
}

static bool init_spec_witness_subject_key(const FengDecl *type_decl,
                                          const FengTypeRef *source_type_ref,
                                          size_t pointer_size,
                                          FengSemanticSubjectKey *out_key) {
    const char *builtin_name;

    if (out_key == NULL) {
        return false;
    }
    if (decl_is_named_fit_target(type_decl)) {
        *out_key = feng_semantic_subject_key_for_type_decl(type_decl);
        return true;
    }
    builtin_name = type_ref_builtin_canonical_name(source_type_ref, pointer_size);
    if (builtin_name != NULL) {
        *out_key = feng_semantic_subject_key_for_builtin(builtin_name);
        return true;
    }
    return feng_semantic_subject_key_init_array_from_type_ref(out_key,
                                                              source_type_ref);
}

static void compute_spec_witness_if_absent(ResolveContext *context,
                                           const FengDecl *type_decl,
                                           InferredExprType source_type,
                                           const FengTypeRef *source_type_ref,
                                           const FengDecl *spec_decl,
                                           const FengTypeRef *spec_type_ref,
                                           FengToken err_token) {
    ObjectSpecRequirementSet requirements;
    FengSpecWitness *witness;
    FengSemanticSubjectKey subject_key;

    memset(&requirements, 0, sizeof(requirements));

    if (context == NULL || context->analysis == NULL || spec_decl == NULL) {
        return;
    }
    if ((type_decl != NULL && !decl_is_named_fit_target(type_decl)) ||
        spec_decl->kind != FENG_DECL_SPEC) {
        return;
    }
    if (source_type.kind == FENG_INFERRED_EXPR_TYPE_UNKNOWN && source_type_ref != NULL) {
        source_type = inferred_expr_type_from_type_ref(source_type_ref);
    }
    if (source_type.kind == FENG_INFERRED_EXPR_TYPE_UNKNOWN && type_decl != NULL) {
        source_type = inferred_expr_type_from_decl(type_decl);
    }
    if (source_type.kind == FENG_INFERRED_EXPR_TYPE_UNKNOWN) {
        return;
    }

    if (type_decl != NULL) {
        if (!init_spec_witness_subject_key(type_decl, source_type_ref, context->pointer_size, &subject_key)) {
            return;
        }
    } else if (source_type.kind == FENG_INFERRED_EXPR_TYPE_BUILTIN) {
        const char *builtin_name = canonical_builtin_type_name(source_type.builtin_name, context->pointer_size);
        if (builtin_name == NULL) {
            return;
        }
        subject_key = feng_semantic_subject_key_for_builtin(builtin_name);
    } else if (source_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF) {
        if (!init_spec_witness_subject_key(NULL, source_type.type_ref, context->pointer_size, &subject_key)) {
            return;
        }
    } else {
        return;
    }

    if (subject_key.kind == FENG_SEMANTIC_SUBJECT_KEY_INVALID ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return;
    }
    if (subject_key.kind == FENG_SEMANTIC_SUBJECT_KEY_ARRAY) {
        const FengSpecRelation *relation =
            feng_semantic_lookup_spec_relation(context->analysis,
                                               &subject_key,
                                               spec_decl);

        /* Array keys created from generic-call type arguments may borrow a
         * resolver-owned element ref. The authoritative relation key comes
         * from the fit declaration AST and therefore remains valid for the
         * complete analysis/codegen lifetime. */
        if (relation == NULL) {
            return;
        }
        subject_key = relation->subject_key;
    }
    if (feng_semantic_lookup_spec_witness(context->analysis,
                                          &subject_key, spec_decl) != NULL) {
        return;
    }

    /* Materialize the same subject implementation for every direct parent
     * before reserving this witness. The nominal parent graph is acyclic, so
     * recursion terminates; the existing witness cache also deduplicates
     * diamonds. Generic parent refs are substituted from this exact spec
     * instance before the parent witness is computed. */
    for (size_t parent_index = 0U;
         parent_index < spec_decl->as.spec_decl.parent_spec_count;
         ++parent_index) {
        const FengTypeRef *declared_parent_ref =
            spec_decl->as.spec_decl.parent_specs[parent_index];
        const FengTypeRef *parent_ref = substitute_spec_member_type_ref_for_instance(
            context,
            spec_decl,
            spec_type_ref,
            declared_parent_ref);
        const FengDecl *parent_decl = resolve_type_ref_decl(context, parent_ref);

        if (parent_decl == NULL || parent_decl->kind != FENG_DECL_SPEC ||
            parent_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            continue;
        }
        compute_spec_witness_if_absent(context,
                                       type_decl,
                                       source_type,
                                       source_type_ref,
                                       parent_decl,
                                       parent_ref,
                                       err_token);
    }

    witness = feng_semantic_reserve_spec_witness(context->analysis,
                                                 &subject_key, spec_decl);
    if (witness == NULL) {
        return;
    }
    if (!collect_object_spec_requirement_surfaces(
            context, spec_decl, spec_type_ref, &requirements)) {
        object_spec_requirement_set_free(&requirements);
        return;
    }

    for (size_t requirement_index = 0U;
         requirement_index < requirements.count;
         ++requirement_index) {
            const ObjectSpecRequirementSurface *surface =
                &requirements.items[requirement_index];
            const FengDecl *cur = surface->declaring_spec;
            const FengTypeRef *cur_spec_type_ref =
                surface->declaring_spec_type_ref;
            const FengTypeMember *sm = surface->member;
            FengSlice name;

            if (sm == NULL) {
                continue;
            }
            if (sm->kind == FENG_TYPE_MEMBER_FIELD) {
                name = sm->as.field.name;
            } else if (sm->kind == FENG_TYPE_MEMBER_METHOD) {
                name = sm->as.callable.name;
            } else {
                continue;
            }

            if (sm->kind == FENG_TYPE_MEMBER_FIELD) {
                const FengTypeMember *t_field;

                if (sm->is_static) {
                    /* 静态字段:只能由 type 自身提供 (fit 不能声明 static let/var). */
                    t_field = (type_decl != NULL)
                        ? find_type_static_field_member(type_decl, name)
                        : NULL;
                } else {
                    t_field = (type_decl != NULL) ? type_find_field(type_decl, name) : NULL;
                }

                if (!spec_requirement_accepts_implementation(sm, t_field)) {
                    t_field = NULL;
                }

                (void)feng_semantic_spec_witness_append_member(
                    witness, sm, t_field,
                    FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_FIELD,
                    NULL, NULL);
                continue;
            }

            /* Method member — collect signature-matching candidates from T
             * and from every visible fit. */
            {
                const FengTypeMember *t_method = NULL;
                WitnessFitCollectCtx fit_st;
                size_t total;

                if (type_decl != NULL && cur_spec_type_ref != NULL) {
                    t_method = type_find_matching_method_for_witness(
                        context,
                        type_decl,
                        source_type_ref,
                        cur,
                        cur_spec_type_ref,
                        sm);
                } else if (type_decl != NULL) {
                    t_method = type_find_matching_method(
                        context,
                        type_decl,
                        sm,
                        NULL,
                        0U);
                }

                fit_st.ctx = context;
                fit_st.source_type_decl = type_decl;
                fit_st.source_type_ref = source_type_ref;
                fit_st.spec_member = sm;
                fit_st.spec_sig = &sm->as.callable;
                fit_st.spec_decl = cur_spec_type_ref != NULL ? cur : NULL;
                fit_st.spec_type_ref = cur_spec_type_ref;
                fit_st.items = NULL;
                fit_st.count = 0U;
                fit_st.capacity = 0U;
                fit_st.oom = false;
                if (type_decl != NULL) {
                    (void)visit_visible_fit_methods_for_type(
                        context, type_decl, name, true, sm->is_static,
                        witness_fit_collect_visitor, &fit_st);
                } else {
                    const FengDecl *owner_type_decl = resolve_inferred_expr_type_decl(
                        context, source_type);

                    (void)visit_visible_fit_methods_for_owner_type(
                        context,
                        owner_type_decl,
                        source_type,
                        name,
                        true,
                        sm->is_static,
                        witness_fit_collect_visitor,
                        &fit_st);
                }
                if (fit_st.oom) {
                    free(fit_st.items);
                    object_spec_requirement_set_free(&requirements);
                    return;
                }

                total = (t_method != NULL ? 1U : 0U) + fit_st.count;
                if (total == 0U) {
                    /* Missing — diagnostic is the responsibility of the
                     * type/fit validation passes. Record a NULL slot. */
                    (void)feng_semantic_spec_witness_append_member(
                        witness, sm, NULL,
                        FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_METHOD,
                        NULL, NULL);
                } else if (total == 1U) {
                    if (t_method != NULL) {
                        (void)feng_semantic_spec_witness_append_member(
                            witness, sm, t_method,
                            FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_METHOD,
                            NULL, NULL);
                    } else {
                        (void)feng_semantic_spec_witness_append_member(
                            witness, sm, fit_st.items[0].method,
                            FENG_SPEC_WITNESS_SOURCE_FIT_METHOD,
                            fit_st.items[0].fit_decl,
                            fit_st.items[0].fit_module);
                    }
                } else {
                    /* §8.1 — multiple visible-face implementations of the
                     * same (name, params, return). Report once, at the
                     * triggering coercion site. */
                    if (type_decl != NULL) {
                        (void)resolver_append_error(
                            context,
                            err_token,
                            "AE0804", format_message(
                                "type '%.*s' has multiple visible implementations of method '%.*s' required by spec '%.*s' (one or more fits and/or the type itself)",
                                (int)decl_typeish_name(type_decl).length,
                                decl_typeish_name(type_decl).data,
                                (int)name.length,
                                name.data,
                                (int)spec_decl->as.spec_decl.name.length,
                                spec_decl->as.spec_decl.name.data));
                    } else {
                        (void)resolver_append_error(
                            context,
                            err_token,
                            "AE0804", format_message(
                                "fit target has multiple visible implementations of method '%.*s' required by spec '%.*s'",
                                (int)name.length,
                                name.data,
                                (int)spec_decl->as.spec_decl.name.length,
                                spec_decl->as.spec_decl.name.data));
                    }
                    (void)feng_semantic_spec_witness_append_member(
                        witness, sm, NULL,
                        FENG_SPEC_WITNESS_SOURCE_TYPE_OWN_METHOD,
                        NULL, NULL);
                }
                free(fit_st.items);
            }
    }

    object_spec_requirement_set_free(&requirements);
}

static bool collect_type_decl_satisfied_specs(const ResolveContext *ctx,
                                              const FengDecl *type_decl,
                                              const FengDecl ***out_set,
                                              size_t *out_count,
                                              size_t *out_capacity) {
    size_t i;
    size_t p;
    size_t d;

    if (!decl_is_named_fit_target(type_decl)) {
        return true;
    }

    /* Specs from the type's own declared spec list (transitive). */
    if (type_decl->kind == FENG_DECL_TYPE) {
        for (i = 0U; i < type_decl->as.type_decl.declared_spec_count; ++i) {
            const FengDecl *spec = resolve_type_ref_decl(ctx, type_decl->as.type_decl.declared_specs[i]);

            if (!spec_collect_closure(ctx, spec, out_set, out_count, out_capacity)) {
                return false;
            }
        }
    }

    /* Specs from every visible fit declaration (current module + cross-module
     * `open fit`s the consumer has imported via `use`). Mirrors docs/specifications/feng-fit.md
     * §4 — a `open fit` activates in the importing module after `use`. */
    if (ctx->analysis != NULL) {
        size_t m_idx;

        for (m_idx = 0U; m_idx < ctx->analysis->module_count; ++m_idx) {
            const FengSemanticModule *m = &ctx->analysis->modules[m_idx];

            for (p = 0U; p < m->program_count; ++p) {
                const FengProgram *prog = m->programs[p];

                if (prog == NULL) {
                    continue;
                }
                for (d = 0U; d < prog->declaration_count; ++d) {
                    const FengDecl *fd = prog->declarations[d];
                    size_t s;

                    if (fd == NULL || fd->kind != FENG_DECL_FIT) {
                        continue;
                    }
                    if (!fit_decl_is_visible_from(ctx, m, fd)) {
                        continue;
                    }
                    if (resolve_type_ref_decl(ctx, fd->as.fit_decl.target) != type_decl) {
                        continue;
                    }
                    for (s = 0U; s < fd->as.fit_decl.spec_count; ++s) {
                        const FengDecl *spec = resolve_type_ref_decl(ctx, fd->as.fit_decl.specs[s]);

                        if (!spec_collect_closure(ctx, spec, out_set, out_count, out_capacity)) {
                            return false;
                        }
                    }
                }
            }
        }
    }
    return true;
}

static bool spec_relation_source_visible_from_context(const ResolveContext *ctx,
                                                      const FengSpecRelationSource *source) {
    size_t index;

    if (source == NULL) {
        return false;
    }
    if (source->kind == FENG_SPEC_RELATION_SOURCE_DECLARED_HEAD ||
        source->kind == FENG_SPEC_RELATION_SOURCE_DECLARED_PARENT) {
        return true;
    }
    if (ctx == NULL) {
        return false;
    }
    if (source->provider_module == ctx->module) {
        return true;
    }
    if (source->via_fit_decl == NULL ||
        source->via_fit_decl->visibility != FENG_VISIBILITY_PUBLIC) {
        return false;
    }
    for (index = 0U; index < ctx->imported_module_count; ++index) {
        if (ctx->imported_modules[index].target_module == source->provider_module) {
            return true;
        }
    }
    return false;
}

static bool subject_key_satisfies_spec_decl(const ResolveContext *ctx,
                                            const FengSemanticSubjectKey *subject_key,
                                            const FengDecl *spec_decl) {
    const FengSpecRelation *relation;
    size_t i;

    if (ctx == NULL || ctx->analysis == NULL || subject_key == NULL ||
        spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        subject_key->kind == FENG_SEMANTIC_SUBJECT_KEY_INVALID) {
        return false;
    }

    /* Intersection-form: the subject must nominally satisfy every flattened
     * member spec (all members are object-form after flattening). */
    if (spec_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
        const FengIntersectionSpecInfo *info =
            feng_semantic_lookup_intersection_spec_info(ctx->analysis, spec_decl);
        size_t member_idx;

        if (info == NULL || info->flattened_member_count == 0U) {
            return false;
        }
        for (member_idx = 0U; member_idx < info->flattened_member_count; ++member_idx) {
            const FengDecl *member_decl = info->flattened_members[member_idx];
            if (member_decl == NULL || member_decl->kind != FENG_DECL_SPEC ||
                !subject_key_satisfies_spec_decl(ctx, subject_key, member_decl)) {
                return false;
            }
        }
        return true;
    }

    if (spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return false;
    }

    relation = feng_semantic_lookup_spec_relation(ctx->analysis, subject_key, spec_decl);
    if (relation == NULL) {
        return false;
    }
    for (i = 0U; i < relation->source_count; ++i) {
        if (spec_relation_source_visible_from_context(ctx, &relation->sources[i])) {
            return true;
        }
    }
    return false;
}

static bool type_decl_satisfies_spec_decl(const ResolveContext *ctx,
                                          const FengDecl *type_decl,
                                          const FengDecl *spec_decl) {
    const FengDecl **closure = NULL;
    size_t closure_count = 0U;
    size_t closure_capacity = 0U;
    size_t i;
    bool found = false;

    if (type_decl == NULL || spec_decl == NULL ||
        !decl_is_named_fit_target(type_decl) || spec_decl->kind != FENG_DECL_SPEC) {
        return false;
    }

    /* Intersection-form: derive the subject key and delegate to
     * subject_key_satisfies_spec_decl which checks all flattened members. */
    if (spec_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
        if (ctx == NULL || ctx->analysis == NULL) {
            return false;
        }
        FengSemanticSubjectKey sk = feng_semantic_subject_key_for_type_decl(type_decl);
        return subject_key_satisfies_spec_decl(ctx, &sk, spec_decl);
    }

    if (spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return false;
    }

    if (ctx != NULL && ctx->analysis != NULL) {
        FengSemanticSubjectKey sk = feng_semantic_subject_key_for_type_decl(type_decl);

        return subject_key_satisfies_spec_decl(ctx, &sk, spec_decl);
    }

    if (!collect_type_decl_satisfied_specs(ctx, type_decl, &closure,
                                           &closure_count, &closure_capacity)) {
        free(closure);
        return false;
    }
    for (i = 0U; i < closure_count; ++i) {
        if (closure[i] == spec_decl) {
            found = true;
            break;
        }
    }
    free(closure);
    return found;
}

static bool detect_cross_spec_method_conflicts(ResolveContext *ctx,
                                               const FengDecl *type_decl,
                                               const FengDecl *const *spec_set,
                                               size_t spec_count,
                                               FengToken err_token) {
    size_t i;
    size_t j;
    size_t a;
    size_t b;
    size_t p;

    for (i = 0U; i < spec_count; ++i) {
        const FengDecl *spec_a = spec_set[i];

        if (spec_a->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            continue;
        }
        for (a = 0U; a < spec_a->as.spec_decl.as.object.member_count; ++a) {
            const FengTypeMember *ma = spec_a->as.spec_decl.as.object.members[a];

            if (ma->kind != FENG_TYPE_MEMBER_METHOD) {
                continue;
            }
            for (j = i + 1U; j < spec_count; ++j) {
                const FengDecl *spec_b = spec_set[j];

                if (spec_b->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
                    continue;
                }
                for (b = 0U; b < spec_b->as.spec_decl.as.object.member_count; ++b) {
                    const FengTypeMember *mb = spec_b->as.spec_decl.as.object.members[b];
                    bool same_params;

                    if (mb->kind != FENG_TYPE_MEMBER_METHOD ||
                        !slice_eq(ma->as.callable.name, mb->as.callable.name) ||
                        ma->as.callable.param_count != mb->as.callable.param_count) {
                        continue;
                    }
                    same_params = true;
                    for (p = 0U; p < ma->as.callable.param_count; ++p) {
                        if (!type_refs_semantically_equal(ctx,
                                                          ma->as.callable.params[p].type,
                                                          mb->as.callable.params[p].type)) {
                            same_params = false;
                            break;
                        }
                    }
                    if (!same_params) {
                        continue;
                    }
                    if (!type_refs_semantically_equal(ctx,
                                                      ma->as.callable.return_type,
                                                      mb->as.callable.return_type)) {
                        return resolver_append_error(
                            ctx, err_token,
                            "AE0706", format_message(
                                "type '%.*s' satisfies specs '%.*s' and '%.*s' which both declare method '%.*s' with the same parameters but different return types",
                                (int)decl_typeish_name(type_decl).length,
                                decl_typeish_name(type_decl).data,
                                (int)spec_a->as.spec_decl.name.length,
                                spec_a->as.spec_decl.name.data,
                                (int)spec_b->as.spec_decl.name.length,
                                spec_b->as.spec_decl.name.data,
                                (int)ma->as.callable.name.length,
                                ma->as.callable.name.data));
                    }
                }
            }
        }
    }
    return true;
}

/* Two parameter type references potentially overlap when there exists at
 * least one concrete type T (visible in the current analysis) that can be
 * supplied as an argument to both parameters under the visible explicit
 * contract relations (declared spec lists and `fit` declarations). This
 * mirrors docs/specifications/feng-function.md §5: "若同一重载集合中的两个候选在当前可见
 * 的显式契约关系下可能同时匹配同一实参类型，必须视为签名冲突". The check
 * is intentionally nominal — duck typing is not considered. */
static bool param_type_refs_potentially_overlap(const ResolveContext *ctx,
                                                const FengTypeRef *a,
                                                const FengTypeRef *b) {
    const FengDecl *da;
    const FengDecl *db;
    size_t module_index;
    size_t program_index;
    size_t decl_index;

    if (ctx == NULL || a == NULL || b == NULL) {
        return false;
    }
    if (type_refs_semantically_equal(ctx, a, b)) {
        return true;
    }

    da = resolve_type_ref_decl(ctx, a);
    db = resolve_type_ref_decl(ctx, b);
    if (da == NULL || db == NULL) {
        return false;
    }
    if (da == db) {
        return true;
    }
    if (decl_is_named_fit_target(da) && db->kind == FENG_DECL_SPEC) {
        return type_decl_satisfies_spec_decl(ctx, da, db);
    }
    if (decl_is_named_fit_target(db) && da->kind == FENG_DECL_SPEC) {
        return type_decl_satisfies_spec_decl(ctx, db, da);
    }
    if (da->kind != FENG_DECL_SPEC || db->kind != FENG_DECL_SPEC) {
        return false;
    }

    /* Both parameters are object specs — they overlap when at least one
     * concrete type in the analysis satisfies both specs (either via its
     * declared spec list, transitive parents, or a visible fit). */
    for (module_index = 0U; module_index < ctx->analysis->module_count; ++module_index) {
        const FengSemanticModule *m = &ctx->analysis->modules[module_index];

        for (program_index = 0U; program_index < m->program_count; ++program_index) {
            const FengProgram *prog = m->programs[program_index];

            if (prog == NULL) {
                continue;
            }
            for (decl_index = 0U; decl_index < prog->declaration_count; ++decl_index) {
                const FengDecl *t = prog->declarations[decl_index];

                if (!decl_is_named_fit_target(t)) {
                    continue;
                }
                if (type_decl_satisfies_spec_decl(ctx, t, da) &&
                    type_decl_satisfies_spec_decl(ctx, t, db)) {
                    return true;
                }
            }
        }
    }
    return false;
}

static bool signatures_potentially_overlap(const ResolveContext *ctx,
                                           const FengCallableSignature *a,
                                           const FengCallableSignature *b) {
    size_t i;

    if (a == NULL || b == NULL || a->param_count != b->param_count) {
        return false;
    }
    for (i = 0U; i < a->param_count; ++i) {
        /* A variadic parameter (T...) and a non-variadic parameter (T[]) at
         * the same position cannot both match the same call: the variadic
         * position accepts only individual T values (packing them into T[]),
         * while the explicit T[] position accepts only an existing array.
         * Per §4.2 of the variadic spec, passing an existing T[] into a
         * variadic position is forbidden, so they never overlap. */
        if (a->params[i].is_variadic != b->params[i].is_variadic) {
            return false;
        }
        if (!param_type_refs_potentially_overlap(ctx, a->params[i].type, b->params[i].type)) {
            return false;
        }
    }
    return true;
}

/* Validate declaration-local overload overlap under visible contract
 * relations for both types and object-form specs. */
static bool validate_declared_method_overload_overlap(
    ResolveContext *context,
    const FengDecl *decl) {
    DeclaredMemberSet set;
    size_t i;
    size_t j;
    bool ok = true;

    if (context == NULL || !declared_member_set_init(decl, &set)) {
        return true;
    }

    for (i = 0U; i < set.member_count; ++i) {
        const FengTypeMember *mi = set.members[i];
        const FengCallableSignature *si;

        if (mi == NULL || mi->kind != FENG_TYPE_MEMBER_METHOD) {
            continue;
        }
        si = &mi->as.callable;

        for (j = 0U; j < i; ++j) {
            const FengTypeMember *mj = set.members[j];
            const FengCallableSignature *sj;

            if (mj == NULL || mj->kind != FENG_TYPE_MEMBER_METHOD ||
                mi->is_static != mj->is_static) {
                continue;
            }
            sj = &mj->as.callable;
            if (!slice_equals(si->name, sj->name)) {
                continue;
            }
            if (si->type_param_count != sj->type_param_count) {
                continue;
            }
            /* Identical-parameter pairs are already reported by
             * validate_type_member_overloads with a more specific message.
             * Variadic conflicts are also reported there. */
            if (parameters_equal(si, sj)) {
                continue;
            }
            if ((sig_is_variadic(si) || sig_is_variadic(sj)) &&
                variadic_parameters_conflict(si, sj)) {
                continue;
            }
            if (signatures_potentially_overlap(context, si, sj)) {
                bool error_ok = resolver_append_error(
                    context,
                    mixin_conflict_primary_token(mi, mj, si->token),
                    "AE0706", format_message(
                        "method overloads in %s '%.*s' may both match the same arguments under visible contract relations: '%.*s'",
                        set.owner_label,
                        (int)set.owner_name.length,
                        set.owner_name.data,
                        (int)si->name.length, si->name.data));

                if (error_ok) {
                    error_ok = append_mixin_conflict_related_locations(
                        context, mi, mj);
                }
                ok = error_ok && ok;
            }
        }
    }
    return ok;
}

/* Close one parameter or return type against the exact object-spec owner
 * instance represented by a logical requirement surface. */
static const FengTypeRef *close_object_spec_requirement_type(
    ResolveContext *context,
    const ObjectSpecRequirementSurface *surface,
    const FengTypeRef *type_ref) {
    if (surface == NULL) {
        return type_ref;
    }
    return substitute_spec_member_type_ref_for_instance(
        context,
        surface->declaring_spec,
        surface->declaring_spec_type_ref,
        type_ref);
}

/* Compare closed parameter lists, including the variadic shape. */
static bool object_spec_requirement_parameters_equal(
    ResolveContext *context,
    const ObjectSpecRequirementSurface *left,
    const ObjectSpecRequirementSurface *right) {
    const FengCallableSignature *left_sig = &left->member->as.callable;
    const FengCallableSignature *right_sig = &right->member->as.callable;

    if (left_sig->param_count != right_sig->param_count) {
        return false;
    }
    for (size_t index = 0U; index < left_sig->param_count; ++index) {
        const FengTypeRef *left_type;
        const FengTypeRef *right_type;

        if (left_sig->params[index].is_variadic !=
            right_sig->params[index].is_variadic) {
            return false;
        }
        left_type = close_object_spec_requirement_type(
            context, left, left_sig->params[index].type);
        right_type = close_object_spec_requirement_type(
            context, right, right_sig->params[index].type);
        if (!type_refs_semantically_equal(context, left_type, right_type)) {
            return false;
        }
    }
    return true;
}

/* Compare closed return types while treating omitted and explicit void as
 * the same ordinary callable result. */
static bool object_spec_requirement_returns_equal(
    ResolveContext *context,
    const ObjectSpecRequirementSurface *left,
    const ObjectSpecRequirementSurface *right) {
    const FengTypeRef *left_type = left->member->as.callable.return_type;
    const FengTypeRef *right_type = right->member->as.callable.return_type;
    bool left_void = left_type == NULL || type_ref_is_void(left_type);
    bool right_void = right_type == NULL || type_ref_is_void(right_type);

    if (left_void || right_void) {
        return left_void && right_void;
    }
    left_type = close_object_spec_requirement_type(context, left, left_type);
    right_type = close_object_spec_requirement_type(context, right, right_type);
    return type_refs_semantically_equal(context, left_type, right_type);
}

/* Return the closed effective argument type at one variadic-expanded
 * position. */
static const FengTypeRef *object_spec_requirement_param_type_at(
    ResolveContext *context,
    const ObjectSpecRequirementSurface *surface,
    size_t position) {
    const FengCallableSignature *sig = &surface->member->as.callable;
    size_t fixed_count = sig_fixed_count(sig);
    const FengTypeRef *type_ref;

    if (position < fixed_count) {
        type_ref = sig->params[position].type;
    } else {
        type_ref = sig_variadic_elem(sig);
    }
    return close_object_spec_requirement_type(context, surface, type_ref);
}

/* Apply the ordinary variadic overlap algorithm to independently closed
 * object-spec owner instances. */
static bool object_spec_requirement_variadic_conflict(
    ResolveContext *context,
    const ObjectSpecRequirementSurface *left,
    const ObjectSpecRequirementSurface *right) {
    const FengCallableSignature *left_sig = &left->member->as.callable;
    const FengCallableSignature *right_sig = &right->member->as.callable;
    size_t left_fixed = sig_fixed_count(left_sig);
    size_t right_fixed = sig_fixed_count(right_sig);
    size_t compare_count;

    if (left_fixed < right_fixed) {
        if (!sig_is_variadic(left_sig)) {
            return false;
        }
        compare_count = right_fixed;
    } else if (left_fixed > right_fixed) {
        if (!sig_is_variadic(right_sig)) {
            return false;
        }
        compare_count = left_fixed;
    } else {
        compare_count = left_fixed;
    }
    for (size_t index = 0U; index < compare_count; ++index) {
        if (!type_refs_semantically_equal(
                context,
                object_spec_requirement_param_type_at(context, left, index),
                object_spec_requirement_param_type_at(context, right, index))) {
            return false;
        }
    }
    return true;
}

/* Test visible-contract overlap after closing both requirement owners. */
static bool object_spec_requirement_signatures_potentially_overlap(
    ResolveContext *context,
    const ObjectSpecRequirementSurface *left,
    const ObjectSpecRequirementSurface *right) {
    const FengCallableSignature *left_sig = &left->member->as.callable;
    const FengCallableSignature *right_sig = &right->member->as.callable;

    if (left_sig->param_count != right_sig->param_count) {
        return false;
    }
    for (size_t index = 0U; index < left_sig->param_count; ++index) {
        if (left_sig->params[index].is_variadic !=
                right_sig->params[index].is_variadic ||
            !param_type_refs_potentially_overlap(
                context,
                close_object_spec_requirement_type(
                    context, left, left_sig->params[index].type),
                close_object_spec_requirement_type(
                    context, right, right_sig->params[index].type))) {
            return false;
        }
    }
    return true;
}

/* Return whether two surfaces belong to the same declaration-local overload
 * set after closing their owner. Distinct instances of one generic parent are
 * separate accumulated surfaces and must still be compared. */
static bool object_spec_requirements_share_closed_owner(
    ResolveContext *context,
    const ObjectSpecRequirementSurface *left,
    const ObjectSpecRequirementSurface *right) {
    if (left == NULL || right == NULL ||
        left->declaring_spec != right->declaring_spec) {
        return false;
    }
    if (left->declaring_spec_type_ref == NULL ||
        right->declaring_spec_type_ref == NULL) {
        return left->declaring_spec_type_ref == NULL &&
               right->declaring_spec_type_ref == NULL;
    }
    return type_refs_semantically_equal(
        context,
        left->declaring_spec_type_ref,
        right->declaring_spec_type_ref);
}

/* One closed object-spec owner visited while validating accumulated members. */
typedef struct ObjectSpecMemberOwnerSurface {
    const FengDecl *spec_decl;
    const FengTypeRef *spec_type_ref;
} ObjectSpecMemberOwnerSurface;

/* Compiler-only state for one complete object-spec member-surface check. */
typedef struct ObjectSpecMemberConflictState {
    ObjectSpecRequirementSurface *members;
    size_t member_count;
    size_t member_capacity;
    ObjectSpecMemberOwnerSurface *owners;
    size_t owner_count;
    size_t owner_capacity;
} ObjectSpecMemberConflictState;

/* Return whether two traversed owners denote the same closed spec surface. */
static bool object_spec_member_owner_surfaces_equal(
    ResolveContext *context,
    ObjectSpecMemberOwnerSurface left,
    ObjectSpecMemberOwnerSurface right) {
    if (left.spec_decl != right.spec_decl) {
        return false;
    }
    if (left.spec_type_ref == NULL || right.spec_type_ref == NULL) {
        return left.spec_type_ref == NULL && right.spec_type_ref == NULL;
    }
    return type_refs_semantically_equal(context,
                                        left.spec_type_ref,
                                        right.spec_type_ref);
}

/* Append one closed owner unless the same diamond path was already visited. */
static bool object_spec_member_conflict_add_owner(
    ResolveContext *context,
    ObjectSpecMemberConflictState *state,
    ObjectSpecMemberOwnerSurface owner,
    bool *out_added) {
    if (state == NULL || out_added == NULL) {
        return false;
    }
    *out_added = false;
    for (size_t index = 0U; index < state->owner_count; ++index) {
        if (object_spec_member_owner_surfaces_equal(
                context, state->owners[index], owner)) {
            return true;
        }
    }
    if (!append_raw((void **)&state->owners,
                    &state->owner_count,
                    &state->owner_capacity,
                    sizeof(*state->owners),
                    &owner)) {
        return false;
    }
    *out_added = true;
    return true;
}

/* Append one member surface after all prior conflict comparisons succeed. */
static bool object_spec_member_conflict_add_member(
    ObjectSpecMemberConflictState *state,
    ObjectSpecRequirementSurface member) {
    return state != NULL &&
           append_raw((void **)&state->members,
                      &state->member_count,
                      &state->member_capacity,
                      sizeof(*state->members),
                      &member);
}

/* Walk one closed owner and reject field/field or field/method conflicts
 * contributed by distinct owners to the same instance or static surface.
 * Identical diamond paths are visited once; closed generic owners remain
 * distinct. Method/method conflicts are handled by the overload validator. */
static bool validate_object_spec_accumulated_members_recursive(
    ResolveContext *context,
    const FengDecl *root_spec_decl,
    const FengDecl *spec_decl,
    const FengTypeRef *spec_type_ref,
    ObjectSpecMemberConflictState *state) {
    ObjectSpecMemberOwnerSurface owner;
    bool owner_added;

    if (context == NULL || root_spec_decl == NULL || spec_decl == NULL ||
        state == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return false;
    }
    owner = (ObjectSpecMemberOwnerSurface){
        .spec_decl = spec_decl,
        .spec_type_ref = spec_type_ref,
    };
    if (!object_spec_member_conflict_add_owner(
            context, state, owner, &owner_added)) {
        return false;
    }
    if (!owner_added) {
        return true;
    }

    for (size_t member_index = 0U;
         member_index < spec_decl->as.spec_decl.as.object.member_count;
         ++member_index) {
        const FengTypeMember *member =
            spec_decl->as.spec_decl.as.object.members[member_index];
        ObjectSpecRequirementSurface candidate;

        if (member == NULL ||
            (member->kind != FENG_TYPE_MEMBER_FIELD &&
             member->kind != FENG_TYPE_MEMBER_METHOD)) {
            continue;
        }
        candidate = (ObjectSpecRequirementSurface){
            .member = member,
            .declaring_spec = spec_decl,
            .declaring_spec_type_ref = spec_type_ref,
        };
        for (size_t previous_index = 0U;
             previous_index < state->member_count;
             ++previous_index) {
            const ObjectSpecRequirementSurface *previous =
                &state->members[previous_index];
            ObjectSpecMemberOwnerSurface previous_owner = {
                .spec_decl = previous->declaring_spec,
                .spec_type_ref = previous->declaring_spec_type_ref,
            };
            FengSlice member_name;
            FengSlice previous_name;
            FengToken error_token;

            if (object_spec_member_owner_surfaces_equal(
                    context, previous_owner, owner) ||
                previous->member->is_static != member->is_static ||
                (previous->member->kind == FENG_TYPE_MEMBER_METHOD &&
                 member->kind == FENG_TYPE_MEMBER_METHOD)) {
                continue;
            }
            previous_name =
                previous->member->kind == FENG_TYPE_MEMBER_FIELD
                    ? previous->member->as.field.name
                    : previous->member->as.callable.name;
            member_name = member->kind == FENG_TYPE_MEMBER_FIELD
                              ? member->as.field.name
                              : member->as.callable.name;
            if (!slice_equals(previous_name, member_name)) {
                continue;
            }
            error_token = previous->declaring_spec == root_spec_decl
                              ? previous->member->token
                              : member->token;
            if (previous->member->kind == FENG_TYPE_MEMBER_FIELD &&
                member->kind == FENG_TYPE_MEMBER_FIELD) {
                return resolver_append_error(
                           context,
                           error_token,
                           "AE0514",
                           format_message(
                               "duplicate field '%.*s' in object-form spec '%.*s' within the %s member surface",
                               (int)member_name.length,
                               member_name.data,
                               (int)root_spec_decl->as.spec_decl.name.length,
                               root_spec_decl->as.spec_decl.name.data,
                               member->is_static ? "static" : "instance")) &&
                       false;
            }
            return resolver_append_error(
                       context,
                       error_token,
                       "AE0513",
                       format_message(
                           "field and method '%.*s' in object-form spec '%.*s' cannot share the same name within the %s member surface",
                           (int)member_name.length,
                           member_name.data,
                           (int)root_spec_decl->as.spec_decl.name.length,
                           root_spec_decl->as.spec_decl.name.data,
                           member->is_static ? "static" : "instance")) &&
                   false;
        }
        if (!object_spec_member_conflict_add_member(state, candidate)) {
            return false;
        }
    }

    for (size_t parent_index = 0U;
         parent_index < spec_decl->as.spec_decl.parent_spec_count;
         ++parent_index) {
        const FengTypeRef *parent_ref =
            substitute_spec_member_type_ref_for_instance(
                context,
                spec_decl,
                spec_type_ref,
                spec_decl->as.spec_decl.parent_specs[parent_index]);
        const FengDecl *parent_decl = resolve_type_ref_decl(context, parent_ref);

        if (parent_decl == NULL || parent_decl->kind != FENG_DECL_SPEC ||
            parent_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            continue;
        }
        if (!validate_object_spec_accumulated_members_recursive(
                context,
                root_spec_decl,
                parent_decl,
                parent_ref,
                state)) {
            return false;
        }
    }
    return true;
}

/* Validate the complete inherited object-spec member surface at declaration
 * time. All storage is compiler-only and released before resolution returns. */
static bool validate_object_spec_accumulated_member_conflicts(
    ResolveContext *context,
    const FengDecl *spec_decl) {
    ObjectSpecMemberConflictState state;
    bool ok;

    if (context == NULL || spec_decl == NULL ||
        spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return true;
    }
    memset(&state, 0, sizeof(state));
    ok = validate_object_spec_accumulated_members_recursive(
        context, spec_decl, spec_decl, NULL, &state);
    free(state.members);
    free(state.owners);
    return ok;
}

/* Validate conflicts introduced by accumulating parent object-spec
 * requirements. Local pairs are handled by the shared declaration validator;
 * this pass compares only declarations originating in different specs. */
static bool validate_object_spec_accumulated_method_overloads(
    ResolveContext *context,
    const FengDecl *spec_decl) {
    ObjectSpecRequirementSet requirements;
    bool ok = true;

    if (context == NULL || spec_decl == NULL ||
        spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return true;
    }
    memset(&requirements, 0, sizeof(requirements));
    if (!collect_object_spec_requirement_surfaces(
            context, spec_decl, NULL, &requirements)) {
        object_spec_requirement_set_free(&requirements);
        return false;
    }
    for (size_t index = 0U; index < requirements.count; ++index) {
        const ObjectSpecRequirementSurface *current =
            &requirements.items[index];
        const FengCallableSignature *current_sig;

        if (current->member->kind != FENG_TYPE_MEMBER_METHOD) {
            continue;
        }
        current_sig = &current->member->as.callable;
        for (size_t previous_index = 0U;
             previous_index < index;
             ++previous_index) {
            const ObjectSpecRequirementSurface *previous =
                &requirements.items[previous_index];
            const FengCallableSignature *previous_sig;
            FengToken error_token;

            if (previous->member->kind != FENG_TYPE_MEMBER_METHOD ||
                object_spec_requirements_share_closed_owner(
                    context, previous, current) ||
                previous->member->is_static != current->member->is_static) {
                continue;
            }
            previous_sig = &previous->member->as.callable;
            error_token = previous->declaring_spec == spec_decl
                              ? previous_sig->token
                              : current_sig->token;
            if (!slice_equals(previous_sig->name, current_sig->name) ||
                previous_sig->type_param_count !=
                    current_sig->type_param_count) {
                continue;
            }
            if (object_spec_requirement_parameters_equal(
                    context, previous, current)) {
                if (!object_spec_requirement_returns_equal(
                        context, previous, current)) {
                    ok = resolver_append_error(
                             context,
                             error_token,
                             "AE0509",
                             format_message(
                                 "method overloads in object-form spec '%.*s' cannot differ only by return type: '%.*s'",
                                 (int)spec_decl->as.spec_decl.name.length,
                                 spec_decl->as.spec_decl.name.data,
                                 (int)current_sig->name.length,
                                 current_sig->name.data)) &&
                         ok;
                }
                continue;
            }
            if ((sig_is_variadic(previous_sig) ||
                 sig_is_variadic(current_sig)) &&
                object_spec_requirement_variadic_conflict(
                    context, previous, current)) {
                ok = resolver_append_error(
                         context,
                         error_token,
                         "AE0510",
                         format_message(
                             "variadic method overload conflicts with existing method '%.*s' in object-form spec '%.*s'",
                             (int)current_sig->name.length,
                             current_sig->name.data,
                             (int)spec_decl->as.spec_decl.name.length,
                             spec_decl->as.spec_decl.name.data)) &&
                     ok;
                continue;
            }
            if (object_spec_requirement_signatures_potentially_overlap(
                    context, previous, current)) {
                ok = resolver_append_error(
                         context,
                         error_token,
                         "AE0706",
                         format_message(
                             "method overloads in object-form spec '%.*s' may both match the same arguments under visible contract relations: '%.*s'",
                             (int)spec_decl->as.spec_decl.name.length,
                             spec_decl->as.spec_decl.name.data,
                             (int)current_sig->name.length,
                             current_sig->name.data)) &&
                     ok;
            }
        }
    }
    object_spec_requirement_set_free(&requirements);
    return ok;
}

static bool validate_fit_member_overload_overlap(ResolveContext *context,
                                                 const FengDecl *fit_decl) {
    size_t i;
    size_t j;
    bool ok = true;
    char *target_name;

    if (context == NULL || fit_decl == NULL || fit_decl->kind != FENG_DECL_FIT) {
        return true;
    }

    target_name = format_type_ref_name(fit_decl->as.fit_decl.target);

    for (i = 0U; i < fit_decl->as.fit_decl.member_count; ++i) {
        const FengTypeMember *mi = fit_decl->as.fit_decl.members[i];
        const FengCallableSignature *si;

        if (mi == NULL || mi->kind != FENG_TYPE_MEMBER_METHOD) {
            continue;
        }
        si = &mi->as.callable;

        for (j = 0U; j < i; ++j) {
            const FengTypeMember *mj = fit_decl->as.fit_decl.members[j];
            const FengCallableSignature *sj;

            if (mj == NULL || mj->kind != FENG_TYPE_MEMBER_METHOD ||
                mi->is_static != mj->is_static) {
                continue;
            }
            sj = &mj->as.callable;
            if (!slice_equals(si->name, sj->name)) {
                continue;
            }
            if (si->type_param_count != sj->type_param_count) {
                continue;
            }
            if (parameters_equal(si, sj)) {
                continue;
            }
            if ((sig_is_variadic(si) || sig_is_variadic(sj)) &&
                variadic_parameters_conflict(si, sj)) {
                continue;
            }
            if (signatures_potentially_overlap(context, si, sj)) {
                bool error_ok = resolver_append_error(
                    context,
                    mixin_conflict_primary_token(mi, mj, si->token),
                    "AE0805", format_message(
                        "method overloads in fit target '%s' may both match the same arguments under visible contract relations: '%.*s'",
                        target_name != NULL ? target_name : "<unknown>",
                        (int)si->name.length, si->name.data));

                if (error_ok) {
                    error_ok = append_mixin_conflict_related_locations(
                        context, mi, mj);
                }
                ok = error_ok && ok;
            }
        }
    }

    free(target_name);
    return ok;
}

static bool validate_top_level_overload_overlap(ResolveContext *context,
                                                const FengProgram *program) {
    size_t decl_index;
    size_t set_index;
    size_t k;
    bool ok = true;

    if (context == NULL || program == NULL) {
        return true;
    }

    for (decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
        const FengDecl *decl = program->declarations[decl_index];
        const FunctionOverloadSetEntry *set;
        const FengCallableSignature *current;

        if (decl == NULL || decl->kind != FENG_DECL_FUNCTION) {
            continue;
        }
        current = &decl->as.function_decl;

        for (set_index = 0U; set_index < context->function_set_count; ++set_index) {
            if (slice_equals(context->function_sets[set_index].name, current->name)) {
                break;
            }
        }
        if (set_index == context->function_set_count) {
            continue;
        }
        set = &context->function_sets[set_index];

        for (k = 0U; k < set->decl_count; ++k) {
            const FengDecl *other = set->decls[k];
            const FengCallableSignature *other_sig;

            /* The function_sets array is populated by check_symbol_conflicts
             * in declaration order. To report each pair exactly once we stop
             * at the current decl and only compare against earlier-registered
             * candidates. */
            if (other == decl) {
                break;
            }
            if (other == NULL || other->kind != FENG_DECL_FUNCTION) {
                continue;
            }
            other_sig = &other->as.function_decl;
            if (current->type_param_count != other_sig->type_param_count) {
                continue;
            }
            /* Identical-parameter pairs are already reported by
             * check_symbol_conflicts with a more specific message.
             * Variadic conflicts are also reported there. */
            if (parameters_equal(current, other_sig)) {
                continue;
            }
            if ((sig_is_variadic(current) || sig_is_variadic(other_sig)) &&
                variadic_parameters_conflict(current, other_sig)) {
                continue;
            }
            if (signatures_potentially_overlap(context, current, other_sig)) {
                ok = resolver_append_error(
                         context,
                         current->token,
                         "AE0706", format_message(
                             "function overloads may both match the same arguments under visible contract relations: '%.*s'",
                             (int)current->name.length,
                             current->name.data)) && ok;
            }
        }
    }
    return ok;
}

static bool validate_type_declared_specs_and_satisfaction(ResolveContext *context,
                                                          const FengDecl *type_decl) {
    size_t i;
    size_t j;
    const FengDecl **closure = NULL;
    size_t closure_count = 0U;
    size_t closure_capacity = 0U;
    bool ok = true;

    for (i = 0U; i < type_decl->as.type_decl.declared_spec_count; ++i) {
        const FengTypeRef *r = type_decl->as.type_decl.declared_specs[i];
        const FengDecl *resolved = resolve_type_ref_decl(context, r);

        if (resolved == NULL || resolved->kind != FENG_DECL_SPEC) {
            char *target_name = format_type_ref_name(r);
            bool result = resolver_append_error(
                context, r->token,
                "AE0615", format_message(
                    "type '%.*s' declared spec list must contain only spec types but found '%s'",
                    (int)type_decl->as.type_decl.name.length,
                    type_decl->as.type_decl.name.data,
                    target_name != NULL ? target_name : "<unknown>"));

            free(target_name);
            return result;
        }
        if (resolved->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            return resolver_append_error(
                context,
                r->token,
                "AE0615", format_message("type '%.*s' declared spec list can only contain object-form specs",
                               (int)type_decl->as.type_decl.name.length,
                               type_decl->as.type_decl.name.data));
        }
        for (j = 0U; j < i; ++j) {
            const FengDecl *prev = resolve_type_ref_decl(context, type_decl->as.type_decl.declared_specs[j]);

            if (prev == resolved) {
                return resolver_append_error(
                    context, r->token,
                    "AE0616", format_message(
                        "type '%.*s' lists '%.*s' more than once in its declared spec list",
                        (int)type_decl->as.type_decl.name.length,
                        type_decl->as.type_decl.name.data,
                        (int)resolved->as.spec_decl.name.length,
                        resolved->as.spec_decl.name.data));
            }
        }
    }

    for (i = 0U; i < type_decl->as.type_decl.declared_spec_count; ++i) {
        const FengTypeRef *declared_spec_ref = type_decl->as.type_decl.declared_specs[i];
        const FengDecl *spec = resolve_type_ref_decl(context, type_decl->as.type_decl.declared_specs[i]);

        if (spec != NULL && spec->kind == FENG_DECL_SPEC &&
            declared_spec_ref != NULL && declared_spec_ref->kind == FENG_TYPE_REF_NAMED &&
            declared_spec_ref->as.named.type_arg_count > 0U) {
            ok = verify_type_satisfies_spec(context,
                                            type_decl,
                                            type_decl,
                                            spec,
                                            declared_spec_ref,
                                            type_decl->token,
                                            NULL,
                                            0U,
                                            /*allow_type_private_implementations=*/true);
            if (!ok) {
                free(closure);
                return false;
            }
        }

        if (!spec_collect_closure(context, spec, &closure, &closure_count, &closure_capacity)) {
            free(closure);
            return false;
        }
    }
    for (i = 0U; i < closure_count && ok; ++i) {
        bool verified_direct_generic = false;

        for (j = 0U; j < type_decl->as.type_decl.declared_spec_count; ++j) {
            const FengTypeRef *declared_spec_ref = type_decl->as.type_decl.declared_specs[j];
            const FengDecl *declared_spec = resolve_type_ref_decl(context, declared_spec_ref);

            if (declared_spec == closure[i] && declared_spec_ref != NULL &&
                declared_spec_ref->kind == FENG_TYPE_REF_NAMED &&
                declared_spec_ref->as.named.type_arg_count > 0U) {
                verified_direct_generic = true;
                break;
            }
        }
        if (verified_direct_generic) {
            continue;
        }

        {
            const FengTypeRef *instantiated_spec_ref = NULL;

            for (j = 0U; j < type_decl->as.type_decl.declared_spec_count; ++j) {
                const FengTypeRef *declared_spec_ref = type_decl->as.type_decl.declared_specs[j];
                const FengDecl *declared_spec = resolve_type_ref_decl(context, declared_spec_ref);

                if (declared_spec == NULL || declared_spec == closure[i] ||
                    declared_spec_ref == NULL ||
                    declared_spec_ref->kind != FENG_TYPE_REF_NAMED) {
                    continue;
                }
                instantiated_spec_ref = instantiate_parent_spec_ref_for_instance(
                    context,
                    declared_spec,
                    declared_spec_ref,
                    closure[i]);
                if (instantiated_spec_ref != NULL) {
                    break;
                }
            }

            ok = verify_type_satisfies_spec(context, type_decl, type_decl, closure[i],
                                            instantiated_spec_ref,
                                            type_decl->token, NULL, 0U,
                                            /*allow_type_private_implementations=*/true);
        }
    }
    if (ok) {
        ok = detect_cross_spec_method_conflicts(context, type_decl, closure, closure_count,
                                                type_decl->token);
    }
    free(closure);
    return ok;
}

static bool validate_fit_declaration_contracts(ResolveContext *context,
                                               const FengDecl *fit_decl) {
    const FengTypeRef *target_ref = fit_decl->as.fit_decl.target;
    FitTargetResolution fit_target = resolve_fit_target(context, target_ref);
    const FengDecl *target = fit_target.type_decl;
    size_t i;
    size_t j;
    const FengDecl **closure = NULL;
    size_t closure_count = 0U;
    size_t closure_capacity = 0U;
    bool ok = true;
    bool allow_target_private_implementations = false;

    if (fit_target.kind == FIT_TARGET_KIND_BUILTIN ||
        fit_target.kind == FIT_TARGET_KIND_ARRAY) {
        /* Builtin and array fit targets support both method-only form (no
         * spec_count) and spec-implementation form (spec_count > 0).  Both
         * paths share the same orphan/export downgrade logic; the spec
         * contract validation below (closure, duplicate-spec checks, etc.)
         * requires a user-type target decl and is intentionally skipped here.
         */
        size_t spec_count = fit_decl->as.fit_decl.spec_count;
        /* Require a body when specs are listed: `fit i32: Spec;` (stub without
         * a body) is not valid — specs must be fully implemented by the fit. */
        if (spec_count > 0U && !fit_decl->as.fit_decl.has_body) {
            return resolver_append_error(
                context,
                fit_decl->token,
                "AE0807", format_message("fit with spec clause requires a body; "
                               "use 'fit %s: %s { ... }' to provide the implementation",
                               fit_target.builtin_canonical_name != NULL
                                   ? fit_target.builtin_canonical_name
                                   : "array",
                               "Spec"));
        }
        const FengDecl **specs = spec_count > 0U
            ? (const FengDecl **)malloc(spec_count * sizeof(const FengDecl *))
            : NULL;
        bool spec_ok = true;

        for (size_t si = 0U; si < spec_count && spec_ok; ++si) {
            const FengTypeRef *sr = fit_decl->as.fit_decl.specs[si];
            const FengDecl *sd = resolve_type_ref_decl(context, sr);
            if (sd == NULL || sd->kind != FENG_DECL_SPEC) {
                char *sname = format_type_ref_name(sr);
                spec_ok = resolver_append_error(
                    context, sr != NULL ? sr->token : fit_decl->token,
                    "AE0808", format_message("fit spec '%s' could not be resolved",
                                   sname != NULL ? sname : "<unknown>"));
                free(sname);
            } else if (sd->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
                spec_ok = resolver_append_error(
                    context,
                    sr != NULL ? sr->token : fit_decl->token,
                    "AE0809", format_message("fit specs list can only contain object-form specs"));
            } else if (specs != NULL) {
                specs[si] = sd;
            }
        }
        if (!spec_ok) {
            free(specs);
            return false;
        }
        bool result = maybe_downgrade_orphan_fit_export(context,
                                                        fit_decl,
                                                        fit_target,
                                                        specs,
                                                        spec_count);
        free(specs);
        return result;
    }

    if (fit_target.kind != FIT_TARGET_KIND_USER_TYPE || target == NULL) {
        char *target_name = format_type_ref_name(fit_decl->as.fit_decl.target);
        bool result = resolver_append_error(
            context, fit_decl->as.fit_decl.target->token,
            "AE0811", format_message(
                "fit target must be a concrete type but found '%s'",
                target_name != NULL ? target_name : "<unknown>"));

        free(target_name);
        return result;
    }

    allow_target_private_implementations =
        fit_may_use_target_private_implementations(context, target);

    if (target->kind == FENG_DECL_TYPE && target->as.type_decl.type_param_count > 0U) {
        const FengTypeRef *target_ref = fit_decl->as.fit_decl.target;

        if (target_ref == NULL || target_ref->kind != FENG_TYPE_REF_NAMED ||
            target_ref->as.named.type_arg_count != target->as.type_decl.type_param_count) {
            return resolver_append_error(
                context,
                fit_decl->token,
                "AE0812", format_message(
                    "fit target for generic type '%.*s' must reference all target type parameters directly",
                    (int)target->as.type_decl.name.length,
                    target->as.type_decl.name.data));
        }
        for (i = 0U; i < target->as.type_decl.type_param_count; ++i) {
            const FengTypeRef *arg = target_ref->as.named.type_args[i];
            if (arg == NULL || arg->kind != FENG_TYPE_REF_NAMED ||
                arg->as.named.segment_count != 1U ||
                arg->as.named.type_arg_count != 0U ||
                !slice_equals(arg->as.named.segments[0], target->as.type_decl.type_params[i].name)) {
                return resolver_append_error(
                    context,
                    arg != NULL ? arg->token : fit_decl->token,
                    "AE0812", format_message(
                        "fit target for generic type '%.*s' must use target type parameter '%.*s' at position %zu",
                        (int)target->as.type_decl.name.length,
                        target->as.type_decl.name.data,
                        (int)target->as.type_decl.type_params[i].name.length,
                        target->as.type_decl.type_params[i].name.data,
                        i + 1U));
            }
        }
    } else if (fit_decl->as.fit_decl.target != NULL &&
               fit_decl->as.fit_decl.target->kind == FENG_TYPE_REF_NAMED &&
               fit_decl->as.fit_decl.target->as.named.type_arg_count > 0U) {
        FengSlice target_name = decl_typeish_name(target);
        return resolver_append_error(
            context,
            fit_decl->as.fit_decl.target->token,
            "AE0813", format_message("fit target type '%.*s' is not generic",
                           (int)target_name.length,
                           target_name.data));
    }

    for (i = 0U; i < fit_decl->as.fit_decl.spec_count; ++i) {
        const FengTypeRef *r = fit_decl->as.fit_decl.specs[i];
        const FengDecl *resolved = resolve_type_ref_decl(context, r);

        if (resolved == NULL || resolved->kind != FENG_DECL_SPEC) {
            char *spec_name = format_type_ref_name(r);
            bool result = resolver_append_error(
                context, r->token,
                "AE0809", format_message(
                    "fit specs list must contain only spec types but found '%s'",
                    spec_name != NULL ? spec_name : "<unknown>"));

            free(spec_name);
            return result;
        }
        if (resolved->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            return resolver_append_error(
                context,
                r->token,
                "AE0809", format_message("fit specs list can only contain object-form specs"));
        }
        for (j = 0U; j < i; ++j) {
            const FengDecl *prev = resolve_type_ref_decl(context, fit_decl->as.fit_decl.specs[j]);

            if (prev == resolved) {
                return resolver_append_error(
                    context, r->token,
                    "AE0810", format_message(
                        "fit lists '%.*s' more than once in its specs clause",
                        (int)resolved->as.spec_decl.name.length,
                        resolved->as.spec_decl.name.data));
            }
        }
    }

    for (i = 0U; i < fit_decl->as.fit_decl.spec_count; ++i) {
        const FengTypeRef *fit_spec_ref = fit_decl->as.fit_decl.specs[i];
        const FengDecl *spec = resolve_type_ref_decl(context, fit_decl->as.fit_decl.specs[i]);

        if (spec != NULL && spec->kind == FENG_DECL_SPEC &&
            fit_spec_ref != NULL && fit_spec_ref->kind == FENG_TYPE_REF_NAMED &&
            fit_spec_ref->as.named.type_arg_count > 0U) {
            ok = verify_type_satisfies_spec(
                context,
                target,
                fit_decl,
                spec,
                fit_spec_ref,
                fit_decl->token,
                (const FengTypeMember *const *)fit_decl->as.fit_decl.members,
                fit_decl->as.fit_decl.member_count,
                allow_target_private_implementations);
            if (!ok) {
                free(closure);
                return false;
            }
        }

        if (!spec_collect_closure(context, spec, &closure, &closure_count, &closure_capacity)) {
            free(closure);
            return false;
        }
    }
    for (i = 0U; i < closure_count && ok; ++i) {
        bool verified_direct_generic = false;

        for (j = 0U; j < fit_decl->as.fit_decl.spec_count; ++j) {
            const FengTypeRef *fit_spec_ref = fit_decl->as.fit_decl.specs[j];
            const FengDecl *fit_spec = resolve_type_ref_decl(context, fit_spec_ref);

            if (fit_spec == closure[i] && fit_spec_ref != NULL &&
                fit_spec_ref->kind == FENG_TYPE_REF_NAMED &&
                fit_spec_ref->as.named.type_arg_count > 0U) {
                verified_direct_generic = true;
                break;
            }
        }
        if (verified_direct_generic) {
            continue;
        }

        {
            const FengTypeRef *instantiated_spec_ref = NULL;

            for (j = 0U; j < fit_decl->as.fit_decl.spec_count; ++j) {
                const FengTypeRef *fit_spec_ref = fit_decl->as.fit_decl.specs[j];
                const FengDecl *fit_spec = resolve_type_ref_decl(context, fit_spec_ref);

                if (fit_spec == NULL || fit_spec == closure[i] ||
                    fit_spec_ref == NULL ||
                    fit_spec_ref->kind != FENG_TYPE_REF_NAMED) {
                    continue;
                }
                instantiated_spec_ref = instantiate_parent_spec_ref_for_instance(
                    context,
                    fit_spec,
                    fit_spec_ref,
                    closure[i]);
                if (instantiated_spec_ref != NULL) {
                    break;
                }
            }

            ok = verify_type_satisfies_spec(
                context, target, fit_decl, closure[i], instantiated_spec_ref, fit_decl->token,
                (const FengTypeMember *const *)fit_decl->as.fit_decl.members,
                fit_decl->as.fit_decl.member_count,
                allow_target_private_implementations);
        }
    }
    if (ok) {
        ok = detect_cross_spec_method_conflicts(context, target, closure, closure_count,
                                                fit_decl->token);
    }
    if (ok) {
        ok = maybe_downgrade_orphan_fit_export(context,
                                               fit_decl,
                                               fit_target,
                                               closure,
                                               closure_count);
    }
    free(closure);
    return ok;
}

/* G4-3: Validate the constraints on a list of type parameters.
 * Each constraint (if present) must resolve to a spec declaration. */
static bool validate_type_param_constraints(ResolveContext *context,
                                            const FengTypeParam *type_params,
                                            size_t type_param_count) {
    size_t i;

    for (i = 0U; i < type_param_count; ++i) {
        if (type_params[i].constraint == NULL) {
            continue;
        }
        if (!resolve_type_ref(context, type_params[i].constraint, false)) {
            return false;
        }
        {
            const FengDecl *constraint_decl =
                resolve_type_ref_decl(context, type_params[i].constraint);

            if (decl_is_tuple_type(constraint_decl)) {
                return resolver_append_error(
                    context,
                    type_params[i].token,
                    "AE0304", format_message("type parameter '%.*s': tuple type cannot be used as a constraint; use a spec constraint",
                                   (int)type_params[i].name.length,
                                   type_params[i].name.data));
            }
            if (constraint_decl != NULL && constraint_decl->kind != FENG_DECL_SPEC) {
                return resolver_append_error(
                    context,
                    type_params[i].token,
                    "AE0709", format_message("type parameter '%.*s': constraint must be a spec, not a type",
                                   (int)type_params[i].name.length,
                                   type_params[i].name.data));
            }
        }
    }
    return true;
}

static bool resolve_intersection_spec_form(ResolveContext *context, const FengDecl *decl) {
    const FengDecl **flattened = NULL;
    size_t flattened_count = 0U;
    size_t flattened_capacity = 0U;
    size_t index;
    bool ok = true;

    for (index = 0U; ok && index < decl->as.spec_decl.as.intersection_form.member_count; ++index) {
        const FengTypeRef *member_ref = decl->as.spec_decl.as.intersection_form.members[index];
        const FengDecl *member_decl;

        if (!resolve_type_ref(context, member_ref, false)) {
            ok = false;
            break;
        }
        member_decl = resolve_type_ref_decl(context, member_ref);
        if (member_decl == NULL || member_decl->kind != FENG_DECL_SPEC) {
            char *target_name = format_type_ref_name(member_ref);
            ok = resolver_append_error(
                context, member_ref->token,
                "AE0621", format_message(
                    "intersection-form spec '%.*s' members must be spec types but found '%s'",
                    (int)decl->as.spec_decl.name.length,
                    decl->as.spec_decl.name.data,
                    target_name != NULL ? target_name : "<unknown>"));
            free(target_name);
            break;
        }
        if (member_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT &&
            member_decl->as.spec_decl.form != FENG_SPEC_FORM_INTERSECTION) {
            ok = resolver_append_error(
                context, member_ref->token,
                "AE0621", format_message(
                    "intersection-form spec '%.*s' members must be object-form or intersection-form specs",
                    (int)decl->as.spec_decl.name.length,
                    decl->as.spec_decl.name.data));
            break;
        }
        if (member_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
            const FengIntersectionSpecInfo *inner_info =
                feng_semantic_lookup_intersection_spec_info(context->analysis, member_decl);
            if (inner_info == NULL) {
                ok = false;
                break;
            }
            for (size_t inner_idx = 0U; inner_idx < inner_info->flattened_member_count; ++inner_idx) {
                const FengDecl *leaf = inner_info->flattened_members[inner_idx];
                bool duplicate = false;
                for (size_t dup_idx = 0U; dup_idx < flattened_count; ++dup_idx) {
                    if (flattened[dup_idx] == leaf) {
                        duplicate = true;
                        break;
                    }
                }
                if (duplicate) {
                    continue;
                }
                if (!append_raw((void **)&flattened, &flattened_count, &flattened_capacity,
                                sizeof(*flattened), &leaf)) {
                    ok = false;
                    break;
                }
            }
        } else {
            bool duplicate = false;
            for (size_t dup_idx = 0U; dup_idx < flattened_count; ++dup_idx) {
                if (flattened[dup_idx] == member_decl) {
                    duplicate = true;
                    break;
                }
            }
            if (duplicate) {
                continue;
            }
            if (!append_raw((void **)&flattened, &flattened_count, &flattened_capacity,
                            sizeof(*flattened), &member_decl)) {
                ok = false;
            }
        }
    }
    if (ok) {
        ok = feng_semantic_record_intersection_spec_info(context->analysis, decl,
                                                         flattened, flattened_count);
        if (ok && flattened_count > 1U) {
            ok = detect_cross_spec_method_conflicts(context, decl, flattened,
                                                     flattened_count, decl->token);
        }
    } else {
        free(flattened);
    }
    return ok;
}

/* Read the constructor overload selected while resolving a source expression. */
static const FengTypeMember *member_mix_selected_constructor(
    const FengExpr *source_constructor) {
    const FengExpr *target = member_mix_construction_target(source_constructor);

    if (target != NULL && target->kind == FENG_EXPR_CALL &&
        target->as.call.resolved_callable.kind ==
            FENG_RESOLVED_CALLABLE_TYPE_CONSTRUCTOR) {
        return target->as.call.resolved_callable.member;
    }
    return NULL;
}

/* Return whether the source object-literal phase explicitly binds a field. */
static bool member_mix_object_literal_binds_field(const FengExpr *source_constructor,
                                                  FengSlice field_name) {
    if (source_constructor == NULL ||
        source_constructor->kind != FENG_EXPR_OBJECT_LITERAL) {
        return false;
    }
    for (size_t index = 0U;
         index < source_constructor->as.object_literal.field_count;
         ++index) {
        if (slice_equals(source_constructor->as.object_literal.fields[index].name,
                         field_name)) {
            return true;
        }
    }
    return false;
}

/* Resolve explicit source construction once as a semantic expression and
 * propagate its compile-time final-binding facts to the generated fields.
 * The code generator separately guarantees one runtime evaluation. */
static bool resolve_type_member_mix_initializers(ResolveContext *context,
                                                 const FengDecl *type_decl) {
    if (context == NULL || type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return true;
    }

    for (size_t mixin_index = 0U;
         mixin_index < type_decl->as.type_decl.mixin_count;
         ++mixin_index) {
        const FengTypeMixinDecl *mixin = &type_decl->as.type_decl.mixins[mixin_index];
        const FengTypeMember *constructor;
        ResolvedTypeTarget constructed_target;

        if (mixin->source_constructor == NULL) {
            continue;
        }
        if (!resolve_expr(context, mixin->source_constructor, false)) {
            return false;
        }
        if (!validate_expr_against_expected_type(context,
                                                 mixin->source_constructor,
                                                 mixin->source_type)) {
            return false;
        }
        constructed_target = resolve_type_target_expr(
            context,
            member_mix_construction_target(mixin->source_constructor),
            true);
        if (constructed_target.type_decl != mixin->resolved_source_decl) {
            return resolver_append_error(
                context,
                mixin->token,
                "AE0329",
                format_message(
                    "member mix initializer must construct the declared source type"));
        }
        constructor = member_mix_selected_constructor(mixin->source_constructor);

        for (size_t member_index = 0U;
             member_index < type_decl->as.type_decl.member_count;
             ++member_index) {
            FengTypeMember *member = type_decl->as.type_decl.members[member_index];
            const FengTypeMember *source_field;
            bool declaration_bound;

            if (member == NULL || member->kind != FENG_TYPE_MEMBER_FIELD ||
                member->mixin_origin != mixin ||
                member->mixin_source_member == NULL) {
                continue;
            }
            source_field = member->mixin_source_member;
            declaration_bound =
                source_field->as.field.mutability == FENG_MUTABILITY_VAR ||
                field_has_declaration_initializer(source_field) ||
                constructor_binds_let_field(mixin->resolved_source_decl,
                                            constructor,
                                            source_field->as.field.name) ||
                member_mix_object_literal_binds_field(
                    mixin->source_constructor,
                    source_field->as.field.name);
            if (declaration_bound && !member->as.field.declaration_bound) {
                member->as.field.declaration_bound = true;
                if (context->callable_return_cache != NULL) {
                    context->callable_return_cache->changed = true;
                }
            }
        }
    }
    return true;
}

/* Validate one normalized mixable member before ordinary member checks. */
static bool validate_mixable_member_contract(ResolveContext *context,
                                             const FengTypeMember *member,
                                             const FengDecl *owner_type,
                                             const char *nominal_error_code) {
    const FengDecl *spec_decl;

    if (member == NULL || !member->is_mixable) {
        return true;
    }
    if (member->kind == FENG_TYPE_MEMBER_FIELD) {
        if (owner_type != NULL && owner_type->kind == FENG_DECL_TYPE &&
            !member->is_static &&
            member->visibility == FENG_VISIBILITY_PRIVATE) {
            return true;
        }
        return resolver_append_error(
            context,
            member->token,
            "AE1330",
            format_message(
                "@mixable can only be applied to static methods declared in a type or fit block, or seal instance fields declared in a type"));
    }
    if (owner_type != NULL && owner_type->kind == FENG_DECL_SPEC) {
        return resolver_append_error(
            context,
            member->token,
            "AE1330",
            format_message(
                "@mixable can only be applied to static methods declared in a type or fit block, or seal instance fields declared in a type"));
    }
    if (member->kind != FENG_TYPE_MEMBER_METHOD || !member->is_static) {
        return resolver_append_error(
            context,
            member->token,
            "AE1330",
            format_message(
                "@mixable can only be applied to static methods declared in a type or fit block, or seal instance fields declared in a type"));
    }
    if (member->as.callable.param_count == 0U) {
        return resolver_append_error(
            context,
            member->token,
            "AE1331",
            format_message(
                "@mixable static method '%.*s' must declare at least one parameter",
                (int)member->as.callable.name.length,
                member->as.callable.name.data));
    }
    if (member->as.callable.params[0].is_variadic) {
        return resolver_append_error(
            context,
            member->as.callable.params[0].token,
            "AE1332",
            format_message(
                "@mixable static method '%.*s' first parameter cannot be variadic",
                (int)member->as.callable.name.length,
                member->as.callable.name.data));
    }
    if (!resolve_type_ref(context, member->as.callable.params[0].type, false)) {
        return false;
    }
    spec_decl = resolve_type_ref_decl(context, member->as.callable.params[0].type);
    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return resolver_append_error(
            context,
            member->as.callable.params[0].token,
            "AE1333",
            format_message(
                "@mixable static method '%.*s' first parameter must use an object-form spec",
                (int)member->as.callable.name.length,
                member->as.callable.name.data));
    }
    if (!type_decl_satisfies_spec_decl(context, owner_type, spec_decl)) {
        return resolver_append_error(
            context,
            member->as.callable.params[0].token,
            nominal_error_code,
            format_message(
                "type '%.*s' must nominally declare spec '%.*s' before declaring @mixable static method '%.*s'",
                owner_type != NULL && owner_type->kind == FENG_DECL_TYPE
                    ? (int)owner_type->as.type_decl.name.length
                    : 0,
                owner_type != NULL && owner_type->kind == FENG_DECL_TYPE
                    ? owner_type->as.type_decl.name.data
                    : "",
                (int)spec_decl->as.spec_decl.name.length,
                spec_decl->as.spec_decl.name.data,
                (int)member->as.callable.name.length,
                member->as.callable.name.data));
    }
    return true;
}

static bool resolve_declaration(ResolveContext *context, const FengDecl *decl) {
    size_t index;

    if (!validate_supported_decl_annotations(context, decl)) {
        return false;
    }

    if (!validate_runtime_annotation_on_decl(context, decl)) {
        return false;
    }

    if (!validate_value_annotation_on_decl(context, decl)) {
        return false;
    }

    switch (decl->kind) {
        case FENG_DECL_GLOBAL_BINDING:
            return resolve_binding(context, &decl->as.binding, false, false);

        case FENG_DECL_ENUM:
            return ensure_enum_decl_info(context, decl);

        case FENG_DECL_TYPE: {
            /* G4-1: Push the type's own type parameters into scope so that
             * field types, declared spec refs, and member methods can all
             * reference them.  Method-level type params (if any) are pushed
             * additionally by resolve_callable.
             * G4-3: Validate constraints before resolving members. */
            const TypeParamEntry *prev_tp = NULL;
            size_t prev_tp_count = 0U;
            bool ok;

            if (!resolver_push_type_params(context,
                                           decl->as.type_decl.type_params,
                                           decl->as.type_decl.type_param_count,
                                           &prev_tp, &prev_tp_count)) {
                return false;
            }

            if (!validate_type_param_constraints(context,
                                                 decl->as.type_decl.type_params,
                                                 decl->as.type_decl.type_param_count)) {
                resolver_pop_type_params(context, prev_tp, prev_tp_count);
                return false;
            }

            ok = true;
            for (index = 0U; ok && index < decl->as.type_decl.declared_spec_count; ++index) {
                if (!resolve_type_ref(context, decl->as.type_decl.declared_specs[index], false)) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                const FengDecl *previous_implementation_owner =
                    context->current_type_implementation_owner;

                context->current_type_implementation_owner = decl;
                ok = resolve_type_member_mix_initializers(context, decl);
                context->current_type_implementation_owner =
                    previous_implementation_owner;
            }
            for (index = 0U; ok && index < decl->as.type_decl.member_count; ++index) {
                const FengTypeMember *member = decl->as.type_decl.members[index];
                const FengDecl *previous_type_decl = context->current_type_decl;
                const FengDecl *previous_implementation_owner =
                    context->current_type_implementation_owner;
                const FengTypeMember *previous_callable_member = context->current_callable_member;
                const FengTypeMember *previous_callable_body_member =
                    context->current_callable_body_member;

                if (!validate_supported_member_annotations(context, member)) {
                    ok = false;
                    break;
                }

                if (!validate_runtime_annotation_on_member(context, member)) {
                    ok = false;
                    break;
                }

                if (!normalize_friend_member_annotations(
                        context,
                        decl,
                        member,
                        decl->as.type_decl.type_params,
                        decl->as.type_decl.type_param_count)) {
                    ok = false;
                    break;
                }

                if (!validate_mixable_member_contract(context,
                                                       member,
                                                       decl,
                                                       "AE1334")) {
                    ok = false;
                    break;
                }

                if (member->kind == FENG_TYPE_MEMBER_FIELD) {
                    bool field_is_callable_spec = false;
                    bool prev_self_capturable = context->self_capturable;
                    bool init_is_lambda = member->as.field.initializer != NULL &&
                                          member->as.field.initializer->kind == FENG_EXPR_LAMBDA;

                    if (!resolve_type_ref(context, member->as.field.type, false)) {
                        ok = false;
                        break;
                    }
                    if (member->is_static &&
                        member->as.field.initializer == NULL &&
                        !validate_binding_default_zero_target(
                            context,
                            member->as.field.type,
                            member->token)) {
                        ok = false;
                        break;
                    }
                    /* A field initializer is part of the owning type's
                     * implementation and may use that type's seal static
                     * members. This does not make direct self capture legal. */
                    context->current_type_decl = decl;
                    context->current_type_implementation_owner = decl;
                    /* Per docs/specifications/feng-function.md: a callable-spec field whose
                     * initializer is a lambda may capture the enclosing
                     * type's `self`, because the lambda runs only when the
                     * callable is invoked, after the object is constructed.
                     * Direct `self` references in the initializer expression
                     * itself remain disallowed. */
                    if (!member->is_static &&
                        init_is_lambda &&
                        resolve_function_type_decl(context, member->as.field.type) != NULL) {
                        field_is_callable_spec = true;
                        context->current_type_decl = decl;
                        context->self_capturable = true;
                    }
                    {
                        InferredExprType field_type;
                        bool init_ok = resolve_expr(context, member->as.field.initializer, false);
                        bool match_ok = init_ok &&
                                         validate_expr_against_expected_type(
                                             context,
                                             member->as.field.initializer,
                                             member->as.field.type);

                        if (field_is_callable_spec) {
                            context->self_capturable = prev_self_capturable;
                        }
                        if (!init_ok || !match_ok) {
                            context->current_type_implementation_owner =
                                previous_implementation_owner;
                            context->current_type_decl = previous_type_decl;
                            ok = false;
                            break;
                        }

                        if (member->as.field.type != NULL) {
                            field_type = inferred_expr_type_from_type_ref(member->as.field.type);
                        } else if (member->mixin_source_member != NULL &&
                                   member->mixin_origin != NULL) {
                            const FengSemanticTypeFact *source_fact =
                                feng_semantic_lookup_type_fact(
                                    context->analysis,
                                    member->mixin_source_member);

                            field_type = inferred_expr_type_from_type_fact(source_fact);
                            if (field_type.kind == FENG_INFERRED_EXPR_TYPE_TYPE_REF &&
                                field_type.type_ref != NULL) {
                                InferredExprType source_owner =
                                    inferred_expr_type_from_type_ref(
                                        member->mixin_origin->source_type);

                                field_type.type_ref =
                                    substitute_type_ref_for_owner_instance(
                                        context,
                                        member->mixin_origin->resolved_source_decl,
                                        source_owner,
                                        field_type.type_ref);
                            }
                            if (!inferred_expr_type_is_known(field_type) &&
                                context->callable_return_cache != NULL) {
                                context->callable_return_cache->changed = true;
                            }
                        } else {
                            field_type = infer_expr_type(context,
                                                         member->as.field.initializer);
                        }
                        if (!record_type_fact_for_site(context, member, field_type)) {
                            context->current_type_implementation_owner =
                                previous_implementation_owner;
                            context->current_type_decl = previous_type_decl;
                            ok = false;
                            break;
                        }
                    }
                    if (member->as.field.initializer == NULL) {
                        /* Phase S2-a: a `let`/`var` field whose declared type
                         * is a spec and whose initializer is omitted at the
                         * member declaration site is a default-witness slot
                         * (the field may still be assigned later in the
                         * constructor; that does not change the syntactic
                         * default-witness obligation here). */
                        record_spec_default_binding_if_applicable(
                            context,
                            member,
                            FENG_SPEC_DEFAULT_BINDING_POSITION_TYPE_FIELD,
                            member->as.field.type);
                    }
                    context->current_type_implementation_owner =
                        previous_implementation_owner;
                    context->current_type_decl = previous_type_decl;
                    continue;
                }

                if (!validate_special_member_type_params(context, member)) {
                    ok = false;
                    break;
                }

                context->current_type_decl = decl;
                context->current_type_implementation_owner = decl;
                context->current_callable_member = member;
                context->current_callable_body_member = member;
                if (!resolve_callable(context, &member->as.callable, !member->is_static)) {
                    context->current_callable_member = previous_callable_member;
                    context->current_callable_body_member =
                        previous_callable_body_member;
                    context->current_type_implementation_owner =
                        previous_implementation_owner;
                    context->current_type_decl = previous_type_decl;
                    ok = false;
                    break;
                }
                if (!validate_abi_callable_member(context, member)) {
                    context->current_callable_member = previous_callable_member;
                    context->current_callable_body_member =
                        previous_callable_body_member;
                    context->current_type_implementation_owner =
                        previous_implementation_owner;
                    context->current_type_decl = previous_type_decl;
                    ok = false;
                    break;
                }
                context->current_callable_member = previous_callable_member;
                context->current_callable_body_member =
                    previous_callable_body_member;
                context->current_type_implementation_owner =
                    previous_implementation_owner;
                context->current_type_decl = previous_type_decl;
            }

            if (ok && !validate_abi_type_declaration(context, decl)) {
                ok = false;
            }
            if (ok && !validate_declared_method_overloads(context, decl)) {
                ok = false;
            }
            if (ok && !validate_declared_field_name_conflicts(context, decl)) {
                ok = false;
            }
            if (ok &&
                !validate_declared_method_overload_overlap(context, decl)) {
                ok = false;
            }
            if (ok &&
                !validate_declared_field_method_name_conflicts(
                    context, decl)) {
                ok = false;
            }
            if (ok && !validate_type_finalizer_constraints(context, decl)) {
                ok = false;
            }
            if (ok && !validate_iterator_annotations(context, decl)) {
                ok = false;
            }
            if (ok) {
                ok = validate_type_declared_specs_and_satisfaction(context, decl);
            }
            resolver_pop_type_params(context, prev_tp, prev_tp_count);
            return ok;
        }

        case FENG_DECL_SPEC: {
            /* G4-1: Push the spec's own type parameters into scope. */
            const TypeParamEntry *prev_tp = NULL;
            size_t prev_tp_count = 0U;
            bool ok;

            if (!resolver_push_type_params(context,
                                           decl->as.spec_decl.type_params,
                                           decl->as.spec_decl.type_param_count,
                                           &prev_tp, &prev_tp_count)) {
                return false;
            }

            if (!validate_type_param_constraints(context,
                                                 decl->as.spec_decl.type_params,
                                                 decl->as.spec_decl.type_param_count)) {
                resolver_pop_type_params(context, prev_tp, prev_tp_count);
                return false;
            }

            ok = true;
            for (index = 0U; ok && index < decl->as.spec_decl.parent_spec_count; ++index) {
                if (!resolve_type_ref(context, decl->as.spec_decl.parent_specs[index], false)) {
                    ok = false;
                }
            }
            if (ok && !validate_spec_parent_spec_list(context, decl)) {
                ok = false;
            }
            if (ok && !validate_object_spec_member_kinds(context, decl)) {
                ok = false;
            }
            if (ok && decl->as.spec_decl.form == FENG_SPEC_FORM_UNION) {
                if (!record_normalized_union_spec_info(context, decl)) {
                    ok = false;
                }
                if (ok) {
                    ok = validate_abi_type_declaration(context, decl);
                }
                resolver_pop_type_params(context, prev_tp, prev_tp_count);
                return ok;
            }
            if (ok && decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
                ok = resolve_intersection_spec_form(context, decl);
                resolver_pop_type_params(context, prev_tp, prev_tp_count);
                return ok;
            }
            if (ok && decl->as.spec_decl.form == FENG_SPEC_FORM_CALLABLE) {
                if (!resolve_type_ref(context, decl->as.spec_decl.as.callable.return_type, true)) {
                    ok = false;
                }
                for (index = 0U; ok && index < decl->as.spec_decl.as.callable.param_count; ++index) {
                    if (!resolve_type_ref(context,
                                          decl->as.spec_decl.as.callable.params[index].type,
                                          false)) {
                        ok = false;
                    }
                }
                if (ok) {
                    ok = validate_abi_type_declaration(context, decl);
                }
                resolver_pop_type_params(context, prev_tp, prev_tp_count);
                return ok;
            }
            for (index = 0U; ok && index < decl->as.spec_decl.as.object.member_count; ++index) {
                const FengTypeMember *member = decl->as.spec_decl.as.object.members[index];

                if (!validate_object_spec_method_type_params(context, member)) {
                    ok = false;
                    break;
                }

                if (!validate_supported_member_annotations(context, member)) {
                    ok = false;
                    break;
                }

                if (!validate_runtime_annotation_on_member(context, member)) {
                    ok = false;
                    break;
                }

                if (!validate_mixable_member_contract(context,
                                                       member,
                                                       decl,
                                                       "AE1334")) {
                    ok = false;
                    break;
                }

                if (!normalize_friend_member_annotations(
                        context,
                        decl,
                        member,
                        decl->as.spec_decl.type_params,
                        decl->as.spec_decl.type_param_count)) {
                    ok = false;
                    break;
                }

                if (member->kind == FENG_TYPE_MEMBER_FIELD) {
                    if (!resolve_type_ref(context, member->as.field.type, false)) {
                        ok = false;
                    }
                    continue;
                }
                {
                    const FengDecl *previous_type_decl =
                        context->current_type_decl;
                    const FengTypeMember *previous_callable_member =
                        context->current_callable_member;
                    const FengTypeMember *previous_callable_body_member =
                        context->current_callable_body_member;

                    context->current_type_decl = decl;
                    context->current_callable_member = member;
                    context->current_callable_body_member = member;
                    ok = resolve_callable(context,
                                          &member->as.callable,
                                          /*allow_self=*/false);
                    context->current_callable_member =
                        previous_callable_member;
                    context->current_callable_body_member =
                        previous_callable_body_member;
                    context->current_type_decl = previous_type_decl;
                }
            }
            if (ok) {
                ok = validate_abi_type_declaration(context, decl);
            }
            if (ok && !validate_declared_method_overloads(context, decl)) {
                ok = false;
            }
            if (ok && !validate_declared_field_name_conflicts(context, decl)) {
                ok = false;
            }
            if (ok &&
                !validate_declared_field_method_name_conflicts(
                    context, decl)) {
                ok = false;
            }
            if (ok &&
                !validate_declared_method_overload_overlap(context, decl)) {
                ok = false;
            }
            if (ok &&
                !validate_object_spec_accumulated_member_conflicts(
                    context, decl)) {
                ok = false;
            }
            if (ok &&
                !validate_object_spec_accumulated_method_overloads(
                    context, decl)) {
                ok = false;
            }
            resolver_pop_type_params(context, prev_tp, prev_tp_count);
            return ok;
        }

        case FENG_DECL_FIT: {
            size_t fit_index;
            FitTargetResolution fit_target;
            const FengDecl *fit_target_decl;
            const TypeParamEntry *prev_tp = NULL;
            size_t prev_tp_count = 0U;
            const TypeParamEntry *prev_fit_tp = NULL;
            size_t prev_fit_tp_count = 0U;
            bool fit_scope_pushed = false;
            bool ok = true;
            FengTypeParam fit_local_type_param;

            fit_target = resolve_fit_target(context, decl->as.fit_decl.target);
            fit_target_decl = fit_target.kind == FIT_TARGET_KIND_USER_TYPE
                                  ? fit_target.type_decl
                                  : NULL;
            if (fit_target_decl != NULL && fit_target_decl->kind == FENG_DECL_TYPE &&
                fit_target_decl->as.type_decl.type_param_count > 0U) {
                if (!resolver_push_type_params(context,
                                               fit_target_decl->as.type_decl.type_params,
                                               fit_target_decl->as.type_decl.type_param_count,
                                               &prev_tp,
                                               &prev_tp_count)) {
                    return false;
                }

            }
            if (fit_target_collect_array_local_type_param(context,
                                                          decl->as.fit_decl.target,
                                                          &fit_local_type_param)) {
                /* Preserve Semantic's visible-symbol decision for later
                 * compiler passes. The fit declaration is a stable sidecar
                 * key and the target element TypeRef is AST-owned. */
                if (!feng_semantic_record_type_fact(
                        context->analysis,
                        decl,
                        FENG_SEMANTIC_TYPE_FACT_TYPE_REF,
                        (FengSlice){0},
                        decl->as.fit_decl.target->as.inner,
                        NULL)) {
                    resolver_pop_type_params(context, prev_tp, prev_tp_count);
                    return false;
                }
                if (!resolver_push_type_params(context,
                                               &fit_local_type_param,
                                               1U,
                                               &prev_fit_tp,
                                               &prev_fit_tp_count)) {
                    resolver_pop_type_params(context, prev_tp, prev_tp_count);
                    return false;
                }
                fit_scope_pushed = true;
            }
            if (!resolve_type_ref(context, decl->as.fit_decl.target, false)) {
                if (fit_scope_pushed) {
                    resolver_pop_type_params(context, prev_fit_tp, prev_fit_tp_count);
                }
                resolver_pop_type_params(context, prev_tp, prev_tp_count);
                return false;
            }
            for (fit_index = 0U; fit_index < decl->as.fit_decl.spec_count; ++fit_index) {
                if (!resolve_type_ref(context, decl->as.fit_decl.specs[fit_index], false)) {
                    if (fit_scope_pushed) {
                        resolver_pop_type_params(context, prev_fit_tp, prev_fit_tp_count);
                    }
                    resolver_pop_type_params(context, prev_tp, prev_tp_count);
                    return false;
                }
            }
            /* Resolve the fit's target type once so that fit-body methods can
             * see `self` as the target type and trigger normal instance member
             * checks. The target may legitimately fail to resolve here (e.g.
             * when the right-hand side is a built-in or unresolved name); in
             * that case `validate_fit_declaration_contracts` reports the proper
             * diagnostic and we simply skip context propagation. */
            for (fit_index = 0U; fit_index < decl->as.fit_decl.member_count; ++fit_index) {
                const FengTypeMember *member = decl->as.fit_decl.members[fit_index];
                const FengDecl *previous_type_decl = context->current_type_decl;
                const FengDecl *previous_fit_decl = context->current_fit_decl;
                const FengTypeRef *previous_fit_target_type_ref =
                    context->current_fit_target_type_ref;
                const FengTypeMember *previous_callable_member =
                    context->current_callable_member;
                const FengTypeMember *previous_callable_body_member =
                    context->current_callable_body_member;
                bool member_ok;

                if (!validate_supported_member_annotations(context, member)) {
                    if (fit_scope_pushed) {
                        resolver_pop_type_params(context, prev_fit_tp, prev_fit_tp_count);
                    }
                    resolver_pop_type_params(context, prev_tp, prev_tp_count);
                    return false;
                }

                if (!normalize_friend_member_annotations(
                        context,
                        decl,
                        member,
                        fit_target_decl != NULL &&
                                fit_target_decl->kind == FENG_DECL_TYPE
                            ? fit_target_decl->as.type_decl.type_params
                            : fit_scope_pushed ? &fit_local_type_param : NULL,
                        fit_target_decl != NULL &&
                                fit_target_decl->kind == FENG_DECL_TYPE
                            ? fit_target_decl->as.type_decl.type_param_count
                            : fit_scope_pushed ? 1U : 0U)) {
                    if (fit_scope_pushed) {
                        resolver_pop_type_params(context,
                                                 prev_fit_tp,
                                                 prev_fit_tp_count);
                    }
                    resolver_pop_type_params(context, prev_tp, prev_tp_count);
                    return false;
                }

                if (!validate_mixable_member_contract(context,
                                                       member,
                                                       fit_target_decl,
                                                       "AE1334")) {
                    if (fit_scope_pushed) {
                        resolver_pop_type_params(context, prev_fit_tp, prev_fit_tp_count);
                    }
                    resolver_pop_type_params(context, prev_tp, prev_tp_count);
                    return false;
                }

                if (!member->is_static &&
                    fit_target_decl != NULL && fit_target_decl->kind == FENG_DECL_TYPE) {
                    context->current_type_decl = fit_target_decl;
                }
                context->current_fit_decl = decl;
                context->current_fit_target_type_ref = decl->as.fit_decl.target;
                context->current_callable_member = member;
                context->current_callable_body_member = member;

                member_ok = resolve_callable(context, &member->as.callable, !member->is_static);

                context->current_callable_member = previous_callable_member;
                context->current_callable_body_member =
                    previous_callable_body_member;
                context->current_fit_decl = previous_fit_decl;
                context->current_fit_target_type_ref = previous_fit_target_type_ref;
                context->current_type_decl = previous_type_decl;

                if (!member_ok) {
                    if (fit_scope_pushed) {
                        resolver_pop_type_params(context, prev_fit_tp, prev_fit_tp_count);
                    }
                    resolver_pop_type_params(context, prev_tp, prev_tp_count);
                    return false;
                }
            }
            ok = validate_fit_member_overloads(context, decl);
            if (ok) {
                ok = validate_fit_member_overload_overlap(context, decl);
            }
            if (ok) {
                ok = validate_fit_declaration_contracts(context, decl);
            }
            if (fit_scope_pushed) {
                resolver_pop_type_params(context, prev_fit_tp, prev_fit_tp_count);
            }
            resolver_pop_type_params(context, prev_tp, prev_tp_count);
            return ok;
        }

        case FENG_DECL_FUNCTION:
            if (!validate_extern_function_annotations(context, decl)) {
                return false;
            }
            {
                const FengTypeMember *previous_callable_body_member =
                    context->current_callable_body_member;
                bool callable_ok;

                context->current_callable_body_member = NULL;
                callable_ok = resolve_callable(
                    context, &decl->as.function_decl, false);
                context->current_callable_body_member =
                    previous_callable_body_member;
                if (!callable_ok) {
                    return false;
                }
            }
            if (!validate_extern_function_signature(context, decl)) {
                return false;
            }
            return validate_abi_function_declaration(context, decl);
    }

    return true;
}

/* Effective declaration visibility ordered from the narrowest scope to the
 * widest scope.  The ordering is used directly by signature consistency
 * checks: every referenced type must have a value greater than or equal to
 * the signature that exposes it. */
typedef enum SignatureEffectiveVisibility {
    SIGNATURE_VISIBILITY_TYPE_PRIVATE = 0,
    SIGNATURE_VISIBILITY_MODULE_PRIVATE,
    SIGNATURE_VISIBILITY_PACKAGE,
    SIGNATURE_VISIBILITY_PUBLIC
} SignatureEffectiveVisibility;

/* Lexical type-parameter scopes active for one declaration signature.
 * Type-parameter references are not declarations and therefore do not
 * participate directly in visibility comparisons. */
typedef struct SignatureTypeParamScope {
    const FengTypeParam *params;
    size_t param_count;
    const struct SignatureTypeParamScope *parent;
} SignatureTypeParamScope;

/* Return the stable diagnostic name for one effective visibility level. */
static const char *signature_visibility_name(SignatureEffectiveVisibility visibility) {
    switch (visibility) {
        case SIGNATURE_VISIBILITY_TYPE_PRIVATE:
            return "type-private";
        case SIGNATURE_VISIBILITY_MODULE_PRIVATE:
            return "module-private";
        case SIGNATURE_VISIBILITY_PACKAGE:
            return "package";
        case SIGNATURE_VISIBILITY_PUBLIC:
            return "public";
    }
    return "unknown";
}

/* Compute the effective visibility of a top-level declaration from its
 * module and declaration modifiers. */
static SignatureEffectiveVisibility signature_decl_visibility(
    const FengSemanticModule *module,
    const FengDecl *decl) {
    if (decl != NULL && decl->kind == FENG_DECL_FIT) {
        return module != NULL &&
                       module->visibility == FENG_VISIBILITY_PUBLIC &&
                       decl->visibility == FENG_VISIBILITY_PUBLIC
                   ? SIGNATURE_VISIBILITY_PUBLIC
                   : SIGNATURE_VISIBILITY_MODULE_PRIVATE;
    }
    if (decl == NULL || decl->visibility != FENG_VISIBILITY_PUBLIC) {
        return SIGNATURE_VISIBILITY_MODULE_PRIVATE;
    }
    if (module == NULL || module->visibility != FENG_VISIBILITY_PUBLIC) {
        return SIGNATURE_VISIBILITY_PACKAGE;
    }
    return SIGNATURE_VISIBILITY_PUBLIC;
}

/* Apply a member visibility modifier to its owner's effective visibility. */
static SignatureEffectiveVisibility signature_member_visibility(
    SignatureEffectiveVisibility owner_visibility,
    const FengTypeMember *member) {
    if (member != NULL && member->visibility == FENG_VISIBILITY_PRIVATE &&
        !feng_semantic_member_is_mixable_seal_capability(member)) {
        return SIGNATURE_VISIBILITY_TYPE_PRIVATE;
    }
    return owner_visibility;
}

/* Return true when a named type reference denotes a type parameter in the
 * active declaration signature. */
static bool signature_type_ref_is_type_param(
    const FengTypeRef *type_ref,
    const SignatureTypeParamScope *scope) {
    const SignatureTypeParamScope *cursor;

    if (type_ref == NULL || type_ref->kind != FENG_TYPE_REF_NAMED ||
        type_ref->as.named.segment_count != 1U ||
        type_ref->as.named.type_arg_count != 0U) {
        return false;
    }
    for (cursor = scope; cursor != NULL; cursor = cursor->parent) {
        size_t param_index;

        for (param_index = 0U; param_index < cursor->param_count; ++param_index) {
            if (slice_equals(type_ref->as.named.segments[0],
                             cursor->params[param_index].name)) {
                return true;
            }
        }
    }
    return false;
}

/* Record the first member-signature type that is seal in the @friend owner's
 * own module. This is exactly the type that cannot be consumed from another
 * module under the friend signature rule. */
static bool scan_friend_signature_type_ref(
    ResolveContext *context,
    struct FengFriendMemberInfo *info,
    const FengTypeRef *type_ref,
    const SignatureTypeParamScope *type_params) {
    if (type_ref == NULL || info == NULL ||
        info->owner_private_signature_decl != NULL) {
        return true;
    }
    if (type_ref->kind == FENG_TYPE_REF_POINTER ||
        type_ref->kind == FENG_TYPE_REF_ARRAY) {
        return scan_friend_signature_type_ref(context,
                                              info,
                                              type_ref->as.inner,
                                              type_params);
    }
    if (signature_type_ref_is_type_param(type_ref, type_params)) {
        return true;
    }
    if (type_ref->kind == FENG_TYPE_REF_NAMED) {
        const FengDecl *target = resolve_type_ref_decl(context, type_ref);

        if (target != NULL &&
            find_decl_provider_module(context->analysis, target) ==
                info->owner_module &&
            target->visibility != FENG_VISIBILITY_PUBLIC) {
            info->owner_private_signature_decl = target;
            info->owner_private_signature_ref = type_ref;
            return true;
        }
        for (size_t index = 0U;
             index < type_ref->as.named.type_arg_count;
             ++index) {
            if (!scan_friend_signature_type_ref(
                    context,
                    info,
                    type_ref->as.named.type_args[index],
                    type_params)) {
                return false;
            }
        }
    }
    return true;
}

/* Scan an inferred field/return surface using the same owner-module rule. */
static bool scan_friend_signature_type_fact(
    ResolveContext *context,
    struct FengFriendMemberInfo *info,
    const FengSemanticTypeFact *fact,
    const SignatureTypeParamScope *type_params) {
    if (fact == NULL || info == NULL ||
        info->owner_private_signature_decl != NULL) {
        return true;
    }
    if (fact->kind == FENG_SEMANTIC_TYPE_FACT_TYPE_REF) {
        return scan_friend_signature_type_ref(context,
                                              info,
                                              fact->type_ref,
                                              type_params);
    }
    if (fact->kind == FENG_SEMANTIC_TYPE_FACT_DECL &&
        fact->type_decl != NULL &&
        find_decl_provider_module(context->analysis, fact->type_decl) ==
            info->owner_module &&
        fact->type_decl->visibility != FENG_VISIBILITY_PUBLIC) {
        info->owner_private_signature_decl = fact->type_decl;
        info->owner_private_signature_ref = NULL;
    }
    return true;
}

/* Format the first owner-private signature type for AE1338 diagnostics. */
static char *format_friend_hidden_signature_type(
    const struct FengFriendMemberInfo *info) {
    if (info == NULL || info->owner_private_signature_decl == NULL) {
        return duplicate_cstr("<unknown>");
    }
    if (info->owner_private_signature_ref != NULL) {
        return format_type_ref_name(info->owner_private_signature_ref);
    }
    {
        FengSlice name = decl_typeish_name(info->owner_private_signature_decl);

        return format_message("%.*s", (int)name.length, name.data);
    }
}

/* Validate one normalized @friend member after all explicit and inferred
 * signature types are known. Direct friends and recorded same-package fit
 * users share the same owner-module-private type scan. */
static bool validate_friend_member_signature_rules(
    ResolveContext *context,
    const FengTypeMember *member,
    const SignatureTypeParamScope *owner_type_params) {
    struct FengFriendMemberInfo *info;
    FengSlice member_name;

    info = (struct FengFriendMemberInfo *)find_friend_member_info(
        context != NULL ? context->analysis : NULL, member);
    if (info == NULL) {
        return true;
    }
    info->signature_checked = false;
    info->owner_private_signature_decl = NULL;
    info->owner_private_signature_ref = NULL;
    if (member->kind == FENG_TYPE_MEMBER_FIELD) {
        if (member->as.field.type != NULL) {
            if (!scan_friend_signature_type_ref(context,
                                                info,
                                                member->as.field.type,
                                                owner_type_params)) {
                return false;
            }
        } else if (!scan_friend_signature_type_fact(
                       context,
                       info,
                       feng_semantic_lookup_type_fact(context->analysis,
                                                      member),
                       owner_type_params)) {
            return false;
        }
    } else if (member->kind == FENG_TYPE_MEMBER_METHOD) {
        const FengCallableSignature *callable = &member->as.callable;
        SignatureTypeParamScope callable_scope = {
            callable->type_params,
            callable->type_param_count,
            owner_type_params};

        for (size_t index = 0U;
             index < callable->type_param_count;
             ++index) {
            if (!scan_friend_signature_type_ref(
                    context,
                    info,
                    callable->type_params[index].constraint,
                    &callable_scope)) {
                return false;
            }
        }
        for (size_t index = 0U; index < callable->param_count; ++index) {
            if (!scan_friend_signature_type_ref(
                    context,
                    info,
                    callable->params[index].type,
                    &callable_scope)) {
                return false;
            }
        }
        if (callable->return_type != NULL) {
            if (!scan_friend_signature_type_ref(context,
                                                info,
                                                callable->return_type,
                                                &callable_scope)) {
                return false;
            }
        } else if (!scan_friend_signature_type_fact(
                       context,
                       info,
                       feng_semantic_lookup_type_fact(context->analysis,
                                                      callable),
                       &callable_scope)) {
            return false;
        }
    }
    info->signature_checked = true;
    member_name = member->kind == FENG_TYPE_MEMBER_FIELD
                      ? member->as.field.name
                      : member->as.callable.name;
    for (size_t index = 0U; index < info->friend_type_count; ++index) {
        const FriendTypeIdentity *friend_type = info->friend_types[index];
        const FengSemanticModule *friend_module =
            friend_type->kind == FRIEND_TYPE_IDENTITY_NAMED
                ? find_decl_provider_module(context->analysis,
                                            friend_type->as.named.decl)
                : NULL;

        if (friend_module == NULL ||
            friend_member_signature_visible_from_module(info,
                                                        friend_module)) {
            continue;
        }
        {
            char *friend_name = format_type_ref_name(friend_type->source_ref);
            char *hidden_name = format_friend_hidden_signature_type(info);
            bool ok = resolver_append_error(
                context,
                friend_type->source_ref != NULL
                    ? friend_type->source_ref->token
                    : member->token,
                "AE1338",
                format_message(
                    "member '%.*s' exposes type '%s' that is not accessible to friend type '%s'",
                    (int)member_name.length,
                    member_name.data,
                    hidden_name != NULL ? hidden_name : "<unknown>",
                    friend_name != NULL ? friend_name : "<unknown>"));

            free(hidden_name);
            free(friend_name);
            return ok && false;
        }
    }
    for (size_t index = 0U; index < info->fit_access_count; ++index) {
        const FriendFitAccess *access = &info->fit_accesses[index];

        if (friend_member_signature_visible_from_module(info,
                                                        access->module)) {
            continue;
        }
        {
            char *module_name = format_module_name(
                access->module->segments, access->module->segment_count);
            char *hidden_name = format_friend_hidden_signature_type(info);
            bool ok = append_error(
                context->errors,
                context->error_count,
                context->error_capacity,
                access->program != NULL ? access->program->path
                                        : context->program->path,
                access->callable_member != NULL
                    ? access->callable_member->token
                    : member->token,
                "AE1338",
                format_message(
                    "@friend member '%.*s' exposes type '%s' that is not accessible from fit module '%s'",
                    (int)member_name.length,
                    member_name.data,
                    hidden_name != NULL ? hidden_name : "<unknown>",
                    module_name != NULL ? module_name : "<unknown>"));

            free(hidden_name);
            free(module_name);
            return ok && false;
        }
    }
    return true;
}

/* Recheck recorded fit friend uses after the complete module fixpoint. This
 * catches a use resolved after its owner program's signature pass in the same
 * iteration, without making correctness depend on program ordering. */
static bool validate_all_friend_fit_access_signatures(
    const FengSemanticAnalysis *analysis,
    FengSemanticError **errors,
    size_t *error_count,
    size_t *error_capacity) {
    if (analysis == NULL) {
        return true;
    }
    for (size_t info_index = 0U;
         info_index < analysis->friend_member_info_count;
         ++info_index) {
        const struct FengFriendMemberInfo *info =
            &analysis->friend_member_infos[info_index];
        FengSlice member_name =
            info->member->kind == FENG_TYPE_MEMBER_FIELD
                ? info->member->as.field.name
                : info->member->as.callable.name;

        if (!info->signature_checked ||
            info->owner_private_signature_decl == NULL) {
            continue;
        }
        for (size_t access_index = 0U;
             access_index < info->fit_access_count;
             ++access_index) {
            const FriendFitAccess *access = &info->fit_accesses[access_index];

            if (access->module == info->owner_module) {
                continue;
            }
            {
                char *hidden_name = format_friend_hidden_signature_type(info);
                char *module_name = format_module_name(
                    access->module->segments, access->module->segment_count);
                bool ok = append_error(
                    errors,
                    error_count,
                    error_capacity,
                    access->program != NULL ? access->program->path : NULL,
                    access->callable_member != NULL
                        ? access->callable_member->token
                        : info->member->token,
                    "AE1338",
                    format_message(
                        "@friend member '%.*s' exposes type '%s' that is not accessible from fit module '%s'",
                        (int)member_name.length,
                        member_name.data,
                        hidden_name != NULL ? hidden_name : "<unknown>",
                        module_name != NULL ? module_name : "<unknown>"));

                free(module_name);
                free(hidden_name);
                if (!ok) {
                    return false;
                }
                return false;
            }
        }
    }
    return true;
}

/* Return the source-level name used to identify a declaration signature in
 * AE0327 diagnostics. */
static FengSlice signature_decl_name(const FengDecl *decl) {
    static const char kFitName[] = "fit";

    if (decl == NULL) {
        return (FengSlice){NULL, 0U};
    }
    switch (decl->kind) {
        case FENG_DECL_GLOBAL_BINDING:
            return decl->as.binding.name;
        case FENG_DECL_TYPE:
            return decl->as.type_decl.name;
        case FENG_DECL_ENUM:
            return decl->as.enum_decl.name;
        case FENG_DECL_SPEC:
            return decl->as.spec_decl.name;
        case FENG_DECL_FIT:
            return (FengSlice){kFitName, sizeof(kFitName) - 1U};
        case FENG_DECL_FUNCTION:
            return decl->as.function_decl.name;
    }
    return (FengSlice){NULL, 0U};
}

/* Append one AE0327 diagnostic for a type whose visibility is narrower than
 * the declaration signature that exposes it. */
static bool report_signature_visibility_error(
    ResolveContext *context,
    FengSlice signature_name,
    FengToken token,
    SignatureEffectiveVisibility signature_visibility,
    const char *type_name,
    SignatureEffectiveVisibility type_visibility) {
    return resolver_append_error(
        context,
        token,
        "AE0327",
        format_message(
            "declaration '%.*s' has effective visibility '%s' but type '%s' has narrower effective visibility '%s'",
            (int)signature_name.length,
            signature_name.data != NULL ? signature_name.data : "",
            signature_visibility_name(signature_visibility),
            type_name != NULL ? type_name : "<unknown>",
            signature_visibility_name(type_visibility)));
}

/* Compare one resolved target declaration with the signature that references
 * it.  Builtins and type parameters never reach this helper. */
static bool validate_signature_target_visibility(
    ResolveContext *context,
    const FengDecl *target,
    FengSlice signature_name,
    FengToken token,
    SignatureEffectiveVisibility signature_visibility,
    const char *type_name) {
    const FengSemanticModule *target_module;
    SignatureEffectiveVisibility target_visibility;

    if (target == NULL) {
        return true;
    }
    target_module = find_decl_provider_module(context->analysis, target);
    if (target_module == NULL) {
        return true;
    }
    target_visibility = signature_decl_visibility(target_module, target);
    if (target_visibility >= signature_visibility) {
        return true;
    }
    return report_signature_visibility_error(context,
                                             signature_name,
                                             token,
                                             signature_visibility,
                                             type_name,
                                             target_visibility);
}

/* Recursively validate a structured type reference.  Named targets are
 * compared by resolved declaration identity; generic arguments, arrays and
 * pointers are traversed independently. */
static bool validate_signature_type_ref_visibility(
    ResolveContext *context,
    const FengTypeRef *type_ref,
    const SignatureTypeParamScope *type_params,
    FengSlice signature_name,
    SignatureEffectiveVisibility signature_visibility) {
    bool ok = true;

    if (type_ref == NULL) {
        return true;
    }
    if (type_ref->kind == FENG_TYPE_REF_POINTER ||
        type_ref->kind == FENG_TYPE_REF_ARRAY) {
        return validate_signature_type_ref_visibility(context,
                                                      type_ref->as.inner,
                                                      type_params,
                                                      signature_name,
                                                      signature_visibility);
    }
    if (signature_type_ref_is_type_param(type_ref, type_params)) {
        return true;
    }
    if (type_ref->kind == FENG_TYPE_REF_NAMED) {
        const FengDecl *target = resolve_type_ref_decl(context, type_ref);

        if (target != NULL) {
            char *type_name = format_type_ref_name(type_ref);

            ok = validate_signature_target_visibility(context,
                                                      target,
                                                      signature_name,
                                                      type_ref->token,
                                                      signature_visibility,
                                                      type_name);
            free(type_name);
            if (!ok) {
                return false;
            }
        }
        for (size_t arg_index = 0U;
             arg_index < type_ref->as.named.type_arg_count;
             ++arg_index) {
            if (!validate_signature_type_ref_visibility(
                    context,
                    type_ref->as.named.type_args[arg_index],
                    type_params,
                    signature_name,
                    signature_visibility)) {
                return false;
            }
        }
    }
    return true;
}

/* Validate an inferred semantic type fact when a declaration has no explicit
 * type reference in the AST. */
static bool validate_signature_type_fact_visibility(
    ResolveContext *context,
    const FengSemanticTypeFact *fact,
    const SignatureTypeParamScope *type_params,
    FengSlice signature_name,
    FengToken declaration_token,
    SignatureEffectiveVisibility signature_visibility) {
    if (fact == NULL) {
        return true;
    }
    switch (fact->kind) {
        case FENG_SEMANTIC_TYPE_FACT_TYPE_REF:
            return validate_signature_type_ref_visibility(context,
                                                          fact->type_ref,
                                                          type_params,
                                                          signature_name,
                                                          signature_visibility);
        case FENG_SEMANTIC_TYPE_FACT_DECL: {
            FengSlice target_name = decl_typeish_name(fact->type_decl);
            char *type_name = format_module_name(&target_name, 1U);
            bool ok = validate_signature_target_visibility(context,
                                                           fact->type_decl,
                                                           signature_name,
                                                           declaration_token,
                                                           signature_visibility,
                                                           type_name);

            free(type_name);
            return ok;
        }
        case FENG_SEMANTIC_TYPE_FACT_UNKNOWN:
        case FENG_SEMANTIC_TYPE_FACT_BUILTIN:
            return true;
    }
    return true;
}

/* Validate an explicit type or its inferred replacement for a field/binding
 * site. */
static bool validate_signature_site_type_visibility(
    ResolveContext *context,
    const void *site,
    const FengTypeRef *explicit_type,
    const SignatureTypeParamScope *type_params,
    FengSlice signature_name,
    FengToken declaration_token,
    SignatureEffectiveVisibility signature_visibility) {
    if (explicit_type != NULL) {
        return validate_signature_type_ref_visibility(context,
                                                      explicit_type,
                                                      type_params,
                                                      signature_name,
                                                      signature_visibility);
    }
    return validate_signature_type_fact_visibility(
        context,
        feng_semantic_lookup_type_fact(context->analysis, site),
        type_params,
        signature_name,
        declaration_token,
        signature_visibility);
}

/* Validate every constraint in one generic parameter list. */
static bool validate_signature_type_param_visibility(
    ResolveContext *context,
    const FengTypeParam *params,
    size_t param_count,
    const SignatureTypeParamScope *scope,
    FengSlice signature_name,
    SignatureEffectiveVisibility signature_visibility) {
    size_t param_index;

    for (param_index = 0U; param_index < param_count; ++param_index) {
        if (!validate_signature_type_ref_visibility(context,
                                                    params[param_index].constraint,
                                                    scope,
                                                    signature_name,
                                                    signature_visibility)) {
            return false;
        }
    }
    return true;
}

/* Validate parameters, return type and generic constraints for one callable
 * signature.  Constructors and finalizers have no exposed return type. */
static bool validate_callable_signature_visibility(
    ResolveContext *context,
    const FengCallableSignature *callable,
    const SignatureTypeParamScope *parent_type_params,
    FengSlice signature_name,
    SignatureEffectiveVisibility signature_visibility,
    bool check_return_type) {
    SignatureTypeParamScope callable_scope;
    size_t param_index;

    callable_scope.params = callable->type_params;
    callable_scope.param_count = callable->type_param_count;
    callable_scope.parent = parent_type_params;
    if (!validate_signature_type_param_visibility(context,
                                                  callable->type_params,
                                                  callable->type_param_count,
                                                  &callable_scope,
                                                  signature_name,
                                                  signature_visibility)) {
        return false;
    }
    for (param_index = 0U; param_index < callable->param_count; ++param_index) {
        if (!validate_signature_type_ref_visibility(
                context,
                callable->params[param_index].type,
                &callable_scope,
                signature_name,
                signature_visibility)) {
            return false;
        }
    }
    if (!check_return_type) {
        return true;
    }
    return validate_signature_site_type_visibility(context,
                                                   callable,
                                                   callable->return_type,
                                                   &callable_scope,
                                                   signature_name,
                                                   callable->token,
                                                   signature_visibility);
}

/* Validate all signature surfaces of one type member. */
static bool validate_type_member_signature_visibility(
    ResolveContext *context,
    const FengTypeMember *member,
    const SignatureTypeParamScope *owner_type_params,
    SignatureEffectiveVisibility owner_visibility) {
    SignatureEffectiveVisibility member_visibility;
    FengSlice member_name;
    bool ok;

    if (member == NULL) {
        return true;
    }
    member_visibility = signature_member_visibility(owner_visibility, member);
    if (member->kind == FENG_TYPE_MEMBER_FIELD) {
        member_name = member->as.field.name;
        ok = validate_signature_site_type_visibility(context,
                                                     member,
                                                     member->as.field.type,
                                                     owner_type_params,
                                                     member_name,
                                                     member->token,
                                                     member_visibility);
        return ok && validate_friend_member_signature_rules(context,
                                                            member,
                                                            owner_type_params);
    }

    member_name = member->as.callable.name;
    ok = validate_callable_signature_visibility(
        context,
        &member->as.callable,
        owner_type_params,
        member_name,
        member_visibility,
        member->kind == FENG_TYPE_MEMBER_METHOD);
    return ok && validate_friend_member_signature_rules(context,
                                                        member,
                                                        owner_type_params);
}

/* Validate every signature surface declared by one top-level declaration. */
static bool validate_declaration_signature_visibility(
    ResolveContext *context,
    const FengDecl *decl) {
    SignatureEffectiveVisibility visibility =
        signature_decl_visibility(context->module, decl);
    FengSlice name = signature_decl_name(decl);
    size_t index;

    switch (decl->kind) {
        case FENG_DECL_GLOBAL_BINDING:
            return validate_signature_site_type_visibility(context,
                                                           &decl->as.binding,
                                                           decl->as.binding.type,
                                                           NULL,
                                                           name,
                                                           decl->as.binding.token,
                                                           visibility);

        case FENG_DECL_ENUM:
            return true;

        case FENG_DECL_TYPE: {
            SignatureTypeParamScope type_scope = {
                decl->as.type_decl.type_params,
                decl->as.type_decl.type_param_count,
                NULL};

            if (!validate_signature_type_param_visibility(
                    context,
                    decl->as.type_decl.type_params,
                    decl->as.type_decl.type_param_count,
                    &type_scope,
                    name,
                    visibility)) {
                return false;
            }
            for (index = 0U; index < decl->as.type_decl.declared_spec_count; ++index) {
                if (!validate_signature_type_ref_visibility(
                        context,
                        decl->as.type_decl.declared_specs[index],
                        &type_scope,
                        name,
                        visibility)) {
                    return false;
                }
            }
            for (index = 0U; index < decl->as.type_decl.member_count; ++index) {
                if (!validate_type_member_signature_visibility(
                        context,
                        decl->as.type_decl.members[index],
                        &type_scope,
                        visibility)) {
                    return false;
                }
            }
            return true;
        }

        case FENG_DECL_SPEC: {
            SignatureTypeParamScope spec_scope = {
                decl->as.spec_decl.type_params,
                decl->as.spec_decl.type_param_count,
                NULL};

            if (!validate_signature_type_param_visibility(
                    context,
                    decl->as.spec_decl.type_params,
                    decl->as.spec_decl.type_param_count,
                    &spec_scope,
                    name,
                    visibility)) {
                return false;
            }
            for (index = 0U; index < decl->as.spec_decl.parent_spec_count; ++index) {
                if (!validate_signature_type_ref_visibility(
                        context,
                        decl->as.spec_decl.parent_specs[index],
                        &spec_scope,
                        name,
                        visibility)) {
                    return false;
                }
            }
            if (decl->as.spec_decl.form == FENG_SPEC_FORM_CALLABLE) {
                for (index = 0U;
                     index < decl->as.spec_decl.as.callable.param_count;
                     ++index) {
                    if (!validate_signature_type_ref_visibility(
                            context,
                            decl->as.spec_decl.as.callable.params[index].type,
                            &spec_scope,
                            name,
                            visibility)) {
                        return false;
                    }
                }
                return validate_signature_type_ref_visibility(
                    context,
                    decl->as.spec_decl.as.callable.return_type,
                    &spec_scope,
                    name,
                    visibility);
            }
            if (decl->as.spec_decl.form == FENG_SPEC_FORM_UNION) {
                for (index = 0U;
                     index < decl->as.spec_decl.as.union_form.member_count;
                     ++index) {
                    if (!validate_signature_type_ref_visibility(
                            context,
                            decl->as.spec_decl.as.union_form.members[index],
                            &spec_scope,
                            name,
                            visibility)) {
                        return false;
                    }
                }
                return true;
            }
            if (decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
                for (index = 0U;
                     index < decl->as.spec_decl.as.intersection_form.member_count;
                     ++index) {
                    if (!validate_signature_type_ref_visibility(
                            context,
                            decl->as.spec_decl.as.intersection_form.members[index],
                            &spec_scope,
                            name,
                            visibility)) {
                        return false;
                    }
                }
                return true;
            }
            for (index = 0U;
                 index < decl->as.spec_decl.as.object.member_count;
                 ++index) {
                if (!validate_type_member_signature_visibility(
                        context,
                        decl->as.spec_decl.as.object.members[index],
                        &spec_scope,
                        visibility)) {
                    return false;
                }
            }
            return true;
        }

        case FENG_DECL_FIT: {
            const FengDecl *target =
                resolve_type_ref_decl(context, decl->as.fit_decl.target);
            FengTypeParam array_type_param;
            SignatureTypeParamScope fit_scope = {NULL, 0U, NULL};

            if (target != NULL && target->kind == FENG_DECL_TYPE) {
                fit_scope.params = target->as.type_decl.type_params;
                fit_scope.param_count = target->as.type_decl.type_param_count;
            } else if (fit_target_collect_array_local_type_param(
                           context,
                           decl->as.fit_decl.target,
                           &array_type_param)) {
                fit_scope.params = &array_type_param;
                fit_scope.param_count = 1U;
            }
            if (!validate_signature_type_ref_visibility(context,
                                                        decl->as.fit_decl.target,
                                                        &fit_scope,
                                                        name,
                                                        visibility)) {
                return false;
            }
            for (index = 0U; index < decl->as.fit_decl.spec_count; ++index) {
                if (!validate_signature_type_ref_visibility(
                        context,
                        decl->as.fit_decl.specs[index],
                        &fit_scope,
                        name,
                        visibility)) {
                    return false;
                }
            }
            for (index = 0U; index < decl->as.fit_decl.member_count; ++index) {
                if (!validate_type_member_signature_visibility(
                        context,
                        decl->as.fit_decl.members[index],
                        &fit_scope,
                        visibility)) {
                    return false;
                }
            }
            return true;
        }

        case FENG_DECL_FUNCTION:
            return validate_callable_signature_visibility(
                context,
                &decl->as.function_decl,
                NULL,
                name,
                visibility,
                true);
    }
    return true;
}

/* Validate declaration/type visibility consistency after all declarations in
 * the current program have completed normal type resolution and inference. */
static bool validate_program_signature_visibility(
    ResolveContext *context,
    const FengProgram *program) {
    size_t decl_index;

    for (decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
        if (!validate_declaration_signature_visibility(
                context,
                program->declarations[decl_index])) {
            return false;
        }
    }
    return true;
}

static bool resolve_program_names(const FengSemanticAnalysis *analysis,
                                  const FengSemanticModule *module,
                                  const FengProgram *program,
                                  const VisibleTypeEntry *visible_types,
                                  size_t visible_type_count,
                                  const VisibleValueEntry *visible_values,
                                  size_t visible_value_count,
                                  const FunctionOverloadSetEntry *function_sets,
                                  size_t function_set_count,
                                  bool infer_binding_types_only,
                                  CallableReturnCache *callable_return_cache,
                                  CallableExceptionEscapeCache *callable_exception_escape_cache,
                                  FengSemanticError **errors,
                                  size_t *error_count,
                                  size_t *error_capacity) {
    ResolveContext context;
    AliasEntry *aliases = NULL;
    size_t alias_count = 0U;
    size_t alias_capacity = 0U;
    ImportedModuleEntry *imported_modules = NULL;
    size_t imported_module_count = 0U;
    size_t imported_module_capacity = 0U;
    size_t decl_index;
    size_t use_index;
    bool ok;

    memset(&context, 0, sizeof(context));
    context.analysis = analysis;
    context.module = module;
    context.program = program;
    context.pointer_size = analysis->pointer_size;
    context.visible_types = visible_types;
    context.visible_type_count = visible_type_count;
    context.visible_values = visible_values;
    context.visible_value_count = visible_value_count;
    context.function_sets = function_sets;
    context.function_set_count = function_set_count;
    context.callable_return_cache = callable_return_cache;
    context.callable_exception_escape_cache = callable_exception_escape_cache;
    context.errors = errors;
    context.error_count = error_count;
    context.error_capacity = error_capacity;

    ok = build_program_aliases(analysis, program, &aliases, &alias_count, &alias_capacity);
    if (!ok) {
        free(aliases);
        return false;
    }

    /* Collect every `use`-imported target module (short-name and aliased)
     * so that cross-module visibility checks can require an explicit `use`. */
    for (use_index = 0U; use_index < program->use_count && ok; ++use_index) {
        const FengUseDecl *use_decl = &program->uses[use_index];
        size_t target_index =
            find_module_index_by_path(analysis, use_decl->segments, use_decl->segment_count);
        ImportedModuleEntry entry;
        size_t scan;
        bool already = false;

        if (target_index == analysis->module_count) {
            continue;
        }
        entry.target_module = &analysis->modules[target_index];
        for (scan = 0U; scan < imported_module_count; ++scan) {
            if (imported_modules[scan].target_module == entry.target_module) {
                already = true;
                break;
            }
        }
        if (already) {
            continue;
        }
        ok = append_raw((void **)&imported_modules,
                        &imported_module_count,
                        &imported_module_capacity,
                        sizeof(entry),
                        &entry);
    }
    if (!ok) {
        free(aliases);
        free(imported_modules);
        return false;
    }

    context.aliases = aliases;
    context.alias_count = alias_count;
    context.imported_modules = imported_modules;
    context.imported_module_count = imported_module_count;

    for (decl_index = 0U; decl_index < program->declaration_count && ok; ++decl_index) {
        const FengDecl *decl = program->declarations[decl_index];

        if (infer_binding_types_only) {
            /* Publish available inferred binding types before consumer bodies
             * are checked. The ordinary pass still validates every initializer
             * and declaration; this pass neither evaluates nor accepts them. */
            if (decl->kind == FENG_DECL_GLOBAL_BINDING && decl->as.binding.type == NULL &&
                decl->as.binding.initializer != NULL &&
                feng_semantic_lookup_type_fact(analysis, &decl->as.binding) == NULL) {
                ok = record_type_fact_for_site(&context, &decl->as.binding,
                                                infer_expr_type(&context, decl->as.binding.initializer));
            }
        } else {
            ok = resolve_declaration(&context, decl);
        }
    }

    if (ok && !infer_binding_types_only) {
        ok = validate_program_signature_visibility(&context, program);
    }

    if (ok && !infer_binding_types_only) {
        ok = validate_top_level_overload_overlap(&context, program);
    }

    resolver_free_scopes(&context);
    free(aliases);
    free(imported_modules);
    return ok;
}

/* Return whether a source member carries at least one @friend annotation. */
static bool member_has_friend_annotation(const FengTypeMember *member) {
    return member != NULL &&
           annotations_contain_kind(member->annotations,
                                    member->annotation_count,
                                    FENG_ANNOTATION_FRIEND);
}

/* Normalize every @friend member in one declaration without resolving any
 * executable body. This order-independent pre-pass makes all friend sets
 * available before ordinary member access starts. */
static bool normalize_declaration_friend_metadata(ResolveContext *context,
                                                  const FengDecl *decl) {
    const TypeParamEntry *previous_type_params = NULL;
    size_t previous_type_param_count = 0U;
    const TypeParamEntry *previous_fit_type_params = NULL;
    size_t previous_fit_type_param_count = 0U;
    const FengTypeParam *owner_type_params = NULL;
    size_t owner_type_param_count = 0U;
    FengTypeParam fit_local_type_param;
    bool fit_scope_pushed = false;
    bool ok = true;

    if (context == NULL || decl == NULL) {
        return true;
    }
    if (decl->kind == FENG_DECL_TYPE) {
        owner_type_params = decl->as.type_decl.type_params;
        owner_type_param_count = decl->as.type_decl.type_param_count;
        if (!resolver_push_type_params(context,
                                       owner_type_params,
                                       owner_type_param_count,
                                       &previous_type_params,
                                       &previous_type_param_count)) {
            return false;
        }
        for (size_t index = 0U;
             index < decl->as.type_decl.member_count && ok;
             ++index) {
            const FengTypeMember *member = decl->as.type_decl.members[index];

            if (!member_has_friend_annotation(member)) {
                continue;
            }
            ok = validate_supported_member_annotations(context, member) &&
                 normalize_friend_member_annotations(context,
                                                     decl,
                                                     member,
                                                     owner_type_params,
                                                     owner_type_param_count);
        }
        resolver_pop_type_params(context,
                                 previous_type_params,
                                 previous_type_param_count);
        return ok;
    }
    if (decl->kind == FENG_DECL_SPEC) {
        if (decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            return true;
        }
        owner_type_params = decl->as.spec_decl.type_params;
        owner_type_param_count = decl->as.spec_decl.type_param_count;
        if (!resolver_push_type_params(context,
                                       owner_type_params,
                                       owner_type_param_count,
                                       &previous_type_params,
                                       &previous_type_param_count)) {
            return false;
        }
        for (size_t index = 0U;
             index < decl->as.spec_decl.as.object.member_count && ok;
             ++index) {
            const FengTypeMember *member =
                decl->as.spec_decl.as.object.members[index];

            if (!member_has_friend_annotation(member)) {
                continue;
            }
            ok = validate_supported_member_annotations(context, member) &&
                 normalize_friend_member_annotations(context,
                                                     decl,
                                                     member,
                                                     owner_type_params,
                                                     owner_type_param_count);
        }
        resolver_pop_type_params(context,
                                 previous_type_params,
                                 previous_type_param_count);
        return ok;
    }
    if (decl->kind != FENG_DECL_FIT) {
        return true;
    }
    {
        FitTargetResolution fit_target =
            resolve_fit_target(context, decl->as.fit_decl.target);
        const FengDecl *fit_target_decl =
            fit_target.kind == FIT_TARGET_KIND_USER_TYPE
                ? fit_target.type_decl
                : NULL;

        if (fit_target_decl != NULL && fit_target_decl->kind == FENG_DECL_TYPE) {
            owner_type_params = fit_target_decl->as.type_decl.type_params;
            owner_type_param_count =
                fit_target_decl->as.type_decl.type_param_count;
            if (!resolver_push_type_params(context,
                                           owner_type_params,
                                           owner_type_param_count,
                                           &previous_type_params,
                                           &previous_type_param_count)) {
                return false;
            }
        }
        if (fit_target_collect_array_local_type_param(context,
                                                      decl->as.fit_decl.target,
                                                      &fit_local_type_param)) {
            owner_type_params = &fit_local_type_param;
            owner_type_param_count = 1U;
            if (!resolver_push_type_params(context,
                                           owner_type_params,
                                           owner_type_param_count,
                                           &previous_fit_type_params,
                                           &previous_fit_type_param_count)) {
                resolver_pop_type_params(context,
                                         previous_type_params,
                                         previous_type_param_count);
                return false;
            }
            fit_scope_pushed = true;
        }
        for (size_t index = 0U;
             index < decl->as.fit_decl.member_count && ok;
             ++index) {
            const FengTypeMember *member = decl->as.fit_decl.members[index];

            if (!member_has_friend_annotation(member)) {
                continue;
            }
            ok = validate_supported_member_annotations(context, member) &&
                 normalize_friend_member_annotations(context,
                                                     decl,
                                                     member,
                                                     owner_type_params,
                                                     owner_type_param_count);
        }
        if (fit_scope_pushed) {
            resolver_pop_type_params(context,
                                     previous_fit_type_params,
                                     previous_fit_type_param_count);
        }
        resolver_pop_type_params(context,
                                 previous_type_params,
                                 previous_type_param_count);
        return ok;
    }
}

/* Build one program's normal lexical import context and pre-normalize only
 * @friend metadata. No fields, callable bodies, witnesses, or codegen facts
 * are touched in this pass. */
static bool normalize_program_friend_metadata(
    const FengSemanticAnalysis *analysis,
    const FengSemanticModule *module,
    const FengProgram *program,
    const VisibleTypeEntry *visible_types,
    size_t visible_type_count,
    const VisibleValueEntry *visible_values,
    size_t visible_value_count,
    const FunctionOverloadSetEntry *function_sets,
    size_t function_set_count,
    FengSemanticError **errors,
    size_t *error_count,
    size_t *error_capacity) {
    ResolveContext context;
    AliasEntry *aliases = NULL;
    size_t alias_count = 0U;
    size_t alias_capacity = 0U;
    ImportedModuleEntry *imported_modules = NULL;
    size_t imported_module_count = 0U;
    size_t imported_module_capacity = 0U;
    bool ok;

    memset(&context, 0, sizeof(context));
    context.analysis = analysis;
    context.module = module;
    context.program = program;
    context.pointer_size = analysis->pointer_size;
    context.visible_types = visible_types;
    context.visible_type_count = visible_type_count;
    context.visible_values = visible_values;
    context.visible_value_count = visible_value_count;
    context.function_sets = function_sets;
    context.function_set_count = function_set_count;
    context.errors = errors;
    context.error_count = error_count;
    context.error_capacity = error_capacity;
    ok = build_program_aliases(analysis,
                               program,
                               &aliases,
                               &alias_count,
                               &alias_capacity);
    for (size_t use_index = 0U;
         use_index < program->use_count && ok;
         ++use_index) {
        size_t target_index = find_module_index_by_path(
            analysis,
            program->uses[use_index].segments,
            program->uses[use_index].segment_count);
        ImportedModuleEntry entry;
        bool duplicate = false;

        if (target_index == analysis->module_count) {
            continue;
        }
        entry.target_module = &analysis->modules[target_index];
        for (size_t index = 0U;
             index < imported_module_count;
             ++index) {
            if (imported_modules[index].target_module == entry.target_module) {
                duplicate = true;
                break;
            }
        }
        if (!duplicate) {
            ok = append_raw((void **)&imported_modules,
                            &imported_module_count,
                            &imported_module_capacity,
                            sizeof(entry),
                            &entry);
        }
    }
    context.aliases = aliases;
    context.alias_count = alias_count;
    context.imported_modules = imported_modules;
    context.imported_module_count = imported_module_count;
    for (size_t decl_index = 0U;
         decl_index < program->declaration_count && ok;
         ++decl_index) {
        ok = normalize_declaration_friend_metadata(
            &context, program->declarations[decl_index]);
    }
    resolver_free_scopes(&context);
    free(aliases);
    free(imported_modules);
    return ok;
}

/* Return the direct construction target accepted by member-mix syntax.
 * Object-literal construction keeps its constructor target in `target`;
 * ordinary construction is represented directly by a call expression. */
static const FengExpr *member_mix_construction_target(const FengExpr *expr) {
    if (expr == NULL) {
        return NULL;
    }
    if (expr->kind == FENG_EXPR_CALL) {
        return expr;
    }
    if (expr->kind == FENG_EXPR_OBJECT_LITERAL) {
        const FengExpr *target = expr->as.object_literal.target;

        if (target != NULL &&
            (target->kind == FENG_EXPR_IDENTIFIER ||
             target->kind == FENG_EXPR_MEMBER ||
             target->kind == FENG_EXPR_CALL)) {
            return target;
        }
    }
    return NULL;
}

/* Materialize the type reference encoded by a construction target.  The
 * returned tree is owned by the caller and is used to normalize the inferred
 * `... = Construction` form into the same fact shape as the explicit forms. */
static FengTypeRef *member_mix_type_ref_from_construction_target(
    const FengExpr *construction_target) {
    const FengExpr *path_expr = construction_target;
    FengTypeRef *type_ref;
    FengSlice *segments;
    size_t segment_count = 0U;
    FengTypeRef *const *type_args = NULL;
    size_t type_arg_count = 0U;

    if (path_expr == NULL) {
        return NULL;
    }
    if (path_expr->kind == FENG_EXPR_CALL) {
        type_args = path_expr->as.call.explicit_type_args;
        type_arg_count = path_expr->as.call.explicit_type_arg_count;
        path_expr = path_expr->as.call.callee;
    } else if (path_expr->kind == FENG_EXPR_GENERIC_TARGET) {
        type_args = path_expr->as.generic_target.type_args;
        type_arg_count = path_expr->as.generic_target.type_arg_count;
        path_expr = path_expr->as.generic_target.target;
    }
    if (path_expr == NULL ||
        (path_expr->kind != FENG_EXPR_IDENTIFIER && path_expr->kind != FENG_EXPR_MEMBER)) {
        return NULL;
    }

    segments = expr_path_segments_alloc(path_expr, &segment_count);
    if (segments == NULL || segment_count == 0U) {
        free(segments);
        return NULL;
    }
    type_ref = (FengTypeRef *)calloc(1U, sizeof(*type_ref));
    if (type_ref == NULL) {
        free(segments);
        return NULL;
    }
    type_ref->token = construction_target->token;
    type_ref->kind = FENG_TYPE_REF_NAMED;
    type_ref->as.named.segments = segments;
    type_ref->as.named.segment_count = segment_count;
    if (type_arg_count > 0U) {
        type_ref->as.named.type_args =
            (FengTypeRef **)calloc(type_arg_count, sizeof(FengTypeRef *));
        if (type_ref->as.named.type_args == NULL) {
            free_synthetic_type_ref(type_ref);
            return NULL;
        }
        type_ref->as.named.type_arg_count = type_arg_count;
        for (size_t index = 0U; index < type_arg_count; ++index) {
            type_ref->as.named.type_args[index] = clone_type_ref_for_inference(type_args[index]);
            if (type_ref->as.named.type_args[index] == NULL) {
                free_synthetic_type_ref(type_ref);
                return NULL;
            }
        }
    }
    return type_ref;
}

/* Resolve only member-mix source edges.  This pass runs after module/provider
 * injection but before expansion and ordinary semantic analysis, so every
 * source is interpreted in the lexical imports and generic scope of the type
 * that declared the `...` directive. */
static bool resolve_program_mixin_sources(
    const FengSemanticAnalysis *analysis,
    const FengSemanticModule *module,
    const FengProgram *program,
    const VisibleTypeEntry *visible_types,
    size_t visible_type_count,
    const VisibleValueEntry *visible_values,
    size_t visible_value_count,
    const FunctionOverloadSetEntry *function_sets,
    size_t function_set_count,
    FengSemanticError **errors,
    size_t *error_count,
    size_t *error_capacity) {
    ResolveContext context;
    AliasEntry *aliases = NULL;
    size_t alias_count = 0U;
    size_t alias_capacity = 0U;
    ImportedModuleEntry *imported_modules = NULL;
    size_t imported_module_count = 0U;
    size_t imported_module_capacity = 0U;
    bool ok = true;

    memset(&context, 0, sizeof(context));
    context.analysis = analysis;
    context.module = module;
    context.program = program;
    context.pointer_size = analysis->pointer_size;
    context.visible_types = visible_types;
    context.visible_type_count = visible_type_count;
    context.visible_values = visible_values;
    context.visible_value_count = visible_value_count;
    context.function_sets = function_sets;
    context.function_set_count = function_set_count;
    context.errors = errors;
    context.error_count = error_count;
    context.error_capacity = error_capacity;

    ok = build_program_aliases(analysis, program, &aliases, &alias_count, &alias_capacity);
    for (size_t use_index = 0U; use_index < program->use_count && ok; ++use_index) {
        size_t target_index = find_module_index_by_path(
            analysis,
            program->uses[use_index].segments,
            program->uses[use_index].segment_count);
        ImportedModuleEntry entry;
        bool already = false;

        if (target_index == analysis->module_count) {
            continue;
        }
        entry.target_module = &analysis->modules[target_index];
        for (size_t index = 0U; index < imported_module_count; ++index) {
            if (imported_modules[index].target_module == entry.target_module) {
                already = true;
                break;
            }
        }
        if (!already) {
            ok = append_raw((void **)&imported_modules,
                            &imported_module_count,
                            &imported_module_capacity,
                            sizeof(entry),
                            &entry);
        }
    }
    context.aliases = aliases;
    context.alias_count = alias_count;
    context.imported_modules = imported_modules;
    context.imported_module_count = imported_module_count;

    for (size_t decl_index = 0U;
         decl_index < program->declaration_count && ok;
         ++decl_index) {
        FengDecl *decl = program->declarations[decl_index];
        const TypeParamEntry *previous_type_params = NULL;
        size_t previous_type_param_count = 0U;

        if (decl == NULL || decl->kind != FENG_DECL_TYPE ||
            decl->as.type_decl.mixin_count == 0U) {
            continue;
        }
        if (!resolver_push_type_params(&context,
                                       decl->as.type_decl.type_params,
                                       decl->as.type_decl.type_param_count,
                                       &previous_type_params,
                                       &previous_type_param_count)) {
            ok = false;
            break;
        }

        for (size_t mixin_index = 0U;
             mixin_index < decl->as.type_decl.mixin_count && ok;
             ++mixin_index) {
            FengTypeMixinDecl *mixin = &decl->as.type_decl.mixins[mixin_index];
            const FengExpr *construction_target = NULL;
            const FengDecl *constructed_decl = NULL;
            char *source_name;

            if (mixin->source_constructor != NULL) {
                ResolvedTypeTarget target;

                construction_target = member_mix_construction_target(
                    mixin->source_constructor);
                if (construction_target == NULL) {
                    ok = resolver_append_error(
                        &context,
                        mixin->token,
                        "AE0329",
                        format_message(
                            "member mix initializer must be an object construction expression"));
                    break;
                }
                target = resolve_type_target_expr(&context, construction_target, true);
                constructed_decl = target.type_decl;
                if (mixin->infer_source_type && mixin->source_type == NULL) {
                    mixin->source_type =
                        member_mix_type_ref_from_construction_target(construction_target);
                    if (mixin->source_type == NULL) {
                        ok = false;
                        break;
                    }
                }
            }

            if (!resolve_type_ref(&context, mixin->source_type, false)) {
                ok = false;
                break;
            }
            mixin->resolved_source_decl = resolve_type_ref_decl(&context, mixin->source_type);
            if (mixin->resolved_source_decl == NULL ||
                mixin->resolved_source_decl->kind != FENG_DECL_TYPE) {
                source_name = format_type_ref_name(mixin->source_type);
                ok = resolver_append_error(
                    &context,
                    mixin->token,
                    "AE0328",
                    format_message(
                        "member mix source must resolve to a concrete object type but found '%s'",
                        source_name != NULL ? source_name : "<unknown>"));
                free(source_name);
                break;
            }
            if (constructed_decl != NULL && constructed_decl != mixin->resolved_source_decl) {
                ok = resolver_append_error(
                    &context,
                    mixin->token,
                    "AE0329",
                    format_message(
                        "member mix initializer must construct the declared source type"));
                break;
            }
            if (mixin->source_constructor != NULL &&
                (constructed_decl == NULL || constructed_decl->kind != FENG_DECL_TYPE)) {
                ok = resolver_append_error(
                    &context,
                    mixin->token,
                    "AE0329",
                    format_message(
                        "member mix initializer must be an object construction expression"));
            }
        }
        resolver_pop_type_params(
            &context, previous_type_params, previous_type_param_count);
    }

    resolver_free_scopes(&context);
    free(aliases);
    free(imported_modules);
    return ok;
}

/* —— Overload-category conflict helpers (docs/engineering/feng-type-arity-overload-dev.md §3.2/§3.3) ——
 *
 * Symbol conflict detection uses two arrays: visible_types (type/spec/enum)
 * and visible_values (function/binding). Within each array, entries from
 * different overload categories must not share a name (cross-category,
 * name-only). Across the two arrays, the same rule applies.
 *
 * These three helpers each check ONE array for cross-category name
 * collisions, keeping same-array and cross-array checks separate to
 * avoid double-reporting. */

/* Same-array cross-category check (visible_types). Called by type/spec/enum
 * branches before registration to detect name collisions with entries in
 * a different overload category within the same array. */
static bool has_cross_category_conflict(const VisibleTypeEntry *entries,
                                        size_t count,
                                        FengSlice name,
                                        FengOverloadCategory new_category) {
    size_t i;

    for (i = 0U; i < count; ++i) {
        FengOverloadCategory existing_category;

        if (!slice_equals(entries[i].name, name)) {
            continue;
        }
        existing_category = decl_overload_category(entries[i].decl);
        /* Overload-capability semantics:
         * - NO_OVERLOADING: no arity dimension, same name is always a conflict
         * - 5 type/spec categories: (name, arity) within same category;
         *   cross-category same name is a conflict
         * - FUNCTION: multi-dimensional overloading within same category;
         *   cross-category same name is a conflict
         * Conflict when either side is NO_OVERLOADING or categories differ. */
        if (new_category == FENG_OVERLOAD_CATEGORY_NO_OVERLOADING ||
            existing_category == FENG_OVERLOAD_CATEGORY_NO_OVERLOADING ||
            existing_category != new_category) {
            return true;
        }
    }
    return false;
}

/* Cross-array check: visible_values. Called by type/spec/enum branches
 * before registration to detect name collisions with entries in the
 * opposite array (function/binding). */
static bool has_value_name_only_conflict(const VisibleValueEntry *values,
                                         size_t value_count,
                                         FengSlice name,
                                         FengOverloadCategory new_category) {
    size_t i;

    for (i = 0U; i < value_count; ++i) {
        FengOverloadCategory existing_category;

        if (!slice_equals(values[i].name, name)) {
            continue;
        }
        existing_category = decl_overload_category(values[i].decl);
        if (new_category == FENG_OVERLOAD_CATEGORY_NO_OVERLOADING ||
            existing_category == FENG_OVERLOAD_CATEGORY_NO_OVERLOADING ||
            existing_category != new_category) {
            return true;
        }
    }
    return false;
}

/* Cross-array check: visible_types. Called by function/binding branches
 * before registration to detect name collisions with entries in the
 * opposite array (type/spec/enum). */
static bool has_type_name_only_conflict(const VisibleTypeEntry *types,
                                        size_t type_count,
                                        FengSlice name,
                                        FengOverloadCategory new_category) {
    size_t i;

    for (i = 0U; i < type_count; ++i) {
        FengOverloadCategory existing_category;

        if (!slice_equals(types[i].name, name)) {
            continue;
        }
        existing_category = decl_overload_category(types[i].decl);
        if (new_category == FENG_OVERLOAD_CATEGORY_NO_OVERLOADING ||
            existing_category == FENG_OVERLOAD_CATEGORY_NO_OVERLOADING ||
            existing_category != new_category) {
            return true;
        }
    }
    return false;
}

/* Select the progressively richer module pass used during mixin lowering. */
typedef enum SemanticModulePass {
    SEMANTIC_MODULE_PASS_MIXIN_SOURCES = 0,
    SEMANTIC_MODULE_PASS_MIXIN_STATIC_WRAPPERS,
    SEMANTIC_MODULE_PASS_FRIEND_METADATA,
    SEMANTIC_MODULE_PASS_BINDING_TYPES,
    SEMANTIC_MODULE_PASS_FULL
} SemanticModulePass;

static bool expand_program_mixable_static_wrappers(
    const FengSemanticAnalysis *analysis,
    const FengSemanticModule *module,
    const FengProgram *program,
    const VisibleTypeEntry *visible_types,
    size_t visible_type_count,
    const VisibleValueEntry *visible_values,
    size_t visible_value_count,
    const FunctionOverloadSetEntry *function_sets,
    size_t function_set_count,
    bool *changed,
    FengSemanticError **errors,
    size_t *error_count,
    size_t *error_capacity);

static bool check_symbol_conflicts(const FengSemanticAnalysis *analysis,
                                   const FengSemanticModule *module,
                                   SemanticModulePass pass,
                                   CallableReturnCache *callable_return_cache,
                                   CallableExceptionEscapeCache *callable_exception_escape_cache,
                                   bool *mixin_wrappers_changed,
                                   FengSemanticError **errors,
                                   size_t *error_count,
                                   size_t *error_capacity) {
    VisibleTypeEntry *visible_types = NULL;
    VisibleValueEntry *visible_values = NULL;
    FunctionOverloadSetEntry *function_sets = NULL;
    size_t visible_type_count = 0U;
    size_t visible_value_count = 0U;
    size_t function_set_count = 0U;
    size_t visible_type_capacity = 0U;
    size_t visible_value_capacity = 0U;
    size_t function_set_capacity = 0U;
    size_t program_index;
    bool ok = true;

    for (program_index = 0U; program_index < module->program_count && ok; ++program_index) {
        const FengProgram *program = module->programs[program_index];
        size_t decl_index;

        for (decl_index = 0U; decl_index < program->declaration_count && ok; ++decl_index) {
            const FengDecl *decl = program->declarations[decl_index];
            size_t index;

            switch (decl->kind) {
                case FENG_DECL_TYPE: {
                    VisibleTypeEntry entry;
                    FengOverloadCategory category = decl_overload_category(decl);
                    size_t arity = decl->as.type_decl.type_param_count;

                    /* Cross-array name-only conflict (rule 2, visible_values) */
                    if (has_value_name_only_conflict(visible_values, visible_value_count,
                                                     decl->as.type_decl.name, category)) {
                        char *message = format_message(
                            "'%.*s' conflicts with an existing visible name in a different category",
                            (int)decl->as.type_decl.name.length,
                            decl->as.type_decl.name.data);
                        ok = append_error(errors, error_count, error_capacity,
                                          program->path, *decl_token(decl), "AE0004", message);
                        break;
                    }

                    /* Same-array cross-category conflict (rule 2, visible_types) */
                    if (has_cross_category_conflict(visible_types, visible_type_count,
                                                    decl->as.type_decl.name, category)) {
                        char *message = format_message(
                            "'%.*s' conflicts with an existing visible name in a different category",
                            (int)decl->as.type_decl.name.length,
                            decl->as.type_decl.name.data);
                        ok = append_error(errors, error_count, error_capacity,
                                          program->path, *decl_token(decl), "AE0004", message);
                        break;
                    }

                    /* Same-category conflict (rule 3, by name + arity) */
                    index = find_visible_type_index(visible_types, visible_type_count,
                                                    decl->as.type_decl.name, category, arity);
                    if (index < visible_type_count) {
                        char *message = format_message("duplicate type declaration '%.*s'",
                                                       (int)decl->as.type_decl.name.length,
                                                       decl->as.type_decl.name.data);

                        ok = append_error(errors,
                                          error_count,
                                          error_capacity,
                                          program->path,
                                          *decl_token(decl),
                                          "AE0213", message);
                        break;
                    }
                    if (!ok) {
                        break;
                    }

                    entry.name = decl->as.type_decl.name;
                    entry.provider_module = module;
                    entry.provider_program = program;
                    entry.decl = decl;
                    ok = append_raw((void **)&visible_types,
                                    &visible_type_count,
                                    &visible_type_capacity,
                                    sizeof(entry),
                                    &entry);
                    break;
                }

                case FENG_DECL_ENUM: {
                    VisibleTypeEntry entry;
                    FengOverloadCategory category = decl_overload_category(decl);

                    /* Cross-array name-only conflict (rule 2, visible_values) */
                    if (has_value_name_only_conflict(visible_values, visible_value_count,
                                                     decl->as.enum_decl.name, category)) {
                        char *message = format_message(
                            "'%.*s' conflicts with an existing visible name in a different category",
                            (int)decl->as.enum_decl.name.length,
                            decl->as.enum_decl.name.data);
                        ok = append_error(errors, error_count, error_capacity,
                                          program->path, *decl_token(decl), "AE0004", message);
                        break;
                    }

                    /* Same-array cross-category conflict (rule 2, visible_types) */
                    if (has_cross_category_conflict(visible_types, visible_type_count,
                                                    decl->as.enum_decl.name, category)) {
                        char *message = format_message(
                            "'%.*s' conflicts with an existing visible name in a different category",
                            (int)decl->as.enum_decl.name.length,
                            decl->as.enum_decl.name.data);
                        ok = append_error(errors, error_count, error_capacity,
                                          program->path, *decl_token(decl), "AE0004", message);
                        break;
                    }

                    /* Same-category conflict (rule 3, NO_OVERLOADING is name-only, arity=0) */
                    index = find_visible_type_index(visible_types, visible_type_count,
                                                    decl->as.enum_decl.name, category, 0U);
                    if (index < visible_type_count) {
                        char *message = format_message(
                            "enum declaration '%.*s' conflicts with an existing visible type name",
                            (int)decl->as.enum_decl.name.length,
                            decl->as.enum_decl.name.data);

                        ok = append_error(errors,
                                          error_count,
                                          error_capacity,
                                          program->path,
                                          *decl_token(decl),
                                          "AE0214", message);
                        break;
                    }
                    if (!ok) {
                        break;
                    }

                    entry.name = decl->as.enum_decl.name;
                    entry.provider_module = module;
                    entry.provider_program = program;
                    entry.decl = decl;
                    ok = append_raw((void **)&visible_types,
                                    &visible_type_count,
                                    &visible_type_capacity,
                                    sizeof(entry),
                                    &entry);
                    break;
                }

                case FENG_DECL_GLOBAL_BINDING: {
                    VisibleValueEntry entry;
                    FengOverloadCategory category = decl_overload_category(decl);

                    /* Cross-array name-only conflict (rule 2, visible_types) */
                    if (has_type_name_only_conflict(visible_types, visible_type_count,
                                                    decl->as.binding.name, category)) {
                        char *message = format_message(
                            "'%.*s' conflicts with an existing visible name in a different category",
                            (int)decl->as.binding.name.length,
                            decl->as.binding.name.data);
                        ok = append_error(errors, error_count, error_capacity,
                                          program->path, decl->as.binding.token, "AE0004", message);
                        break;
                    }

                    index = find_visible_value_index(visible_values, visible_value_count, decl->as.binding.name);
                    if (index < visible_value_count) {
                        const char *msg_code;
                        char *message;

                        if (visible_values[index].is_function) {
                            msg_code = "AE0215";
                            message = format_message(
                                "top-level binding '%.*s' conflicts with an existing top-level function",
                                (int)decl->as.binding.name.length,
                                decl->as.binding.name.data);
                        } else {
                            msg_code = "AE0216";
                            message = format_message("duplicate top-level binding '%.*s'",
                                                     (int)decl->as.binding.name.length,
                                                     decl->as.binding.name.data);
                        }

                        ok = append_error(errors,
                                          error_count,
                                          error_capacity,
                                          program->path,
                                          decl->as.binding.token,
                                          msg_code, message);
                        break;
                    }
                    if (!ok) {
                        break;
                    }

                    entry.name = decl->as.binding.name;
                    entry.provider_module = module;
                    entry.provider_program = program;
                    entry.decl = decl;
                    entry.mutability = decl->as.binding.mutability;
                    entry.is_function = false;
                    ok = append_raw((void **)&visible_values,
                                    &visible_value_count,
                                    &visible_value_capacity,
                                    sizeof(entry),
                                    &entry);
                    break;
                }

                case FENG_DECL_FUNCTION: {
                    FengOverloadCategory category = decl_overload_category(decl);
                    size_t value_index;
                    size_t function_set_index;

                    /* Cross-array name-only conflict (rule 2, visible_types) */
                    if (has_type_name_only_conflict(visible_types, visible_type_count,
                                                    decl->as.function_decl.name, category)) {
                        char *message = format_message(
                            "'%.*s' conflicts with an existing visible name in a different category",
                            (int)decl->as.function_decl.name.length,
                            decl->as.function_decl.name.data);
                        ok = append_error(errors, error_count, error_capacity,
                                          program->path, decl->as.function_decl.token, "AE0004", message);
                        break;
                    }

                    value_index =
                        find_visible_value_index(visible_values, visible_value_count, decl->as.function_decl.name);
                    function_set_index = find_function_overload_set_index(
                        function_sets, function_set_count, decl->as.function_decl.name);

                    if (value_index < visible_value_count && !visible_values[value_index].is_function) {
                        char *message = format_message(
                            "top-level function '%.*s' conflicts with an existing top-level binding",
                            (int)decl->as.function_decl.name.length,
                            decl->as.function_decl.name.data);

                        ok = append_error(errors,
                                          error_count,
                                          error_capacity,
                                          program->path,
                                          decl->as.function_decl.token,
                                          "AE0217", message);
                        break;
                    }

                    if (function_set_index < function_set_count) {
                        const FunctionOverloadSetEntry *function_set = &function_sets[function_set_index];

                        for (index = 0U; index < function_set->decl_count; ++index) {
                            const FengCallableSignature *existing =
                                &function_set->decls[index]->as.function_decl;
                            if (existing->type_param_count != decl->as.function_decl.type_param_count) {
                                continue;
                            }
                            bool params_eq = parameters_equal(existing, &decl->as.function_decl);
                            bool var_conflict = !params_eq &&
                                (sig_is_variadic(existing) || sig_is_variadic(&decl->as.function_decl)) &&
                                variadic_parameters_conflict(existing, &decl->as.function_decl);

                            if (!params_eq && !var_conflict) {
                                continue;
                            }

                            if (params_eq) {
                                if (return_type_equals(existing->return_type, decl->as.function_decl.return_type)) {
                                    char *message = format_message("duplicate function signature '%.*s'",
                                                                   (int)decl->as.function_decl.name.length,
                                                                   decl->as.function_decl.name.data);

                                    ok = append_error(errors,
                                                      error_count,
                                                      error_capacity,
                                                      program->path,
                                                      decl->as.function_decl.token,
                                                      "AE0508", message);
                                } else {
                                    char *message = format_message(
                                        "function overloads cannot differ only by return type: '%.*s'",
                                        (int)decl->as.function_decl.name.length,
                                        decl->as.function_decl.name.data);

                                    ok = append_error(errors,
                                                      error_count,
                                                      error_capacity,
                                                      program->path,
                                                      decl->as.function_decl.token,
                                                      "AE0509", message);
                                }
                            } else {
                                char *message = format_message(
                                    "variadic function overload conflicts with existing overload '%.*s'",
                                    (int)decl->as.function_decl.name.length,
                                    decl->as.function_decl.name.data);

                                ok = append_error(errors,
                                                  error_count,
                                                  error_capacity,
                                                  program->path,
                                                  decl->as.function_decl.token,
                                                  "AE0510", message);
                            }
                            break;
                        }
                        if (!ok) {
                            break;
                        }
                        if (index < function_set->decl_count) {
                            break;
                        }
                    } else {
                        FunctionOverloadSetEntry entry;

                        memset(&entry, 0, sizeof(entry));
                        entry.name = decl->as.function_decl.name;
                        entry.provider_module = module;
                        ok = append_raw((void **)&function_sets,
                                        &function_set_count,
                                        &function_set_capacity,
                                        sizeof(entry),
                                        &entry);
                        if (!ok) {
                            break;
                        }
                        function_set_index = function_set_count - 1U;
                    }

                    if (value_index == visible_value_count) {
                        VisibleValueEntry value_entry;

                        value_entry.name = decl->as.function_decl.name;
                        value_entry.provider_module = module;
                        value_entry.provider_program = program;
                        value_entry.decl = decl;
                        value_entry.mutability = FENG_MUTABILITY_DEFAULT;
                        value_entry.is_function = true;
                        ok = append_raw((void **)&visible_values,
                                        &visible_value_count,
                                        &visible_value_capacity,
                                        sizeof(value_entry),
                                        &value_entry);
                        if (!ok) {
                            break;
                        }
                    }

                    ok = append_visible_function_overload(&function_sets,
                                                          &function_set_count,
                                                          &function_set_capacity,
                                                          module,
                                                          decl);
                    break;
                }

                case FENG_DECL_SPEC: {
                    VisibleTypeEntry entry;
                    FengOverloadCategory category = decl_overload_category(decl);
                    size_t arity = decl->as.spec_decl.type_param_count;

                    /* Cross-array name-only conflict (rule 2, visible_values) */
                    if (has_value_name_only_conflict(visible_values, visible_value_count,
                                                     decl->as.spec_decl.name, category)) {
                        char *message = format_message(
                            "'%.*s' conflicts with an existing visible name in a different category",
                            (int)decl->as.spec_decl.name.length,
                            decl->as.spec_decl.name.data);
                        ok = append_error(errors, error_count, error_capacity,
                                          program->path, *decl_token(decl), "AE0004", message);
                        break;
                    }

                    /* Same-array cross-category conflict (rule 2, visible_types) */
                    if (has_cross_category_conflict(visible_types, visible_type_count,
                                                    decl->as.spec_decl.name, category)) {
                        char *message = format_message(
                            "'%.*s' conflicts with an existing visible name in a different category",
                            (int)decl->as.spec_decl.name.length,
                            decl->as.spec_decl.name.data);
                        ok = append_error(errors, error_count, error_capacity,
                                          program->path, *decl_token(decl), "AE0004", message);
                        break;
                    }

                    /* Same-category conflict (rule 3, by name + arity) */
                    index = find_visible_type_index(visible_types, visible_type_count,
                                                    decl->as.spec_decl.name, category, arity);
                    if (index < visible_type_count) {
                        char *message = format_message("duplicate type declaration '%.*s'",
                                                       (int)decl->as.spec_decl.name.length,
                                                       decl->as.spec_decl.name.data);

                        ok = append_error(errors,
                                          error_count,
                                          error_capacity,
                                          program->path,
                                          *decl_token(decl),
                                          "AE0213", message);
                        break;
                    }
                    if (!ok) {
                        break;
                    }

                    entry.name = decl->as.spec_decl.name;
                    entry.provider_module = module;
                    entry.provider_program = program;
                    entry.decl = decl;
                    ok = append_raw((void **)&visible_types,
                                    &visible_type_count,
                                    &visible_type_capacity,
                                    sizeof(entry),
                                    &entry);
                    break;
                }

                case FENG_DECL_FIT:
                    /* fit declarations register adapter relationships; they do not
                       introduce a new top-level name and are processed elsewhere. */
                    break;
            }
        }
    }

    for (program_index = 0U; program_index < module->program_count && ok; ++program_index) {
        const FengProgram *program = module->programs[program_index];
        VisibleTypeEntry *program_visible_types = NULL;
        VisibleValueEntry *program_visible_values = NULL;
        FunctionOverloadSetEntry *program_function_sets = NULL;
        size_t program_visible_type_count = 0U;
        size_t program_visible_value_count = 0U;
        size_t program_function_set_count = 0U;
        size_t program_visible_type_capacity = 0U;
        size_t program_visible_value_capacity = 0U;
        size_t program_function_set_capacity = 0U;
        size_t use_index;

        if (!copy_visible_type_entries(visible_types,
                                       visible_type_count,
                                       &program_visible_types,
                                       &program_visible_type_count,
                                       &program_visible_type_capacity) ||
            !copy_visible_value_entries(visible_values,
                                        visible_value_count,
                                        &program_visible_values,
                                        &program_visible_value_count,
                                        &program_visible_value_capacity) ||
            !copy_function_overload_sets(function_sets,
                                         function_set_count,
                                         &program_function_sets,
                                         &program_function_set_count,
                                         &program_function_set_capacity)) {
            ok = false;
        }

        for (use_index = 0U; use_index < program->use_count && ok; ++use_index) {
            const FengUseDecl *use_decl = &program->uses[use_index];
            size_t prior_index;
            size_t target_index;

            if (use_decl->has_alias) {
                for (prior_index = 0U; prior_index < use_index; ++prior_index) {
                    if (program->uses[prior_index].has_alias &&
                        slice_equals(program->uses[prior_index].alias, use_decl->alias)) {
                        ok = append_error(errors,
                                          error_count,
                                          error_capacity,
                                          program->path,
                                          use_decl->token,
                                          "AE0902", format_message("duplicate import alias '%.*s' in the same file",
                                                         (int)use_decl->alias.length,
                                                         use_decl->alias.data));
                        break;
                    }
                }
                if (!ok) {
                    break;
                }
            }

            target_index =
                find_module_index_by_path(analysis, use_decl->segments, use_decl->segment_count);
            if (target_index == analysis->module_count) {
                char *module_name = format_module_name(use_decl->segments, use_decl->segment_count);

                ok = append_error(
                    errors,
                    error_count,
                    error_capacity,
                    program->path,
                    use_decl->token,
                    "AE0902", format_message("import target module '%s' was not found in current compilation input",
                                   module_name != NULL ? module_name : "<unknown>"));
                free(module_name);
                if (!ok) {
                    break;
                }
                continue;
            }

            if (use_decl->has_alias) {
                continue;
            }

            ok = import_public_names(&analysis->modules[target_index],
                                     &program_visible_types,
                                     &program_visible_type_count,
                                     &program_visible_type_capacity,
                                     &program_visible_values,
                                     &program_visible_value_count,
                                     &program_visible_value_capacity,
                                     &program_function_sets,
                                     &program_function_set_count,
                                     &program_function_set_capacity);
        }

        if (ok) {
            ok = validate_program_alias_conflicts(program,
                                                  errors,
                                                  error_count,
                                                  error_capacity);
        }

        if (ok && (pass == SEMANTIC_MODULE_PASS_FULL || pass == SEMANTIC_MODULE_PASS_BINDING_TYPES)) {
            ok = resolve_program_names(analysis,
                                       module,
                                       program,
                                       program_visible_types,
                                       program_visible_type_count,
                                       program_visible_values,
                                       program_visible_value_count,
                                       program_function_sets,
                                       program_function_set_count,
                                       pass == SEMANTIC_MODULE_PASS_BINDING_TYPES,
                                       callable_return_cache,
                                       callable_exception_escape_cache,
                                       errors,
                                       error_count,
                                       error_capacity);
        } else if (ok && pass == SEMANTIC_MODULE_PASS_FRIEND_METADATA) {
            ok = normalize_program_friend_metadata(
                analysis,
                module,
                program,
                program_visible_types,
                program_visible_type_count,
                program_visible_values,
                program_visible_value_count,
                program_function_sets,
                program_function_set_count,
                errors,
                error_count,
                error_capacity);
        } else if (ok && pass == SEMANTIC_MODULE_PASS_MIXIN_SOURCES) {
            ok = resolve_program_mixin_sources(analysis,
                                               module,
                                               program,
                                               program_visible_types,
                                               program_visible_type_count,
                                               program_visible_values,
                                               program_visible_value_count,
                                               program_function_sets,
                                               program_function_set_count,
                                               errors,
                                               error_count,
                                               error_capacity);
        } else if (ok) {
            ok = expand_program_mixable_static_wrappers(
                analysis,
                module,
                program,
                program_visible_types,
                program_visible_type_count,
                program_visible_values,
                program_visible_value_count,
                program_function_sets,
                program_function_set_count,
                mixin_wrappers_changed,
                errors,
                error_count,
                error_capacity);
        }

        free(program_visible_types);
        free(program_visible_values);
        free_function_overload_sets(program_function_sets, program_function_set_count);
    }

    free(visible_types);
    free(visible_values);
    free_function_overload_sets(function_sets, function_set_count);
    return ok;
}

/* One local concrete type in the member-expansion dependency graph. */
typedef struct MixinTypeEntry {
    FengDecl *decl;
    const FengProgram *program;
    unsigned char cycle_state; /* 0 = unseen, 1 = visiting, 2 = complete */
} MixinTypeEntry;

/* Find a dependency-graph entry by declaration identity. */
static size_t find_mixin_type_entry(const MixinTypeEntry *entries,
                                    size_t entry_count,
                                    const FengDecl *decl) {
    for (size_t index = 0U; index < entry_count; ++index) {
        if (entries[index].decl == decl) {
            return index;
        }
    }
    return entry_count;
}

/* Validate the expansion graph before mutating any member array.  Ordinary
 * field/signature type-reference cycles are intentionally absent from this
 * graph and remain the responsibility of their existing semantic passes. */
static bool validate_mixin_cycle_from(MixinTypeEntry *entries,
                                      size_t entry_count,
                                      size_t entry_index,
                                      size_t *entry_stack,
                                      const FengTypeMixinDecl **edge_stack,
                                      const char **edge_path_stack,
                                      size_t depth,
                                      FengSemanticError **errors,
                                      size_t *error_count,
                                      size_t *error_capacity) {
    MixinTypeEntry *entry = &entries[entry_index];
    FengDecl *decl = entry->decl;

    if (entry->cycle_state == 2U) {
        return true;
    }
    entry_stack[depth] = entry_index;
    entry->cycle_state = 1U;
    for (size_t mixin_index = 0U;
         mixin_index < decl->as.type_decl.mixin_count;
         ++mixin_index) {
        const FengTypeMixinDecl *mixin = &decl->as.type_decl.mixins[mixin_index];
        const FengDecl *source = mixin->resolved_source_decl;
        size_t source_index = find_mixin_type_entry(entries, entry_count, source);

        if (source_index == entry_count) {
            continue;
        }
        if (entries[source_index].cycle_state == 1U) {
            size_t cycle_start = 0U;
            bool appended;

            while (cycle_start <= depth &&
                   entry_stack[cycle_start] != source_index) {
                ++cycle_start;
            }
            appended = append_error(
                errors,
                error_count,
                error_capacity,
                entry->program != NULL ? entry->program->path : NULL,
                mixin->token,
                "AE0330",
                format_message(
                    "member mix expansion for type '%.*s' forms a cycle through source type '%.*s'",
                    (int)decl->as.type_decl.name.length,
                    decl->as.type_decl.name.data,
                    (int)source->as.type_decl.name.length,
                    source->as.type_decl.name.data));
            for (size_t stack_index = cycle_start + 1U;
                 appended && stack_index <= depth;
                 ++stack_index) {
                appended = append_latest_error_related_location(
                    *errors,
                    *error_count,
                    edge_path_stack[stack_index],
                    edge_stack[stack_index]->token,
                    format_message("member mix expansion cycle continues here"));
            }
            return false;
        }
        if (entries[source_index].cycle_state == 0U) {
            edge_stack[depth + 1U] = mixin;
            edge_path_stack[depth + 1U] =
                entry->program != NULL ? entry->program->path : NULL;
            if (!validate_mixin_cycle_from(entries,
                                           entry_count,
                                           source_index,
                                           entry_stack,
                                           edge_stack,
                                           edge_path_stack,
                                           depth + 1U,
                                           errors,
                                           error_count,
                                           error_capacity)) {
                return false;
            }
        }
    }
    entry->cycle_state = 2U;
    return true;
}

/* Apply target-explicit priority to an incoming instance-field candidate. */
static bool target_explicit_member_conflicts_with_mixed_field(
    const FengDecl *target,
    FengSlice field_name) {
    if (target == NULL || target->kind != FENG_DECL_TYPE) {
        return false;
    }
    for (size_t index = 0U; index < target->as.type_decl.member_count; ++index) {
        const FengTypeMember *member = target->as.type_decl.members[index];

        if (member == NULL || member->mixin_origin != NULL || member->is_static) {
            continue;
        }
        if (member->kind == FENG_TYPE_MEMBER_FIELD &&
            slice_equals(member->as.field.name, field_name)) {
            return true;
        }
        if (member->kind == FENG_TYPE_MEMBER_METHOD &&
            slice_equals(member->as.callable.name, field_name)) {
            return true;
        }
    }
    return false;
}

/* Create one ordinary target field from a visible source field declaration. */
static FengTypeMember *create_mixed_field(const FengTypeMixinDecl *mixin,
                                          const FengTypeMember *source_field) {
    const FengDecl *source_decl;
    FengTypeMember *field;
    FengTypeRef *field_type;

    if (mixin == NULL || source_field == NULL ||
        source_field->kind != FENG_TYPE_MEMBER_FIELD ||
        mixin->resolved_source_decl == NULL ||
        mixin->resolved_source_decl->kind != FENG_DECL_TYPE) {
        return NULL;
    }
    source_decl = mixin->resolved_source_decl;
    if (source_field->as.field.type == NULL) {
        field_type = NULL;
    } else if (source_decl->as.type_decl.type_param_count > 0U &&
        mixin->source_type != NULL &&
        mixin->source_type->kind == FENG_TYPE_REF_NAMED &&
        mixin->source_type->as.named.type_arg_count ==
            source_decl->as.type_decl.type_param_count) {
        field_type = clone_type_ref_substituting_type_params(
            NULL,
            source_field->as.field.type,
            source_decl->as.type_decl.type_params,
            source_decl->as.type_decl.type_param_count,
            mixin->source_type->as.named.type_args);
    } else {
        field_type = clone_type_ref_for_inference(source_field->as.field.type);
    }
    if (source_field->as.field.type != NULL && field_type == NULL) {
        return NULL;
    }

    field = (FengTypeMember *)calloc(1U, sizeof(*field));
    if (field == NULL) {
        free_synthetic_type_ref(field_type);
        return NULL;
    }
    field->token = mixin->token;
    field->kind = FENG_TYPE_MEMBER_FIELD;
    field->visibility = source_field->visibility;
    field->is_static = false;
    field->is_mixable = source_field->is_mixable;
    field->mixin_origin = mixin;
    field->mixin_source_member = source_field;
    field->as.field.mutability = source_field->as.field.mutability;
    field->as.field.name = source_field->as.field.name;
    field->as.field.type = field_type;
    /* The explicit-construction form computes this fact after resolving its
     * selected constructor and object-literal bindings.  The zero form stays
     * unbound for let fields and uses ordinary default initialization. */
    field->as.field.declaration_bound = false;
    return field;
}

/* Roll back one generated field before normal AST ownership takes over. */
static void free_generated_mixed_field(FengTypeMember *field) {
    if (field == NULL) {
        return;
    }
    free_synthetic_type_ref(field->as.field.type);
    free(field);
}

/* Clone a callable-surface type from a source generic instance into the
 * target type scope.  Method type parameters are distinct from owner type
 * parameters under Feng's existing collision rules and therefore remain
 * untouched by this substitution. */
static FengTypeRef *clone_mixin_callable_type_ref(
    const FengTypeRef *type_ref,
    const FengDecl *source_owner,
    const FengTypeRef *source_instance) {
    if (type_ref == NULL) {
        return NULL;
    }
    if (source_owner != NULL && source_owner->kind == FENG_DECL_TYPE &&
        source_owner->as.type_decl.type_param_count > 0U &&
        source_instance != NULL && source_instance->kind == FENG_TYPE_REF_NAMED &&
        source_instance->as.named.type_arg_count ==
            source_owner->as.type_decl.type_param_count) {
        return clone_type_ref_substituting_type_params(
            NULL,
            type_ref,
            source_owner->as.type_decl.type_params,
            source_owner->as.type_decl.type_param_count,
            source_instance->as.named.type_args);
    }
    return clone_type_ref_for_inference(type_ref);
}

/* Free the limited expression shapes synthesized for ordinary forwarding
 * wrapper bodies.  Successful wrappers are owned by the normal parser AST
 * teardown; this helper is only for construction failure rollback. */
static void free_mixin_wrapper_expr(FengExpr *expr) {
    if (expr == NULL) {
        return;
    }
    if (expr->kind == FENG_EXPR_CALL) {
        free_mixin_wrapper_expr(expr->as.call.callee);
        for (size_t index = 0U; index < expr->as.call.arg_count; ++index) {
            free_mixin_wrapper_expr(expr->as.call.args[index]);
        }
        free(expr->as.call.args);
        for (size_t index = 0U;
             index < expr->as.call.explicit_type_arg_count;
             ++index) {
            free_synthetic_type_ref(
                expr->as.call.explicit_type_args[index]);
        }
        free(expr->as.call.explicit_type_args);
    } else if (expr->kind == FENG_EXPR_MEMBER) {
        free_mixin_wrapper_expr(expr->as.member.object);
    } else if (expr->kind == FENG_EXPR_GENERIC_TARGET) {
        free_mixin_wrapper_expr(expr->as.generic_target.target);
        for (size_t index = 0U;
             index < expr->as.generic_target.type_arg_count;
             ++index) {
            free_synthetic_type_ref(expr->as.generic_target.type_args[index]);
        }
        free(expr->as.generic_target.type_args);
    }
    free(expr);
}

/* Roll back a partially constructed generated wrapper member. */
static void free_mixin_wrapper_member(FengTypeMember *member) {
    if (member == NULL) {
        return;
    }
    for (size_t index = 0U;
         index < member->as.callable.type_param_count;
         ++index) {
        free_synthetic_type_ref(
            member->as.callable.type_params[index].constraint);
    }
    free(member->as.callable.type_params);
    for (size_t index = 0U; index < member->as.callable.param_count; ++index) {
        free_synthetic_type_ref(member->as.callable.params[index].type);
    }
    free(member->as.callable.params);
    free_synthetic_type_ref(member->as.callable.return_type);
    if (member->as.callable.body != NULL) {
        for (size_t index = 0U;
             index < member->as.callable.body->statement_count;
             ++index) {
            FengStmt *stmt = member->as.callable.body->statements[index];

            if (stmt != NULL && stmt->kind == FENG_STMT_RETURN) {
                free_mixin_wrapper_expr(stmt->as.return_value);
            } else if (stmt != NULL && stmt->kind == FENG_STMT_EXPR) {
                free_mixin_wrapper_expr(stmt->as.expr);
            }
            free(stmt);
        }
        free(member->as.callable.body->statements);
        free(member->as.callable.body);
    }
    free(member);
}

/* Allocate one expression node for a generated wrapper body. */
static FengExpr *new_mixin_wrapper_expr(FengExprKind kind, FengToken token) {
    FengExpr *expr = (FengExpr *)calloc(1U, sizeof(*expr));

    if (expr != NULL) {
        expr->kind = kind;
        expr->token = token;
    }
    return expr;
}

/* Convert a named type reference to the ordinary expression target used by
 * a fully-qualified static call (for example module.View<T>). */
static FengExpr *mixin_type_target_expr_from_ref(const FengTypeRef *type_ref) {
    FengExpr *target = NULL;

    if (type_ref == NULL || type_ref->kind != FENG_TYPE_REF_NAMED ||
        type_ref->as.named.segment_count == 0U) {
        return NULL;
    }
    target = new_mixin_wrapper_expr(FENG_EXPR_IDENTIFIER, type_ref->token);
    if (target == NULL) {
        return NULL;
    }
    target->as.identifier = type_ref->as.named.segments[0];
    for (size_t index = 1U;
         index < type_ref->as.named.segment_count;
         ++index) {
        FengExpr *member =
            new_mixin_wrapper_expr(FENG_EXPR_MEMBER, type_ref->token);

        if (member == NULL) {
            free_mixin_wrapper_expr(target);
            return NULL;
        }
        member->as.member.object = target;
        member->as.member.member = type_ref->as.named.segments[index];
        target = member;
    }
    if (type_ref->as.named.type_arg_count > 0U) {
        FengExpr *generic =
            new_mixin_wrapper_expr(FENG_EXPR_GENERIC_TARGET, type_ref->token);

        if (generic == NULL) {
            free_mixin_wrapper_expr(target);
            return NULL;
        }
        generic->as.generic_target.target = target;
        generic->as.generic_target.type_args = (FengTypeRef **)calloc(
            type_ref->as.named.type_arg_count, sizeof(FengTypeRef *));
        if (generic->as.generic_target.type_args == NULL) {
            free_mixin_wrapper_expr(generic);
            return NULL;
        }
        generic->as.generic_target.type_arg_count =
            type_ref->as.named.type_arg_count;
        for (size_t index = 0U;
             index < type_ref->as.named.type_arg_count;
             ++index) {
            generic->as.generic_target.type_args[index] =
                clone_type_ref_for_inference(
                    type_ref->as.named.type_args[index]);
            if (generic->as.generic_target.type_args[index] == NULL) {
                free_mixin_wrapper_expr(generic);
                return NULL;
            }
        }
        target = generic;
    }
    return target;
}

/* Build the current concrete type reference, including its owner parameters,
 * for an instance wrapper's fully qualified static call. */
static FengTypeRef *mixin_owner_instance_type_ref(const FengDecl *owner) {
    FengTypeRef *type_ref;

    if (owner == NULL || owner->kind != FENG_DECL_TYPE) {
        return NULL;
    }
    type_ref = (FengTypeRef *)calloc(1U, sizeof(*type_ref));
    if (type_ref == NULL) {
        return NULL;
    }
    type_ref->token = owner->token;
    type_ref->kind = FENG_TYPE_REF_NAMED;
    type_ref->as.named.segments =
        (FengSlice *)calloc(1U, sizeof(FengSlice));
    if (type_ref->as.named.segments == NULL) {
        free(type_ref);
        return NULL;
    }
    type_ref->as.named.segments[0] = owner->as.type_decl.name;
    type_ref->as.named.segment_count = 1U;
    if (owner->as.type_decl.type_param_count > 0U) {
        type_ref->as.named.type_args = (FengTypeRef **)calloc(
            owner->as.type_decl.type_param_count, sizeof(FengTypeRef *));
        if (type_ref->as.named.type_args == NULL) {
            free_synthetic_type_ref(type_ref);
            return NULL;
        }
        type_ref->as.named.type_arg_count =
            owner->as.type_decl.type_param_count;
        for (size_t index = 0U;
             index < owner->as.type_decl.type_param_count;
             ++index) {
            FengTypeRef *arg = (FengTypeRef *)calloc(1U, sizeof(*arg));

            if (arg == NULL) {
                free_synthetic_type_ref(type_ref);
                return NULL;
            }
            arg->token = owner->as.type_decl.type_params[index].token;
            arg->kind = FENG_TYPE_REF_NAMED;
            arg->as.named.segments =
                (FengSlice *)calloc(1U, sizeof(FengSlice));
            if (arg->as.named.segments == NULL) {
                free(arg);
                free_synthetic_type_ref(type_ref);
                return NULL;
            }
            arg->as.named.segments[0] =
                owner->as.type_decl.type_params[index].name;
            arg->as.named.segment_count = 1U;
            type_ref->as.named.type_args[index] = arg;
        }
    }
    return type_ref;
}

/* Clone method generic parameters, substituting source-owner parameters. */
static bool clone_mixin_wrapper_type_params(
    const FengCallableSignature *source,
    const FengDecl *source_owner,
    const FengTypeRef *source_instance,
    FengCallableSignature *target) {
    if (source->type_param_count == 0U) {
        return true;
    }
    target->type_params = (FengTypeParam *)calloc(
        source->type_param_count, sizeof(FengTypeParam));
    if (target->type_params == NULL) {
        return false;
    }
    target->type_param_count = source->type_param_count;
    for (size_t index = 0U; index < source->type_param_count; ++index) {
        target->type_params[index].token = source->type_params[index].token;
        target->type_params[index].name = source->type_params[index].name;
        target->type_params[index].constraint = clone_mixin_callable_type_ref(
            source->type_params[index].constraint,
            source_owner,
            source_instance);
        if (source->type_params[index].constraint != NULL &&
            target->type_params[index].constraint == NULL) {
            return false;
        }
    }
    return true;
}

/* Clone a wrapper parameter suffix and substitute source-owner parameters. */
static bool clone_mixin_wrapper_params(
    const FengCallableSignature *source,
    size_t first_param,
    const FengDecl *source_owner,
    const FengTypeRef *source_instance,
    FengCallableSignature *target) {
    if (first_param > source->param_count) {
        return false;
    }
    target->param_count = source->param_count - first_param;
    if (target->param_count == 0U) {
        return true;
    }
    target->params = (FengParameter *)calloc(
        target->param_count, sizeof(FengParameter));
    if (target->params == NULL) {
        return false;
    }
    for (size_t index = 0U; index < target->param_count; ++index) {
        const FengParameter *source_param = &source->params[first_param + index];
        FengParameter *target_param = &target->params[index];

        target_param->token = source_param->token;
        target_param->mutability = source_param->mutability;
        target_param->name = source_param->name;
        target_param->is_variadic = source_param->is_variadic;
        target_param->type = clone_mixin_callable_type_ref(
            source_param->type, source_owner, source_instance);
        if (source_param->type != NULL && target_param->type == NULL) {
            return false;
        }
    }
    return true;
}

/* Build a one-statement wrapper body that performs an ordinary qualified
 * static call.  The final variadic parameter is forwarded through the
 * existing prepacked `...args` AST marker. */
static FengBlock *create_mixin_wrapper_body(
    FengToken token,
    FengExpr *type_target,
    const FengCallableSignature *wrapper_signature,
    bool inject_self,
    bool explicit_void_return) {
    FengExpr *member = NULL;
    FengExpr *callee = NULL;
    FengExpr *call = NULL;
    FengStmt *stmt = NULL;
    FengBlock *body = NULL;
    size_t call_arg_count = wrapper_signature->param_count +
                            (inject_self ? 1U : 0U);

    if (type_target == NULL) {
        return NULL;
    }
    member = new_mixin_wrapper_expr(FENG_EXPR_MEMBER, token);
    if (member == NULL) {
        free_mixin_wrapper_expr(type_target);
        return NULL;
    }
    member->as.member.object = type_target;
    member->as.member.member = wrapper_signature->name;
    callee = member;
    call = new_mixin_wrapper_expr(FENG_EXPR_CALL, token);
    if (call == NULL) {
        free_mixin_wrapper_expr(callee);
        return NULL;
    }
    call->as.call.callee = callee;
    if (wrapper_signature->type_param_count > 0U) {
        call->as.call.explicit_type_args = (FengTypeRef **)calloc(
            wrapper_signature->type_param_count, sizeof(FengTypeRef *));
        if (call->as.call.explicit_type_args == NULL) {
            free_mixin_wrapper_expr(call);
            return NULL;
        }
        call->as.call.has_explicit_type_args = true;
        call->as.call.explicit_type_arg_count =
            wrapper_signature->type_param_count;
        for (size_t index = 0U;
             index < wrapper_signature->type_param_count;
             ++index) {
            FengTypeRef *arg = (FengTypeRef *)calloc(1U, sizeof(*arg));

            if (arg == NULL) {
                free_mixin_wrapper_expr(call);
                return NULL;
            }
            arg->token = wrapper_signature->type_params[index].token;
            arg->kind = FENG_TYPE_REF_NAMED;
            arg->as.named.segments =
                (FengSlice *)calloc(1U, sizeof(FengSlice));
            if (arg->as.named.segments == NULL) {
                free(arg);
                free_mixin_wrapper_expr(call);
                return NULL;
            }
            arg->as.named.segments[0] =
                wrapper_signature->type_params[index].name;
            arg->as.named.segment_count = 1U;
            call->as.call.explicit_type_args[index] = arg;
        }
    }
    if (call_arg_count > 0U) {
        call->as.call.args =
            (FengExpr **)calloc(call_arg_count, sizeof(FengExpr *));
        if (call->as.call.args == NULL) {
            free_mixin_wrapper_expr(call);
            return NULL;
        }
        call->as.call.arg_count = call_arg_count;
    }
    if (inject_self) {
        call->as.call.args[0] =
            new_mixin_wrapper_expr(FENG_EXPR_SELF, token);
        if (call->as.call.args[0] == NULL) {
            free_mixin_wrapper_expr(call);
            return NULL;
        }
        call->as.call.args[0]->as.identifier = (FengSlice){"self", 4U};
    }
    for (size_t index = 0U;
         index < wrapper_signature->param_count;
         ++index) {
        size_t arg_index = index + (inject_self ? 1U : 0U);
        FengExpr *arg = new_mixin_wrapper_expr(
            FENG_EXPR_IDENTIFIER,
            wrapper_signature->params[index].token);

        if (arg == NULL) {
            free_mixin_wrapper_expr(call);
            return NULL;
        }
        arg->as.identifier = wrapper_signature->params[index].name;
        if (index + 1U == wrapper_signature->param_count &&
            wrapper_signature->params[index].is_variadic) {
            arg->is_prepacked_variadic_arg = true;
        }
        call->as.call.args[arg_index] = arg;
    }

    stmt = (FengStmt *)calloc(1U, sizeof(*stmt));
    body = (FengBlock *)calloc(1U, sizeof(*body));
    if (stmt == NULL || body == NULL) {
        free(stmt);
        free(body);
        free_mixin_wrapper_expr(call);
        return NULL;
    }
    stmt->token = token;
    if (explicit_void_return) {
        stmt->kind = FENG_STMT_EXPR;
        stmt->as.expr = call;
    } else {
        stmt->kind = FENG_STMT_RETURN;
        stmt->is_mixin_wrapper_forward_return = true;
        stmt->as.return_value = call;
    }
    body->token = token;
    body->statements = (FengStmt **)calloc(1U, sizeof(FengStmt *));
    if (body->statements == NULL) {
        free_mixin_wrapper_expr(call);
        free(stmt);
        free(body);
        return NULL;
    }
    body->statements[0] = stmt;
    body->statement_count = 1U;
    return body;
}

/* Create a target static wrapper that forwards to the selected source
 * declaration and keeps the mixable fact for later propagation. */
static FengTypeMember *create_mixin_static_wrapper(
    const FengTypeMixinDecl *mixin,
    const FengTypeMember *source_method,
    const FengDecl *source_owner) {
    FengTypeMember *wrapper =
        (FengTypeMember *)calloc(1U, sizeof(*wrapper));
    FengCallableSignature *target;
    const FengCallableSignature *source;

    if (wrapper == NULL || mixin == NULL || source_method == NULL) {
        free(wrapper);
        return NULL;
    }
    source = &source_method->as.callable;
    target = &wrapper->as.callable;
    wrapper->token = mixin->token;
    wrapper->kind = FENG_TYPE_MEMBER_METHOD;
    wrapper->visibility = source_method->visibility;
    wrapper->is_static = true;
    wrapper->is_mixable = true;
    wrapper->is_mixin_static_wrapper = true;
    wrapper->mixin_origin = mixin;
    wrapper->mixin_source_member = source_method;
    target->token = mixin->token;
    target->name = source->name;
    if (!clone_mixin_wrapper_type_params(
            source, source_owner, mixin->source_type, target) ||
        !clone_mixin_wrapper_params(
            source, 0U, source_owner, mixin->source_type, target)) {
        free_mixin_wrapper_member(wrapper);
        return NULL;
    }
    target->return_type = clone_mixin_callable_type_ref(
        source->return_type, source_owner, mixin->source_type);
    if (source->return_type != NULL && target->return_type == NULL) {
        free_mixin_wrapper_member(wrapper);
        return NULL;
    }
    target->body = create_mixin_wrapper_body(
        wrapper->token,
        mixin_type_target_expr_from_ref(mixin->source_type),
        target,
        false,
        target->return_type != NULL && type_ref_is_void(target->return_type));
    if (target->body == NULL) {
        free_mixin_wrapper_member(wrapper);
        return NULL;
    }
    return wrapper;
}

/* Derive the ordinary instance entry for one retained mixable static method. */
static FengTypeMember *create_mixin_instance_wrapper(
    const FengTypeMember *static_method,
    FengExpr *owner_type_target) {
    FengTypeMember *wrapper =
        (FengTypeMember *)calloc(1U, sizeof(*wrapper));
    FengCallableSignature *target;
    const FengCallableSignature *source;

    if (wrapper == NULL || static_method == NULL || owner_type_target == NULL) {
        free(wrapper);
        free_mixin_wrapper_expr(owner_type_target);
        return NULL;
    }
    source = &static_method->as.callable;
    target = &wrapper->as.callable;
    wrapper->token = static_method->token;
    wrapper->kind = FENG_TYPE_MEMBER_METHOD;
    wrapper->visibility = static_method->visibility;
    wrapper->is_static = false;
    wrapper->is_mixable = false;
    wrapper->is_mixin_instance_wrapper = true;
    wrapper->mixin_origin = static_method->mixin_origin;
    wrapper->mixin_source_member = static_method;
    target->token = static_method->token;
    target->name = source->name;
    if (!clone_mixin_wrapper_type_params(source, NULL, NULL, target) ||
        !clone_mixin_wrapper_params(source, 1U, NULL, NULL, target)) {
        free_mixin_wrapper_expr(owner_type_target);
        free_mixin_wrapper_member(wrapper);
        return NULL;
    }
    target->return_type = clone_type_ref_for_inference(source->return_type);
    if (source->return_type != NULL && target->return_type == NULL) {
        free_mixin_wrapper_expr(owner_type_target);
        free_mixin_wrapper_member(wrapper);
        return NULL;
    }
    target->body = create_mixin_wrapper_body(
        wrapper->token,
        owner_type_target,
        target,
        true,
        target->return_type != NULL && type_ref_is_void(target->return_type));
    if (target->body == NULL) {
        free_mixin_wrapper_member(wrapper);
        return NULL;
    }
    return wrapper;
}

/* Compare wrapper parameter surfaces using ordinary semantic type equality. */
static bool mixin_callable_parameters_equal(
    const ResolveContext *context,
    const FengCallableSignature *left,
    const FengCallableSignature *right) {
    if (left == NULL || right == NULL ||
        left->param_count != right->param_count) {
        return false;
    }
    for (size_t index = 0U; index < left->param_count; ++index) {
        if (left->params[index].is_variadic !=
                right->params[index].is_variadic ||
            !type_refs_semantically_equal(
                context,
                left->params[index].type,
                right->params[index].type)) {
            return false;
        }
    }
    return true;
}

/* Apply the existing variadic-overlap rule to two wrapper signatures. */
static bool mixin_variadic_parameters_conflict(
    const ResolveContext *context,
    const FengCallableSignature *left,
    const FengCallableSignature *right) {
    size_t left_fixed = sig_fixed_count(left);
    size_t right_fixed = sig_fixed_count(right);
    size_t compare_count;

    if (left_fixed < right_fixed) {
        if (!sig_is_variadic(left)) {
            return false;
        }
        compare_count = right_fixed;
    } else if (left_fixed > right_fixed) {
        if (!sig_is_variadic(right)) {
            return false;
        }
        compare_count = left_fixed;
    } else {
        compare_count = left_fixed;
    }
    for (size_t index = 0U; index < compare_count; ++index) {
        if (!type_refs_semantically_equal(
                context,
                sig_param_type_at(left, index),
                sig_param_type_at(right, index))) {
            return false;
        }
    }
    return true;
}

/* Compare two mixable callable surfaces after independently dropping a
 * leading parameter prefix.  Offset zero preserves the complete static
 * surface; offset one represents the ordinary instance-wrapper projection. */
static bool mixin_callable_surfaces_conflict(
    const ResolveContext *context,
    const FengCallableSignature *left,
    size_t left_param_offset,
    const FengCallableSignature *right,
    size_t right_param_offset) {
    FengCallableSignature left_surface;
    FengCallableSignature right_surface;

    if (left == NULL || right == NULL ||
        !slice_equals(left->name, right->name) ||
        left->type_param_count != right->type_param_count ||
        left_param_offset > left->param_count ||
        right_param_offset > right->param_count) {
        return false;
    }
    left_surface = *left;
    right_surface = *right;
    left_surface.param_count -= left_param_offset;
    right_surface.param_count -= right_param_offset;
    left_surface.params = left_surface.param_count > 0U
        ? left->params + left_param_offset
        : NULL;
    right_surface.params = right_surface.param_count > 0U
        ? right->params + right_param_offset
        : NULL;

    return mixin_callable_parameters_equal(
               context, &left_surface, &right_surface) ||
           ((sig_is_variadic(&left_surface) ||
             sig_is_variadic(&right_surface)) &&
            mixin_variadic_parameters_conflict(
                context, &left_surface, &right_surface)) ||
           signatures_potentially_overlap(
               context, &left_surface, &right_surface);
}

/* Apply target-explicit priority to one incoming static wrapper candidate. */
static bool target_explicit_member_conflicts_with_mixin_static_wrapper(
    const ResolveContext *context,
    const FengDecl *target,
    const FengTypeMember *candidate) {
    if (target == NULL || candidate == NULL ||
        target->kind != FENG_DECL_TYPE ||
        candidate->kind != FENG_TYPE_MEMBER_METHOD || !candidate->is_static) {
        return false;
    }
    for (size_t index = 0U;
         index < target->as.type_decl.member_count;
         ++index) {
        const FengTypeMember *member = target->as.type_decl.members[index];

        if (member == NULL || member->mixin_origin != NULL ||
            member->is_mixin_static_wrapper ||
            member->is_mixin_instance_wrapper || !member->is_static) {
            continue;
        }
        if (member->kind == FENG_TYPE_MEMBER_FIELD &&
            slice_equals(member->as.field.name,
                         candidate->as.callable.name)) {
            return true;
        }
        if (member->kind == FENG_TYPE_MEMBER_METHOD &&
            (mixin_callable_surfaces_conflict(
                 context,
                 &member->as.callable,
                 0U,
                 &candidate->as.callable,
                 0U) ||
             (member->is_mixable && candidate->is_mixable &&
              member->as.callable.param_count > 0U &&
              candidate->as.callable.param_count > 0U &&
              mixin_callable_surfaces_conflict(
                  context,
                  &member->as.callable,
                  1U,
                  &candidate->as.callable,
                  1U)))) {
            return true;
        }
    }
    return false;
}

/* Prevent a fixed-point round from regenerating the same source wrapper. */
static bool target_already_has_mixin_static_wrapper(
    const FengDecl *target,
    const FengTypeMixinDecl *mixin,
    const FengTypeMember *source_method) {
    for (size_t index = 0U;
         index < target->as.type_decl.member_count;
         ++index) {
        const FengTypeMember *member = target->as.type_decl.members[index];

        if (member != NULL && member->is_mixin_static_wrapper &&
            member->mixin_origin == mixin &&
            member->mixin_source_member == source_method) {
            return true;
        }
    }
    return false;
}

/* Validate the ordinary open or directly-authorized seal source surface
 * needed before a method can be mixed. */
static bool mixable_source_method_is_candidate(
    ResolveContext *context,
    const FengDecl *target,
    const FengDecl *source,
    const FengTypeMember *method,
    const FengDecl **out_first_spec) {
    const FengDecl *spec_decl;

    if (out_first_spec != NULL) {
        *out_first_spec = NULL;
    }
    if (method == NULL || method->kind != FENG_TYPE_MEMBER_METHOD ||
        !method->is_static || !method->is_mixable ||
        (!type_member_is_public(method) &&
         !feng_semantic_type_has_mixable_seal_access(
             target, source, method)) ||
        method->as.callable.param_count == 0U ||
        method->as.callable.params[0].is_variadic ||
        !resolve_type_ref(context,
                          method->as.callable.params[0].type,
                          false)) {
        return false;
    }
    spec_decl = resolve_type_ref_decl(
        context, method->as.callable.params[0].type);
    if (spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
        spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
        return false;
    }
    if (out_first_spec != NULL) {
        *out_first_spec = spec_decl;
    }
    return true;
}

/* Validate and append one source method's static wrapper candidate. */
static bool append_mixin_static_wrapper_candidate(
    ResolveContext *context,
    FengDecl *target,
    const FengTypeMixinDecl *mixin,
    const FengTypeMember *source_method,
    bool *changed) {
    const FengDecl *first_spec = NULL;
    FengTypeMember *wrapper;
    FengTypeMember **grown;

    if (!mixable_source_method_is_candidate(
            context,
            target,
            mixin->resolved_source_decl,
            source_method,
            &first_spec)) {
        return context->errors == NULL || context->error_count == NULL ||
               *context->error_count == 0U;
    }
    if (!type_decl_satisfies_spec_decl(context, target, first_spec)) {
        return resolver_append_error(
                   context,
                   mixin->token,
                   "AE1335",
                   format_message(
                       "type '%.*s' must nominally declare spec '%.*s' before mixing @mixable static method '%.*s'",
                       (int)target->as.type_decl.name.length,
                       target->as.type_decl.name.data,
                       (int)first_spec->as.spec_decl.name.length,
                       first_spec->as.spec_decl.name.data,
                       (int)source_method->as.callable.name.length,
                       source_method->as.callable.name.data)) &&
               false;
    }
    if (target_already_has_mixin_static_wrapper(
            target, mixin, source_method)) {
        return true;
    }
    wrapper = create_mixin_static_wrapper(
        mixin, source_method, mixin->resolved_source_decl);
    if (wrapper == NULL) {
        return false;
    }
    if (target_explicit_member_conflicts_with_mixin_static_wrapper(
            context, target, wrapper)) {
        free_mixin_wrapper_member(wrapper);
        return true;
    }
    grown = (FengTypeMember **)realloc(
        target->as.type_decl.members,
        (target->as.type_decl.member_count + 1U) * sizeof(FengTypeMember *));
    if (grown == NULL) {
        free_mixin_wrapper_member(wrapper);
        return false;
    }
    target->as.type_decl.members = grown;
    target->as.type_decl.members[target->as.type_decl.member_count++] = wrapper;
    if (changed != NULL) {
        *changed = true;
    }
    return true;
}

/* State shared by the ordinary visible-fit method visitor. */
typedef struct MixinFitStaticCollect {
    ResolveContext *context;
    FengDecl *target;
    const FengTypeMixinDecl *mixin;
    bool *changed;
    bool ok;
} MixinFitStaticCollect;

/* Feed one visible fit static method through normal wrapper selection. */
static bool collect_mixin_fit_static_method(
    const FengTypeMember *member,
    const FengSemanticModule *fit_module,
    const FengDecl *fit_decl,
    void *userdata) {
    MixinFitStaticCollect *state = (MixinFitStaticCollect *)userdata;

    (void)fit_module;
    (void)fit_decl;
    if (!append_mixin_static_wrapper_candidate(
            state->context,
            state->target,
            state->mixin,
            member,
            state->changed)) {
        state->ok = false;
        return false;
    }
    return true;
}

/* Recursively materialize one type's generated fields in declaration order. */
static bool expand_type_mixed_fields(FengDecl *target) {
    FengTypeMember **original_members;
    size_t original_count;
    FengTypeMember **expanded_members = NULL;
    size_t expanded_count = 0U;
    size_t expanded_capacity = 0U;
    size_t expanded_field_count = 0U;

    if (target == NULL || target->kind != FENG_DECL_TYPE ||
        target->as.type_decl.mixins_expanded) {
        return true;
    }
    original_members = target->as.type_decl.members;
    original_count = target->as.type_decl.member_count;

    for (size_t position = 0U; position <= original_count; ++position) {
        for (size_t mixin_index = 0U;
             mixin_index < target->as.type_decl.mixin_count;
             ++mixin_index) {
            FengTypeMixinDecl *mixin = &target->as.type_decl.mixins[mixin_index];
            const FengDecl *source = mixin->resolved_source_decl;

            if (mixin->member_index != position || source == NULL ||
                source->kind != FENG_DECL_TYPE) {
                continue;
            }
            mixin->expanded_field_index = expanded_field_count;
            if (!((FengDecl *)source)->as.type_decl.mixins_expanded &&
                !expand_type_mixed_fields((FengDecl *)source)) {
                goto fail;
            }
            for (size_t source_index = 0U;
                 source_index < source->as.type_decl.member_count;
                 ++source_index) {
                const FengTypeMember *source_member =
                    source->as.type_decl.members[source_index];
                FengTypeMember *generated;

                if (source_member == NULL ||
                    source_member->kind != FENG_TYPE_MEMBER_FIELD ||
                    source_member->is_static ||
                    (!type_member_is_public(source_member) &&
                     !feng_semantic_member_is_mixable_seal_capability(
                         source_member)) ||
                    target_explicit_member_conflicts_with_mixed_field(
                        target, source_member->as.field.name)) {
                    continue;
                }
                generated = create_mixed_field(mixin, source_member);
                if (generated == NULL ||
                    !append_raw((void **)&expanded_members,
                                &expanded_count,
                                &expanded_capacity,
                                sizeof(generated),
                                &generated)) {
                    free_generated_mixed_field(generated);
                    goto fail;
                }
                ++expanded_field_count;
            }
        }
        if (position < original_count &&
            !append_raw((void **)&expanded_members,
                        &expanded_count,
                        &expanded_capacity,
                        sizeof(original_members[position]),
                        &original_members[position])) {
            goto fail;
        }
        if (position < original_count && original_members[position] != NULL &&
            original_members[position]->kind == FENG_TYPE_MEMBER_FIELD) {
            ++expanded_field_count;
        }
    }

    free(original_members);
    target->as.type_decl.members = expanded_members;
    target->as.type_decl.member_count = expanded_count;
    target->as.type_decl.mixins_expanded = true;
    return true;

fail:
    for (size_t index = 0U; index < expanded_count; ++index) {
        if (expanded_members[index] != NULL &&
            expanded_members[index]->mixin_origin != NULL) {
            free_generated_mixed_field(expanded_members[index]);
        }
    }
    free(expanded_members);
    return false;
}

/* Expand one program's static behavior candidates using exactly the same
 * lexical aliases, imports, and fit visibility surface as an ordinary
 * hand-written qualified static call in that program. */
static bool expand_program_mixable_static_wrappers(
    const FengSemanticAnalysis *analysis,
    const FengSemanticModule *module,
    const FengProgram *program,
    const VisibleTypeEntry *visible_types,
    size_t visible_type_count,
    const VisibleValueEntry *visible_values,
    size_t visible_value_count,
    const FunctionOverloadSetEntry *function_sets,
    size_t function_set_count,
    bool *changed,
    FengSemanticError **errors,
    size_t *error_count,
    size_t *error_capacity) {
    ResolveContext context;
    AliasEntry *aliases = NULL;
    size_t alias_count = 0U;
    size_t alias_capacity = 0U;
    ImportedModuleEntry *imported_modules = NULL;
    size_t imported_module_count = 0U;
    size_t imported_module_capacity = 0U;
    bool ok = true;

    memset(&context, 0, sizeof(context));
    context.analysis = analysis;
    context.module = module;
    context.program = program;
    context.pointer_size = analysis->pointer_size;
    context.visible_types = visible_types;
    context.visible_type_count = visible_type_count;
    context.visible_values = visible_values;
    context.visible_value_count = visible_value_count;
    context.function_sets = function_sets;
    context.function_set_count = function_set_count;
    context.errors = errors;
    context.error_count = error_count;
    context.error_capacity = error_capacity;

    ok = build_program_aliases(
        analysis, program, &aliases, &alias_count, &alias_capacity);
    for (size_t use_index = 0U;
         use_index < program->use_count && ok;
         ++use_index) {
        size_t target_index = find_module_index_by_path(
            analysis,
            program->uses[use_index].segments,
            program->uses[use_index].segment_count);
        ImportedModuleEntry entry;
        bool already = false;

        if (target_index == analysis->module_count) {
            continue;
        }
        entry.target_module = &analysis->modules[target_index];
        for (size_t index = 0U;
             index < imported_module_count;
             ++index) {
            if (imported_modules[index].target_module == entry.target_module) {
                already = true;
                break;
            }
        }
        if (!already) {
            ok = append_raw((void **)&imported_modules,
                            &imported_module_count,
                            &imported_module_capacity,
                            sizeof(entry),
                            &entry);
        }
    }
    context.aliases = aliases;
    context.alias_count = alias_count;
    context.imported_modules = imported_modules;
    context.imported_module_count = imported_module_count;

    for (size_t decl_index = 0U;
         decl_index < program->declaration_count && ok;
         ++decl_index) {
        FengDecl *target = program->declarations[decl_index];
        const TypeParamEntry *previous_type_params = NULL;
        size_t previous_type_param_count = 0U;

        if (target == NULL || target->kind != FENG_DECL_TYPE ||
            target->as.type_decl.mixin_count == 0U) {
            continue;
        }
        if (!resolver_push_type_params(
                &context,
                target->as.type_decl.type_params,
                target->as.type_decl.type_param_count,
                &previous_type_params,
                &previous_type_param_count)) {
            ok = false;
            break;
        }
        for (size_t mixin_index = 0U;
             mixin_index < target->as.type_decl.mixin_count && ok;
             ++mixin_index) {
            const FengTypeMixinDecl *mixin =
                &target->as.type_decl.mixins[mixin_index];
            const FengDecl *source = mixin->resolved_source_decl;
            MixinFitStaticCollect fit_state;

            if (source == NULL || source->kind != FENG_DECL_TYPE) {
                continue;
            }
            for (size_t member_index = 0U;
                 member_index < source->as.type_decl.member_count && ok;
                 ++member_index) {
                ok = append_mixin_static_wrapper_candidate(
                    &context,
                    target,
                    mixin,
                    source->as.type_decl.members[member_index],
                    changed);
            }
            if (!ok) {
                break;
            }
            memset(&fit_state, 0, sizeof(fit_state));
            fit_state.context = &context;
            fit_state.target = target;
            fit_state.mixin = mixin;
            fit_state.changed = changed;
            fit_state.ok = true;
            (void)visit_visible_fit_methods_for_type(
                &context,
                source,
                (FengSlice){0},
                false,
                true,
                collect_mixin_fit_static_method,
                &fit_state);
            ok = fit_state.ok;
        }
        resolver_pop_type_params(
            &context, previous_type_params, previous_type_param_count);
    }

    resolver_free_scopes(&context);
    free(aliases);
    free(imported_modules);
    return ok;
}

/* Derive instance wrappers for every retained mixable static type method. */
static bool append_all_type_mixable_instance_wrappers(FengDecl *type_decl) {
    size_t static_surface_count;
    FengTypeRef *owner_ref;

    if (type_decl == NULL || type_decl->kind != FENG_DECL_TYPE) {
        return true;
    }
    static_surface_count = type_decl->as.type_decl.member_count;
    owner_ref = mixin_owner_instance_type_ref(type_decl);
    if (owner_ref == NULL) {
        return false;
    }
    for (size_t index = 0U; index < static_surface_count; ++index) {
        const FengTypeMember *member = type_decl->as.type_decl.members[index];
        FengExpr *owner_target;
        FengTypeMember *wrapper;
        FengTypeMember **grown;

        if (member == NULL || member->kind != FENG_TYPE_MEMBER_METHOD ||
            !member->is_static || !member->is_mixable ||
            member->as.callable.param_count == 0U) {
            continue;
        }
        owner_target = mixin_type_target_expr_from_ref(owner_ref);
        wrapper = create_mixin_instance_wrapper(member, owner_target);
        if (wrapper == NULL) {
            free_synthetic_type_ref(owner_ref);
            return false;
        }
        grown = (FengTypeMember **)realloc(
            type_decl->as.type_decl.members,
            (type_decl->as.type_decl.member_count + 1U) *
                sizeof(FengTypeMember *));
        if (grown == NULL) {
            free_mixin_wrapper_member(wrapper);
            free_synthetic_type_ref(owner_ref);
            return false;
        }
        type_decl->as.type_decl.members = grown;
        type_decl->as.type_decl.members[
            type_decl->as.type_decl.member_count++] = wrapper;
    }
    free_synthetic_type_ref(owner_ref);
    return true;
}

/* Derive fit-owned instance wrappers beside their mixable static methods. */
static bool append_all_fit_mixable_instance_wrappers(FengDecl *fit_decl) {
    size_t static_surface_count;

    if (fit_decl == NULL || fit_decl->kind != FENG_DECL_FIT) {
        return true;
    }
    static_surface_count = fit_decl->as.fit_decl.member_count;
    for (size_t index = 0U; index < static_surface_count; ++index) {
        const FengTypeMember *member = fit_decl->as.fit_decl.members[index];
        FengExpr *owner_target;
        FengTypeMember *wrapper;
        FengTypeMember **grown;

        if (member == NULL || member->kind != FENG_TYPE_MEMBER_METHOD ||
            !member->is_static || !member->is_mixable ||
            member->as.callable.param_count == 0U) {
            continue;
        }
        owner_target =
            mixin_type_target_expr_from_ref(fit_decl->as.fit_decl.target);
        wrapper = create_mixin_instance_wrapper(member, owner_target);
        if (wrapper == NULL) {
            return false;
        }
        grown = (FengTypeMember **)realloc(
            fit_decl->as.fit_decl.members,
            (fit_decl->as.fit_decl.member_count + 1U) *
                sizeof(FengTypeMember *));
        if (grown == NULL) {
            free_mixin_wrapper_member(wrapper);
            return false;
        }
        fit_decl->as.fit_decl.members = grown;
        fit_decl->as.fit_decl.members[
            fit_decl->as.fit_decl.member_count++] = wrapper;
    }
    return true;
}

/* Derive every local type and fit instance wrapper after static propagation. */
static bool append_all_mixable_instance_wrappers(
    FengSemanticAnalysis *analysis) {
    for (size_t module_index = 0U;
         module_index < analysis->module_count;
         ++module_index) {
        FengSemanticModule *module = &analysis->modules[module_index];

        if (module->origin == FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        for (size_t program_index = 0U;
             program_index < module->program_count;
             ++program_index) {
            FengProgram *program = (FengProgram *)module->programs[program_index];

            for (size_t decl_index = 0U;
                 decl_index < program->declaration_count;
                 ++decl_index) {
                FengDecl *decl = program->declarations[decl_index];

                if (decl != NULL && decl->kind == FENG_DECL_TYPE) {
                    if (!append_all_type_mixable_instance_wrappers(decl)) {
                        return false;
                    }
                } else if (decl != NULL && decl->kind == FENG_DECL_FIT) {
                    if (!append_all_fit_mixable_instance_wrappers(decl)) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

/* Expand every local type only after the complete dependency graph has passed
 * cycle validation.  Imported `.ft` types already expose their final ordinary
 * member surface and therefore do not carry raw mixin directives. */
static bool expand_all_mixed_fields(FengSemanticAnalysis *analysis,
                                    FengSemanticError **errors,
                                    size_t *error_count,
                                    size_t *error_capacity) {
    MixinTypeEntry *entries = NULL;
    size_t entry_count = 0U;
    size_t entry_capacity = 0U;
    size_t *entry_stack = NULL;
    const FengTypeMixinDecl **edge_stack = NULL;
    const char **edge_path_stack = NULL;
    bool ok = true;

    for (size_t module_index = 0U;
         module_index < analysis->module_count && ok;
         ++module_index) {
        FengSemanticModule *module = &analysis->modules[module_index];

        if (module->origin == FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        for (size_t program_index = 0U;
             program_index < module->program_count && ok;
             ++program_index) {
            const FengProgram *program = module->programs[program_index];

            for (size_t decl_index = 0U;
                 decl_index < program->declaration_count;
                 ++decl_index) {
                FengDecl *decl = program->declarations[decl_index];
                MixinTypeEntry entry;

                if (decl == NULL || decl->kind != FENG_DECL_TYPE) {
                    continue;
                }
                entry.decl = decl;
                entry.program = program;
                entry.cycle_state = 0U;
                ok = append_raw((void **)&entries,
                                &entry_count,
                                &entry_capacity,
                                sizeof(entry),
                                &entry);
                if (!ok) {
                    break;
                }
            }
        }
    }

    if (ok && entry_count > 0U) {
        entry_stack = (size_t *)calloc(entry_count, sizeof(*entry_stack));
        edge_stack = (const FengTypeMixinDecl **)calloc(
            entry_count, sizeof(*edge_stack));
        edge_path_stack = (const char **)calloc(
            entry_count, sizeof(*edge_path_stack));
        ok = entry_stack != NULL && edge_stack != NULL &&
             edge_path_stack != NULL;
    }
    for (size_t index = 0U; index < entry_count && ok; ++index) {
        if (entries[index].cycle_state == 0U) {
            ok = validate_mixin_cycle_from(entries,
                                           entry_count,
                                           index,
                                           entry_stack,
                                           edge_stack,
                                           edge_path_stack,
                                           0U,
                                           errors,
                                           error_count,
                                           error_capacity);
        }
    }
    for (size_t index = 0U; index < entry_count && ok; ++index) {
        ok = expand_type_mixed_fields(entries[index].decl);
    }
    free(entry_stack);
    free(edge_stack);
    free(edge_path_stack);
    free(entries);
    return ok;
}

/* Propagate mixable static behavior to a fixed point before deriving any
 * instance entry.  Expansion cycles have already been rejected, so the
 * maximum useful number of rounds is bounded by the number of declarations. */
static bool expand_all_mixable_static_wrappers(
    FengSemanticAnalysis *analysis,
    FengSemanticError **errors,
    size_t *error_count,
    size_t *error_capacity) {
    size_t declaration_count = 0U;

    for (size_t module_index = 0U;
         module_index < analysis->module_count;
         ++module_index) {
        const FengSemanticModule *module = &analysis->modules[module_index];

        if (module->origin == FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        for (size_t program_index = 0U;
             program_index < module->program_count;
             ++program_index) {
            declaration_count +=
                module->programs[program_index]->declaration_count;
        }
    }
    for (size_t iteration = 0U;
         iteration <= declaration_count;
         ++iteration) {
        bool changed = false;
        bool ok = true;

        for (size_t module_index = 0U;
             module_index < analysis->module_count && ok &&
             (error_count == NULL || *error_count == 0U);
             ++module_index) {
            if (analysis->modules[module_index].origin ==
                FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
                continue;
            }
            ok = check_symbol_conflicts(
                analysis,
                &analysis->modules[module_index],
                SEMANTIC_MODULE_PASS_MIXIN_STATIC_WRAPPERS,
                NULL,
                NULL,
                &changed,
                errors,
                error_count,
                error_capacity);
        }
        if (!ok || (error_count != NULL && *error_count > 0U)) {
            return false;
        }
        if (!changed) {
            return true;
        }
    }
    return false;
}

static size_t count_all_callables(const FengSemanticAnalysis *analysis) {
    size_t module_index;
    size_t count = 0U;

    if (analysis == NULL) {
        return 0U;
    }

    for (module_index = 0U; module_index < analysis->module_count; ++module_index) {
        const FengSemanticModule *module = &analysis->modules[module_index];
        size_t program_index;

        for (program_index = 0U; program_index < module->program_count; ++program_index) {
            const FengProgram *program = module->programs[program_index];
            size_t decl_index;

            if (program == NULL) {
                continue;
            }

            for (decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
                const FengDecl *decl = program->declarations[decl_index];
                size_t member_index;

                if (decl == NULL) {
                    continue;
                }

                if (decl->kind == FENG_DECL_FUNCTION) {
                    ++count;
                    continue;
                }

                if (decl->kind == FENG_DECL_TYPE) {
                    /* Mixin binding/type facts can require one additional
                     * fixed-point step per dependency edge when the source
                     * declaration appears later in program order. */
                    count += decl->as.type_decl.mixin_count;
                    for (member_index = 0U;
                         member_index < decl->as.type_decl.member_count;
                         ++member_index) {
                        const FengTypeMember *member = decl->as.type_decl.members[member_index];

                        if (member != NULL &&
                            (member->kind == FENG_TYPE_MEMBER_METHOD ||
                             member->kind == FENG_TYPE_MEMBER_CONSTRUCTOR ||
                             member->kind == FENG_TYPE_MEMBER_FINALIZER)) {
                            ++count;
                        }
                    }
                    continue;
                }

                if (decl->kind == FENG_DECL_SPEC) {
                    if (decl->as.spec_decl.form == FENG_SPEC_FORM_CALLABLE) {
                        ++count;
                        continue;
                    }
                    if (decl->as.spec_decl.form == FENG_SPEC_FORM_UNION ||
                        decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
                        continue;
                    }
                    for (member_index = 0U;
                         member_index < decl->as.spec_decl.as.object.member_count;
                         ++member_index) {
                        const FengTypeMember *member =
                            decl->as.spec_decl.as.object.members[member_index];

                        if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD) {
                            ++count;
                        }
                    }
                    continue;
                }

                if (decl->kind == FENG_DECL_FIT) {
                    for (member_index = 0U;
                         member_index < decl->as.fit_decl.member_count;
                         ++member_index) {
                        const FengTypeMember *member = decl->as.fit_decl.members[member_index];

                        if (member != NULL && member->kind == FENG_TYPE_MEMBER_METHOD) {
                            ++count;
                        }
                    }
                }
            }
        }
    }

    return count;
}

static bool report_uninferred_callable_returns(const FengSemanticAnalysis *analysis,
                                               const CallableReturnCache *callable_return_cache,
                                               FengSemanticError **errors,
                                               size_t *error_count,
                                               size_t *error_capacity) {
    size_t module_index;
    bool ok = true;

    if (analysis == NULL) {
        return true;
    }

    for (module_index = 0U; module_index < analysis->module_count; ++module_index) {
        const FengSemanticModule *module = &analysis->modules[module_index];
        size_t program_index;

        /* External package modules have no local bodies to infer. */
        if (module->origin == FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }

        for (program_index = 0U; program_index < module->program_count; ++program_index) {
            const FengProgram *program = module->programs[program_index];
            size_t decl_index;

            for (decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
                const FengDecl *decl = program->declarations[decl_index];

                if (decl->kind == FENG_DECL_FUNCTION && decl->as.function_decl.return_type == NULL) {
                    if (find_callable_return_cache_entry(callable_return_cache,
                                                         &decl->as.function_decl) == NULL) {
                        ok = append_error(
                            errors,
                            error_count,
                            error_capacity,
                            program->path,
                            decl->as.function_decl.token,
                            "AE0503", format_message(
                                "function '%.*s' requires an explicit return type because its return type could not be inferred",
                                (int)decl->as.function_decl.name.length,
                                decl->as.function_decl.name.data));
                        if (!ok) {
                            return false;
                        }
                    }
                    continue;
                }

                if (decl->kind == FENG_DECL_TYPE) {
                    size_t member_index;

                    for (member_index = 0U;
                         member_index < decl->as.type_decl.member_count;
                         ++member_index) {
                        const FengTypeMember *member =
                            decl->as.type_decl.members[member_index];

                        if (member->kind != FENG_TYPE_MEMBER_METHOD ||
                            member->as.callable.return_type != NULL) {
                            continue;
                        }
                        if (find_callable_return_cache_entry(callable_return_cache,
                                                             &member->as.callable) != NULL) {
                            continue;
                        }

                        ok = append_error(
                            errors,
                            error_count,
                            error_capacity,
                            program->path,
                            member->as.callable.token,
                            "AE0503", format_message(
                                "method '%.*s.%.*s' requires an explicit return type because its return type could not be inferred",
                                (int)decl->as.type_decl.name.length,
                                decl->as.type_decl.name.data,
                                (int)member->as.callable.name.length,
                                member->as.callable.name.data));
                        if (!ok) {
                            return false;
                        }
                    }
                }
            }
        }
    }

    return true;
}

static bool type_ref_is_named_simple(const FengTypeRef *type_ref, const char *name) {
    size_t len;

    if (type_ref == NULL || type_ref->kind != FENG_TYPE_REF_NAMED ||
        type_ref->as.named.segment_count != 1U) {
        return false;
    }
    len = strlen(name);
    return type_ref->as.named.segments[0].length == len &&
           memcmp(type_ref->as.named.segments[0].data, name, len) == 0;
}

static bool main_param_type_is_string_array(const FengTypeRef *type_ref) {
    return type_ref != NULL && type_ref->kind == FENG_TYPE_REF_ARRAY &&
           type_ref_is_named_simple(type_ref->as.inner, "string");
}

static bool validate_main_entry(const FengSemanticAnalysis *analysis,
                                FengCompileTarget target,
                                FengSemanticError **errors,
                                size_t *error_count,
                                size_t *error_capacity) {
    static const FengToken kEmptyToken = {0};
    const FengDecl *first_main = NULL;
    const char *first_main_path = NULL;
    size_t main_count = 0U;
    size_t module_index;
    bool ok = true;

    if (target != FENG_COMPILE_TARGET_BIN || analysis == NULL) {
        return true;
    }

    for (module_index = 0U; module_index < analysis->module_count; ++module_index) {
        const FengSemanticModule *module = &analysis->modules[module_index];
        size_t program_index;

        for (program_index = 0U; program_index < module->program_count; ++program_index) {
            const FengProgram *program = module->programs[program_index];
            size_t decl_index;

            for (decl_index = 0U; decl_index < program->declaration_count; ++decl_index) {
                const FengDecl *decl = program->declarations[decl_index];
                const FengCallableSignature *sig;

                if (decl == NULL || decl->kind != FENG_DECL_FUNCTION) {
                    continue;
                }
                sig = &decl->as.function_decl;
                if (sig->name.length != 4U || memcmp(sig->name.data, "main", 4U) != 0) {
                    continue;
                }
                main_count += 1U;
                if (main_count == 1U) {
                    first_main = decl;
                    first_main_path = program->path;
                } else {
                    ok = append_error(errors, error_count, error_capacity,
                                      program->path, sig->token,
                                      "AE0907", format_message(
                                          "duplicate 'main' entry: target 'bin' requires exactly one 'main(args: string[])' across all programs"));
                    if (!ok) {
                        return false;
                    }
                }
            }
        }
    }

    if (main_count == 0U) {
        ok = append_error(errors, error_count, error_capacity,
                          NULL, kEmptyToken,
                          "AE0908", format_message(
                              "target 'bin' requires a 'main(args: string[])' entry function but none was found"));
        return ok;
    }

    {
        const FengCallableSignature *sig = &first_main->as.function_decl;

        if (sig->param_count != 1U ||
            sig->params[0].name.length != 4U ||
            memcmp(sig->params[0].name.data, "args", 4U) != 0 ||
            !main_param_type_is_string_array(sig->params[0].type)) {
            ok = append_error(errors, error_count, error_capacity,
                              first_main_path, sig->token,
                              "AE0909", format_message(
                                  "'main' entry must have signature 'main(args: string[])'"));
            if (!ok) {
                return false;
            }
        }
        if (sig->return_type != NULL && !type_ref_is_void(sig->return_type)) {
            ok = append_error(errors, error_count, error_capacity,
                              first_main_path, sig->token,
                              "AE0910", format_message(
                                  "'main' entry must return void"));
            if (!ok) {
                return false;
            }
        }
        if (decl_is_public(first_main)) {
            /* main is the program entry; visibility is irrelevant here. */
        }
    }

    return ok;
}

/* Phase S3-pre: pre-compute spec witnesses for builtin-subject spec relations.
 *
 * When an imported module contains a concrete generic type instance whose type
 * parameter has a constraint satisfied by a builtin fit (e.g. Map<string, V>
 * where string: Hashable<string>), the consumer module's semantic pass never
 * encounters the type-ref resolution that would trigger on-demand witness
 * computation.  The codegen still needs the witness when emitting method
 * wrappers for these imported generic instances.
 *
 * This pass iterates all spec relations with builtin subject keys and
 * pre-computes their witnesses using each local module's visibility context. */
/* Resolve a named type ref to its decl using the analysis module list.
 * Lighter than the full resolve_type_ref_decl — does not require a
 * ResolveContext or visibility tables, only the global module array. */
static const FengDecl *analysis_resolve_named_type_ref(
    const FengSemanticAnalysis *analysis,
    const FengTypeRef *ref) {
    size_t mi;

    if (ref == NULL || ref->kind != FENG_TYPE_REF_NAMED ||
        ref->as.named.segment_count == 0U) {
        return NULL;
    }
    if (ref->as.named.segment_count == 1U &&
        is_builtin_type_name(ref->as.named.segments[0])) {
        return NULL;
    }
    if (ref->as.named.segment_count > 1U) {
        size_t mod_index = find_module_index_by_path(
            analysis, ref->as.named.segments,
            ref->as.named.segment_count - 1U);

        if (mod_index < analysis->module_count) {
            return find_module_public_type_decl(
                &analysis->modules[mod_index],
                ref->as.named.segments[ref->as.named.segment_count - 1U],
                ref->as.named.type_arg_count);
        }
        return NULL;
    }
    for (mi = 0U; mi < analysis->module_count; ++mi) {
        const FengDecl *d = find_module_public_type_decl(
            &analysis->modules[mi], ref->as.named.segments[0],
            ref->as.named.type_arg_count);

        if (d != NULL) {
            return d;
        }
    }
    return NULL;
}

/* Resolve an imported declaration's unqualified member ref in its declaring
 * module before falling back to the analysis-wide qualified-name lookup. */
static const FengDecl *analysis_resolve_named_type_ref_from_module(
    const FengSemanticAnalysis *analysis,
    const FengSemanticModule *declaring_module,
    const FengTypeRef *ref) {
    const FengDecl *decl;

    if (analysis == NULL || ref == NULL || ref->kind != FENG_TYPE_REF_NAMED ||
        ref->as.named.segment_count == 0U) {
        return NULL;
    }
    if (ref->as.named.segment_count == 1U && declaring_module != NULL) {
        decl = find_module_public_type_decl(
            declaring_module,
            ref->as.named.segments[0],
            ref->as.named.type_arg_count);
        if (decl != NULL) {
            return decl;
        }
    }
    return analysis_resolve_named_type_ref(analysis, ref);
}

/* Append one object-form leaf to an imported intersection's flattened set. */
static bool append_unique_intersection_leaf(const FengDecl ***items,
                                            size_t *count,
                                            size_t *capacity,
                                            const FengDecl *leaf) {
    size_t index;

    for (index = 0U; index < *count; ++index) {
        if ((*items)[index] == leaf) {
            return true;
        }
    }
    return append_raw((void **)items, count, capacity, sizeof(**items), &leaf);
}

/* Try to flatten one imported intersection. A false result with
 * `out_pending` set means that a nested intersection must be computed first. */
static bool precompute_imported_intersection_spec_info(
    FengSemanticAnalysis *analysis,
    const FengSemanticModule *declaring_module,
    const FengDecl *decl,
    bool *out_pending) {
    const FengDecl **flattened = NULL;
    size_t flattened_count = 0U;
    size_t flattened_capacity = 0U;
    size_t member_index;

    *out_pending = false;
    for (member_index = 0U;
         member_index < decl->as.spec_decl.as.intersection_form.member_count;
         ++member_index) {
        const FengTypeRef *member_ref =
            decl->as.spec_decl.as.intersection_form.members[member_index];
        const FengDecl *member_decl = analysis_resolve_named_type_ref_from_module(
            analysis, declaring_module, member_ref);

        if (member_decl == NULL || member_decl->kind != FENG_DECL_SPEC) {
            free(flattened);
            *out_pending = true;
            return false;
        }
        if (member_decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
            const FengIntersectionSpecInfo *inner =
                feng_semantic_lookup_intersection_spec_info(analysis, member_decl);

            if (inner == NULL) {
                free(flattened);
                *out_pending = true;
                return false;
            }
            for (size_t inner_index = 0U;
                 inner_index < inner->flattened_member_count;
                 ++inner_index) {
                if (!append_unique_intersection_leaf(
                        &flattened,
                        &flattened_count,
                        &flattened_capacity,
                        inner->flattened_members[inner_index])) {
                    free(flattened);
                    return false;
                }
            }
            continue;
        }
        if (member_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT ||
            !append_unique_intersection_leaf(&flattened,
                                             &flattened_count,
                                             &flattened_capacity,
                                             member_decl)) {
            free(flattened);
            return false;
        }
    }

    return feng_semantic_record_intersection_spec_info(
        analysis, decl, flattened, flattened_count);
}

/* Imported packages have already validated their declarations and are skipped
 * by the local resolve pass. Rebuild their derived intersection metadata in
 * dependency order so consumer-side constraint checks see the same surface. */
static bool precompute_imported_intersection_spec_infos(
    FengSemanticAnalysis *analysis) {
    size_t intersection_count = 0U;
    size_t iteration;

    if (analysis == NULL) {
        return true;
    }
    for (size_t module_index = 0U;
         module_index < analysis->module_count;
         ++module_index) {
        const FengSemanticModule *module = &analysis->modules[module_index];

        if (module->origin != FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        for (size_t program_index = 0U;
             program_index < module->program_count;
             ++program_index) {
            const FengProgram *program = module->programs[program_index];

            for (size_t decl_index = 0U;
                 decl_index < program->declaration_count;
                 ++decl_index) {
                const FengDecl *decl = program->declarations[decl_index];

                if (decl != NULL && decl->kind == FENG_DECL_SPEC &&
                    decl->as.spec_decl.form == FENG_SPEC_FORM_INTERSECTION) {
                    ++intersection_count;
                }
            }
        }
    }

    for (iteration = 0U; iteration < intersection_count; ++iteration) {
        bool changed = false;

        for (size_t module_index = 0U;
             module_index < analysis->module_count;
             ++module_index) {
            const FengSemanticModule *module = &analysis->modules[module_index];

            if (module->origin != FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
                continue;
            }
            for (size_t program_index = 0U;
                 program_index < module->program_count;
                 ++program_index) {
                const FengProgram *program = module->programs[program_index];

                for (size_t decl_index = 0U;
                     decl_index < program->declaration_count;
                     ++decl_index) {
                    const FengDecl *decl = program->declarations[decl_index];
                    bool pending;

                    if (decl == NULL || decl->kind != FENG_DECL_SPEC ||
                        decl->as.spec_decl.form != FENG_SPEC_FORM_INTERSECTION ||
                        feng_semantic_lookup_intersection_spec_info(analysis, decl) != NULL) {
                        continue;
                    }
                    if (precompute_imported_intersection_spec_info(
                            analysis, module, decl, &pending)) {
                        changed = true;
                    } else if (!pending) {
                        return false;
                    }
                }
            }
        }
        if (!changed) {
            break;
        }
    }
    return true;
}

/* Find the spec type ref in a fit decl's spec list that resolves to the
 * given spec_decl.  Returns the concrete type ref (e.g. Hashable<string>)
 * or NULL if no match is found. */
static const FengTypeRef *find_spec_type_ref_in_fit(
    const FengSemanticAnalysis *analysis,
    const FengDecl *fit_decl,
    const FengDecl *target_spec_decl) {
    size_t i;

    if (fit_decl == NULL || fit_decl->kind != FENG_DECL_FIT) {
        return NULL;
    }
    for (i = 0U; i < fit_decl->as.fit_decl.spec_count; ++i) {
        const FengTypeRef *spec_ref = fit_decl->as.fit_decl.specs[i];
        const FengDecl *resolved =
            analysis_resolve_named_type_ref(analysis, spec_ref);

        if (resolved == target_spec_decl) {
            return spec_ref;
        }
    }
    return NULL;
}

/* Pre-register union-spec member info for all modules (both local and
 * imported-package) before the per-program resolution pass.
 *
 * Source files within a module are processed in alphabetical path order.
 * Without this pre-registration, if a file that uses a union spec is sorted
 * before the file that defines it, feng_semantic_lookup_union_spec_info
 * returns NULL during constructor/method argument matching and a spurious
 * AE0315 error is reported.
 *
 * For imported-package modules the pre-registered info is the final version
 * (these modules are skipped during the resolution pass).
 *
 * For local modules the pre-registered info is a lightweight clone of the
 * member type refs.  When the resolution pass later reaches the defining
 * file, record_normalized_union_spec_info replaces it with the fully
 * normalized version (nested-union expansion, deduplication, validation)
 * via feng_semantic_record_union_spec_info's built-in replacement
 * semantics. */
static void precompute_union_spec_infos(FengSemanticAnalysis *analysis) {
    size_t mi;

    if (analysis == NULL) {
        return;
    }

    for (mi = 0U; mi < analysis->module_count; ++mi) {
        const FengSemanticModule *mod = &analysis->modules[mi];
        size_t pi;

        for (pi = 0U; pi < mod->program_count; ++pi) {
            const FengProgram *prog = mod->programs[pi];
            size_t di;

            for (di = 0U; di < prog->declaration_count; ++di) {
                const FengDecl *decl = prog->declarations[di];
                FengUnionSpecMemberInfo *members;
                size_t member_count;
                size_t member_index;
                bool oom = false;

                if (decl == NULL || decl->kind != FENG_DECL_SPEC ||
                    decl->as.spec_decl.form != FENG_SPEC_FORM_UNION) {
                    continue;
                }
                if (feng_semantic_lookup_union_spec_info(analysis, decl) != NULL) {
                    continue;
                }

                member_count = decl->as.spec_decl.as.union_form.member_count;
                if (member_count == 0U) {
                    continue;
                }

                members = (FengUnionSpecMemberInfo *)calloc(member_count, sizeof(*members));
                if (members == NULL) {
                    continue;
                }

                for (member_index = 0U; member_index < member_count; ++member_index) {
                    const FengTypeRef *src = decl->as.spec_decl.as.union_form.members[member_index];

                    members[member_index].type_ref = clone_type_ref_for_inference(src);
                    members[member_index].resolved_decl = NULL;
                    if (src != NULL && members[member_index].type_ref == NULL) {
                        oom = true;
                        break;
                    }
                }

                if (oom) {
                    for (size_t k = 0U; k < member_count; ++k) {
                        free_synthetic_type_ref((FengTypeRef *)members[k].type_ref);
                    }
                    free(members);
                    continue;
                }

                feng_semantic_record_union_spec_info(analysis, decl, members, member_count);
            }
        }
    }
}

/* Pre-compute spec witnesses for builtin/array subjects whose fits are
 * defined in imported-package modules.  In a local-only build the
 * on-demand path in the resolution pass handles this, but imported
 * modules are skipped entirely during resolution so the witnesses are
 * never computed.  The codegen still needs them when emitting generic
 * type instance method wrappers that reference constrained type params. */
static void precompute_imported_builtin_spec_witnesses(
        FengSemanticAnalysis *analysis) {
    size_t ri;
    size_t mi;
    bool has_imported = false;
    ImportedModuleEntry *imported_modules = NULL;
    size_t imported_module_count = 0U;
    size_t imported_module_capacity = 0U;
    bool oom = false;
    const FengSemanticModule *first_local_module = NULL;
    ResolveContext ctx;

    if (analysis == NULL || analysis->spec_relation_count == 0U) {
        return;
    }

    /* Only needed when imported-package modules exist. */
    for (mi = 0U; mi < analysis->module_count; ++mi) {
        if (analysis->modules[mi].origin ==
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            has_imported = true;
            break;
        }
    }
    if (!has_imported) {
        return;
    }

    /* Collect the union of all use-imported modules across every local
     * program so every cross-module fit has a chance to be found. */
    for (mi = 0U; mi < analysis->module_count && !oom; ++mi) {
        const FengSemanticModule *mod = &analysis->modules[mi];
        size_t pi;

        if (mod->origin == FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        if (first_local_module == NULL) {
            first_local_module = mod;
        }
        for (pi = 0U; pi < mod->program_count && !oom; ++pi) {
            const FengProgram *prog = mod->programs[pi];
            size_t ui;

            for (ui = 0U; ui < prog->use_count && !oom; ++ui) {
                const FengUseDecl *use_decl = &prog->uses[ui];
                size_t target_index = find_module_index_by_path(
                    analysis, use_decl->segments, use_decl->segment_count);
                size_t scan;
                bool already = false;
                ImportedModuleEntry entry;

                if (target_index == analysis->module_count) {
                    continue;
                }
                entry.target_module = &analysis->modules[target_index];
                for (scan = 0U; scan < imported_module_count; ++scan) {
                    if (imported_modules[scan].target_module ==
                        entry.target_module) {
                        already = true;
                        break;
                    }
                }
                if (already) {
                    continue;
                }
                oom = !append_raw((void **)&imported_modules,
                                  &imported_module_count,
                                  &imported_module_capacity,
                                  sizeof(entry),
                                  &entry);
            }
        }
    }

    if (first_local_module == NULL || oom) {
        free(imported_modules);
        return;
    }

    /* Build a minimal ResolveContext with visibility info from all local
     * modules. The witness computation for builtin subjects only needs
     * analysis (for storage), module/imported_modules (for fit visibility),
     * and synthetic_type_refs (for type-param substitution tracking). */
    memset(&ctx, 0, sizeof(ctx));
    ctx.analysis = analysis;
    ctx.module = first_local_module;
    ctx.pointer_size = analysis->pointer_size;
    ctx.imported_modules = imported_modules;
    ctx.imported_module_count = imported_module_count;

    for (ri = 0U; ri < analysis->spec_relation_count; ++ri) {
        const FengSpecRelation *rel = &analysis->spec_relations[ri];
        const FengDecl *spec_decl = rel->spec_decl;
        size_t source_index;

        if ((rel->subject_key.kind != FENG_SEMANTIC_SUBJECT_KEY_BUILTIN &&
             rel->subject_key.kind != FENG_SEMANTIC_SUBJECT_KEY_ARRAY) ||
            spec_decl == NULL || spec_decl->kind != FENG_DECL_SPEC ||
            spec_decl->as.spec_decl.form != FENG_SPEC_FORM_OBJECT) {
            continue;
        }

        /* Only direct fit heads carry the exact subject and spec instances.
         * Computing that head recursively materializes every inherited
         * parent witness with the same subject; FIT_PARENT relation entries
         * therefore need no independent, potentially under-instantiated
         * witness construction. */
        for (source_index = 0U;
             source_index < rel->source_count;
             ++source_index) {
            const FengSpecRelationSource *source = &rel->sources[source_index];
            const FengDecl *fit_decl = source->via_fit_decl;
            const FengTypeRef *source_type_ref;
            const FengTypeRef *spec_type_ref;
            InferredExprType source_type;

            if (source->kind != FENG_SPEC_RELATION_SOURCE_FIT_HEAD ||
                fit_decl == NULL || fit_decl->kind != FENG_DECL_FIT) {
                continue;
            }
            source_type_ref = fit_decl->as.fit_decl.target;
            spec_type_ref = find_spec_type_ref_in_fit(
                analysis, fit_decl, spec_decl);
            if (source_type_ref == NULL || spec_type_ref == NULL) {
                continue;
            }
            source_type = inferred_expr_type_from_type_ref(source_type_ref);
            compute_spec_witness_if_absent(&ctx,
                                           NULL,
                                           source_type,
                                           source_type_ref,
                                           spec_decl,
                                           spec_type_ref,
                                           fit_decl->token);
        }
    }

    /* Release synthetic type refs allocated during signature substitution. */
    {
        size_t si;

        for (si = 0U; si < ctx.synthetic_type_ref_count; ++si) {
            free_synthetic_type_ref(ctx.synthetic_type_refs[si]);
        }
        free(ctx.synthetic_type_refs);
    }
    free(imported_modules);
}

/* ==================== AST builtin alias normalization ====================
 *
 * Per docs/engineering/feng-scalar-alias-optimize.md §6: normalize all user-written alias
 * names (int, byte, float, double) in type_ref nodes to their canonical
 * width-explicit spelling (i32, i64, u8, f32, f64).  Runs once at the start of
 * semantic analysis so that downstream phases (codegen, symbol export, LSP)
 * only ever see canonical names and need not handle aliases.
 *
 * The AST is mutated in-place: each alias slice in a NAMED type_ref's first
 * segment is replaced with a pointer to a static canonical string.  Only
 * single-segment NAMED refs are candidates (multi-segment refs are qualified
 * module paths, never builtin aliases). */

static void normalize_expr(FengExpr *expr, size_t pointer_size);
static void normalize_stmt(FengStmt *stmt, size_t pointer_size);
static void normalize_block(FengBlock *block, size_t pointer_size);
static void normalize_decl(FengDecl *decl, size_t pointer_size);

static void normalize_type_ref(FengTypeRef *type_ref, size_t pointer_size) {
    size_t i;

    if (type_ref == NULL) {
        return;
    }
    switch (type_ref->kind) {
        case FENG_TYPE_REF_NAMED:
            if (type_ref->as.named.segment_count == 1U) {
                const char *canonical = canonical_builtin_type_name(
                    type_ref->as.named.segments[0], pointer_size);
                if (canonical != NULL &&
                    (canonical != type_ref->as.named.segments[0].data ||
                     strlen(canonical) != type_ref->as.named.segments[0].length)) {
                    type_ref->as.named.segments[0].data = canonical;
                    type_ref->as.named.segments[0].length = strlen(canonical);
                }
            }
            for (i = 0; i < type_ref->as.named.type_arg_count; ++i) {
                normalize_type_ref(type_ref->as.named.type_args[i], pointer_size);
            }
            break;
        case FENG_TYPE_REF_POINTER:
            normalize_type_ref(type_ref->as.inner, pointer_size);
            break;
        case FENG_TYPE_REF_ARRAY:
            normalize_type_ref(type_ref->as.inner, pointer_size);
            break;
    }
}

static void normalize_callable_signature(FengCallableSignature *sig, size_t pointer_size) {
    size_t i;

    if (sig == NULL) {
        return;
    }
    for (i = 0; i < sig->type_param_count; ++i) {
        normalize_type_ref(sig->type_params[i].constraint, pointer_size);
    }
    for (i = 0; i < sig->param_count; ++i) {
        normalize_type_ref(sig->params[i].type, pointer_size);
    }
    normalize_type_ref(sig->return_type, pointer_size);
}

static void normalize_block(FengBlock *block, size_t pointer_size) {
    size_t i;

    if (block == NULL) {
        return;
    }
    for (i = 0; i < block->statement_count; ++i) {
        normalize_stmt(block->statements[i], pointer_size);
    }
}

static void normalize_expr(FengExpr *expr, size_t pointer_size) {
    size_t i;

    if (expr == NULL) {
        return;
    }
    switch (expr->kind) {
        case FENG_EXPR_ARRAY_LITERAL:
            for (i = 0; i < expr->as.array_literal.count; ++i) {
                normalize_expr(expr->as.array_literal.items[i], pointer_size);
            }
            break;
        case FENG_EXPR_TUPLE_LITERAL:
            for (i = 0; i < expr->as.tuple_literal.count; ++i) {
                normalize_expr(expr->as.tuple_literal.items[i], pointer_size);
            }
            break;
        case FENG_EXPR_OBJECT_LITERAL:
            normalize_expr(expr->as.object_literal.target, pointer_size);
            for (i = 0; i < expr->as.object_literal.field_count; ++i) {
                normalize_expr(expr->as.object_literal.fields[i].value, pointer_size);
            }
            break;
        case FENG_EXPR_GENERIC_TARGET:
            normalize_expr(expr->as.generic_target.target, pointer_size);
            for (i = 0; i < expr->as.generic_target.type_arg_count; ++i) {
                normalize_type_ref(expr->as.generic_target.type_args[i], pointer_size);
            }
            break;
        case FENG_EXPR_CALL:
            normalize_expr(expr->as.call.callee, pointer_size);
            for (i = 0; i < expr->as.call.arg_count; ++i) {
                normalize_expr(expr->as.call.args[i], pointer_size);
            }
            if (expr->as.call.has_explicit_type_args) {
                for (i = 0; i < expr->as.call.explicit_type_arg_count; ++i) {
                    normalize_type_ref(expr->as.call.explicit_type_args[i], pointer_size);
                }
            }
            break;
        case FENG_EXPR_MEMBER:
            normalize_expr(expr->as.member.object, pointer_size);
            break;
        case FENG_EXPR_INDEX:
            normalize_expr(expr->as.index.object, pointer_size);
            normalize_expr(expr->as.index.index, pointer_size);
            break;
        case FENG_EXPR_UNARY:
            normalize_expr(expr->as.unary.operand, pointer_size);
            break;
        case FENG_EXPR_BINARY:
            normalize_expr(expr->as.binary.left, pointer_size);
            normalize_expr(expr->as.binary.right, pointer_size);
            break;
        case FENG_EXPR_LAMBDA:
            for (i = 0; i < expr->as.lambda.param_count; ++i) {
                normalize_type_ref(expr->as.lambda.params[i].type, pointer_size);
            }
            if (expr->as.lambda.is_block_body) {
                normalize_block(expr->as.lambda.body_block, pointer_size);
            } else {
                normalize_expr(expr->as.lambda.body, pointer_size);
            }
            break;
        case FENG_EXPR_CAST:
            normalize_type_ref(expr->as.cast.type, pointer_size);
            normalize_expr(expr->as.cast.value, pointer_size);
            break;
        case FENG_EXPR_IF:
            normalize_expr(expr->as.if_expr.condition, pointer_size);
            normalize_block(expr->as.if_expr.then_block, pointer_size);
            normalize_block(expr->as.if_expr.else_block, pointer_size);
            break;
        case FENG_EXPR_MATCH:
            normalize_expr(expr->as.match_expr.target, pointer_size);
            for (i = 0; i < expr->as.match_expr.branch_count; ++i) {
                FengMatchBranch *branch = &expr->as.match_expr.branches[i];
                size_t j;
                for (j = 0; j < branch->label_count; ++j) {
                    if (branch->labels[j].kind == FENG_MATCH_LABEL_TYPE) {
                        normalize_type_ref(branch->labels[j].type, pointer_size);
                        for (size_t ci = 0; ci < branch->labels[j].type_chain_count; ++ci) {
                            normalize_type_ref(branch->labels[j].type_chain[ci], pointer_size);
                        }
                    } else if (branch->labels[j].kind == FENG_MATCH_LABEL_VALUE) {
                        normalize_expr(branch->labels[j].value, pointer_size);
                    }
                }
                normalize_block(branch->body, pointer_size);
            }
            normalize_block(expr->as.match_expr.else_block, pointer_size);
            break;
        case FENG_EXPR_MATCH_OP:
            normalize_expr(expr->as.match_op.target, pointer_size);
            for (i = 0; i < expr->as.match_op.label_count; ++i) {
                if (expr->as.match_op.labels[i].kind == FENG_MATCH_LABEL_TYPE) {
                    normalize_type_ref(expr->as.match_op.labels[i].type, pointer_size);
                    for (size_t ci = 0; ci < expr->as.match_op.labels[i].type_chain_count; ++ci) {
                        normalize_type_ref(expr->as.match_op.labels[i].type_chain[ci], pointer_size);
                    }
                } else if (expr->as.match_op.labels[i].kind == FENG_MATCH_LABEL_VALUE) {
                    normalize_expr(expr->as.match_op.labels[i].value, pointer_size);
                }
            }
            break;
        case FENG_EXPR_TRY:
            normalize_expr(expr->as.try_expr.body, pointer_size);
            for (i = 0; i < expr->as.try_expr.clause_count; ++i) {
                normalize_type_ref(expr->as.try_expr.clauses[i].type, pointer_size);
                normalize_block(expr->as.try_expr.clauses[i].body, pointer_size);
            }
            break;
        case FENG_EXPR_ARRAY_NEW:
            normalize_type_ref(expr->as.array_new.element_type, pointer_size);
            normalize_expr(expr->as.array_new.size, pointer_size);
            break;
        default:
            break;
    }
}

static void normalize_stmt(FengStmt *stmt, size_t pointer_size) {
    size_t i;

    if (stmt == NULL) {
        return;
    }
    switch (stmt->kind) {
        case FENG_STMT_BLOCK:
            normalize_block(stmt->as.block, pointer_size);
            break;
        case FENG_STMT_BINDING:
            normalize_type_ref(stmt->as.binding.type, pointer_size);
            normalize_expr(stmt->as.binding.initializer, pointer_size);
            break;
        case FENG_STMT_ASSIGN:
            normalize_expr(stmt->as.assign.target, pointer_size);
            normalize_expr(stmt->as.assign.value, pointer_size);
            break;
        case FENG_STMT_EXPR:
            normalize_expr(stmt->as.expr, pointer_size);
            break;
        case FENG_STMT_IF:
            for (i = 0; i < stmt->as.if_stmt.clause_count; ++i) {
                normalize_expr(stmt->as.if_stmt.clauses[i].condition, pointer_size);
                normalize_block(stmt->as.if_stmt.clauses[i].block, pointer_size);
            }
            normalize_block(stmt->as.if_stmt.else_block, pointer_size);
            break;
        case FENG_STMT_MATCH:
            normalize_expr(stmt->as.match_stmt.target, pointer_size);
            for (i = 0; i < stmt->as.match_stmt.branch_count; ++i) {
                FengMatchBranch *branch = &stmt->as.match_stmt.branches[i];
                size_t j;
                for (j = 0; j < branch->label_count; ++j) {
                    if (branch->labels[j].kind == FENG_MATCH_LABEL_TYPE) {
                        normalize_type_ref(branch->labels[j].type, pointer_size);
                        for (size_t ci = 0; ci < branch->labels[j].type_chain_count; ++ci) {
                            normalize_type_ref(branch->labels[j].type_chain[ci], pointer_size);
                        }
                    } else if (branch->labels[j].kind == FENG_MATCH_LABEL_VALUE) {
                        normalize_expr(branch->labels[j].value, pointer_size);
                    }
                }
                normalize_block(branch->body, pointer_size);
            }
            normalize_block(stmt->as.match_stmt.else_block, pointer_size);
            break;
        case FENG_STMT_WHILE:
            normalize_expr(stmt->as.while_stmt.condition, pointer_size);
            normalize_block(stmt->as.while_stmt.body, pointer_size);
            break;
        case FENG_STMT_FOR:
            if (stmt->as.for_stmt.is_for_in) {
                normalize_type_ref(stmt->as.for_stmt.iter_binding.type, pointer_size);
                normalize_expr(stmt->as.for_stmt.iter_expr, pointer_size);
            } else {
                normalize_stmt(stmt->as.for_stmt.init, pointer_size);
                normalize_expr(stmt->as.for_stmt.condition, pointer_size);
                normalize_stmt(stmt->as.for_stmt.update, pointer_size);
            }
            normalize_block(stmt->as.for_stmt.body, pointer_size);
            break;
        case FENG_STMT_RETURN:
            normalize_expr(stmt->as.return_value, pointer_size);
            break;
        case FENG_STMT_THROW:
            normalize_expr(stmt->as.throw_value, pointer_size);
            break;
        case FENG_STMT_DEFER:
            normalize_block(stmt->as.defer_block, pointer_size);
            break;
        case FENG_STMT_TRY:
            normalize_expr(stmt->as.expr, pointer_size);
            break;
        case FENG_STMT_BREAK:
        case FENG_STMT_CONTINUE:
            break;
    }
}

/* Normalize builtin aliases appearing in type-position annotation arguments. */
static void normalize_member_annotation_type_args(FengTypeMember *member,
                                                  size_t pointer_size) {
    if (member == NULL) {
        return;
    }
    for (size_t annotation_index = 0U;
         annotation_index < member->annotation_count;
         ++annotation_index) {
        FengAnnotation *annotation = &member->annotations[annotation_index];

        if (annotation->argument_kind != FENG_ANNOTATION_ARGUMENT_TYPE) {
            continue;
        }
        for (size_t arg_index = 0U;
             arg_index < annotation->arg_count;
             ++arg_index) {
            normalize_type_ref(annotation->type_args[arg_index], pointer_size);
        }
    }
}

static void normalize_decl(FengDecl *decl, size_t pointer_size) {
    size_t i;

    if (decl == NULL) {
        return;
    }
    switch (decl->kind) {
        case FENG_DECL_GLOBAL_BINDING:
            normalize_type_ref(decl->as.binding.type, pointer_size);
            normalize_expr(decl->as.binding.initializer, pointer_size);
            break;
        case FENG_DECL_FUNCTION:
            normalize_callable_signature(&decl->as.function_decl, pointer_size);
            normalize_block(decl->as.function_decl.body, pointer_size);
            break;
        case FENG_DECL_TYPE:
            for (i = 0; i < decl->as.type_decl.type_param_count; ++i) {
                normalize_type_ref(decl->as.type_decl.type_params[i].constraint, pointer_size);
            }
            for (i = 0; i < decl->as.type_decl.mixin_count; ++i) {
                normalize_type_ref(decl->as.type_decl.mixins[i].source_type, pointer_size);
                normalize_expr(decl->as.type_decl.mixins[i].source_constructor, pointer_size);
            }
            for (i = 0; i < decl->as.type_decl.member_count; ++i) {
                FengTypeMember *member = decl->as.type_decl.members[i];
                if (member == NULL) {
                    continue;
                }
                normalize_member_annotation_type_args(member, pointer_size);
                switch (member->kind) {
                    case FENG_TYPE_MEMBER_FIELD:
                        normalize_type_ref(member->as.field.type, pointer_size);
                        normalize_expr(member->as.field.initializer, pointer_size);
                        break;
                    case FENG_TYPE_MEMBER_METHOD:
                    case FENG_TYPE_MEMBER_CONSTRUCTOR:
                    case FENG_TYPE_MEMBER_FINALIZER:
                        normalize_callable_signature(&member->as.callable, pointer_size);
                        normalize_block(member->as.callable.body, pointer_size);
                        break;
                }
            }
            for (i = 0; i < decl->as.type_decl.declared_spec_count; ++i) {
                normalize_type_ref(decl->as.type_decl.declared_specs[i], pointer_size);
            }
            break;
        case FENG_DECL_ENUM:
            /* No type_refs in enum declarations. */
            break;
        case FENG_DECL_SPEC:
            for (i = 0; i < decl->as.spec_decl.type_param_count; ++i) {
                normalize_type_ref(decl->as.spec_decl.type_params[i].constraint, pointer_size);
            }
            for (i = 0; i < decl->as.spec_decl.parent_spec_count; ++i) {
                normalize_type_ref(decl->as.spec_decl.parent_specs[i], pointer_size);
            }
            switch (decl->as.spec_decl.form) {
                case FENG_SPEC_FORM_OBJECT:
                    for (i = 0; i < decl->as.spec_decl.as.object.member_count; ++i) {
                        FengTypeMember *member = decl->as.spec_decl.as.object.members[i];
                        if (member == NULL) {
                            continue;
                        }
                        normalize_member_annotation_type_args(member,
                                                              pointer_size);
                        switch (member->kind) {
                            case FENG_TYPE_MEMBER_FIELD:
                                normalize_type_ref(member->as.field.type, pointer_size);
                                normalize_expr(member->as.field.initializer, pointer_size);
                                break;
                            case FENG_TYPE_MEMBER_METHOD:
                            case FENG_TYPE_MEMBER_CONSTRUCTOR:
                            case FENG_TYPE_MEMBER_FINALIZER:
                                normalize_callable_signature(&member->as.callable, pointer_size);
                                normalize_block(member->as.callable.body, pointer_size);
                                break;
                        }
                    }
                    break;
                case FENG_SPEC_FORM_CALLABLE:
                    for (i = 0; i < decl->as.spec_decl.as.callable.param_count; ++i) {
                        normalize_type_ref(decl->as.spec_decl.as.callable.params[i].type, pointer_size);
                    }
                    normalize_type_ref(decl->as.spec_decl.as.callable.return_type, pointer_size);
                    break;
                case FENG_SPEC_FORM_UNION:
                    for (i = 0; i < decl->as.spec_decl.as.union_form.member_count; ++i) {
                        normalize_type_ref(decl->as.spec_decl.as.union_form.members[i], pointer_size);
                    }
                    break;
                case FENG_SPEC_FORM_INTERSECTION:
                    for (i = 0; i < decl->as.spec_decl.as.intersection_form.member_count; ++i) {
                        normalize_type_ref(decl->as.spec_decl.as.intersection_form.members[i], pointer_size);
                    }
                    break;
            }
            break;
        case FENG_DECL_FIT:
            normalize_type_ref(decl->as.fit_decl.target, pointer_size);
            for (i = 0; i < decl->as.fit_decl.spec_count; ++i) {
                normalize_type_ref(decl->as.fit_decl.specs[i], pointer_size);
            }
            for (i = 0; i < decl->as.fit_decl.member_count; ++i) {
                FengTypeMember *member = decl->as.fit_decl.members[i];
                if (member == NULL) {
                    continue;
                }
                normalize_member_annotation_type_args(member, pointer_size);
                switch (member->kind) {
                    case FENG_TYPE_MEMBER_FIELD:
                        normalize_type_ref(member->as.field.type, pointer_size);
                        normalize_expr(member->as.field.initializer, pointer_size);
                        break;
                    case FENG_TYPE_MEMBER_METHOD:
                    case FENG_TYPE_MEMBER_CONSTRUCTOR:
                    case FENG_TYPE_MEMBER_FINALIZER:
                        normalize_callable_signature(&member->as.callable, pointer_size);
                        normalize_block(member->as.callable.body, pointer_size);
                        break;
                }
            }
            break;
    }
}

static void feng_program_normalize_builtin_aliases(FengProgram *program, size_t pointer_size) {
    size_t i;

    if (program == NULL) {
        return;
    }
    for (i = 0; i < program->declaration_count; ++i) {
        normalize_decl(program->declarations[i], pointer_size);
    }
}

bool feng_semantic_analyze_with_options(const FengProgram *const *programs,
                                        size_t program_count,
                                        const FengSemanticAnalyzeOptions *options,
                                        FengSemanticAnalysis **out_analysis,
                                        FengSemanticError **out_errors,
                                        size_t *out_error_count) {
    FengSemanticAnalysis *analysis = NULL;
    FengSemanticError *errors = NULL;
    size_t error_count = 0U;
    size_t error_capacity = 0U;
    size_t program_index;
    size_t iteration;
    size_t max_iterations;
    bool ok = true;
    CallableReturnCache callable_return_cache;
    CallableExceptionEscapeCache callable_exception_escape_cache;
    /* pointer_size drives platform-dependent alias resolution (int → i32/i64).
     * Caller (CLI layer) fills options->pointer_size from feng_get_host_pointer_size().
     * Must be non-zero; see docs/engineering/feng-binary-literal-adaptation-bugfix.md §3. */
    if (options == NULL || options->pointer_size == 0U) {
        return false;
    }
    FengCompileTarget target = options->target;
    const FengSemanticImportedModuleQuery *imported_query = options->imported_modules;
    size_t pointer_size = options->pointer_size;

    memset(&callable_return_cache, 0, sizeof(callable_return_cache));
    memset(&callable_exception_escape_cache, 0, sizeof(callable_exception_escape_cache));

    analysis = (FengSemanticAnalysis *)calloc(1U, sizeof(*analysis));
    if (analysis == NULL) {
        ok = false;
        goto finish;
    }
    analysis->pointer_size = pointer_size;

    /* Phase 0: normalize builtin alias names in all type_ref nodes across
     * every program.  After this pass, only canonical width-explicit names
     * (i32, i64, u8, f32, f64, ...) appear in the AST; downstream phases
     * need not handle aliases.  See docs/engineering/feng-scalar-alias-optimize.md §6. */
    for (program_index = 0U; program_index < program_count; ++program_index) {
        feng_program_normalize_builtin_aliases((FengProgram *)programs[program_index], pointer_size);
    }

    for (program_index = 0U; program_index < program_count && ok; ++program_index) {
        const FengProgram *program = programs[program_index];
        size_t module_index = find_module_index(analysis, program);

        if (module_index == analysis->module_count) {
            ok = add_module(analysis, program);
            continue;
        }

        if (analysis->modules[module_index].visibility != program->module_visibility) {
            char *module_name = format_module_name(program->module_segments, program->module_segment_count);
            char *message = format_message(
                "all files of module '%s' must use the same module visibility",
                module_name != NULL ? module_name : "<unknown>");

            free(module_name);
            ok = append_error(&errors,
                              &error_count,
                              &error_capacity,
                              program->path,
                              program->module_token,
                              "AE0229", message);
            if (!ok) {
                break;
            }
        }

        ok = append_module_program(&analysis->modules[module_index], program);
    }

    /* Pre-inject synthetic FengSemanticModule entries for any external-package
     * 'use' targets.  After injection, find_module_index_by_path() finds them
     * like any local module, so check_symbol_conflicts and build_program_aliases
     * need no special-case logic for external modules. */
    if (ok && imported_query != NULL && imported_query->get_module != NULL) {
        for (program_index = 0U; program_index < program_count && ok; ++program_index) {
            const FengProgram *prog = programs[program_index];
            size_t use_index;

            for (use_index = 0U; use_index < prog->use_count && ok; ++use_index) {
                const FengUseDecl *use_decl = &prog->uses[use_index];
                size_t target_index;
                const FengSemanticModule *ext;

                target_index = find_module_index_by_path(
                    analysis, use_decl->segments, use_decl->segment_count);
                if (target_index < analysis->module_count) {
                    continue; /* already known (local or already injected) */
                }

                ext = imported_query->get_module(
                    imported_query->user, use_decl->segments, use_decl->segment_count);
                if (ext != NULL) {
                    ok = add_external_module(analysis, ext);
                }
            }
        }

        if (ok) {
            ok = inject_external_modules_from_full_path_type_refs(analysis,
                                                                  imported_query,
                                                                  programs,
                                                                  program_count);
        }

        /* Transitively inject modules referenced by imported-package type
         * signatures.  Each module is scanned exactly once via a cursor;
         * newly discovered modules are appended and picked up in the next
         * iteration of the outer loop. */
        if (ok) {
            size_t scan_from = 0U;

            while (scan_from < analysis->module_count && ok) {
                size_t scan_end = analysis->module_count;

                for (size_t mi = scan_from; mi < scan_end && ok; ++mi) {
                    if (analysis->modules[mi].origin !=
                        FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
                        continue;
                    }
                    for (size_t pi = 0U; pi < analysis->modules[mi].program_count && ok; ++pi) {
                        const FengProgram *ext_prog = analysis->modules[mi].programs[pi];

                        for (size_t di = 0U; di < ext_prog->declaration_count && ok; ++di) {
                            ok = inject_external_modules_from_decl(
                                analysis, imported_query, ext_prog,
                                ext_prog->declarations[di]);
                        }
                    }
                }
                scan_from = scan_end;
            }
        }
    }

    /* Phase M1/M2: resolve every raw member-mix source in its declaring
     * program context, reject expansion cycles, then materialize ordinary
     * target fields before spec relations and normal member checking. */
    for (program_index = 0U;
         program_index < analysis->module_count && ok && error_count == 0U;
         ++program_index) {
        if (analysis->modules[program_index].origin ==
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        ok = check_symbol_conflicts(analysis,
                                    &analysis->modules[program_index],
                                    SEMANTIC_MODULE_PASS_MIXIN_SOURCES,
                                    &callable_return_cache,
                                    &callable_exception_escape_cache,
                                    NULL,
                                    &errors,
                                    &error_count,
                                    &error_capacity);
    }
    if (ok && error_count == 0U) {
        ok = expand_all_mixed_fields(analysis,
                                     &errors,
                                     &error_count,
                                     &error_capacity);
    }
    /* Nominal spec relations do not depend on generated method bodies, but
     * the ordinary overload-overlap rule needs them while applying target
     * explicit-member priority to static wrapper candidates.  Build the
     * sidecar after fields are expanded and before wrapper selection. */
    if (ok && error_count == 0U) {
        precompute_union_spec_infos(analysis);
        ok = precompute_imported_intersection_spec_infos(analysis);
    }
    if (ok && error_count == 0U) {
        ok = feng_semantic_compute_spec_relations(analysis);
    }
    if (ok && error_count == 0U) {
        ok = expand_all_mixable_static_wrappers(
            analysis, &errors, &error_count, &error_capacity);
    }
    if (ok && error_count == 0U) {
        ok = append_all_mixable_instance_wrappers(analysis);
    }

    /* Normalize all local @friend sets before any executable body is checked,
     * so authorization is independent of declaration and file order. */
    for (program_index = 0U;
         program_index < analysis->module_count && ok && error_count == 0U;
         ++program_index) {
        if (analysis->modules[program_index].origin ==
            FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
            continue;
        }
        ok = check_symbol_conflicts(analysis,
                                    &analysis->modules[program_index],
                                    SEMANTIC_MODULE_PASS_FRIEND_METADATA,
                                    NULL,
                                    NULL,
                                    NULL,
                                    &errors,
                                    &error_count,
                                    &error_capacity);
    }

    /* Phase S1a: spec satisfaction relation sidecar must be available
     * during the resolve pass so coercion-site recording (Phase S1b) can
     * link each site back to its justifying relation. Imported-package
     * modules must already be injected before this pass runs so their
     * declared_specs / parent_specs participate in the same relation table.
     * See docs/engineering/feng-spec-semantic-delivered.md §10. */
    /* The sidecar was built immediately before mixable wrapper selection;
     * wrapper generation does not change nominal declaration relations. */

    /* Phase S3-pre: pre-compute spec witnesses for builtin-subject spec
     * relations that the on-demand resolution pass would miss (e.g. imported
     * generic type instances whose type params have builtin constraints). */
    if (ok && error_count == 0U) {
        precompute_imported_builtin_spec_witnesses(analysis);
    }

    /* Module binding types must be available independently of file order.
     * Propagate only known initializer types; all ordinary source validation
     * still runs below. A dependency chain can add at most one fact per local
     * inferred binding, so no runtime initialization or unbounded pass is used. */
    {
        size_t binding_pass_limit = 1U;

        for (program_index = 0U; program_index < program_count; ++program_index) {
            const FengProgram *program = programs[program_index];

            for (size_t index = 0U; index < program->declaration_count; ++index) {
                const FengDecl *decl = program->declarations[index];

                if (decl->kind == FENG_DECL_GLOBAL_BINDING && decl->as.binding.type == NULL) {
                    ++binding_pass_limit;
                }
            }
        }
        for (size_t pass = 0U; pass < binding_pass_limit && ok && error_count == 0U; ++pass) {
            size_t facts_before = analysis->type_fact_count;

            for (size_t index = 0U; index < analysis->module_count && ok && error_count == 0U; ++index) {
                if (analysis->modules[index].origin == FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
                    continue;
                }
                ok = check_symbol_conflicts(analysis, &analysis->modules[index],
                                             SEMANTIC_MODULE_PASS_BINDING_TYPES,
                                             &callable_return_cache, &callable_exception_escape_cache,
                                             NULL, &errors, &error_count, &error_capacity);
            }
            if (analysis->type_fact_count == facts_before) {
                break;
            }
        }
    }

    max_iterations = count_all_callables(analysis) + 1U;
    if (max_iterations == 0U) {
        max_iterations = 1U;
    }

    for (iteration = 0U; iteration < max_iterations && ok && error_count == 0U; ++iteration) {
        callable_return_cache.changed = false;
        callable_exception_escape_cache.changed = false;

        for (program_index = 0U;
             program_index < analysis->module_count && ok && error_count == 0U;
             ++program_index) {
            if (analysis->modules[program_index].origin ==
                FENG_SEMANTIC_MODULE_ORIGIN_IMPORTED_PACKAGE) {
                continue; /* external modules are pre-resolved; skip semantic analysis */
            }
            ok = check_symbol_conflicts(analysis,
                                        &analysis->modules[program_index],
                                        SEMANTIC_MODULE_PASS_FULL,
                                        &callable_return_cache,
                                        &callable_exception_escape_cache,
                                        NULL,
                                        &errors,
                                        &error_count,
                                        &error_capacity);
        }

        if (!callable_return_cache.changed && !callable_exception_escape_cache.changed) {
            break;
        }
    }

    if (ok && error_count == 0U) {
        ok = report_uninferred_callable_returns(analysis,
                                                &callable_return_cache,
                                                &errors,
                                                &error_count,
                                                &error_capacity);
    }

    if (ok && error_count == 0U) {
        ok = validate_all_friend_fit_access_signatures(analysis,
                                                       &errors,
                                                       &error_count,
                                                       &error_capacity);
    }

    if (ok && error_count == 0U) {
        ok = validate_main_entry(analysis, target,
                                 &errors,
                                 &error_count,
                                 &error_capacity);
    }

    /* Post-pass: value-type cycle detection (docs/engineering/feng-value-type-dev.md
     * §3.5, §9.2). Rejects value types (tuples and `@value type` decls)
     * that directly or indirectly contain themselves as fields. Ordinary
     * (heap-allocated) type decls are not subject to this check. Runs
     * before `finish:` so the reported errors flow through the normal
     * error-reporting path. Also fixes the prior silent-failure bug for
     * self-referential tuples (no C output, exit 0, no diagnostic). */
    if (ok && error_count == 0U) {
        ok = feng_semantic_detect_value_type_cycles(analysis,
                                                    &errors,
                                                    &error_count,
                                                    &error_capacity);
    }

finish:
    if (out_error_count != NULL) {
        *out_error_count = error_count;
    }

    if (error_count > 0U || !ok) {
        if (out_analysis != NULL) {
            *out_analysis = NULL;
        }
        if (out_errors != NULL) {
            *out_errors = errors;
        } else {
            feng_semantic_errors_free(errors, error_count);
        }
        free_callable_exception_escape_cache(&callable_exception_escape_cache);
        free_callable_return_cache(&callable_return_cache);
        feng_semantic_analysis_free(analysis);
        return false;
    }

    if (out_analysis != NULL) {
        *out_analysis = analysis;
    } else {
        feng_semantic_analysis_free(analysis);
    }
    free_callable_exception_escape_cache(&callable_exception_escape_cache);
    free_callable_return_cache(&callable_return_cache);
    if (out_errors != NULL) {
        *out_errors = NULL;
    }
    /* Post-pass: 收集泛型声明的待具体化依赖（§2.2.1）。
     * 在 fixpoint 循环完成后、type cyclicity 计算前执行。 */
    if (out_analysis != NULL && *out_analysis != NULL) {
        if (!feng_semantic_collect_reifiable_deps(*out_analysis)) {
            feng_semantic_analysis_free(*out_analysis);
            *out_analysis = NULL;
            return false;
        }
    }
    /* Phase 1B: post-pass that classifies user `type` decls into acyclic vs
     * potentially-cyclic via Tarjan SCC over the managed-reference graph.
     * Failure here is treated as fatal — codegen relies on the marker table
     * being either complete or empty, never partial. */
    if (out_analysis != NULL && *out_analysis != NULL) {
        if (!feng_semantic_compute_type_cyclicity(*out_analysis)) {
            feng_semantic_analysis_free(*out_analysis);
            *out_analysis = NULL;
            return false;
        }
    }
    return true;
}

void feng_semantic_analysis_free(FengSemanticAnalysis *analysis) {
    size_t index;

    if (analysis == NULL) {
        return;
    }

    for (index = 0U; index < analysis->module_count; ++index) {
        free(analysis->modules[index].programs);
    }
    free(analysis->modules);
    free(analysis->type_markers);
    free(analysis->type_facts);
    for (index = 0U; index < analysis->spec_relation_count; ++index) {
        free(analysis->spec_relations[index].sources);
    }
    free(analysis->spec_relations);
    for (index = 0U; index < analysis->spec_coercion_site_count; ++index) {
        free(analysis->spec_coercion_sites[index].object_upcast_parent_indices);
        free((void *)analysis->spec_coercion_sites[index].callable_type_args);
    }
    free(analysis->spec_coercion_sites);
    feng_semantic_free_union_spec_infos(analysis);
    feng_semantic_free_intersection_spec_infos(analysis);
    free(analysis->union_coercion_sites);
    free(analysis->spec_default_bindings);
    free(analysis->spec_member_accesses);
    for (index = 0U; index < analysis->spec_witness_count; ++index) {
        free(analysis->spec_witnesses[index].members);
    }
    free(analysis->spec_witnesses);
    free(analysis->spec_implementation_selections);
    free(analysis->spec_equalities);
    for (index = 0U; index < analysis->reifiable_dep_set_count; ++index) {
        free(analysis->reifiable_dep_sets[index].deps);
        free(analysis->reifiable_dep_sets[index].callable_deps);
    }
    free(analysis->reifiable_dep_sets);
    for (index = 0U;
         index < analysis->imported_symbol_identity_count;
         ++index) {
        free(analysis->imported_symbol_identities[index].module_name);
    }
    free(analysis->imported_symbol_identities);
    for (index = 0U; index < analysis->friend_member_info_count; ++index) {
        struct FengFriendMemberInfo *info =
            &analysis->friend_member_infos[index];

        for (size_t friend_index = 0U;
             friend_index < info->friend_type_count;
             ++friend_index) {
            friend_type_identity_free(info->friend_types[friend_index]);
        }
        free(info->friend_types);
        free(info->fit_accesses);
    }
    free(analysis->friend_member_infos);
    /* synthesized_type_refs contains complete trees cloned or synthesized by
     * the analyzer for metadata that outlives ResolveContext. */
    for (index = 0U; index < analysis->synthesized_type_ref_count; ++index) {
        free_synthetic_type_ref(analysis->synthesized_type_refs[index]);
    }
    free(analysis->synthesized_type_refs);
    /* GENERIC_TARGET wrappers borrow type_args from the source AST and own
     * only their root node and path segments. */
    for (index = 0U;
         index < analysis->reifiable_wrapper_type_ref_count;
         ++index) {
        free(analysis->reifiable_wrapper_type_refs[index]->as.named.segments);
        free(analysis->reifiable_wrapper_type_refs[index]);
    }
    free(analysis->reifiable_wrapper_type_refs);
    /* coercion_owned_type_refs holds deep clones (with owned type_args / inner)
     * produced by spec_coercion_sites.c record_* entry points. Free them
     * recursively so nested type_args / inner don't leak. */
    for (index = 0U; index < analysis->coercion_owned_type_ref_count; ++index) {
        free_synthetic_type_ref(analysis->coercion_owned_type_refs[index]);
    }
    free(analysis->coercion_owned_type_refs);
    feng_semantic_infos_free(analysis->infos, analysis->info_count);
    free(analysis);
}

void feng_semantic_errors_free(FengSemanticError *errors, size_t error_count) {
    size_t index;

    if (errors == NULL) {
        return;
    }

    for (index = 0U; index < error_count; ++index) {
        for (size_t related_index = 0U;
             related_index < errors[index].related_location_count;
             ++related_index) {
            free(errors[index].related_locations[related_index].message);
        }
        free(errors[index].related_locations);
        free(errors[index].message);
    }
    free(errors);
}

void feng_semantic_infos_free(FengSemanticInfo *infos, size_t info_count) {
    size_t index;

    if (infos == NULL) {
        return;
    }

    for (index = 0U; index < info_count; ++index) {
        free(infos[index].message);
    }
    free(infos);
}
